  [pscustomobject]@{ Id = 'T9-DODVAR-MULTITOK'; Dod = 'dod_command: pwsh -NoProfile -Command Write-Output $ok'; Kind = 'danger'; Trace = $true; FailA = { "闸10f(f17)：未加引号的多 token -Command 载荷（Write-Output `$ok，$ok 是紧邻元素之后的独立元素）被 check-cards 接受（exit 0）——只查紧邻 -Command 的一个元素、漏了后续 token 的内插，危险形态仍可达（vacuous RED）。`n实际输出：$($r.out)" }; FailB = { "闸10f(f17)：check-cards 拒了多 token 危险卡但未点名卡 id。`n实际输出：$($r.out)" }; Ok = '  种子缺陷 10f(f17) OK：未加引号的多 token -Command 载荷仍被拒（-Command 消费其后所有元素、逐个查内插）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-EXEHOST'; Dod = 'dod_command: pwsh.exe -NoProfile -Command "if (-not $ok) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f18)：`.exe 后缀主机 pwsh.exe 的内插 -Command 载荷被 check-cards 接受（exit 0）——主机识别漏了 .exe 后缀，危险形态仍可达（vacuous RED）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f18) OK：.exe 后缀主机 pwsh.exe 的内插 -Command 载荷仍被拒（覆盖主机名 .exe 识别）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-PATHHOST'; Dod = 'dod_command: & "C:\tools\pwsh.exe" -Command "if (-not $ok) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f19)：路径限定主机（& ""C:\tools\pwsh.exe""）的内插 -Command 载荷被 check-cards 接受（exit 0）——主机识别漏了路径前缀，危险形态仍可达（vacuous RED）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f19) OK：路径限定主机的内插 -Command 载荷仍被拒（覆盖主机名 [\/] 路径前缀）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-EXESAFE'; Dod = 'dod_command: pwsh.exe -NoProfile -Command "if (-not (Test-Path README.md)) { exit 1 }"'; Kind = 'safe'; Trace = $false; FailA = { "闸10f(f20)：.exe 主机 + 无变量安全载荷被 check-cards 拒绝（exit=$($r.exit)）——主机 .exe 识别牵连误拦无变量卡。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f20) OK：.exe 主机 + 无变量载荷不被误拒' },
  [pscustomobject]@{ Id = 'T9-DODVAR-ATTACHED'; Dod = 'dod_command: pwsh -NoProfile -Command:"if (-not $ok) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f21)：附着式 -Command:<内插实参>（-Command:""…`$ok…""）被 check-cards 接受（exit 0）——漏了附着实参 .Argument 分支，危险形态仍可达（vacuous RED）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f21) OK：附着式 -Command:<内插实参> 仍被拒（覆盖 .Argument 附着分支）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-CMDWITHARGS'; Dod = 'dod_command: pwsh -NoProfile -CommandWithArgs "if (-not $ok) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f22)：-CommandWithArgs 的内插载荷被 check-cards 接受（exit 0）——漏了「command… 扩展参数名」分支，危险形态仍可达（vacuous RED）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f22) OK：-CommandWithArgs 的内插载荷仍被拒（覆盖 command… 扩展参数名分支）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-CWA-ARG'; Dod = 'dod_command: pwsh -NoProfile -CommandWithArgs ''$args[0]'' $ok'; Kind = 'safe'; Trace = $false; FailA = { "闸10f(f23)：-CommandWithArgs 的安全实参（command 串单引号 '`$args[0]'、`$ok 是有意求值传给孙 shell 的实参）被 check-cards 拒绝（exit=$($r.exit)）——把 -CommandWithArgs 当 -Command 连其实参也扫、越权误拦（Dimension #14）。应只查其 command 串本身。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f23) OK：-CommandWithArgs 的实参（非 command 串）不被误拒（只查 command 串本身、其后实参是有意求值）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-QUOTEDPARAM'; Dod = 'dod_command: pwsh "-Command" "if (-not $ok) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f24)：引号包裹的单横线参数 ""-Command"" 后接内插载荷被 check-cards 接受（exit 0）——漏了引号单横线形态（Fable R3 D1），危险形态仍可达（vacuous RED）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f24) OK：引号包裹的单横线参数（"-Command"）后接内插载荷仍被拒（Fable R3 D1）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-CWAALIAS'; Dod = 'dod_command: pwsh -cwa "if (-not $ok) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f25)：-CommandWithArgs 别名 -cwa 的内插 command 串被 check-cards 接受（exit 0）——漏了 cwa 别名（Fable R3 D2），危险形态仍可达（vacuous RED）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f25) OK：-CommandWithArgs 别名 -cwa 的内插 command 串仍被拒（Fable R3 D2）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-FILETHENCMD'; Dod = 'dod_command: pwsh -File runner.ps1 -Command "$env:PROBE_X"'; Kind = 'safe'; Trace = $false; FailA = { "闸10f(f26)：-File 模式下其后的 -Command（脚本实参、有意求值）被 check-cards 拒绝（exit=$($r.exit)）——扫过了 -File 边界、越权误拦（Fable R3 D3）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f26) OK：-File 模式下其后的 -Command（脚本实参）不被误拒（遇 -File 即停扫，Fable R3 D3）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-EXECPOL'; Dod = 'dod_command: pwsh -ExecutionPolicy Bypass -Command "if (-not $ok) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f27)：-ExecutionPolicy Bypass 之后的真 -Command 内插载荷被 check-cards 接受（exit 0）——把中间参数/裸词当 -File 边界误吞了真 -Command（Fable R3），危险形态仍可达。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f27) OK：中间参数（-ExecutionPolicy Bypass）之后的真 -Command 内插载荷仍被拒（不误吞，Fable R3）' },
  [pscustomobject]@{ Id = 'T9-DODVAR-PARSEERR'; Dod = 'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path'; Kind = 'danger'; Trace = $false; FailA = { "闸10f(f28)：语法不通的 dod_command（未闭合引号）被 check-cards 接受（exit 0）——中间 shell 会 ParserError exit 1、被 -Phase red 误当合法 RED（vacuous RED 另一扇门，Fable R3）。`n实际输出：$($r.out)" }; FailB = $null; Ok = '  种子缺陷 10f(f28) OK：语法不通的 dod_command 被拒（parse-error 亦是 vacuous RED，Fable R3）' },
  [pscustomobject]@{ Id = 'T9-DODEXIT-INHERIT'; Sentinel = 'CARD-DOD-EXIT'; Dod = 'dod_command: pwsh -NoProfile -Command "& pwsh -NoProfile -File a.ps1; if (-not (Test-Path README.md)) { exit 1 }"'; Kind = 'danger'; Trace = $true; FailA = { "gate 10f(f29) seeded defect: a dod_command whose -Command payload spawns pwsh itself and does not end on an explicit exit was ACCEPTED by check-cards (exit 0) - a pwsh -Command block with no trailing exit returns the exit code of the last NATIVE command it ran, so the subprocess's non-zero becomes the block's: every assertion can pass and the command still exits non-zero, GREEN is unreachable and -Phase red banks it as valid RED (vacuous RED; TD153/L245 not closed)." }; FailB = { "gate 10f(f29): check-cards rejected the exit-inheritance card (exit<>0) but the error does not name the card id - not traceable.`n actual output: $($r.out)" }; Ok = '  seeded defect 10f(f29) OK: a payload that spawns pwsh without ending on an explicit exit is rejected by name (TD153/L245)' },
  [pscustomobject]@{ Id = 'T9-DODEXIT-REPAIRED'; Dod = 'dod_command: pwsh -NoProfile -Command "& pwsh -NoProfile -File a.ps1; if (-not (Test-Path README.md)) { exit 1 }; exit 0"'; Kind = 'safe'; Trace = $false; FailA = { "gate 10f(f30): the REPAIRED form - the same payload ending on an explicit exit 0 - was rejected by check-cards (exit=$($r.exit)). The TD153 rule then rejects the very shape its failure text tells the author to write, so the printed repair does not work.`n actual output: $($r.out)" }; FailB = $null; Ok = '  seeded defect 10f(f30) OK: a payload ending on an explicit exit 0 is not rejected (the printed repair really works)' },
  [pscustomobject]@{ Id = 'T9-DODEXIT-BRANCHONLY'; Sentinel = 'CARD-DOD-EXIT'; Dod = 'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path README.md)) { exit 1 }; & pwsh -NoProfile -File a.ps1"'; Kind = 'danger'; Trace = $false; FailA = { "gate 10f(f31): an exit sitting only inside a branch, with the payload ending on the nested pwsh call, was ACCEPTED by check-cards (exit 0) - that branch is exactly what does not run when every assertion passes, so the exit code still comes from the subprocess (TD153/L245).`n actual output: $($r.out)" }; FailB = $null; Ok = '  seeded defect 10f(f31) OK: an exit inside a branch does not count as ending the payload (the LAST statement must be the exit)' },
  [pscustomobject]@{ Id = 'T9-DODEXIT-STRINGONLY'; Dod = 'dod_command: pwsh -NoProfile -Command "if (-not (Select-String -Path README.md -Pattern ''pwsh'' -Quiet)) { exit 1 }"'; Kind = 'safe'; Trace = $false; FailA = { "gate 10f(f32): a payload that merely NAMES pwsh inside a string literal (-Pattern 'pwsh', not a host invocation) was rejected by check-cards (exit=$($r.exit)) - the TD153 rule is matching text rather than AST command invocations and takes a legitimate assertion red.`n actual output: $($r.out)" }; FailB = $null; Ok = '  seeded defect 10f(f32) OK: pwsh appearing as a string literal in the payload is not read as a nested invocation (judged by AST, not by text)' },
  [pscustomobject]@{ Id = 'T9-DODFN-BARE'; LaterPolicy = $true; Sentinel = 'CARD-DOD-FN-EXISTS'; Names = @('Get-ScaffoldFoo'); Dod = 'dod_command: pwsh -NoProfile -Command ". scripts/_cards.ps1; if (-not (Get-ScaffoldFoo).Bar) { exit 1 }"'; Kind = 'danger'; Trace = $true; FailA = { "gate 10f(f33) seeded defect: a dod_command calling the repo function Get-ScaffoldFoo without asserting anywhere that it exists was ACCEPTED by check-cards (exit 0). -Phase red runs the dod RAW, where CommandNotFoundException is terminating for the STATEMENT only: the enclosing if is abandoned, control falls through to the trailing exit 0, and the dod exits 0 with every arm silently no-op'd. That vacuous GREEN is banked as a passing DoD gate and -Phase red reports the card is already GREEN (TD250/L308 not closed)." }; FailB = { "gate 10f(f33): check-cards rejected the missing-existence-arm card (exit<>0) but the error does not name the card id - not traceable.`n actual output: $($r.out)" }; Ok = '  seeded defect 10f(f33) OK: a dod calling a repo function with no existence assertion is rejected by name (TD250/L308)' },
  [pscustomobject]@{ Id = 'T9-DODFN-ARMED'; Dod = 'dod_command: pwsh -NoProfile -Command ". scripts/_cards.ps1; if (-not (Get-Command Get-ScaffoldFoo -ErrorAction SilentlyContinue)) { exit 1 }; if (-not (Get-ScaffoldFoo).Bar) { exit 1 }"'; Kind = 'safe'; Trace = $false; FailA = { "gate 10f(f34): the REPAIRED form - the same dod carrying the existence arm the failure text tells the author to write - was rejected by check-cards (exit=$($r.exit)). The TD250 rule then rejects the very shape it prints as the fix, so the printed repair does not work.`n actual output: $($r.out)" }; FailB = $null; Ok = '  seeded defect 10f(f34) OK: the existence arm the failure text prints really clears the rule (the repair works)' },
  [pscustomobject]@{ Id = 'T9-DODFN-STRINGONLY'; Dod = 'dod_command: pwsh -NoProfile -Command "if (-not (Select-String -Path README.md -Pattern ''Get-ScaffoldFoo'' -Quiet)) { exit 1 }"'; Kind = 'safe'; Trace = $false; FailA = { "gate 10f(f35): a payload that merely NAMES a repo function inside a string literal (-Pattern 'Get-ScaffoldFoo', not an invocation) was rejected by check-cards (exit=$($r.exit)) - the TD250 rule is matching text rather than AST command names, which reds T234's live dod, where Get-ScaffoldHandoffStatusRules appears twice inside .Replace() literals.`n actual output: $($r.out)" }; FailB = $null; Ok = '  seeded defect 10f(f35) OK: a repo function named only inside a string literal is not read as a call (judged by AST, not by text)' },
  [pscustomobject]@{ Id = 'T9-DODFN-PARTIAL'; LaterPolicy = $true; Sentinel = 'CARD-DOD-FN-EXISTS'; Names = @('Get-ScaffoldBar'); Dod = 'dod_command: pwsh -NoProfile -Command ". scripts/_cards.ps1; if (-not (Get-Command Get-ScaffoldFoo -ErrorAction SilentlyContinue)) { exit 1 }; if (-not (Get-ScaffoldFoo).Bar) { exit 1 }; if (-not (Get-ScaffoldBar).Baz) { exit 1 }"'; Kind = 'danger'; Trace = $false; FailA = { "gate 10f(f36) seeded defect: a dod asserting ONE of the two repo functions it calls was ACCEPTED by check-cards (exit 0) - the unasserted Get-ScaffoldBar arm still no-ops silently, so partial coverage buys a partial vacuous GREEN and the rule is judging the dod rather than each name it calls (TD250/L308)." }; FailB = $null; Ok = '  seeded defect 10f(f36) OK: asserting one of two called functions is not enough - the rule is per name, not per card' }
)
foreach ($case in $seed10fCases) {
  New-Seed10fCard $case.Id $case.Dod
  $r = Invoke-Seed10fCheck $case.Id
  if ($case.Kind -eq 'danger') {
    if ($localLegacyCardPolicy10 -and ($case.PSObject.Properties.Name -contains 'LaterPolicy') -and $case.LaterPolicy) {
      if ($r.exit -ne 0) { Fail "gate 10f($($case.Id)): local compatibility policy keeps this later upstream rule advisory, but the fixture exited $($r.exit).`nActual output: $($r.out)" }
      elseif ($r.out -match '\[CARD-DOD-FN-EXISTS\]') { Fail "gate 10f($($case.Id)): local compatibility policy keeps this later upstream rule advisory, but its blocking sentinel was emitted.`nActual output: $($r.out)" }
      elseif (-not $fail) { Write-Host "  local compatibility 10f($($case.Id)) OK: later upstream existence policy remains non-blocking" -ForegroundColor Green }
    }
    elseif ($r.exit -eq 0) { Fail (& $case.FailA) }
    elseif ($case.Trace -and ($r.out -notmatch $case.Id)) { Fail (& $case.FailB) }
    # Optional per-case sentinel (T109): a non-zero exit only proves SOME guard fired. Where two guards
    # could plausibly reject the same fixture, the case names the sentinel its own rule must report, so a
    # rejection arriving from a different rule cannot read as this case passing. Declared per row rather
    # than on all 32, hence the property probe - selftest runs under Set-StrictMode -Version Latest.
    elseif (($case.PSObject.Properties.Name -contains 'Sentinel') -and ($r.out -notmatch [regex]::Escape($case.Sentinel))) { Fail "闸10f($($case.Id))：check-cards 拒了该卡（exit≠0）但输出里没有本条规则的哨兵 $($case.Sentinel)——非零可能来自另一条规则，本用例并未证明目标规则生效。`n实际输出：$($r.out)" }
    # Optional per-case NAMES (T244/TD252): exit + card id + sentinel together still only prove the rule
    # fired on this CARD. Where the rule is per NAME - the existence-arm rule is - the case names the
    # function the message must carry, so a card asserting one of two called functions cannot pass on a
    # message that names the wrong one, or names none. This is the assertion T243's acceptance item 1
    # promised and no arm checked.
    elseif (($case.PSObject.Properties.Name -contains 'Names') -and (@($case.Names | Where-Object { $r.out -notmatch [regex]::Escape($_) }).Count -gt 0)) { Fail "gate 10f($($case.Id)): check-cards rejected the card and printed the right sentinel, but the message does not name $(@($case.Names | Where-Object { $r.out -notmatch [regex]::Escape($_) }) -join ', ') - the rule is per NAME, so a message that does not carry the offending function tells the author nothing about WHICH call is unasserted, and a rule that had silently become per-card would still pass every other arm of this case.`n actual output: $($r.out)" }
    elseif (-not $fail) { Write-Host $case.Ok -ForegroundColor Green }
  } else {
    if ($r.exit -ne 0) { Fail (& $case.FailA) }
    elseif (-not $fail) { Write-Host $case.Ok -ForegroundColor Green }
  }
}
Remove-Item -Recurse -Force $ccSeed10f -ErrorAction SilentlyContinue

# 10g. 种子缺陷（TD111/L61）：check-cards 建卡期拒卡文双大括号大写蛇形 token 字面量（真 token 只应出现在模板产物；
# 混进卡文会被 init 干跑冒烟 闸 8 替换污染 / 残留失败）。三条 case 夹具：大写须拒（点名卡 + 含 sentinel），小写/混合须
# 放行（证 -cmatch 严格大写不过度拒绝）。token 名运行时拼接构造，源码不留字面量。背景见卡 T52-TD111-CARD-TOKEN-GATE。
$td111Cases = @(
  @{ Name = 'EXAMPLE_TOKEN'; Reject = $true },   # 全大写蛇形 = 真 token 形态，-cmatch 命中，须拒
  @{ Name = 'example_token'; Reject = $false },  # 小写：-cmatch 不命中，须放行（证不过度拒绝）
  @{ Name = 'Example_Token'; Reject = $false }   # 混合：同上
)
$ok10g = $true
foreach ($tc in $td111Cases) {
  $ccSeed10g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10g-$PID-$($tc.Name)"
  if (Test-Path $ccSeed10g) { Remove-Item -Recurse -Force $ccSeed10g }
  New-Item -ItemType Directory -Force (Join-Path $ccSeed10g 'scripts') | Out-Null
  New-Item -ItemType Directory -Force (Join-Path $ccSeed10g 'specs/tasks') | Out-Null
  Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10g 'scripts/check-cards.ps1') -Force
  Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10g 'scripts/_cards.ps1') -Force
  $tokLit = '{' + '{' + $tc.Name + '}' + '}'   # 运行时构造，源码不留双大括号字面量
  $seedCard10g = @(
    '---', 'id: T9-TOKEN-LITERAL', 'title: seeded card token-literal case', 'status: todo',
    'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - README.md', '---',
    "# 种子缺陷卡（TD111/L61）：卡文含双大括号包裹的 $tokLit 形态"
  ) -join "`n"
  Set-Content (Join-Path $ccSeed10g 'specs/tasks/T9-TOKEN-LITERAL.md') $seedCard10g -Encoding utf8
  $ccOut10g = & pwsh -NoProfile -File (Join-Path $ccSeed10g 'scripts/check-cards.ps1') -TaskId T9-TOKEN-LITERAL 2>&1 | Out-String
  $ccExit10g = $LASTEXITCODE
  Remove-Item -Recurse -Force $ccSeed10g -ErrorAction SilentlyContinue
  if ($tc.Reject) {
    if ($ccExit10g -eq 0) { Fail "闸10g 种子缺陷（大写须拒）：卡文含大写蛇形 token 字面量（$tokLit）被 check-cards.ps1 接受（exit 0，未触发 [CARD-TOKEN-LITERAL]）——L61 建卡期机检失守，此类卡直推 master 即 CI 红（闸 8 事后才报、不指真凶；实测 T44 双平台双红 ~16min，TD111）。"; $ok10g = $false }
    elseif ((Remove-TierPrintLine $ccOut10g) -notmatch 'T9-TOKEN-LITERAL') { Fail "闸10g 种子缺陷（大写须拒）：check-cards 拒了含 token 字面量的卡但未点名卡 id——排错不可追溯。`n实际输出：$ccOut10g"; $ok10g = $false }
    elseif ($ccOut10g -notmatch '\[CARD-TOKEN-LITERAL\]') { Fail "闸10g 种子缺陷（大写须拒）：check-cards 拒了该卡但错误信息未命中 ASCII 哨兵 [CARD-TOKEN-LITERAL]——可能别的校验巧合拦下、未真覆盖 TD111（L165：仅断非零/仅断点名卡 id 不够）。`n实际输出：$ccOut10g"; $ok10g = $false }
  } else {
    if ($ccExit10g -ne 0) { Fail "闸10g 种子缺陷（$($tc.Name) 须放行）：非全大写形态（$tokLit）被 check-cards.ps1 拒绝（exit=$ccExit10g）——探测器过度拒绝，应 -cmatch 严格大写、只拦全大写蛇形（R3 r1 #14）。`n实际输出：$ccOut10g"; $ok10g = $false }
  }
}
if ($ok10g -and -not $fail) { Write-Host '  种子缺陷 10g OK：卡文大写蛇形 token 字面量被 check-cards 建卡期拒绝、点名卡 + 可操作信息；小写/混合形态不被过度拒绝（-cmatch，TD111/L61 机检下沉）' -ForegroundColor Green }

# 10h. Seeded defect (T94-CARD-SWEEP): a card declaring more than five allow_paths and carrying no
# `sweep:` field must be rejected at authoring time by the check-cards ENTRY SCRIPT. This fixture proves
# the WIRING - that check-cards.ps1 really calls Test-ScaffoldCardSweep and blocks on its finding; the four
# behavioural arms of the rule itself are the card's dod_command. Asserts non-zero AND that the card is
# named AND that the ASCII sentinel [CARD-SWEEP] is present, because a bare non-zero could come from any
# other card rule (L165). It asserts that the declaration is REQUIRED, never that a declared sweep was
# exhaustive - that is not machine-checkable and nothing in this gate claims it is.
$ccSeed10h = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10h-$PID"
if (Test-Path $ccSeed10h) { Remove-Item -Recurse -Force $ccSeed10h }
New-Item -ItemType Directory -Force (Join-Path $ccSeed10h 'scripts') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $ccSeed10h 'specs/tasks') | Out-Null
Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10h 'scripts/check-cards.ps1') -Force
Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10h 'scripts/_cards.ps1') -Force
$seedCard10h = @(
  '---', 'id: T9-NO-SWEEP', 'title: seeded cross-cutting card carrying no sweep declaration (T94)', 'status: todo',
  'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:',
  '  - a.md', '  - b.md', '  - c.md', '  - d.md', '  - e.md', '  - f.md', '---',
  '# Seeded defect card (T94): six allow_paths (more than five) and no sweep declaration'
) -join "`n"
Set-Content (Join-Path $ccSeed10h 'specs/tasks/T9-NO-SWEEP.md') $seedCard10h -Encoding utf8
$ccOut10h = & pwsh -NoProfile -File (Join-Path $ccSeed10h 'scripts/check-cards.ps1') -TaskId T9-NO-SWEEP 2>&1 | Out-String
$ccExit10h = $LASTEXITCODE
Remove-Item -Recurse -Force $ccSeed10h -ErrorAction SilentlyContinue
if ($localLegacyCardPolicy10) {
  if ($ccExit10h -ne 0 -or $ccOut10h -match '\[CARD-SWEEP\]') { Fail "gate 10h: the preserved local policy keeps sweep advisory, but the fixture became blocking (exit=$ccExit10h).`nActual output: $ccOut10h" }
  elseif (-not $fail) { Write-Host '  local compatibility 10h OK: sweep remains advisory while the corpus is unmigrated' -ForegroundColor Green }
}
elseif ($ccExit10h -eq 0) { Fail "gate 10h seeded defect (T94): a card with six allow_paths and no 'sweep:' field was ACCEPTED by check-cards.ps1 (exit 0) - the cross-cutting sweep requirement is not wired into the entry script, so the L97 teaching-face grep is optional again and comes back as a late allow_paths widening.`nActual output: $ccOut10h" }
elseif ((Remove-TierPrintLine $ccOut10h) -notmatch 'T9-NO-SWEEP') { Fail "gate 10h seeded defect (T94): check-cards rejected the card (exit=$ccExit10h) but the message does not name the card id - the failure is not traceable to a card.`nActual output: $ccOut10h" }
elseif ($ccOut10h -notmatch '\[CARD-SWEEP\]') { Fail "gate 10h seeded defect (T94): check-cards rejected the card (exit=$ccExit10h) but the message does not carry the ASCII sentinel [CARD-SWEEP] - another rule may have caught it by coincidence, so the sweep requirement is not proven covered (L165: a bare non-zero is not evidence).`nActual output: $ccOut10h" }
else { Write-Host '  seeded defect 10h OK: a card with six allow_paths and no sweep declaration is rejected at authoring time, names the card and carries the [CARD-SWEEP] sentinel (T94 wiring present)' -ForegroundColor Green }
# 10i. T101-CARD-SCALAR-EMPTY: the shared single-line scalar reader must return EMPTY for an empty field
# rather than the FOLLOWING line's text (TD143, an instance of L230). The card's dod_command runs these same
# declared examples; this gate is what keeps them running once that card is archived. It also asserts that
# both REJECTED pattern shapes are still caught, because a fixture that stopped discriminating would pass
# silently forever - the failure mode L165 exists to prevent.
$scalarFindings = @(Test-ScaffoldScalarExamples)
if ($scalarFindings.Count) { $scalarFindings | ForEach-Object { Fail "gate 10i (scalar reader, T101): $_" } }
elseif (@(Test-ScaffoldScalarExamples -Variant 'legacy-crossline').Count -lt 1) {
  Fail "gate 10i (anti-vacuous / legacy-crossline): feeding the SAME examples through the legacy cross-line pattern produced zero findings, so the fixture no longer discriminates and the empty-field-captures-next-line defect could regress unnoticed. [FIX] confirm the empty-field examples are still in Test-ScaffoldScalarExamples and that -Variant really swaps the extractor (Get-ScaffoldScalarVia)."
}
elseif (@(Test-ScaffoldScalarExamples -Variant 'naive-narrowing').Count -lt 1) {
  Fail "gate 10i (anti-vacuous / CRLF): feeding the SAME examples through the naive narrowing produced zero findings, which means the CRLF example is gone. That example is the ONLY thing standing between this repo and a silent Windows regression, because dropping the carriage return from the trailing character class looks like a correct simplification and is not. [FIX] confirm the fixture still runs every example under both lf and crlf line endings."
}
else { Write-Host '  10i OK: empty scalars read as empty under LF and CRLF, absent keys read as null, an empty title adds no PR summary, block-form diagnosis still classifies as a fix, and both rejected pattern shapes are still caught (T101/TD143)' -ForegroundColor Green }
# 10j. T102-TD147-CARD-DUP-GUARD: two live cards may not CLAIM the same debt row unless the split is
# declared. Two halves, because neither alone is enough. The declared examples prove the RULE (and that it
# still discriminates - each -Variant feeds it one of the three designs this repo measured and rejected);
# the seeded temp tree proves the WIRING, which examples in a library cannot show. Same split as 10h.
$crossFindings = @(Test-ScaffoldCardCrossRefExamples)
if ($crossFindings.Count) { $crossFindings | ForEach-Object { Fail "gate 10j (cross-card claims, T102): $_" } }
else {
  $badVariant = @('body-wide', 'blank-pointer', 'count-superseded') | Where-Object { @(Test-ScaffoldCardCrossRefExamples -Variant $_).Count -lt 1 }
  if ($badVariant) {
    Fail "gate 10j (anti-vacuous): feeding the SAME examples the '$($badVariant -join "', '")' input produced zero findings, so the fixture no longer discriminates and the rule could be narrowed back to a rejected design unnoticed. body-wide = claims read from the card body, where TD69 appears in 35 archived cards as lineage; blank-pointer = the declared-split escape stops being consulted (a tracker whose pointer cells are blanked, since an ABSENT one now switches the rule off - TD174), which would reject TD88's nine legitimate waves; count-superseded = a retired card counts as an active claim. [FIX] confirm the fixture still carries the declared-split pair, the superseded pair and the body-only mention."
  }
  else {
    $ccSeed10j = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10j-$PID"
    if (Test-Path $ccSeed10j) { Remove-Item -Recurse -Force $ccSeed10j }
    New-Item -ItemType Directory -Force (Join-Path $ccSeed10j 'scripts') | Out-Null
    New-Item -ItemType Directory -Force (Join-Path $ccSeed10j 'specs/tasks') | Out-Null
    Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10j 'scripts/check-cards.ps1') -Force
    Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10j 'scripts/_cards.ps1') -Force
    # The seeded tracker declares TD500 as a two-card split and TD501 as a one-card repayment. The four
    # seeded cards are therefore one legal pair and one duplicate: only the TD501 pair may be reported.
    Set-Content (Join-Path $ccSeed10j 'specs/tech-debt-tracker.md') ((Get-ScaffoldCardCrossRefFixture).Tracker) -Encoding utf8
    foreach ($seedPair in @(
        @('T90-TD500-ALPHA', 'first half of the declared TD500 split'),
        @('T91-TD500-BETA', 'second half of the declared TD500 split'),
        @('T92-TD501-GAMMA', 'repay TD501'),
        @('T94-TD501-DELTA', 'also repay TD501, opened from a parallel session'))) {
      $seedCard10j = @(
        '---', "id: $($seedPair[0])", "title: $($seedPair[1])", 'status: todo',
        'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - a.md', '---',
        '# Seeded card (T102): the TD it claims is named in its id and title'
      ) -join "`n"
      Set-Content (Join-Path $ccSeed10j "specs/tasks/$($seedPair[0]).md") $seedCard10j -Encoding utf8
    }
    $ccOut10j = & pwsh -NoProfile -File (Join-Path $ccSeed10j 'scripts/check-cards.ps1') 2>&1 | Out-String
    $ccExit10j = $LASTEXITCODE
    Remove-Item -Recurse -Force $ccSeed10j -ErrorAction SilentlyContinue
    if ($ccExit10j -eq 0) { Fail "gate 10j seeded defect (T102): two live cards claiming TD501, whose repayment pointer names only one of them, were ACCEPTED by check-cards.ps1 (exit 0) - the cross-card claim rule is not wired into the entry script, so a parallel session can card a debt that is already carded and the duplicate only surfaces after the work is done (TD144 cost a full card).`nActual output: $ccOut10j" }
    elseif ($ccOut10j -notmatch '\[CARD-TD-DUP\]') { Fail "gate 10j seeded defect (T102): check-cards rejected the tree (exit=$ccExit10j) but the message does not carry the ASCII sentinel [CARD-TD-DUP] - another rule may have caught it by coincidence, so the claim rule is not proven covered (L165: a bare non-zero is not evidence).`nActual output: $ccOut10j" }
    else {
      $dupLines10j = (($ccOut10j -split '\r?\n') | Where-Object { $_ -match '\[CARD-TD-DUP\]' }) -join "`n"
      if ($dupLines10j -notmatch 'T92-TD501-GAMMA' -or $dupLines10j -notmatch 'T94-TD501-DELTA') { Fail "gate 10j seeded defect (T102): the target rule does not name BOTH TD501 claimants.`nActual output: $ccOut10j" }
      elseif ($dupLines10j -match 'TD500') { Fail "gate 10j seeded defect (T102): the target rule reported the declared TD500 split as well.`nActual output: $ccOut10j" }
      else { Write-Host '  seeded defect 10j OK: an undeclared duplicate claim is rejected at validation time, names both cards and carries the [CARD-TD-DUP] sentinel, while the declared split passes untouched (T102/TD147 wiring present)' -ForegroundColor Green }
    }
  }
}
# 10k. T103-CARD-ACCEPTANCE-SET: a card declaring review_gate should close its own acceptance set, so
# rubric #6 is decided against an enumeration rather than an open one. Two halves, same split as 10h/10j.
# The declared examples prove the RULE still discriminates - each -Variant feeds the SAME decision one of
# the two designs this repo considered and rejected, and both are LOWER-bound arms because an upper-bound
# arm reads identically for "healthy" and "absent" (L239). The seeded temp tree proves the WIRING, which
# examples in a library cannot show, and additionally proves the finding now BLOCKS (T161): check-cards
# must exit NON-ZERO. It was warning-only under T103 so pre-T103 cards kept working; measured adoption
# under that nudge was 13%, so T161 made it a wall. If this seed reds, FILL THE FIXTURE - never move the
# finding back to the warning list, which is the one repair this card exists to foreclose.
$accFindings = @(Test-ScaffoldCardAcceptanceExamples)
if ($accFindings.Count) { $accFindings | ForEach-Object { Fail "gate 10k (acceptance set, T103): $_" } }
elseif (@(Test-ScaffoldCardAcceptanceExamples -Variant 'key-presence-only').Count -lt 1) {
  Fail "gate 10k (anti-vacuous / key-presence-only): feeding the SAME examples through a checker that judges by KEY PRESENCE instead of item count produced zero findings, so the fixture no longer discriminates and a bare 'acceptance:' key with nothing under it would pass as a closed set. The key on its own closes nothing - that is the [CARD-SWEEP] judgement applied to this field. [FIX] confirm the empty-key example is still in Test-ScaffoldCardAcceptanceExamples and that -Variant really swaps the item count."
}
elseif (@(Test-ScaffoldCardAcceptanceExamples -Variant 'ignore-review-gate').Count -lt 1) {
  Fail "gate 10k (anti-vacuous / ignore-review-gate): feeding the SAME examples through a checker that drops the review_gate precondition produced zero findings, which means the no-gate example is gone. That example is what keeps the rule a nudge rather than noise - without it the warning fires on cards no second reviewer will ever read. [FIX] confirm the fixture still carries a card with no review_gate."
}
else {
  $ccSeed10k = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10k-$PID"
  if (Test-Path $ccSeed10k) { Remove-Item -Recurse -Force $ccSeed10k }
  New-Item -ItemType Directory -Force (Join-Path $ccSeed10k 'scripts') | Out-Null
  New-Item -ItemType Directory -Force (Join-Path $ccSeed10k 'specs/tasks') | Out-Null
  Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10k 'scripts/check-cards.ps1') -Force
  Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10k 'scripts/_cards.ps1') -Force
  $seedCard10k = @(
    '---', 'id: T9-NO-ACCEPT', 'title: seeded card with a review gate and no closed set', 'status: todo',
    'branch: T9-NO-ACCEPT', 'allow_paths:', '  - scripts/x.ps1',
    'review_gate: codex {verdict:pass}',
    'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/x.ps1)) { exit 1 }"', 'dod_exit: 0',
    '---', '', '# T9-NO-ACCEPT'
  ) -join "`n"
  Set-Content (Join-Path $ccSeed10k 'specs/tasks/T9-NO-ACCEPT.md') $seedCard10k -Encoding utf8
  $ccOut10k = & pwsh -NoProfile -File (Join-Path $ccSeed10k 'scripts/check-cards.ps1') -TaskId T9-NO-ACCEPT 2>&1 | Out-String
  $ccExit10k = $LASTEXITCODE
  $seedCard10kMalformed = $seedCard10k -replace '(?m)^dod_exit: 0$', "dod_exit: 0`nacceptance:`n  - 1. legacy item"
  Set-Content (Join-Path $ccSeed10k 'specs/tasks/T9-NO-ACCEPT.md') $seedCard10kMalformed -Encoding utf8
  $ccOut10kMalformed = & pwsh -NoProfile -File (Join-Path $ccSeed10k 'scripts/check-cards.ps1') -TaskId T9-NO-ACCEPT 2>&1 | Out-String
  $ccExit10kMalformed = $LASTEXITCODE
  $seedCard10kValid = $seedCard10k -replace '(?m)^dod_exit: 0$', "dod_exit: 0`nacceptance:`n  - ""A1 first closed item.""`n  - ""A2 second closed item.""`n  - ""A3 third closed item."""
  Set-Content (Join-Path $ccSeed10k 'specs/tasks/T9-NO-ACCEPT.md') $seedCard10kValid -Encoding utf8
  $ccOut10kValid = & pwsh -NoProfile -File (Join-Path $ccSeed10k 'scripts/check-cards.ps1') -TaskId T9-NO-ACCEPT 2>&1 | Out-String
  $ccExit10kValid = $LASTEXITCODE
  Remove-Item -Recurse -Force $ccSeed10k -ErrorAction SilentlyContinue
  if ($ccOut10k -notmatch '\[CARD-ACCEPTANCE-ADVISORY\]') { Fail "gate 10k: a review-gated card with no acceptance set did not emit the preserved advisory marker.`nActual output: $ccOut10k" }
  elseif ($ccExit10k -ne 0) { Fail "gate 10k: the preserved local acceptance policy is advisory, but the missing-set fixture exited $ccExit10k.`nActual output: $ccOut10k" }
  elseif ($ccExit10kMalformed -eq 0 -or $ccOut10kMalformed -notmatch '\[CARD-ACCEPTANCE-INVALID\]') { Fail "gate 10k: a malformed declared acceptance set was not rejected with [CARD-ACCEPTANCE-INVALID].`nActual output: $ccOut10kMalformed" }
  elseif ($ccExit10kValid -ne 0 -or $ccOut10kValid -match '\[CARD-ACCEPTANCE-(?:ADVISORY|INVALID)\]') { Fail "gate 10k: a legal three-item quoted acceptance set did not pass silently.`nActual output: $ccOut10kValid" }
  elseif ((Remove-TierPrintLine $ccOut10k) -notmatch 'T9-NO-ACCEPT') { Fail "gate 10k seeded defect (T103): the warning does not name the card id, so it is not traceable to a card.`nActual output: $ccOut10k" }
  else { Write-Host '  local compatibility 10k OK: missing acceptance remains an explicit advisory' -ForegroundColor Green }
}
# 10l. T110-MUT-EVIDENCE-PATHS (TD145 item 1), tightened by T200-CARD-MUT-BOTH-PATHS (TD194): a card whose
# `hygiene` promises a mutation-evidence batch must have room in allow_paths for BOTH files the batch
# writes - the registry `.psd1` and its `-results.tsv` - or that half has nowhere to be committed: the ship
# scope gate reads allow_paths from the BASE card, so widening it in-branch is inert and the unscoped file
# ends up in a scratchpad (measured on T90, noticed by nothing; the half-declared form was measured on T191,
# where the batch had already run before the refusal landed). The seeded cards below prove the WIRING - that
# check-cards.ps1 really calls Test-ScaffoldCardMutationPaths and blocks on its finding - and the declared
# examples at the end of this block prove the DECISION over every allow_paths shape the rule separates.
# FIVE cards, closing over both halves of the decision. Two must be REJECTED: one declaring nothing under
# specs/mutations/, and one declaring only its registry .psd1 - the half-a-batch shape, whose results TSV
# would be refused at ship after the batch had already run (TD194, paid for live on T191). Three must be
# ACCEPTED: the bare directory (the repair the failure text names, so it has to actually work), both files
# named explicitly (the rule asks for COVERAGE, not one spelling), and the template's mutation-survivor
# pruning line, carried verbatim by 17 live and archived cards - a rule that rejected everything mentioning
# the word mutation would pass the first case and take those 17 red.
$ccSeed10l = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10l-$PID"
if (Test-Path $ccSeed10l) { Remove-Item -Recurse -Force $ccSeed10l }
New-Item -ItemType Directory -Force (Join-Path $ccSeed10l 'scripts') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $ccSeed10l 'specs/tasks') | Out-Null
Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10l 'scripts/check-cards.ps1') -Force
Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10l 'scripts/_cards.ps1') -Force
$mk10l = {
  param($cardId, $hygLine, $extraPath)
  # No debt row in the title - see the FIXTURE CONVENTION note at the head of gate 10. This one tests TD145.
  (@('---', "id: $cardId", "title: seeded hygiene/allow_paths case ($cardId)", 'status: todo',
     'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/x.ps1)) { exit 1 }"', 'dod_exit: 0',
     $hygLine, 'allow_paths:', '  - scripts/x.ps1') +
   @($extraPath | Where-Object { $null -ne $_ } | ForEach-Object { "  - $_" }) +
   @('---', '', "# seeded card ($cardId)")) -join "`n"
}
$batchHyg = 'hygiene: Single-line-deletion mutation evidence (L165) run by scripts/mutate.ps1 from this worktree.'
$cases10l = @(
  @{ Id = 'T9-MUT-NOPATH'; Hyg = $batchHyg; Extra = $null; Reject = $true
     Why = 'declares nothing under specs/mutations/ at all, so neither artifact has anywhere to land' }
  @{ Id = 'T9-MUT-REGONLY'; Hyg = $batchHyg; Extra = 'specs/mutations/T9-MUT-REGONLY.psd1'; Reject = $true
     Why = 'declares only its registry .psd1, so the results TSV mutate.ps1 writes beside it is out of scope at ship - half a batch, which is the shape T191 paid for (TD194)' }
  @{ Id = 'T9-MUT-DECLARED'; Hyg = $batchHyg; Extra = 'specs/mutations/'; Reject = $false
     Why = 'declares the bare specs/mutations/ directory, which covers the registry AND its results TSV and is the repair the failure text names - rejecting it makes the printed fix unusable'
     Ok = '(the declared specs/mutations/ directory covers both artifacts)' }
  @{ Id = 'T9-MUT-BOTHFILES'; Hyg = $batchHyg; Extra = @('specs/mutations/T9-MUT-BOTHFILES.psd1', 'specs/mutations/T9-MUT-BOTHFILES-results.tsv'); Reject = $false
     Why = 'names both artifacts explicitly, so the rule demands COVERAGE rather than one particular spelling - rejecting it silently narrows a both-halves rule into a directory-only rule'
     Ok = '(naming both artifacts explicitly is the other satisfying shape)' }
  @{ Id = 'T9-MUT-TEMPLATE'; Hyg = 'hygiene: 冗余测试经 mutation-survivor 剪枝（R4）'; Extra = $null; Reject = $false
     Why = 'carries only the template mutation-survivor pruning line, which 17 live and archived cards carry verbatim and which owes no registry - the pattern has widened to the bare word mutation'
     Ok = '(the template mutation-survivor line owes no registry)' }
)
foreach ($c10l in $cases10l) {
  Set-Content (Join-Path $ccSeed10l "specs/tasks/$($c10l.Id).md") (& $mk10l $c10l.Id $c10l.Hyg $c10l.Extra) -Encoding utf8
  $out10l = & pwsh -NoProfile -File (Join-Path $ccSeed10l 'scripts/check-cards.ps1') -TaskId $c10l.Id 2>&1 | Out-String
  $exit10l = $LASTEXITCODE
  if ($c10l.Reject) {
    if ($localLegacyCardPolicy10) {
      if ($exit10l -ne 0 -or $out10l -match '\[CARD-HYGIENE-MUT\]') { Fail "gate 10l($($c10l.Id)): the preserved local policy keeps mutation-path validation advisory, but the fixture became blocking (exit=$exit10l).`nActual output: $out10l" }
      elseif (-not $fail) { Write-Host "  local compatibility 10l($($c10l.Id)) OK: mutation-path policy remains non-blocking" -ForegroundColor Green }
    }
    elseif ($exit10l -eq 0) { Fail "gate 10l seeded defect (T110/TD145 + T200/TD194): a card whose hygiene promises a mutation-evidence batch $($c10l.Why) was ACCEPTED by check-cards.ps1 (exit 0) - the rule is not wired into the entry script, or it no longer requires BOTH artifacts, so at least one of the two files mutate.ps1 writes can only run from a scratchpad and is never committed, which is exactly what specs/mutations/README.md exists to stop.`nActual output: $out10l" }
    elseif ((Remove-TierPrintLine $out10l) -notmatch $c10l.Id) { Fail "gate 10l ($($c10l.Id)): check-cards rejected the card (exit=$exit10l) but the message does not name the card id - the failure is not traceable to a card.`nActual output: $out10l" }
    elseif ($out10l -notmatch '\[CARD-HYGIENE-MUT\]') { Fail "gate 10l ($($c10l.Id)): check-cards rejected the card (exit=$exit10l) but the message carries no [CARD-HYGIENE-MUT] sentinel - another rule may have caught it by coincidence, so this rule is not proven covered (L165: a bare non-zero is not evidence).`nActual output: $out10l" }
    elseif (-not $fail) { Write-Host "  seeded defect 10l($($c10l.Id)) OK: a promised batch that $($c10l.Why) is rejected, names the card and carries the [CARD-HYGIENE-MUT] sentinel (T110/T200 wiring present)" -ForegroundColor Green }
  }
  else {
    if ($exit10l -ne 0) { Fail "gate 10l ($($c10l.Id)): check-cards REJECTED a card it must accept (exit=$exit10l). This card $($c10l.Why).`nActual output: $out10l" }
    elseif (-not $fail) { Write-Host "  seeded defect 10l($($c10l.Id)) OK: not rejected $($c10l.Ok)" -ForegroundColor Green }
  }
}
Remove-Item -Recurse -Force $ccSeed10l -ErrorAction SilentlyContinue

# Same rule, SECOND SURFACE: the declared examples behind [CARD-HYGIENE-MUT]. The fixture above proves the WIRING (the real
# entry script calls the predicate and blocks on it); this proves the DECISION over every allow_paths shape
# the rule has to separate, the way 10j/10k/10m/10n each run their own rule's example table. Until T200
# nothing ran this one: it was reachable only from T110's card dod_command, which stopped running the day
# that card was archived - an archived DoD is live only where a live fixture executes it (L97). That is why
# the anti-vacuous arm matters more here than the count: without it, a predicate that agreed with the
# examples for the WRONG reason would sit green forever.
$mutPathFindings = @(Test-ScaffoldCardMutationPathsExamples)
if ($mutPathFindings.Count) {
  Fail "gate 10l (declared examples): the [CARD-HYGIENE-MUT] predicate disagrees with its own declared cases, so the rule no longer separates the shapes it exists to separate - a promised batch needs room for BOTH the registry and its results TSV, the bare specs/mutations/ directory or both files named give it that, and the template's mutation-survivor pruning line owes neither. [FIX] fix the predicate or the table pattern, never the example.`n$($mutPathFindings -join "`n")"
}
foreach ($v10l in @('any-mutation-path', 'any-mutation-word', 'ignore-allow-paths')) {
  if (@(Test-ScaffoldCardMutationPathsExamples -Variant $v10l).Count -lt 1) {
    Fail "gate 10l (anti-vacuous / $v10l): feeding the SAME examples through the rejected shape '$v10l' produced zero disagreements, so the example table no longer discriminates and that shape could be shipped unnoticed. $(switch ($v10l) { 'any-mutation-path' { 'This one IS the defect TD194 recorded: any entry under specs/mutations/ satisfies, so a card declaring only its registry passes and has its results TSV refused at ship, after the batch has run. The table must still carry a half-declared card.' } 'any-mutation-word' { 'This one matches the bare word mutation, which flags the 17 live and archived cards carrying the template mutation-survivor line. The table must still carry that line in both languages.' } default { 'This one never consults allow_paths, so a card that DID declare somewhere to put the evidence is flagged anyway and the rule can never be satisfied. The table must still carry a card that declared it.' } }) [FIX] restore the missing case, never relax the variant."
  }
}

# 10m. T174-CARD-PATH-EXISTS (TD166): an allow_paths entry that resolves to nothing while a path one small
# edit away DOES exist. Every other card guard judges the SHAPE of allow_paths and never resolves an entry,
# so a path that was never there passed validation and surfaced later as a confusing scope verdict. This
# fixture proves the WIRING - that check-cards.ps1 really calls Test-ScaffoldCardPathNearMiss and BLOCKS on
# its finding; the behavioural arms of the rule live in the declared examples, run just below.
# The fixture is a real git repo ON PURPOSE: check-cards builds its tree from `git ls-files`, and in a
# non-repo directory the list is empty, every entry resolves to nothing, no neighbour is ever found and the
# rule reports nothing. Case 1 rejecting is therefore also the proof that the tree was actually populated -
# a vacuous fixture takes this sub-gate red rather than passing quietly (L265).
# FOUR cards, and the last two are the ones that matter: a bare existence rule would pass cases 1-2 and
# take 12 of the last 14 archived cards red, because a card is written before the files it creates exist.
$ccSeed10m = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10m-$PID"
if (Test-Path $ccSeed10m) { Remove-Item -Recurse -Force $ccSeed10m }
New-Item -ItemType Directory -Force (Join-Path $ccSeed10m 'scripts') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $ccSeed10m 'specs/tasks') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $ccSeed10m 'docs/adr') | Out-Null
Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10m 'scripts/check-cards.ps1') -Force
Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10m 'scripts/_cards.ps1') -Force
# the two real neighbours the seeded typos are one edit away from
Set-Content (Join-Path $ccSeed10m 'docs/adr/0013-no-trajectory-replay-view.md') '# seeded neighbour' -Encoding utf8
Set-Content (Join-Path $ccSeed10m 'scripts/task.ps1') '# seeded neighbour' -Encoding utf8
# ...and two files sharing a COMMON basename, with no root README.md. This is the shape that took gate 15's
# e2e fixture red: its card declares a root README.md it is about to create, and a rule keying on "same
# basename anywhere" flagged it against every other README.md in the tree. Case T9-PATH-COMMON pins it.
Set-Content (Join-Path $ccSeed10m 'docs/README.md') '# common basename' -Encoding utf8
Set-Content (Join-Path $ccSeed10m 'specs/README.md') '# common basename' -Encoding utf8
Push-Location $ccSeed10m
& git init -q 2>&1 | Out-Null
& git add -A 2>&1 | Out-Null
Pop-Location
$mk10m = {
  param($cardId, $entry)
  # No debt row in the title - see the FIXTURE CONVENTION note at the head of gate 10. This one tests TD166.
  (@('---', "id: $cardId", "title: seeded allow_paths resolution case ($cardId)", 'status: todo',
     'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/task.ps1)) { exit 1 }"', 'dod_exit: 0',
     'allow_paths:', "  - $entry",
     '---', '', "# seeded card ($cardId)")) -join "`n"
}
$cases10m = @(
  @{ Id = 'T9-PATH-SIBLING'; Entry = 'docs/adr/0013-no-trajectory-or-replay-view.md'; Reject = $true; Near = '0013-no-trajectory-replay-view' }
  @{ Id = 'T9-PATH-BASENAME'; Entry = 'docs/task.ps1'; Reject = $true; Near = 'scripts/task.ps1' }
  @{ Id = 'T9-PATH-CREATES'; Entry = 'specs/mutations/T9-PATH-CREATES.psd1'; Reject = $false; Near = $null }
  @{ Id = 'T9-PATH-GLOB'; Entry = 'scripts/*.ps1'; Reject = $false; Near = $null }
  @{ Id = 'T9-PATH-COMMON'; Entry = 'README.md'; Reject = $false; Near = $null }
)
foreach ($c10m in $cases10m) {
  Set-Content (Join-Path $ccSeed10m "specs/tasks/$($c10m.Id).md") (& $mk10m $c10m.Id $c10m.Entry) -Encoding utf8
  $out10m = & pwsh -NoProfile -File (Join-Path $ccSeed10m 'scripts/check-cards.ps1') -TaskId $c10m.Id 2>&1 | Out-String
  $exit10m = $LASTEXITCODE
  if ($c10m.Reject) {
    if ($localLegacyCardPolicy10) {
      if ($exit10m -ne 0 -or $out10m -match '\[CARD-PATH-NEARMISS\]') { Fail "gate 10m($($c10m.Id)): the preserved local policy keeps path-nearmiss validation advisory, but the fixture became blocking (exit=$exit10m).`nActual output: $out10m" }
      elseif (-not $fail) { Write-Host "  local compatibility 10m($($c10m.Id)) OK: path-nearmiss policy remains non-blocking" -ForegroundColor Green }
    }
    elseif ($exit10m -eq 0) { Fail "gate 10m seeded defect (T174/TD166): a card whose allow_paths entry '$($c10m.Entry)' names nothing - while '$($c10m.Near)' does exist - was ACCEPTED by check-cards.ps1 (exit 0). Either the rule is not wired into the entry script, or the tree it resolves against came back empty (check-cards builds it from git ls-files, so a fixture that is not a git repo makes this rule inert and this gate vacuous).`nActual output: $out10m" }
    elseif ($out10m -notmatch $c10m.Id) { Fail "gate 10m ($($c10m.Id)): check-cards rejected the card (exit=$exit10m) but the message does not name the card id - the failure is not traceable to a card.`nActual output: $out10m" }
    elseif ($out10m -notmatch '\[CARD-PATH-NEARMISS\]') { Fail "gate 10m ($($c10m.Id)): check-cards rejected the card (exit=$exit10m) but the message carries no [CARD-PATH-NEARMISS] sentinel - another rule may have caught it by coincidence, so this rule is not proven covered (L165: a bare non-zero is not evidence).`nActual output: $out10m" }
    elseif ($out10m -notmatch [regex]::Escape($c10m.Near)) { Fail "gate 10m ($($c10m.Id)): the finding fired but does not name the neighbour '$($c10m.Near)' it claims to have found. Naming the near path IS the actionable half of this rule - without it the author is told only that something is wrong.`nActual output: $out10m" }
    elseif (-not $fail) { Write-Host "  seeded defect 10m($($c10m.Id)) OK: a near-miss entry is rejected, names the card, carries [CARD-PATH-NEARMISS] and names the neighbour it found (T174 wiring present)" -ForegroundColor Green }
  }
  else {
    $why10m = switch ($c10m.Id) {
      'T9-PATH-CREATES' { 'This card declares a path it CREATES - the dominant shape in this repo, carried by 12 of the last 14 archived cards. Rejecting it is the bare-existence rule this card exists to avoid.' }
      'T9-PATH-GLOB' { 'A glob is a pattern, not a path, and this rule deliberately does not expand one.' }
      'T9-PATH-COMMON' { 'This card declares a root README.md it is about to create while other README.md files exist elsewhere. A basename that occurs many times says nothing about where the author meant, so it is NOT a neighbour - measured, README.md occurs 14 times in this repo and SKILL.md 17. Keying on "same basename anywhere" is what took gate 15 e2e fixture red the first time this rule was written.' }
    }
    $ok10m = switch ($c10m.Id) {
      'T9-PATH-CREATES' { '(a path the card creates has no near neighbour and stays silent)' }
      'T9-PATH-GLOB' { '(glob entries are never resolved)' }
      'T9-PATH-COMMON' { '(a common basename is not a neighbour - only a name unique in the tree is)' }
    }
    if ($exit10m -ne 0) { Fail "gate 10m ($($c10m.Id)): check-cards REJECTED a card it must accept (exit=$exit10m). $why10m`nActual output: $out10m" }
    elseif (-not $fail) { Write-Host "  seeded defect 10m($($c10m.Id)) OK: not rejected $ok10m" -ForegroundColor Green }
  }
}
Remove-Item -Recurse -Force $ccSeed10m -ErrorAction SilentlyContinue
# Anti-vacuous arms: the declared examples must agree with the live predicate, and each rejected shape must
# measurably differ from it. A variant that produces nothing means the fixture stopped discriminating.
$nmFindings = @(Test-ScaffoldCardPathNearMissExamples)
if ($nmFindings.Count) { $nmFindings | ForEach-Object { Fail "gate 10m (path near-miss examples, T174): $_" } }
if (@(Test-ScaffoldCardPathNearMissExamples -Variant 'bare-existence').Count -lt 1) {
  Fail "gate 10m (anti-vacuous / bare-existence): feeding the SAME examples through a checker that drops the near-neighbour condition produced zero findings, so the fixture no longer carries a path a card legitimately CREATES. That example is the only thing standing between this rule and rejecting this repo's dominant card shape - measured, the bare form rejects 12 of the last 14 archived cards at -Phase start. [FIX] confirm the self-created specs/mutations/ examples are still in Test-ScaffoldCardPathNearMissExamples."
}
if (@(Test-ScaffoldCardPathNearMissExamples -Variant 'ignore-comment-strip').Count -lt 1) {
  Fail "gate 10m (anti-vacuous / ignore-comment-strip): feeding the SAME examples through a checker that resolves entries AS DECLARED produced zero findings, which means the commented example is gone. This rule BLOCKS on failed resolution, so without the comment strip Get-YamlListItems performs, a card carrying a perfectly good commented entry goes red - four archived cards carry that shape. [FIX] confirm the fixture still carries an allow_paths entry with a trailing '# ...' comment."
}
# 10n. T177-CARD-RULES-UNGATED (TD173): the four cross-card rules must be REACHABLE when the run is narrowed
# to one card. They used to sit behind a not-task-id guard while all three task.ps1 phases pass a task id, so
# none of them ran in the local loop and CI enforced a strictly stronger contract than ship - measured live,
# a card naming an id that resolved to nothing passed start, red and ship and then failed CI twice.
# The behavioural arms of the split live in the declared examples (run below); THIS fixture proves the
# WIRING, which examples in a library cannot show. Two cases carry the whole design between them: the
# dangling card must be REJECTED under a narrowed run, and the clean card - whose text references the
# dangling one, a card that really exists - must be ACCEPTED under its own narrowed run. The second is the
# arm that would fail if the corpus were narrowed along with the scope, which is where a naive move of the
# block lands, and it is also the arm that proves an unrelated card's defect does not block this ship.
# specs/archive/tasks/ is created ON PURPOSE though it stays empty: the reference arm degrades OFF in a tree
# with no cold store (a freshly initialised downstream), so without it this whole sub-gate would be vacuous.
$ccSeed10n = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10n-$PID"
if (Test-Path $ccSeed10n) { Remove-Item -Recurse -Force $ccSeed10n }
foreach ($d10n in @('scripts', 'specs/tasks', 'specs/archive/tasks')) { New-Item -ItemType Directory -Force (Join-Path $ccSeed10n $d10n) | Out-Null }
Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10n 'scripts/check-cards.ps1') -Force
Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10n 'scripts/_cards.ps1') -Force
# TD600's repayment pointer names NEITHER claimant, so the pair below is an undeclared duplicate.
Set-Content (Join-Path $ccSeed10n 'specs/tech-debt-tracker.md') (@(
    '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |',
    '| --- | --- | --- | --- | --- | --- | --- |',
    '| TD600 | 2026-08-26 | seeded | seeded row for sub-gate 10n | major | open | — |'
  ) -join "`n") -Encoding utf8
$mk10n = {
  param($cardId, $entry, $par, $body, $claims)
  # Only the two cards that are MEANT to be a duplicate pair name TD600 in their title - a claim is read
  # from the id and title, so putting it in every seed would make all six cards claim one row.
  $tdSuffix = if ($claims) { ", $claims" } else { '' }
  $lines = @('---', "id: $cardId", "title: seeded cross-card reachability case ($cardId$tdSuffix)", 'status: todo')
  if ($par) { $lines += "parallelizable_with: [$par]" }
  $lines += @('dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/check-cards.ps1)) { exit 1 }"', 'dod_exit: 0',
    'allow_paths:', "  - $entry", '---', '', "# $cardId", $body)
  ($lines -join "`n")
}
# T9-SCOPE-DANGLE names an id that resolves to nothing. T9-SCOPE-CLEAN names T9-SCOPE-DANGLE, which EXISTS.
& $mk10n 'T9-SCOPE-DANGLE' 'seeded/scope-dangle.txt' '' 'This card names T9-NOSUCH-CARD, which is not a card anywhere.' |
  Set-Content (Join-Path $ccSeed10n 'specs/tasks/T9-SCOPE-DANGLE.md') -Encoding utf8
& $mk10n 'T9-SCOPE-CLEAN' 'seeded/scope-clean.txt' '' 'This card names T9-SCOPE-DANGLE, a live card, so the reference resolves.' |
  Set-Content (Join-Path $ccSeed10n 'specs/tasks/T9-SCOPE-CLEAN.md') -Encoding utf8
& $mk10n 'T9-TD600-ALPHA' 'seeded/alpha.txt' '' 'Claims the seeded debt row through its id and title.' 'TD600' |
  Set-Content (Join-Path $ccSeed10n 'specs/tasks/T9-TD600-ALPHA.md') -Encoding utf8
& $mk10n 'T9-TD600-BETA' 'seeded/beta.txt' '' 'Claims the same row, as a parallel session would.' 'TD600' |
  Set-Content (Join-Path $ccSeed10n 'specs/tasks/T9-TD600-BETA.md') -Encoding utf8
& $mk10n 'T9-PAR-LEFT' 'seeded/shared/' 'T9-PAR-RIGHT' 'Declares itself parallel with a card whose allow_paths overlap it.' |
  Set-Content (Join-Path $ccSeed10n 'specs/tasks/T9-PAR-LEFT.md') -Encoding utf8
& $mk10n 'T9-PAR-RIGHT' 'seeded/shared/deep.txt' '' 'The other half of the overlapping parallel pair.' |
  Set-Content (Join-Path $ccSeed10n 'specs/tasks/T9-PAR-RIGHT.md') -Encoding utf8
$cc10n = Join-Path $ccSeed10n 'scripts/check-cards.ps1'
$cases10n = @(
  @{ Id = 'T9-SCOPE-DANGLE'; Reject = $true; Sentinel = '\[CARD-REF-DANGLING\]'; Rule = 'a full-form id that resolves to nothing'; Why = "This is the defect measured live on T174: it passed start, red AND ship locally and was caught only by CI, twice, costing a stale-merge-ref detour. If it passes here the local loop is still weaker than the merge gate and TD173 is not paid." }
  @{ Id = 'T9-TD600-ALPHA'; Reject = $true; Sentinel = '\[CARD-TD-DUP\]'; Rule = 'two live cards claiming one debt row the tracker does not split'; Why = 'This rule shares the gate the reference rule sits behind, so it had the same reachability hole. A parallel session carding an already-carded debt costs a whole card (TD144).' }
  @{ Id = 'T9-PAR-LEFT'; Reject = $true; Sentinel = 'parallelizable_with'; Rule = 'a declared-parallel pair whose allow_paths overlap'; Why = 'Same gate again. Overlapping parallel cards collide when their worktrees merge, and the whole point of declaring parallelism is that the collision was ruled out first.' }
  @{ Id = 'T9-SCOPE-CLEAN'; Reject = $false; Sentinel = ''; Rule = 'a card whose reference names another LIVE card'; Why = "The corpus must stay whole when the scope narrows. Narrow it too and this card's perfectly good reference to T9-SCOPE-DANGLE resolves to nothing - every inter-card reference in the repo becomes a false rejection. It also proves scope isolation: three OTHER cards in this same tree are defective, and none of them may block this card's ship, because they sit outside its allow_paths and cannot be fixed from its worktree." }
)
foreach ($c10n in $cases10n) {
  $out10n = & pwsh -NoProfile -File $cc10n -TaskId $c10n.Id 2>&1 | Out-String
  $exit10n = $LASTEXITCODE
  if ($c10n.Reject) {
    if ($localLegacyCardPolicy10 -and $c10n.Id -eq 'T9-SCOPE-DANGLE') {
      if ($exit10n -ne 0 -or $out10n -match '(?m)^\s*-\s+\[CARD-REF-DANGLING\]\s+\[T9-SCOPE-DANGLE\]') { Fail "gate 10n($($c10n.Id)): the preserved local policy keeps dangling-reference validation advisory, but the fixture became blocking (exit=$exit10n).`nActual output: $out10n" }
      elseif (-not $fail) { Write-Host '  local compatibility 10n(T9-SCOPE-DANGLE) OK: dangling reference remains non-blocking' -ForegroundColor Green }
    }
    elseif ($exit10n -eq 0) { Fail "gate 10n ($($c10n.Id), T177/TD173): a run narrowed to this card ACCEPTED $($c10n.Rule) (exit 0). The cross-card rules are not reachable under -TaskId, which is the mode every task.ps1 phase uses, so ship enforces a weaker contract than the CI merge gate. $($c10n.Why)`nActual output: $out10n" }
    elseif ($out10n -notmatch $c10n.Sentinel) { Fail "gate 10n ($($c10n.Id)): the narrowed run rejected the card (exit=$exit10n) but the output carries no '$($c10n.Sentinel)' marker - another rule may have caught it by coincidence, so this rule is not proven reachable (L165: a bare non-zero is not evidence).`nActual output: $out10n" }
    elseif ($out10n -notmatch $c10n.Id) { Fail "gate 10n ($($c10n.Id)): the narrowed run rejected the card but the message does not name it, so the failure is not traceable to a card.`nActual output: $out10n" }
    elseif (-not $fail) { Write-Host "  seeded defect 10n($($c10n.Id)) OK: a narrowed run rejects $($c10n.Rule) (T177 wiring present)" -ForegroundColor Green }
  }
  else {
    if ($exit10n -ne 0) { Fail "gate 10n ($($c10n.Id), T177/TD173): a run narrowed to this card REJECTED it (exit=$exit10n), and it is clean. $($c10n.Why)`nActual output: $out10n" }
    elseif (-not $fail) { Write-Host "  seeded defect 10n($($c10n.Id)) OK: a narrowed run accepts $($c10n.Rule), so the corpus stayed whole and the scope stayed narrow" -ForegroundColor Green }
  }
}
# 10n'. The PAIR to 10n's duplicate-claim reject arm (TD174): same tree, same two claiming
# cards, tracker REMOVED. A claim can only be judged against a declaration surface that exists, so with no
# specs/tech-debt-tracker.md the rule must switch OFF rather than report the pair and tell the author to
# edit a file that is not there - which is the state a freshly initialised downstream is in, and since T177
# this rule reaches it at -Phase start. Proven as a PAIR: the reject arm above already fires on this very
# tree WITH the tracker, so deleting only that one file isolates the degradation from everything else here.
$trk10n = Join-Path $ccSeed10n 'specs/tech-debt-tracker.md'
Remove-Item -LiteralPath $trk10n -Force
$outNoTd10n = & pwsh -NoProfile -File $cc10n -TaskId 'T9-TD600-ALPHA' 2>&1 | Out-String
$exitNoTd10n = $LASTEXITCODE
if ($exitNoTd10n -ne 0) { Fail "gate 10n' [TD-DUP-NO-TRACKER] (TD174): with specs/tech-debt-tracker.md REMOVED from the seeded tree, a run narrowed to one of the two claiming cards still exited $exitNoTd10n. The pair is UNDECLARABLE - there is no tracker to declare the split in - so the rule must degrade off, the way [CARD-REF-DANGLING] already does on the same input. Fail-closed here blocks the first two cards a fresh downstream writes and points its author at a file that does not exist.`nActual output: $outNoTd10n" }
elseif ($outNoTd10n -match '\[CARD-TD-DUP\]') { Fail "gate 10n' [TD-DUP-NO-TRACKER] (TD174): the tracker-less run exited 0 but still printed the [CARD-TD-DUP] sentinel, so the finding is being produced and then dropped downstream rather than the rule declining to judge. The same wrong message at a lower volume still names a file that is not on disk.`nActual output: $outNoTd10n" }
elseif (-not $fail) { Write-Host '  seeded defect 10n'' OK: removing the tracker from the SAME tree that rejects the pair with it turns the duplicate-claim rule off, so a tracker-less downstream is not blocked (TD174)' -ForegroundColor Green }
# The overlap predicate's built-in seed self-check must run in BOTH modes. An anti-vacuous guard that is
# itself switched off in the mode the loop actually uses guards nothing. Proven as a PAIR: the clean card
# above already exits 0 under a narrowed run (the control), so breaking only the seed's expected count and
# seeing that same narrowed run go non-zero isolates the failure to the self-check. Asserting on the exit
# code rather than on the message keeps this independent of console encoding (L17).
$cc10nText = Get-Content $cc10n -Raw
$cc10nBroken = $cc10nText -replace '\$seedErrs\.Count -ne 1', '$seedErrs.Count -ne 2'
if ($cc10nBroken -eq $cc10nText) {
  Fail "gate 10n (seed self-check reachability): could not find the seed expectation to break in check-cards.ps1, so this arm proves nothing. The built-in seed self-check guards the overlap predicate against silent degradation; if it was renamed or removed, restore it or re-anchor this arm - do not delete the arm. [FIX] search check-ards.ps1 for the 内建种子自检 block."
}
else {
  Set-Content $cc10n $cc10nBroken -Encoding utf8
  $outSeed10n = & pwsh -NoProfile -File $cc10n -TaskId 'T9-SCOPE-CLEAN' 2>&1 | Out-String
  $exitSeed10n = $LASTEXITCODE
  Set-Content $cc10n $cc10nText -Encoding utf8
  if ($exitSeed10n -eq 0) { Fail "gate 10n (seed self-check reachability, T177/TD173): the overlap predicate's built-in seed self-check was broken and a run narrowed to a card still exited 0 - the same narrowed run passes cleanly when the self-check is intact, so the guard is not running in the mode task.ps1 actually uses. A degraded overlap predicate would then ship green through every local phase.`nActual output: $outSeed10n" }
  elseif (-not $fail) { Write-Host '  seeded defect 10n(seed-self-check) OK: breaking the built-in seed self-check turns a NARROWED run red, so the anti-vacuous guard runs in both modes' -ForegroundColor Green }
}
Remove-Item -Recurse -Force $ccSeed10n -ErrorAction SilentlyContinue
# Anti-vacuous arms: the declared examples must agree with the live core, and each REJECTED design must
# measurably differ from it. A variant that produces nothing means the fixture stopped discriminating.
$scopeFindings = @(Test-ScaffoldCardCheckScopeExamples)
if ($scopeFindings.Count) { $scopeFindings | ForEach-Object { Fail "gate 10n (corpus/scope examples, T177): $_" } }
if (@(Test-ScaffoldCardCheckScopeExamples -Variant 'scope-is-corpus').Count -lt 1) {
  Fail "gate 10n (anti-vacuous / scope-is-corpus): feeding the SAME examples a core that narrows the resolution corpus along with the scope produced zero findings, so the fixture no longer carries a live card OTHER than the scoped one. That example is the only thing standing between this change and reporting every inter-card reference as dangling. [FIX] confirm Test-ScaffoldCardCheckScopeExamples still passes three live ids and narrows to one of them."
}
if (@(Test-ScaffoldCardCheckScopeExamples -Variant 'no-scope-filter').Count -lt 1) {
  Fail "gate 10n (anti-vacuous / no-scope-filter): feeding the SAME examples a core that reports on every live card even when the run is narrowed produced zero findings, so the fixture no longer checks the reported scope. Without that arm, ship would block on defects in cards outside its own allow_paths, which the shipper cannot fix from that worktree. [FIX] confirm the examples still assert the narrowed scope is exactly one id."
}
# 10o. Seeded defect (T233/TD235-CARD-BUDGET): the `budget:` VALUE-shape rule, proven through the
# check-cards ENTRY SCRIPT in BOTH directions. A declared value that cannot be a line count must be
# rejected and must carry the [CARD-BUDGET] sentinel; a card that declares NO budget must pass in silence.
# The second half is not a formality - `budget:` is deliberately not a required field, and a rule that
# quietly started reporting on absence would red every in-flight card that predates it, mid-acceptance.
# Both halves run against the same fixture so the only difference between them is the one seeded line.
$ccSeed10o = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10o-$PID"
if (Test-Path $ccSeed10o) { Remove-Item -Recurse -Force $ccSeed10o }
New-Item -ItemType Directory -Force (Join-Path $ccSeed10o 'scripts') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $ccSeed10o 'specs/tasks') | Out-Null
Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10o 'scripts/check-cards.ps1') -Force
Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10o 'scripts/_cards.ps1') -Force
function New-SeedCard10o([string]$BudgetLine) {
  $l = @('---', 'id: T9-BAD-BUDGET', 'title: seeded card budget value shape (T233)', 'status: todo')
  if ($BudgetLine) { $l += $BudgetLine }
  $l += @('dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - a.md', '---',
    '# Seeded defect card (T233): the budget: value shape, judged at card time')
  Set-Content (Join-Path $ccSeed10o 'specs/tasks/T9-BAD-BUDGET.md') ($l -join "`n") -Encoding utf8
}
New-SeedCard10o 'budget: soon'
$ccOut10o = & pwsh -NoProfile -File (Join-Path $ccSeed10o 'scripts/check-cards.ps1') -TaskId T9-BAD-BUDGET 2>&1 | Out-String
$ccExit10o = $LASTEXITCODE
New-SeedCard10o ''
$ccOut10oNone = & pwsh -NoProfile -File (Join-Path $ccSeed10o 'scripts/check-cards.ps1') -TaskId T9-BAD-BUDGET 2>&1 | Out-String
$ccExit10oNone = $LASTEXITCODE
Remove-Item -Recurse -Force $ccSeed10o -ErrorAction SilentlyContinue
if ($localLegacyCardPolicy10) {
  if ($ccExit10o -ne 0 -or $ccOut10o -match '\[CARD-BUDGET\]') { Fail "gate 10o: the preserved local policy keeps budget-shape validation advisory, but the malformed fixture became blocking (exit=$ccExit10o).`nActual output: $ccOut10o" }
  elseif ($ccExit10oNone -ne 0 -or $ccOut10oNone -match '\[CARD-BUDGET\]') { Fail "gate 10o: the budget-absent control is no longer silent (exit=$ccExit10oNone).`nActual output: $ccOut10oNone" }
  elseif (-not $fail) { Write-Host '  local compatibility 10o OK: budget-shape policy remains non-blocking' -ForegroundColor Green }
}
elseif ($ccExit10o -eq 0) { Fail "gate 10o seeded defect (T233): a card declaring 'budget: soon' was ACCEPTED by check-cards.ps1 (exit 0) - the value-shape rule is not wired into the entry script, so a budget that reads as a number to a human and as ABSENT to Get-ScaffoldCardBudgetValue ships as a governed card that no gate is governing.`nActual output: $ccOut10o" }
elseif ($ccOut10o -notmatch '\[CARD-BUDGET\]') { Fail "gate 10o seeded defect (T233): check-cards rejected the card (exit=$ccExit10o) but the message carries no [CARD-BUDGET] sentinel - another rule may have caught it by coincidence, so this rule is not proven covered (L165: a bare non-zero is not evidence).`nActual output: $ccOut10o" }
elseif ($ccExit10oNone -ne 0) { Fail "gate 10o (absence must stay legal, T233): the SAME fixture with the budget line removed was REJECTED (exit=$ccExit10oNone). The budget key is deliberately optional - making it required reds every in-flight card that predates the field, mid-acceptance, which is exactly what the card's forbid clause rules out.`nActual output: $ccOut10oNone" }
elseif ($ccOut10oNone -match '\[CARD-BUDGET\]') { Fail "gate 10o (absence must stay SILENT, T233): the budget-less fixture passed (exit 0) but the output still carries a [CARD-BUDGET] line - absence is not a finding, and reporting it trains readers to ignore the sentinel.`nActual output: $ccOut10oNone" }
else { Write-Host '  seeded defect 10o OK: a declared-but-unusable budget is rejected with [CARD-BUDGET], and the same card with no budget passes silently (T233 wiring present, absence still legal)' -ForegroundColor Green }
# Anti-vacuous arms, same shape as 10k/10l/10m/10n: the declared examples must agree with the live rule,
# and each REJECTED design must measurably differ from it. A variant producing nothing means the table
# stopped discriminating, and a table that discriminates nothing passes wherever the rule is absent.
$budgetFindings10o = @(Test-ScaffoldCardBudgetFindingExamples)
if ($budgetFindings10o.Count) { $budgetFindings10o | ForEach-Object { Fail "gate 10o (budget value examples, T233): $_" } }
if (@(Test-ScaffoldCardBudgetFindingExamples -Variant 'absent-rejected').Count -lt 1) {
  Fail "gate 10o (anti-vacuous / absent-rejected): feeding the SAME examples a rule that REPORTS on a card with no budget produced zero findings, so the table no longer carries an absent-budget case and 'absence never blocks' is intended rather than tested. That case is the only thing standing between this rule and redding every card that predates the field. [FIX] confirm the no-key example is still in Test-ScaffoldCardBudgetFindingExamples."
}
if (@(Test-ScaffoldCardBudgetFindingExamples -Variant 'accept-any-value').Count -lt 1) {
  Fail "gate 10o (anti-vacuous / accept-any-value): feeding the SAME examples a rule that ACCEPTS every declared value produced zero findings, so the table no longer carries a malformed value and the green run above proves only that the rule stayed quiet. [FIX] confirm the non-numeric, zero and negative examples are still in Test-ScaffoldCardBudgetFindingExamples."
}
# 10p. [CARD-BUDGET-DECISION] (T240/TD246): the DECISION core's declared examples, judged by a gate.
#     Sub-gate 10o above covers the value SHAPE rule; this covers the state machine, the binding, the
#     reader and the budget SOURCE - a different table, and until now one no run touched. Its only caller
#     was the archived T231 card's `dod_command`, which nothing executes (TD229's class), so its three
#     rejected shapes had proved nothing since that card merged and a case added to it would have proved
#     nothing either. Asserted BOTH ways, which is the contract the table's own header states: zero
#     findings from the live core, and at least one finding from each variant, so a table that stopped
#     discriminating is visible instead of quietly green.
$cbDecision10p = @(Test-ScaffoldCardBudgetExamples)
if ($cbDecision10p.Count) { $cbDecision10p | ForEach-Object { Fail "gate 10p [CARD-BUDGET-DECISION] $_" } }
else {
  $cbDead10p = @()
  foreach ($cbVariant10p in @('no-trip', 'absent-blocks', 'branch-side-budget')) {
    if (@(Test-ScaffoldCardBudgetExamples -Variant $cbVariant10p).Count -lt 1) { $cbDead10p += $cbVariant10p }
  }
  if ($cbDead10p.Count) {
    Fail "gate 10p (anti-vacuous): rejected shape(s) '$($cbDead10p -join ', ')' produced ZERO findings against the same examples, so the rule each one breaks is exercised by no case in the table and the green run above proves only that the core stayed quiet. [FIX] restore the case that discriminates that shape in Test-ScaffoldCardBudgetExamples."
  }
  elseif (-not $fail) { Write-Host '  10p [CARD-BUDGET-DECISION] OK (state table incl. both trip boundaries, base-card binding, budget SOURCE named for a default-sourced overrun and not for a card-declared one, value reader; three rejected shapes each still measurably red)' -ForegroundColor Green }
}
# 10q. [REVIEW-RUN-DECISION] (T242/TD248): the ship R3 leg's run/skip DECISION, judged by a gate.
#     The decision that says whether a card gets its second review read `$ScaffoldConfig.ReviewGate` and
#     nothing else, so a card declaring `review_gate:` shipped without one - measured on T238 and T239,
#     both of which declared it and both of whose reviews returned block once someone ran them by hand.
#     What makes this a gate rather than a code comment: the decision has TWO call sites (remote ship and
#     -Local ship) and the difference the project cares about, run versus BLOCK, is invisible in a boolean.
#     Asserted BOTH ways, the contract the table's own header states: zero findings from the live core,
#     and at least one finding from each rejected shape, so a table that stopped discriminating is visible
#     instead of quietly green.
$rrDecision10q = @(Test-ScaffoldReviewRunDecisionExamples)
if ($rrDecision10q.Count) { $rrDecision10q | ForEach-Object { Fail "gate 10q [REVIEW-RUN-DECISION] $_" } }
else {
  $rrDead10q = @()
  foreach ($rrVariant10q in @('config-only', 'card-blocks', 'run-always')) {
    if (@(Test-ScaffoldReviewRunDecisionExamples -Variant $rrVariant10q).Count -lt 1) { $rrDead10q += $rrVariant10q }
  }
  if ($rrDead10q.Count) {
    Fail "gate 10q (anti-vacuous): rejected shape(s) '$($rrDead10q -join ', ')' produced ZERO findings against the same examples, so the rule each one breaks is exercised by no case in the table and the green run above proves only that the core stayed quiet. 'config-only' is the pre-T242 defect itself, 'card-blocks' is the naive fix that re-arms the merge gate T68 removed, and 'run-always' is a fix with no negative control. [FIX] restore the case that discriminates that shape in Test-ScaffoldReviewRunDecisionExamples."
  }
  elseif (-not $fail) { Write-Host '  10q [REVIEW-RUN-DECISION] OK (card declaration runs the reviewer advisory, no declaration still skips it, required still blocks and outranks a card, whitespace and padding read correctly; three rejected shapes each still measurably red)' -ForegroundColor Green }
}

# 10r. [CARD-DOD-FN-EXISTS] (T243/TD250): the existence-arm DECISION's declared examples, judged by a gate.
#     The seeded fixtures at 10f(f33-f36) above prove check-cards WIRES this rule; this gate proves the rule
#     itself still discriminates. (That reference is deliberately not written at the start of this line: a
#     comment opening '# 10f(' is read by 14m as a CONTINUATION header for 10f, which this block is not.)
#     The two are different questions and the seeded fixtures cannot answer the second: they drive whole
#     cards through check-cards, so they can only see a verdict, while the boundaries that make this rule
#     usable rather than merely loud - a name in a string literal is not a call, a payload is analysed
#     separately from the text around it, an arm placed AFTER the call still counts, and an assertion has
#     to be an arm that EXITS on absence with the name bound, not any mention of Get-Command (T244/TD252),
#     and that arm has to be one the missing command really REACHES and really leaves non-zero (T262/TD257),
#     on the ubuntu runner as well as here (T267/TD268), judged on the FIRST terminator the clause body
#     reaches rather than on any acceptable one below it (T268/TD270) - live in the predicate.
#     Asserted BOTH ways, the contract the table's own header states: zero findings from the live core, and
#     at least one finding from each rejected shape, so a table that stopped discriminating is visible
#     instead of quietly green.
$dfDecision10r = @(Test-ScaffoldDodFnExistsExamples)
if ($dfDecision10r.Count) { $dfDecision10r | ForEach-Object { Fail "gate 10r [CARD-DOD-FN-EXISTS] $_" } }
else {
  $dfDead10r = @()
  # DERIVED, not re-listed (T262/TD257). A hand-kept second copy of the shape names is a pair that goes
  # silently out of step the moment one side grows - the TD241/TD254 class - and this gate grew from four
  # names to seven in one card. Reading the core's own [ValidateSet] means a shape added later is exercised
  # here without a second edit, and a shape deleted there cannot leave a dead name behind.
  # The attribute is SELECTED rather than read off the collection: this file runs under Set-StrictMode
  # -Version Latest, and `.Attributes.ValidValues` enumerates a collection that also holds the parameter's
  # own [Parameter()] attribute, which has no such property - that throws and takes the whole gate down.
  $dfShapes10r = @((Get-Command Test-ScaffoldDodFnExistsExamples).Parameters['Variant'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] } | ForEach-Object { $_.ValidValues })
  # Fail-closed on the derivation itself: a reflection that came back SHORT leaves the loop below exercising
  # only what it got, and the gate reports OK on the shapes that vanished. The floor is the count the core
  # declares today and is written as a floor, not an equality, so an eleventh shape does not turn this red.
  # The message states the count it READ rather than asserting the loop does nothing: that is only true at
  # zero, and a diagnostic whose first clause is false at 1-3 sends the next reader after the wrong cause
  # (TD268; the same failure L97 names, where a contrast sentence still asserts its first half).
  $dfFloor10r = 11
  if ($dfShapes10r.Count -lt $dfFloor10r) { Fail "gate 10r (anti-vacuous): the rejected-shape list read back from Test-ScaffoldDodFnExistsExamples' own [ValidateSet] holds $($dfShapes10r.Count) name(s), fewer than the $dfFloor10r this gate requires. At zero the loop below exercises nothing at all, and at any count below the floor it exercises only the names that came back - EVERY one of them, which is what this floor is really about. It is not that a name the loop received goes unmeasured; it is that a name has LEFT the declaration, and a loop driven by reflection cannot notice what is no longer there to reflect. [FIX] restore the [ValidateSet] on the -Variant parameter in scripts/_cards.ps1." }
  foreach ($dfVariant10r in $dfShapes10r) {
    if (@(Test-ScaffoldDodFnExistsExamples -Variant $dfVariant10r).Count -lt 1) { $dfDead10r += $dfVariant10r }
  }
  if ($dfDead10r.Count) {
    Fail "gate 10r (anti-vacuous): rejected shape(s) '$($dfDead10r -join ', ')' produced ZERO findings against the same examples, so the rule each one breaks is exercised by no case in the table and the green run above proves only that the core stayed quiet. 'text-match' reads a name mentioned in a -Pattern or a .Replace() literal as a call, which is T234's live dod; 'ignore-payload' scans only the outer AST and so never sees the canonical nested -Command payload, which is the L95 residual this rule exists to close; 'assert-anywhere' accepts any Get-Command mention as an assertion regardless of arm shape or parameter binding, and 'payload-into-parent' lets the outer walk see through a scriptblock payload so an outer arm vouches across a process boundary - both were MEASURED bypasses of the shipped rule (TD252). 'lookup-anywhere' lets the walk cross any node on its way to the if, so a compound condition counts although the arm can never be taken; 'terminator-anywhere' finds the terminator anywhere below the clause, so an exit in a dead branch and a throw its own catch swallows both count; 'exit-any-status' accepts an exit whatever status it carries, and exit 0 on the missing-command path is the vacuous GREEN the rule exists to stop - all three were MEASURED bypasses of the narrowed rule (TD257). 'pipeline-any-length' accepts the pipeline carrying the lookup however many elements it holds, so a lookup piped to Measure-Object counts although whatever stands downstream decides the truth value and the arm is never taken; 'ignore-divert' reads the clause body as a set rather than in order, so an exit standing behind a return counts although return at script scope ends the unit at 0; 'exit-status-unmasked' accepts any non-zero constant, so exit 256 counts although POSIX masks a wait status to 8 bits and the ubuntu runner sees 0 - all three were MEASURED bypasses of the reachability rule (TD268). 'exit-skip-rejected' walks past an exit whose status the rule just refused and credits a later acceptable one, so { exit 0; exit 1 } counts although the exit 0 is the statement that runs - four shapes MEASURED that way (TD270). [FIX] restore the case that discriminates that shape in Test-ScaffoldDodFnExistsExamples."
  }
  elseif (-not $fail) { Write-Host '  10r [CARD-DOD-FN-EXISTS] OK (bare call flagged, the printed repair clears it, string-literal and bareword mentions are not calls, nested payloads analysed, a late arm still counts, partial coverage still flagged; an assertion must exit on absence and must bind the name, a scriptblock payload is its own unit while an in-process scriptblock is not; the lookup must BE the condition of a single-element pipeline and the terminator must be the FIRST one the clause body reaches, carrying a status in 1..255, while a report before the exit and statuses of 2 and 255 still count; every rejected shape the core declares is still measurably red)' -ForegroundColor Green }
}

# 10s. [CARD-DOD-REGIME] (T270/TD250 fix (b)): the payload builder judged by what it DOES, not by its text.
#     The gate above and Test-ScaffoldDodPayloadExamples are both hermetic string tests - deliberately, so
#     a review sandbox can re-run them (L60). (That reference is written this way round for the reason 10r
#     states about its own: a comment line opening with a bare label is read by 14m as a CONTINUATION
#     header for that label. This block is not one, and writing it the obvious way cost one silent red.)
#     Neither can see the only property that matters here: whether
#     the text this builder returns actually ends the unit on a dod that no-ops. That needs child
#     processes, so it lives in a gate rather than in the examples table.
#     THE MATRIX IS THE ASSERTION. Three dod shapes measured vacuous under the shipped raw regime must go
#     NON-ZERO under the live payload, and both honest verdicts must be UNCHANGED - an alignment that only
#     turned things red would be a gate that breaks working cards, which is the direction this must not err
#     in. The `raw` variant is the negative control on the same shapes: it must reproduce the vacuous 0s,
#     otherwise this whole block is asserting a difference that the environment, not the builder, produces.
#     Every child runs with the PARENT's $PSNativeCommandUseErrorActionPreference at $false, which is the
#     regime `-Phase red` uses - so this gate also proves the claim the card rests on: a wrapped payload
#     and a readable exit code are not in tension (TD250's false premise).
Step '10s [CARD-DOD-REGIME] the dod payload measured in child processes (three vacuous shapes go non-zero, both honest verdicts unchanged, raw reproduces the vacuity)'
# No `Get-Command Get-ScaffoldDodPayload` guard, deliberately, and the reason is worth one line because the
# guard LOOKS like diligence: it would be read by 8.2j as an environment-skip site (a tool-absent branch
# whose body does not run while the gate still reports PASS), and it buys nothing here - the builder is a
# repo function, not a tool, so if it goes missing the call below raises CommandNotFoundException under this
# script's own `Stop` and the gate goes red for the true reason. Same shape as 10r above, which also just
# calls its examples function.
# FIRST the hermetic table, asserted BOTH ways exactly as 10r asserts its own: zero findings from the live
# builder, and at least one from each rejected shape. Without the second half a table that had stopped
# discriminating would sail through, and the behavioural matrix below would be the only thing left judging
# - which is the shape this whole card exists to remove, one proof standing in for two.
$rgDecision10s = @(Test-ScaffoldDodPayloadExamples)
if ($rgDecision10s.Count) { $rgDecision10s | ForEach-Object { Fail "gate 10s [CARD-DOD-PAYLOAD] $_" } }
else {
  $rgDead10s = @()
  # DERIVED from the builder's own [ValidateSet], never re-listed here: a hand-kept second copy of the
  # shape names is the pair that goes stale (T262/TD257, and 10r above does the same).
  $rgShapes10s = @((Get-Command Test-ScaffoldDodPayloadExamples).Parameters['Variant'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] } | ForEach-Object { $_.ValidValues })
  if ($rgShapes10s.Count -lt 3) { Fail "gate 10s (anti-vacuous): the rejected-shape list read back from Test-ScaffoldDodPayloadExamples' own [ValidateSet] holds $($rgShapes10s.Count) name(s), fewer than the 3 this gate requires. Every name that came back IS exercised below, so this floor is not about the coverage of the list it read - it is that a shape the builder is expected to declare has LEFT the declaration, and a loop driven by reflection cannot notice what is no longer there to reflect. [FIX] restore the [ValidateSet] on the -Variant parameter in scripts/_cards.ps1." }
  foreach ($rgVariant10s in $rgShapes10s) {
    if (@(Test-ScaffoldDodPayloadExamples -Variant $rgVariant10s).Count -lt 1) { $rgDead10s += $rgVariant10s }
  }
  if ($rgDead10s.Count) {
    Fail "gate 10s (anti-vacuous): rejected shape(s) '$($rgDead10s -join ', ')' produced ZERO findings against the same examples, so the rule each one breaks is exercised by no case in the table. 'raw' is the regime -Phase red shipped with, under which a missing command, a missing FILE and a failing native command all leave the unit at 0; 'errorpref-only' keeps the Stop half and drops the native one, which leaves a failing native command silent; 'nativepref-only' keeps the native half alone and is MEASURED INERT - it reproduces the raw verdict on every shape, because a native error still obeys a Continue policy, which is why the two assignments are one clause rather than two. [FIX] restore the case that discriminates that shape in Test-ScaffoldDodPayloadExamples."
  }
}
# THEN the behavioural half, which the hermetic table cannot reach.
# cases: name -> @(dod text, expected exit under the LIVE payload, expected exit under `raw`)
# The three vacuous shapes are the ones TD250 and TD236 were measured on; the two honest ones are the
# boundary from the other side, and they are why this is an alignment rather than a tightening.
$rgCases10s = @(
  @{ what = 'a missing repo function on the arm path (TD250, measured on T242)'; dod = 'if (-not (Get-ScaffoldNoSuchThingT270).Bar) { exit 1 }; exit 0'; live = 1; raw = 0 }
  @{ what = 'a positive grep at a path that does not exist (the TD236 shape)'; dod = 'if (-not (Select-String -Path no-such-dir-t270/no-such-file.md -Pattern X -SimpleMatch -Quiet)) { exit 1 }; exit 0'; live = 1; raw = 0 }
  @{ what = 'a failing native command before a trailing exit 0'; dod = 'git rev-parse --verify no-such-ref-t270; exit 0'; live = 1; raw = 0 }
  @{ what = 'an honest failure stays a failure'; dod = 'if (1 -eq 1) { exit 1 }; exit 0'; live = 1; raw = 1 }
  @{ what = 'an honest pass stays a pass - alignment must not redden a working card'; dod = 'if (1 -eq 2) { exit 1 }; exit 0'; live = 0; raw = 0 }
)
# The parent preference is set to $false for the whole block and restored in finally: that is the regime
# -Phase red runs under, and reading $LASTEXITCODE rather than catching a throw is the point being proved.
# Read defensively per R3 r4 #10 - the variable is PS 7.3+ and StrictMode throws on an undefined read.
$rgPrev10s = if (Test-Path variable:PSNativeCommandUseErrorActionPreference) { $PSNativeCommandUseErrorActionPreference } else { $true }
$rgBad10s = @()
try {
  $PSNativeCommandUseErrorActionPreference = $false
  foreach ($c in $rgCases10s) {
    & pwsh -NoProfile -Command (Get-ScaffoldDodPayload -Dod $c.dod) *> $null
    $gotLive = $LASTEXITCODE
    & pwsh -NoProfile -Command (Get-ScaffoldDodPayload -Dod $c.dod -Variant raw) *> $null
    $gotRaw = $LASTEXITCODE
    $liveOk = if ($c.live -eq 0) { $gotLive -eq 0 } else { $gotLive -ne 0 }
    $rawOk = if ($c.raw -eq 0) { $gotRaw -eq 0 } else { $gotRaw -ne 0 }
    if (-not $liveOk) { $rgBad10s += "case '$($c.what)': the LIVE payload exited $gotLive, expected $(if ($c.live -eq 0) { 'zero' } else { 'non-zero' })" }
    if (-not $rawOk) { $rgBad10s += "case '$($c.what)': the raw control exited $gotRaw, expected $(if ($c.raw -eq 0) { 'zero' } else { 'non-zero' })" }
  }
}
finally { $PSNativeCommandUseErrorActionPreference = $rgPrev10s }
if ($rgBad10s.Count) {
  Fail ("10s [CARD-DOD-REGIME]: " + ($rgBad10s -join ' ; ') + ". task.ps1 runs BOTH -Phase red and -Phase ship through Get-ScaffoldDodPayload, so what this payload does to a no-op dod is what the DoD gate and the RED checkpoint each decide. A live case that exited zero means a dod can bank a vacuous GREEN again (TD250/L308); an honest case that changed verdict means the alignment is reddening working cards, which is the direction it must not err in; a raw control that no longer reproduces the vacuity means this gate is measuring the environment rather than the builder, and its green proves nothing. [FIX] fix Get-ScaffoldDodPayload in scripts/_cards.ps1, never these cases.")
}
elseif (-not $fail) { Write-Host '  10s [CARD-DOD-REGIME] OK (a missing function, a grep at a missing path and a failing native command all end the unit non-zero under the live payload and all exited ZERO under the raw control; an honest failure and an honest pass keep their verdicts; every child read as an exit code with the parent native preference off, which is the regime -Phase red uses)' -ForegroundColor Green }

# 10t. [CARD-TIER] (T273/ADR 0016): the tier a card's allow_paths COMPUTE, the raise a card may declare,
#     and the lowering check-cards refuses. Three questions in one sub-gate because they are one decision:
#     the table proves the DECISION over every shape it separates, the equivalence arm proves the matcher
#     it decides with is still the ship scope gate's, and the seeded cards prove the WIRING - that the real
#     entry script calls it, prints the line both task.ps1 phases show, and blocks on a lowering card.
#     A tier nothing prints is a tier nobody can act on, and a tier no card can be blocked over is advice.
Step '10t [CARD-TIER] computed tier: declared examples, matcher equivalence with the scope gate, and the seeded print/block through check-cards'
# FIRST the hermetic table, asserted BOTH ways as 10p/10q/10r/10s assert theirs: zero findings from the live
# decision, at least one from each rejected shape. The shape names are DERIVED from the examples function's
# own [ValidateSet] rather than re-listed, for the reason 10r states: a hand-kept second copy is the pair
# that goes stale, and a loop driven by reflection cannot notice a name that has left the declaration.
$ctDecision10t = @(Test-ScaffoldCardTierExamples)
if ($ctDecision10t.Count) { $ctDecision10t | ForEach-Object { Fail "gate 10t [CARD-TIER] $_" } }
else {
  $ctDead10t = @()
  $ctShapes10t = @((Get-Command Test-ScaffoldCardTierExamples).Parameters['Variant'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] } | ForEach-Object { $_.ValidValues })
  if ($ctShapes10t.Count -lt 3) { Fail "gate 10t (anti-vacuous): the rejected-shape list read back from Test-ScaffoldCardTierExamples' own [ValidateSet] holds $($ctShapes10t.Count) name(s), fewer than the 3 this gate requires. Every name that came back IS exercised below, so the floor is not about the coverage of the list it read - it is that a shape the decision is expected to declare has LEFT the declaration. [FIX] restore the [ValidateSet] on the -Variant parameter in scripts/_cards.ps1." }
  foreach ($ctVariant10t in $ctShapes10t) {
    if (@(Test-ScaffoldCardTierExamples -Variant $ctVariant10t).Count -lt 1) { $ctDead10t += $ctVariant10t }
  }
  if ($ctDead10t.Count) {
    Fail "gate 10t (anti-vacuous): rejected shape(s) '$($ctDead10t -join ', ')' produced ZERO findings against the same examples, so the rule each one breaks is exercised by no case in the table and the green run above proves only that the decision stayed quiet. 'ignore-declared' drops the declaration entirely, so a card that knows it is riskier than its paths look cannot say so; 'allow-lower' lets the declaration win in BOTH directions, which is the tier an author under pressure lowers - the shape ADR 0016 rejected in those words; 'no-off-switch' stops reading an empty TierSPaths as tiering off, so a downstream that has not filled the list in would drop every card to the cheapest bar instead of keeping today's. [FIX] restore the case that discriminates that shape in Test-ScaffoldCardTierExamples."
  }
}
# T280: the OTHER half of the tier's input - WHICH COPY of the card its allow_paths were read from - has a
# declared table of its own, driven here rather than only by the card's DoD, because a self-check nobody
# runs is a function and not coverage (ADR 0011). Same contract both ways, and the shape list is read back
# from the [ValidateSet] rather than restated, so a shape added to the decision is exercised on arrival.
$csDecision10t = @(Test-ScaffoldTierCardTextExamples)
if ($csDecision10t.Count) { $csDecision10t | ForEach-Object { Fail "gate 10t [TIER-CARD-SOURCE] $_" } }
else {
  $csDead10t = @()
  $csShapes10t = @((Get-Command Test-ScaffoldTierCardTextExamples).Parameters['Variant'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] } | ForEach-Object { $_.ValidValues })
  if ($csShapes10t.Count -lt 2) { Fail "gate 10t (anti-vacuous): the rejected-shape list read back from Test-ScaffoldTierCardTextExamples' own [ValidateSet] holds $($csShapes10t.Count) name(s), fewer than the 2 this gate requires. [FIX] restore the [ValidateSet] on the -Variant parameter in scripts/_cards.ps1." }
  foreach ($csVariant10t in $csShapes10t) {
    if (@(Test-ScaffoldTierCardTextExamples -Variant $csVariant10t).Count -lt 1) { $csDead10t += $csVariant10t }
  }
  if ($csDead10t.Count) {
    Fail "gate 10t (anti-vacuous): rejected shape(s) '$($csDead10t -join ', ')' produced ZERO findings against the card-source examples, so the rule each one breaks is exercised by no case and the green run above proves only that the decision stayed quiet. Both are the same bypass through different doors: 'working-tree-wins' prefers the branch's own copy of the card while a base copy exists, so narrowing allow_paths inside a branch buys a cheaper tier; 'missing-base-is-cheap' falls back to that copy when the baseline has none, so a card the baseline never carried still computes a bar. [FIX] restore the case that discriminates that shape in Test-ScaffoldTierCardTextExamples."
  }
}
# THEN the equivalence arm, which the table cannot reach. Get-ScaffoldCardTier matches with
# Test-ScaffoldTierPathMatch, a restatement of the three clauses inside Get-ScaffoldOutOfScopePath
# (scripts/_scope.ps1, dot-sourced by 10d' above): the load order rules out a call - _scope.ps1 sources
# _cards.ps1 for the front-matter reader, and the seeded fixtures below copy check-cards.ps1 + _cards.ps1
# alone - so the bond is made here instead, and it is a stronger one than a shared call. A call proves the
# same CODE ran; this proves the same ANSWER, over the shapes the two rules exist to separate, which is
# what the TD68 drift pairs got wrong while looking byte-identical. Both directions of the pair matter:
# a tier entry that stopped matching under-tiers a card, and one that started matching over-tiers it.
$ctPaths10t = @('scripts/_guard.ps1', 'scripts/_guard.ps1.bak', '.github/workflows/ci.yml', '.github/workflowsX/ci.yml', 'docs/HANDOFF.md', 'docsite/x.md', 'specs/mutations/', 'CHANGELOG.md', 'scripts\_guard.ps1')
$ctEntries10t = @('scripts/_guard.ps1', '.github/workflows/', 'docs/', 'specs/', '*.md', 'CHANGELOG.md')
$ctDisagree10t = @()
foreach ($ctP10t in $ctPaths10t) {
  foreach ($ctE10t in $ctEntries10t) {
    $mine10t = [bool](Test-ScaffoldTierPathMatch -Path $ctP10t -Entry $ctE10t)
    # The scope gate's answer, read through its own production matcher: a path it does NOT report as out
    # of scope against this single entry is a path that entry covers.
    $scope10t = (@(Get-ScaffoldOutOfScopePath -ChangedPath @($ctP10t) -AllowPath @($ctE10t)).Count -eq 0)
    if ($mine10t -ne $scope10t) { $ctDisagree10t += "path '$ctP10t' vs entry '$ctE10t': tier matcher says $mine10t, scope gate says $scope10t" }
  }
}
if ($ctDisagree10t.Count) {
  Fail ("10t matcher equivalence: the tier matcher and the ship scope gate no longer give the same answer - " + ($ctDisagree10t -join ' ; ') + ". ADR 0016 defines a card's tier as its allow_paths matched THE WAY THE SCOPE GATE MATCHES THEM, so a divergence here means the tier is computed against a rule the merge gate does not use: a card can be scoped one way and tiered another, and whichever is looser wins silently. [FIX] restore Test-ScaffoldTierPathMatch in scripts/_cards.ps1 to the three clauses of Get-ScaffoldOutOfScopePath in scripts/_scope.ps1 - fix the matcher, never this corpus.")
}
# THEN the wiring, through the real entry script on seeded cards. Two trees: one carrying _config.ps1, so
# the shipped default lists decide, and one WITHOUT it, which is both the off switch and the degradation
# every other seeded fixture in this gate depends on - check-cards must keep validating cards in a tree
# holding nothing but itself and _cards.ps1, and answer S there rather than throwing or going quiet.
$ccSeed10t = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10t-$PID"
if (Test-Path $ccSeed10t) { Remove-Item -Recurse -Force $ccSeed10t }
$ccSeed10tOff = "$ccSeed10t-off"
if (Test-Path $ccSeed10tOff) { Remove-Item -Recurse -Force $ccSeed10tOff }
foreach ($root10t in @($ccSeed10t, $ccSeed10tOff)) {
  New-Item -ItemType Directory -Force (Join-Path $root10t 'scripts') | Out-Null
  New-Item -ItemType Directory -Force (Join-Path $root10t 'specs/tasks') | Out-Null
  Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $root10t 'scripts/check-cards.ps1') -Force
  Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $root10t 'scripts/_cards.ps1') -Force
}
# Only the first tree gets a configuration; the second one IS the off switch.
Copy-Item (Join-Path $PSScriptRoot '_config.ps1') (Join-Path $ccSeed10t 'scripts/_config.ps1') -Force
$mk10t = {
  param($cardId, $allowPaths, $tierLine)
  # No debt row in the title - see the FIXTURE CONVENTION note at the head of gate 10. This one tests T273.
  (@('---', "id: $cardId", "title: seeded tier case ($cardId)", 'status: todo',
     'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/x.ps1)) { exit 1 }"', 'dod_exit: 0') +
   @($tierLine | Where-Object { $_ }) +
   @('allow_paths:') + @($allowPaths | ForEach-Object { "  - $_" }) +
   @('---', '', "# seeded card ($cardId)")) -join "`n"
}
# Every case names REAL default entries, so the fixture measures the shipped lists rather than a private
# copy of them: a card that touches an enforcer is S, one that touches only docs and specs is 0, one that
# touches a script no list names is 1, a declared S RAISES a 0 card, and a declared 1 on an S card is
# refused with the sentinel. The last case is the same 0-shaped card in the tree with no _config.ps1.
$cases10t = @(
  @{ Id = 'T9-TIER-S'; Root = $ccSeed10t; Allow = @('scripts/_guard.ps1'); Tier = $null; Expect = 'S'; Block = $false
     Why = 'touches an enforcer named in TierSPaths, so the full-run bar is where its exposure is' }
  @{ Id = 'T9-TIER-ZERO'; Root = $ccSeed10t; Allow = @('docs/HANDOFF.md', 'specs/tech-debt-tracker.md'); Tier = $null; Expect = '0'; Block = $false
     Why = 'declares nothing outside Tier0Paths - the doc and ledger commit that is 80% of this history' }
  @{ Id = 'T9-TIER-ONE'; Root = $ccSeed10t; Allow = @('scripts/lessons.ps1', 'docs/LESSONS.md'); Tier = $null; Expect = '1'; Block = $false
     Why = 'touches a script no TierS entry names while not being all-docs, which is the default tier' }
  @{ Id = 'T9-TIER-RAISE'; Root = $ccSeed10t; Allow = @('docs/HANDOFF.md'); Tier = 'tier: S'; Expect = 'S'; Block = $false
     Why = 'computes 0 and declares S - the raise ADR 0016 allows, so a card can state a risk its paths do not show' }
  @{ Id = 'T9-TIER-LOWER'; Root = $ccSeed10t; Allow = @('scripts/_guard.ps1'); Tier = 'tier: 1'; Expect = 'S'; Block = $true
     Why = 'computes S and declares 1 - the lowering that must be refused AND reported, or the whole computed tier is advice' }
  @{ Id = 'T9-TIER-OFF'; Root = $ccSeed10tOff; Allow = @('docs/HANDOFF.md'); Tier = $null; Expect = 'S'; Block = $false
     Why = 'sits in a tree with no _config.ps1 at all: empty lists mean tiering is off and every card is S, today''s bar' }
)
foreach ($c10t in $cases10t) {
  Set-Content (Join-Path $c10t.Root "specs/tasks/$($c10t.Id).md") (& $mk10t $c10t.Id $c10t.Allow $c10t.Tier) -Encoding utf8
  $out10t = & pwsh -NoProfile -File (Join-Path $c10t.Root 'scripts/check-cards.ps1') -TaskId $c10t.Id 2>&1 | Out-String
  $exit10t = $LASTEXITCODE
  $line10t = "[CARD-TIER] id=$($c10t.Id) tier=$($c10t.Expect) reason="
  # .Contains, not -like and not -match: the expected line OPENS with a bracketed sentinel, which -like
  # reads as a character class and -match as one too, so either operator would compare something other
  # than this text. Measured on this gate's own first run, where all six cases reported a line the log
  # shows was printed exactly as expected.
  if (-not $out10t.Contains($line10t)) {
    Fail "gate 10t ($($c10t.Id)) seeded print: check-cards.ps1 did not print '$line10t...' for a card that $($c10t.Why). Either the tier line is not wired into the entry script - in which case neither task.ps1 -Phase start nor -Phase ship shows a tier and every later tiered gate reads nothing - or the computed tier is wrong for this shape.`nActual output: $out10t"
  }
  elseif ($c10t.Block) {
    if ($exit10t -eq 0) { Fail "gate 10t ($($c10t.Id)) seeded block: a card that $($c10t.Why) was ACCEPTED by check-cards.ps1 (exit 0). A declaration that can LOWER the computed tier is the tier an author under pressure lowers, and it arrives as a one-line edit inside the branch while the computed value is bound to allow_paths off the BASE card.`nActual output: $out10t" }
    elseif ($out10t -notmatch '\[CARD-TIER-LOWER\]') { Fail "gate 10t ($($c10t.Id)): check-cards rejected the card (exit=$exit10t) but the message carries no [CARD-TIER-LOWER] sentinel - another rule may have caught it by coincidence, so this rule is not proven covered (L165: a bare non-zero is not evidence).`nActual output: $out10t" }
    elseif (-not $fail) { Write-Host "  seeded defect 10t($($c10t.Id)) OK: a card that $($c10t.Why) is rejected, prints tier=$($c10t.Expect) and carries the [CARD-TIER-LOWER] sentinel" -ForegroundColor Green }
  }
  elseif ($exit10t -ne 0) {
    Fail "gate 10t ($($c10t.Id)): check-cards REJECTED a card it must accept (exit=$exit10t). This card $($c10t.Why), and no tier is a reason to refuse a card - the tier decides the ACCEPTANCE a card owes, never whether it is valid.`nActual output: $out10t"
  }
  elseif (-not $fail) { Write-Host "  seeded defect 10t($($c10t.Id)) OK: prints tier=$($c10t.Expect) - $($c10t.Why)" -ForegroundColor Green }
}
Remove-Item -Recurse -Force $ccSeed10t -ErrorAction SilentlyContinue
Remove-Item -Recurse -Force $ccSeed10tOff -ErrorAction SilentlyContinue
if (-not $fail) { Write-Host '  10t [CARD-TIER] OK (both declared tables driven both ways over every rejected shape their own [ValidateSet]s declare - the tier decision and, since T280, which COPY of the card it read; the matcher agrees with the scope gate over every shape they separate; S/0/1 printed through the real entry script, a declared raise honoured, a declared lowering blocked with its sentinel, and an absent _config.ps1 read as tiering off)' -ForegroundColor Green }

# 10u. [CARD-REQ-DANGLING] (T276/ADR 0016 item 5), [CARD-TIER-BADVALUE] (T276) and [CARD-ARBITRATION]
#     (T285/ADR 0016 item 4): the card-field refusals, each proved twice - the hermetic table over every
#     shape it separates, and the real entry script over a seeded card, because a rule the validator never
#     calls is a function and not a guard. They share one sub-gate because they share one fixture tree and
#     one wiring question; T285 folded its rule in here rather than claim a new label for the third variant
#     of the same question ([SUBGATE-CEILING]).
Step '10u [CARD-REQ-DANGLING] requirement citations, the bad tier value and the arbitration entry: declared examples plus the seeded block through check-cards'
# FIRST the hermetic table, asserted BOTH ways as 10r/10s/10t assert theirs: zero findings from the live
# rule, at least one from each rejected shape, and the shape names read back from the examples function's
# own [ValidateSet] rather than restated here - a hand-kept second copy is the pair that goes stale.
$crDecision10u = @(Test-ScaffoldCardRequirementExamples)
if ($crDecision10u.Count) { $crDecision10u | ForEach-Object { Fail "gate 10u [CARD-REQ-DANGLING] $_" } }
else {
  $crDead10u = @()
  $crShapes10u = @((Get-Command Test-ScaffoldCardRequirementExamples).Parameters['Variant'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] } | ForEach-Object { $_.ValidValues })
  if ($crShapes10u.Count -lt 2) { Fail "gate 10u (anti-vacuous): the rejected-shape list read back from Test-ScaffoldCardRequirementExamples' own [ValidateSet] holds $($crShapes10u.Count) name(s), fewer than the 2 this gate requires. Every name that came back IS exercised below, so the floor is not about the coverage of the list it read - it is that a shape the rule is expected to declare has LEFT the declaration, and a loop driven by reflection cannot notice what is no longer there to reflect. [FIX] restore the [ValidateSet] on the -Variant parameter in scripts/_cards.ps1." }
  foreach ($crVariant10u in $crShapes10u) {
    if (@(Test-ScaffoldCardRequirementExamples -Variant $crVariant10u).Count -lt 1) { $crDead10u += $crVariant10u }
  }
  if ($crDead10u.Count) {
    Fail "gate 10u (anti-vacuous): rejected shape(s) '$($crDead10u -join ', ')' produced ZERO findings against the same examples, so the rule each one breaks is exercised by no case in the table and the green run above proves only that the rule stayed quiet. 'ignore-dangling' never resolves the citation, which makes the link decoration: a renumbered or deleted requirement leaves an acceptance item pointing at nothing and nothing says so. 'require-list' reports a card that declares no requirements and cites none, which turns an optional field into a required one and reds every card written before it existed - the degradation `budget:` already makes. [FIX] restore the case that discriminates that shape in Test-ScaffoldCardRequirementExamples."
  }
}
# T285: the arbitration table, driven the same two ways for the same reason. This one guards a WAIVER, so a
# quiet rule here does not merely mis-report a card - it lets a recorded ruling that cannot bind look like
# one that can, and the ship then reads a bypass as an arbitration.
$caDecision10u = @(Test-ScaffoldCardArbitrationExamples)
if ($caDecision10u.Count) { $caDecision10u | ForEach-Object { Fail "gate 10u [CARD-ARBITRATION] $_" } }
else {
  $caDead10u = @()
  $caShapes10u = @((Get-Command Test-ScaffoldCardArbitrationExamples).Parameters['Variant'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] } | ForEach-Object { $_.ValidValues })
  if ($caShapes10u.Count -lt 3) { Fail "gate 10u (anti-vacuous): the rejected-shape list read back from Test-ScaffoldCardArbitrationExamples' own [ValidateSet] holds $($caShapes10u.Count) name(s), fewer than the 3 this gate requires - one per anti-bypass property the entry carries (the sha binding, the two-round floor, the stated reason). Every name that came back IS exercised below, so the floor is not about the coverage of the list it read; it is that a shape the rule is expected to declare has LEFT the declaration, and a loop driven by reflection cannot notice what is no longer there to reflect. [FIX] restore the [ValidateSet] on the -Variant parameter in scripts/_cards.ps1."
  }
  foreach ($caVariant10u in $caShapes10u) {
    if (@(Test-ScaffoldCardArbitrationExamples -Variant $caVariant10u).Count -lt 1) { $caDead10u += $caVariant10u }
  }
  if ($caDead10u.Count) {
    Fail "gate 10u (anti-vacuous): rejected shape(s) '$($caDead10u -join ', ')' produced ZERO findings against the same examples, so the rule each one breaks is exercised by no case in the table. 'unbound-sha' stops checking the sha, which is the whole anti-bypass property: a ruling would then be writable against a ref, an abbreviation or nothing, and would cover every later round instead of the one verdict it names. 'first-round' drops the two-round floor, so the FIRST spec block on any Tier-S card becomes waivable - the opposite of the stop rule CLAUDE.md states. 'no-reason' accepts a waiver nobody explained. [FIX] restore the case that discriminates that shape in Test-ScaffoldCardArbitrationExamples."
  }
}
# THEN the wiring, through the real entry script on seeded cards - the half the table cannot reach. The tree
# carries check-cards.ps1 and _cards.ps1 only, exactly as 10t's off-switch tree does, so this also re-proves
# that both refusals survive in a tree with no _config.ps1 (the bad-value refusal reads the rule table, never
# the tier lists, so it must fire with tiering off).
$ccSeed10u = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cc-seed10u-$PID"
if (Test-Path $ccSeed10u) { Remove-Item -Recurse -Force $ccSeed10u }
New-Item -ItemType Directory -Force (Join-Path $ccSeed10u 'scripts') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $ccSeed10u 'specs/tasks') | Out-Null
Copy-Item (Join-Path $PSScriptRoot 'check-cards.ps1') (Join-Path $ccSeed10u 'scripts/check-cards.ps1') -Force
Copy-Item (Join-Path $PSScriptRoot '_cards.ps1') (Join-Path $ccSeed10u 'scripts/_cards.ps1') -Force
# No debt row in the title - see the FIXTURE CONVENTION note at the head of gate 10.
$mk10u = {
  param($cardId, $extra, $acceptanceItems)
  $firstAcceptance10u = '  - "A1 ' + (($acceptanceItems | Select-Object -First 1) -replace '"', '') + '"'
  (@('---', "id: $cardId", "title: seeded requirement case ($cardId)", 'status: todo',
     'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/x.ps1)) { exit 1 }"', 'dod_exit: 0',
     'allow_paths:', '  - scripts/foo.ps1') +
    @($extra) + @('review_gate: codex {verdict:pass}', 'acceptance:') +
    @($firstAcceptance10u, '  - "A2 fixture acceptance two."', '  - "A3 fixture acceptance three."') +
   @('---', '', "# seeded card ($cardId)")) -join "`n"
}
$cases10u = @(
  @{ Id = 'T9-REQ-OK'; Extra = @('requirements:', '  - R1. the guard refuses a dangling citation'); Acc = @('1. the guard refuses it. [R1]'); Block = ''
     Why = 'cites a requirement the card declares, which is the shape the field exists for' }
  @{ Id = 'T9-REQ-DANGLING'; Extra = @('requirements:', '  - R1. the guard refuses a dangling citation'); Acc = @('1. done. [R7]'); Block = 'CARD-REQ-DANGLING'; LaterPolicy = $true
     Why = 'cites [R7] while declaring only R1 - a closed-looking link that resolves to nothing' }
  @{ Id = 'T9-REQ-ABSENT'; Extra = @(); Acc = @('1. done. [dod arm 1]'); Block = ''
     Why = 'declares no requirements and cites none, which is the normal card and must stay silent' }
  @{ Id = 'T9-TIER-BADVALUE'; Extra = @('tier: 2'); Acc = @('1. done. [dod arm 1]'); Block = 'CARD-TIER-BADVALUE'
     Why = "declares 'tier: 2', a value no gate can read - governed to a human, undeclared to every gate" }
  @{ Id = 'T9-TIER-GOODVALUE'; Extra = @('tier: S'); Acc = @('1. done. [dod arm 1]'); Block = ''
     Why = "declares 'tier: S', which is legal and (with tiering off) equal to the computed tier" }
  # T285: the arbitration entry, seeded through the same entry script. The accepted case matters as much as
  # the two refused ones - a rule that rejected a well-formed ruling would make the stop rule unusable, and
  # the ship would be back to "reword the card or keep paying rounds".
  @{ Id = 'T9-ARB-OK'; Extra = @('arbitration:', '  - sha: 0123456789abcdef0123456789abcdef01234567', '    rounds: 2', '    ruling: maker', '    by: arc-owner', '    reason: the remaining asks are outside this card closed list'); Acc = @('1. done. [dod arm 1]'); Block = ''
     Why = 'records a well-formed ruling - a full lowercase sha, two rounds, a named ruler and a stated reason - which is the shape the field exists for' }
  @{ Id = 'T9-ARB-EARLY'; Extra = @('arbitration:', '  - sha: 0123456789abcdef0123456789abcdef01234567', '    rounds: 1', '    ruling: maker', '    by: arc-owner', '    reason: too early'); Acc = @('1. done. [dod arm 1]'); Block = 'CARD-ARBITRATION'; LaterPolicy = $true
     Why = 'rules after ONE round - the first block is the reviewer turn, so this is a pre-emptive waiver rather than the end of an impasse' }
  @{ Id = 'T9-ARB-UNBOUND'; Extra = @('arbitration:', '  - sha: HEAD', '    rounds: 2', '    ruling: maker', '    by: arc-owner', '    reason: bound to nothing'); Acc = @('1. done. [dod arm 1]'); Block = 'CARD-ARBITRATION'; LaterPolicy = $true
     Why = "binds its ruling to 'HEAD' instead of a reviewed sha - a blanket waiver wearing the shape of an arbitration, which is the one thing this field must never be" }
  @{ Id = 'T9-ARB-NOBODY'; Extra = @('arbitration:', '  - sha: 0123456789abcdef0123456789abcdef01234567', '    rounds: 2', '    ruling: maker', '    by: # nobody', '    reason: # omitted'); Acc = @('1. done. [dod arm 1]'); Block = 'CARD-ARBITRATION'; LaterPolicy = $true
     Why = 'fills by and reason with nothing but YAML comments - filled to a reader, empty to YAML, so the waiver is unattributed and unexplained while looking complete' }
  @{ Id = 'T9-ARB-EMPTY'; Extra = @('arbitration: maker'); Acc = @('1. done. [dod arm 1]'); Block = 'CARD-ARBITRATION'; LaterPolicy = $true
     Why = 'writes a scalar where the block list belongs, which declares a ruling to a reader and nothing at all to the ship - the in-between state a declared budget that cannot be a line count is already refused for' }
  @{ Id = 'T9-ARB-QUOTEDHASH'; Extra = @('arbitration:', '  - sha: 0123456789abcdef0123456789abcdef01234567', '    rounds: 2', '    ruling: maker', '    by: "#team"', '    reason: "#6 was rejected as out of scope"'); Acc = @('1. done. [dod arm 1]'); Block = ''
     Why = 'quotes a by and a reason that OPEN on a hash - legal YAML scalars, and a rule that unquoted before looking for a comment would call both empty and refuse a card for saying something ordinary' }
)
foreach ($c10u in $cases10u) {
  Set-Content (Join-Path $ccSeed10u "specs/tasks/$($c10u.Id).md") (& $mk10u $c10u.Id $c10u.Extra $c10u.Acc) -Encoding utf8
  $out10u = & pwsh -NoProfile -File (Join-Path $ccSeed10u 'scripts/check-cards.ps1') -TaskId $c10u.Id 2>&1 | Out-String
  $exit10u = $LASTEXITCODE
  if ($c10u.Block) {
    if ($localLegacyCardPolicy10 -and $c10u.ContainsKey('LaterPolicy') -and $c10u.LaterPolicy) {
      if ($exit10u -ne 0 -or $out10u -match "\[$($c10u.Block)\]") { Fail "gate 10u($($c10u.Id)): the preserved local policy keeps this rule advisory, but the fixture became blocking (exit=$exit10u).`nActual output: $out10u" }
      elseif (-not $fail) { Write-Host "  local compatibility 10u($($c10u.Id)) OK: later upstream policy remains non-blocking" -ForegroundColor Green }
    }
    elseif ($exit10u -eq 0) { Fail "gate 10u ($($c10u.Id)) seeded block: a card that $($c10u.Why) was ACCEPTED by check-cards.ps1 (exit 0). The rule is declared, its table is green above, and the validator never calls it - which is a function, not a guard.`nActual output: $out10u" }
    elseif ($out10u -notmatch "\[$($c10u.Block)\]") { Fail "gate 10u ($($c10u.Id)): check-cards rejected the card (exit=$exit10u) but the message carries no [$($c10u.Block)] sentinel - another rule may have caught it by coincidence, so this rule is not proven covered (L165: a bare non-zero is not evidence).`nActual output: $out10u" }
    elseif (-not $fail) { Write-Host "  seeded defect 10u($($c10u.Id)) OK: a card that $($c10u.Why) is rejected and carries the [$($c10u.Block)] sentinel" -ForegroundColor Green }
  }
  elseif ($exit10u -ne 0) {
    Fail "gate 10u ($($c10u.Id)): check-cards REJECTED a card it must accept (exit=$exit10u). This card $($c10u.Why), and a rule written to refuse a link that goes nowhere must refuse nothing else - an optional field reported on absence reds every card that predates it.`nActual output: $out10u"
  }
  elseif ($out10u -match '\[CARD-REQ-DANGLING\]|\[CARD-TIER-BADVALUE\]|\[CARD-ARBITRATION\]') {
    Fail "gate 10u ($($c10u.Id)): check-cards ACCEPTED the card but still printed one of the new sentinels, so a clean card is being told it is broken. This card $($c10u.Why).`nActual output: $out10u"
  }
  elseif (-not $fail) { Write-Host "  seeded defect 10u($($c10u.Id)) OK: accepted in silence - $($c10u.Why)" -ForegroundColor Green }
}
Remove-Item -Recurse -Force $ccSeed10u -ErrorAction SilentlyContinue
if (-not $fail) { Write-Host '  10u [CARD-REQ-DANGLING] OK (the citation and arbitration tables each driven both ways over every rejected shape their own [ValidateSet]s declare; through the real entry script a dangling citation, a bad tier value, a ruling recorded after one round and a ruling bound to no reviewed sha are each refused with their own sentinel, while a resolving citation, a card declaring neither, a legal tier value and a well-formed ruling are all accepted in silence)' -ForegroundColor Green }

# --- 11. 交叉链接完整性：agent 入口图引用的工件须存在 ---
# OpenAI《Harness Engineering》：linters verify cross-link integrity automatically。
# 校验 CLAUDE.md / AGENTS.md（agent 的入口上下文图）里引用的 docs/specs/scripts/.claude/.github 工件确实存在，
# 防「索引指向已删/改名文件」的悬空链接。占位/通配（* < > { } ..）与非入口前缀（如 backend/ 骨架示例路径）天然豁免。
Exit-Gate
}

if (Enter-Gate '11') {
Step '11/17 交叉链接完整性（CLAUDE.md / AGENTS.md / TEMPLATE-README.md / DELIVERY-CHAINS.md 引用的工件存在）'
$linkFiles = @('CLAUDE.md', 'AGENTS.md', 'TEMPLATE-README.md', 'docs/DELIVERY-CHAINS.md') | ForEach-Object { Join-Path $RepoRoot $_ } | Where-Object { Test-Path $_ }
$artifactRe = '(?<![\w./\\-])((?:docs|specs|scripts|\.claude|\.github)[\\/][\w./\\-]+\.(?:md|ps1|mjs|json|yml|yaml))'
$missing = @()
$checkedLinks = 0
foreach ($lf in $linkFiles) {
  $leaf = Split-Path $lf -Leaf
  foreach ($mm in [regex]::Matches((Get-Content $lf -Raw), $artifactRe)) {
    $p = $mm.Groups[1].Value
    if ($p -match '[*<>{}]' -or $p -match '\.\.') { continue }   # 占位/通配/相对回溯豁免
    $checkedLinks++
    if (-not (Test-Path (Join-Path $RepoRoot $p))) { $missing += "$leaf → $p" }   # 正斜杠跨 OS（同闸⑨）：不再 '/'→'\'，Linux 兼容
  }
}
if ($missing) { $missing | Sort-Object -Unique | ForEach-Object { Fail "悬空链接：$_（入口图引用的工件不存在；改名/删除后请同步 CLAUDE.md/AGENTS.md）" } }
elseif ($linkFiles.Count -eq 0) { Write-Host '  无 CLAUDE.md / AGENTS.md，跳过。' -ForegroundColor DarkGray }
else { Write-Host "  入口图交叉链接完整（核验 $checkedLinks 处引用，无悬空）" }

# 11b. 下游文档触发语 + tier-routing 钩子可见性（TD61/TD-124）：`route-new-work` 是 UserPromptSubmit 钩子、
# 只按启动触发语「根据脚手架」的正则命中才启动 tier-routing（TD19/PR#40 已实现该能力），但下游文档
# （CLAUDE.template.md 索引 / TEMPLATE-README.md 能力表+目录速览）从未提过这句触发语或这个钩子——
# 能力对下游休眠，违反「能力变→同步 TEMPLATE-README/CLAUDE.template 索引」规则。断言两份下游文档都提及
# 触发语与钩子名，且 TEMPLATE-README 目录速览的钩子枚举行（settings.json 那行）把 UserPromptSubmit 与其余
# 三类钩子绑定（PreToolUse/Stop/SessionStart）并列列出。
$ctPath = Join-Path $RepoRoot 'CLAUDE.template.md'
$trPath = Join-Path $RepoRoot 'TEMPLATE-README.md'
if (-not (Test-Path $ctPath)) { Write-Host '  CLAUDE.template.md 不存在（已初始化下游），11b 跳过。' -ForegroundColor DarkGray }
elseif (-not (Test-Path $trPath)) { Fail 'TEMPLATE-README.md 不存在（下游 on-ramp 缺失）。' }
else {
  $ctRaw = Get-Content $ctPath -Raw
  $trRaw = Get-Content $trPath -Raw
  if ($ctRaw -notmatch '根据脚手架') { Fail 'CLAUDE.template.md 未提启动触发语「根据脚手架」——下游 agent 不知道怎么触发 tier-routing（TD61）。' }
  elseif ($ctRaw -notmatch 'UserPromptSubmit' -or $ctRaw -notmatch 'route-new-work') { Fail 'CLAUDE.template.md 未提 UserPromptSubmit / route-new-work 钩子（TD61：tier-routing 能力对下游休眠）。' }
  elseif ($trRaw -notmatch '根据脚手架') { Fail 'TEMPLATE-README.md 未提启动触发语「根据脚手架」（TD61）。' }
  elseif ($trRaw -notmatch 'UserPromptSubmit' -or $trRaw -notmatch 'route-new-work') { Fail 'TEMPLATE-README.md 未提 UserPromptSubmit / route-new-work 钩子（TD61）。' }
  else {
    $hookLine = ($trRaw -split "`r?`n") | Where-Object { $_ -match 'PreToolUse\(guard-frozen\)' } | Select-Object -First 1
    if (-not $hookLine) { Fail 'TEMPLATE-README.md 目录速览未见 settings.json 钩子枚举行（PreToolUse(guard-frozen) 锚点缺失，改动过大？）。' }
    elseif ($hookLine -notmatch 'UserPromptSubmit') { Fail "TEMPLATE-README.md 钩子枚举行漏 UserPromptSubmit(route-new-work)：`n  $hookLine" }
    else { Write-Host '  11b 下游文档触发语 + tier-routing 钩子可见性 OK（CLAUDE.template.md / TEMPLATE-README.md 均提及，钩子枚举行完整）' }
  }
}

# --- 12. 心跳冒烟：triage.ps1 scan -NoWrite 在默认配置下干跑无异常、退出 0 ---
# loop-engineering 的「心跳」是 reporter 非闸门：它必须在任何配置下都能干跑且不阻断（exit 0）。
# 此处核验它解析各子系统信号时不抛异常（-NoWrite 不落收件箱，避免污染工作区）。
Exit-Gate
}

if (Enter-Gate '12') {
Step '12/17 心跳冒烟（triage.ps1 scan -NoWrite + selfcheck + scaffold-sync selfcheck）'
# Gate 12 executes production reporters and archive/lessons commands whose script-location fallback is the
# repository root.  A `-RepoRoot` argument on only the apparent write calls is not sufficient: an omitted
# path in a nested subprocess previously selected this worktree and archived L1 during an R3 diagnostic run.
# Give every Gate-12 production invocation one disposable, complete-enough repository root instead.  The
# source bytes are copied from this candidate; only its state is disposable.  Android is intentionally not
# copied: no Gate-12 probe reads it, and Android-specific regression coverage remains in its own gate.
$g12ProtectedRel = @('docs/lessons/LEDGER.md', 'specs/archive/lessons-archive.md')
$g12Before = @{}
foreach ($g12Rel in $g12ProtectedRel) {
  $g12Path = Join-Path $RepoRoot $g12Rel
  $g12Before[$g12Rel] = if (Test-Path -LiteralPath $g12Path -PathType Leaf) { (Get-FileHash -LiteralPath $g12Path -Algorithm SHA256).Hash } else { '<missing>' }
}
$fixtureRepoRoot = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-g12-repo-$PID-$([guid]::NewGuid().ToString('N'))"
New-Item -ItemType Directory -Force $fixtureRepoRoot | Out-Null
foreach ($g12Item in @('scripts', '.claude', 'docs', 'specs', 'configs', 'CLAUDE.md', 'CLAUDE.template.md', 'README.md', 'CHANGELOG.md', '.gitignore')) {
  $g12Source = Join-Path $RepoRoot $g12Item
  if (Test-Path -LiteralPath $g12Source) { Copy-Item -LiteralPath $g12Source -Destination $fixtureRepoRoot -Recurse -Force }
}
$triagePath = Join-Path $fixtureRepoRoot 'scripts/triage.ps1'
if (-not (Test-Path $triagePath)) { Fail 'scripts\triage.ps1 不存在（loop-engineering 心跳缺失）。' }
else {
  & pwsh -NoProfile -File $triagePath scan -NoWrite -Quiet *> $null
  if ($LASTEXITCODE -ne 0) { Fail "triage.ps1 干跑非零退出（$LASTEXITCODE）——心跳应恒 0（reporter 非闸门）。" }
  else { Write-Host '  心跳干跑 OK（exit 0，未写收件箱）' }
}
# 12b. probe-8 fail-safe 回归守卫（TD9 + 两轮 max-effort review）：空账本走不到读循环、E2E ship 写隔离 worktree 的 _local，故此读路径无覆盖。
# **hermetic**：用 $env:SCAFFOLD_EFFECTIVENESS_LEDGER 注入隔离临时账本，绝不碰生产 _local 文件（治「seed 生产路径」与并发 ship/残留行串扰致假失败）。
# seed **坏行 + 好行**混合，断言探针 (1) 不崩（exit 0、心跳恒 0 契约）、(2) 正确数各闸拦截。坏行覆盖 null/裸标量/空对象/
# 非法 JSON/**单元素数组**——专测 strict-mode 非对象属性访问坑 + 管道把 [{…}] 解包误计（原 12b 只 seed 好行、假绿）。
$tmpLedger = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-selftest-eff-$PID.jsonl"
$env:SCAFFOLD_EFFECTIVENESS_LEDGER = $tmpLedger
try {
  @(
    '{"ts":"t","gate":"dod","task":"X","detail":"d"}'   # 好行：1 次 dod 拦截
    'null'                                              # 坏行：JSON null（非对象）
    '42'                                                # 坏行：裸标量
    '{}'                                                # 坏行：空对象（无 gate 字段）
    '[{"gate":"dod"}]'                                  # 坏行：单元素数组（管道解包陷阱，须**不**计入 dod）
    '{not valid json'                                   # 坏行：非法 JSON
    '{"ts":"t","gate":"secrets","task":"Y"}'            # 好行：1 次 secrets 拦截
  ) | Set-Content -Path $tmpLedger -Encoding utf8
  $effOut = & pwsh -NoProfile -File $triagePath scan -NoWrite 2>&1 | Out-String
  if ($LASTEXITCODE -ne 0) { Fail "probe-8 在坏行账本上崩了（exit $LASTEXITCODE）——心跳须恒 0、坏行须跳过：`n$effOut" }
  elseif (($effOut -notmatch 'dod:1\b') -or ($effOut -notmatch 'secrets:1\b')) { Fail "probe-8 拦截计数异常（期望 dod:1 secrets:1：坏行+单元素数组均须跳过、不得 dod:2）：`n$effOut" }
  else { Write-Host '  probe-8 fail-safe OK（坏行 null/标量/空对象/数组/非法JSON 跳过、dod:1 secrets:1、exit 0）' }
} finally {
  Remove-Item $tmpLedger -Force -ErrorAction SilentlyContinue
  Remove-Item Env:SCAFFOLD_EFFECTIVENESS_LEDGER -ErrorAction SilentlyContinue
}
# 12c. triage selfcheck 常设接线（TD23）：PR #26 引入的 hermetic 探针自测（探针 4 跨 worktree，临时夹具）
#   此前「可跑不被跑」；接进常设闸使改探针即回归。triage 退出码恒 0（reporter 契约），故同 12b 只断言输出——
#   且钉**末行**（selfcheck 的 PASS/FAIL 总结行恒为最后输出）：防「输出里早处出现 PASS、随后才报错」的假绿。
$selfcheckOut = & pwsh -NoProfile -File $triagePath selfcheck 2>&1 | Out-String
$selfcheckLines = @($selfcheckOut -split "`r?`n" | ForEach-Object { ($_ -replace "`e\[[0-9;]*m", '').Trim() } | Where-Object { $_ -ne '' })   # 去 ANSI 色码 + 空行（防终端差异）
$selfcheckLast = if ($selfcheckLines.Count) { $selfcheckLines[-1] } else { '' }
if ($selfcheckLast -notmatch '^triage selfcheck: PASS') { Fail "triage selfcheck 未过（期望末行为 'triage selfcheck: PASS…'，实际末行「$selfcheckLast」）：`n$selfcheckOut" }
else { Write-Host '  triage selfcheck OK（探针 4 hermetic 自检：末行 PASS）' }

# 12f. scaffold-sync selfcheck 常设接线（T84）：the fleet-loop version logic (release-tag parse, newer-set,
#   CHANGELOG downstream-block cut, ledger high-water mark) is what decides whether a downstream is told it is
#   behind. Wrong there fails **silently and reassuringly** - a project is told it is up to date when it is not -
#   so the hermetic selfcheck is wired here rather than left runnable-but-never-run (same reasoning as 12c).
#   Pinned to the **last** line for the same reason as 12c: an early PASS followed by a later error must not read green.
$syncPath = Join-Path $fixtureRepoRoot 'scripts/scaffold-sync.ps1'
if (-not (Test-Path $syncPath)) { Fail 'scripts\scaffold-sync.ps1 不存在（fleet 双向回路的入口缺失）。' }
else {
  $syncOut = & pwsh -NoProfile -File $syncPath selfcheck 2>&1 | Out-String
  $syncLines = @($syncOut -split "`r?`n" | ForEach-Object { ($_ -replace "`e\[[0-9;]*m", '').Trim() } | Where-Object { $_ -ne '' })
  $syncLast = if ($syncLines.Count) { $syncLines[-1] } else { '' }
  if ($syncLast -notmatch '^scaffold-sync selfcheck: PASS') { Fail "scaffold-sync selfcheck 未过（期望末行为 'scaffold-sync selfcheck: PASS…'，实际末行「$syncLast」）：`n$syncOut" }
  else { Write-Host '  scaffold-sync selfcheck OK（fleet 回路版本逻辑 hermetic 自检：末行 PASS）' }
}

# 12d. tech-debt 探针（探针2）位置解析硬化（TD57/TD-120）：旧码硬编码 `$cells[5]` 为状态列、且用朴素
#   `.Split('|')` 分列——单元格内出现字面竖线（如位置列 backtick 代码片段里的正则析取 `a\|b`）会
#   把该行错位一列，`状态` 落进错误单元格，`open` 债项静默从收件箱消失（生产 TD46/TD49 行已真实携带
#   此形态）。同时旧码 `-eq 'open'` 精确匹配漏判 `Open`/`open (partial)` 等大小写与后缀变体。
#   夹具建独立临时 specs/tech-debt-tracker.md（表头 7 列 + 分隔行 + 示例行 + 三条数据行）：
#     TDX1 位置列含转义竖线 `\|`（转义感知分列后仍是 7 列，旧朴素分列会错位成 8 列）
#     TDX2 状态='Open'（大写变体）  TDX3 状态='open (partial)'（后缀变体）
#   断言：scan -NoWrite 输出须同时含 TDX1/TDX2/TDX3 三条 tech-debt-open 发现（旧码三者皆漏判 → RED）。
$td12 = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-triage-td12d-$PID"
if (Test-Path $td12) { Remove-Item -Recurse -Force $td12 }
New-Item -ItemType Directory -Force (Join-Path $td12 'scripts') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $td12 'specs') | Out-Null
Copy-Item $triagePath (Join-Path $td12 'scripts/triage.ps1') -Force
# Every library triage.ps1 dot-sources unguarded must travel with it, or the fixture run dies in the
# preamble and every probe reads as "missed the finding" - which is a fixture defect wearing a probe
# defect's failure text. _lessons.ps1 joined that set with the shared Tier-1 cap core (issue #184).
# T104 lived that failure once: a new unguarded dot-source of _guard.ps1 took 12d down exactly this way.
# Two fixes, both kept - triage.ps1 now SOFT-loads _guard.ps1 (reporter contract: never die on load), and
# it still travels here, because a library that is merely soft-loaded would otherwise leave its probe
# permanently no-op inside the fixture and any future regression in it would read green.
Copy-Item (Join-Path $fixtureRepoRoot 'scripts/_cards.ps1') (Join-Path $td12 'scripts/_cards.ps1') -Force
Copy-Item (Join-Path $fixtureRepoRoot 'scripts/_lessons.ps1') (Join-Path $td12 'scripts/_lessons.ps1') -Force
Copy-Item (Join-Path $fixtureRepoRoot 'scripts/_guard.ps1') (Join-Path $td12 'scripts/_guard.ps1') -Force
Copy-Item (Join-Path $fixtureRepoRoot 'scripts/_config.ps1') (Join-Path $td12 'scripts/_config.ps1') -Force
$tdFixture = @(
  '# Fixture 技术债追踪器（选顶 12d · TD57/TD-120 种子缺陷）', '',
  '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |',
  '|---|---|---|---|---|---|---|',
  '| _示例_ | 2026-06-15 | `x/y` | 示例行须被跳过 | major | open | — |',
  '| TDX1 | 2026-07-08 | `scripts/foo.ps1`(a\|b 正则析取) | 位置列含转义竖线，朴素分列会错位一列 | major | open | — |',
  '| TDX2 | 2026-07-08 | `scripts/bar.ps1` | 状态大写变体 | minor | Open | — |',
  '| TDX3 | 2026-07-08 | `scripts/baz.ps1` | 状态含后缀变体 | minor | open (partial) | — |'
) -join "`n"
Set-Content (Join-Path $td12 'specs/tech-debt-tracker.md') $tdFixture -Encoding utf8
$td12Out = & pwsh -NoProfile -File (Join-Path $td12 'scripts/triage.ps1') scan -NoWrite 2>&1 | Out-String
Remove-Item -Recurse -Force $td12 -ErrorAction SilentlyContinue
# 断言只认 ASCII 的 id 字面量（TDX1/2/3），不比对相邻中文短语——中文经跨子进程管道捕获在
# 非 UTF-8 主机 console 下可能乱码（同 TD31/TD34），ASCII 字节跨代码页恒等、免这坑（同 12b 的 dod:1 手法）。
$td12Missing = @(@('TDX1', 'TDX2', 'TDX3') | Where-Object { -not $td12Out.Contains($_) })
if ($td12Missing.Count) {
  Fail "种子缺陷 12d：tech-debt 探针漏判 $($td12Missing -join ', ')——位置列含转义竖线致朴素分列错位 / 状态大小写或后缀变体未识别（TD57/TD-120）。`n实际输出：$td12Out"
} else {
  Write-Host '  12d tech-debt 探针 OK（转义竖线不致错位 · 状态列表头动态定位 · Open/open (partial) 变体均识别）' -ForegroundColor Green
}

# 12e. archive.ps1 冷存压缩（TD86/T28）hermetic 闸：seed 混合状态的 tracker + 卡，跑生产 archive.ps1（-RepoRoot 指夹具，
#   绝不动元仓），断言：(1) 热/冷分区——paid/accepted 债行 + merged 卡搬走，open/carded/示例/todo 留活文件；
#   (1b) 同 id 不同内容两行都保全（防按 id 去重致静默数据丢失，fresh-context 审计 #1）；(2) 精简索引条数 == 归档条数
#   （期望值从夹具声明的冷行派生，不写死字面量）；(7) 索引恒等于生成器投影——手写标题/手改计数即红（见该段头注）；
#   (2b) 索引头注反引号指针未被转义吞掉（审计 #2）；(3) _TEMPLATE.md 不被误归档；(4) 幂等——再跑分区与索引不变。
#   转义竖线行（位置列 `a\|b`）验证状态列不被朴素分列错位而误分类。断言只认 ASCII id（TDX*/TA*），避开 CJK 跨子进程乱码坑（同 12b/12d）。
#   T40-LEDGERARCH（(5)，R3 F4 加固版）：同一夹具再加 lessons 账本冷存子夹具——种 4 条目 fixture LEDGER
#   （L1/L2/L3/L4，L4 最高），真跑生产 archive.ps1 -LessonIds 驱动，断言①②逗号形式（单 token，模拟外部进程真实
#   调用，F1）精确文本搬运（LEDGER 全文精确相等 + 归档含逐字拼接块，非子串）③幂等 ④拒搬最高 id（捕获告警含
#   ASCII 码 [ARCHIVE-LESSON-MAXID]）⑤拒不存在 id（含 [ARCHIVE-LESSON-UNKNOWN-ID]）⑥DryRun 亦 fail-closed（F2）⑦暂存原子替换——注入归档暂存写失败，
#   LEDGER 与既有归档双侧逐字零丢失（F3+F5）⑧空 token/显式空串 fail-closed（F8/F10 参数在场性判定）⑨LEDGER 替换
#   失败注入 + 两侧并存自愈（F7）⑩两侧并存内容不一致 → 拒绝自愈、双侧不动（F9）；⑥b 合法 DryRun exit 0 且零写盘；
#   ⑪前导零别名（L04）校验层拒绝——Id 逐字串匹配、Number 只作最高 id 数值比较（F11）；⑫ T74 selector
#   （lessons.ps1 archive，独立 mini-repo）：只选 tier=ledger+recurrence=1、放过 max-id 与 resident-referenced
#   （CLAUDE.md/template 引用的 id 留热）、DryRun 只读、幂等、归档后 search 以 [archived] 标签命中。
$ar = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-archive-12e-$PID"
if (Test-Path $ar) { Remove-Item -Recurse -Force $ar }
New-Item -ItemType Directory -Force (Join-Path $ar 'specs/tasks') | Out-Null
$arFixture = @(
  '# Fixture 技术债追踪器（12e · archive.ps1 冷存分区）', '',
  '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |',
  '|---|---|---|---|---|---|---|',
  '| _示例_ | 2026-06-15 | `x/y` | 示例行须留活表 | major | open | — |',
  '| TDX1 | 2026-07-08 | `scripts/foo.ps1`(a\|b 正则) | 位置列含转义竖线，paid 须搬走 | major | paid | PR #1 |',
  '| TDX2 | 2026-07-08 | `scripts/bar.ps1` | open 须留活表 | minor | open | — |',
  '| TDX3 | 2026-07-08 | `scripts/baz.ps1` | accepted 须搬走 | minor | accepted | ADR 0009 |',
  '| TDX4 | 2026-07-08 | `scripts/qux.ps1` | carded 须留活表 | minor | carded | 卡 TX-FOO |',
  '| TDX5 | 2026-07-08 | `scripts/dup.ps1` | 同 id 首行 DUPA，paid 须搬 | minor | paid | PR DUPA |',
  '| TDX5 | 2026-07-08 | `scripts/dup.ps1` | 同 id 次行 DUPB，paid 须搬（不得被 id 去重吞掉，审计 #1） | minor | paid | PR DUPB |'
) -join "`n"
Set-Content (Join-Path $ar 'specs/tech-debt-tracker.md') $arFixture -Encoding utf8
Set-Content (Join-Path $ar 'specs/tasks/TA1.md') "---`nid: TA1`ntitle: merged one`nstatus: merged`n---" -Encoding utf8
Set-Content (Join-Path $ar 'specs/tasks/TA2.md') "---`nid: TA2`ntitle: todo two`nstatus: todo`n---" -Encoding utf8
Set-Content (Join-Path $ar 'specs/tasks/TA3.md') "---`nid: TA3`ntitle: merged three`nstatus: merged`n---" -Encoding utf8
Set-Content (Join-Path $ar 'specs/tasks/_TEMPLATE.md') "---`nid: T?-EXAMPLE`nstatus: merged`n---" -Encoding utf8   # 名字豁免：即便 merged 也不该被归档
# T107/L238：TA4 = merged 但 worktree 仍在磁盘上 → 须被【拒搬】。目录真建在夹具里，故本闸仍是 hermetic 的；
#   TA5 = merged 且 worktree 指向不存在的路径 → 须照常搬走（证拒搬判据是「目录在不在」，不是「有没有写 worktree 字段」）。
#   既有 TA1/TA2/TA3 不带 worktree 字段，判据对它们恒为「可搬」，故上面每一条既有断言的裁决逐字不变。
$arHeldWt = Join-Path $ar 'wt/TA4'
New-Item -ItemType Directory -Force $arHeldWt | Out-Null
Set-Content (Join-Path $ar 'specs/tasks/TA4.md') "---`nid: TA4`ntitle: merged but worktree still on disk`nstatus: merged`nworktree: $arHeldWt`n---" -Encoding utf8
Set-Content (Join-Path $ar 'specs/tasks/TA5.md') "---`nid: TA5`ntitle: merged with a dead worktree path`nstatus: merged`nworktree: $(Join-Path $ar 'wt/TA5-gone')`n---" -Encoding utf8
# T40-LEDGERARCH：lessons 账本冷存子夹具——同一隔离夹具内种 4 条目 fixture LEDGER（L1/L2/L3/L4，L4 为当前最高 id）。
# 每条块内容存成数组变量：下方断言用同一批变量拼「预期结果」文本，不重打内容（R3 F4 item2，防誊抄误差）。
New-Item -ItemType Directory -Force (Join-Path $ar 'docs/lessons') | Out-Null
$lsL1 = @('## L1', '- date: 2026-07-01', '- symptom: 示例症状一（须留在活账本，与逗号形式移动测试无关）', '- rule: 示例规则一')
$lsL2 = @('## L2', '- date: 2026-07-02', '- symptom: 示例症状二（经逗号形式 -LessonIds L2,L3 与 L3 一起搬走）', '- rule: 示例规则二')
$lsL3 = @('## L3', '- date: 2026-07-03', '- symptom: 示例症状三（经逗号形式 -LessonIds L2,L3 与 L2 一起搬走）', '- rule: 示例规则三')
$lsL4 = @('## L4', '- date: 2026-07-04', '- symptom: 示例症状四（当前最高 id，须被拒搬）', '- rule: 示例规则四')
$lsHeaderLine = '# Fixture LEDGER（12e lessons 子夹具 · T40-LEDGERARCH）'
$lsFixtureText = ((@($lsHeaderLine, '') + $lsL1 + @('') + $lsL2 + @('') + $lsL3 + @('') + $lsL4)) -join "`n"
Set-Content (Join-Path $ar 'docs/lessons/LEDGER.md') $lsFixtureText -Encoding utf8
$arScript = Join-Path $fixtureRepoRoot 'scripts/archive.ps1'
if (-not (Test-Path $arScript)) { Fail '12e：scripts\archive.ps1 不存在（冷存压缩引擎缺失，TD86/T28 未落地）。' }
else {
  $arOut = & pwsh -NoProfile -File $arScript -RepoRoot $ar -Quiet 2>&1 | Out-String   # T107: 输出要断言 [ARCHIVE-HELD]
  $arCode = $LASTEXITCODE
  $liveTd = if (Test-Path (Join-Path $ar 'specs/tech-debt-tracker.md')) { Get-Content (Join-Path $ar 'specs/tech-debt-tracker.md') -Raw } else { '' }
  $archTd = if (Test-Path (Join-Path $ar 'specs/archive/tech-debt-archive.md')) { Get-Content (Join-Path $ar 'specs/archive/tech-debt-archive.md') -Raw } else { '' }
  $idxTd  = if (Test-Path (Join-Path $ar 'specs/archive/tech-debt-index.md')) { @(Get-Content (Join-Path $ar 'specs/archive/tech-debt-index.md') | Where-Object { $_ -match '^\|\s*TDX' }) } else { @() }
  $cardsIdx = if (Test-Path (Join-Path $ar 'specs/archive/cards-index.md')) { Get-Content (Join-Path $ar 'specs/archive/cards-index.md') -Raw } else { '' }
  $arFail = @()
  if ($arCode -ne 0) { $arFail += "archive.ps1 非零退出（$arCode）" }
  # (1) 热/冷分区
  if ($liveTd -match 'TDX1' -or $liveTd -match 'TDX3' -or $liveTd -match 'TDX5') { $arFail += '活追踪器仍含已闭合行 TDX1/TDX3/TDX5（paid/accepted 未搬走——含转义竖线行状态列错位？）' }
  if ($liveTd -notmatch 'TDX2' -or $liveTd -notmatch 'TDX4' -or $liveTd -notmatch '示例') { $arFail += '活追踪器丢了在飞行 TDX2(open)/TDX4(carded)/示例（保守留存被破坏）' }
  if ($archTd -notmatch 'TDX1' -or $archTd -notmatch 'TDX3') { $arFail += '归档缺 TDX1/TDX3（冷行未落归档）' }
  # (1b) 同 id 不同内容两行都须保全——按 id 去重会吞掉 DUPB = 静默数据丢失（fresh-context 审计 #1）
  if ($archTd -notmatch 'DUPA' -or $archTd -notmatch 'DUPB') { $arFail += '同 id（TDX5）两条相异行未都进归档（DUPA/DUPB 缺一）——按 id 去重致数据丢失（审计 #1）' }
  # (2) 索引条数 == 归档条数。The expected count is DERIVED from the seed rows this fixture declares cold
  #     (status cell exactly paid|accepted), never typed as a literal: a hand-written expectation rots the
  #     moment a fixture row is added, and it is the very hand-written-count defect (7) exists to catch,
  #     one layer up in the checker itself. Anchored on the trailing `| <status> | <pointer> |` shape so
  #     TDX1's escaped pipe cannot shift the column the way a naive split would.
  $arExpectCold = @($arFixture -split "`n" | Where-Object { $_ -match '^\|\s*TDX' -and $_ -match '\|\s*(paid|accepted)\s*\|[^|]*\|\s*$' }).Count
  if ($arExpectCold -lt 1) { $arFail += '12e(2)：夹具未声明任何 paid/accepted 冷行——期望值派生失效，断言会变空转' }
  if ($idxTd.Count -ne $arExpectCold) { $arFail += "精简索引数据行 $($idxTd.Count) ≠ 夹具声明的冷行 $arExpectCold 条（索引投影漏/多）" }
  # (2b) 索引头注的反引号代码跨未被当转义吞掉：文件名须原样在场（审计 #2：双引号里 `t 被当 TAB → ech-debt-archive.md）
  $idxRaw = if (Test-Path (Join-Path $ar 'specs/archive/tech-debt-index.md')) { Get-Content (Join-Path $ar 'specs/archive/tech-debt-index.md') -Raw } else { '' }
  if ($idxRaw -notmatch 'tech-debt-archive\.md') { $arFail += '索引头注 `tech-debt-archive.md` 指针被转义吞掉（审计 #2：双引号 `t → TAB）' }
  # (3) 卡分区 + 模板豁免
  if (-not (Test-Path (Join-Path $ar 'specs/archive/tasks/TA1.md')) -or -not (Test-Path (Join-Path $ar 'specs/archive/tasks/TA3.md'))) { $arFail += 'merged 卡 TA1/TA3 未移入 specs/archive/tasks/' }
  if (-not (Test-Path (Join-Path $ar 'specs/tasks/TA2.md'))) { $arFail += 'todo 卡 TA2 被误归档（应留活目录）' }
  if (-not (Test-Path (Join-Path $ar 'specs/tasks/_TEMPLATE.md')) -or (Test-Path (Join-Path $ar 'specs/archive/tasks/_TEMPLATE.md'))) { $arFail += '_TEMPLATE.md 被误归档（名字豁免失效）' }
  if ($cardsIdx -notmatch 'TA1' -or $cardsIdx -notmatch 'TA3' -or $cardsIdx -match 'TA2') { $arFail += '卡索引内容错（应含 TA1/TA3、不含 TA2）' }
  # (3b) T107/L238：worktree 未拆的 merged 卡须被拒搬、被点名、并给出 cleanup 而非「再跑一次冷存」的下一步。
  if (Test-Path (Join-Path $ar 'specs/archive/tasks/TA4.md')) { $arFail += '12e(3b)：TA4（merged 但 worktree 仍在磁盘上）被搬进冷存——挂着 worktree 的卡还没办完，归档它等于把一棵孤儿工作树当成已完成收进冷存、并掩盖 triage 探针 9/11 该报的东西（T107/L238；T293 起 cleanup 不再依赖卡，故这里不再是「保住前置条件」）。' }
  if (-not (Test-Path (Join-Path $ar 'specs/tasks/TA4.md'))) { $arFail += '12e(3b)：TA4 既没进冷存也不在活目录——拒搬不等于删除，卡必须原地留着等 cleanup。' }
  if (-not (Test-Path (Join-Path $ar 'specs/archive/tasks/TA5.md'))) { $arFail += '12e(3b)：TA5（merged，worktree 路径不存在）未被搬走——拒搬判据被写成「有没有 worktree 字段」而非「那个目录在不在」，于是每张写了 worktree 的卡都永远搬不走。' }
  if ($cardsIdx -match 'TA4') { $arFail += '12e(3b)：卡索引含 TA4——被拒搬的卡不得进索引投影（索引只投影真正到达 specs/archive/ 的卡）。' }
  if ($arOut -notmatch 'ARCHIVE-HELD') { $arFail += "12e(3b)：拒搬未打印哨兵 [ARCHIVE-HELD]——静默拒搬比拒搬更糟：调用方看到「保留 N 张」却不知其中一张是被挡下的。`n输出=$arOut" }
  if ($arOut -notmatch 'TA4') { $arFail += "12e(3b)：拒搬信息未点名 TA4——必须说清是哪张卡挡住了，否则调用方只能逐卡猜。`n输出=$arOut" }
  if ($arOut -notmatch 'Phase cleanup') { $arFail += "12e(3b)：拒搬信息未给出 -Phase cleanup 这个下一步——「再跑一次冷存清扫」是错的建议（再跑仍不会搬它），会让调用方原地打转（T107/L238）。`n输出=$arOut" }
  # (4) 幂等：再跑一次，分区与索引不得变
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -Quiet *> $null
  $liveTd2 = Get-Content (Join-Path $ar 'specs/tech-debt-tracker.md') -Raw
  $idxTd2  = @(Get-Content (Join-Path $ar 'specs/archive/tech-debt-index.md') | Where-Object { $_ -match '^\|\s*TDX' })
  if ($liveTd2 -match 'TDX1' -or $idxTd2.Count -ne $arExpectCold -or -not (Test-Path (Join-Path $ar 'specs/tasks/TA2.md'))) { $arFail += "非幂等：二次运行改变了分区/索引（活表 TDX1 在场=$([bool]($liveTd2 -match 'TDX1')) · 索引 $($idxTd2.Count) 条 vs 期望 $arExpectCold · TA2 仍在活目录=$(Test-Path (Join-Path $ar 'specs/tasks/TA2.md'))）" }

  # (5) T40-LEDGERARCH：lessons 账本冷存子夹具（R3 F4 加固版）——同一隔离夹具，真跑生产 archive.ps1 -LessonIds，
  #     既有 (1)-(4) tracker/cards 断言面在上方一字未动；本段独立正交，只加不改。
  $lsLedgerPath = Join-Path $ar 'docs/lessons/LEDGER.md'
  $lsArchivePath = Join-Path $ar 'specs/archive/lessons-archive.md'
  # 规范化：CRLF→LF、去尾换行——精确文本比对不受平台换行差异/文件尾换行有无影响。
  $lsNormalize = { param([string]$s) ($s -replace "`r`n", "`n").TrimEnd("`n") }

  # ①② 逗号形式（单 token `-LessonIds L2,L3`，模拟外部进程真实调用形态——pwsh -File 不做逗号数组自动
  #    拆分，验证 F1 修复）：精确文本断言而非子串——LEDGER 去掉 L2/L3 两块后须与预期**全文精确相等**
  #    （规范化换行后比对）；归档须含 L2+L3 的逐字拼接块（预期串由同一批 seed 变量拼出，不重打内容）。
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds 'L2,L3' -Quiet *> $null
  $lsCode1 = $LASTEXITCODE
  $lsLedgerRaw1 = if (Test-Path $lsLedgerPath) { Get-Content $lsLedgerPath -Raw } else { '' }
  $lsArchRaw1 = if (Test-Path $lsArchivePath) { Get-Content $lsArchivePath -Raw } else { '' }
  $lsLedgerNorm1 = & $lsNormalize $lsLedgerRaw1
  $lsArchNorm1 = & $lsNormalize $lsArchRaw1
  $lsExpectedRemainText = ((@($lsHeaderLine, '') + $lsL1 + @('') + $lsL4)) -join "`n"
  $lsExpectedArchBodyText = (($lsL2 + @('') + $lsL3)) -join "`n"
  if ($lsCode1 -ne 0) { $arFail += "12e lessons：逗号形式 -LessonIds L2,L3 非零退出（$lsCode1，F1 未修复？）" }
  if ($lsLedgerNorm1 -ne $lsExpectedRemainText) { $arFail += "12e lessons①：逗号形式搬运后 LEDGER 与预期未精确相等（F1 逗号拆分或搬运逻辑有偏差）。实际=[$lsLedgerNorm1] 预期=[$lsExpectedRemainText]" }
  if (-not $lsArchNorm1.Contains($lsExpectedArchBodyText)) { $arFail += "12e lessons②：归档未含 L2+L3 的逐字拼接块（逗号形式未双双搬入）。归档=[$lsArchNorm1]" }

  # ③ 幂等：同参（仍逗号形式）重跑 → 0 搬，归档 L2/L3 标题各恰一份，LEDGER 精确不变。
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds 'L2,L3' -Quiet *> $null
  $lsCode3 = $LASTEXITCODE
  $lsLedgerRaw3 = Get-Content $lsLedgerPath -Raw
  $lsArchRaw3 = Get-Content $lsArchivePath -Raw
  $lsL2HeadCount = ([regex]::Matches($lsArchRaw3, '(?m)^##\s+L2\s*$')).Count
  $lsL3HeadCount = ([regex]::Matches($lsArchRaw3, '(?m)^##\s+L3\s*$')).Count
  if ($lsCode3 -ne 0) { $arFail += "12e lessons③：幂等重跑非零退出（$lsCode3）" }
  if ($lsL2HeadCount -ne 1 -or $lsL3HeadCount -ne 1) { $arFail += "12e lessons③：非幂等——归档 L2/L3 标题各出现 $lsL2HeadCount/$lsL3HeadCount 次（应各恰 1 次）" }
  if ((& $lsNormalize $lsLedgerRaw3) -ne $lsExpectedRemainText) { $arFail += '12e lessons③：非幂等——重跑改变了 LEDGER 内容' }

  # ④ 拒搬最高 id（L4，4 条目夹具下的最高）：LEDGER 仍含 L4；捕获合并输出须见「拒绝」字样；非零退出。
  $lsOut4 = & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds L4 -Quiet 2>&1 | Out-String
  $lsCode4 = $LASTEXITCODE
  $lsLedgerRaw4 = Get-Content $lsLedgerPath -Raw
  if ($lsCode4 -eq 0) { $arFail += '12e lessons④：拒搬最高 id（L4）未反映为非零退出' }
  if ($lsLedgerRaw4 -notmatch '## L4') { $arFail += '12e lessons④：最高 id L4 被错误搬走（应被拒绝、留在 LEDGER）' }
  if ($lsOut4 -notmatch '\[ARCHIVE-LESSON-MAXID\]') { $arFail += "12e lessons④：拒最高 id 的捕获输出未命中 ASCII 哨兵 [ARCHIVE-LESSON-MAXID]（L165）。输出=[$lsOut4]" }

  # ⑤ 拒不存在 id（L999）：捕获合并输出须见「未知」字样；非零退出（fail-closed，防手滑打错 id）。
  $lsOut5 = & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds L999 -Quiet 2>&1 | Out-String
  $lsCode5 = $LASTEXITCODE
  if ($lsCode5 -eq 0) { $arFail += '12e lessons⑤：未知 id（L999）未非零退出（fail-closed 失效）' }
  if ($lsOut5 -notmatch '\[ARCHIVE-LESSON-UNKNOWN-ID\]') { $arFail += "12e lessons⑤：未知 id 的捕获输出未命中 ASCII 哨兵 [ARCHIVE-LESSON-UNKNOWN-ID]（L165）。输出=[$lsOut5]" }

  # ⑥ DryRun 亦 fail-closed（F2）：`-DryRun -LessonIds L999` 须非零退出，且不写任何文件（LEDGER 原样不动）。
  $lsLedgerBefore6 = Get-Content $lsLedgerPath -Raw
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -DryRun -LessonIds L999 -Quiet *> $null
  $lsCode6 = $LASTEXITCODE
  $lsLedgerAfter6 = Get-Content $lsLedgerPath -Raw
  if ($lsCode6 -eq 0) { $arFail += '12e lessons⑥：`-DryRun -LessonIds L999` 未非零退出（F2 DryRun fail-closed 失效）' }
  if ($lsLedgerAfter6 -ne $lsLedgerBefore6) { $arFail += '12e lessons⑥：DryRun 不该写任何文件，但 LEDGER 在 DryRun 后发生了变化' }

  # ⑥b 合法 DryRun 预览（F10 补全覆盖）：`-DryRun -LessonIds L1`（合法·非最高）——exit 0、报告见 [ARCHIVE-LESSON-PLAN] move=1、
  #    LEDGER 与归档逐字不变（若回归成「合法 DryRun 也写盘」在此现形）。
  $lsLedgerBefore6b = Get-Content $lsLedgerPath -Raw
  $lsArchBefore6b = Get-Content $lsArchivePath -Raw
  $lsOut6b = & pwsh -NoProfile -File $arScript -RepoRoot $ar -DryRun -LessonIds L1 2>&1 | Out-String
  $lsCode6b = $LASTEXITCODE
  if ($lsCode6b -ne 0) { $arFail += "12e lessons⑥b：合法 `-DryRun -LessonIds L1` 非零退出（$lsCode6b，应 0）" }
  if ($lsOut6b -notmatch '\[ARCHIVE-LESSON-PLAN\]\s+move=1\b') { $arFail += "12e lessons⑥b：DryRun 报告未见 [ARCHIVE-LESSON-PLAN] move=1（条数是契约的一部分，须机器可读）。输出=[$lsOut6b]" }
  if ((Get-Content $lsLedgerPath -Raw) -ne $lsLedgerBefore6b) { $arFail += '12e lessons⑥b：合法 DryRun 不该改 LEDGER' }
  if ((Get-Content $lsArchivePath -Raw) -ne $lsArchBefore6b) { $arFail += '12e lessons⑥b：合法 DryRun 不该改归档' }

  # ⑦ 目的地写失败防数据丢失（F3+F5 暂存原子替换）：在暂存旁路路径 `<归档>.tmp` 预置同名**目录**令暂存写
  #    确定性失败（跨平台确定：Set-Content 到目录两系皆错；只读文件注入在 Linux 上 rename 到写保护文件仍会
  #    成功、不可靠）——须非零退出，且 LEDGER 与**既有归档**都逐字不变（暂存未成 → 原子替换未发生 → 旧条目
  #    零截断风险，「Set-Content 直写截断毁旧条目」类回归在此现形）；测毕清掉注入目录不影响后续清理。
  $lsTmpBlock7 = "$lsArchivePath.tmp"
  New-Item -ItemType Directory -Force $lsTmpBlock7 | Out-Null
  $lsLedgerBefore7 = Get-Content $lsLedgerPath -Raw
  $lsArchBefore7 = Get-Content $lsArchivePath -Raw
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds L1 -Quiet *> $null
  $lsCode7 = $LASTEXITCODE
  Remove-Item $lsTmpBlock7 -Recurse -Force -ErrorAction SilentlyContinue
  $lsLedgerAfter7 = Get-Content $lsLedgerPath -Raw
  $lsArchAfter7 = Get-Content $lsArchivePath -Raw
  if ($lsCode7 -eq 0) { $arFail += '12e lessons⑦：归档暂存写失败时搬 L1 未反映为非零退出（F3/F5 写失败未 fail-closed）' }
  if ($lsLedgerAfter7 -ne $lsLedgerBefore7) { $arFail += '12e lessons⑦：归档暂存写失败时 LEDGER 不该有任何变化，但内容变了（数据丢失窗口未堵住）' }
  if ($lsArchAfter7 -ne $lsArchBefore7) { $arFail += '12e lessons⑦：归档暂存写失败时既有归档不该有任何变化，但内容变了（F5：直写截断毁旧条目类回归）' }
  if (-not (& $lsNormalize $lsLedgerAfter7).Contains((& $lsNormalize ($lsL1 -join "`n")))) { $arFail += '12e lessons⑦：归档暂存写失败后 LEDGER 丢失了 L1 整块' }

  # ⑧ 空 token fail-closed（F8）：`-LessonIds ','` 拆分后全空——不得静默 exit 0；非零退出且 LEDGER 不变。
  $lsLedgerBefore8 = Get-Content $lsLedgerPath -Raw
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds ',' -Quiet *> $null
  $lsCode8 = $LASTEXITCODE
  if ($lsCode8 -eq 0) { $arFail += '12e lessons⑧：全空 token（-LessonIds 单逗号）未非零退出（F8：误输入静默成功）' }
  if ((Get-Content $lsLedgerPath -Raw) -ne $lsLedgerBefore8) { $arFail += '12e lessons⑧：全空 token 不该改动 LEDGER' }

  # ⑧b 显式空串参数（F10）：`-LessonIds ''` 绑定单空串——参数在场性判定下须走空 token 拒绝、非零退出；
  #    值真伪判定（'' 为假）会静默 exit 0 绕过 fail-closed，在此现形。
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds '' -Quiet *> $null
  $lsCode8b = $LASTEXITCODE
  if ($lsCode8b -eq 0) { $arFail += '12e lessons⑧b：显式空串 -LessonIds 未非零退出（F10：参数在场却被值判定静默跳过）' }
  if ((Get-Content $lsLedgerPath -Raw) -ne $lsLedgerBefore8) { $arFail += '12e lessons⑧b：显式空串参数不该改动 LEDGER' }

  # ⑨ LEDGER 替换失败注入（F7）+ 两侧并存自愈：`LEDGER.md.tmp` 预置同名目录令 LEDGER 暂存写确定性失败——
  #    非零退出、LEDGER 逐字不变（在册经验零丢失）、归档已先行含 L1（权威侧）；清注入后重跑同 id →
  #    自愈补齐分支生效：LEDGER 移除 L1、归档不重复追加、exit 0。
  $lsLedgerTmpBlock9 = Join-Path $ar 'docs/lessons/LEDGER.md.tmp'
  New-Item -ItemType Directory -Force $lsLedgerTmpBlock9 | Out-Null
  $lsLedgerBefore9 = Get-Content $lsLedgerPath -Raw
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds L1 -Quiet *> $null
  $lsCode9 = $LASTEXITCODE
  Remove-Item $lsLedgerTmpBlock9 -Recurse -Force -ErrorAction SilentlyContinue
  $lsLedgerAfter9 = Get-Content $lsLedgerPath -Raw
  $lsArchAfter9 = Get-Content $lsArchivePath -Raw
  if ($lsCode9 -eq 0) { $arFail += '12e lessons⑨：LEDGER 暂存/替换失败未非零退出（F7 fail-closed 失效）' }
  if ($lsLedgerAfter9 -ne $lsLedgerBefore9) { $arFail += '12e lessons⑨：LEDGER 替换失败时其内容不该有任何变化（在册经验丢失窗口未堵住）' }
  if ($lsArchAfter9 -notmatch '(?m)^##\s+L1\s*$') { $arFail += '12e lessons⑨：归档应已先行含 L1（两侧并存态的权威侧未落盘）' }
  & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds L1 -Quiet *> $null
  $lsCode9b = $LASTEXITCODE
  $lsLedgerAfter9b = Get-Content $lsLedgerPath -Raw
  $lsArchAfter9b = Get-Content $lsArchivePath -Raw
  $lsL1HeadCount9 = ([regex]::Matches($lsArchAfter9b, '(?m)^##\s+L1\s*$')).Count
  if ($lsCode9b -ne 0) { $arFail += "12e lessons⑨：两侧并存自愈重跑非零退出（$lsCode9b）" }
  if ($lsLedgerAfter9b -match '(?m)^##\s+L1\s*$') { $arFail += '12e lessons⑨：自愈重跑后 LEDGER 仍含 L1（补齐分支未生效）' }
  if ($lsL1HeadCount9 -ne 1) { $arFail += "12e lessons⑨：自愈后归档 L1 标题出现 $lsL1HeadCount9 次（应恰 1 次，不得重复追加）" }

  # ⑩ 两侧并存但内容不一致（F9）：把改动过的 L2 变体粘回 LEDGER（模拟在册被人工更新/归档陈旧）——
  #    自动清除会毁掉在册较新内容；须拒绝自愈：非零退出、LEDGER 与归档逐字不变、告警见「不一致」。
  $lsL2Divergent = @('## L2', '- date: 2026-07-02', '- symptom: 示例症状二（在册侧已被人工更新，与归档副本不同）', '- rule: 示例规则二（更新版）')
  $lsLedgerRaw10 = Get-Content $lsLedgerPath -Raw
  Set-Content $lsLedgerPath -Value (($lsLedgerRaw10.TrimEnd() + "`n`n" + ($lsL2Divergent -join "`n"))) -Encoding utf8
  $lsLedgerBefore10 = Get-Content $lsLedgerPath -Raw
  $lsArchBefore10 = Get-Content $lsArchivePath -Raw
  $lsOut10 = & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds L2 -Quiet 2>&1 | Out-String
  $lsCode10 = $LASTEXITCODE
  if ($lsCode10 -eq 0) { $arFail += '12e lessons⑩：两侧内容不一致时未非零退出（F9：盲删在册较新内容）' }
  if ((Get-Content $lsLedgerPath -Raw) -ne $lsLedgerBefore10) { $arFail += '12e lessons⑩：内容不一致时 LEDGER 不该有任何变化（在册更新被毁）' }
  if ((Get-Content $lsArchivePath -Raw) -ne $lsArchBefore10) { $arFail += '12e lessons⑩：内容不一致时归档不该有任何变化' }
  if ($lsOut10 -notmatch '\[ARCHIVE-LESSON-DIVERGED\]') { $arFail += "12e lessons⑩：冲突拒绝的捕获输出未命中 ASCII 哨兵 [ARCHIVE-LESSON-DIVERGED]（L165）。输出=[$lsOut10]" }

  # ⑪ 非规范别名拒绝（F11）：`-LessonIds L04` 数值上等于最高 id L4，但前导零别名须在校验层直接拒绝
  #    （数值匹配会让 L02 撞 L2 的块）——非零退出、告警见「非规范」、LEDGER 不变（L4 未被搬/未被当最高拒）。
  $lsLedgerBefore11 = Get-Content $lsLedgerPath -Raw
  $lsOut11 = & pwsh -NoProfile -File $arScript -RepoRoot $ar -LessonIds L04 -Quiet 2>&1 | Out-String
  $lsCode11 = $LASTEXITCODE
  if ($lsCode11 -eq 0) { $arFail += '12e lessons⑪：前导零别名 L04 未非零退出（F11：数值匹配别名撞块）' }
  if ($lsOut11 -notmatch '\[ARCHIVE-LESSON-BADID\]') { $arFail += "12e lessons⑪：别名拒绝的捕获输出未命中 ASCII 哨兵 [ARCHIVE-LESSON-BADID]（L165）。输出=[$lsOut11]" }
  if ((Get-Content $lsLedgerPath -Raw) -ne $lsLedgerBefore11) { $arFail += '12e lessons⑪：别名拒绝不该改动 LEDGER' }

  # ⑬-⑯ [ARCHIVE-LESSON-ORDER] (T166, upstream issue #226): two data-integrity gaps in ONE contract.
  #   ORDER: the mover used to mutate its projections in CALLER order, so a retry listing the same ids in a
  #     different order assigned separators to different blocks and reported a false [ARCHIVE-LESSON-DIVERGED]
  #     - refusing to finish a move that had been interrupted half-done.
  #   COMPARISON: the self-heal path compared with case-insensitive `-ne` after `TrimEnd()`. TrimEnd removes
  #     meaningful terminal SPACES along with separator artifacts, so a case-only or trailing-space
  #     difference read as identical - and the hot copy was then DELETED. That is the only-move-never-delete
  #     contract broken in the one direction that loses data.
  # A hermetic mini-repo per arm; each asserts file HASHES, because "refused" must mean "nothing changed".
  $lsoMake = {
    param($tag, $l1Ledger, $l1Archive)
    $root = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-lso-$tag-$PID"
    if (Test-Path $root) { Remove-Item -Recurse -Force $root }
    New-Item -ItemType Directory -Force (Join-Path $root 'docs/lessons') | Out-Null
    New-Item -ItemType Directory -Force (Join-Path $root 'specs/archive') | Out-Null
    New-Item -ItemType Directory -Force (Join-Path $root 'specs/tasks') | Out-Null
    Set-Content (Join-Path $root 'specs/tech-debt-tracker.md') (@('# Fixture tracker', '', '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |', '|---|---|---|---|---|---|---|') -join "`n") -Encoding utf8
    Set-Content (Join-Path $root 'docs/lessons/LEDGER.md') ((@('# Fixture LEDGER', '') + $l1Ledger) -join "`n") -Encoding utf8
    Set-Content (Join-Path $root 'specs/archive/lessons-archive.md') ((@('# Fixture archive', '') + $l1Archive) -join "`n") -Encoding utf8
    return $root
  }
  $lsoL1 = @('## L1', '- date: 2026-07-01 ｜ tier: ledger ｜ recurrence: 1', '- rule: block one')
  $lsoL2 = @('## L2', '- date: 2026-07-02 ｜ tier: ledger ｜ recurrence: 1', '- rule: block two')
  $lsoL9 = @('## L9', '- date: 2026-07-09 ｜ tier: ledger ｜ recurrence: 1', '- rule: max id, never moved')

  # ⑬ ORDER-INDEPENDENCE - a CONVERGENCE assertion, and deliberately labelled as one.
  #    MEASURED 2026-08-25: this arm does NOT discriminate. Deleting the source-order sort from archive.ps1
  #    leaves gate 12 green, because the byte-faithful comparison in ⑭-⑯ already makes both orderings reach
  #    the same state - separator artifacts no longer decide the verdict, so the order they are assigned in
  #    stops mattering. The upstream report reproduced the false DIVERGED with a harness that FORCES the
  #    second atomic replacement to fail mid-batch; this repo has no such injection point, and building one
  #    only to make an assertion look load-bearing would be worse than saying this plainly.
  #    So: the sort stays (it makes the batch deterministic regardless of what a future edit does to the
  #    comparison), this arm pins that both orders converge on the correct result, and NO mutation in the
  #    T166 registry claims to cover the ordering half. The registry says the same thing.
  foreach ($lsoOrder in @(@('L1', 'L2'), @('L2', 'L1'))) {
    $lsoTag = ($lsoOrder -join '')
    # Interrupted move, both ids: the archive already holds them, the ledger copies were never cleared.
    $lsoRoot = & $lsoMake "ord$lsoTag" ($lsoL1 + @('') + $lsoL2 + @('') + $lsoL9) ($lsoL1 + @('') + $lsoL2)
    $lsoOut = & pwsh -NoProfile -File $arScript -RepoRoot $lsoRoot -LessonIds ($lsoOrder -join ',') -Quiet 2>&1 | Out-String
    $lsoCode = $LASTEXITCODE
    $lsoLedger = Get-Content (Join-Path $lsoRoot 'docs/lessons/LEDGER.md') -Raw
    $lsoArch = Get-Content (Join-Path $lsoRoot 'specs/archive/lessons-archive.md') -Raw
    if ($lsoCode -ne 0) { $arFail += "12e lessons⑬[ARCHIVE-LESSON-ORDER]：order $lsoTag 的续做重跑非零退出（$lsoCode）——中断的移动应当被完成，而不是被拒。输出=[$lsoOut]" }
    if ($lsoOut -match '\[ARCHIVE-LESSON-DIVERGED\]') { $arFail += "12e lessons⑬[ARCHIVE-LESSON-ORDER]：order $lsoTag 报了假 DIVERGED——两侧内容一致，分歧只来自处理顺序。输出=[$lsoOut]" }
    foreach ($lsoId in @('L1', 'L2')) {
      if ($lsoLedger -match ("(?m)^##\s+$lsoId\s*$")) { $arFail += "12e lessons⑬[ARCHIVE-LESSON-ORDER]：order $lsoTag 之后 LEDGER 仍留着 $lsoId（续做未完成）" }
      $lsoN = ([regex]::Matches($lsoArch, "(?m)^##\s+$lsoId\s*$")).Count
      if ($lsoN -ne 1) { $arFail += "12e lessons⑬[ARCHIVE-LESSON-ORDER]：order $lsoTag 之后归档里 $lsoId 出现 $lsoN 次（应恰 1 次）" }
    }
    Remove-Item -Recurse -Force $lsoRoot -ErrorAction SilentlyContinue
  }

  # ⑭ CASE-ONLY divergence must be REFUSED. `-ne` is case-insensitive, so this used to read as identical
  #    and delete the hot copy.
  $lsoCaseArch = @('## L1', '- date: 2026-07-01 ｜ tier: ledger ｜ recurrence: 1', '- rule: BLOCK ONE')
  $lsoRootC = & $lsoMake 'case' ($lsoL1 + @('') + $lsoL9) $lsoCaseArch
  $lsoLedH0 = (Get-FileHash (Join-Path $lsoRootC 'docs/lessons/LEDGER.md')).Hash
  $lsoArcH0 = (Get-FileHash (Join-Path $lsoRootC 'specs/archive/lessons-archive.md')).Hash
  $lsoOutC = & pwsh -NoProfile -File $arScript -RepoRoot $lsoRootC -LessonIds L1 -Quiet 2>&1 | Out-String
  $lsoCodeC = $LASTEXITCODE
  if ($lsoCodeC -eq 0) { $arFail += '12e lessons⑭[ARCHIVE-LESSON-ORDER]：仅大小写不同的两侧未被判分歧（退出 0）——case-insensitive 比较会删掉在册副本' }
  if ($lsoOutC -notmatch '\[ARCHIVE-LESSON-DIVERGED\]') { $arFail += "12e lessons⑭[ARCHIVE-LESSON-ORDER]：仅大小写不同未报 DIVERGED。输出=[$lsoOutC]" }
  if ((Get-FileHash (Join-Path $lsoRootC 'docs/lessons/LEDGER.md')).Hash -ne $lsoLedH0) { $arFail += '12e lessons⑭[ARCHIVE-LESSON-ORDER]：被拒的恢复改动了 LEDGER（哈希变了）' }
  if ((Get-FileHash (Join-Path $lsoRootC 'specs/archive/lessons-archive.md')).Hash -ne $lsoArcH0) { $arFail += '12e lessons⑭[ARCHIVE-LESSON-ORDER]：被拒的恢复改动了归档（哈希变了）' }
  Remove-Item -Recurse -Force $lsoRootC -ErrorAction SilentlyContinue

  # ⑮ FINAL-LINE TRAILING SPACE must be REFUSED. TrimEnd() erased exactly this difference.
  $lsoSpArch = @('## L1', '- date: 2026-07-01 ｜ tier: ledger ｜ recurrence: 1', '- rule: block one ')
  $lsoRootS = & $lsoMake 'space' ($lsoL1 + @('') + $lsoL9) $lsoSpArch
  $lsoLedH1 = (Get-FileHash (Join-Path $lsoRootS 'docs/lessons/LEDGER.md')).Hash
  $lsoOutS = & pwsh -NoProfile -File $arScript -RepoRoot $lsoRootS -LessonIds L1 -Quiet 2>&1 | Out-String
  if ($LASTEXITCODE -eq 0) { $arFail += '12e lessons⑮[ARCHIVE-LESSON-ORDER]：末行尾随空格差异未被判分歧——TrimEnd 会连内容字符一起抹掉' }
  if ($lsoOutS -notmatch '\[ARCHIVE-LESSON-DIVERGED\]') { $arFail += "12e lessons⑮[ARCHIVE-LESSON-ORDER]：末行尾随空格差异未报 DIVERGED。输出=[$lsoOutS]" }
  if ((Get-FileHash (Join-Path $lsoRootS 'docs/lessons/LEDGER.md')).Hash -ne $lsoLedH1) { $arFail += '12e lessons⑮[ARCHIVE-LESSON-ORDER]：被拒的恢复改动了 LEDGER' }
  Remove-Item -Recurse -Force $lsoRootS -ErrorAction SilentlyContinue

  # ⑯ SEPARATOR-ONLY difference stays RECOVERABLE. A trailing blank line is storage, not content - if this
  #    went red the fix would have over-corrected and no interrupted move could ever be finished.
  $lsoRootB = & $lsoMake 'blank' ($lsoL1 + @('') + $lsoL9) ($lsoL1 + @('', ''))
  $lsoOutB = & pwsh -NoProfile -File $arScript -RepoRoot $lsoRootB -LessonIds L1 -Quiet 2>&1 | Out-String
  if ($LASTEXITCODE -ne 0) { $arFail += "12e lessons⑯[ARCHIVE-LESSON-ORDER]：仅尾随空行不同被判成分歧——分隔符是存储细节，不是内容。输出=[$lsoOutB]" }
  if ((Get-Content (Join-Path $lsoRootB 'docs/lessons/LEDGER.md') -Raw) -match '(?m)^##\s+L1\s*$') { $arFail += '12e lessons⑯[ARCHIVE-LESSON-ORDER]：仅分隔符不同的续做未清掉 LEDGER 侧副本' }
  Remove-Item -Recurse -Force $lsoRootB -ErrorAction SilentlyContinue

  # ⑫ T74 cold-store SELECTOR (lessons.ps1 archive): hermetic mini-repo, real lessons.ps1 -RepoRoot run.
  #    Selection contract = tier==ledger AND recurrence==1, MINUS the current max id, MINUS ids referenced
  #    by resident faces (CLAUDE.md/CLAUDE.template.md). Seed: L1 qualifies; L2 tier=must; L3 recurrence=2;
  #    L4 one-off but referenced by fixture CLAUDE.md (resident-kept); L5 one-off but max id.
  $t74fx = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-t74sel-$PID"
  if (Test-Path $t74fx) { Remove-Item -Recurse -Force $t74fx }
  New-Item -ItemType Directory -Force (Join-Path $t74fx 'docs/lessons') | Out-Null
  New-Item -ItemType Directory -Force (Join-Path $t74fx 'specs/tasks') | Out-Null
  Set-Content (Join-Path $t74fx 'specs/tech-debt-tracker.md') (@('# Fixture tracker (12e-12)', '', '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |', '|---|---|---|---|---|---|---|') -join "`n") -Encoding utf8
  $t74Ledger = @(
    '# Fixture LEDGER (12e-12 T74 selector)', '',
    '## L1', '- date: 2026-07-01 ｜ tags: t ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1', '- symptom: one-off T74COLDPROBE token lives only here', '- rule: qualifies for the cold store', '',
    '## L2', '- date: 2026-07-02 ｜ tags: t ｜ tier: must ｜ kind: pitfall ｜ severity: blocking ｜ recurrence: 3', '- symptom: must-tier entry', '- rule: never selected (tier)', '- enforced_by: tests/probe.ps1', '',
    '## L3', '- date: 2026-07-03 ｜ tags: t ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 2', '- symptom: recurring entry', '- rule: never selected (recurrence)', '',
    '## L4', '- date: 2026-07-04 ｜ tags: t ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1', '- symptom: one-off but resident-referenced', '- rule: kept hot (CLAUDE.md cites it)', '',
    '## L5', '- date: 2026-07-05 ｜ tags: t ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1', '- symptom: one-off but current max id', '- rule: kept hot (Next-Id guard)'
  ) -join "`n"
  Set-Content (Join-Path $t74fx 'docs/lessons/LEDGER.md') $t74Ledger -Encoding utf8
  Set-Content (Join-Path $t74fx 'CLAUDE.md') 'Fixture resident core: doctrine cites L4 here.' -Encoding utf8
  $lsnScript = Join-Path $fixtureRepoRoot 'scripts/lessons.ps1'
  $t74LedgerBefore = Get-Content (Join-Path $t74fx 'docs/lessons/LEDGER.md') -Raw
  $t74Dry = & pwsh -NoProfile -File $lsnScript archive -DryRun -RepoRoot $t74fx 2>&1 | Out-String
  $t74DryCode = $LASTEXITCODE
  if ($t74DryCode -ne 0) { $arFail += "12e-12a: selector dry-run exited non-zero ($t74DryCode)" }
  if ($t74Dry -notmatch '\[LSN-ARCHIVE-DRYRUN\] candidates=1 \(resident-referenced kept hot: 1\): L1\b') { $arFail += "12e-12a: dry-run did not report exactly candidate L1 with one resident-kept id. Out=[$($t74Dry.Trim())]" }
  if ((Get-Content (Join-Path $t74fx 'docs/lessons/LEDGER.md') -Raw) -ne $t74LedgerBefore) { $arFail += '12e-12a: dry-run modified the LEDGER (must be read-only)' }
  $t74Run = & pwsh -NoProfile -File $lsnScript archive -RepoRoot $t74fx 2>&1 | Out-String
  $t74RunCode = $LASTEXITCODE
  $t74HotAfter = Get-Content (Join-Path $t74fx 'docs/lessons/LEDGER.md') -Raw
  $t74ColdPath = Join-Path $t74fx 'specs/archive/lessons-archive.md'
  $t74ColdAfter = if (Test-Path $t74ColdPath) { Get-Content $t74ColdPath -Raw } else { '' }
  if ($t74RunCode -ne 0) { $arFail += "12e-12b: selector real run exited non-zero ($t74RunCode). Out=[$($t74Run.Trim())]" }
  if ($t74Run -notmatch '\[LSN-ARCHIVE\] requested=1') { $arFail += "12e-12b: real run did not report requested=1. Out=[$($t74Run.Trim())]" }
  if ($t74HotAfter -match '(?m)^##\s+L1\s*$') { $arFail += '12e-12b: L1 still in the hot LEDGER after archiving' }
  foreach ($keepId in 'L2', 'L3', 'L4', 'L5') { if ($t74HotAfter -notmatch "(?m)^##\s+$keepId\s*$") { $arFail += "12e-12b: $keepId missing from the hot LEDGER (over-selection)" } }
  if ($t74ColdAfter -notmatch '(?m)^##\s+L1\s*$') { $arFail += '12e-12b: L1 absent from specs/archive/lessons-archive.md' }
  $t74Again = & pwsh -NoProfile -File $lsnScript archive -RepoRoot $t74fx 2>&1 | Out-String
  if ($LASTEXITCODE -ne 0 -or $t74Again -notmatch '\[LSN-ARCHIVE\] moved=0') { $arFail += "12e-12c: second run not an idempotent no-op. Out=[$($t74Again.Trim())]" }
  $t74Search = & pwsh -NoProfile -File $lsnScript search T74COLDPROBE -RepoRoot $t74fx 2>&1 | Out-String
  if ($LASTEXITCODE -ne 0 -or $t74Search -notmatch 'L1 \[archived\]') { $arFail += "12e-12d: archived-only entry not found by search with the [archived] label. Out=[$($t74Search.Trim())]" }
  Remove-Item -Recurse -Force $t74fx -ErrorAction SilentlyContinue

  # (6) TD107: every read-modify-write path must hand back the delimiter it was given. Two hermetic
  #     mini-repos, seeded identically except for the delimiter, each driven through the real archive.ps1
  #     twice (tracker+cards pass, then the -LessonIds lessons pass), then asserted over all six write
  #     targets: a CRLF tree stays uniformly CRLF and keeps its final CRLF, an LF tree comes back with
  #     zero CR bytes. The old `($lines -join "`n") | Set-Content` shape failed both directions at once -
  #     it flattened CRLF to LF, and because Set-Content appends the platform newline unless told not to,
  #     it also gave pure-LF files a stray CRLF on the last line. Assertions read with -Raw, never plain
  #     Get-Content (which strips delimiters before anything can observe them). Anti-vacuum: the block
  #     first proves TDE1 and L1 actually moved, so a no-op run - which would leave every seeded file
  #     untouched and satisfy the byte assertions for free - is red rather than green.
  foreach ($eolCase in @(@{ Name = 'CRLF'; Nl = "`r`n" }, @{ Name = 'LF'; Nl = "`n" })) {
    $eolNl = $eolCase.Nl
    $eolFx = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-archive-eol-$($eolCase.Name)-$PID"
    if (Test-Path $eolFx) { Remove-Item -Recurse -Force $eolFx }
    foreach ($eolDir in 'specs/tasks', 'specs/archive', 'docs/lessons') { New-Item -ItemType Directory -Force (Join-Path $eolFx $eolDir) | Out-Null }
    $eolSeed = { param([string]$rel, [string[]]$lines)
      Set-Content -LiteralPath (Join-Path $eolFx $rel) -Value (($lines -join $eolNl) + $eolNl) -Encoding utf8 -NoNewline }
    & $eolSeed 'specs/tech-debt-tracker.md' @(
      '# Fixture tracker (12e-6 EOL)', '',
      '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |',
      '|---|---|---|---|---|---|---|',
      '| TDE1 | 2026-07-27 | `scripts/a.ps1` | paid row, must be archived | minor | paid | PR #1 |',
      '| TDE2 | 2026-07-27 | `scripts/b.ps1` | open row, must stay hot | minor | open | - |')
    & $eolSeed 'specs/archive/tech-debt-archive.md' @('# Fixture td archive', '', '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |', '|---|---|---|---|---|---|---|')
    & $eolSeed 'specs/archive/tech-debt-index.md' @('# Fixture td index', '', '| id | 严重度 | 状态 | 位置 | 一句话（债，截断） |', '|---|---|---|---|---|')
    & $eolSeed 'specs/archive/cards-index.md' @('# Fixture cards index', '', '| id | 状态 | 标题 |', '|---|---|---|')
    & $eolSeed 'specs/archive/lessons-archive.md' @('# Fixture lessons archive', '')
    & $eolSeed 'specs/tasks/TE1.md' @('---', 'id: TE1', 'title: merged card', 'status: merged', '---')
    & $eolSeed 'docs/lessons/LEDGER.md' @('# Fixture LEDGER (12e-6 EOL)', '', '## L1', '- symptom: one-off, archived by this pass', '', '## L2', '- symptom: highest id, stays hot')
    & pwsh -NoProfile -File $arScript -RepoRoot $eolFx -Quiet *> $null
    $eolCode1 = $LASTEXITCODE
    & pwsh -NoProfile -File $arScript -RepoRoot $eolFx -LessonIds L1 -Quiet *> $null
    $eolCode2 = $LASTEXITCODE
    $eolRead = { param([string]$rel) $p = Join-Path $eolFx $rel; if (Test-Path $p) { Get-Content -LiteralPath $p -Raw } else { $null } }
    $eolBad = @()
    if ($eolCode1 -ne 0 -or $eolCode2 -ne 0) { $eolBad += "archive.ps1 exited non-zero (tracker/cards=$eolCode1 lessons=$eolCode2)" }
    $eolLiveTd = & $eolRead 'specs/tech-debt-tracker.md'
    $eolArchTd = & $eolRead 'specs/archive/tech-debt-archive.md'
    $eolHotLedger = & $eolRead 'docs/lessons/LEDGER.md'
    $eolColdLedger = & $eolRead 'specs/archive/lessons-archive.md'
    if ($eolLiveTd -match 'TDE1' -or $eolArchTd -notmatch 'TDE1') { $eolBad += 'vacuous fixture: TDE1 never moved, so the tracker write path never ran' }
    if ($eolHotLedger -match '(?m)^##\s+L1\s*$' -or $eolColdLedger -notmatch '(?m)^##\s+L1\s*$') { $eolBad += 'vacuous fixture: L1 never moved, so the lessons write path never ran' }
    foreach ($eolRel in 'specs/tech-debt-tracker.md', 'specs/archive/tech-debt-archive.md', 'specs/archive/tech-debt-index.md', 'specs/archive/cards-index.md', 'specs/archive/lessons-archive.md', 'docs/lessons/LEDGER.md') {
      $eolRaw = & $eolRead $eolRel
      if ($null -eq $eolRaw) { $eolBad += "$eolRel missing after the run"; continue }
      $eolLf = ([regex]::Matches($eolRaw, "`n")).Count
      $eolCr = ([regex]::Matches($eolRaw, "`r")).Count
      $eolCrLf = ([regex]::Matches($eolRaw, "`r`n")).Count
      if ($eolCase.Name -eq 'CRLF') {
        if ($eolLf -ne $eolCrLf -or $eolCr -ne $eolCrLf) { $eolBad += "$eolRel is not uniformly CRLF (lf=$eolLf cr=$eolCr crlf=$eolCrLf)" }
        if (-not $eolRaw.EndsWith("`r`n")) { $eolBad += "$eolRel lost its final CRLF" }
      } else {
        if ($eolCr -ne 0) { $eolBad += "$eolRel gained $eolCr CR byte(s) - an LF tree must come back pure LF" }
        if (-not $eolRaw.EndsWith("`n")) { $eolBad += "$eolRel lost its final LF" }
      }
    }
    Remove-Item -Recurse -Force $eolFx -ErrorAction SilentlyContinue
    if ($eolBad.Count) { $arFail += "12e(6) EOL-PRESERVE [$($eolCase.Name)]: archive.ps1 did not preserve the line endings it was given - " + ($eolBad -join ' | ') }
  }

  # (7) INDEX-IS-A-PROJECTION: both indices must stay byte-equal, line for line, to what the generator
  #     projects - the title column copied off the archived card / tracker row, the count in the header note
  #     recomputed from the rows. A hand-authored title or a hand-patched count is the failure mode, and it
  #     used to pass everything: (1)-(4) above only ever asserted id PRESENCE and a row count, never a cell's
  #     text. Four cases: (a) freshly swept fixture is green; (b) reword a title by hand -> red at that line;
  #     (c) hand-patch the count -> red at line 3; (d) THIS repo's own two indices are still the projection.
  #     Each mutation is reverted from the exact bytes read before it and the revert is verified before the
  #     next case runs (L196 - never trust a restore you did not compare).
  $chkCards = Join-Path $ar 'specs/archive/cards-index.md'
  $chkTd = Join-Path $ar 'specs/archive/tech-debt-index.md'
  $chkOutA = & pwsh -NoProfile -File $arScript -RepoRoot $ar -Check 2>&1 | Out-String
  $chkCodeA = $LASTEXITCODE
  if ($chkCodeA -ne 0) { $arFail += "12e(7a): -Check went red on a freshly swept fixture (exit $chkCodeA). Out=[$($chkOutA.Trim())]" }
  if ($chkOutA -notmatch '\[ARCHIVE-CHECK-OK\]') { $arFail += "12e(7a): green path missing ASCII sentinel [ARCHIVE-CHECK-OK] (L167). Out=[$($chkOutA.Trim())]" }

  # (7b) hand-edited TITLE cell. TA1's seeded title is `merged one`; rewording it must be caught, because
  #      the title is projected from the card's front-matter and nothing else may author it.
  if (-not (Test-Path $chkCards)) { $arFail += '12e(7b): cards-index.md missing from the swept fixture' }
  else {
    $chkCardsBytes = [IO.File]::ReadAllBytes($chkCards)
    $chkCardsText = [IO.File]::ReadAllText($chkCards)
    [IO.File]::WriteAllText($chkCards, ($chkCardsText -replace 'merged one', 'HAND EDITED'))
    $chkOutB = & pwsh -NoProfile -File $arScript -RepoRoot $ar -Check 2>&1 | Out-String
    $chkCodeB = $LASTEXITCODE
    [IO.File]::WriteAllBytes($chkCards, $chkCardsBytes)
    if ([IO.File]::ReadAllText($chkCards) -ne $chkCardsText) { $arFail += '12e(7b): restore of the tampered cards-index failed - later cases would be judging tampered bytes (L196)' }
    if ($chkCodeB -eq 0) { $arFail += "12e(7b): a hand-edited title cell did NOT turn -Check red. Out=[$($chkOutB.Trim())]" }
    if ($chkOutB -notmatch '\[ARCHIVE-CHECK-DRIFT\]') { $arFail += "12e(7b): title drift missing ASCII sentinel [ARCHIVE-CHECK-DRIFT] (L167). Out=[$($chkOutB.Trim())]" }
    if ($chkOutB -notmatch 'cards-index\.md:\d+') { $arFail += "12e(7b): drift report does not name the offending file:line. Out=[$($chkOutB.Trim())]" }
  }

  # (7c) hand-patched COUNT in the header note. Mutated by rewriting the digits on line 3 - a pure-ASCII
  #      anchor, so the assertion never depends on the CJK in that note surviving a subprocess round trip.
  if (-not (Test-Path $chkTd)) { $arFail += '12e(7c): tech-debt-index.md missing from the swept fixture' }
  else {
    $chkTdBytes = [IO.File]::ReadAllBytes($chkTd)
    $chkTdLines = [IO.File]::ReadAllLines($chkTd)
    if ($chkTdLines.Count -lt 3 -or $chkTdLines[2] -notmatch '\d') { $arFail += "12e(7c): header note line 3 carries no digit to mutate - the projected count moved, so this case would pass vacuously. Line=[$(if ($chkTdLines.Count -ge 3) { $chkTdLines[2] } else { '<absent>' })]" }
    else {
      $chkTdLines[2] = $chkTdLines[2] -replace '\d+', '99'
      [IO.File]::WriteAllLines($chkTd, $chkTdLines)
      $chkOutC = & pwsh -NoProfile -File $arScript -RepoRoot $ar -Check 2>&1 | Out-String
      $chkCodeC = $LASTEXITCODE
      [IO.File]::WriteAllBytes($chkTd, $chkTdBytes)
      if ([IO.File]::ReadAllBytes($chkTd).Length -ne $chkTdBytes.Length) { $arFail += '12e(7c): restore of the tampered tech-debt-index failed (L196)' }
      if ($chkCodeC -eq 0) { $arFail += "12e(7c): a hand-patched count did NOT turn -Check red. Out=[$($chkOutC.Trim())]" }
      if ($chkOutC -notmatch 'tech-debt-index\.md:3') { $arFail += "12e(7c): drift not reported at the header-note line. Out=[$($chkOutC.Trim())]" }
    }
  }

  # (7d) the meta repo itself. (a)-(c) only prove the checker works; THIS is the assertion that catches an
  #      index hand-edited in this repo. -Check is read-only, so running it against $RepoRoot writes nothing.
  $chkSelf = & pwsh -NoProfile -File $arScript -RepoRoot $fixtureRepoRoot -Check 2>&1 | Out-String
  if ($LASTEXITCODE -ne 0) { $arFail += "12e(7d): this repo's own archive indices are not what the generator projects - re-run scripts\archive.ps1 rather than editing them. Out=[$($chkSelf.Trim())]" }

  # (7e) Keep the base repository's cards-only check contract as a distinct regression.
  # `-Check` is intentionally broader, but it cannot prove that the verifier's
  # historical `-CheckCardsIndex` entry remains byte-exact, read-only, and usable
  # on its own.  The three mutations exercise BOM drift, same-content-tree
  # immutability, and a projected row disappearing from the index.
  $cardsIndexPath = Join-Path $ar 'specs/archive/cards-index.md'
  $getArchiveTreeState = {
    @(Get-ChildItem -LiteralPath $ar -Recurse -File | Sort-Object FullName | ForEach-Object {
      $rel = [IO.Path]::GetRelativePath($ar, $_.FullName).Replace('\', '/')
      "$rel|$((Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash)"
    })
  }
  $cardsTreeBefore = @(& $getArchiveTreeState)
  $cardsGoodOut = & pwsh -NoProfile -File $arScript -RepoRoot $ar -CheckCardsIndex -Quiet 2>&1 | Out-String
  $cardsGoodCode = $LASTEXITCODE
  $cardsTreeAfter = @(& $getArchiveTreeState)
  if ($cardsGoodCode -ne 0) { $arFail += "12e(7e): correct cards index failed its dedicated read-only check (exit=$cardsGoodCode): $cardsGoodOut" }
  if (@(Compare-Object $cardsTreeBefore $cardsTreeAfter).Count) { $arFail += '12e(7e): dedicated cards-index check modified the fixture tree.' }
  if (-not (Test-Path -LiteralPath $cardsIndexPath -PathType Leaf)) { $arFail += '12e(7e): cards-index.md is absent from the swept fixture.' }
  else {
    $cardsCorrectBytes = [IO.File]::ReadAllBytes($cardsIndexPath)
    $utf8Bom = [Text.UTF8Encoding]::new($true).GetPreamble()
    [IO.File]::WriteAllBytes($cardsIndexPath, [byte[]]($utf8Bom + $cardsCorrectBytes))
    $cardsBomHash = (Get-FileHash -LiteralPath $cardsIndexPath -Algorithm SHA256).Hash
    $cardsBomOut = & pwsh -NoProfile -File $arScript -RepoRoot $ar -CheckCardsIndex -Quiet 2>&1 | Out-String
    $cardsBomCode = $LASTEXITCODE
    if ($cardsBomCode -eq 0 -or $cardsBomOut -notmatch '\[ARCHIVE-CHECK-DRIFT\]') { $arFail += "12e(7e): BOM-only cards-index byte drift was not rejected by -CheckCardsIndex: $cardsBomOut" }
    if ((Get-FileHash -LiteralPath $cardsIndexPath -Algorithm SHA256).Hash -ne $cardsBomHash) { $arFail += '12e(7e): BOM drift check rewrote or repaired the fixture.' }
    [IO.File]::WriteAllBytes($cardsIndexPath, $cardsCorrectBytes)

    $missingTa3 = @(Get-Content -LiteralPath $cardsIndexPath | Where-Object { $_ -notmatch '^\| TA3 \|' })
    Set-Content -LiteralPath $cardsIndexPath -Value ($missingTa3 -join "`n") -Encoding utf8
    $cardsDriftTreeBefore = @(& $getArchiveTreeState)
    $cardsRowOut = & pwsh -NoProfile -File $arScript -RepoRoot $ar -CheckCardsIndex -Quiet 2>&1 | Out-String
    $cardsRowCode = $LASTEXITCODE
    $cardsDriftTreeAfter = @(& $getArchiveTreeState)
    if ($cardsRowCode -eq 0 -or $cardsRowOut -notmatch '\[ARCHIVE-CHECK-DRIFT\]') { $arFail += "12e(7e): deleting the TA3 projection row was not rejected by -CheckCardsIndex: $cardsRowOut" }
    if (@(Compare-Object $cardsDriftTreeBefore $cardsDriftTreeAfter).Count) { $arFail += '12e(7e): cards-index drift check modified or self-repaired the fixture tree.' }
    [IO.File]::WriteAllBytes($cardsIndexPath, $cardsCorrectBytes)
  }

  Remove-Item -Recurse -Force $ar -ErrorAction SilentlyContinue
  if ($arFail.Count) { Fail ("12e archive.ps1 冷存压缩闸失败：`n    - " + ($arFail -join "`n    - ")) }
  else { Write-Host '  12e archive.ps1 冷存压缩 OK（热/冷分区正确 · 同 id 相异行不丢 · 索引条数==归档（期望值从夹具派生）+ 头注指针完好 · 模板豁免 · 幂等 · index-is-a-projection: -Check green when swept, red on a hand-edited title and on a hand-patched count, and this repo''s own indices still project clean · lessons 子夹具：逗号形式精确文本搬运/幂等/拒最高id+告警/拒未知id+告警/拒前导零别名/DryRun fail-closed/空token fail-closed/双侧暂存原子替换·任一侧写失败零丢失/两侧并存一致自愈·不一致拒改 均 OK · T74 selector: picks only tier=ledger+rec=1, keeps max-id and resident-referenced ids hot, dry-run read-only, idempotent, archived entries searchable [archived]）' -ForegroundColor Green }
}
$g12Drift = @()
foreach ($g12Rel in $g12ProtectedRel) {
  $g12Path = Join-Path $RepoRoot $g12Rel
  $g12After = if (Test-Path -LiteralPath $g12Path -PathType Leaf) { (Get-FileHash -LiteralPath $g12Path -Algorithm SHA256).Hash } else { '<missing>' }
  if ($g12After -ne $g12Before[$g12Rel]) { $g12Drift += "$g12Rel before=$($g12Before[$g12Rel]) after=$g12After" }
}
$fixtureResolved = [IO.Path]::GetFullPath($fixtureRepoRoot)
$fixtureTempRoot = [IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
if (-not $fixtureResolved.StartsWith($fixtureTempRoot, [StringComparison]::OrdinalIgnoreCase) -or (Split-Path -Leaf $fixtureResolved) -notlike 'selftest-g12-repo-*') {
  Fail "[SELFTEST-FIXTURE-CLEANUP-UNSAFE] refusing recursive cleanup outside the Gate-12 Temp fixture namespace: $fixtureResolved"
} else {
  Remove-Item -LiteralPath $fixtureResolved -Recurse -Force -ErrorAction SilentlyContinue
}
if ($g12Drift.Count) { Fail "[SELFTEST-FIXTURE-SIDE-EFFECT] Gate 12 altered the live worktree: $($g12Drift -join '; ')" }
else { Write-Host '  Gate 12 fixture isolation OK（live lessons ledger/archive bytes unchanged）' -ForegroundColor Green }

# --- 13. 防泄露闸冒烟：check-secrets.ps1 对当前（已入 git 的）元仓真跑扫描 ---
# TD63 item12：本节注释曾称「本元仓非 git 仓」，但本仓自身现已纳入 git（见 CLAUDE.md）——下方这一跑
# 实际走的是「真扫描、当前无命中」路径，退出 0，并非「非 git 仓优雅跳过」路径；后者此前长期零覆盖
# （说着测跳过、实际测的是另一条分支）。跳过路径由下方 13c 在**临时非 git 目录**里单独、真正覆盖。
Exit-Gate
}

if (Enter-Gate '13') {
Step '13/17 防泄露闸冒烟（check-secrets.ps1 对已入 git 的元仓真扫描）'
$secPath = Join-Path $PSScriptRoot 'check-secrets.ps1'
# T158 [SELFTEST-SCAN-SKIPPED]：本项目可在 _config 的 SelftestSkipScans 里声明这条**冒烟**扫描冗余。
# 能这么做的唯一理由写在枚举里：ship / pre-push / CI / 建仓四条**执行臂**照跑，且 17a 的种子缺陷臂
# （证明扫描器真能抓到）**不可跳、也没跳**。**绝不静默**：跳过必须打出 id 与仍在覆盖它的臂——
# 静默跳过与通过不可区分，正是许可闸「零覆盖≠合规」信条禁止的形状。
. (Join-Path $PSScriptRoot '_config.ps1')   # T158: SelftestSkipScans accessor lives here
. (Join-Path $PSScriptRoot '_guard.ps1')    # T158: the closed enum and its judgement live here
# 先跑声明样例再信它对真配置的判定：本仓的 SelftestSkipScans 只含合法 id，于是「未知 id 硬报错」那条
# 在真树上永不触发——不跑样例，这条规则就无从证明还活着（变异必存活，白记一笔假红）。
$secSkipEx = @(Test-ScaffoldSelftestSkipExamples)
if ($secSkipEx.Count) { foreach ($sse in $secSkipEx) { Fail "13 probe: $sse" } }
$secSkipIssues = @(Get-ScaffoldSelftestSkipIssue -Requested (Get-ScaffoldSelftestSkipScans))
if ($secSkipIssues.Count) { foreach ($ssi in $secSkipIssues) { Fail $ssi } }
$secSkipEntry = @(Get-ScaffoldSkippableSelftestScan | Where-Object { $_.Id -eq 'secrets-smoke' -and $_.Id -cin @(Get-ScaffoldSelftestSkipScans) })
if (-not (Test-Path $secPath)) { Fail 'scripts\check-secrets.ps1 不存在（防泄露闸缺失）。' }
elseif ($secSkipEntry.Count -eq 1) {
  Write-Host "  [SELFTEST-SCAN-SKIPPED] secrets-smoke —— $($secSkipEntry[0].What)。本项目在 _config 的 SelftestSkipScans 里声明它冗余。" -ForegroundColor Yellow
  foreach ($arm in @($secSkipEntry[0].CoveredBy)) { Write-Host "      仍覆盖：$arm" -ForegroundColor Yellow }
  Write-Host '      这是**项目的声明，不是证明**：跳过的只是验收跑里的一条冒烟断言，一旦仓里真进了密钥，消息会在 ship/push/PR 处到达，而不是在本次元层跑里。' -ForegroundColor Yellow
}
else {
  & pwsh -NoProfile -File $secPath *> $null
  if ($LASTEXITCODE -ne 0) { Fail "check-secrets.ps1 在本元仓非零退出（$LASTEXITCODE）——当前应无致命命中、退出 0。" }
  else { Write-Host '  防泄露闸冒烟 OK（本元仓真扫描，当前无致命命中，exit 0）' }
}
# 13a'. [LICENSE-SURFACE] (T157)：许可闸的扫描面判定跑它自己的声明样例。放在闸 13（本闸已覆盖
# check-secrets / check-licenses 一族）而非新开闸号，且**先跑样例再信它对真仓的判定**——一个恒返回空的
# 判定会让空态永远命中、把「什么都没查」重新伪装成合规，正是本卡要废掉的那种绿字。
. (Join-Path $PSScriptRoot '_guard.ps1')
$licSurfEx = @(Test-ScaffoldLicenseSurfaceExamples)
if ($licSurfEx.Count -ne 0) { foreach ($lse in $licSurfEx) { Fail "13a' $lse" } }
elseif (-not $fail) { Write-Host '  13a'' [LICENSE-SURFACE] 扫描面判定样例 OK（空/清单/vendored/不可判定四向；跳过只由磁盘内容推出，无任何调用方开关）' -ForegroundColor Green }
# 13a''. [LICENSE-PIN] (T167, upstream issue #225): the license gate's ONLINE/OFFLINE boundary is structural.
# 8.2a' already pins the two SCANNER versions; what was unpinned is the uv BINARY - the action sha was
# pinned, which fixes who installs uv, not which uv gets installed - and nothing stopped the gate reaching a
# registry WHILE deciding whether the repo is distributable. Same commit, different day, different verdict.
# Asserted structurally rather than by running a scan: this repo carries no manifest, so a behavioural test
# here would scan nothing and pass vacuously - the exact "zero coverage reads as compliant" shape the
# license chain exists to refuse.
$lpCi = Join-Path $RepoRoot '.github/workflows/ci.yml'
$lpGate = Join-Path $PSScriptRoot 'check-licenses.ps1'
if (-not (Test-Path $lpCi) -or -not (Test-Path $lpGate)) { Fail "13a'' [LICENSE-PIN] ci.yml 或 check-licenses.ps1 不存在——许可闸的钉版本面无从校验。" }
else {
  $lpCiRaw = Get-Content -LiteralPath $lpCi -Raw
  $lpGateRaw = Get-Content -LiteralPath $lpGate -Raw
  $lpFindings = @()
  # (1) the uv BINARY version, pinned to a concrete x.y.z on the setup-uv step.
  if ($lpCiRaw -notmatch '(?s)astral-sh/setup-uv@[0-9a-f]{40}[^\n]*\n(?:[^\n]*\n){0,8}?\s*version:\s*"?\d+\.\d+\.\d+"?') {
    $lpFindings += 'setup-uv 未钉 uv 二进制版本（version: x.y.z）——action sha 只钉了「谁来装 uv」，没钉「装哪个 uv」，判定合规的解析器仍随上游发版漂移。'
  }
  # (2) the ONLINE provisioning phase must actually INSTALL both pinned scanners. Asserting only that the
  #     [LICENSE-PIN] sentinel appears somewhere in ci.yml is too weak - the sentinel also sits in the
  #     surrounding prose, so deleting an install line left the check green (measured: that mutation
  #     SURVIVED). Naming both pinned installs is what makes the warm phase load-bearing.
  if ($lpCiRaw -notmatch '\[LICENSE-PIN\]') { $lpFindings += 'ci.yml 无 [LICENSE-PIN] 联网预热阶段——扫描器改回在闸内按需拉取，即在「判定是否可分发」的同时联网。' }
  if ($lpCiRaw -notmatch 'pip-licenses==\d+\.\d+\.\d+') { $lpFindings += 'ci.yml 的联网预热阶段未按钉死版本装 pip-licenses——离线闸届时扫不到后端依赖，覆盖缺口而非合规。' }
  if ($lpCiRaw -notmatch 'license-checker@\d+\.\d+\.\d+') { $lpFindings += 'ci.yml 的联网预热阶段未按钉死版本装 license-checker——离线闸届时扫不到前端依赖。' }
  # (3) the gate forces offline, and (4) does so BEFORE the first scanner call. Order is the property:
  #     setting it afterwards would be decoration.
  foreach ($lpVar in @('UV_OFFLINE', 'npm_config_offline')) {
    if ($lpGateRaw -notmatch [regex]::Escape($lpVar)) { $lpFindings += "check-licenses.ps1 未置 $lpVar——扫描阶段仍可联网取包。" }
  }
  $lpGateLines = @($lpGateRaw -split '\r?\n')
  # Both matches are captured into a variable BEFORE any property read: `(... | Select-Object -First 1).LineNumber`
  # throws under StrictMode when nothing matched, which turns a legitimate finding into a crash - non-zero
  # for the wrong reason (measured: the UV_OFFLINE deletion came back [MUT-BAD-EVIDENCE] this way).
  $lpOffM = @($lpGateLines | Select-String -Pattern '^\s*\$env:UV_OFFLINE\s*=')
  $lpOffAt = if ($lpOffM.Count) { $lpOffM[0].LineNumber } else { 0 }
  # Matched on the CALL OPERATOR, not the tool name. The script's comment-based help quotes both
  # invocations inside a <# #> block to explain them - a `^\s*#` filter does not exclude those lines, and
  # matching them reports "offline is set after the first scan" against documentation.
  $lpScanM = @($lpGateLines | Select-String -Pattern '&\s+uv\s+run\s+--with\s+pip-licenses|&\s+npx\s+--yes\s+license-checker')
  $lpScanAt = if ($lpScanM.Count) { $lpScanM[0].LineNumber } else { 0 }
  if (-not $lpOffAt) { $lpFindings += 'check-licenses.ps1 找不到 $env:UV_OFFLINE 赋值行——无法判定离线是否在扫描前生效。' }
  elseif ($lpScanAt -and $lpOffAt -ge $lpScanAt) { $lpFindings += "离线设置在第 $lpOffAt 行、首个扫描器调用在第 $lpScanAt 行——设在扫描之后等于没设。" }
  if ($lpFindings.Count) { foreach ($lpF in $lpFindings) { Fail "13a'' [LICENSE-PIN] $lpF" } }
  elseif (-not $fail) { Write-Host '  13a'''' [LICENSE-PIN] OK（uv 二进制钉版本 · ci.yml 有联网预热阶段 · 许可闸在首个扫描器调用之前置 UV_OFFLINE/npm_config_offline）' -ForegroundColor Green }
}
# 13b. gh-bootstrap 建 PUBLIC 仓时防泄露闸须升 -Strict 全历史（TD62/TD-125）——结构断言：
#      脚本在 public 路径（-not $Private）给 check-secrets 加 -Strict，堵「变 public 那刻的历史盲点无任何自动闸把守」。
$ghbPath = Join-Path $PSScriptRoot 'gh-bootstrap.ps1'
if (-not (Test-Path $ghbPath)) { Fail '13b TD62：scripts\gh-bootstrap.ps1 不存在。' }
else {
  $ghbRaw = Get-Content -LiteralPath $ghbPath -Raw
  if ($ghbRaw -notmatch '-Strict') { Fail '13b TD62：gh-bootstrap 全脚本无 -Strict——建 public 仓未做全历史扫描（变 public 前历史盲点）。' }
  elseif ($ghbRaw -notmatch '(?s)Private[\s\S]{0,240}-Strict') { Fail '13b TD62：-Strict 未与 $Private/public 判定关联（应仅在建 public 仓时升 -Strict）。' }
  else { Write-Host '  13b gh-bootstrap 建 public 仓 → check-secrets -Strict 全历史 OK' -ForegroundColor Green }
}
# 13c. （TD63 item12）：在**真正的非 git 目录**（无 .git、无 git 祖先）里真跑 check-secrets.ps1，断言其
# 优雅跳过路径确实生效（exit 0 + ASCII 哨兵 [SECRETS-SKIP-NONGIT]）——补上此前从未被真正验证的这条降级路径。
$ngDir = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-nogit-$PID"
if (Test-Path $ngDir) { Remove-Item -Recurse -Force $ngDir }
New-Item -ItemType Directory -Force $ngDir | Out-Null
Copy-Item (Join-Path $RepoRoot 'scripts') $ngDir -Recurse -Force
