$ngExit = $LASTEXITCODE
Remove-Item -Recurse -Force $ngDir -ErrorAction SilentlyContinue
if ($ngExit -ne 0) { Fail "闸13c：check-secrets.ps1 在真正的非 git 目录（无 .git）里非零退出（$ngExit）——「非 git 仓优雅跳过」路径回归。" }
elseif ($ngOut -notmatch '\[SECRETS-SKIP-NONGIT\]') { Fail "闸13c：check-secrets.ps1 在非 git 目录里退出 0 但输出未命中 ASCII 哨兵 [SECRETS-SKIP-NONGIT]——退出 0 可能来自别的路径，未证真走了「非 git 仓优雅跳过」这一支（L165）。`n输出：$ngOut" }
else { Write-Host '  13c 非 git 目录下 check-secrets 真正优雅跳过 OK（此前该路径零覆盖，TD63 item12）' -ForegroundColor Green }

# 13d. （TD64/TD-127 item7）：ruleset apply 仅凭 CLI 退出码判成功，从不读回校验落地状态——结构断言：
#      脚本在 PUT/POST 成功后应有一次读回 GET，并**逐项**校验 enforcement 与 required_status_checks 是否真落地
#      （R3 catch：初版只查字面 'enforcement' 一词出现，删掉 missingChecks 判断仍能过闸——收紧为逐个关键子表达式）。
if (-not (Test-Path $ghbPath)) { Fail '13d TD64/TD-127 item7：scripts\gh-bootstrap.ps1 不存在。' }
else {
  $ghbRaw13d = Get-Content -LiteralPath $ghbPath -Raw
  $reqSubstrings13d = @(
    'rulesets/$newId',
    "'required_status_checks'",
    'required_status_checks.context',
    'missingChecks',
    'missingChecks.Count -gt 0',
    "enforcement -ne 'active'"
  )
  $missing13d = @($reqSubstrings13d | Where-Object { -not $ghbRaw13d.Contains($_) })
  if ($ghbRaw13d -notmatch '读回校验') { Fail '13d TD64/TD-127 item7：gh-bootstrap 未见读回校验逻辑——ruleset apply 仍只凭 CLI 退出码判成功，不确认 enforcement/必需检查真落地。' }
  elseif ($missing13d.Count -gt 0) { Fail "13d TD64/TD-127 item7：读回校验逻辑不完整，缺少子表达式：$($missing13d -join ' | ')——不足以证明 enforcement 与 required_status_checks 均被逐项比对（而非仅字面出现 'enforcement' 一词）。" }
  else { Write-Host '  13d gh-bootstrap ruleset apply 读回校验 OK（enforcement + required_status_checks 逐项比对，TD64/TD-127 item7）' -ForegroundColor Green }
}

# --- 14. 计数一致性：探针数 / 闸数 的真相源（脚本）须与 docs 里的计数字面量吻合 ---
# 治本：计数（探针 9 / 闸 17）散落多份 docs，手改易漂移。此闸从 triage.ps1（探针真相源）、
# 本脚本（闸真相源）机器数出，反查相关 docs 的字面量是否一致；不符即 Fail。graceful（文件缺失跳过）。
Exit-Gate
}

if (Enter-Gate '14') {
Step '14/17 计数一致性（探针/闸计数 ↔ docs 字面量）'
# 14a. 探针真相源：triage.ps1 里 "# ── 探针 N" 注释行数
$triageForCount = Join-Path $PSScriptRoot 'triage.ps1'
$probeCount = 0
if (Test-Path $triageForCount) {
  $probeCount = @([regex]::Matches((Get-Content $triageForCount -Raw), '(?m)^#\s*──\s*探针\s*\d')).Count
}
# 14b. 闸真相源：本脚本里 Step 'N/M' 的 M（取最大值，即闸总数）
$gateCount = 0
$gateMatches = [regex]::Matches((Get-Content $PSCommandPath -Raw), "Step\s+'\d+/(\d+)\b")
if ($gateMatches.Count) { $gateCount = ($gateMatches | ForEach-Object { [int]$_.Groups[1].Value } | Measure-Object -Maximum).Maximum }

if ($probeCount -lt 1) { Fail '无法从 triage.ps1 机数探针数（"# ── 探针 N" 注释缺失？）。' }
if ($gateCount -lt 1)  { Fail "无法从 selftest.ps1 机数闸总数（Step 'N/M' 缺失？）。" }

if ($probeCount -ge 1 -and $gateCount -ge 1) {
  # 探针计数字面量须吻合的 docs（阿拉伯数字，便于机检）
  $probeDocs = @{
    'docs/LOOP-ENGINEERING.md'        = $probeCount
    '.claude/skills/triage/SKILL.md'  = $probeCount
  }
  # 闸计数字面量须吻合的 docs
  $gateDocs = @{
    'CLAUDE.md'                = $gateCount
    'TEMPLATE-README.md'       = $gateCount
    'docs/DELIVERY-CHAINS.md'  = $gateCount
  }
  # TD98/TD137: $reads is the fix instruction — the offending .md is already named dynamically by $relPath, so the
  # caller only supplies which sub-gate read it and which -Only id re-checks it. Never hardcode a file list here.
  function Test-Count($relPath, $n, $unit, $reads) {
    $p = Join-Path $RepoRoot $relPath
    if (-not (Test-Path $p)) { Write-Host "  $relPath 不存在，跳过。" -ForegroundColor DarkGray; return }
    $raw = Get-Content $p -Raw
    if ($raw -notmatch "\b$n\s*$unit") { Fail "$relPath 缺正确的计数字面量「$n $unit」（真相源 = $n；计数漂移，请同步）。$reads" }
  }
  $reads14a = ' [DOC-GATE-READS 14a] this gate reads the probe-count literal in the .md named above; re-check with: selftest.ps1 -Only 14'
  $reads14b = ' [DOC-GATE-READS 14b] this gate reads the gate-count literal in the .md named above; re-check with: selftest.ps1 -Only 14'
  foreach ($k in $probeDocs.Keys) { Test-Count $k $probeDocs[$k] '探针' $reads14a }
  foreach ($k in $gateDocs.Keys)  { Test-Count $k $gateDocs[$k] '闸' $reads14b }
  if (-not $fail) { Write-Host "  计数一致：探针 $probeCount（triage.ps1）/ 闸 $gateCount（selftest.ps1），docs 字面量吻合" }
}

# 14d. 探针名清单一致性（TD67）：14a 只数不比名——DELIVERY-CHAINS 心跳行曾 7/9 漂移且无机检可拦。
#   按 TD67 行内修法：从 triage.ps1 抽 Add-Finding '<name>' 的名字集合（功能真相源：不 Add-Finding 的探针不上报），
#   先交叉核 14a 的标记计数（防「有标记未注册 / 注册未立标记」的死探针），再断言每名 ⊆ DELIVERY-CHAINS 心跳行、
#   ∈ LOOP-ENGINEERING.md 全文（该文档自述逐一列全）。graceful（文件缺失跳过）。
if (Test-Path $triageForCount) {
  $probeNames = @([regex]::Matches((Get-Content $triageForCount -Raw), "Add-Finding\s+'([a-z][a-z0-9-]*)'") | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique)
  if ($probeNames.Count -lt 1) { Fail '14d TD67：无法从 triage.ps1 抽 Add-Finding 探针名（调用形态漂移？）。' }
  elseif ($probeCount -ge 1 -and $probeNames.Count -ne $probeCount) {
    Fail "14d TD67：Add-Finding 名集合 $($probeNames.Count) 个 ≠ 探针标记 $probeCount 个——存在「有标记未注册」或「注册未立标记」的探针，先对齐 triage.ps1 自身。"
  }
  $dcPath14 = Join-Path $RepoRoot 'docs/DELIVERY-CHAINS.md'
  if (Test-Path $dcPath14) {
    $hbRow14 = @(Get-Content $dcPath14) | Where-Object { $_ -match '^\|\s*心跳\s*/\s*triage' } | Select-Object -First 1
    if (-not $hbRow14) { Fail '14d TD67：DELIVERY-CHAINS.md 找不到心跳行（"| 心跳 / triage"）——行标识漂移或被删。' }
    else { foreach ($n in $probeNames) { if ($hbRow14 -notlike "*$n*") { Fail "14d TD67：DELIVERY-CHAINS.md 心跳行漏列探针「$n」（加/改探针未同步文档枚举）。" } } }
  }
  $lePath14 = Join-Path $RepoRoot 'docs/LOOP-ENGINEERING.md'
  if (Test-Path $lePath14) {
    $leRaw14 = Get-Content $lePath14 -Raw
    foreach ($n in $probeNames) { if ($leRaw14 -notlike "*$n*") { Fail "14d TD67：LOOP-ENGINEERING.md 未提及探针「$n」（该文档自述逐一列全，应同步）。" } }
  }
  if (-not $fail) { Write-Host "  14d 探针名清单一致（$($probeNames.Count) 名：Add-Finding ↔ 标记计数 ↔ DELIVERY-CHAINS 心跳行 ↔ LOOP-ENGINEERING）OK" -ForegroundColor Green }
}

# 14c. lens 计数一致性：从 workflow 源（真相源）机数，反查工作流+docs 里的计数字面量。
#   治本「7-vs-8 lens」这类漂移——plan-forge 的 lens 散落多份 docs，
#   加 lens 时易漏改字面量；此处从 .mjs 的 key: 条目机数，断言相关文件含正确计数字面量（缺即漂移）。
$pfPath  = Join-Path $RepoRoot '.claude/workflows/plan-forge.mjs'
$lensCount = 0
if (Test-Path $pfPath)  { $lensCount  = @([regex]::Matches((Get-Content $pfPath -Raw),  "(?m)^\s*key:\s*'")).Count }
# 字面量须与数字**相邻**（数字 + 可选「个」+ 关键词），避免同行其它数字误判。
function Test-CountAdjacent($relPath, $n, $kwRe, $label) {
  $p = Join-Path $RepoRoot $relPath
  if (-not (Test-Path $p)) { Write-Host "  $relPath 不存在，跳过。" -ForegroundColor DarkGray; return }
  if ((Get-Content $p -Raw) -notmatch "\b$n\s*(?:个\s*)?(?:$kwRe)") {
    Fail "$relPath 缺正确的 $label 计数字面量「$n …($kwRe)」（真相源=$n；lens/角度计数漂移，请同步）。"
  }
}
if ($lensCount -lt 1)  { Fail "无法从 plan-forge.mjs 机数 lens 数（key: 条目缺失？）。" }
if ($lensCount -ge 1) {
  foreach ($f in @('.claude/workflows/plan-forge.mjs', 'docs/IDEA-TO-PLAN.md', 'docs/idea-to-plan-diagram.html', 'docs/scaffold-architecture.html')) {
    Test-CountAdjacent $f $lensCount 'lens|透镜' 'lens'
  }
}
if (-not $fail) { Write-Host "  lens 计数一致：lens $lensCount（plan-forge.mjs），工作流+docs 字面量吻合" }

# 14e. 「执行边界」节同步（CLAUDE.md「文档同步」硬规则的机检化）：该节是每轮必载的行为红线，
#   CLAUDE.md 与 CLAUDE.template.md 各持一份、此前仅靠人工同步——无机检可拦漂移或红线被无声删改。
#   断言：① 两文件「## 执行边界」节逐字一致（case-sensitive，连行尾一起比）；② 必备红线锚点在场
#   （测试篡改禁令 / 「完成与词义」/ 虚构禁令）。已初始化下游无模板，跳过。
if ($isPostInit) { Write-Host '  14e 已初始化（无 CLAUDE.template.md），跳过执行边界同步比对。' -ForegroundColor DarkGray }
else {
  # TD98/TD137: every 14e failure carries the .md pair this gate read plus the -Only id that re-checks it.
  $reads14e = ' [DOC-GATE-READS 14e] this gate reads the two execution-boundary documents named above; after editing either, re-check with: selftest.ps1 -Only 14'
  $ebPat = '(?s)## 执行边界.*?(?=\r?\n## )'
  $ebCm = [regex]::Match((Get-Content (Join-Path $RepoRoot 'CLAUDE.md') -Raw), $ebPat).Value
  $ebCt = [regex]::Match((Get-Content (Join-Path $RepoRoot 'CLAUDE.template.md') -Raw), $ebPat).Value
  if (-not $ebCm) { Fail ('14e：CLAUDE.md 缺「## 执行边界」节（每轮必载的行为红线被删？）。' + $reads14e) }
  elseif (-not $ebCt) { Fail ('14e：CLAUDE.template.md 缺「## 执行边界」节（下游将失去行为红线）。' + $reads14e) }
  elseif ($ebCm -cne $ebCt) { Fail ('14e：「执行边界」节两文件不一致——CLAUDE.md ↔ CLAUDE.template.md 须逐字同步（CLAUDE.md「文档同步」硬规则）。' + $reads14e) }
  else {
    foreach ($anchor in @('弱化断言', '完成与词义', '虚构机密/端点')) {
      if (-not $ebCm.Contains($anchor)) { Fail "14e：执行边界节缺必备红线锚点「$anchor」（红线被无声移除/改写）。$reads14e" }
    }
    # 模板「硬边界」敏感面基线（0.26.3 新增，属「## 硬边界」节、执行边界比对够不着）：
    # 认证/计费/迁移/生产配置 → FrozenPaths 的安全红线须在「## 硬边界」节**内**在场且同行提及 FrozenPaths。
    # 节内定位（非全文搜索）：防被无声删除，也防被移出硬边界节（如挪进注释/无约束力段落）后仍假绿。
    $ctRaw14e = Get-Content (Join-Path $RepoRoot 'CLAUDE.template.md') -Raw
    $hbCt = [regex]::Match($ctRaw14e, '(?s)## 硬边界.*?(?=\r?\n## )').Value
    if (-not $hbCt) { Fail ('14e：CLAUDE.template.md 缺「## 硬边界」节（模板骨架被删改？）。' + $reads14e) }
    elseif ($hbCt -notmatch '敏感面无人值守不动[^\r\n]*FrozenPaths') {
      Fail ('14e：CLAUDE.template.md「## 硬边界」节内缺「敏感面无人值守不动…FrozenPaths」基线（被无声删除、移出硬边界节、或与 FrozenPaths 脱钩）。' + $reads14e)
    }
    if (-not $fail) { Write-Host '  14e 执行边界节同步 + 模板硬边界敏感面基线 OK（逐字一致 + 红线/基线锚点在场）' -ForegroundColor Green }
  }
}
# 14e continuation.  The initialized project has no CLAUDE.template.md, but its operational authority still
# has to follow the executable review policy and CI workflow.  Read the policy and workflow as the sources of
# truth, then inspect only the bounded local-ship instruction and the two architecture nodes: this verifies
# the operator contract without making a brittle second copy of either manifest.
$cfg14eOps = Get-Content (Join-Path $RepoRoot 'scripts/_config.ps1') -Raw
$ci14eOps = Get-Content (Join-Path $RepoRoot '.github/workflows/ci.yml') -Raw
$verify14eOps = Get-Content (Join-Path $RepoRoot 'scripts/verify.ps1') -Raw
$devops14eOps = Get-Content (Join-Path $RepoRoot 'docs/DEVOPS-WORKFLOW.md') -Raw
$deliveryChains14eOps = Get-Content (Join-Path $RepoRoot 'docs/DELIVERY-CHAINS.md') -Raw
$task14eOps = Get-Content (Join-Path $RepoRoot 'scripts/task.ps1') -Raw
$taskLoop14eOps = Get-Content (Join-Path $RepoRoot '.claude/skills/task-loop/SKILL.md') -Raw
$architecture14eOps = Get-Content (Join-Path $RepoRoot 'docs/scaffold-architecture.html') -Raw
$localShip14eOps = [regex]::Match($devops14eOps, '(?m)^#\s+无远端.*-Local.*$').Value
$localSkill14eOps = [regex]::Match($taskLoop14eOps, '\*\*无远端的本地 T0\*\*：[^\r\n]*?。').Value
$taskNode14eOps = [regex]::Match($architecture14eOps, '(?s)<article\b[^>]*data-self="task"[^>]*>.*?</article>').Value
$verifyNode14eOps = [regex]::Match($architecture14eOps, '(?s)<article\b[^>]*data-self="verify"[^>]*>.*?</article>').Value
$configRequires14eOps = $cfg14eOps -match "(?m)^\s*ReviewGate\s*=\s*'required'\s*$"
$ciWindows14eOps = $ci14eOps -match '(?m)^\s*runs-on:\s*windows-latest\s*$'
$ciBootstrap14eOps = ($ci14eOps -match '(?m)^\s*uses:\s*actions/setup-java@') -and ($ci14eOps -match '(?m)^\s*uses:\s*android-actions/setup-android@') -and ($ci14eOps -match '(?ms)^\s*working-directory:\s*android\s*$.*?^\s*cmd /c gradlew\.bat --no-daemon build\s*$')
$ciOffline14eOps = $ci14eOps -match '(?m)gradlew\.bat\s+--offline\b'
$verifyGoldenE2e14eOps = ($verify14eOps -match ':core:e2eTest') -and ($verify14eOps -match '\[GATE2-MISSING\]') -and ($verify14eOps -match '\[GATE2-NOT-RUN\]')
$localReviewContract14eOps = {
  param([string]$Line)
  ($Line -match '-Local') -and ($Line -match "ReviewGate='required'") -and ($Line -match 'fail-closed') -and ($Line -notmatch '无 Codex|可选评审')
}
$candidateDeadlineDocContract14eOps = {
  param([string]$Document, [string]$TaskSource)
  $findings = @()
  if ($TaskSource -notmatch '(?s)\$mergeRun\s*=\s*Invoke-GhBeforeDeadline\s+-Arguments\s+@\(\x27pr\x27,\x27merge\x27.*?\)\s+-Deadline\s+\$ciDeadline') { $findings += 'task.ps1 no longer runs the PR merge through Invoke-GhBeforeDeadline with ciDeadline; review the documented deadline boundary against the executable flow.' }
  if ($TaskSource -notmatch '(?s)# T24-MERGETOKEN.*?\& git -C \$RepoRoot rev-parse --git-common-dir') { $findings += 'task.ps1 no longer has the documented post-merge bare T24 git rev-parse read; review the documented T24 boundary against the executable flow.' }
  if ($TaskSource -notmatch '(?s)# T24-MERGETOKEN.*?\& gh pr view \$pr --json \x27state,headRefOid\x27') { $findings += 'task.ps1 no longer has the documented post-merge bare T24 gh read; review the documented T24 boundary against the executable flow.' }
  if ($Document -match '\[CI-GATE-PASS\] 后的 merge/T24 不在此 deadline 内') { $findings += 'DELIVERY-CHAINS still says merge/T24 are outside the deadline although merge consumes the shared ciDeadline.' }
  if ($Document -notmatch '自动 merge 使用 `ciDeadline` 的剩余预算') { $findings += 'DELIVERY-CHAINS does not state that automatic merge consumes the shared ciDeadline remaining budget.' }
  if ($Document -notmatch 'T24 凭据铸造.*裸 `gh pr view` / `git rev-parse`.*不声明 deadline 或 containment 保障') { $findings += 'DELIVERY-CHAINS does not accurately limit its T24 claim to the current bare reads without a declared deadline/containment guarantee.' }
  return @($findings)
}
$candidateDeadlineFindings14eOps = @(& $candidateDeadlineDocContract14eOps $deliveryChains14eOps $task14eOps)
if ($deliveryChains14eOps -match '自动 merge 使用 `ciDeadline` 的剩余预算；成功后的 T24 凭据铸造仍是裸 `gh pr view` / `git rev-parse` 读取，当前不声明 deadline 或 containment 保障。') {
  $staleCandidateDeadline14eOps = $deliveryChains14eOps -replace '自动 merge 使用 `ciDeadline` 的剩余预算；成功后的 T24 凭据铸造仍是裸 `gh pr view` / `git rev-parse` 读取，当前不声明 deadline 或 containment 保障。', '[CI-GATE-PASS] 后的 merge/T24 不在此 deadline 内'
  if ($staleCandidateDeadline14eOps -ceq $deliveryChains14eOps) { Fail '14e setup: candidate deadline stale-document replacement did not change the current documentation; the negative control is not exercising its intended input.' }
  elseif ((@(& $candidateDeadlineDocContract14eOps $staleCandidateDeadline14eOps $task14eOps)).Count -eq 0) { Fail '14e setup: candidate deadline documentation matcher accepts the preserved stale merge/T24-outside-deadline claim; its negative control is vacuous.' }
}
$staleLocalShip14eOps = '#   无远端 / 无 Codex 的本地 T0：加 -Local（DoD + 可选评审后**本地**合并，不 push/PR/gh）'
if (-not $configRequires14eOps) { Fail '14e setup: _config.ps1 no longer sets ReviewGate=''required''; revise this documentation contract with the executable policy instead of judging a stale regime.' }
elseif (& $localReviewContract14eOps $staleLocalShip14eOps) { Fail '14e setup: the local-review matcher accepted the preserved stale -Local guidance; it would not independently catch optional/no-Codex drift.' }
elseif (-not (& $localReviewContract14eOps $localShip14eOps)) { Fail '14e [DOC-REVIEW-REQUIRED] DEVOPS-WORKFLOW local ship guidance does not bind -Local to ReviewGate=''required'' and fail-closed R3; it can falsely teach a no-Codex local merge.' }
elseif (-not (& $localReviewContract14eOps $localSkill14eOps)) { Fail '14e [DOC-REVIEW-REQUIRED] task-loop skill local ship guidance does not bind -Local to ReviewGate=''required'' and fail-closed R3.' }
elseif (($taskNode14eOps -notmatch "ReviewGate='required'") -or ($taskNode14eOps -notmatch '-Local') -or ($taskNode14eOps -notmatch 'fail-closed')) { Fail '14e [DOC-REVIEW-REQUIRED] scaffold architecture task-loop node does not bind -Local to the configured required R3/fail-closed contract.' }
elseif ($taskNode14eOps -match '可选第二意见|无远端 / 无 Codex') { Fail '14e [DOC-REVIEW-OPTIONAL-DRIFT] scaffold architecture task-loop node still calls the review optional or says no Codex can locally complete the loop while ReviewGate is required.' }
elseif (-not $ciWindows14eOps -or -not $ciBootstrap14eOps -or -not $ciOffline14eOps) { Fail '14e setup: ci.yml no longer has the Windows runner, Java/Android setup, online Gradle bootstrap, and offline Gradle verification contract this sync check reads.' }
elseif (-not $verifyGoldenE2e14eOps) { Fail '14e setup: verify.ps1 no longer declares the Golden Evidence :core:e2eTest as mandatory for missing or unexecuted Gate 2; revise the document contract with the executable verification policy.' }
elseif (($verifyNode14eOps -notmatch 'windows-latest') -or ($verifyNode14eOps -notmatch 'online bootstrap') -or ($verifyNode14eOps -notmatch 'offline verify') -or ($verifyNode14eOps -notmatch 'Golden Evidence JVM') -or ($verifyNode14eOps -notmatch ':core:e2eTest') -or ($verifyNode14eOps -notmatch 'fail-closed')) { Fail '14e [DOC-CI-PLATFORM] scaffold architecture CI verify node does not describe the actual Windows runner, online bootstrap/offline verify, and mandatory Golden Evidence :core:e2eTest contract.' }
elseif ($verifyNode14eOps -match 'ubuntu-latest|无网络') { Fail '14e [DOC-CI-PLATFORM-DRIFT] scaffold architecture CI verify node still describes an Ubuntu or wholly no-network CI job despite the Windows/bootstrap workflow.' }
elseif ($candidateDeadlineFindings14eOps.Count -gt 0) { Fail ('14e [DOC-CI-DEADLINE-SYNC] ' + ($candidateDeadlineFindings14eOps -join ' | ')) }
elseif (-not $fail) { Write-Host '  14e [DOC-R3-CI-SYNC] required local R3 and Windows bootstrap/offline verify documentation agree with _config.ps1 and ci.yml' -ForegroundColor Green }

# 14j. T97-GENERATOR-SWEEP: every card generator must know the card fields check-cards can REJECT a card
#   for. T94 added [CARD-SWEEP] to check-cards and nothing that projects a card learned it, so a projected
#   cross-cutting card was born rejected at the next -Phase start. This is drift between two sources, which
#   is what gate 14 already owns - no new gate and no new -Only id, and the [GATE-MAP] row for
#   .claude/workflows/*.mjs already routes here. A generator must both ACCEPT the field (a schema
#   property) and ASK for it (its own slash-separated field enumeration in the prompt): a file-level
#   mention would be satisfied by a comment alone, and the enumeration is the half that claims to be
#   exhaustive. Whether the field belongs in a generator's `required` list is deliberately NOT asserted -
#   the rule is conditional on the allow_paths count, and requiring it of every card would make the model
#   invent a sweep for cards that never needed one. Absent generator = downstream trim, skip.
#   TD180 NARROWED THE SUBJECT LIST, and the distinction matters: plan-forge.mjs was dropped because it
#   STOPPED BEING A CARD GENERATOR (its Decompose phase and CARDS_SCHEMA were deleted so that projection
#   has a single owner), not because the rule was relaxed to buy a green run. The rule is untouched and
#   still binds every generator that still projects cards - today exactly one. The wrong repair, had this
#   list been left alone, was to keep a dead CARDS_SCHEMA alive in plan-forge purely so this grep still
#   hits, which would have re-created the second projector TD180 exists to delete while printing OK.
foreach ($gen14j in @('.claude/workflows/decompose-cards.mjs')) {
  $genPath14j = Join-Path $RepoRoot $gen14j
  if (-not (Test-Path -LiteralPath $genPath14j -PathType Leaf)) {
    Write-Host "  14j skipped for $gen14j (absent - normal in a trimmed downstream)." -ForegroundColor DarkGray
    continue
  }
  $genText14j = [System.IO.File]::ReadAllText($genPath14j)
  $missing14j = @()
  if ($genText14j -notmatch '(?m)^[ \t]*sweep[ \t]*:[ \t]*\{') { $missing14j += "a 'sweep' property in its card schema (so a projected card carrying the field is not dropped)" }
  if ($genText14j -notmatch '/sweep/') { $missing14j += "'sweep' in the slash-separated per-card field enumeration in its prompt (so the model is actually asked for it)" }
  if ($missing14j.Count -gt 0) {
    Fail ("14j card-contract drift: $gen14j lacks " + ($missing14j -join ' AND ') + ". check-cards.ps1 rejects a card declaring more than five allow_paths with no non-empty 'sweep:' field ([CARD-SWEEP], T94, regression 10h), so this generator projects a card that is rejected the moment someone runs task.ps1 -Phase start on it. [FIX] the generator changes, never the rule: add the field to the schema and to the field enumeration, and state the >5 condition there. Re-check with: selftest.ps1 -Only 14")
  }
}
if (-not $fail) { Write-Host '  14j OK: decompose-cards.mjs - the single card generator since TD180 - accepts and asks for the sweep field check-cards can reject a card for (T97)' -ForegroundColor Green }

# T38-DOCDRIFT
function Get-DocDriftMissing {
  param(
    [string[]]$ChangedFiles,
    [hashtable]$Map,
    [bool]$EscapeHatch
  )
  if ($EscapeHatch -or $null -eq $Map -or $Map.Count -eq 0) { return @() }

  # 大小写敏感比对（R3 #10）：git 在 Linux CI 上路径大小写敏感——用大小写不敏感的 -match/-notcontains
  # 会让错大小写的 docs/devops-workflow.md 假冒满足 docs/DEVOPS-WORKFLOW.md 耦合，令 drift 漏网。故用 -cmatch/-cnotcontains。
  $missing = [System.Collections.Generic.List[string]]::new()
  foreach ($sourcePattern in @($Map.Keys)) {
    $sourceChanged = $false
    foreach ($changedFile in @($ChangedFiles)) {
      if ($changedFile -cmatch [string]$sourcePattern) {
        $sourceChanged = $true
        break
      }
    }
    if (-not $sourceChanged) { continue }

    foreach ($docPath in @($Map[$sourcePattern])) {
      $docPath = [string]$docPath
      if ($ChangedFiles -cnotcontains $docPath) { $missing.Add($docPath) }
    }
  }
  return @($missing | Sort-Object -Unique)
}

