# base/skip 决策抽成可测函数（R3 #6）：入=仓路径，出= @{Skip='原因'} 或 @{Base=sha;Changed=@();Messages=@()}。
# 抽出后无-base 各态可用临时仓夹具真跑（此前仅对 ambient 检出跑、坏 skip 分支无从捕获）。
# $PSNativeCommandUseErrorActionPreference 局部置 false（原生命令正常返回非零按退出码判、不终止），finally 复位——
# 修原内联版「置 false 后不复位、污染后续闸」的隐患。
function Get-DocDriftBaseOrSkip {
  param([Parameter(Mandatory)][string]$RepoPath)
  if (-not (Get-Command git -ErrorAction SilentlyContinue)) { return @{ Skip = 'git 未安装' } }
  # R3 r4 #10：$PSNativeCommandUseErrorActionPreference 仅 PS 7.3+ 内置；仓约束 7.0+，StrictMode 下读未定义变量会抛。
  # Test-Path variable: 安全探测存否（不抛），缺则以 7.3+ 默认值 $true 回退，finally 一致复位。
  $prevNative = if (Test-Path variable:PSNativeCommandUseErrorActionPreference) { $PSNativeCommandUseErrorActionPreference } else { $true }
  $PSNativeCommandUseErrorActionPreference = $false
  try {
    $headRef = @(& git -C $RepoPath symbolic-ref --quiet --short HEAD 2>$null)
    if ($LASTEXITCODE -ne 0 -or $headRef.Count -eq 0 -or -not $headRef[0]) { return @{ Skip = 'HEAD detached 或分支不可解析' } }
    $head = @(& git -C $RepoPath rev-parse --verify 'HEAD^{commit}' 2>$null)
    if ($LASTEXITCODE -ne 0 -or $head.Count -eq 0 -or -not $head[0]) { return @{ Skip = '首提交尚未建立或 HEAD 不可解析' } }
    $shallow = @(& git -C $RepoPath rev-parse --is-shallow-repository 2>$null)
    if ($LASTEXITCODE -ne 0 -or $shallow.Count -eq 0) { return @{ Skip = '无法判定 shallow 状态' } }
    if ([string]$shallow[0] -eq 'true') { return @{ Skip = 'shallow repository' } }
    $master = @(& git -C $RepoPath rev-parse --verify 'master^{commit}' 2>$null)
    if ($LASTEXITCODE -ne 0 -or $master.Count -eq 0 -or -not $master[0]) { return @{ Skip = 'master 不可解析' } }
    $mb = @(& git -C $RepoPath merge-base HEAD master 2>$null)
    if ($LASTEXITCODE -ne 0 -or $mb.Count -eq 0 -or -not $mb[0]) { return @{ Skip = 'merge-base 不可解析' } }
    $base = ([string]$mb[0]).Trim()
    # 与范围闸同款硬化（R3 #10）：core.quotepath=false 令非 ASCII 路径不被 C-quote；
    # diff.renames=false 令改名显示为 old+new 两路径（不折叠成目的地），保 mapped 源改名后旧路径仍在 Changed、不逃检。
    # 变更集 = 已提交 base..HEAD（R3 r4 #6a：align diff and commit ordering）。14f 在 selftest 内运行，强制点 =
    # CI(push/PR) 或提交后本地自检——**非** ship 的 pre-commit DoD（卡的 pre-commit DoD 是 dod_command）。故变更集与
    # [doc-sync:none] 逃生门同源于【已提交】历史，语义自洽（若含未提交改动，逃生门（提交信息）无从表达 → R3 r3↔r4 张力，取 r4 收敛解）。
    $changed = @(& git -C $RepoPath -c core.quotepath=false -c diff.renames=false diff --name-only $base HEAD 2>$null)
    if ($LASTEXITCODE -ne 0) { return @{ Skip = 'git diff 失败' } }
    $messages = @(& git -C $RepoPath log '--format=%B' "$base..HEAD" 2>$null)
    if ($LASTEXITCODE -ne 0) { return @{ Skip = 'git log 失败' } }
    return @{ Base = $base; Changed = $changed; Messages = $messages }
  }
  catch { return @{ Skip = 'git 元数据读取异常' } }
  finally { $PSNativeCommandUseErrorActionPreference = $prevNative }
}

# fail-open 状态夹具（R3 #6，仿 15 系临时仓）：每个无-base 态断言返回 Skip、绝不 Fail；
# 正例（正常仓 master 祖先）须返回 Base——否则 Skip 断言在「恒 Skip」实现下全 vacuous（正例即非-vacuous 证明）。
if (Get-Command git -ErrorAction SilentlyContinue) {
  $docDriftFoOk = $true
  $foRoot = Join-Path ([System.IO.Path]::GetTempPath()) ('docdrift-fo-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
  New-Item -ItemType Directory -Force -Path $foRoot | Out-Null
  $prevFoNative = if (Test-Path variable:PSNativeCommandUseErrorActionPreference) { $PSNativeCommandUseErrorActionPreference } else { $true }
  $PSNativeCommandUseErrorActionPreference = $false
  try {
    function New-FoRepo([string]$Name) {
      $p = Join-Path $foRoot $Name
      New-Item -ItemType Directory -Force -Path $p | Out-Null
      & git -C $p init -q 2>$null
      & git -C $p config user.email 'fo@t' 2>$null
      & git -C $p config user.name 'fo' 2>$null
      return $p
    }
    function Assert-FoSkip([hashtable]$D, [string]$Label) {
      if (-not $D.ContainsKey('Skip')) { Fail "14f fail-open($Label)：无-base 态未 skip（返回 $($D.Keys -join ',')）。"; $script:docDriftFoOk = $false }
    }
    Assert-FoSkip (Get-DocDriftBaseOrSkip -RepoPath (New-FoRepo 'unborn')) 'unborn'
    $rDet = New-FoRepo 'detached'; Set-Content (Join-Path $rDet 'a.txt') 'x'; & git -C $rDet add -A 2>$null; & git -C $rDet commit -qm c1 2>$null
    $detSha = ([string](@(& git -C $rDet rev-parse HEAD 2>$null)[0])).Trim(); & git -C $rDet checkout -q $detSha 2>$null
    Assert-FoSkip (Get-DocDriftBaseOrSkip -RepoPath $rDet) 'detached'
    $rNM = New-FoRepo 'nomaster'; & git -C $rNM checkout -q -b work 2>$null; Set-Content (Join-Path $rNM 'a.txt') 'x'; & git -C $rNM add -A 2>$null; & git -C $rNM commit -qm c1 2>$null
    Assert-FoSkip (Get-DocDriftBaseOrSkip -RepoPath $rNM) 'no-master'
    $rOr = New-FoRepo 'orphan'; & git -C $rOr checkout -q -b master 2>$null; Set-Content (Join-Path $rOr 'a.txt') 'x'; & git -C $rOr add -A 2>$null; & git -C $rOr commit -qm c1 2>$null
    & git -C $rOr checkout -q --orphan orphanbr 2>$null; Set-Content (Join-Path $rOr 'b.txt') 'y'; & git -C $rOr add -A 2>$null; & git -C $rOr commit -qm c2 2>$null
    Assert-FoSkip (Get-DocDriftBaseOrSkip -RepoPath $rOr) 'no-merge-base'
    $rOk = New-FoRepo 'okbase'; & git -C $rOk checkout -q -b master 2>$null; Set-Content (Join-Path $rOk 'a.txt') 'x'; & git -C $rOk add -A 2>$null; & git -C $rOk commit -qm c1 2>$null
    & git -C $rOk checkout -q -b feature 2>$null; Set-Content (Join-Path $rOk 'b.txt') 'y'; & git -C $rOk add -A 2>$null; & git -C $rOk commit -qm c2 2>$null
    $okD = Get-DocDriftBaseOrSkip -RepoPath $rOk
    # 正例须 Base 在场 + Changed/Messages 真填充（R3 #6）：恒空数组会让 real-run 恒绿而生产闸 vacuous。
    if (-not $okD.ContainsKey('Base')) { Fail '14f fail-open(正例)：正常仓（master 祖先）未返回 Base，Skip 断言恐全 vacuous。'; $docDriftFoOk = $false }
    elseif (@($okD.Changed) -cnotcontains 'b.txt') { Fail '14f fail-open(正例)：Base 返回但 Changed 未含已提交文件 b.txt（Changed 恐恒空、real-run vacuous）。'; $docDriftFoOk = $false }
    elseif ((@($okD.Messages) -join "`n") -cnotmatch 'c2') { Fail '14f fail-open(正例)：Messages 未含提交信息 c2（escape hatch 检测恐 vacuous）。'; $docDriftFoOk = $false }
    # 决策端到端（R3 #6）：mapped 源变更缺配对 doc → 经 BaseOrSkip+DocDriftMissing 真报缺失；追加 [doc-sync:none] 提交 → 豁免为空。
    $rDec = New-FoRepo 'decide'; & git -C $rDec checkout -q -b master 2>$null; New-Item -ItemType Directory -Force -Path (Join-Path $rDec 'scripts') | Out-Null; Set-Content (Join-Path $rDec 'seed.txt') 's'; & git -C $rDec add -A 2>$null; & git -C $rDec commit -qm seed 2>$null
    & git -C $rDec checkout -q -b feature 2>$null; Set-Content (Join-Path $rDec 'scripts/task.ps1') 'x'; & git -C $rDec add -A 2>$null; & git -C $rDec commit -qm 'touch mapped source' 2>$null
    $decMap = @{ 'scripts/task\.ps1' = @('docs/DEVOPS-WORKFLOW.md') }
    $decD = Get-DocDriftBaseOrSkip -RepoPath $rDec
    $decMiss = @(Get-DocDriftMissing -ChangedFiles @($decD.Changed) -Map $decMap -EscapeHatch ((@($decD.Messages) -join "`n").Contains('[doc-sync:none]')))
    if ($decMiss -cnotcontains 'docs/DEVOPS-WORKFLOW.md') { Fail '14f real-run 决策：mapped 源变更缺配对 doc 未报缺失。'; $docDriftFoOk = $false }
    & git -C $rDec commit -q --allow-empty -m 'ack drift [doc-sync:none]' 2>$null
    $decD2 = Get-DocDriftBaseOrSkip -RepoPath $rDec
    $decMiss2 = @(Get-DocDriftMissing -ChangedFiles @($decD2.Changed) -Map $decMap -EscapeHatch ((@($decD2.Messages) -join "`n").Contains('[doc-sync:none]')))
    if ($decMiss2.Count -ne 0) { Fail '14f real-run 决策：[doc-sync:none] 逃生门未豁免缺失。'; $docDriftFoOk = $false }
    # CJK 路径（R3 #10）：core.quotepath=false → 非 ASCII 路径原样出现在 Changed（非 C-quote 的 "\344..."）。
    $rCjk = New-FoRepo 'cjk'; & git -C $rCjk checkout -q -b master 2>$null; Set-Content (Join-Path $rCjk 'seed.txt') 's'; & git -C $rCjk add -A 2>$null; & git -C $rCjk commit -qm seed 2>$null
    & git -C $rCjk checkout -q -b feature 2>$null; Set-Content (Join-Path $rCjk '你好.txt') 'x'; & git -C $rCjk add -A 2>$null; & git -C $rCjk commit -qm cjk 2>$null
    $cjkD = Get-DocDriftBaseOrSkip -RepoPath $rCjk
    if (@($cjkD.Changed) -cnotcontains '你好.txt') { Fail "14f real-run(CJK)：非 ASCII 路径未原样出现在 Changed（core.quotepath=false 未生效，得到 $(@($cjkD.Changed) -join ',')）。"; $docDriftFoOk = $false }
    # mapped 源改名（R3 #10）：diff.renames=false → 改名显示为 old+new，旧路径 scripts/task.ps1 在场→源仍被检出、不逃检。
    $rRen = New-FoRepo 'rename'; & git -C $rRen checkout -q -b master 2>$null; New-Item -ItemType Directory -Force -Path (Join-Path $rRen 'scripts') | Out-Null; Set-Content (Join-Path $rRen 'scripts/task.ps1') ('x' * 200); & git -C $rRen add -A 2>$null; & git -C $rRen commit -qm seed 2>$null
    & git -C $rRen checkout -q -b feature 2>$null; & git -C $rRen mv 'scripts/task.ps1' 'scripts/renamed.ps1' 2>$null; & git -C $rRen commit -qm 'rename mapped source' 2>$null
    $renD = Get-DocDriftBaseOrSkip -RepoPath $rRen
    if (@($renD.Changed) -cnotcontains 'scripts/task.ps1') { Fail "14f real-run(rename)：改名 mapped 源的旧路径未在 Changed（diff.renames=false 未生效，源逃检，得到 $(@($renD.Changed) -join ',')）。"; $docDriftFoOk = $false }
    # shallow（R3 r5 #6b）：克隆【master 分支】（--branch master → 本地 master 可解析），令唯一 skip 理由 = shallow；
    # 断言 skip 理由【精确】= 'shallow repository'。若 shallow 检测被破坏，会落到 master 可解析→返回 Base，测转红（非从别的 skip 路径蒙混）。
    $rSh = Join-Path $foRoot 'shallow'; & git clone -q --depth 1 --branch master ("file:///" + ((Join-Path $foRoot 'okbase') -replace '\\', '/')) $rSh 2>$null
    if (Test-Path (Join-Path $rSh '.git')) {
      $shD = Get-DocDriftBaseOrSkip -RepoPath $rSh
      if ($shD['Skip'] -ne 'shallow repository') { Fail "14f fail-open(shallow)：期望 skip 理由『shallow repository』，实得『$($shD.Keys -join ',')=$($shD['Skip'])』（master 可解析下唯一 skip 应为 shallow；检测恐失效）。"; $docDriftFoOk = $false }
    }
    else { Write-Host '  14f fail-open(shallow) 跳过（浅克隆未成）。' -ForegroundColor DarkGray }
  }
  finally {
    $PSNativeCommandUseErrorActionPreference = $prevFoNative
    Remove-Item -Recurse -Force $foRoot -ErrorAction SilentlyContinue
  }
  if ($docDriftFoOk) { Write-Host '  14f fail-open + 硬化夹具 OK（unborn/detached/no-master/no-merge-base/shallow skip + 正常仓 base/Changed/Messages + 决策端到端 + CJK/quotepath + 改名/renames=false）' -ForegroundColor Green }
}
else {
  Write-Host '  14f fail-open 状态夹具跳过（git 未安装）。' -ForegroundColor DarkGray
}

$docDriftDecision = Get-DocDriftBaseOrSkip -RepoPath $RepoRoot
if ($docDriftDecision.ContainsKey('Skip')) {
  Write-Host "  14f real-run 跳过（$($docDriftDecision.Skip)）。" -ForegroundColor DarkGray
}
else {
  $docDriftEscape = (@($docDriftDecision.Messages) -join "`n").Contains('[doc-sync:none]')
  $docDriftMissing = @(Get-DocDriftMissing -ChangedFiles @($docDriftDecision.Changed) -Map (Get-ScaffoldDocSyncMap) -EscapeHatch $docDriftEscape)
  if ($docDriftMissing.Count -gt 0) {
    Fail "14f doc-drift：源脚本已变更但缺配对文档：$($docDriftMissing -join ', ')"
  }
  else {
    Write-Host '  14f real-run DocSyncMap 耦合 OK' -ForegroundColor Green
  }
}

Step '14g/17 doc budgets (DocBudgets character ceilings)'
# T89-DOCBUDGETS: every-turn context is the scarcest resource in the system, and until now its only governor was
# the advisory harness-refresh triage probe, which reports but never blocks. The manifest is declared data in
# _config.ps1 (DocBudgets) and the judgement lives in _guard.ps1 (Test-ScaffoldDocBudget); this sub-gate only runs
# the checker on the real manifest, so no new gate and no new -Only id are introduced - 14 already owns doc drift.
# Meta-repo only, mirroring 14f's production-map assertion: init renames CLAUDE.template.md and -Cleanup deletes
# TEMPLATE-README.md, so the shipped ceilings describe the upstream tree, not a downstream one. A downstream
# declares its own manifest, or leaves it empty (@{}) and the check is a no-op (graceful-degrade rule).
. (Join-Path $PSScriptRoot '_guard.ps1')
if ($isPostInit) {
  Write-Host '  14g skipped (post-init: the shipped ceilings describe the upstream scaffold tree - declare your own DocBudgets in scripts/_config.ps1).' -ForegroundColor DarkGray
}
else {
  # TD98/TD137: the failure text is the fix instruction, and every finding already names the .md it read, so the
  # caller only supplies which sub-gate read it and which -Only id re-checks it. Never hardcode a file list here.
  $reads14g = ' [DOC-GATE-READS 14g] this gate reads the .md named above and counts its characters; after editing it, re-check with: selftest.ps1 -Only 14'
  $budgetFindings = @(Test-ScaffoldDocBudget)
  if ($budgetFindings.Count -gt 0) {
    foreach ($bf in $budgetFindings) { Fail "14g doc budget: $bf$reads14g" }
  }
  else {
    Write-Host "  14g doc budgets OK ($((Get-ScaffoldDocBudgets).Count) standing docs within their character ceilings)" -ForegroundColor Green
  }
  # 14g' [RESIDENT-BUDGET] (T150): the ALWAYS-ON payload, which the six standing-doc ceilings above do not
  # describe. The 17 skill `description:` blocks ride in the system prompt on every turn and had never been
  # counted, while CLAUDE.md sat at 98.7% of a machine-enforced ratchet - the surface under a ratchet was
  # being squeezed while the surface beside it grew freely. Rides 14g rather than taking a gate number:
  # same question, same unit, same empty-is-off contract.
  if (@(Test-ScaffoldResidentBudgetExamples).Count -ne 0) {
    foreach ($rbE in @(Test-ScaffoldResidentBudgetExamples)) { Fail "14g' probe: $rbE" }
  }
  else {
    $rbMeasure = Get-ScaffoldSkillDescriptionSize -SkillRoot (Join-Path $RepoRoot '.claude/skills')
    $rbMeasured = @{ 'SkillDescriptions' = [int]$rbMeasure.Total }
    $rbClaude = Join-Path $RepoRoot 'CLAUDE.md'
    if (Test-Path $rbClaude) { $rbMeasured['CLAUDE.md'] = [System.IO.File]::ReadAllText($rbClaude).Length }
    $rbFindings = @(Test-ScaffoldResidentBudget -Budget (Get-ScaffoldResidentBudgets) -Measured $rbMeasured -DocBudget (Get-ScaffoldDocBudgets) -PerItem $rbMeasure.PerSkill)
    if ($rbFindings.Count -gt 0) { foreach ($rbF in $rbFindings) { Fail "14g' $rbF Re-check with: selftest.ps1 -Only 14" } }
    elseif (@((Get-ScaffoldResidentBudgets).Keys).Count -eq 0) { Write-Host "  14g' resident budgets skipped (ResidentBudgets empty = off)" -ForegroundColor DarkGray }
    else { Write-Host "  14g' resident budgets OK (skill descriptions $($rbMeasure.Total) chars across $(@($rbMeasure.PerSkill).Count) skills; the two ceilings are judged separately and never pooled)" -ForegroundColor Green }
  }
}

Step '14h/17 ADR header contract (status line + recorded alternatives)'
# T90-ADR-FORMAT: a decision recorded without what it beat invites re-litigation, which is the one failure a
# decision record exists to prevent. Before this sub-gate docs/adr/README.md stated the intended structure as a
# suggestion with nothing checking it, and the nine records had drifted into four status syntaxes. Judgement
# lives in _guard.ps1 (Test-ScaffoldAdrFormat) with scripts/check-adr.ps1 as the thin CLI, so no new gate and no
# new -Only id: 14 already owns doc shape.
#
# The hermetic fixtures come FIRST and are not optional. The real-tree assertion below is vacuous on its own -
# a checker that always returned zero findings would pass it, and would pass it even harder in a downstream
# where init -Cleanup has removed the numbered records and there is nothing left to judge. The fixtures are what
# prove the checker can still fire, in the meta-repo and downstream alike (same reasoning as 15c/15d).
$adrNl = [string][char]10
$adrWaiver = [char]60 + '!-- adr-format: alternatives-not-recorded --' + [char]62
$adrFixtureOk = $true
$adrCase = @(
  @{ Why = 'missing status line'
     Text = @('# ADR 9999: probe', '## Context', 'x', '## Alternatives considered', 'x') -join $adrNl
     Want = 1 }
  @{ Why = 'status present, alternatives absent, no waiver'
     Text = @('# ADR 9999: probe', '- Status: Accepted', '## Context', 'x') -join $adrNl
     Want = 1 }
  @{ Why = 'waiver marker honored in place of an alternatives section'
     Text = @('# ADR 9999: probe', '- Status: Accepted', '## Context', 'x', $adrWaiver) -join $adrNl
     Want = 0 }
  @{ Why = 'Chinese heading alias accepted (four records use it; English-first forbids converting untouched lines)'
     Text = @('# ADR 9999: probe', '- Status: Accepted', '## 背景', 'x', '## 备选方案', 'x') -join $adrNl
     Want = 0 }
  @{ Why = 'dated Chinese MyInspection header plus approved-decision alternatives heading accepted'
     Text = @('# ADR 9999: probe', '日期：2026-09-10 · 状态：accepted', '## 背景', 'x', '## 批准决定与备选', 'x') -join $adrNl
     Want = 0 }
  @{ Why = 'dated English MyInspection header plus rejected-alternatives heading accepted'
     Text = @('# ADR 9999: probe', 'Date: 2026-09-10 · Status: proposed', '## Context', 'x', '## Rejected alternatives', 'x') -join $adrNl
     Want = 0 }
  @{ Why = 'dated header with an unknown status is rejected'
     Text = @('# ADR 9999: probe', '日期：2026-09-10 · 状态：pending-review', '## 背景', 'x', '## 批准决定与备选', 'x') -join $adrNl
     Want = 1 }
  @{ Why = 'a dated status-shaped line in the body does not establish header status'
     Text = @('# ADR 9999: probe', '## Context', 'Date: 2026-09-10 · Status: accepted', '## Rejected alternatives', 'x') -join $adrNl
     Want = 1 }
  @{ Why = 'both rules can fire on one record'
     Text = @('# ADR 9999: probe', '## Context', 'x') -join $adrNl
     Want = 2 }
)
foreach ($c in $adrCase) {
  $got = @(Test-ScaffoldAdrFormat -Name 'fixture.md' -Text ([string]$c.Text)).Count
  if ($got -ne [int]$c.Want) {
    Fail "14h fixture ($($c.Why)): expected $($c.Want) finding(s), got $got - Test-ScaffoldAdrFormat no longer judges the ADR contract correctly, so this gate cannot be trusted. Fix the checker in scripts/_guard.ps1, never the fixture."
    $adrFixtureOk = $false
  }
}
if ($adrFixtureOk) { Write-Host '  14h hermetic fixtures OK (missing status / missing alternatives / waiver / Chinese alias / dated Chinese+English headers / both local alternatives headings / unknown-or-body-only dated status / both rules)' -ForegroundColor Green }

# T96-SCOUT-ADR-STATUS: the recipe that DRAFTS an ADR must teach the line this contract requires, or every
# draft it produces is born failing 14h. That is the sibling of stale-text drift and the reason the L97 sweep
# missed it: nothing the recipe says is false, it is simply INCOMPLETE against a contract that got stricter
# underneath it. The verdict runs through Test-ScaffoldAdrFormat itself, never a private regex - the literal
# found in the recipe is planted into an otherwise-conformant record, so a recipe that merely mentions the
# word Status cannot pass. A missing file is skipped, the same downstream trimming 1b and 17m already allow.
$adrRecipeOk = $true
foreach ($adrRecipe in @('.claude/workflows/scout-options.mjs', 'docs/SCOUT-OPTIONS.md')) {
  $adrRecipeFull = Join-Path $RepoRoot $adrRecipe
  if (-not (Test-Path -LiteralPath $adrRecipeFull)) {
    Write-Host "  14h ADR recipe skipped (no $adrRecipe - normal after downstream trimming)." -ForegroundColor DarkGray
    continue
  }
  $adrTaught = [regex]::Match([System.IO.File]::ReadAllText($adrRecipeFull), '-[ \t]+Status:[ \t]*[A-Za-z]+')
  $adrRecipeProbe = @('# ADR 9999: probe', $adrTaught.Value, '## Context', 'x', '## Alternatives considered', 'x') -join $adrNl
  if (@(Test-ScaffoldAdrFormat -Name '9999-recipe.md' -Text $adrRecipeProbe).Count -ne 0) {
    Fail "14h ADR recipe: $adrRecipe tells an agent how to draft an ADR but teaches no status line this gate accepts, so every draft generated from it is born failing 14h. Add the literal '- Status: Accepted' beside the section list it already names - the bare word Status is not enough, because it reads to a human but not to this gate. [DOC-GATE-READS 14h] this gate reads the recipe named above; after editing it, re-check with: selftest.ps1 -Only 14"
    $adrRecipeOk = $false
  }
}
if ($adrRecipeOk) { Write-Host '  14h ADR recipe OK (the scout-options workflow and its manual both teach a status line this gate accepts)' -ForegroundColor Green }

# Real tree. Empty is green by construction: init -Cleanup strips the numbered records from a downstream and a
# project that has not written its first ADR must not be blocked by a contract about records it does not have.
$adrReads = ' [DOC-GATE-READS 14h] this gate reads the ADR named above under docs/adr; after editing it, re-check with: selftest.ps1 -Only 14 (or the faster scripts\check-adr.ps1)'
$adrFindings = @(Test-ScaffoldAdrFormat)
if ($adrFindings.Count -gt 0) {
  foreach ($af in $adrFindings) { Fail "14h ADR contract: $af$adrReads" }
}
else {
  Write-Host "  14h ADR header contract OK ($(@(Get-ScaffoldAdrFile).Count) records carry a parseable status and a recorded-or-waived alternative)" -ForegroundColor Green
}

$metaRun = Test-MetaSelected "14i"
if ($metaRun) {
Step '14i/17 gate map (change surface to -Only tokens, tokens projected from this file own id list)'
# T95-GATE-MAP: the table lives in THIS script's header (search [GATE-MAP]) and the judgement lives in
# _guard.ps1 (Test-ScaffoldGateMap), the same split 14g/14h use - so no new gate and no new -Only id: 14
# already owns doc drift. The table is a reading aid, never a router (ADR 0007), and it does not move the
# acceptance bar: -Only stays diagnosis-only and the full unfiltered run is still the only pre-merge proof
# of the 17 gates.
#
# The bogus-token probe comes FIRST for the reason 14h states about its fixtures: a checker that always
# returned zero findings would sail through the real-table assertion below, and would sail through it
# hardest in a tree where there is nothing left to judge. The probe is what proves it can still fire.
if (@(Test-ScaffoldGateMap -Token 'no-such-gate').Count -ne 1) {
  Fail '14i probe: Test-ScaffoldGateMap accepted a token that is not a legal -Only id, so its verdict on the real table below proves nothing. Fix the checker in scripts/_guard.ps1, never the probe.'
}
$gateMapRows = @(Get-ScaffoldGateMapRow)
if ($gateMapRows.Count -lt 9) {
  Fail "14i gate map: only $($gateMapRows.Count) row(s) parsed out of the [GATE-MAP] table in scripts/selftest.ps1's header - rows were deleted, or the [GATE-MAP] / [GATE-MAP-END] sentinels moved. Restore the table; re-check with: selftest.ps1 -Only 14"
}
$gateMapFindings = @(Test-ScaffoldGateMap)
# T274: the table is no longer only a reading aid - Get-ScaffoldGateRoutes is the same rows as DATA, and
# -TaskId runs what the routes say. So 14i now holds BOTH representations equal (row count, tokens per row,
# in order) as well as holding the tokens legal. Same probe-first stance as the arm above: a comparator that
# always agreed would sail through the real pair, so the disagreeing fixture proves it can still fire before
# its silence on the live tree is trusted.
$gateRouteProbe = @(Test-ScaffoldGateRouteTable -Path (Join-Path $RepoRoot 'scripts/_config.ps1'))
if ($gateRouteProbe.Count -lt 1) {
  Fail '14i route probe: Test-ScaffoldGateRouteTable read a file carrying NO [GATE-MAP] table and still reported nothing, so its silence on the real table proves nothing. Fix the checker in scripts/_guard.ps1, never the probe.'
}
$gateRouteFindings = @(Test-ScaffoldGateRouteTable)
if ($gateMapFindings.Count -gt 0) {
  foreach ($gm in $gateMapFindings) { Fail "14i gate map: $gm Re-check with: selftest.ps1 -Only 14" }
}
elseif ($gateRouteFindings.Count -gt 0) {
  foreach ($gr in $gateRouteFindings) { Fail "14i gate routes: $gr Re-check with: selftest.ps1 -Only 14" }
}
elseif ($gateMapRows.Count -ge 9) {
  Write-Host "  14i gate map OK ($($gateMapRows.Count) rows, every token legal per this script's own -Only id list, and Get-ScaffoldGateRoutes declares the same rows with the same tokens in the same order - the reading aid and the machine route held equal since ADR 0016)" -ForegroundColor Green
}
}

$metaRun = Test-MetaSelected "14k"
if ($metaRun) {
Step '14k/17 gate-17 region literals (every -Region literal names a region this file actually routes)'
# T141-SELFTEST-REGION-LITERAL: a region literal matching no router arm runs in NO shard under -Parallel
# while every token-level assertion still passes, because those assertions check that the shard list
# mentions the token, never that a region answered to it - a green run over an unexecuted region. The
# judgement lives in _guard.ps1 (Get-ScaffoldOrphanRegionLiteral) and rides gate 14 exactly as 14g/14h/14i
# do, so there is no new gate number and no new -Only token. (Letter k, not j: 14j is already the T97
# card-generator sweep check above.)
#
# Probe first, for the reason 14i states about its own: a predicate that always returned zero findings would
# sail through the real-file assertion below, and would sail through it hardest in a file where there is
# nothing left to judge. The examples are what prove it can still fire.
if (@(Test-ScaffoldRegionLiteralExamples).Count -ne 0) {
  Fail '14k probe: the declared examples for Get-ScaffoldOrphanRegionLiteral do not hold, so its verdict on this file proves nothing. Fix the rule in scripts/_guard.ps1, never the example.'
}
$regionOrphans = @(Get-ScaffoldOrphanRegionLiteral -Text ([System.IO.File]::ReadAllText((Join-Path $RepoRoot 'scripts/selftest.ps1'))))
if ($regionOrphans.Count -gt 0) {
  foreach ($ro in $regionOrphans) {
    Fail "[SELFTEST-REGION-ORPHAN] scripts/selftest.ps1:$($ro.Line) hands Test-SeedRegionSelected the literal '$($ro.Literal)', which names no region this file routes. Declared right now, read live from this file's own `$onlyValidIds literal and the router's own arms: $($ro.Declared -join ', '). That region runs in NO shard under -Parallel and every token-level assertion still passes, so the suite reports green over an unexecuted region. Fix the literal; re-check with: selftest.ps1 -Only 14"
  }
}
else {
  Write-Host '  14k region literals OK (every Test-SeedRegionSelected literal names a routed region)' -ForegroundColor Green
}
}

$metaRun = Test-MetaSelected "14m@labels"
if ($metaRun) {
Step '14m/17 sub-gate labels (every label declared once inside its gate, projected from this file own declaration headers, gate 17 indented seed headers included)'
# T172-SUBGATE-LABEL-UNIQUE (TD163): sub-gate letters inside a gate are hand-assigned and nothing read them
# back, so two different blocks could print under one label while the suite stayed green - a scoped -Only run
# then reports two different '14j OK' lines and a reader cannot tell which check spoke. Live at T141, caught
# by eye and by no gate. The judgement lives in _guard.ps1 (Get-ScaffoldDuplicateSubGateLabel) and rides gate
# 14 exactly as 14g/14h/14i/14k do, so there is no new gate number and no new -Only token. (Letter m, not l:
# l is visually confusable with 1 in this gate's own console output, which is the class of reading error this
# sub-gate exists to prevent. A skipped letter is legal under the rule.)
#
# Probe first, for the reason 14i and 14k state about theirs: a predicate that always returned zero findings
# would sail through the real-file assertion below, and would sail through it hardest in a file where there
# is nothing left to judge.
if (@(Test-ScaffoldSubGateLabelExamples).Count -ne 0) {
  Fail '14m probe: the declared examples for Get-ScaffoldDuplicateSubGateLabel do not hold, so its verdict on this file proves nothing. Fix the rule in scripts/_guard.ps1, never the example.'
}
# Anti-rot: TD163 proposed projecting from the Step headers alone. That surface does not carry 14j, which is
# the label the recorded collision landed on, so the narrow form is measurably blind to its own incident. The
# same examples run through it MUST fail; silence here means the projection rotted back to the narrow form.
if (@(Test-ScaffoldSubGateLabelExamples -Variant 'step-headers-only').Count -lt 1) {
  Fail '14m anti-rot: the declared examples still hold when the projection is narrowed to Step headers alone, so widening it to the comment headers decides nothing. The recorded T141 collision landed on 14j, which has no Step header.'
}
$subGateSelf = Join-Path $RepoRoot 'scripts/selftest.ps1'
$subGateDecls = @(Get-ScaffoldDuplicateSubGateLabel -Path $subGateSelf -Declaration)
$subGateDupes = @(Get-ScaffoldDuplicateSubGateLabel -Path $subGateSelf)
# [SUBGATE-SEED-COUNTED] (T284): the projection above is anchored at COLUMN 0, and gate 17 is not. Every
# seeded-defect sub-gate in that gate is authored INSIDE the region/try body it guards, so its canonical
# header carries leading whitespace and the column-0 matcher sees none of them - the ratchet bracketed every
# gate except the one that is a third of this file, and T277 could land 17b' without the ceiling being able
# to notice. This is a SECOND projection over the SAME canonical grammar at a different indentation, and it
# is a caller-side set rather than a widening of Get-ScaffoldDuplicateSubGateLabel because widening the
# production matcher to any indentation would admit indented PROSE whose first token happens to read as a
# label. This file carries such a line today (a mid-sentence mention of another gate's sub-gate inside 14q's
# commentary), and a mention promoted to a declaration would be a false duplicate, not a closed blind spot.
# Restricted to gate 17 for the same reason: outside it every declaration this file makes is at column 0,
# so a wider seed set would buy nothing and could only ever be wrong. A seed projection that quietly stopped
# matching is not silent either: the floor below counts BOTH sets, so the whole set going missing drops the
# total far below it and reds on [SUBGATE-LABEL] rather than shrinking the verdict unannounced.
# Both halves are FUNCTIONS, not inline expressions, for the reason 14i/14k/14m state about theirs and L271
# states generally: the declared examples below drive the SAME code the real verdict runs, so a rule that has
# stopped deciding fails there before its silence on this file is ever trusted. A second copy of either would
# BE the drift the examples exist to catch.
function Get-SeedSubGateDeclaration {
  # AllowEmptyString as well as AllowEmptyCollection: the real call hands this every line of a 14k-line
  # file, blank ones included, and without it the binder rejects the first empty line rather than the gate
  # reporting anything. Measured, not reasoned about - the synthetic examples carry no blank line, so the
  # arms passed while the live call threw.
  param([Parameter(Mandatory)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Line)
  $sgFound = [System.Collections.Generic.List[object]]::new()
  for ($sgi = 0; $sgi -lt $Line.Count; $sgi++) {
    $sgM = [regex]::Match($Line[$sgi], "^[ \t]+#[ \t]+(?<label>17[a-z]+\d?'*)\.[ \t]")
    if ($sgM.Success) { $sgFound.Add([pscustomobject]@{ Label = $sgM.Groups['label'].Value; Line = $sgi + 1; Surface = 'indented seed header' }) }
  }
  return @($sgFound)
}
function Get-SeedCrossSetDuplicate {
  param([AllowEmptyCollection()][object[]]$Column0, [AllowEmptyCollection()][object[]]$Seed)
  return @(@(@($Column0) + @($Seed)) | Group-Object Label | Where-Object {
      @($_.Group).Count -gt 1 -and @($_.Group | Where-Object { $_.Surface -eq 'indented seed header' }).Count -gt 0
    } | ForEach-Object { [pscustomobject]@{ Label = $_.Name; Declarations = @($_.Group) } })
}
# Declared examples, hermetic - synthetic text only, so they read no file and need no tree. Both directions,
# as 14k's and 14m's own tables carry: silence on a legal shape is the half that keeps the rule landable, and
# the collision arm is the half acceptance item 2 closes. A cross-set guard nobody has watched refuse anything
# is a guard nobody has tested - the same argument T275 answered with its ceiling bite test.
$sgProbe = @()
$sgCol0 = @([pscustomobject]@{ Label = '17a'; Line = 1; Surface = 'comment header' })
$sgShapes = @(
  '# 17q. a column-0 header belongs to the projection above, not to this set',
  '    # 17z. an indented canonical gate-17 header IS a seed declaration',
  '    # 17p2. an indented gate-17 header whose label carries a trailing digit is a seed declaration too',
  '    # 17ad exists for one gate over).',
  '    # 9z. an indented canonical header outside gate 17 is not a seed',
  '    # 17y(cont): the parenthetical form continues a sub-gate, it does not declare one')
$sgShapeGot = @(Get-SeedSubGateDeclaration -Line $sgShapes)
if (@($sgShapeGot).Count -ne 2 -or @($sgShapeGot)[0].Label -ne '17z' -or @($sgShapeGot)[1].Label -ne '17p2') {
  $sgProbe += "projection: expected exactly two findings, the indented canonical gate-17 header 17z and the digit-form 17p2; got $(@($sgShapeGot).Count) [$((@($sgShapeGot) | ForEach-Object { $_.Label }) -join ', ')]. The other four shapes are each a way this set could wrongly grow - a column-0 header, an indented PROSE mention of a label, a non-gate-17 label, and a continuation."
}
$sgCleanGot = @(Get-SeedCrossSetDuplicate -Column0 $sgCol0 -Seed (Get-SeedSubGateDeclaration -Line @('    # 17b. a label the column-0 set does not carry')))
if (@($sgCleanGot).Count -ne 0) {
  $sgProbe += "cross-set silence: two DIFFERENT labels, one per set, were reported as a collision [$((@($sgCleanGot) | ForEach-Object { $_.Label }) -join ', ')] - a rule that reports the legal case is unlandable."
}
$sgCollideGot = @(Get-SeedCrossSetDuplicate -Column0 $sgCol0 -Seed (Get-SeedSubGateDeclaration -Line @('    # 17a. the SAME label the column-0 set already declares')))
if (@($sgCollideGot).Count -ne 1 -or @($sgCollideGot)[0].Label -ne '17a' -or @(@($sgCollideGot)[0].Declarations).Count -ne 2) {
  $sgProbe += "cross-set collision: a seed label colliding with a column-0 label must be reported exactly once, naming the label and BOTH declarations; got $(@($sgCollideGot).Count) finding(s). This is the arm acceptance item 2 closes, and the state [SUBGATE-LABEL] below exists to make red."
}
if ($sgProbe.Count -ne 0) {
  Fail "14m seed probe: the declared examples for the gate-17 seed projection and its cross-set uniqueness verdict do not hold, so their verdict on this file proves nothing. Fix the rule, never the example. Got: $($sgProbe -join ' | ')"
}
$subGateSeeds = @(Get-SeedSubGateDeclaration -Line ([System.IO.File]::ReadAllLines((Convert-Path -LiteralPath $subGateSelf))))
# [SUBGATE-SEED-WIRED] (T284, answering R3 round 2). The examples above prove the RULE; this proves the
# CONSUMER, and the two are different claims. On a tree that carries no collision - which is every healthy
# tree - NO assertion over data can tell "the seed set is wired into the uniqueness verdict" apart from "it
# is not": deleting the seed half of the consumer condition changes no output, so every arm above would stay
# green while the guard silently stopped guarding. That is a WIRING claim, and this repo judges wiring on the
# SYNTAX TREE rather than by grep (TD273) - a text count cannot tell a live condition from the same words in
# a comment or a string. So: find the if/elseif clause whose CONDITION reads $subGateSeedDupes, and require
# that the body it guards is the one that raises [SUBGATE-LABEL]. Delete the condition and this reds.
$sgAst = [System.Management.Automation.Language.Parser]::ParseFile($subGateSelf, [ref]$null, [ref]$null)
$sgWiredClause = 0
foreach ($sgIf in $sgAst.FindAll({ param($n) $n -is [System.Management.Automation.Language.IfStatementAst] }, $true)) {
  foreach ($sgClause in $sgIf.Clauses) {
    $sgReads = @($sgClause.Item1.FindAll({ param($n) $n -is [System.Management.Automation.Language.VariableExpressionAst] -and $n.VariablePath.UserPath -eq 'subGateSeedDupes' }, $true))
    if ($sgReads.Count -gt 0 -and $sgClause.Item2.Extent.Text -match '\[SUBGATE-LABEL\]') { $sgWiredClause++ }
  }
}
if ($sgWiredClause -ne 1) {
  Fail "[SUBGATE-SEED-WIRED] expected exactly ONE if/elseif clause whose condition reads `$subGateSeedDupes and whose body raises [SUBGATE-LABEL]; found $sgWiredClause. The cross-set projection and its declared examples can all be green while the verdict never consumes the seed set - a collision would then ship silently, which is the whole point of counting it. Re-check with: selftest.ps1 -Only 14 -IncludeMeta"
}
$subGateSeedLabels = @(@($subGateSeeds) | Select-Object -ExpandProperty Label -Unique)
Write-Host "  [SUBGATE-SEED-COUNTED] seeds=$($subGateSeedLabels.Count) (gate 17's indented seed headers, projected into the same bracket as the column-0 declarations)" -ForegroundColor DarkGray
# Both sets share ONE bracket and ONE uniqueness verdict: a seed label that also appears at column 0 is two
# blocks printing under one label just as surely as two column-0 headers are, and it is the shape a new gate
# reusing a seed letter would take.
$subGateDeclTotal = $subGateDecls.Count + @($subGateSeeds).Count
$subGateSeedDupes = @(Get-SeedCrossSetDuplicate -Column0 $subGateDecls -Seed $subGateSeeds)
# The floor RATCHETS with the count (T185: 64 -> 92, after 21 headers were normalised into the canonical
# form; T187: 92 -> 93 with sub-gate 1i; T201: 93 -> 100, a step of SEVEN because the literal had been six
# BEHIND the tree - six declarations were deletable while this gate stayed green; T202: 100 -> 101. Both of
# those last two were caught by re-measuring rather than by incrementing, and T202 needed a SECOND
# measurement after rebasing onto T201: the two cards each added one sub-gate, both wrote 100, and the
# rebase merged that literal without a conflict - a clean auto-merge landing on a stale number is exactly
# the shape this floor exists to catch. Measure the tree after every rebase; never increment, never copy a
# number from a card. T210: 101 -> 103, and the STEP OF TWO is the point. T210 added one sub-gate (15u) and
# measured 102; T211 added one (14o) concurrently and deliberately left this literal alone; rebasing T210
# onto T211 then produced a tree of 103 declarations carrying a literal of 102 - green, because this is a
# floor, and one behind the tree, which is precisely how T201 came to be six behind. Caught by re-measuring
# after the rebase, exactly as the line above instructs, rather than by trusting the number the card had
# already justified. Re-measure after every rebase; the value a card computed before its rebase is stale by
# construction whenever another card touched this file).
# It is stated ONCE and the failure text reads that same value back
# - before T185 the guard read 64 while the message it printed said 40, so a reader chasing the number was
# told something the check never applied. Moving the floor up with the count is what keeps a newly projected
# header from being deletable while this gate stays green: measure the tree, never copy a number from a card.
# T284: 104 -> the count of BOTH sets. The floor had drifted eleven behind its own tree, and it now brackets
# the same total the ceiling does, so the two ends measure one number and neither can go stale alone.
# T286: 138 -> 149, and not growth either - the ten labels T284 measured as unreachable from its own
# allow_paths are in. Two headers put a box-drawing decoration before the label, five followed the label
# with a space or a full-width paren instead of a dot, and four carried a trailing digit the grammar in
# _guard.ps1 rejected (8l2, one gate over, came in with them). Re-measured on the tree this card ships
# from, and both ends of the bracket read the same number.
# PR297 upstream adoption: 150 -> 151.  The restored 16a hot+cold lesson-reference witness is a distinct
# local regression judgement (cold-only references must remain valid), so it cannot be folded into 16's
# existing live-tree scan without losing the fixture-specific diagnosis.  MEASURED on this candidate.
$subGateDeclFloor = 151
# [SUBGATE-CEILING] (T275 / ADR 0016 item 3): the OTHER end of the same measurement, and the reason it is a
# ceiling rather than more prose. `[HR-GATE-CENSUS]` found twelve of the seventeen gates with no measurable
# catch history, so no cut is justified by the numbers; what the numbers do show is growth - 115 commits to
# this file in fourteen days, 252 in its lifetime. A ceiling makes the next sub-gate cost a DECISION instead
# of a habit: it is raised only by editing the constant below, with the reason in the commit that raises it,
# exactly the convention DocBudgets already uses for the standing docs. It is measured on the tree it ships
# with and carries NO headroom - a ceiling with slack is a floor wearing a hat, and the slack is spent
# before anyone notices it existed. The count compared is the number of DISTINCT labels, which is the same
# number the floor above compares whenever the duplicate verdict below is green (the projection is
# one-to-one by construction), so the pair brackets one count from both ends.
# T276: 114 -> 115, one sub-gate, for 10u. The rule this card adds ([CARD-REQ-DANGLING]) blocks a card, and
# a blocking rule with no seeded case is a rule nobody has watched refuse anything; folding it into 10t was
# the alternative this ceiling asks about and it was rejected because 10t already brackets two tables and
# would then bracket four, so a red there would no longer say which decision broke.
# T284: 115 -> the count over BOTH sets. The step is not growth - not one sub-gate was added by that card;
# it is the gate-17 seed labels entering a bracket that had never seen them, which is why the number moves
# by more than one and why the SAME commit re-measures the floor. A ceiling that covered every gate but the
# largest was a ceiling with a hole, not a ceiling with slack, and the hole cost nothing to walk through.
# T286: 138 -> 149, the same ten labels. What the bracket holds is every label the two projections READ,
# and after this card that set includes gate 17's decorated and digit-form headers. It is NOT every header
# a human would call a sub-gate: `# 15d2(` writes its label then a full-width paren, one gate over, and
# stays outside both projections and outside this count - normalising a non-canonical header outside gate
# 17 is this card's declared non-goal, so the number is honest about its own edge rather than silent on it.
# PR297 upstream adoption: 150 -> 151 for the restored 16a hot+cold witness.  The ceiling stays paired with
# the measured declaration floor above: a new sub-gate still requires this explicit decision rather than
# silently becoming part of the count.
$subGateDeclCeil = 151
$subGateLabelCount = @(@($subGateDecls) + @($subGateSeeds) | Select-Object -ExpandProperty Label -Unique).Count
if ($subGateDeclTotal -lt $subGateDeclFloor) {
  Fail "[SUBGATE-LABEL] only $subGateDeclTotal sub-gate declaration(s) were projected out of scripts/selftest.ps1 (expected at least $subGateDeclFloor) - the declaration form has drifted, so the uniqueness verdict below judges nothing. Re-check with: selftest.ps1 -Only 14"
}
elseif ($subGateLabelCount -gt $subGateDeclCeil) {
  Fail "[SUBGATE-CEILING] declared=$subGateLabelCount ceiling=$subGateDeclCeil - scripts/selftest.ps1 declares more distinct sub-gates than the ceiling this file states for itself. Raising it is an explicit edit of `$subGateDeclCeil in this file with the reason written into the commit that raises it, the same convention DocBudgets uses; the alternative is to fold the new judgement into a sub-gate that already exists. Re-check with: selftest.ps1 -Only 14"
}
elseif ($subGateDupes.Count -gt 0 -or $subGateSeedDupes.Count -gt 0) {
  foreach ($sd in (@($subGateDupes) + @($subGateSeedDupes))) {
    Fail "[SUBGATE-LABEL] scripts/selftest.ps1 declares sub-gate '$($sd.Label)' $(@($sd.Declarations).Count) times: $((@($sd.Declarations) | ForEach-Object { "$($_.Surface) at line $($_.Line)" }) -join '; '). Two blocks printing under one label make a scoped -Only run unreadable - the reader cannot tell which check spoke. Give one of them a free letter; do NOT renumber an existing sub-gate to buy a green. Re-check with: selftest.ps1 -Only 14"
  }
}
else {
  Write-Host "  14m sub-gate labels OK ($($subGateDecls.Count) column-0 + $(@($subGateSeeds).Count) gate-17 indented seed = $subGateDeclTotal declarations projected from this file's own comment and Step headers, each label declared once across both sets, $subGateLabelCount distinct labels inside $subGateDeclFloor..$subGateDeclCeil)" -ForegroundColor Green
}
}

$metaRun = Test-MetaSelected "14m@header-form"
if ($metaRun) {
# [SUBGATE-FORM] (T182 / TD168, modelled by T186 / TD177): the projection above is one-to-one by design, so a
# sub-gate that declares itself in any other form is not judged by it - it is INVISIBLE, and an invisible
# sub-gate reads exactly like a clean one. Measured at T182 on this file: 37 of 95 sub-gates sat outside the
# verdict, three times what TD168 counted, because that row looked only at the supply-chain gate. T182
# normalised the dotted family, T185 the rest of the formatting backlog, and what was left was not formatting
# at all - four sub-gates each implemented across several blocks. T186 gave those a way to SAY so: one
# canonical header plus N declared continuations, read from Get-ScaffoldContinuedSubGateLabel, with the count
# read in both directions so a block appearing or disappearing is a stated act. Probe first, for the same
# reason 14m states about its own; the probe prints the arms it got back, so a batch mutating one arm's
# judgement can be told apart from one mutating another.
$subGateFormProbe = @(Test-ScaffoldUnprojectedSubGateHeaderExamples)
if ($subGateFormProbe.Count -ne 0) {
  Fail "14m form probe: the declared examples for Get-ScaffoldUnprojectedSubGateHeader do not hold, so its verdict on this file proves nothing. Fix the rule in scripts/_guard.ps1, never the example. Got: $($subGateFormProbe -join ' | ')"
}
$subGateContinued = Get-ScaffoldContinuedSubGateLabel
$subGateForm = @(Get-ScaffoldUnprojectedSubGateHeader -Path $subGateSelf)
if ($subGateForm.Count -gt 0) {
  foreach ($sf in $subGateForm) {
    if ($sf.Kind -eq 'count') {
      Fail "[SUBGATE-FORM] Get-ScaffoldContinuedSubGateLabel in scripts/_guard.ps1 declares $($sf.Declared) continuation block(s) for sub-gate '$($sf.Label)', but scripts/selftest.ps1 carries $($sf.Found). A continued sub-gate declares how many blocks continue it so that a block appearing or disappearing is a stated act, never a silent one - restate the count if the change is intended, and drop the entry entirely once the file carries none. Re-check with: selftest.ps1 -Only 14"
    }
    elseif ($sf.Kind -eq 'orphan') {
      Fail "[SUBGATE-FORM] scripts/selftest.ps1:$($sf.Line) writes sub-gate '$($sf.Label)' in the continuation form and Get-ScaffoldContinuedSubGateLabel declares it continued, but no CANONICAL '# $($sf.Label). ' header exists for it to continue - so the label sits outside the uniqueness verdict with nothing declaring it, which is the exemption the continuation map replaced. Give it a canonical header, or drop it from the map and write this one canonically. Re-check with: selftest.ps1 -Only 14"
    }
    else {
      Fail "[SUBGATE-FORM] scripts/selftest.ps1:$($sf.Line) declares sub-gate '$($sf.Label)' in a form the projection cannot see, so that label is exempt from the uniqueness verdict and a collision on it would ship green. Write the header in the canonical form - the label, a period, then a space - as '# $($sf.Label). ...'. If this block CONTINUES a sub-gate already declared canonically elsewhere, write it as '# $($sf.Label)(...)' instead and declare '$($sf.Label)' in Get-ScaffoldContinuedSubGateLabel with the number of blocks that continue it. Re-check with: selftest.ps1 -Only 14"
    }
  }
}
else {
  Write-Host "  14m header form OK ($($subGateDecls.Count) declarations projected, $($subGateContinued.Count) sub-gate(s) declared as continued across $(($subGateContinued.Values | Measure-Object -Sum).Sum) block(s), no header outside the verdict)" -ForegroundColor Green
}
}

$metaRun = Test-MetaSelected "14n"
if ($metaRun) {
Step '14n/17 doc-read tags (every tagged site names a legal -Only id and paths that exist; id predicate shared with 14i)'
# T201-DOCGATE-READS-GUARD (TD193): docs/SELFTEST.md teaches two grep-this-tag mechanisms in one sentence
# and only one of them had a reader. The gate-map half has had 14i since T95; the read-tag half arrived at
# T77 as failure-text prose, so deleting the tag from a site reddened nothing while the doc kept telling
# readers to grep for a set that had silently shrunk - and the .md that gate reads then got edited under the
# pure-doc exemption with no gate run at all, which is the failure that exemption's own EXCEPT clause exists
# to prevent. The judgement lives in _guard.ps1 (Get-ScaffoldDocReadTagSite / Test-ScaffoldDocReadTag) and
# rides gate 14 exactly as 14g/14h/14i/14k/14m do, so there is no new gate number and no new -Only token.
#
# Transposition, not a second design: the -Only id predicate is 14i's own Get-ScaffoldGateMapValidToken,
# CALLED. A second copy of the legal id set would BE the drift both gates exist to prevent.
#
# Probe first, for the reason 14i and 14m state about theirs: a predicate that always returned zero findings
# would sail through the real-file verdict below, and would sail through it hardest in a file where there is
# nothing left to judge. The probe prints the arms it got back, so a batch mutating one arm's judgement can
# be told apart from one mutating another.
# ONE if/elseif chain, and the ordering is load-bearing rather than stylistic. Fail() records a failure and
# RETURNS - it does not exit - so a probe failure written as its own statement would leave the success line
# below reachable, and this gate's success line is what the card's dod_command greps. The mutation batch
# proved that is not hypothetical: with the probe arm deleted, M1/M2/M3 each went non-zero AND still printed
# the OK line, so the DoD passed over a guard that had stopped judging (L283 - the grepped pattern must be
# reserved to a line only a fully green verdict can print). Chaining makes the OK line unreachable unless
# the probe held, the population is the declared size, and the verdict is empty.
#
# The final arm reads `-not $fail`, the run-wide latch, and that is L283's literal requirement rather than
# extra caution: the success line must be "emitted under the gate-wide fail flag so it means nothing above
# failed either". The chain alone only proves 14n's OWN three conditions, so a failure in 14f/14g/14h/14i/
# 14k/14m would redden gate 14 while this line still printed - and the dod_command greps this line, so the
# DoD would report green over a red gate. The latch is set by Fail() and never falls (see its declaration),
# so under -Only 14 it means "no sub-gate of 14 failed" and under a full run it means "nothing before this
# point failed". Both are the reading L283 asks for.
$docReadProbe = @(Test-ScaffoldDocReadTagExamples)
$docReadSelf = Join-Path $RepoRoot 'scripts/selftest.ps1'
$docReadSites = @(Get-ScaffoldDocReadTagSite -Path $docReadSelf)
$docReadFindings = @(Test-ScaffoldDocReadTag -Path $docReadSelf)
# EXACT, not a floor, and the difference is the whole evidence story. LEDGER's rule names THIS sentinel as
# its next occurrence: a `-ge N` floor resting on N+1 occurrences is vacuous evidence, the same family as
# L95's vacuous RED, because the surplus occurrence absorbs the deletion the check exists to catch. An
# exact count also makes its own declaration killable - delete the line below and `-lt` would compare
# against $null, which 7 satisfies, so the arm would survive its own removal; `-ne` reds instead. And it
# makes ADDING a tag a stated act too: a new site must restate this number in the same diff, which is the
# direction a floor is blind in. Measure the tree; never copy the number out of a card.
$docReadExpected = 7
if ($docReadProbe.Count -ne 0) {
  Fail "14n probe: the declared examples for Test-ScaffoldDocReadTag do not hold, so its verdict on this file proves nothing. Fix the rule in scripts/_guard.ps1, never the example. Got: $($docReadProbe -join ' | ')"
}
elseif ($docReadSites.Count -ne $docReadExpected) {
  Fail "14n read tags: $($docReadSites.Count) tagged site(s) were projected out of scripts/selftest.ps1, and this gate expects exactly $docReadExpected. If a tag was DELETED, docs/SELFTEST.md now tells readers to grep for a set that has silently shrunk - restore it. If one was ADDED, restate the expected count in the same diff so the change is a stated act rather than a silent one. Re-check with: selftest.ps1 -Only 14"
}
elseif ($docReadFindings.Count -gt 0) {
  foreach ($dr in $docReadFindings) { Fail "14n read tags: $dr Re-check with: selftest.ps1 -Only 14" }
}
elseif (-not $fail) {
  Write-Host "  14n doc-gate read tags OK ($($docReadSites.Count) tagged site(s) projected, every -Only id legal per this script's own id list, every path named exists)" -ForegroundColor Green
}
}


$metaRun = Test-MetaSelected "14o"
if ($metaRun) {
# 14o. (T211/TD206) 变异登记表与它点名的代码之间的绑定：锚行被改写后该枚就不再命中，从此**静默地**不产出任何
# 证据，却仍占着批次里的一个席位——不是错的裁决（错的裁决会跟你争辩），是沉默。runner 本身没错、也不动它：
# mutate.ps1 早已把 ANCHOR-MISS 计入失败总数；缺的是「在极少数有人碰某一张登记表的时刻之间，有没有东西重读
# 过整个语料」。开卡时实测：253 枚里 16 枚已腐坏，横跨 9 张登记表，而整个语料只有 14 天大。
# 判定一律走**生产匹配器** Get-MutatedVariant（经 mutate.ps1 -AsLibrary），绝不另写一份规则——否则本闸与
# runner 会对「什么叫命中」产生分歧，而那正是本闸存在要堵的失效类。
# _config.ps1 的 MutationAnchorPending 是**三向棘轮**（ADR 0011，第三向由 T235/TD209 补上）：未登记而腐坏者
# FAIL，已登记却重新命中者报 STALE，已登记但那一枚已被 RETIRE（键无对应 entry）者报 ORPHAN——故该清单既不会
# 烂成永久白名单，也不会留下无人能看见的空座。
$mutAnchorPending = @(Get-ScaffoldMutationAnchorPending)
$mutAnchorProbe = @(Test-ScaffoldMutationAnchorExamples)
$mutAnchorStale = @(Test-ScaffoldMutationAnchorExamples -Variant 'ignore-stale')
$mutAnchorBlind = @(Test-ScaffoldMutationAnchorExamples -Variant 'pending-blind')
$mutAnchorOrphanBlind = @(Test-ScaffoldMutationAnchorExamples -Variant 'orphan-blind')
$mutAnchorFindings = @(Get-ScaffoldMutationAnchorIssue -RegistryDir 'specs/mutations' -Pending $mutAnchorPending -RepoRoot $RepoRoot)
if ($mutAnchorProbe.Count -ne 0) {
  Fail "14o probe: Test-ScaffoldMutationAnchorExamples 的声明用例自身不成立，故它对本仓语料的裁决什么都不证明。改 scripts/_guard.ps1 里的判定，永远别改用例。Got: $($mutAnchorProbe -join ' | ')"
}
elseif ($mutAnchorStale.Count -lt 1 -or $mutAnchorBlind.Count -lt 1 -or $mutAnchorOrphanBlind.Count -lt 1) {
  Fail "14o anti-vacuous: 把同一批用例喂给被拒形态 'ignore-stale'（$($mutAnchorStale.Count) 处分歧）、'pending-blind'（$($mutAnchorBlind.Count) 处分歧）与 'orphan-blind'（$($mutAnchorOrphanBlind.Count) 处分歧），至少一者为零——用例表已不再区分它该区分的形态，该被拒形态可以被悄悄合入而不被发现。[FIX] 补回缺失的用例，绝不放宽被拒形态。Re-check with: selftest.ps1 -Only 14"
}
elseif ($mutAnchorFindings.Count -gt 0) {
  foreach ($ma in $mutAnchorFindings) { Fail "14o mutation anchors: $ma Re-check with: selftest.ps1 -Only 14" }
}
elseif (-not $fail) {
  Write-Host "  14o [MUT-ANCHOR-OK] every registry entry under specs/mutations/ still resolves through the production matcher, or is one of the $($mutAnchorPending.Count) declared on MutationAnchorPending, and every one of those declarations still names an entry that exists (a three-way ratchet: an undeclared decay reds, a declared entry that resolves again reds as STALE, and a declared key whose entry was retired reds as ORPHAN)" -ForegroundColor Green
}
}
$metaRun = Test-MetaSelected "14p"
if ($metaRun) {
# 14p. (T220/TD212) The OTHER channel an entry can decay in. 14o above resolves the ANCHOR; nothing ever
# re-validated the mustFind TEXT an entry greps for. mutate.ps1 compares each literal against captured gate
# output and writes the verdict into a results TSV, but nothing reads those rows again, and for a merged
# card the batch is never re-run - so an entry can hold a perfect anchor, claim text nothing has proven, and
# read as healthy to every gate in this repo. Measured while draining T110 (T219): M4 anchored a line
# byte-identical to T200 M5's and was therefore ABSENT from the sixteen TD207 enumerated, yet a pristine-
# tree batch recorded BAD-EVIDENCE for it. Three cheaper probe designs were tried against that ground truth
# and refuted - a raw source scan false-alarms on 234 of 515 literals (gate output is composed at runtime),
# a wildcarded-interpolation scan is VACUOUS (it explains M4's dead literal through 24 junk patterns), and a
# cacheKey ratchet is stale on 259 of 270 rows because selftest.ps1 enters every key. What holds is the
# comparison below: each entry's CURRENT mustFind against the evidence its OWN stored row recorded, in the
# literal 'found:' form the runner writes, matched as a WHOLE ELEMENT of the '; '-joined field, so gate and
# runner cannot disagree about what counts as covered.
# MutationEvidencePending is the three-way ratchet (ADR 0011), sharing 14o's ORPHAN rule (T235/TD209); an entry already excused on
# MutationAnchorPending is SKIPPED, because an unresolved anchor produces no evidence at all and 14o
# already owns that debt.
# TD219 added the element boundary and the second probe pair beneath. Until then the comparison was a bare
# substring test living inside the I/O wrapper, where no declared example could reach it: it accepted any
# PREFIX of the recorded evidence, so an entry truncated by a source rewording read COVERED - the very decay
# class this sub-gate exists for, passing green. Found by an independent second model reading the merged
# change, not by any gate here, which is the point worth keeping: a deterministic merge bar cannot see a
# predicate that is merely TOO PERMISSIVE, only one that is wrong on the corpus in front of it.
$mutEvidencePending = @(Get-ScaffoldMutationEvidencePending)
$mutEvidenceProbe = @(Test-ScaffoldMutationEvidenceExamples)
$mutEvidenceRowBlind = @(Test-ScaffoldMutationEvidenceExamples -Variant 'row-blind')
$mutEvidenceVerdictBlind = @(Test-ScaffoldMutationEvidenceExamples -Variant 'verdict-blind')
$mutEvidenceStaleShape = @(Test-ScaffoldMutationEvidenceExamples -Variant 'ignore-stale')
$mutEvidenceOrphanBlind = @(Test-ScaffoldMutationEvidenceExamples -Variant 'orphan-blind')
$mutCoverProbe = @(Test-ScaffoldMutationEvidenceCoverageExamples)
$mutCoverSubstring = @(Test-ScaffoldMutationEvidenceCoverageExamples -Variant 'substring-match')
$mutRowProbe = @(Test-ScaffoldMutationEvidenceRowExamples)
$mutEvidenceFindings = @(Get-ScaffoldMutationEvidenceIssue -RegistryDir 'specs/mutations' -Pending $mutEvidencePending -AnchorPending @(Get-ScaffoldMutationAnchorPending) -RepoRoot $RepoRoot)
if ($mutEvidenceProbe.Count -ne 0) {
  Fail "14p probe: Test-ScaffoldMutationEvidenceExamples own declared cases do not hold, so its verdict over this repo corpus proves nothing. Fix the predicate in scripts/_guard.ps1, never the examples. Got: $($mutEvidenceProbe -join ' | ')"
}
elseif ($mutCoverProbe.Count -ne 0) {
  Fail "14p coverage probe: Test-ScaffoldMutationEvidenceCoverageExamples own declared cases do not hold, so every COVERED verdict this sub-gate reports over the corpus is unproven (TD219). Fix the predicate in scripts/_guard.ps1, never the examples. Got: $($mutCoverProbe -join ' | ')"
}
elseif ($mutRowProbe.Count -ne 0) {
  Fail "14p row probe: Test-ScaffoldMutationEvidenceRowExamples own declared cases do not hold, so the LIVE half of this sub-gate is unproven - a malformed results row may be dropped in silence instead of reported, or the wrapper may not be calling the coverage core at all (TD219). Fix the predicate in scripts/_guard.ps1, never the examples. Got: $($mutRowProbe -join ' | ')"
}
elseif ($mutEvidenceRowBlind.Count -lt 1 -or $mutEvidenceVerdictBlind.Count -lt 1 -or $mutEvidenceStaleShape.Count -lt 1 -or $mutEvidenceOrphanBlind.Count -lt 1 -or $mutCoverSubstring.Count -lt 1) {
  Fail "14p anti-vacuous: feeding the same cases to the rejected shapes 'row-blind' ($($mutEvidenceRowBlind.Count) disagreement(s)), 'verdict-blind' ($($mutEvidenceVerdictBlind.Count)), 'ignore-stale' ($($mutEvidenceStaleShape.Count)), 'orphan-blind' ($($mutEvidenceOrphanBlind.Count)) and 'substring-match' ($($mutCoverSubstring.Count)) left at least one at ZERO - the example table no longer discriminates a shape it must, so that shape could be merged back in unnoticed. [FIX] restore the missing case, never relax the rejected shape. Re-check with: selftest.ps1 -Only 14"
}
elseif ($mutEvidenceFindings.Count -gt 0) {
  foreach ($me in $mutEvidenceFindings) { Fail "14p mutation evidence: $me Re-check with: selftest.ps1 -Only 14" }
}
elseif (-not $fail) {
  Write-Host "  14p [MUT-EVIDENCE-OK] every registry entry under specs/mutations/ is still covered by the evidence its own results row recorded - matched as a whole element, so a claim that is merely a PREFIX of the recorded text does not count (TD219) - or is one of the $($mutEvidencePending.Count) declared on MutationEvidencePending, and every one of those declarations still names an entry that exists (a three-way ratchet: an undeclared uncovered entry reds, a declared entry covered again reds as STALE, and a declared key whose entry was retired reds as ORPHAN)" -ForegroundColor Green
}
}
# 14q. (T274-TIER-ACCEPTANCE / ADR 0016 item 2): the -TaskId acceptance face, driven END TO END.
#   Everything else about the tiered run is a pure function with a declared-examples table beside it - the
#   route list, the gate set, the tier itself. None of them can answer the only question that matters at
#   ship time: does naming a card actually run those gates and conclude on that sentinel. So one seeded
#   fixture drives the real script over a synthetic Tier-0 card and asserts the four things a reader would
#   otherwise have to take on trust - the pass sentinel, the gate LIST inside it, the ABSENCE of
#   `selftest: PASS` (a tiered run is not the full-run acceptance face and must never look like one), and
#   the fail-closed refusals. Tier 0 is chosen because its set is fixed by rule rather than routed, so the
#   assertion is a constant rather than a function of whatever the fixture's diff happened to touch.
#   RE-ENTRANCY: the child runs gate 14, which is this gate, so it would spawn its own child forever. The
#   child therefore carries SCAFFOLD_TIER_FIXTURE and this body skips under it, announcing the skip. That
#   is a guard on an ENVIRONMENT VARIABLE, not on a tool, so it is outside 8.2j's Get-Command projection by
#   construction rather than by exclusion.
Step '14q/17 -TaskId tiered acceptance (a synthetic Tier-0 card driven end to end through the real script)'
if ($env:SCAFFOLD_TIER_FIXTURE) {
  Write-Host '  14q skipped (SCAFFOLD_TIER_FIXTURE is set - this run IS the child 14q spawns, and running the fixture again would recurse without bound).' -ForegroundColor DarkGray
}
else {
  # The fail-closed refusals first, and against the REAL script rather than a clone: every one of them exits
  # before a single gate runs, so they cost milliseconds, and putting them first means a broken refusal is
  # reported even when the expensive half below cannot run at all.
  $tqRefusals = @(
    @{ Args = @('-TaskId', 'T274-TIER-ACCEPTANCE', '-Only', '1'); Sentinel = '[SELFTEST-TASKID-CONFLICT]'; Why = '-TaskId with -Only: two different answers about which gates this run proved' }
    @{ Args = @('-TaskId', 'T274-TIER-ACCEPTANCE', '-Parallel'); Sentinel = '[SELFTEST-TASKID-CONFLICT]'; Why = '-TaskId with -Parallel: the shard union is the FULL suite, which is not a computed tier' }
    @{ Args = @('-TaskId', 'T9-NO-SUCH-CARD-EXISTS'); Sentinel = '[SELFTEST-TASKID-UNKNOWN]'; Why = 'a well-formed id the baseline carries no card for: no card means no computed bar, so the run is refused rather than defaulted' }
    @{ Args = @('-TaskId', '../archive/tasks/T274-TIER-ACCEPTANCE'); Sentinel = '[SELFTEST-TASKID-BADID]'; Why = 'a TRAVERSAL, not an id: it resolved to an archived card - frozen history read as an acceptance target - because the value reached Join-Path without ever being judged as an id (T280)' }
    @{ Args = @('-TaskId', ''); Sentinel = '[SELFTEST-TASKID-BADID]'; Why = 'a BOUND but empty id: it used to fall through to a plain full run, so a script that meant to name a card silently proved something else and no tier was computed at all (T280)' }
  )
  foreach ($tqR in $tqRefusals) {
    $tqOut = (& pwsh -NoProfile -File (Join-Path $RepoRoot 'scripts/selftest.ps1') @($tqR.Args) 2>&1 | Out-String)
    $tqExit = $LASTEXITCODE
    if ($tqExit -ne 2) {
      Fail "14q refusal ($($tqR.Why)): selftest.ps1 $($tqR.Args -join ' ') exited $tqExit, expected 2. A combination that cannot be answered has to be refused fail-closed; exiting 0 or 1 lets a run claim a bar nobody computed.`nActual output: $tqOut"
    }
    elseif ($tqOut -notmatch [regex]::Escape($tqR.Sentinel)) {
      Fail "14q refusal ($($tqR.Why)): the run exited 2 but printed no $($tqR.Sentinel) sentinel, so nothing downstream can tell this refusal from any other exit 2 (L165: a bare non-zero is not evidence).`nActual output: $tqOut"
    }
  }
  if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    Write-Host '  14q end-to-end fixture skipped (git 未安装 - the fixture needs a repository snapshot and a diff to read; the five fail-closed refusals above ran and are unaffected).' -ForegroundColor DarkGray
  }
  else {
    $tqRoot = Join-Path ([System.IO.Path]::GetTempPath()) ('st14q_' + [guid]::NewGuid().ToString('N').Substring(0, 8))
    try {
      # Same snapshot recipe gate 15 and -Parallel use: clone, put the SOURCE's HEAD in place, then overlay
      # the working tree on top. The overlay is what makes this fixture judge the tree in front of it rather
      # than the last commit - without it an uncommitted edit to this very file would be tested by its own
      # previous version, which is the shape of a fixture that passes forever.
      & git clone --quiet --no-hardlinks $RepoRoot $tqRoot 2>$null
      if ($LASTEXITCODE -ne 0) { throw 'git clone of the repo snapshot failed' }
      $tqHead = (& git -C $RepoRoot rev-parse HEAD 2>$null)
      if ($tqHead) { & git -C $tqRoot checkout --quiet --detach $tqHead 2>$null }
      foreach ($tqD in @(& git -C $RepoRoot status --porcelain 2>$null)) {
        if ($tqD.Length -le 3) { continue }
        $tqP = $tqD.Substring(3); if ($tqP -match ' -> ') { $tqP = ($tqP -split ' -> ')[-1] }
        $tqP = $tqP.Trim('"')
        $tqSrc = Join-Path $RepoRoot $tqP; $tqDst = Join-Path $tqRoot $tqP
        if (Test-Path -LiteralPath $tqSrc -PathType Leaf) { New-Item -ItemType Directory -Force (Split-Path $tqDst) | Out-Null; Copy-Item -LiteralPath $tqSrc -Destination $tqDst -Force }
        elseif (-not (Test-Path -LiteralPath $tqSrc)) { Remove-Item -LiteralPath $tqDst -Force -ErrorAction SilentlyContinue }
      }
      # A synthetic Tier-0 card: every allow_path under Tier0Paths, nothing under TierSPaths. No debt row in
      # the title - see the FIXTURE CONVENTION note at the head of gate 10. Since T280 it is COMMITTED, and
      # that is the point of the case rather than a detail of it: the tier is read from the card the
      # BASELINE carries, so a card living only in a working tree is refused (asserted separately below).
      $tqCard = @('---', 'id: T9-TIER-FIXTURE', 'title: seeded tiered-acceptance case', 'status: todo',
        'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/x.ps1)) { exit 1 }"', 'dod_exit: 0',
        'allow_paths:', '  - docs/T9-TIER-FIXTURE-NOTE.md', '  - specs/tasks/T9-TIER-FIXTURE.md',
        '---', '', '# seeded card (T9-TIER-FIXTURE)') -join "`n"
      Set-Content -LiteralPath (Join-Path $tqRoot 'specs/tasks/T9-TIER-FIXTURE.md') -Value $tqCard -Encoding utf8
      & git -C $tqRoot add -- 'specs/tasks/T9-TIER-FIXTURE.md' 2>$null
      & git -C $tqRoot -c user.email='t@t.t' -c user.name='t' commit -q -m 'seed the base card 14q reads' -- 'specs/tasks/T9-TIER-FIXTURE.md' 2>$null
      if ($LASTEXITCODE -ne 0) { throw 'committing the seeded base card failed, so there is no baseline copy to read the tier from' }
      # T280: the fixture's default branch is MAIN, and no ref named master survives in it. The base is
      # detected (Get-ScaffoldDefaultBranchName) rather than written down, so a downstream that never had a
      # `master` is the ordinary case and not a special one; with the literal back, the base would resolve
      # to nothing, the base card could not be read, and the run would refuse - loudly, where T274's version
      # silently took an empty changed set and escalated instead.
      & git -C $tqRoot checkout -q -B main 2>$null
      & git -C $tqRoot update-ref refs/remotes/origin/main HEAD 2>$null
      & git -C $tqRoot symbolic-ref refs/remotes/origin/HEAD refs/remotes/origin/main 2>$null
      & git -C $tqRoot update-ref -d refs/remotes/origin/master 2>$null
      & git -C $tqRoot update-ref -d refs/heads/master 2>$null
      # THE BRANCH'S OWN COPY, and it declares a DIFFERENT tier from the one on the baseline. This is the
      # bypass T274 left open, in the smallest form that can be run inside a gate: whichever copy the script
      # reads decides the tier, and only the base copy computes 0. It is not the cheapening direction spelt
      # with a Tier-S base card only because a Tier-S -TaskId run IS the full suite and no sub-gate can pay
      # 15 minutes; the property under test - the working tree is never the source - is the same one, and
      # this direction additionally catches a "take the stricter of the two" reading, which that one cannot.
      $tqBranchCard = @('---', 'id: T9-TIER-FIXTURE', 'title: seeded tiered-acceptance case', 'status: todo',
        'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path scripts/x.ps1)) { exit 1 }"', 'dod_exit: 0',
        'allow_paths:', '  - scripts/lessons.ps1',
        '---', '', '# seeded card (T9-TIER-FIXTURE), narrowed inside the branch') -join "`n"
      Set-Content -LiteralPath (Join-Path $tqRoot 'specs/tasks/T9-TIER-FIXTURE.md') -Value $tqBranchCard -Encoding utf8
      Set-Content -LiteralPath (Join-Path $tqRoot 'docs/T9-TIER-FIXTURE-NOTE.md') -Value "# seeded note`n`nWritten by selftest sub-gate 14q so the fixture run has a docs-only change to route.`n" -Encoding utf8
      $tqEnvWas = $env:SCAFFOLD_TIER_FIXTURE
      $env:SCAFFOLD_TIER_FIXTURE = '1'
      try {
        $tqSw = [System.Diagnostics.Stopwatch]::StartNew()
        $tqOut = (& pwsh -NoProfile -File (Join-Path $tqRoot 'scripts/selftest.ps1') -TaskId 'T9-TIER-FIXTURE' 2>&1 | Out-String)
        $tqExit = $LASTEXITCODE
        $tqSw.Stop()
      } finally {
        if ($null -eq $tqEnvWas) { Remove-Item Env:SCAFFOLD_TIER_FIXTURE -ErrorAction SilentlyContinue } else { $env:SCAFFOLD_TIER_FIXTURE = $tqEnvWas }
      }
      $tqExpected = '[SELFTEST-TIER-PASS] task=T9-TIER-FIXTURE tier=0 gates=1,2,11,13,14,16'
      if ($tqExit -ne 0) {
        Fail "14q end-to-end: selftest.ps1 -TaskId T9-TIER-FIXTURE exited $tqExit over the snapshot, expected 0. A Tier-0 card owes the floor set and nothing else, so this run is the cheapest one the tiering can produce - if it cannot go green, no card can use the face at all.`nActual output: $tqOut"
      }
      elseif (-not $tqOut.Contains($tqExpected)) {
        Fail "14q end-to-end: the run did not conclude with '$tqExpected'. Either the tier was not computed off the card's allow_paths, or the gate LIST is not the Tier-0 floor - and the list is the part a reader trusts, because it is the only place the run says what it actually proved.`nActual output: $tqOut"
      }
      elseif ($tqOut -match '(?m)^selftest: PASS') {
        Fail "14q end-to-end: a Tier-0 -TaskId run printed 'selftest: PASS'. That line is the FULL-run acceptance face and every consumer that greps for it - CI logs, the mutation classifier, a human reading a ship log - would read a routed subset as the whole suite. Tiers 0 and 1 conclude through [SELFTEST-TIER-PASS] alone (T62's rule for -Only, unchanged and now inherited).`nActual output: $tqOut"
      }
      elseif ($tqOut -notmatch '\[SELFTEST-TIER\] task=T9-TIER-FIXTURE tier=0') {
        Fail "14q end-to-end: the run never announced the tier it computed, so a reader cannot tell a Tier-0 run from a Tier-1 run that happened to route to the same set.`nActual output: $tqOut"
      }
      # T280: the baseline this run judged itself against, named in the output. The clone's default branch
      # is `main` and it carries no ref called master at all, so this line is also the proof that the base
      # is DETECTED: a hardcoded branch name resolves to nothing here and the run cannot even start.
      elseif ($tqOut -notmatch '\[SELFTEST-TASKID-BASE\] base=[0-9a-f]{7,40} branch=main') {
        Fail "14q end-to-end: the run did not announce a resolved base commit on the `main`-default clone. The tier is read from the card as the BASELINE carries it (TD247), so a run that cannot say WHICH commit that was has nothing a reader can check the verdict against - and a base that failed to resolve is how a hardcoded branch name hides (L38).`nActual output: $tqOut"
      }
      # The sentinel says which gates the run OWED. This says how many it RAN, and the two are different
      # claims: hand the derived set to a selector that receives nothing and the sentinel still prints a
      # perfect list over a run that executed no gate at all - green, and proving nothing (the same shape
      # 17ad exists for one gate over).
      # T279: the -TaskId FACE must exclude meta, exactly like every other non-nightly face. Acceptance
      # item 5 says so and nothing executable held it: this child is a real routed run of the real script,
      # so its own sentinels are the evidence - skip lines present, no receipt anywhere, and the counts
      # reconciled by the same closing block the no-arg and -Parallel faces use.
      elseif ($tqOut -notmatch '\[META-SKIP\]') {
        Fail "14q end-to-end: the -TaskId run printed no [META-SKIP] line, so the meta sites were not skipped on the tiered face - either they ran, or the tagging is not reached at all. A routed run is not the nightly and must never pay for the sub-gates whose subject is the harness (T279, acceptance item 5).`nActual output: $tqOut"
      }
      elseif ($tqOut -match '\[META-RAN\]') {
        Fail "14q end-to-end: the -TaskId run filed a [META-RAN] receipt. Only the nightly passes -IncludeMeta; a tiered acceptance that runs the meta sites is paying the cost ADR 0016 item 3 moved off every card (T279, acceptance item 5).`nActual output: $tqOut"
      }
      elseif ($tqOut -notmatch '\[META-SUMMARY\] declared=[0-9]+ ran=0 skipped=[1-9]') {
        Fail "14q end-to-end: the -TaskId run did not close on a [META-SUMMARY] reconciling ran=0 against a non-zero skipped count, so the face reports nothing about the sites it owed and a site going dark on this face would be silent.`nActual output: $tqOut"
      }
      elseif ($tqOut -notmatch '\[GATE-RESULT-SUMMARY\] failed=none ran=6\b') {
        Fail "14q end-to-end: the tiered run concluded on the right sentinel but its [GATE-RESULT-SUMMARY] does not report ran=6. The sentinel states the set the card OWED; this line states what actually executed, and a derived set that never reaches the selector prints the first perfectly while running nothing.`nActual output: $tqOut"
      }
      elseif (-not $fail) {
        # T280, over the SAME clone: a card that exists only in the working tree authorises nothing, so it
        # is refused rather than read. The run above proved the base copy WINS; this proves there is no
        # second path where the working copy is used because no base copy exists to compare it with.
        Set-Content -LiteralPath (Join-Path $tqRoot 'specs/tasks/T9-TIER-WTONLY.md') -Value ($tqCard -replace 'T9-TIER-FIXTURE', 'T9-TIER-WTONLY') -Encoding utf8
        $tqWtOut = (& pwsh -NoProfile -File (Join-Path $tqRoot 'scripts/selftest.ps1') -TaskId 'T9-TIER-WTONLY' 2>&1 | Out-String)
        $tqWtExit = $LASTEXITCODE
        if ($tqWtExit -ne 2 -or $tqWtOut -notmatch 'SELFTEST-TASKID-UNKNOWN') {
          Fail "14q base-card binding: a card written ONLY into the working tree was accepted (exit $tqWtExit), expected the [SELFTEST-TASKID-UNKNOWN] refusal with exit 2. A card the baseline does not carry has authorised nothing yet, so computing a tier from it lets a branch mint its own acceptance bar - the widening the ship scope gate refuses for allow_paths (TD247), arriving through the tier instead.`nActual output: $tqWtOut"
        }
        elseif (-not $fail) {
          Write-Host ("  14q [SELFTEST-TIER-PASS] OK: a synthetic Tier-0 card driven through the real script over a main-default clone ran exactly 1,2,11,13,14,16, took its tier from the BASE copy while the branch's own copy declared a different one, announced the base commit it judged against, concluded on the tier sentinel, never printed selftest: PASS, and -TaskId with -Only / -Parallel / an unknown id / a traversal / an empty id are each refused with their own sentinel ({0}s)" -f [math]::Round($tqSw.Elapsed.TotalSeconds, 1)) -ForegroundColor Green
        }
      }
    }
    catch {
      Fail "14q fixture setup: $($_.Exception.Message). The fixture could not be built, so the -TaskId face is unproven on this run - that is reported rather than skipped, because a fixture that cannot be built is not the same as a tool that is absent."
    }
    finally {
      Remove-Item -Recurse -Force $tqRoot -ErrorAction SilentlyContinue
    }
  }
}

# --- 15. 动态 E2E 冒烟：真跑 task.ps1 start + ship -Local，断言工作流真能跑通（静态闸抓不到的回归）---
# 治本 L38/L39：语法/schema/init 干跑都是**静态**闸，抓不到「只有真跑工作流才暴露」的 bug——
# 例如 task.ps1 曾把 worktree 基线分支硬编码成 'main'，默认分支为 master 的仓库一跑就炸。
# 15a：临时仓默认分支设成 master（≠ main）真跑 task.ps1 -Phase start，断言从「当前分支」建出 worktree。
# 15b：再跑 ship -Local（评审/verify 均走确定性 stub、离线），断言 DoD→verify→范围→预算→许可→密钥→合并整条编排过、产出合并提交——
#      治「ship 全链此前零动态覆盖，glue bug 只在下游首卡才炸」。缺 git 优雅跳过；自带临时 WorktreeRoot，绝不动元仓 / 真实 WorktreeRoot（默认 `C:\wt`，见 `_config.ps1`）。
# 15c/15d：ship 两道确定性闸的种子缺陷（17 系模式）：verify 红（exit 1）必拦、卡外改动必拦，且均须写效果账本
#      （gate=verify / gate=scope）——否则「必拦」只是声称，账本无记录还会被 HARNESS-REVIEW 读作死闸。
Exit-Gate
}

# --- T210 / upstream issue #305: E2E fixture baseline fidelity (used by gate 15's fixture and its 15u control) ---
# A fixture that COPIES a repository has to rebuild the SOURCE's tracked set, not "whatever git add -A would
# stage". The two sets differ on exactly the paths a repo force-added past its own .gitignore (git add -f) -
# the shape this repo's .gitignore tells downstreams to create for sanitized sample data. add -A never stages
# them, so a faithful copy silently loses them and every gate reading the fixture's index judges a tree that
# is not the one under test. Measured on a two-member probe: source tracked {.gitignore, a.db, b.db,
# readme.md}, baseline after add -A {.gitignore, readme.md} - both .db files on disk, neither tracked.
# This repository force-adds nothing today (git ls-files -ci --exclude-standard is empty), which is why the
# defect was invisible here and live downstream; the fixture therefore declares a force-add probe of its own
# rather than relying on a collection that happens to be empty.
function Get-ScaffoldE2eForcePath {
  <#
  .SYNOPSIS  The authoritative force-add collection of a SOURCE repository: every path it tracks that its own
             ignore rules would exclude. An empty collection is a legal answer (this repository returns it).
  .DESCRIPTION
    Derived from git, never from a literal path list - a literal list is what failed downstream, where only
    the first of two allowlisted snapshots was staged. -SkipRootName drops members under a root the fixture
    copy itself excludes: they were never copied, so demanding them in the baseline would red for a reason
    the workflow under test has nothing to do with.
    Total by contract: a source that is not a repository (the -Parallel non-git snapshot; a downstream before
    git init) has no tracked set, so the answer is an empty collection and never a terminating error. Under
    ErrorActionPreference=Stop plus the PS 7.4+ native default (which this gate turns off for itself) git
    ls-files outside a repository THROWS - measured, both prefs required - so the guard has to be a catch
    rather than an exit-code test. Sub-gate 15u arm (e) runs this path with that default back ON.
  #>
  param([Parameter(Mandatory)][string]$SourceDir, [string[]]$SkipRootName = @())
  try {
    $forced = @(& git -C $SourceDir -c core.quotepath=false ls-files -ci --exclude-standard 2>$null)
    $forced = @($forced | Where-Object { ($_ -split '/')[0] -notin $SkipRootName })
    return $forced
  } catch { return @() }
}
function Get-ScaffoldE2eBaselineGap {
  <#
  .SYNOPSIS  Report every expected path the fixture's index does NOT carry. An empty result means the
             baseline reproduces the source's tracked set for the declared collection.
  #>
  param([Parameter(Mandatory)][string]$RepoDir, [string[]]$Expected = @())
  $tracked = @(& git -C $RepoDir -c core.quotepath=false ls-files)
  $gaps = @()
  foreach ($p in @($Expected)) {
    if ($tracked -notcontains $p) { $gaps += "[E2E-BASELINE] '$p' is tracked in the source repository but absent from the fixture baseline - 'git add -A' does not stage a path the ignore rules exclude, so every force-added member has to be staged by name. Re-check with: selftest.ps1 -Only 15" }
  }
  return $gaps
}
function Add-ScaffoldE2eBaseline {
  <#
  .SYNOPSIS  Build a fixture repository's baseline index - everything add -A stages PLUS every declared
             force-add member - then re-read the index and report whatever did not land. Empty = green.
  .DESCRIPTION
    Staging member by member rather than in one add -f call is deliberate: one unstageable member must not
    take the whole collection down with it, and the per-member shape is what the gap check below reports on.
    The builder never trusts that add -f did something - it re-reads the index it just built, because a
    silently skipped member is exactly how a baseline goes incomplete without anyone noticing (issue #305).
  #>
  param([Parameter(Mandatory)][string]$RepoDir, [string[]]$ForcePath = @())
  & git -C $RepoDir add -A 2>$null
  foreach ($p in @($ForcePath)) { & git -C $RepoDir add -f -- $p 2>$null }
  return @(Get-ScaffoldE2eBaselineGap -RepoDir $RepoDir -Expected $ForcePath)
}

# Insert after Add-ScaffoldE2eBaseline. Source: base 2221a418, adapted only for current file placement.
function Remove-Td4MigrationFixtureWorktree {
  param(
    [Parameter(Mandatory)][string]$RepoRoot,
    [Parameter(Mandatory)][string]$WorktreePath,
    [int]$MaxAttempts = 3,
    [int]$RetryDelayMs = 250,
    [scriptblock]$AttemptInvoker,
    [scriptblock]$RegistrationProbe,
    [scriptblock]$SleepInvoker
  )

  $comparison = if ($IsWindows) { [System.StringComparison]::OrdinalIgnoreCase } else { [System.StringComparison]::Ordinal }
  $targetPath = [System.IO.Path]::GetFullPath($WorktreePath)
  $diagnostics = [System.Collections.Generic.List[string]]::new()
  $lastRegistered = $true
  $lastPathExists = Test-Path -LiteralPath $targetPath
  for ($attempt = 1; $attempt -le $MaxAttempts; $attempt++) {
    try {
      if ($AttemptInvoker) {
        $attemptResult = & $AttemptInvoker $attempt $targetPath
      } else {
        $removeOutput = (& git -C $RepoRoot worktree remove --force $targetPath 2>&1 | Out-String)
        $attemptResult = [PSCustomObject]@{ Exit = $LASTEXITCODE; Output = $removeOutput }
      }
    } catch { $attemptResult = [PSCustomObject]@{ Exit = 99; Output = $_.Exception.ToString() } }
    $removeExit = if ($null -ne $attemptResult.Exit) { [int]$attemptResult.Exit } else { 99 }
    $removeOutput = [string]$attemptResult.Output
    $listOutput = if ($RegistrationProbe) { '' } else { (& git -C $RepoRoot worktree list --porcelain 2>&1 | Out-String) }
    $listExit = if ($RegistrationProbe) { 0 } else { $LASTEXITCODE }
    $lastRegistered = if ($RegistrationProbe) { [bool](& $RegistrationProbe $targetPath) } elseif ($listExit -ne 0) { $true } else {
      @($listOutput -split '\r?\n' | Where-Object { $_.StartsWith('worktree ', [System.StringComparison]::Ordinal) } | Where-Object {
        try { [System.IO.Path]::GetFullPath($_.Substring(9)).Equals($targetPath, $comparison) } catch { $false }
      }).Count -gt 0
    }
    $fallbackExit = $null; $fallbackOutput = ''
    if (-not $AttemptInvoker -and -not $lastRegistered -and (Test-Path -LiteralPath $targetPath)) {
      try { Remove-Item -LiteralPath $targetPath -Recurse -Force -ErrorAction Stop; $fallbackExit = 0 }
      catch { $fallbackExit = 99; $fallbackOutput = $_.Exception.ToString() }
    }
    $lastPathExists = Test-Path -LiteralPath $targetPath
    $detail = [System.Collections.Generic.List[string]]::new()
    [void]$detail.Add("attempt=$attempt registered=$lastRegistered pathExists=$lastPathExists")
    [void]$detail.Add("remove-exit=$removeExit")
    if ($removeOutput) { [void]$detail.Add("remove-detail=$removeOutput") }
    [void]$detail.Add("list-exit=$listExit")
    if ($listExit -ne 0 -and $listOutput) { [void]$detail.Add("list-detail=$listOutput") }
    if ($null -ne $fallbackExit) {
      [void]$detail.Add("fallback-exit=$fallbackExit")
      if ($fallbackOutput) { [void]$detail.Add("fallback-detail=$fallbackOutput") }
    }
    [void]$diagnostics.Add($detail -join "`n")
    if (-not $lastRegistered -and -not $lastPathExists) {
      return [PSCustomObject]@{ Success = $true; Attempts = $attempt; Diagnostics = ($diagnostics -join "`n---`n"); Registered = $false; PathExists = $false }
    }
    if ($attempt -lt $MaxAttempts) {
      if ($SleepInvoker) { & $SleepInvoker $RetryDelayMs } else { Start-Sleep -Milliseconds $RetryDelayMs }
      continue
    }
  }
  return [PSCustomObject]@{ Success = $false; Attempts = $MaxAttempts; Diagnostics = ($diagnostics -join "`n---`n"); Registered = $lastRegistered; PathExists = $lastPathExists }
}

function Restore-Td4ContinueProbeFixture {
  param(
    [string]$ProbeFile, [bool]$ProbeCreated, [bool]$ProbeExistedBefore,
    [AllowEmptyString()][string]$ProbeOriginal, [bool]$ProbeOriginalCaptured,
    [string]$BuildFile, [AllowEmptyString()][string]$BuildOriginal, [bool]$BuildOriginalCaptured,
    [string]$TenancyFile, [AllowEmptyString()][string]$TenancyOriginal, [bool]$TenancyOriginalCaptured
  )
  $errors = [System.Collections.Generic.List[string]]::new()
  try { if ($ProbeCreated -and $ProbeFile -and (Test-Path -LiteralPath $ProbeFile)) { Remove-Item -LiteralPath $ProbeFile -Force -ErrorAction Stop } } catch { [void]$errors.Add("probe: $($_.Exception.Message)") }
  try { if ($BuildFile -and $BuildOriginalCaptured -and (Test-Path -LiteralPath $BuildFile)) { [System.IO.File]::WriteAllText($BuildFile, $BuildOriginal, [System.Text.UTF8Encoding]::new($false)) } } catch { [void]$errors.Add("build: $($_.Exception.Message)") }
  try { if ($TenancyFile -and $TenancyOriginalCaptured -and (Test-Path -LiteralPath $TenancyFile)) { [System.IO.File]::WriteAllText($TenancyFile, $TenancyOriginal, [System.Text.UTF8Encoding]::new($false)) } } catch { [void]$errors.Add("tenancy: $($_.Exception.Message)") }
  try { $probeRestored = if (-not $ProbeFile) { $true } elseif ($ProbeExistedBefore) { $ProbeOriginalCaptured -and (Test-Path -LiteralPath $ProbeFile) -and ([System.IO.File]::ReadAllText($ProbeFile) -ceq $ProbeOriginal) } else { -not (Test-Path -LiteralPath $ProbeFile) } } catch { [void]$errors.Add("probe-state: $($_.Exception.Message)"); $probeRestored = $false }
  try { $buildRestored = if (-not $BuildFile) { $true } elseif (-not $BuildOriginalCaptured) { $false } else { (Test-Path -LiteralPath $BuildFile) -and ([System.IO.File]::ReadAllText($BuildFile) -ceq $BuildOriginal) } } catch { [void]$errors.Add("build-state: $($_.Exception.Message)"); $buildRestored = $false }
  try { $tenancyRestored = if (-not $TenancyFile) { $true } elseif (-not $TenancyOriginalCaptured) { $false } else { (Test-Path -LiteralPath $TenancyFile) -and ([System.IO.File]::ReadAllText($TenancyFile) -ceq $TenancyOriginal) } } catch { [void]$errors.Add("tenancy-state: $($_.Exception.Message)"); $tenancyRestored = $false }
  return [PSCustomObject]@{ ProbeRestored = $probeRestored; BuildRestored = $buildRestored; TenancyRestored = $tenancyRestored; ProbeFile = $ProbeFile; BuildFile = $BuildFile; TenancyFile = $TenancyFile; Errors = @($errors) }
}

function Test-Td4ContinueProbeCleanupComplete {
  param([Parameter(Mandatory)][object]$Cleanup)
  return $Cleanup.ProbeRestored -and $Cleanup.BuildRestored -and $Cleanup.TenancyRestored -and @($Cleanup.Errors).Count -eq 0
}

function Get-Td4ContinueProbeCleanupDiagnostics {
  param([Parameter(Mandatory)][object]$Cleanup)
  $state = @("ProbeRestored=$($Cleanup.ProbeRestored) path=$($Cleanup.ProbeFile)", "BuildRestored=$($Cleanup.BuildRestored) path=$($Cleanup.BuildFile)", "TenancyRestored=$($Cleanup.TenancyRestored) path=$($Cleanup.TenancyFile)") -join '; '
  $errorDetail = if (@($Cleanup.Errors).Count -eq 0) { 'none' } else { @($Cleanup.Errors) -join ' | ' }
  return "$state; collectedErrors=$errorDetail"
}

if (Enter-Gate '15') {
Step '15/17 动态 E2E 冒烟（task.ps1 start + ship -Local 真跑工作流：master 默认分支下建 worktree → 全链 ship 到合并提交）'
$git = Get-Command git -ErrorAction SilentlyContinue
# T213/TD208: the dynamic e2e region, span 1 of 2. Everything from the repo copy through the license-gate
# group; span 2 is 15j/15k further down. Bodies are NOT re-indented - they carry here-strings whose '@
# terminators must sit at column 0, and PowerShell reads braces, not indentation.
if (Test-Gate15RegionSelected 'e2e') {
if (-not $git) {
  Write-Host '  git 未安装，跳过（离线 / 无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  # 让原生命令非零退出**不抛**（只置 $LASTEXITCODE），这样下面能优雅 Fail 而非崩出栈（PS7.4+ 默认会抛）。
  $PSNativeCommandUseErrorActionPreference = $false
  $e2e = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-e2e-$PID"
  if (Test-Path $e2e) { Remove-Item -Recurse -Force $e2e }
  New-Item -ItemType Directory -Force $e2e | Out-Null
  try {
    # 拷忠实载荷（同闸 ⑧：排除版本库/依赖/运行时/本地工作区）。task 链不读 CLAUDE.md，故保留无妨。
    $e2eSkip = $RootIgnore + @('_local')
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $e2eSkip } |
      Copy-Item -Destination $e2e -Recurse -Force
    # worktree 根 + 账号都指向临时安全值（绝不污染真实 WorktreeRoot；账号非空免 fail-closed，虽 start 不碰 gh）。
    $cfgPath = Join-Path $e2e 'scripts/_config.ps1'
    $cfg = Get-Content $cfgPath -Raw
    $cfg = [regex]::Replace($cfg, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$e2e/wt'" })
    $cfg = [regex]::Replace($cfg, "GhAccount\s*=\s*'[^']*'",   { "GhAccount = 'smoke'" })
    # 15b 的 ship -Local 评审走 pass-stub 后端（确定性+离线；绝不调真 codex——它可能在 PATH 上、联网、非确定）。
    # ship 评审的「裁决逻辑」已由种子闸 17b 覆盖；本闸只验「装起来之后」的编排粘合（DoD→许可→密钥→合并）。
    $reviewStub = @'
[Console]::In.ReadToEnd() | Out-Null
'{"verdict":"pass","reasons":[]}' | Set-Content $env:REVIEW_OUT -Encoding utf8
'@
    Set-Content (Join-Path $e2e 'review-stub.ps1') $reviewStub -Encoding utf8
    $stubPath = (Join-Path $e2e 'review-stub.ps1') -replace '\\', '/'
    $cfg = $cfg.Replace("ReviewCommand = ''", "ReviewCommand = 'pwsh -NoProfile -File $stubPath'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if ($cfg -notmatch 'review-stub') { Fail '闸15b：ReviewCommand pass-stub 未注入（_config 的 ReviewCommand 行格式变了？.Replace 没命中）——否则 ship-loop 静默退化：CI 跳过评审、本地撞真 codex（非确定/联网），覆盖悄悄缩水。' }
    Set-Content $cfgPath $cfg -NoNewline -Encoding utf8
    # verify 亦走确定性 stub（同 review pass-stub 之理：真 verify.ps1 视机器态收紧——pyproject/前端引导后会真跑 ruff/pytest/npm，
    # 会让本闸随机器环境漂移；「verify 红必拦」由 15c 种子缺陷专测，元仓真 verify 的降级路径由 15e 干跑断言）。
    # 注入在 e2e base 提交**之前** → stub 进基线、worktree 继承之，不进 ship diff、不扰 15b/15d 的范围闸。
    Set-Content (Join-Path $e2e 'scripts/verify.ps1') 'exit 0' -Encoding utf8
    # 建临时 git 仓，并**刻意**把默认分支设成 master（≠ main）：若 task.ps1 再硬编码 'main'，此闸必红。
    & git -C $e2e init -q
    & git -C $e2e symbolic-ref HEAD refs/heads/master                 # 版本无关地强制默认分支 = master
    & git -C $e2e config user.email 'selftest@local'                  # 仓级身份：15b ship 的内部 commit/merge 据此（非 -c 内联）
    & git -C $e2e config user.name  'selftest'
    # This fixture is also a repository that FORCE-ADDS a path past its own .gitignore (git add -f) - the
    # shape this repo's .gitignore tells downstreams to create for sanitized sample data, and the shape that
    # took a downstream's gate 15 red (upstream issue #305). Declaring one HERE keeps the force-add limb live
    # on every round instead of only in a consumer that happens to have one: this repository force-adds
    # nothing, so a collection read purely from the live tree would be empty and the limb would never run.
    # *.internal.md is ignored by the copied .gitignore, needs no directory to exist (unlike a data/ path),
    # and matches no check-secrets sensitive pattern, so 15b's secrets leg is unaffected.
    Set-Content (Join-Path $e2e 'e2e-force-add-probe.internal.md') 'force-added past .gitignore so the baseline force-add limb runs every round (T210)' -Encoding utf8
    $e2eForce = @(Get-ScaffoldE2eForcePath -SourceDir $RepoRoot -SkipRootName $e2eSkip) + @('e2e-force-add-probe.internal.md')
    $e2eGap = @(Add-ScaffoldE2eBaseline -RepoDir $e2e -ForcePath $e2eForce)
    if ($e2eGap.Count) { Fail "15 (T210): the e2e fixture baseline does not reproduce the source repository's tracked set, $($e2eGap.Count) finding(s) - $($e2eGap -join ' | ')" }
    & git -C $e2e -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'e2e base' *> $null
    # 写一张最小合法卡（满足 check-cards：id=文件名 / status 枚举 / dod_command / allow_paths）。
    $cardDir = Join-Path $e2e 'specs/tasks'
    New-Item -ItemType Directory -Force $cardDir | Out-Null
    $cardBody = @(
      '---', 'id: T0-SMOKE', 'title: selftest dynamic e2e smoke', 'status: todo',
      'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - README.md', '---',
      '# e2e smoke card（selftest 闸 15 真跑 task start + ship -Local 用；DoD 用 check-cards 求确定性、不依赖 uv/pytest）'
    ) -join "`n"
    Set-Content (Join-Path $cardDir 'T0-SMOKE.md') $cardBody -Encoding utf8
    # T241/TD247: the card is REGISTERED ON THE BASE BRANCH, because that is where the ship scope gate reads
    # allow_paths from. Until T241 this fixture shipped a card committed nowhere at all, and it passed only
    # because the gate then read the main checkout's working file - the fail-open TD247 records, exercised
    # here as if it were the supported workflow. 15w's cards have been published to base since T233 for the
    # same reason, and 15d2 puts its card in the base commit; this one was the outlier.
    & git -C $e2e add -- specs/tasks/T0-SMOKE.md *> $null
    & git -C $e2e -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'register the e2e smoke card on the base branch' *> $null
    # 真跑 start：**不传 -Base**，强制走 task.ps1 的当前分支自动探测（正是 L38 的回归点）。
    & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase start *> $null
    $startExit = $LASTEXITCODE
    $wtDir = Join-Path $e2e 'wt/T0-SMOKE'
    if ($startExit -ne 0) { Fail "task.ps1 -Phase start 非零退出（$startExit）——真跑工作流失败（worktree 基线分支硬编码 main？见 L38）。" }
    elseif (-not (Test-Path $wtDir)) { Fail "task.ps1 start 退出 0 但未建出 worktree（$wtDir）。" }
    else { Write-Host '  动态 E2E OK（start）：默认分支 master 下 task start 从当前分支建出 worktree、exit 0' -ForegroundColor Green }

    # 15b. ship -Local 全链冒烟（治本盲点：start 之外，「装起来之后」的 ship 编排——DoD→verify→范围闸→预算闸→许可闸→
    #   密钥闸→R3→-Local 合并——此前零动态覆盖；正是 L39「静态绿≠工作流真能跑」要堵的面）。在 worktree 里造一处真改动
    #   （否则 --no-ff 合并为空、无合并提交可断言），跑 ship -Local -SkipRed，断言 exit 0 且产出合并提交。
    #   离线确定性：评审/verify 走上面的 stub（非真 codex/机器态）；许可闸无 pyproject 跳过；账号守卫 -Local 跳过。
    if (-not $fail -and (Test-Path $wtDir)) {
      Set-Content (Join-Path $wtDir 'README.md') 'e2e ship-loop smoke change' -Encoding utf8   # allow_paths 内的真改动
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed *> $null
      $shipExit = $LASTEXITCODE
      $mergeCount = @(& git -C $e2e rev-list --merges HEAD 2>$null).Count
      if ($shipExit -ne 0) { Fail "task.ps1 -Phase ship -Local 非零退出（$shipExit）——ship 编排链断（DoD/verify/范围/预算/许可/密钥/评审/合并之一）。" }
      elseif ($mergeCount -lt 1) { Fail 'ship -Local 退出 0 但 master 上无合并提交（--no-ff 未生效 / worktree 改动未提交？）。' }
      else { Write-Host '  动态 E2E OK（ship -Local）：DoD→verify(stub)→范围→预算→许可→密钥→R3(stub)→-Local 合并全过，exit 0 且产出合并提交' -ForegroundColor Green }

      # 15b'. Required means required on the local merge path too. Reuse this real repository/card/worktree
      # fixture, hide only codex in the child process (all other commands delegate to the built-in cmdlet),
      # empty ReviewCommand, and prove the refusal occurs before any `git merge` reaches the fixture trace.
      if (-not $fail) {
        $lrId = 'T0-LOCALREVIEW'; $lrCard = Join-Path $e2e "specs/tasks/$lrId.md"; $lrCfg = Join-Path $e2e 'scripts/_config.ps1'
        $lrCfgBefore = Get-Content $lrCfg -Raw
        try {
          @('---', "id: $lrId", 'title: required local reviewer seed', 'status: todo', 'dod_command: "pwsh -NoProfile -Command exit 0"', 'allow_paths:', '  - README.md', '---') -join "`n" | Set-Content $lrCard -Encoding utf8
          & git -C $e2e add -- $lrCard *> $null; & git -C $e2e -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'register required local review seed' *> $null
          $lrCfgText = [regex]::Replace($lrCfgBefore, "ReviewGate\s*=\s*'[^']*'", "ReviewGate = 'required'")
          $lrCfgText = [regex]::Replace($lrCfgText, "ReviewCommand\s*=\s*'[^']*'", "ReviewCommand = ''")
          Set-Content $lrCfg $lrCfgText -NoNewline -Encoding utf8
          & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId $lrId -Phase start *> $null
          $lrWt = Join-Path $e2e "wt/$lrId"
          if ($LASTEXITCODE -ne 0 -or -not (Test-Path $lrWt)) { Fail "15b' setup: required-review worktree was not created (exit $LASTEXITCODE)." }
          else {
            Set-Content (Join-Path $lrWt 'README.md') 'required local reviewer must block before merge' -Encoding utf8
            $lrHeadBefore = "$(& git -C $e2e rev-parse master 2>$null)".Trim(); $lrTrace = Join-Path $e2e 'local-required-review.gittrace'; Remove-Item $lrTrace -ErrorAction SilentlyContinue
            $lrWrap = Join-Path $e2e 'local-required-review.ps1'
            Set-Content $lrWrap @'
function global:Get-Command {
  [CmdletBinding()] param([Parameter(Position=0)][string]$Name,[Parameter(ValueFromRemainingArguments=$true)][object[]]$Rest)
  if ($Name -eq 'codex') { return }
  Microsoft.PowerShell.Core\Get-Command $Name @Rest
}
& (Join-Path $PSScriptRoot 'scripts/task.ps1') -TaskId T0-LOCALREVIEW -Phase ship -Local -SkipRed
exit $LASTEXITCODE
'@ -Encoding utf8
            $oldTrace = $env:GIT_TRACE; $env:GIT_TRACE = $lrTrace
            try { $lrOut = (& pwsh -NoProfile -File $lrWrap 2>&1 | Out-String); $lrExit = $LASTEXITCODE } finally { $env:GIT_TRACE = $oldTrace }
            $lrHeadAfter = "$(& git -C $e2e rev-parse master 2>$null)".Trim(); $lrTraceText = if (Test-Path $lrTrace) { Get-Content $lrTrace -Raw } else { '' }
            if ($lrExit -eq 0) { Fail "15b': -Local with ReviewGate=required and no backend exited 0." }
            elseif ($lrOut -notmatch 'SHIP-NO-REVIEWER') { Fail "15b': local required reviewer failure was not SHIP-NO-REVIEWER. Output=$lrOut" }
            elseif ($lrHeadBefore -ne $lrHeadAfter) { Fail "15b': local required reviewer failure advanced master before refusal." }
            elseif ($lrTraceText -notmatch '(?m)built-in: git (?:rev-parse|status)(?:\s|$)') { Fail "15b': GIT_TRACE did not record a fixture git call; the no-merge assertion would be vacuous." }
            elseif ($lrTraceText -match '(?m)built-in: git merge(?:\s|$)') { Fail "15b': local required reviewer failure reached git merge before refusal." }
            else { Write-Host "  15b' local required review backend absent -> SHIP-NO-REVIEWER before merge OK" -ForegroundColor Green }
          }
        } finally { Set-Content $lrCfg $lrCfgBefore -NoNewline -Encoding utf8 }
      }
    }

    # 15c/15d. ship 两道确定性闸的种子缺陷覆盖（17 系模式：enforcer 喂已知坏输入须 BLOCK 且写效果账本——
    #   账本（_local/effectiveness-ledger.jsonl，由 Add-CatchRecord 落）无记录会被 HARNESS-REVIEW 读作死闸）。
    # 15c：把 worktree 的 verify.ps1 stub 成 exit 1 → ship 须在 verify 总闸拦下（闸在提交前，坏 stub 不入库；checkout 还原）。
    if (-not $fail -and (Test-Path $wtDir)) {
      $ledger = Join-Path $e2e '_local/effectiveness-ledger.jsonl'
      Set-Content (Join-Path $wtDir 'scripts/verify.ps1') 'exit 1' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed *> $null
      $vExit = $LASTEXITCODE
      $vRec = (Test-Path $ledger) -and ((Get-Content $ledger -Raw) -match '"gate":"verify"')
      & git -C $wtDir checkout -- scripts/verify.ps1
      if ($vExit -eq 0) { Fail '闸15c：verify.ps1 红（exit 1）时 ship -Local 仍退出 0——verify 总闸没拦（回归：项目级回归红可静默合并）。' }
      elseif (-not $vRec) { Fail '闸15c：verify 总闸拦了但效果账本无 gate=verify 记录（Add-CatchRecord 丢失 → 账本读作死闸）。' }
      else { Write-Host '  15c verify 总闸种子缺陷 OK（verify 红 → ship block + 账本 gate=verify）' -ForegroundColor Green }

      # 15d：种一个卡外文件（docs/oob.md ∉ 卡 allow_paths）→ ship 须在范围闸拦下（越界确定性拦截，非只靠 R3 兜底）。
      Set-Content (Join-Path $wtDir 'docs/oob.md') 'out-of-scope seed' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed *> $null
      $sExit = $LASTEXITCODE
      $sRec = (Test-Path $ledger) -and ((Get-Content $ledger -Raw) -match '"gate":"scope"')
      if ($sExit -eq 0) { Fail '闸15d：卡外改动（docs/oob.md ∉ allow_paths）时 ship -Local 仍退出 0——范围闸没拦（回归：越界改动可静默合并）。' }
      elseif (-not $sRec) { Fail '闸15d：范围闸拦了但效果账本无 gate=scope 记录（Add-CatchRecord 丢失 → 账本读作死闸）。' }
      else { Write-Host '  15d 范围闸种子缺陷 OK（越界改动 → ship block + 账本 gate=scope）' -ForegroundColor Green }

      # 15g. RED 相辅助与闸拆除契约（T68：RED 证据闸已从 ship 拆除——合并闸=确定性闸；-Phase red 保留为
      #   可选 TDD 辅助）。保留案：g4（GREEN dod 下 red 必抛）、g9（red 相前置 check-cards）、新契约案（无证据 ship 直通）。
      $redProofPath = Join-Path $wtDir ".review/T0-SMOKE.red"
      New-Item -ItemType Directory -Force (Join-Path $wtDir '.review') | Out-Null

      # g4：dod 已 GREEN（check-cards 恒 exit 0）时 -Phase red 须非零退出——锁 -Phase red 既有行为（此前零覆盖），
      #   拒「无先失败的测试就固化 RED」。状态无副作用（判定即抛，不写证据）。
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase red *> $null
      if ($LASTEXITCODE -eq 0) { Fail '闸15g4：dod 已 GREEN（check-cards exit 0）时 -Phase red 仍退出 0——RED 检查点没挡「无失败测试即进 RED」（TDD 先测铁律失守）。' }
      else { Write-Host '  15g4 RED 检查点 OK（GREEN dod → -Phase red 非零退出）' -ForegroundColor Green }

      # T68 减法：RED 证据闸已从 ship 拆除（合并闸=确定性闸），原 g1/g2/g3/g5/g6/g7/g8 七案随闸删除；
      # 保留一次成功 ship（原 g5 的正路径收尾）以维持 h 系夹具状态流（合并态 + T24-MERGETOKEN 铸造），
      # 并锁新契约：无 RED 证据的 ship -Local 不得再被阻断。
      Remove-Item (Join-Path $wtDir 'docs/oob.md') -Force -ErrorAction SilentlyContinue   # 清 15d 越界种子
      Remove-Item $redProofPath -Force -ErrorAction SilentlyContinue
      Set-Content (Join-Path $wtDir 'README.md') 'e2e red-gate-removed ship' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local *> $null
      if ($LASTEXITCODE -ne 0) { Fail '闸15g(T68)：无 RED 证据的 ship -Local 非零退出——RED 证据闸已拆除（T68），ship 不得因缺证据阻断。' }
      else { Write-Host '  15g(T68) RED 闸拆除契约 OK（无证据 ship -Local 直通确定性闸并合并）' -ForegroundColor Green }

      # 15w. [CARD-BUDGET-GATE] (T233/TD235): the ship-side card-budget block, driven end to end through a
      #   real task.ps1 ship rather than through the decision core. The core's own state table is already
      #   covered by its declared examples (T231); what nothing tests until here is the WIRING - which ref
      #   the budget is read from, which diff is measured against it, and which states block.
      #   All four cases drive the SAME oversized tree, so they are an A/B by construction:
      #     15w1  base card declares budget: 5, diff is dozens of lines  => BLOCK, with the sentinel and a
      #           gate=card-budget ledger record (a gate with no ledger entry reads as dead to HARNESS-REVIEW)
      #     15w2  the branch raises its OWN copy to 5000, base still 5   => STILL BLOCKS
      #     15w3  the raise lands on the BASE card instead               => ships
      #     15w4  a card declaring NO budget, same oversized shape       => ships, and SAYS what it measured
      #   15w2 is the one that proves the mechanism instead of assuming it: a budget a card can raise inside
      #   the diff being judged judges nothing, which is why the base-card binding is the whole design.
      #   15w4 pins the forbid clause - `budget:` is not required, and the configured CardBudgetDefault is
      #   the METER's reporting affordance, never a merge block, so a card that predates the field ships
      #   exactly as it did before. It asserts the REPORTED LINE COUNT and not merely exit 0, because a
      #   gate that measured nothing also exits 0 and would satisfy a bare exit-code assertion (L239).
      if (-not $fail) {
        $cbLedger = Join-Path $e2e '_local/effectiveness-ledger.jsonl'
        $cbBig = ((1..40 | ForEach-Object { "card budget seed line $_" }) -join "`n")
        $cbBig2 = ((1..60 | ForEach-Object { "second card budget seed line $_" }) -join "`n")

        function Write-CbCard([string]$CbRoot, [string]$CbId, [string]$CbBudget) {
          $cbL = @('---', "id: $CbId", 'title: seeded card budget ship gate', 'status: todo')
          if ($CbBudget) { $cbL += "budget: $CbBudget" }
          $cbL += @('dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - README.md', "  - specs/tasks/$CbId.md", '---')
          Set-Content (Join-Path $CbRoot "specs/tasks/$CbId.md") ($cbL -join "`n") -Encoding utf8
        }
        function Publish-CbCard([string]$CbId, [string]$CbWhy) {
          & git -C $e2e add -- "specs/tasks/$CbId.md" *> $null
          & git -C $e2e -c user.email='selftest@local' -c user.name='selftest' commit -q -m $CbWhy *> $null
        }
        function Invoke-CbShip([string]$CbId) {
          $cbText = (& pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId $CbId -Phase ship -Local -SkipRed 2>&1 | Out-String)
          return [pscustomobject]@{ Exit = $LASTEXITCODE; Out = $cbText }
        }
        function Test-CbLedger { return ((Test-Path $cbLedger) -and ((Get-Content $cbLedger -Raw) -match '"gate":"card-budget"')) }

        $cbId = 'T0-BUDGET'
        Write-CbCard $e2e $cbId '5'
        Publish-CbCard $cbId 'register the seeded card-budget card on the base branch'
        & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId $cbId -Phase start *> $null
        $cbWt = Join-Path $e2e "wt/$cbId"
        if ($LASTEXITCODE -ne 0 -or -not (Test-Path $cbWt)) {
          Fail "闸15w 前置：seeded budget card $cbId 的 -Phase start 未建出 worktree（$cbWt）——ship 侧预算闸无法被驱动，本段四例全部落空。"
        }
        else {
          Set-Content (Join-Path $cbWt 'README.md') $cbBig -Encoding utf8

          $cb1 = Invoke-CbShip $cbId
          if ($cb1.Exit -eq 0) { Fail '15w1 [CARD-BUDGET-SHIP-W1]: the base card declares budget: 5 and the branch diff runs to dozens of lines, yet ship -Local still exited 0 - the ship-side budget gate did not block. Regression: a declared budget is no longer a merge gate, so an over-budget card can merge silently.' }
          elseif ($cb1.Out -notmatch '\[CARD-BUDGET-OVER\]') { Fail '15w1 [CARD-BUDGET-SHIP-W1]: ship exited non-zero but printed no [CARD-BUDGET-OVER] sentinel. The non-zero could come from another gate (DoD, scope, licence), so reading it as the budget gate blocking is a false green (L95: non-zero is not the same as this assertion firing).' }
          elseif (-not (Test-CbLedger)) { Fail '15w1 [CARD-BUDGET-SHIP-W1]: the budget gate blocked but the effectiveness ledger holds no gate=card-budget record. A dropped Add-CatchRecord makes the ledger read this gate as dead.' }
          else { Write-Host '  15w1 ship 侧预算闸种子缺陷 OK（超 base 卡预算 → block + [CARD-BUDGET-OVER] + 账本 gate=card-budget）' -ForegroundColor Green }

          if (-not $fail) {
            Write-CbCard $cbWt $cbId '5000'
            $cb2 = Invoke-CbShip $cbId
            if ($cb2.Exit -eq 0) { Fail '闸15w2：分支内把自己的卡从 budget: 5 抬到 5000 后 ship -Local 退出 0——预算是从 BRANCH 卡读的，等于卡可以在「被判的这份 diff 里」抬高自己的上限，预算便什么也没判（base-card binding 失守）。' }
            elseif ($cb2.Out -notmatch '\[CARD-BUDGET-OVER\]') { Fail '闸15w2：ship 非零但输出无 [CARD-BUDGET-OVER]——拦它的不是预算闸，本例证明不了 base-card binding。' }
            else { Write-Host '  15w2 base-card binding OK（分支内抬高预算无效，仍按 base 卡的 5 判定并 block）' -ForegroundColor Green }
            Write-CbCard $cbWt $cbId '5'   # restore, so 15w3's raise on the base card merges without a conflict
          }

          if (-not $fail) {
            Write-CbCard $e2e $cbId '9000'
            Publish-CbCard $cbId 'raise the seeded card budget on the base branch, in its own commit'
            $cb3 = Invoke-CbShip $cbId
            if ($cb3.Exit -ne 0) { Fail "闸15w3：把预算抬到 base 卡（9000）后同一棵树 ship -Local 仍非零退出（$($cb3.Exit)）——「抬预算落在 base 分支即放行」这条出路不成立，预算闸就成了不可解的硬顶，而它本该是提示决策、不是天花板。" }
            else { Write-Host '  15w3 抬预算出路 OK（同一棵树，预算抬到 base 卡后 ship 通过并合并）' -ForegroundColor Green }
          }

          if (-not $fail) {
            $cbNone = 'T0-BUDGETNONE'
            Write-CbCard $e2e $cbNone ''
            Publish-CbCard $cbNone 'register a card that declares no budget at all'
            & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId $cbNone -Phase start *> $null
            $cbWtNone = Join-Path $e2e "wt/$cbNone"
            if ($LASTEXITCODE -ne 0 -or -not (Test-Path $cbWtNone)) { Fail "闸15w4 前置：无预算卡 $cbNone 的 -Phase start 未建出 worktree（$cbWtNone）。" }
            else {
              Set-Content (Join-Path $cbWtNone 'README.md') $cbBig2 -Encoding utf8
              $cb4 = Invoke-CbShip $cbNone
              if ($cb4.Exit -ne 0) { Fail "闸15w4：没有声明 budget: 的卡 ship -Local 非零退出（$($cb4.Exit)）——缺省成了阻断，而 budget: 刻意不是必填字段：这会让每一张早于该字段的在飞卡在验收中途变红（TD235 的 forbid 条款）。" }
              elseif ($cb4.Out -notmatch 'reported only') { Fail '闸15w4：ship 退出 0 但输出没有「报数不阻断」那行——一个什么都没量到的闸同样退出 0，只断言退出码等于没断言（L239：断空/断否之前先断它检视之物存在）。' }
              else { Write-Host '  15w4 缺省即关 OK（无 budget: 的卡照旧 ship，闸只报数：配置里的 CardBudgetDefault 是量表的报数缺省，不是合并闸）' -ForegroundColor Green }
            }
          }
        }
      }

      # 15g9（TD69/L95 · codex R3 纠偏 Dimension #6）：`-Phase red` 前置 check-cards——若危险 dod_command（嵌套
      #   pwsh -Command + 内插 $）在 start 后被编入卡片，red 相须在**跑 dod、铸 RED 证据之前**即被 check-cards 拒。
      #   关键断言是「**不生成 .review/<id>.red**」：删掉 red 相的 check-cards 前置调用后，危险 dod 的 ParserError 仍
      #   让 red 退出非零、但会**铸出**假证据（vacuous RED）——故只有「证据未生成」能证明前置闸真拦在 dod 之前
      #   （否则删掉 task.ps1 的前置调用不会让任何测试变红）。用独立卡/worktree：先写合法卡过 start，再改危险形态测 red。
      $hazId = 'T0-HAZRED'
      $hazCard = Join-Path $cardDir "$hazId.md"
      @('---', "id: $hazId", 'title: seeded red-phase preflight hazard', 'status: todo',
        'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - README.md', '---') -join "`n" |
        Set-Content $hazCard -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId $hazId -Phase start *> $null
      $hazWt = Join-Path $e2e "wt/$hazId"
      if ($LASTEXITCODE -ne 0 -or -not (Test-Path $hazWt)) { Fail "闸15g9 前置：合法卡 $hazId -Phase start 未建出 worktree——无法测 red 相前置闸。" }
      else {
        $hazRedProof = Join-Path $hazWt ".review/$hazId.red"
        # 覆盖两种 -Command 拼写（`-Command` 与 GNU 双横线 `--Command`，codex R3）：各把卡改成该危险形态、跑 -Phase red，
        # 断言前置 check-cards 在跑 dod、铸证据前即拒（退出非零 + **不生成** .review/<id>.red）。模拟「start 后卡片被编成危险 dod」。
        foreach ($hazForm in @(
            @{ tag = '-Command'; dod = 'pwsh -NoProfile -Command "if (-not $ok) { exit 1 }"' },
            @{ tag = '--Command'; dod = 'pwsh -NoProfile --Command "if (-not $ok) { exit 1 }"' })) {
          Remove-Item $hazRedProof -Force -ErrorAction SilentlyContinue   # 清上一轮可能的残留证据
          @('---', "id: $hazId", 'title: seeded red-phase preflight hazard', 'status: todo',
            "dod_command: $($hazForm.dod)", 'allow_paths:', '  - README.md', '---') -join "`n" |
            Set-Content $hazCard -Encoding utf8
          & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId $hazId -Phase red *> $null
          $hazRedExit = $LASTEXITCODE
          if ($hazRedExit -eq 0) { Fail "闸15g9($($hazForm.tag))：危险 dod_command（嵌套 pwsh $($hazForm.tag) + 内插变量）的卡跑 -Phase red 退出 0——red 相前置 check-cards 未拦（TD69 前置闸失守）。" }
          elseif (Test-Path $hazRedProof) { Fail "闸15g9($($hazForm.tag))：危险卡 -Phase red 退出非零但**仍铸出** RED 证据（.review/$hazId.red 存在）——red 未在 dod 之前经 check-cards 拦下，而是让危险 dod 的 ParserError 冒充 RED（vacuous RED；TD69 red 相前置闸被删/绕过）。" }
          elseif (-not $fail) { Write-Host "  15g9($($hazForm.tag)) RED 相前置 check-cards OK（危险 dod 卡 -Phase red 在跑 dod/铸证据前即被拒、无 .red 生成，TD69/L95）" -ForegroundColor Green }
        }
      }

      # 15h. cleanup 脏树守卫种子缺陷（TD47：cleanup 无脏树守卫即 `git worktree remove --force` + `Remove-Item -Recurse -Force`
      #   拆 worktree → 未提交/未跟踪改动不可逆丢失，且 ship 闸序外唯一零覆盖阶段）。**须置于所有 ship 用例之后**——本组会拆除 worktree。
      #   守卫须用 `git status --porcelain`（非 `git branch --merged`：squash-merge 使分支非 base 祖先，--merged 会误拒正路径 cleanup）。
      # h1 安全路径（RED 证明用例）：worktree 有未提交改动 + 无 -Force → cleanup 须拒（非零退出、worktree 原样保留、零删除）。
      #   现码无守卫 → 会 force-destroy 且 exit 0 → 此断言必红（证种子非 vacuous）。
      Set-Content (Join-Path $wtDir 'README.md') 'uncommitted edit that cleanup must not silently destroy' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup *> $null
      $h1Exit = $LASTEXITCODE
      if ($h1Exit -eq 0) { Fail '闸15h1：worktree 有未提交改动且无 -Force 时 -Phase cleanup 仍退出 0——脏树守卫缺失（TD47：未提交改动被 force-destroy、不可逆丢失）。' }
      elseif (-not (Test-Path $wtDir)) { Fail '闸15h1：cleanup 拒绝（非零）但 worktree 已被删——守卫在删除后才判定（须删前守卫、拒时零副作用）。' }
      else { Write-Host '  15h1 cleanup 脏树守卫 OK（未提交改动+无 -Force → 拒绝、worktree 保留）' -ForegroundColor Green }

      # h2 强制覆盖：同一脏树 + -Force → cleanup 须放行（exit 0、worktree 拆除）。证守卫可被显式覆盖、非硬阻断。
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup -Force *> $null
      $h2Exit = $LASTEXITCODE
      if ($h2Exit -ne 0) { Fail "闸15h2：脏树 + -Force 时 -Phase cleanup 仍非零退出（$h2Exit）——-Force 覆盖失效（守卫应可显式放行，否则脏树永久卡死）。" }
      elseif (Test-Path $wtDir) { Fail '闸15h2：-Force cleanup 退出 0 但 worktree 仍在——拆除未生效。' }
      else { Write-Host '  15h2 cleanup -Force 覆盖 OK（脏树 + -Force → 拆除 worktree、exit 0）' -ForegroundColor Green }

      # h3 正路径（无回归）：重建干净 worktree（h2 已删 worktree+分支）→ 无 -Force cleanup 须成功（exit 0、worktree 拆除）。
      #   证守卫不误伤日常正路径——每次 merge 后对干净树 cleanup 都走这条，守卫误拒即等于破坏收尾链。
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase start *> $null
      if (-not (Test-Path $wtDir)) { Fail '闸15h3：重建 worktree 失败（task start 未产出 worktree）——无法验证 cleanup 正路径。' }
      else {
        & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup *> $null
        $h3Exit = $LASTEXITCODE
        if ($h3Exit -ne 0) { Fail "闸15h3：干净 worktree 无 -Force cleanup 非零退出（$h3Exit）——守卫误伤正路径（脏树误判 / 破坏日常 cleanup 收尾）。" }
        elseif (Test-Path $wtDir) { Fail '闸15h3：cleanup 退出 0 但 worktree 仍在——干净树拆除未生效。' }
        else { Write-Host '  15h3 cleanup 正路径 OK（干净 worktree 无 -Force → 拆除、exit 0，守卫不误伤日常收尾）' -ForegroundColor Green }
      }

      # T24-MERGETOKEN 夹具收尾：h2 已消费 15b/15g5 成功 ship 时铸的合并凭据，h3 的 cleanup 无凭据/无 -Force/无 origin →
      #   删除点凭据闸新语义 fail-safe **保留**分支（预期行为，非缺陷）；后续用同名分支重建 worktree，故此处显式删除
      #   夹具残留分支（真实世界对应「确认丢弃 → -Force」或「已合并 → 凭据/在线补验」两条出路）。
      & git -C $e2e branch -D T0-SMOKE 2>$null

      # 15h4. T24-MERGETOKEN 行为回归（R3 #6：静态断言只锁源码形状，此处在本 e2e 夹具里真跑行为）：
      #   (a) 正路径：ship -Local 成功铸凭据（tip 绑定）→ 干净 cleanup 须删分支**并注销凭据**（单次性）；
      #   (b) tip 前移：ship 铸凭据后分支又添新提交 → cleanup（无 -Force）须**保留**分支（旧凭据不授权删新状态，R3 #17）。
      $tokFile = Join-Path (Join-Path (Join-Path $e2e '.git') 'scaffold-merged') 'T0-SMOKE'
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase start *> $null
      Set-Content (Join-Path $wtDir 'README.md') 'h4a probe' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed *> $null
      if ($LASTEXITCODE -ne 0) { Fail '闸15h4(a)：夹具 ship -Local 未过（无法铸凭据）——前置搭建失败。' }
      elseif (-not (Test-Path $tokFile)) { Fail '闸15h4(a)：ship -Local 成功但未铸 T24-MERGETOKEN 凭据文件（<git-common-dir>/scaffold-merged/T0-SMOKE 缺席）。' }
      else {
        & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup *> $null
        $h4aExit = $LASTEXITCODE
        & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
        $h4aBranchAlive = ($LASTEXITCODE -eq 0)
        if ($h4aExit -ne 0) { Fail "闸15h4(a)：凭据在位且 tip 匹配的干净 cleanup 非零退出（$h4aExit）——正路径回归。" }
        elseif ($h4aBranchAlive) { Fail '闸15h4(a)：tip 匹配的合并凭据未授权删除本地分支——正路径回归（收尾链破坏）。' }
        elseif (Test-Path $tokFile) { Fail '闸15h4(a)：分支已删但凭据未注销（单次性失效——残留凭据可再授权一次同名分支删除，R3 #9）。' }
        else { Write-Host '  15h4(a) 凭据正路径 OK（tip 匹配 → 删分支 + 注销凭据）' -ForegroundColor Green }
      }
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase start *> $null
      Set-Content (Join-Path $wtDir 'README.md') 'h4b probe' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed *> $null
      if ($LASTEXITCODE -ne 0) { Fail '闸15h4(b)：夹具第二次 ship -Local 未过——前置搭建失败。' }
      else {
        Set-Content (Join-Path $wtDir 'README.md') 'h4b tip-advance' -Encoding utf8
        & git -C $wtDir add README.md 2>$null
        & git -C $wtDir commit -q -m 'advance tip after mint (15h4b)' *> $null
        & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup *> $null
        $h4bExit = $LASTEXITCODE
        & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
        $h4bBranchAlive = ($LASTEXITCODE -eq 0)
        if ($h4bExit -ne 0) { Fail "闸15h4(b)：tip 前移的 cleanup 非零退出（$h4bExit）——保留分支应为软告警（exit 0），硬失败会卡死收尾链。" }
        elseif (-not $h4bBranchAlive) { Fail '闸15h4(b)：铸造后分支已前移（新提交未合并），旧凭据仍授权删除了分支——R3 #17 数据丢失面未闭合（tip 绑定失效）。' }
        else {
          Write-Host '  15h4(b) tip 前移保留 OK（旧凭据不授权删新状态，分支 fail-safe 保留）' -ForegroundColor Green
          # (c) 不匹配凭据 + -Force（R3 r3 #9：显式覆盖不得被残留/不匹配凭据遮蔽）——沿用 (b) 尾态（tip 前移分支 + 陈旧凭据）。
          & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup -Force *> $null
          $h4cExit = $LASTEXITCODE
          & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
          $h4cBranchAlive = ($LASTEXITCODE -eq 0)
          if ($h4cExit -ne 0) { Fail "闸15h4(c)：陈旧凭据在位 + -Force 的 cleanup 非零退出（$h4cExit）。" }
          elseif ($h4cBranchAlive) { Fail '闸15h4(c)：-Force 被不匹配凭据遮蔽——显式确认丢弃未能删除分支（R3 r3 #9 回归）。' }
          elseif (Test-Path $tokFile) { Fail '闸15h4(c)：-Force 删除后残留凭据未注销——陈旧凭据日后可误配同名新分支。' }
          else { Write-Host '  15h4(c) -Force 优先于凭据 OK（不匹配凭据不遮蔽显式覆盖，连带注销残留凭据）' -ForegroundColor Green }
        }
      }
      # T24-MERGETOKEN 夹具收尾（二）：幂等清场兜底（(c) 正常已删分支+凭据；若 (a)/(b)/(c) 中途 Fail 则此处仍保后续可重建）。
      & git -C $e2e branch -D T0-SMOKE 2>$null
      Remove-Item $tokFile -Force -ErrorAction SilentlyContinue

      # 15h4(d)(e)(f) 仅 Windows 执行：gh stub 用 gh.ps1，仅 Windows 经 PATHEXT 把裸 `gh` 解析成 gh.ps1；Linux/pwsh
      #   无 PATHEXT，`gh` 不解析到 gh.ps1、转而跑**真 gh**（非 stub）→ 在线补验正路径不触发、分支不删、(d) 在 ubuntu
      #   假红（T24 合并后 master 的 ubuntu CI 即因此红）。整段 Windows-guard——同 17aa(8) 的 gh-mock 处理；被测的
      #   online-verify 清理逻辑本身跨平台无关、由 Windows CI 覆盖（Linux 侧此前 stub 从未真被调用，属还原为诚实的 Windows-only）。
      if ($IsWindows) {
      # 15h4(d)(e)(f) 在线补验行为（R3 r4 #6：stub gh + 假 origin，全离线确定，同 15f stub 手法；PATH 用毕还原）：
      #   凭据缺失时——(d) gh 报 MERGED 且 headRefOid==分支 tip → CAS 删除；(e) headRefOid 不匹配 → 保留；
      #   (f) gh 输出不可解析 → 保留（parse-catch fail-safe）。gh 缺席路径由 Get-Command 守卫（15p 词法锁定），不做 PATH 手术。
      #   stub 用 gh.ps1（pwsh 跨 OS 同一解析路径；stub 目录前置 PATH 即赢）。
      $ghStub15h4 = Join-Path $e2e 'gh-stub'
      New-Item -ItemType Directory -Force $ghStub15h4 | Out-Null
      $hadOrigin15h4 = ("$(& git -C $e2e remote get-url origin 2>$null)".Trim() -ne '')
      if (-not $hadOrigin15h4) { & git -C $e2e remote add origin (Join-Path $e2e 'fake-origin.git') 2>$null }
      $oldPath15h4 = $env:Path
      # (d) MERGED + headRefOid 匹配 → CAS 删除
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase start *> $null
      $h4dTip = "$(& git -C $e2e rev-parse T0-SMOKE 2>$null)".Trim()
      Set-Content (Join-Path $ghStub15h4 'gh.ps1') "Write-Output '{""state"":""MERGED"",""headRefOid"":""$h4dTip""}'" -Encoding ascii
      $env:Path = "$ghStub15h4$([IO.Path]::PathSeparator)$oldPath15h4"
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup *> $null
      $h4dExit = $LASTEXITCODE
      $env:Path = $oldPath15h4
      & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
      $h4dBranchAlive = ($LASTEXITCODE -eq 0)
      if ($h4dExit -ne 0) { Fail "闸15h4(d)：在线补验（MERGED + headRefOid 匹配）cleanup 非零退出（$h4dExit）。" }
      elseif ($h4dBranchAlive) { Fail '闸15h4(d)：gh 报 MERGED 且 headRefOid==分支 tip，但分支未被删除——在线补验正路径回归（-NoAutoMerge/他机合并收尾链破坏）。' }
      else { Write-Host '  15h4(d) 在线补验匹配删除 OK（stub gh：MERGED + headRefOid==tip → CAS 删）' -ForegroundColor Green }
      # (e) MERGED 但 headRefOid 不匹配 → 保留
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase start *> $null
      Set-Content (Join-Path $ghStub15h4 'gh.ps1') "Write-Output '{""state"":""MERGED"",""headRefOid"":""0000000000000000000000000000000000000000""}'" -Encoding ascii
      $env:Path = "$ghStub15h4$([IO.Path]::PathSeparator)$oldPath15h4"
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup *> $null
      $h4eExit = $LASTEXITCODE
      $env:Path = $oldPath15h4
      & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
      $h4eBranchAlive = ($LASTEXITCODE -eq 0)
      if ($h4eExit -ne 0) { Fail "闸15h4(e)：在线补验（headRefOid 不匹配）cleanup 非零退出（$h4eExit）——保留分支应为软告警。" }
      elseif (-not $h4eBranchAlive) { Fail '闸15h4(e)：gh 报 MERGED 但 headRefOid≠分支 tip，分支仍被删除——tip 绑定在在线补验路径失效（R3 r3 #17 回归）。' }
      else { Write-Host '  15h4(e) 在线补验不匹配保留 OK（headRefOid≠tip → fail-safe 保留）' -ForegroundColor Green }
      # (f) gh 输出不可解析 → 保留（沿用 (e) 尾态分支；worktree 已拆，cleanup 只走守卫段）
      Set-Content (Join-Path $ghStub15h4 'gh.ps1') "Write-Output 'not-json-at-all'" -Encoding ascii
      $env:Path = "$ghStub15h4$([IO.Path]::PathSeparator)$oldPath15h4"
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase cleanup *> $null
      $h4fExit = $LASTEXITCODE
      $env:Path = $oldPath15h4
      & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
      $h4fBranchAlive = ($LASTEXITCODE -eq 0)
      if ($h4fExit -ne 0) { Fail "闸15h4(f)：gh 输出不可解析时 cleanup 非零退出（$h4fExit）——parse 失败应 fail-safe 保留而非崩相位。" }
      elseif (-not $h4fBranchAlive) { Fail '闸15h4(f)：gh 输出不可解析，分支仍被删除——补验解析失败未走 fail-safe 保留。' }
      else { Write-Host '  15h4(f) 补验不可解析保留 OK（垃圾响应 → parse-catch → fail-safe 保留）' -ForegroundColor Green }
      # 夹具收尾（三）：还原 remote/PATH/stub、清残留分支——15m 需要无远端 + 同名分支可重建的初始形态。
      if (-not $hadOrigin15h4) { & git -C $e2e remote remove origin 2>$null }
      & git -C $e2e branch -D T0-SMOKE 2>$null
      Remove-Item $ghStub15h4 -Recurse -Force -ErrorAction SilentlyContinue
      } else {
        Write-Host '  15h4(d/e/f) 跳过（非 Windows）：gh.ps1 stub 依赖 PATHEXT，仅 Windows 把裸 gh 解析成 gh.ps1；Linux 会跑真 gh（同 17aa(8) 的 gh-mock 仅 Windows）。被测 online-verify 清理逻辑跨平台无关、由 Windows CI 覆盖。' -ForegroundColor DarkGray
      }

      # 15h5. Cardless cleanup (upstream issue #361, the residual L238's enforced_by names). R5 has TWO
      #   steps - this teardown and the cold-store sweep - and archive.ps1 MOVES a merged card from
      #   specs/tasks/ to specs/archive/tasks/. The phase used to resolve its card as a front guard before
      #   doing any work, so once the sweep had run the teardown could not run AT ALL: it exited 1 and told
      #   the operator to create the card, which for a card that just merged is backwards. The phase reads
      #   no card field - both actions derive from the TaskId - so the repair is to stop requiring one.
      #   WHICH STATE THIS ACTUALLY RESCUES, stated precisely because the fixture must reproduce it and the
      #   first version of this sub-gate did not: for a card that declares `worktree:`, [ARCHIVE-HELD] holds
      #   the sweep back while that directory is on disk, so the sweep CANNOT get ahead of a full teardown.
      #   The reachable dead end is the BRANCH-ONLY RESIDUAL that L238's enforced_by names: the worktree is
      #   already gone - removed by hand, or by a cleanup that got that far - while the local branch is
      #   still alive because branch deletion is gated on the merge credential, not on a path test. The
      #   sweep then legitimately moves the card, and the one command that can spend that credential could
      #   no longer run. Arm (a) reproduces exactly that, with a CONFORMING card, and never bypasses the
      #   hold: an earlier version omitted the `worktree:` field so the sweep would take a card whose
      #   worktree was live, which proved the teardown against a state no valid card reaches.
      #   (a) branch-only residual: conforming card, worktree removed, branch and credential retained, the
      #       PRODUCTION archive.ps1 run, then cleanup must delete the residual branch and print
      #       [CLEANUP-CARD-COLD].
      #   (b) card in NEITHER place, on a worktree, branch and credential of its own - what a mistyped
      #       TaskId also looks like - asserting worktree AND branch teardown, since here nothing holds.
      #   (c) the guard is UNCHANGED where a card IS read. `red` and `ship` are asked WITH a worktree in
      #       place: both have an earlier missing-worktree condition that would refuse for a different
      #       reason and leave this arm green for the wrong one (L239). `start` is asked on a clean slate,
      #       where the assertion is that it built nothing. Each case also requires the refusal to NAME the
      #       missing card, so an unrelated refusal cannot be mistaken for this one.
      #   The two sentinels are DISTINCT for the reason the L86-WT/L86-BASE pair is distinct: with one
      #   shared sentinel, either emit could be deleted and this gate would stay green. Each Fail carries an
      #   ASCII tag so the mutation registry can require the arm it PREDICTED and no other (L165(5), L237).
      #   Placed after the 15h4 teardown, which leaves no branch and no worktree, and before 15m, which
      #   rebuilds from specs/tasks/T0-SMOKE.md - this sub-gate rewrites, moves and deletes that file, so
      #   restoring it is part of the fixture and is ASSERTED: a silent restore failure would surface as a
      #   puzzling 15m failure three sub-gates later.
      $cardHot15h5 = Join-Path $e2e 'specs/tasks/T0-SMOKE.md'
      $cardCold15h5 = Join-Path $e2e 'specs/archive/tasks/T0-SMOKE.md'
      $tok15h5 = Join-Path (Join-Path (Join-Path $e2e '.git') 'scaffold-merged') 'T0-SMOKE'
      $task15h5 = Join-Path $e2e 'scripts/task.ps1'
      # The ASCII half of the missing-card refusal - the resolved card path - which is what tells that
      # refusal apart from a missing-worktree one (L17: never assert on the Chinese half).
      $cardDiag15h5 = 'T0-SMOKE.md'
      # Mint a worktree, a branch and a merge credential; returns $true when the setup really happened.
      function Initialize-CardlessFixture15h5 ([string]$Probe) {
        & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase start *> $null
        if (-not (Test-Path $wtDir)) { Fail "[15H5-SETUP] 闸15h5($Probe)：-Phase start 未产出 worktree——前置搭建失败，不是对无卡路径的裁决。"; return $false }
        Set-Content (Join-Path $wtDir 'README.md') "15h5 $Probe probe" -Encoding utf8
        & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase ship -Local -SkipRed *> $null
        if ($LASTEXITCODE -ne 0) { Fail "[15H5-SETUP] 闸15h5($Probe)：夹具 ship -Local 未过（无法铸凭据）——前置搭建失败。"; return $false }
        if (-not (Test-Path $tok15h5)) { Fail "[15H5-SETUP] 闸15h5($Probe)：ship -Local 成功但未铸合并凭据——前置搭建失败。"; return $false }
        return $true
      }
      # Put the fixture card back the way 15m needs it, and clear anything 15h5 built.
      function Restore-CardlessFixture15h5 {
        & git -C $e2e checkout -- specs/tasks/T0-SMOKE.md 2>$null
        Remove-Item (Join-Path $e2e 'specs/archive') -Recurse -Force -ErrorAction SilentlyContinue
        & git -C $e2e worktree remove --force $wtDir 2>$null
        & git -C $e2e worktree prune 2>$null
        & git -C $e2e branch -D T0-SMOKE 2>$null
      }
      # (a) the branch-only residual, produced by the production sweep over a CONFORMING card.
      if (Initialize-CardlessFixture15h5 'a') {
        # Make the card conforming - it must DECLARE the worktree [ARCHIVE-HELD] judges by - and merged.
        $cardA15h5 = (Get-Content $cardHot15h5 -Raw) -replace 'status: todo', "status: merged`nworktree: $wtDir"
        Set-Content $cardHot15h5 $cardA15h5 -Encoding utf8 -NoNewline
        # The hold must be REAL on this card before the residual is created, or arm (a) proves nothing about
        # a state the sweep would otherwise have refused.
        & pwsh -NoProfile -File (Join-Path $e2e 'scripts/archive.ps1') -RepoRoot $e2e -Quiet *> $null
        if (-not (Test-Path $cardHot15h5)) { Fail '[15H5-HOLD] 闸15h5(a)：worktree 仍在磁盘上，archive.ps1 却把这张声明了 worktree: 的 merged 卡搬走了——[ARCHIVE-HELD] 失效，本臂随后构造的「仅剩分支」残留态就不是真实可达态了（T107/L238）。' }
        else {
          # Now the residual itself: drop the worktree, keep the branch and the credential.
          & git -C $e2e worktree remove --force $wtDir 2>$null
          & git -C $e2e worktree prune 2>$null
          & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
          $h5aResidual = ($LASTEXITCODE -eq 0)
          if (Test-Path $wtDir) { Fail '[15H5-RESIDUAL] 闸15h5(a)：worktree 未能移除——无法构造「worktree 已没、分支还在」的残留态。' }
          elseif (-not $h5aResidual) { Fail '[15H5-RESIDUAL] 闸15h5(a)：移除 worktree 连分支也一并没了——残留态的要害正是分支还活着（分支删除只认合并凭据，不认路径）。' }
          elseif (-not (Test-Path $tok15h5)) { Fail '[15H5-RESIDUAL] 闸15h5(a)：合并凭据在构造残留态时丢失——cleanup 将无从授权删除分支，本臂会因错误的原因变红。' }
          else {
            & pwsh -NoProfile -File (Join-Path $e2e 'scripts/archive.ps1') -RepoRoot $e2e -Quiet *> $null
            if (Test-Path $cardHot15h5) { Fail '[15H5-SWEEP-SETUP] 闸15h5(a)：worktree 已不在磁盘上，archive.ps1 仍没把 merged 卡搬出热路径——真实清扫没发生，本臂无从裁决。' }
            elseif (-not (Test-Path $cardCold15h5)) { Fail '[15H5-SWEEP-SETUP] 闸15h5(a)：卡离开了热路径却没出现在 specs/archive/tasks/——拒搬不等于删除，夹具状态不可信。' }
            else {
              $h5aOut = & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase cleanup 2>&1 | Out-String
              $h5aExit = $LASTEXITCODE
              & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
              $h5aBranchAlive = ($LASTEXITCODE -eq 0)
              if ($h5aExit -ne 0) { Fail "[15H5-COLD-EXIT] 闸15h5(a)：真实清扫已把卡搬进冷存后 cleanup 非零退出（$h5aExit）——这正是 issue #361 报的死路：worktree 已没、分支还在，而唯一能花掉合并凭据的命令跑不起来。`n输出=$h5aOut" }
              elseif ($h5aBranchAlive) { Fail '[15H5-COLD-BRANCH] 闸15h5(a)：cleanup 退出 0 但残留分支 T0-SMOKE 仍在——无卡路径没走到凭据授权的删除，搁浅的分支原封不动。' }
              elseif ($h5aOut -notmatch 'CLEANUP-CARD-COLD') { Fail "[15H5-COLD-SENTINEL] 闸15h5(a)：无卡 cleanup 跑了却没打印 [CLEANUP-CARD-COLD]——静默通过等于操作者无从判断自己处在哪种状态。`n输出=$h5aOut" }
              else { Write-Host '  15h5(a) 分支残留态 OK（合规卡 + [ARCHIVE-HELD] 真拦过 → 拆 worktree 造残留 → 真清扫 → cleanup 删掉搁浅分支，打印 [CLEANUP-CARD-COLD]）' -ForegroundColor Green }
            }
          }
        }
      }
      # (b) neither location, on a fixture of its own so worktree AND branch teardown are asserted here.
      Restore-CardlessFixture15h5
      if (Initialize-CardlessFixture15h5 'b') {
        Remove-Item $cardHot15h5 -Force
        $h5bOut = & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase cleanup 2>&1 | Out-String
        $h5bExit = $LASTEXITCODE
        & git -C $e2e rev-parse --verify --quiet T0-SMOKE *> $null
        $h5bBranchAlive = ($LASTEXITCODE -eq 0)
        if ($h5bExit -ne 0) { Fail "[15H5-ABSENT-EXIT] 闸15h5(b)：两处都没有卡时 cleanup 非零退出（$h5bExit）——拆除由 TaskId 派生，不该要求卡在任何地方存在。`n输出=$h5bOut" }
        elseif (Test-Path $wtDir) { Fail '[15H5-ABSENT-WT] 闸15h5(b)：cleanup 退出 0 但 worktree 仍在——两处无卡时报成功却没拆除。' }
        elseif ($h5bBranchAlive) { Fail '[15H5-ABSENT-BRANCH] 闸15h5(b)：worktree 已拆但本地分支仍在——两处无卡时凭据未授权删除，分支搁浅。' }
        elseif ($h5bOut -notmatch 'CLEANUP-CARD-ABSENT') { Fail "[15H5-ABSENT-SENTINEL] 闸15h5(b)：未打印 [CLEANUP-CARD-ABSENT]——这个状态同时也是 TaskId 打错的样子，须单独点名、不能与冷存哨兵合用。`n输出=$h5bOut" }
        elseif ($h5bOut -match 'CLEANUP-CARD-COLD') { Fail "[15H5-ABSENT-CROSSTALK] 闸15h5(b)：冷存里已无卡却打印了 [CLEANUP-CARD-COLD]——两个状态由同一个分支报告，删掉任一个本闸都仍绿。`n输出=$h5bOut" }
        else { Write-Host '  15h5(b) 无卡 cleanup OK（两处皆无 → 拆 worktree + 删分支，打印 [CLEANUP-CARD-ABSENT]）' -ForegroundColor Green }
      }
      # (c) the guard is unchanged where a card IS read.
      $h5cOk = $true
      Restore-CardlessFixture15h5
      # (c1) red and ship, WITH a worktree in place, so neither can refuse for want of one.
      & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase start *> $null
      if (-not (Test-Path $wtDir)) { Fail '[15H5-SETUP] 闸15h5(c)：-Phase start 未产出 worktree——无法在「worktree 在场」的前提下追问 red / ship。'; $h5cOk = $false }
      else {
        $h5cBaseBefore = "$(& git -C $e2e rev-parse master 2>$null)".Trim()
        Remove-Item $cardHot15h5 -Force
        foreach ($h5cPhase in @('red', 'ship')) {
          $h5cOut = if ($h5cPhase -eq 'ship') { & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase ship -Local -SkipRed 2>&1 | Out-String } else { & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase red 2>&1 | Out-String }
          $h5cExit = $LASTEXITCODE
          if ($h5cExit -eq 0) { Fail "[15H5-GUARD-EXIT] 闸15h5(c)：worktree 在场、卡缺席时 -Phase $h5cPhase 退出 0——这些相位读卡字段（dod_command / allow_paths / review_gate / budget），缺卡是真错误，守卫必须保留。"; $h5cOk = $false }
          elseif ($h5cOut -notmatch [regex]::Escape($cardDiag15h5)) { Fail "[15H5-GUARD-DIAG] 闸15h5(c)：-Phase $h5cPhase 非零退出却没点名缺失的卡（输出里找不到 $cardDiag15h5）——worktree 在场时它本不该有别的拒绝理由，这一臂会因错误的原因变绿（L239）。`n输出=$h5cOut"; $h5cOk = $false }
        }
        $h5cBaseAfter = "$(& git -C $e2e rev-parse master 2>$null)".Trim()
        if ($h5cBaseBefore -and ($h5cBaseAfter -ne $h5cBaseBefore)) { Fail '[15H5-GUARD-MERGED] 闸15h5(c)：缺卡的 ship 被拒了，base 分支的 tip 却前移了——拒绝发生在合并之后，副作用已经落地。'; $h5cOk = $false }
      }
      # (c2) start on a clean slate: it BUILDS the worktree, so the assertion is that it built nothing.
      Restore-CardlessFixture15h5
      Remove-Item $cardHot15h5 -Force
      $h5c2Out = & pwsh -NoProfile -File $task15h5 -TaskId T0-SMOKE -Phase start 2>&1 | Out-String
      $h5c2Exit = $LASTEXITCODE
      if ($h5c2Exit -eq 0) { Fail '[15H5-GUARD-EXIT] 闸15h5(c)：缺卡时 -Phase start 退出 0——start 读卡字段，缺卡是真错误。'; $h5cOk = $false }
      elseif (Test-Path $wtDir) { Fail '[15H5-GUARD-SIDEEFFECT] 闸15h5(c)：-Phase start 因缺卡拒绝了，却已经建出 worktree——拒绝须发生在任何副作用之前。'; $h5cOk = $false }
      elseif ($h5c2Out -notmatch [regex]::Escape($cardDiag15h5)) { Fail "[15H5-GUARD-DIAG] 闸15h5(c)：-Phase start 非零退出却没点名缺失的卡。`n输出=$h5c2Out"; $h5cOk = $false }
      if ($h5cOk) { Write-Host '  15h5(c) 缺卡守卫 OK（worktree 在场下 red / ship 仍拒且点名缺卡、base 未前移；start 拒且零副作用——放宽只给了 cleanup）' -ForegroundColor Green }
      # Fixture restore for 15m, asserted rather than assumed.
      Restore-CardlessFixture15h5
      if (-not (Test-Path $cardHot15h5)) { Fail '[15H5-RESTORE] 闸15h5：夹具还原失败——specs/tasks/T0-SMOKE.md 未回到热路径，而 15m 要据它重建 worktree。' }

      # 15m. base==TaskId 守卫（TD-203 / L86）。须置于 15h 之后——它先重建 15h3 拆掉的 worktree。（15i-15l 已被占用。）
      #   夹具须复现两个前提，否则 RED 会因**错误的原因**变绿（vacuous）：
      #   (a) 卡片随分支提交——本夹具把卡写在 $e2e 主检出、且写在 base 提交之后，worktree 检出里没有它；
      #       不补这一步，未加守卫时 task.ps1 会先在「任务卡不存在」处抛，走不到 base==TaskId 那条链。
      #   (b) -SkipRed——历史参数（RED 证据闸已随 T68 拆除，现为兼容 no-op；保留传参不影响行为）。
      #   哨兵取 ASCII `L86`（同 TD50-BADID 手法，免中文断言在异构控制台产假 FAIL · L17）。
      & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase start *> $null
      if (-not (Test-Path $wtDir)) { Fail '闸15m：重建 worktree 失败（task start 未产出 worktree）——无法验证 base==TaskId 守卫。' }
      else {
        # (a) 把卡片提交到分支上（$e2e 的仓级 user.email/name 已配，worktree 提交继承之）。
        Copy-Item (Join-Path $e2e 'specs/tasks/T0-SMOKE.md') (Join-Path $wtDir 'specs/tasks/T0-SMOKE.md') -Force
        & git -C $wtDir add specs/tasks/T0-SMOKE.md 2>$null
        & git -C $wtDir commit -q -m 'card on branch (15m fixture)' *> $null
        if (-not (Test-Path (Join-Path $wtDir 'specs/tasks/T0-SMOKE.md'))) { Fail '闸15m：卡片未落进 worktree——夹具没复现「卡随分支提交」的真实形态，RED 会因「任务卡不存在」而假绿。' }
        $jBaseBefore = (& git -C $e2e rev-parse master 2>$null); if ($jBaseBefore) { $jBaseBefore = $jBaseBefore.Trim() }
        Set-Content (Join-Path $wtDir 'README.md') 'e2e L86 guard probe' -Encoding utf8   # allow_paths 内的真改动
        # 关键：调 **worktree 自带**的 task.ps1（而非 $e2e 主检出那份），且不传 -Base → 复现 $Base 自动派生成 T0-SMOKE。
        $jOut = & pwsh -NoProfile -File (Join-Path $wtDir 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed 2>&1 | Out-String
        $jExit = $LASTEXITCODE
        $jBaseAfter = (& git -C $e2e rev-parse master 2>$null); if ($jBaseAfter) { $jBaseAfter = $jBaseAfter.Trim() }
        if ($jExit -eq 0) { Fail '闸15m(1)：worktree 自带 task.ps1 跑 ship -Local（不传 -Base）仍退出 0——无 in-code 守卫（TD-203/L86）：merge 把分支并进它自己报 "Already up to date."，遂打印「已本地合并」的假成功；随后 cleanup 会 branch -D 强删这条从未合并的分支。' }
        elseif ($jOut -notmatch 'L86-WT') { Fail "闸15m(1)：ship 非零退出但输出不含哨兵 L86-WT——拦它的不是 worktree 自调用守卫（可能是别的闸/夹具没搭对），「非零」断言会因错误原因变绿。实际输出：$jOut" }
        elseif ($jBaseAfter -ne $jBaseBefore) { Fail '闸15m(1)：守卫已拦但 base 分支 tip 变了——守卫触发前已产生提交/合并副作用。' }
        else {
          # (2) R3 catch：只拒 base==TaskId 不够——显式传 -Base master 会绕过该判据，而 $RepoRoot 仍是本卡 worktree，
          #     `git -C $RepoRoot merge $TaskId` 照样把分支并进它自己（exit 0 假成功、base 从未前进；实测仅有一条 WARNING）。
          $kOut = & pwsh -NoProfile -File (Join-Path $wtDir 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed -Base master 2>&1 | Out-String
          $kExit = $LASTEXITCODE
          $kBaseAfter = (& git -C $e2e rev-parse master 2>$null); if ($kBaseAfter) { $kBaseAfter = $kBaseAfter.Trim() }
          if ($kExit -eq 0) { Fail '闸15m(2)：worktree 自带 task.ps1 跑 ship -Local -Base master 仍退出 0——守卫只判 base==TaskId，显式传真实基线即可绕过；而 $RepoRoot 仍是本卡 worktree，merge 照样把分支并进它自己、假报「已本地合并」且 base 从未前进。' }
          elseif ($kOut -notmatch 'L86-WT') { Fail "闸15m(2)：ship -Base master 非零退出但输出不含哨兵 L86-WT——拦它的不是 worktree 自调用守卫。实际输出：$kOut" }
          elseif ($kBaseAfter -ne $jBaseBefore) { Fail '闸15m(2)：守卫已拦但 base 分支 tip 变了——守卫触发前已产生提交/合并副作用。' }
          else {
            # (3) base==TaskId 守卫的**独立**覆盖：(1)(2) 都走 worktree 自带脚本，故恒由守卫 (1) 先拦——
            #     删掉守卫 (2) 它们照样绿。这里改用**主检出**的 task.ps1（$RepoRoot ≠ worktree，守卫 (1) 不触发）
            #     且显式传 -Base T0-SMOKE，断言由守卫 (2) 拦下（哨兵 L86-BASE，与 (1) 的 L86-WT 区分）。
            $mOut = & pwsh -NoProfile -File (Join-Path $e2e 'scripts/task.ps1') -TaskId T0-SMOKE -Phase ship -Local -SkipRed -Base T0-SMOKE 2>&1 | Out-String
            $mExit = $LASTEXITCODE
            $mBaseAfter = (& git -C $e2e rev-parse master 2>$null); if ($mBaseAfter) { $mBaseAfter = $mBaseAfter.Trim() }
            if ($mExit -eq 0) { Fail '闸15m(3)：主检出 task.ps1 跑 ship -Local -Base T0-SMOKE 仍退出 0——base==TaskId 守卫缺失：范围闸 "$Base...HEAD" 得空 diff，越界改动会被空过。' }
            elseif ($mOut -notmatch 'L86-BASE') { Fail "闸15m(3)：非零退出但输出不含哨兵 L86-BASE——拦它的不是 base==TaskId 守卫（该守卫可能已被删除，而 (1)(2) 仍绿）。实际输出：$mOut" }
            elseif ($mBaseAfter -ne $jBaseBefore) { Fail '闸15m(3)：守卫已拦但 base 分支 tip 变了——守卫触发前已产生提交/合并副作用。' }
            else { Write-Host '  15m L86 双守卫 OK（(1)(2) worktree 自调用→L86-WT；(3) 主检出 -Base=卡id→L86-BASE；三例均非零、base tip 无变化）' -ForegroundColor Green }
          }
        }
      }
    }
  } finally {
    Set-Location $RepoRoot
    & git -C $e2e worktree prune 2>$null
    Remove-Item -Recurse -Force $e2e -ErrorAction SilentlyContinue
  }
}
# 15n. Phase commands fail closed with L86-WT. Check every authority shipped in the current repository shape;
#   TEMPLATE-README.md is a meta-only face and is absent after initialization.
$l86Docs = @(
  '.claude/skills/task-loop/SKILL.md'   # 驱动 R1–R5 的 skill（原教「start 后 cd 进 worktree」再跑相对路径）
  'docs/DEVOPS-WORKFLOW.md'             # 单卡闭环唯一操作手册（§3 命令块）
  'TEMPLATE-README.md'                  # 下游 60 秒上手（步骤 4–6）
  'scripts/task.ps1'                    # 脚本自身 .EXAMPLE 头注
)
$nFail = $false
function Test-L86InitializedRepository([string]$RootPath) {
  if (-not (Test-Path (Join-Path $RootPath 'CLAUDE.template.md'))) { return $true }
  return (Test-Path (Join-Path $RootPath 'CLAUDE.md')) -and
    (Test-Path (Join-Path $RootPath 'CLAUDE.scaffold-merge.md'))
}
function Get-L86DocDisposition([string]$RelativePath, [bool]$Initialized, [bool]$Exists) {
  if ($RelativePath -eq 'TEMPLATE-README.md' -and $Initialized -and -not $Exists) { return 'skip-meta-only' }
  return 'check'
}
function Get-L86DocAudit([string]$RootPath, [bool]$Initialized, [scriptblock]$DispositionResolver) {
  foreach ($rel in $l86Docs) {
    $p = Join-Path $RootPath $rel
    $exists = Test-Path $p
    $disposition = & $DispositionResolver $rel $Initialized $exists
    $status = if ($disposition -eq 'skip-meta-only') { 'skipped' }
      elseif (-not $exists) { 'missing' }
      elseif ((Get-Content $p -Raw) -notmatch 'L86-WT') { 'anchor-missing' }
      else { 'ok' }
    [pscustomobject]@{ RelativePath = $rel; Disposition = $disposition; Status = $status }
  }
}

# Hermetic shape matrix: Cleanup removes the template; Retrofit retains it and emits a merge aid beside CLAUDE.md.
# A configured or comment-decoy ProjectName in a scaffold checkout is deliberately not an initialization signal.
$l86Fixture = Join-Path ([IO.Path]::GetTempPath()) "scaffold-l86-retrofit-$PID"
function Set-L86FixtureFile([string]$RelativePath, [string]$Value = 'L86-WT') {
  $fixturePath = Join-Path $l86Fixture $RelativePath
  New-Item -ItemType Directory -Force (Split-Path $fixturePath -Parent) | Out-Null
  Set-Content -Path $fixturePath -Value $Value -NoNewline
}
try {
  $shapeCases = @(
    @{ Name = 'Cleanup output'; Signals = @('CLAUDE.md'); Config = ''; WantInitialized = $true },
    @{ Name = 'Retrofit output'; Signals = @('CLAUDE.template.md', 'CLAUDE.md', 'CLAUDE.scaffold-merge.md'); Config = ''; WantInitialized = $true },
    @{ Name = 'configured scaffold checkout'; Signals = @('CLAUDE.template.md', 'CLAUDE.md'); Config = "ProjectName = 'Meta Checkout'"; WantInitialized = $false },
    @{ Name = 'comment-decoy scaffold checkout'; Signals = @('CLAUDE.template.md', 'CLAUDE.md'); Config = "# ProjectName = 'Decoy'"; WantInitialized = $false }
  )
  foreach ($case in $shapeCases) {
    Remove-Item -Recurse -Force $l86Fixture -ErrorAction SilentlyContinue
    foreach ($rel in @('.claude/skills/task-loop/SKILL.md', 'docs/DEVOPS-WORKFLOW.md', 'scripts/task.ps1')) { Set-L86FixtureFile $rel }
    foreach ($rel in $case.Signals) { Set-L86FixtureFile $rel }
    if ($case.Config) { Set-L86FixtureFile 'scripts/_config.ps1' $case.Config }
    $fixtureInitialized = Test-L86InitializedRepository $l86Fixture
    $fixtureAudit = @(Get-L86DocAudit $l86Fixture $fixtureInitialized ${function:Get-L86DocDisposition})
    $fixtureFailures = @($fixtureAudit | Where-Object { $_.Status -in @('missing', 'anchor-missing') })
    $fixtureSkips = @($fixtureAudit | Where-Object { $_.Status -eq 'skipped' })
    $wantFailureCount = if ($case.WantInitialized) { 0 } else { 1 }
    $wantSkipCount = if ($case.WantInitialized) { 1 } else { 0 }
    if ($fixtureInitialized -ne $case.WantInitialized -or $fixtureFailures.Count -ne $wantFailureCount -or $fixtureSkips.Count -ne $wantSkipCount) {
      Fail "15n shape fixture '$($case.Name)' misclassified initialization or the missing meta README."; $nFail = $true
    }
    if ($case.WantInitialized) {
      $mutantFailures = @(Get-L86DocAudit $l86Fixture $fixtureInitialized { return 'check' } | Where-Object { $_.Status -in @('missing', 'anchor-missing') })
      if ($mutantFailures.Count -ne 1 -or $mutantFailures[0].RelativePath -ne 'TEMPLATE-README.md') {
        Fail "15n deletion mutation survived in '$($case.Name)': removing the exception did not restore the missing TEMPLATE-README.md failure."; $nFail = $true
      }
    }
  }

  # Every retained authority remains fail-closed for both missing and anchorless variants after Retrofit.
  Remove-Item -Recurse -Force $l86Fixture -ErrorAction SilentlyContinue
  foreach ($rel in @('CLAUDE.template.md', 'CLAUDE.md', 'CLAUDE.scaffold-merge.md', '.claude/skills/task-loop/SKILL.md', 'docs/DEVOPS-WORKFLOW.md', 'scripts/task.ps1')) { Set-L86FixtureFile $rel }
  foreach ($negative in @(
    @{ Rel = '.claude/skills/task-loop/SKILL.md'; Mode = 'missing' }, @{ Rel = '.claude/skills/task-loop/SKILL.md'; Mode = 'anchorless' },
    @{ Rel = 'docs/DEVOPS-WORKFLOW.md'; Mode = 'missing' }, @{ Rel = 'docs/DEVOPS-WORKFLOW.md'; Mode = 'anchorless' },
    @{ Rel = 'scripts/task.ps1'; Mode = 'missing' }, @{ Rel = 'scripts/task.ps1'; Mode = 'anchorless' }
  )) {
    $negativePath = Join-Path $l86Fixture $negative.Rel
    if ($negative.Mode -eq 'missing') { Remove-Item $negativePath -Force } else { Set-Content $negativePath -Value 'no guard' -NoNewline }
    $negativeFailures = @(Get-L86DocAudit $l86Fixture $true ${function:Get-L86DocDisposition} | Where-Object { $_.Status -in @('missing', 'anchor-missing') })
    if ($negativeFailures.Count -ne 1 -or $negativeFailures[0].RelativePath -ne $negative.Rel) {
      Fail "15n retained-authority fixture '$($negative.Rel)/$($negative.Mode)' did not fail closed on that exact document."; $nFail = $true
    }
    Set-L86FixtureFile $negative.Rel
  }

  # An existing meta README is checked normally; only absence after recognized initialization is exempt.
  Set-L86FixtureFile 'TEMPLATE-README.md' 'no guard'
  $metaFailures = @(Get-L86DocAudit $l86Fixture $true ${function:Get-L86DocDisposition} | Where-Object { $_.Status -in @('missing', 'anchor-missing') })
  if ($metaFailures.Count -ne 1 -or $metaFailures[0].RelativePath -ne 'TEMPLATE-README.md') {
    Fail '15n existing-meta fixture did not enforce L86-WT on TEMPLATE-README.md.'; $nFail = $true
  }
} finally {
  Remove-Item -Recurse -Force $l86Fixture -ErrorAction SilentlyContinue
}

$l86Initialized = Test-L86InitializedRepository $RepoRoot
$l86Audit = @(Get-L86DocAudit $RepoRoot $l86Initialized ${function:Get-L86DocDisposition})
$l86Checked = @($l86Audit | Where-Object { $_.Status -ne 'skipped' }).Count
$l86Skipped = @($l86Audit | Where-Object { $_.Status -eq 'skipped' }).Count
foreach ($result in $l86Audit) {
  if ($result.Status -eq 'skipped') {
    Write-Host '  [SELFTEST-POSTINIT-L86-DOC-SKIP] TEMPLATE-README.md is meta-repository only and is absent after initialization.' -ForegroundColor DarkGray
    continue
  }
  if ($result.Status -eq 'missing') { Fail "闸15n：$($result.RelativePath) 不存在（相位命令指引失去真相源？）。"; $nFail = $true; continue }
  if ($result.Status -eq 'anchor-missing') { Fail "闸15n：$($result.RelativePath) 未提示 L86-WT 守卫——它仍可能教「在 worktree 内跑 scripts\task.ps1 相位命令」，而该动作现已被 fail-closed 拒（TD-238 文档漂移）。"; $nFail = $true }
}
# 另断言 skill 的 R1 start 条目不再以「之后 cd 进该 worktree」收尾（那句暗示后续相位命令在 worktree 内跑）。
$tlText = Get-Content (Join-Path $RepoRoot '.claude/skills/task-loop/SKILL.md') -Raw
if ($tlText -match '(?m)^-\s+\*\*R1 start\*\*.*之后\s*`cd`\s*进该 worktree。\s*$') { Fail '闸15n：task-loop skill 的 R1 start 仍以「之后 cd 进该 worktree」收尾，暗示后续相位命令在 worktree 内跑——会撞 L86-WT 守卫。'; $nFail = $true }
if (-not $nFail) { Write-Host "  [SELFTEST-L86-DOC-SUMMARY] checked=$l86Checked skipped=$l86Skipped; every checked authority carries L86-WT and the skill no longer teaches task.ps1 from a worktree." -ForegroundColor Green }

# 15p. cleanup 删除点凭据闸（T24-CLEANUP-TOKEN）：`branch -D` 是 cleanup 内唯一无脏树守卫的破坏性删除点——
#   ship 两处合并成功路径（-Local merge / gh pr merge --squash）之后必须各铸一枚 T24-MERGETOKEN 单次合并凭据，
#   cleanup 在 branch -D 之前必须先过凭据检查（凭据 / -Force / gh 在线补验 MERGED，皆无则保留分支 fail-safe）。
#   源码级词法断言（同 17p2 手法：断言位于对应块内、不能被文件任意位置的哨兵满足）；实现前三条断言均 RED（防 vacuous）。
$p15Fail = $false
$tp15p = Get-Content (Join-Path $RepoRoot 'scripts/task.ps1') -Raw
# Locate the actual merge statement and token pipeline in the SAME statement block. Comments, code in
# another branch, and a token written before a successful merge/state guard cannot satisfy this oracle.
function Test-15pTokenFlow([string]$Source, [string]$Kind) {
  $parseErrors = $null; $ast = [System.Management.Automation.Language.Parser]::ParseInput($Source, [ref]$null, [ref]$parseErrors)
  if ($parseErrors.Count) { return $false }
  $mergeName = if ($Kind -ceq 'local') { 'git' } else { 'Invoke-GhBeforeDeadline' }
  $mergePattern = if ($Kind -ceq 'local') { '^& git -C \$RepoRoot merge --no-ff --no-edit \$r3Head$' } else { '^Invoke-GhBeforeDeadline -Arguments @\(''pr'',''merge'',"\$pr",''--squash'',''--match-head-commit'',\$ciHead\)' }
  $merges = @($ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -ceq $mergeName -and $n.Extent.Text -cmatch $mergePattern }, $true))
  if ($merges.Count -ne 1) { return $false }
  $mergeStatement = $merges[0]
  while ($mergeStatement.Parent -and $mergeStatement.Parent -isnot [System.Management.Automation.Language.StatementBlockAst]) { $mergeStatement = $mergeStatement.Parent }
  if ($mergeStatement.Parent -isnot [System.Management.Automation.Language.StatementBlockAst]) { return $false }
  $statements = @($mergeStatement.Parent.Statements)
  $mergeIndex = [array]::IndexOf($statements, $mergeStatement)
  $writeIndex = -1; $exitIndex = -1; $stateIndex = -1; $mergedIndex = -1; $tipIndex = -1
  $exitCondition = if ($Kind -ceq 'local') { '$LASTEXITCODE -ne 0' } else { '$mergeRun.ExitCode -ne 0' }
  for ($i = $mergeIndex + 1; $i -lt $statements.Count; $i++) {
    $statement = $statements[$i]
    if ($statement -is [System.Management.Automation.Language.IfStatementAst] -and $statement.Clauses.Count -eq 1) {
      $condition = $statement.Clauses[0].Item1.Extent.Text
      $body = @($statement.Clauses[0].Item2.Statements)
      if ($body.Count -eq 1 -and $body[0] -is [System.Management.Automation.Language.ThrowStatementAst]) {
        if ($condition -ceq $exitCondition) { $exitIndex = $i }
        if ($condition -ceq '($mintState -ine ''MERGED'') -or (-not $mintTip)') { $stateIndex = $i }
      }
    }
    if ($statement -is [System.Management.Automation.Language.AssignmentStatementAst]) {
      if ($statement.Left.Extent.Text -ceq '$sagaLocalMerged' -and $statement.Right.Extent.Text -ceq '$true') { $mergedIndex = $i }
      if ($statement.Left.Extent.Text -ceq '$mintTip' -and @($statement.Right.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -ceq 'git' -and $n.Extent.Text -cmatch '^& git -C \$RepoRoot rev-parse HEAD\^2(?:\s|$)' }, $true)).Count -eq 1) { $tipIndex = $i }
    }
    if ($statement -is [System.Management.Automation.Language.PipelineAst] -and $statement.PipelineElements.Count -eq 2) {
      $payload = $statement.PipelineElements[0]; $writer = $statement.PipelineElements[1]
      if ($payload -is [System.Management.Automation.Language.CommandExpressionAst] -and $payload.Expression -is [System.Management.Automation.Language.ExpandableStringExpressionAst] -and $payload.Expression.Extent.Text -cmatch '^"tip=\$mintTip`n' -and $writer -is [System.Management.Automation.Language.CommandAst] -and $writer.GetCommandName() -ceq 'Set-Content' -and $writer.Extent.Text -cmatch '^Set-Content \(Join-Path \$tokDir \$TaskId\)(?:\s|$)') { $writeIndex = $i; break }
    }
  }
  if ($writeIndex -lt 0 -or $exitIndex -le $mergeIndex -or $exitIndex -ge $writeIndex) { return $false }
  if ($Kind -ceq 'local') { return $mergedIndex -gt $exitIndex -and $tipIndex -gt $mergedIndex -and $tipIndex -lt $writeIndex }
  return $stateIndex -gt $exitIndex -and $stateIndex -lt $writeIndex
}
if (-not (Test-15pTokenFlow $tp15p 'local')) { Fail '15p: local token must follow successful reviewed-SHA merge and carry HEAD^2 tip in its actual write pipeline.'; $p15Fail = $true }
if (-not (Test-15pTokenFlow $tp15p 'remote')) { Fail '15p: remote token must follow successful deadline merge and an actual MERGED/nonempty-tip refusal guard in the same block.'; $p15Fail = $true }
# These source variants remain syntactically valid: a parse failure or an unchanged seed is a setup error,
# never evidence that the token invariant rejected it. Exercise the exact same oracle as the live source.
$stateLine15p = [regex]::Match($tp15p, '(?m)^[ \t]*if \(\(\$mintState -ine ''MERGED''\).*$').Value
$writeLine15p = [regex]::Match($tp15p, '(?m)^[ \t]*"tip=\$mintTip`nmerged_pr=.*$').Value
if (-not $stateLine15p -or -not $writeLine15p) { Fail '15p mutation setup: remote state/write statements missing.'; $p15Fail = $true }
else {
  $variants15p = @(
    @{ Name='local-tip'; Kind='local'; Text=$tp15p.Replace('rev-parse HEAD^2', 'rev-parse HEAD') },
    @{ Name='local-merge-comment'; Kind='local'; Text=$tp15p.Replace('& git -C $RepoRoot merge --no-ff --no-edit $r3Head', '# & git -C $RepoRoot merge --no-ff --no-edit $r3Head') },
    @{ Name='remote-payload'; Kind='remote'; Text=$tp15p.Replace('tip=$mintTip`nmerged_pr', 'tip=missing`nmerged_pr') },
    @{ Name='remote-write-comment'; Kind='remote'; Text=$tp15p.Replace($writeLine15p, ('# ' + $writeLine15p)) },
    @{ Name='remote-guard-comment'; Kind='remote'; Text=$tp15p.Replace($stateLine15p, ('# ' + $stateLine15p)) },
    @{ Name='remote-wrong-state'; Kind='remote'; Text=$tp15p.Replace('$mintState -ine', '$otherState -ine') },
    @{ Name='remote-state-after-write'; Kind='remote'; Text=$tp15p.Replace($stateLine15p, '').Replace($writeLine15p, ($writeLine15p + "`n" + $stateLine15p)) }
  )
  foreach ($variant15p in $variants15p) {
    $errors15p = $null; [void][System.Management.Automation.Language.Parser]::ParseInput($variant15p.Text, [ref]$null, [ref]$errors15p)
    if ($variant15p.Text -ceq $tp15p -or $errors15p.Count) { Fail "15p mutation setup failed: $($variant15p.Name)."; $p15Fail = $true }
    elseif (Test-15pTokenFlow $variant15p.Text $variant15p.Kind) { Fail "15p token oracle accepted seeded defect $($variant15p.Name)."; $p15Fail = $true }
  }
}

$cl15p = [regex]::Match($tp15p, "(?s)'cleanup'\s*\{.*").Value
if (-not $cl15p) { Fail '闸15p：task.ps1 找不到 cleanup 相位块（结构漂移？）。'; $p15Fail = $true }
else {
  # 代码级断言（fresh-context 审计 F2：哨兵注释也含 branch -D 字样，纯哨兵排序可被「删守卫留注释」蒙混）——
  # 剥掉整行注释后要求：token 检查与 -Force 分支都在场，且首个 branch -D 不得先于 token 检查出现。
  $clCode15p = (($cl15p -split "`r?`n") | Where-Object { $_ -notmatch '^\s*#' }) -join "`n"
  $bd15p = $clCode15p.IndexOf('branch -D')
  $fr15p = $clCode15p.IndexOf('elseif ($Force)')
  $tk15p = $clCode15p.IndexOf('Test-Path $tokPath')
  # 代码级形状要求（R3 r3）：-Force 判定先于凭据判定（#9，防「残留/不匹配凭据遮蔽显式覆盖」）；凭据/在线路径用 CAS
  # 删除（update-ref -d，#17 原子比对+删）；tip 比对与消费注销在场；-Force 判定之前不得出现裸 branch -D。
  if (($cl15p -notmatch 'T24-MERGETOKEN') -or ($tk15p -lt 0) -or ($fr15p -lt 0) -or ($fr15p -gt $tk15p) -or ($clCode15p.IndexOf('update-ref -d') -lt 0) -or ($clCode15p.IndexOf('Remove-Item $tokPath') -lt 0) -or ($clCode15p.IndexOf('-ieq $branchTip') -lt 0) -or ($clCode15p.IndexOf('Get-Command gh -ErrorAction SilentlyContinue') -lt 0) -or (($bd15p -ge 0) -and ($bd15p -lt $fr15p))) { Fail '闸15p：cleanup 删除点守卫形状不符（代码级）——要求：-Force 判定先于凭据判定（防遮蔽，R3 r3 #9）、凭据/在线路径 CAS 删除（update-ref -d，R3 r3 #17）、tip 比对与消费注销在场、gh 在位判定（Get-Command …SilentlyContinue，缺席不得崩相位，R3 r6 #6）、-Force 判定之前无裸 branch -D。'; $p15Fail = $true }
}
if (-not $p15Fail) { Write-Host '  15p cleanup 删除点凭据闸 OK（两处合并成功路径各铸 T24-MERGETOKEN、branch -D 前有凭据守卫）' -ForegroundColor Green }

# 15r. ship saga report gate (T26-SHIPSAGA): ship is a multi-leg saga (card-check -> DoD -> verify ->
#   commit -> scope-gate -> budget-gate -> license-gate -> leak-gate -> push+PR -> R3-review -> CI-gate -> merge; the
#   -Local variant has optional R3-review + local-merge). Any leg's throw must self-report progress at
#   the moment of failure — [SAGA-DONE] / [SAGA-FAIL] (= first pending leg) / [SAGA-TODO] + the exact
#   [SAGA-RESUME] rerun command (post-T69: every merge gate is deterministic and idempotent, so the
#   recovery is always "fix, rerun the same ship"; recovery doctrine anchor: TD85-RESUME,
#   docs/DEVOPS-WORKFLOW.md) — then rethrow the ORIGINAL exception untouched
#   (exit code / failure surface / upstream catch behavior unchanged; only the report layer is added).
#   Source-level lexical assertions (same technique as 15p/17p2; whole-line comments stripped so a
#   deleted-code-but-kept-comment cannot fool them): (a) the ship phase tracks leg completion (ordered
#   leg-name roster + >=13 success-path append points: shared 7 + -Local 2 + remote 4 incl. the TD134
#   CI-gate leg); (b) a catch report block carrying the T26-SHIPSAGA sentinel exists; (c) that block
#   lexically ends in a bare rethrow; (d) recovery-routing lexical lock — full rerun command exactly
#   once, rebuilt with every bound option (R3 r1/r2/r3 #9/#6/#2). All assertions were RED before the
#   implementation (anti-vacuous). (a)-(d) are static, locale-independent, no git/gh needed (same
#   technique as 15n); (e) hermetic failure-path fixtures in the separate block below (r3 #6, needs
#   git, same technique as 15i).
$r15Fail = $false
$tp15r = Get-Content (Join-Path $RepoRoot 'scripts/task.ps1') -Raw
$ship15r = [regex]::Match($tp15r, "(?s)'ship'\s*\{.*?\r?\n  'cleanup'").Value
if (-not $ship15r) { Fail '闸15r：task.ps1 找不到 ship 相位块（结构漂移？）。'; $r15Fail = $true }
else {
  $shipCode15r = (($ship15r -split "`r?`n") | Where-Object { $_ -notmatch '^\s*#' }) -join "`n"
  # (a) 腿完成跟踪：有序腿名列表初始化 + 成功路径追加点（漏标的腿会让报告把已完成腿误报成失败腿）
  if ($shipCode15r -notmatch '\$sagaLegs\s*=') { Fail '闸15r(a)：ship 相体无有序腿名列表（$sagaLegs，代码级）——失败时刻无法自述「哪些腿已完成」。'; $r15Fail = $true }
  $appendCount15r = ([regex]::Matches($shipCode15r, '\$sagaDone\s*\+=')).Count
  if ($appendCount15r -lt 13) { Fail "闸15r(a)：ship 成功路径上的腿完成追加点仅 $appendCount15r 处（要求 ≥13：共享 7 + -Local 2 + 远端 4，远端含 TD134 的 CI-gate 腿）——漏标腿会把已完成腿误报成失败腿。"; $r15Fail = $true }
  if ($shipCode15r -notmatch '\$sagaLocalMerged\s*=\s*\$true') { Fail '闸15r(a)：ship 相体无本地合并成功追踪（$sagaLocalMerged 须在 merge 成功后置真）——post-merge 凭据失败会被误报成合并前守卫态（R3 r5 #9）。'; $r15Fail = $true }
  # (b)+(c) catch 报告块：含哨兵且以原样裸 throw 结尾（throw 后除闭合括号外无其他语句——异常语义不变的词法锁）；
  # tempered 前缀禁止「起点与哨兵之间还有另一个 catch」——防匹配到 ship 内其他 catch（RED 证据解析 / mint 状态解析）。
  $catch15r = [regex]::Match($shipCode15r, '(?s)\}\s*catch\s*\{(?:(?!\}\s*catch\s*\{).)*?T26-SHIPSAGA.*?\n\s*throw\s*\r?\n\s*\}').Value
  if (-not $catch15r) { Fail '闸15r(b/c)：ship 相体无「含哨兵 T26-SHIPSAGA 且以原样裸 throw 结尾」的 catch 报告块（代码级，注释不算）——任一腿失败时不自述进度，或异常被吞/改写（退出码语义漂移）。'; $r15Fail = $true }
  # (c) 尾锚强化（preflight nit）：单靠「throw 后跟某个 }」可被「嵌套块内 throw + 其后吞异常语句」满足——再钉死
  # ship 相体词法尾形状：裸 throw → catch 闭合 → 相位闭合 → 'cleanup' 标签，令 throw 后不存在任何代码路径。
  if ($shipCode15r -notmatch "(?s)\n\s*throw\s*\r?\n\s*\}\s*\}\s*'cleanup'") { Fail "闸15r(c)：ship 相体末尾不是「裸 throw → catch 闭合 → 相位闭合」的词法形状——saga catch 的 throw 须是 ship 相体最后一个语句（throw 之后不得再有可吞异常/改语义的代码）。"; $r15Fail = $true }
  if ($catch15r) {
    # (d) Recovery-routing lexical lock (post-T69 shape): every merge gate is deterministic and idempotent,
    # so the catch block must (i) emit the full re-run command exactly once, rebuilt with every
    # behavior-affecting bound option ($SkipRed compat echo / $NoAutoMerge / ContainsKey('Base')), and
    # (ii) route the -Local merge-leg failure by on-disk state ($sagaLocalMerged / MERGE_HEAD), offering
    # merge --continue as last resort and merge --no-ff --no-edit for the guard-blocked state.
    $rerunHits15r = [regex]::Matches($catch15r, [regex]::Escape('-TaskId $TaskId -Phase ship"'))
    $optsOk15r = ($catch15r.IndexOf('$SkipRed') -ge 0) -and ($catch15r.IndexOf('$NoAutoMerge') -ge 0) -and ($catch15r.IndexOf("ContainsKey('Base')") -ge 0)
    $localOk15r = ($catch15r.IndexOf('merge --continue') -ge 0) -and ($catch15r.IndexOf('--no-ff --no-edit') -ge 0) -and ($catch15r.IndexOf('$sagaLocalMerged') -ge 0) -and ($catch15r.IndexOf('MERGE_HEAD') -ge 0)
    if (($rerunHits15r.Count -ne 1) -or (-not $optsOk15r) -or (-not $localOk15r)) { Fail '闸15r(d)：恢复路由词法形状不符（post-T69）——要求：完整重跑命令在 catch 内恰 1 次且由 $SkipRed/$NoAutoMerge/ContainsKey(Base) 补齐已绑定选项；-Local 合并腿失败态按阶段状态（$sagaLocalMerged/MERGE_HEAD）分流出 merge --continue 最后手段或 merge --no-ff --no-edit 重发。'; $r15Fail = $true }
  }
}
if (-not $r15Fail) { Write-Host '  15r ship saga 报告闸 OK（腿完成追加点 ≥13 在场（含 TD134 CI-gate 腿）、catch 含哨兵且以原样裸 throw 结尾、重跑命令恰 1 次且带齐已绑定选项、-Local 合并腿按阶段状态分流）' -ForegroundColor Green }

# 15r(e). hermetic failure-path fixtures (lexical locks only prove shape; this block actually runs the failure
#   paths in an isolated repo and asserts report output + exception semantics — offline, no gh/codex, -Local):
#   B = post-commit rerunnable family (red->green marker card: ship makes a real commit (marker outside card
#     allow_paths) -> scope gate blocks): completed legs include commit, failure point = scope gate, and the
#     saga must suggest re-running the same ship command (post-T69 every gate is deterministic+idempotent,
#     rerun is always a safe resume);
#   D = no-op commit rerun (same card, -SkipRed compat flag echoed): scope gate blocks again, recovery must
#     echo the full rerun command including -SkipRed, and must NOT print a do-not-rerun warning;
#   C = local merge conflict (master and branch both edit README): failure point = local merge, pending = none,
#     merge --continue offered as last resort; then behaviorally: abort -> bare rerun re-conflicts
#     deterministically; resolve in the worktree (merge base, commit) -> rerun goes green through merge;
#   E = non-conflict merge failure (stub flips the fixture checkout off master -> pre-merge guard blocks,
#     no MERGE_HEAD on disk): must offer re-issuing merge --no-ff --no-edit, not merge --continue;
#   F = post-merge token-mint failure (.git/scaffold-merged pre-seeded as a file): merge really succeeded,
#     report must say so instead of misreporting a guard state.
#   B/D/C/E/F run the R3 leg via pass-stub (offline). Assertions never gate on non-empty $out first — empty
#   output is itself a FAIL (anti-vacuous).
$gitR15 = Get-Command git -ErrorAction SilentlyContinue
if (-not $gitR15) {
  Write-Host '  15r(e) git 未安装，跳过（离线 / 无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  $PSNativeCommandUseErrorActionPreference = $false
  $sg = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-saga-$PID"
  if (Test-Path $sg) { Remove-Item -Recurse -Force $sg }
  New-Item -ItemType Directory -Force $sg | Out-Null
  try {
    Copy-Item (Join-Path $RepoRoot 'scripts') $sg -Recurse -Force   # 忠实拷 scripts/（同 15i/17k）；夹具内改 _config/verify，绝不碰元仓
    $cfgSG = Join-Path $sg 'scripts/_config.ps1'
    $cSG = Get-Content $cfgSG -Raw
    $cSG = [regex]::Replace($cSG, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$sg/wt'" })   # worktree 指向 fixture，绝不碰真实 wt 根
    # 场景 C 会走到 -Local 的 R3 腿：注入 pass-stub 评审后端（确定性+离线，绝不调真 codex——它可能在 PATH 上、联网、
    # 非确定；同 15d2/15b 之理）。A/B 在 R3 之前失败，stub 对其无影响。
    $revStubSG = Join-Path $sg 'review-stub.ps1'
    $revStubBodySG = @'
[Console]::In.ReadToEnd() | Out-Null
if (Test-Path (Join-Path $PSScriptRoot 'switch-flag')) { & git -C $PSScriptRoot switch -q -c sidetrack 2>$null }
'{"verdict":"pass","reasons":[]}' | Set-Content $env:REVIEW_OUT -Encoding utf8
'@
    Set-Content $revStubSG $revStubBodySG -Encoding utf8
    $cSG = $cSG.Replace("ReviewCommand = ''", "ReviewCommand = 'pwsh -NoProfile -File $($revStubSG -replace '\\', '/')'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    # T104：本块断言的是「R3 腿**真的跑过**之后」的 saga 报告，而各腿唯一的改动是 README.md——那是一份 100%
    # markdown、不碰任何闸的 diff，正好**挣到**内容路由的免评审（ReviewSkipWhen），R3 腿于是整条不执行：
    # 本该停在评审腿的场景一路合并、铸出 .git/scaffold-merged（目录），把腿 F「预置该路径为文件」的前提砸掉。
    # 故夹具显式关掉路由——这里测的是评审跑起来之后的报告，路由本身另有 17z(T104) 的正臂与两条负控。
    # ReviewSkipWhen is currently the single-line @{ } form, while older/downstream configs may use a
    # multi-line hashtable. The former must not fall through the multi-line matcher and consume the next map.
    $cSG = [regex]::Replace($cSG, '(?ms)^\s*ReviewSkipWhen\s*=\s*@\{(?:(?:[ \t]*\r?\n)*[ \t]*\}|.*?^\s*\})', '  ReviewSkipWhen = @{}')
    $sgConfigParse = $null
    [void][System.Management.Automation.Language.Parser]::ParseInput($cSG, [ref]$null, [ref]$sgConfigParse)
    if (($cSG -notmatch [regex]::Escape("$sg/wt")) -or ($cSG -notmatch 'review-stub') -or ($cSG -notmatch 'ReviewSkipWhen = @\{\}') -or @($sgConfigParse).Count -gt 0) { Fail '闸15r(e)：fixture _config 注入失败或语法损坏（WorktreeRoot/ReviewCommand/ReviewSkipWhen 行格式变了？）——夹具可能触碰真实 wt 根、撞真 codex，或让内容路由跳过本块要测的 R3 腿，中止本块。' }
    else {
      Set-Content $cfgSG $cSG -NoNewline -Encoding utf8
      Set-Content (Join-Path $sg 'scripts/verify.ps1') 'exit 0' -Encoding utf8   # 确定性 stub（同 15i 之理）
      # 场景 C 的 R3 腿要真跑 review.ps1（pass-stub 后端）：rubric 缺失会被其 fail-closed block（无判定标准），
      # 故夹具基线须带真 rubric（review 从 base ref 读取）。
      New-Item -ItemType Directory -Force (Join-Path $sg 'docs') | Out-Null
      Copy-Item (Join-Path $RepoRoot 'docs/QUALITY-RUBRIC.md') (Join-Path $sg 'docs/QUALITY-RUBRIC.md') -Force
      & git -C $sg init -q
      & git -C $sg symbolic-ref HEAD refs/heads/master
      & git -C $sg config user.email 'selftest@local'
      & git -C $sg config user.name 'selftest'
      New-Item -ItemType Directory -Force (Join-Path $sg 'specs/tasks') | Out-Null
      @('---', 'id: T0-SAGA15R', 'title: seed 15r saga failure-path report', 'status: todo',
        'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - README.md', '---') -join "`n" |
        Set-Content (Join-Path $sg 'specs/tasks/T0-SAGA15R.md') -Encoding utf8
      Set-Content (Join-Path $sg 'README.md') 'saga fixture' -Encoding utf8
      Set-Content (Join-Path $sg '.gitignore') ".review/`n" -Encoding utf8   # 镜像真仓 .gitignore（.review/ 不入库）——否则 red 落的 .review 证据被 git add -A 提交、卡外触范围闸（C 非 -SkipRed 走 red 后必踩，与真仓行为一致）
      & git -C $sg add -A 2>$null
      & git -C $sg commit -q -m 'sg base' *> $null
      $sgStartOut = (& pwsh -NoProfile -File (Join-Path $sg 'scripts/task.ps1') -TaskId T0-SAGA15R -Phase start 2>&1 | Out-String)
      $sgStartExit = $LASTEXITCODE
      $sgWt = Join-Path $sg 'wt/T0-SAGA15R'
      if (-not (Test-Path $sgWt)) { Fail "闸15r(e)：fixture start 未产出 worktree（exit=$sgStartExit）——无法验证失败路径报告（前置失败）。输出：$sgStartOut" }
      else {
        # UTF-8 钉法（TD31/TD34）：子端 enc-wrap 钉 OutputEncoding、父端捕获前后就地钉+还原，防中文 token 误码假 FAIL。
        # 注意用具名参数透传而非数组 splat——PS 对脚本的数组 splat 按**位置**绑定，'-TaskId' 会被当值塞进 TaskId 撞 TD50 校验。
        $encWrapR = Join-Path $sg 'enc-ship-15r.ps1'
        Set-Content $encWrapR 'param([string]$Tid, [switch]$SkipRed) try { [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }; & (Join-Path $PSScriptRoot "scripts/task.ps1") -TaskId $Tid -Phase ship -Local -SkipRed:$SkipRed; exit $LASTEXITCODE' -Encoding utf8
        $prevOutR = $null
        try { $prevOutR = [Console]::OutputEncoding; [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }
        try {
          # B: post-commit family — red->green marker card (dod=Test-Path, L95 no bare $var): red phase, then
          # marker turns green but lives OUTSIDE card allow_paths -> ship makes a real commit, scope gate blocks
          $sgWtB = New-ShipFixtureCard $sg 'T0-SAGA15RB' 'seed 15r post-commit deadlock' 'dod_command: pwsh -NoProfile -Command "if (-not (Test-Path marker-15r.txt)) { exit 1 }"'
          $bExit = -1; $bOut = ''; $dExit = -1; $dOut = ''
          if (-not (Test-Path $sgWtB)) { Fail '闸15r(e)B：fixture start 未产出 worktree B（前置失败）。' }
          else {
            & pwsh -NoProfile -File (Join-Path $sg 'scripts/task.ps1') -TaskId T0-SAGA15RB -Phase red *> $null
            Set-Content (Join-Path $sgWtB 'marker-15r.txt') 'green' -Encoding utf8
            $bOut = (& pwsh -NoProfile -File $encWrapR -Tid T0-SAGA15RB 2>&1 | Out-String)
            $bExit = $LASTEXITCODE
            # D：no-op 提交重跑（r5 #9）——B 已把 marker 提交；-SkipRed 重跑时 commit 腿 no-op、HEAD 未动
            $dOut = (& pwsh -NoProfile -File $encWrapR -Tid T0-SAGA15RB -SkipRed 2>&1 | Out-String)
            $dExit = $LASTEXITCODE
          }
          # C: separate card+worktree; branch and master each edit README -> deterministic local-merge conflict.
          #    Three-step main-path behavior fixture: (1) abort then bare rerun -> re-conflicts;
          #    (2) merge base inside the worktree, resolve, commit -> rerun goes green through merge.
          #    dod uses no bare $var and a pure-ASCII sentinel GREENC (L95).
          $sgWtC = New-ShipFixtureCard $sg 'T0-SAGA15RC' 'seed 15r local-merge conflict' 'dod_command: pwsh -NoProfile -Command "if (-not (Select-String -Path README.md -Pattern GREENC -Quiet)) { exit 1 }"'
          # The folded copy is pre-initialised beside its raw twin (T261/TD260): the branch below is
          # skipped when the fixture worktree failed to build, Fail() sets a flag and RETURNS rather than
          # exiting, and this file runs under Set-StrictMode -Version Latest - so a copy assigned only
          # inside the branch and read after it masks the fixture diagnostic with an undefined-variable
          # exception attributed to no arm.
          $cExit = -1; $cOut = ''; $cFlat = ''; $c2Exit = -1; $c2Out = ''; $c3Exit = -1; $c3Out = ''
          if (-not (Test-Path $sgWtC)) { Fail '闸15r(e)C：fixture start 未产出 worktree C（前置失败）。' }
          else {
            # master 侧改 README（与分支侧冲突）；worktree 仍是 base 'saga fixture'（start 自 master base commit）
            Set-Content (Join-Path $sg 'README.md') 'master side change' -Encoding utf8
            & git -C $sg add README.md 2>$null
            & git -C $sg commit -q -m 'sg master readme' *> $null
            # red phase (optional TDD aid), then make dod green in a way that conflicts with master
            & pwsh -NoProfile -File (Join-Path $sg 'scripts/task.ps1') -TaskId T0-SAGA15RC -Phase red *> $null
            Set-Content (Join-Path $sgWtC 'README.md') 'GREENC branch side' -Encoding utf8
            # first ship: real commit -> local merge conflict (failure point = local merge)
            $cOut = (& pwsh -NoProfile -File $encWrapR -Tid T0-SAGA15RC 2>&1 | Out-String)
            $cExit = $LASTEXITCODE
            # EXACTLY ONE assertion below reads this folded copy (T259/TD258): the [SHIP-LOCAL-MERGE-FAIL] arm, because that text is THROWN - the child rendered it at its own console width and a wrap can split any phrase. Every other arm in C and E greps Write-Host output (task.ps1 :921/:923/:925), which is not error-view formatted and has never wrapped on either runner; T259 folded those too on a false classification and T261/TD260 put them back on the raw capture. Placed after $LASTEXITCODE is banked, never between the native call and its exit code.
            $cFlat = Get-ScaffoldUnwrappedErrorText -Text $cOut
            & git -C $sg merge --abort 2>$null
            # (1) bare rerun after abort: byte-identical replay -> must re-conflict (main-path step one)
            $c2Out = (& pwsh -NoProfile -File $encWrapR -Tid T0-SAGA15RC 2>&1 | Out-String)
            $c2Exit = $LASTEXITCODE
            & git -C $sg merge --abort 2>$null
            # (2) merge base (master) inside the worktree, resolve and commit -> rerun goes green through merge
            & git -C $sgWtC merge master -m 'merge base into branch (resolve)' *> $null
            Set-Content (Join-Path $sgWtC 'README.md') 'GREENC resolved both sides' -Encoding utf8
            & git -C $sgWtC add README.md 2>$null
            & git -C $sgWtC commit -q --no-edit *> $null
            $c3Out = (& pwsh -NoProfile -File $encWrapR -Tid T0-SAGA15RC 2>&1 | Out-String)
            $c3Exit = $LASTEXITCODE
            & git -C $sg merge --abort 2>$null   # 复位主检出（防残留影响 E/F；③已成时无进行中合并、无害）
            # C3 成功 -Local 合并铸了 T24 凭据目录 .git/scaffold-merged/<id>——清掉，否则 F 的「同名文件占位」(Set-Content .git/scaffold-merged) 因目录已存在而失败
            Remove-Item (Join-Path $sg '.git/scaffold-merged') -Recurse -Force -ErrorAction SilentlyContinue
          }
          # E：非冲突合并失败（r5 #9）——stub 见 flag 即把 fixture 检出切到 sidetrack，合并前守卫（F3）必拦
          $sgWtE = New-ShipFixtureCard $sg 'T0-SAGA15RE' 'seed 15r merge guard block' 'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"'
          $eExit = -1; $eOut = ''
          if (-not (Test-Path $sgWtE)) { Fail '闸15r(e)E：fixture start 未产出 worktree E（前置失败）。' }
          else {
            Set-Content (Join-Path $sgWtE 'README.md') 'branch E change' -Encoding utf8
            Set-Content (Join-Path $sg 'switch-flag') '1' -Encoding utf8
            $eOut = (& pwsh -NoProfile -File $encWrapR -Tid T0-SAGA15RE -SkipRed 2>&1 | Out-String)
            $eExit = $LASTEXITCODE
            Remove-Item (Join-Path $sg 'switch-flag') -ErrorAction SilentlyContinue
            & git -C $sg switch -q master 2>$null
            & git -C $sg branch -q -D sidetrack 2>$null
          }
          # F：post-merge 凭据铸造失败（r5 #9）——.git/scaffold-merged 预置为文件，mint 的 New-Item 目录必败；
          # 合并已真成功 → 报告须走 post-merge 态而非守卫态
          $sgWtF = New-ShipFixtureCard $sg 'T0-SAGA15RF' 'seed 15r post-merge mint fail' 'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"'
          $fExit = -1; $fOut = ''
          if (-not (Test-Path $sgWtF)) { Fail '闸15r(e)F：fixture start 未产出 worktree F（前置失败）。' }
          else {
            Set-Content (Join-Path $sgWtF 'README.md') 'branch F change' -Encoding utf8
            Set-Content (Join-Path $sg '.git/scaffold-merged') 'occupied' -Encoding utf8
            $fOut = (& pwsh -NoProfile -File $encWrapR -Tid T0-SAGA15RF -SkipRed 2>&1 | Out-String)
            $fExit = $LASTEXITCODE
          }
        } finally {
          if ($prevOutR) { try { [Console]::OutputEncoding = $prevOutR } catch { } }
        }
        $reFail = $false
        # r5 #6：断言一律无 $out -and 前置豁免——空输出本身即 FAIL（防「静默非零退出+空输出」vacuous pass）。
        if (-not $bOut) { Fail '闸15r(e)B：ship 输出为空——未产出任何 saga 报告。'; $reFail = $true }
        if ($bExit -eq 0) { Fail '闸15r(e)B：越界改动下 ship -Local 仍退出 0——范围闸失效或 saga catch 吞异常。'; $reFail = $true }
        if ($bOut -notmatch '\[SAGA-DONE\].*commit') { Fail 'Gate 15r(e)B: commit landed but is absent from the [SAGA-DONE] leg list - post-commit self-report broken.'; $reFail = $true }
        if ($bOut -notmatch '\[SAGA-FAIL\] scope-gate') { Fail 'Gate 15r(e)B: the scope-gate failure is not named as the [SAGA-FAIL] point.'; $reFail = $true }
        # Post-T69: rerunning the same ship command is always a safe resume (all merge gates deterministic
        # and idempotent), so after a real commit the saga must still suggest the full rerun command.
        if ($bOut -notmatch '\[SAGA-RESUME\] pwsh -File scripts\\task\.ps1 -TaskId T0-SAGA15RB -Phase ship -Local') { Fail 'Gate 15r(e)B: after a real commit the saga does not suggest rerunning the same ship - post-T69 every gate is deterministic and idempotent, rerun is always a safe resume; the [SAGA-RESUME] line must give the full rerun command.'; $reFail = $true }
        # T233 inserted budget-gate between scope-gate and license-gate, so the expected remainder moved
        # with it. The literal stays EXACT rather than becoming a loose match: this arm exists to catch
        # leg-list drift, and a pattern that tolerated an extra leg would stop being able to see it.
        if ($bOut -notmatch [regex]::Escape('[SAGA-TODO] budget-gate -> license-gate -> leak-gate -> R3-review -> local-merge')) { Fail 'Gate 15r(e)B: on a leg failure [SAGA-TODO] must be the exact ordered list of legs after the failed one - list mismatch (R3 r4 #6).'; $reFail = $true }
        if ($bOut -notmatch 'SHIP-SCOPE-BLOCK') { Fail 'Gate 15r(e)B: the original scope-gate exception text is not present verbatim - the throw was rewritten or swallowed.'; $reFail = $true }
        if (-not $dOut) { Fail '闸15r(e)D：ship 输出为空——未产出任何 saga 报告。'; $reFail = $true }
        if ($dExit -eq 0) { Fail '闸15r(e)D：no-op 提交重跑（范围闸仍越界）竟退出 0。'; $reFail = $true }
        if ($dOut -notmatch '\[SAGA-RESUME\] pwsh -File scripts\\task\.ps1 -TaskId T0-SAGA15RB -Phase ship -Local -SkipRed') { Fail 'Gate 15r(e)D: the rerun suggestion does not carry the caller''s bound options verbatim (-SkipRed compat echo) - the rebuilt command must match what the caller ran.'; $reFail = $true }
        if ($dOut -match '勿重跑 -Phase ship') { Fail '闸15r(e)D：出现「勿重跑」死锁警告——post-T69 无 RED 闸即无死锁态，重跑恒安全（回归）。'; $reFail = $true }
        if (-not $cOut) { Fail '闸15r(e)C：ship 输出为空——未产出任何 saga 报告。'; $reFail = $true }
        if ($cExit -eq 0) { Fail '闸15r(e)C：本地合并冲突下 ship -Local 仍退出 0——异常被吞（rethrow/退出码语义被改）。'; $reFail = $true }
        if ($cOut -notmatch [regex]::Escape('[SAGA-FAIL] local-merge (= first pending leg)')) { Fail 'Gate 15r(e)C: the merge-leg failure is not named as the [SAGA-FAIL] point.'; $reFail = $true }
        if ($cOut -notmatch [regex]::Escape('[SAGA-TODO] (none)')) { Fail 'Gate 15r(e)C: on a last-leg failure [SAGA-TODO] must be (none) - leg-list computation drifted.'; $reFail = $true }
        # T36-DOCTRINE 三步主路重锁：-Local 冲突恢复须以三步主路（abort→worktree merge base→重跑同一条 ship）为**主**，
        # merge --continue 降为**最后手段**（树不过范围闸与 R3）——文案须与 docs/DEVOPS-WORKFLOW.md S6 段一致（先复现 RED）。
        if ($cOut -notmatch 'SAGA-MERGE-CONFLICT') { Fail 'Gate 15r(e)C: -Local conflict recovery does not lead with the [SAGA-MERGE-CONFLICT] three-step main path (abort -> worktree merge base -> rerun ship) - saga text drifted from the T36 doctrine.'; $reFail = $true }
        if ($cOut -notmatch 'merge --abort') { Fail '闸15r(e)C：三步主路首步 git merge --abort 未在场。'; $reFail = $true }
        if ($cOut -notmatch '\(3\) rerun the same ship') { Fail 'Gate 15r(e)C: the three-step main path''s last step ((3) rerun the same ship) is not present - the resolved tree must re-pass every gate, not take the merge --continue bypass. (Anchored on the numbered step so the always-printed saga header cannot satisfy it, L165.)'; $reFail = $true }
        if ($cOut -notmatch 'merge --continue') { Fail '闸15r(e)C：冲突态未把 git merge --continue 保留为最后手段命令（R3 r4/r5 #9）。'; $reFail = $true }
        if ($cOut -notmatch 'selftest\.ps1') { Fail '闸15r(e)C：冲突态未要求合并后复检合并树（selftest/verify）——冲突消解产生的树未经过任何闸（R3 r6 #9）。'; $reFail = $true }
        if ($cFlat -notmatch '\[SHIP-LOCAL-MERGE-FAIL\] local merge of T0-SAGA15RC failed') { Fail 'Gate 15r(e)C: the original merge exception text is not present verbatim - the throw was rewritten or swallowed.'; $reFail = $true }
        # Three-step main-path BEHAVIOR fixture: (1) after abort, a bare rerun must re-conflict
        # deterministically; (2) resolving in the worktree (merge base, commit) then rerunning goes green
        # all the way through the local merge.
        if ($c2Exit -eq 0) { Fail '闸15r(e)C：abort 后裸重跑 ship -Local 竟退出 0——内容级冲突应确定性再现，三步主路首步（abort→裸重跑再冲突）不成立。'; $reFail = $true }
        if ($c2Out -notmatch [regex]::Escape('[SAGA-FAIL] local-merge (= first pending leg)')) { Fail 'Gate 15r(e)C: bare rerun after abort did not re-conflict on the local-merge leg - the conflict is not deterministic (three-step main-path premise broken).'; $reFail = $true }
        if ($c3Exit -ne 0) { Fail "闸15r(e)C：worktree 并入 base 解冲突提交后重跑 ship -Local 未全绿（exit $c3Exit）——管线内合并未 clean（三步主路末步不成立）。"; $reFail = $true }
        if ($c3Out -match 'T26-SHIPSAGA') { Fail 'Gate 15r(e)C: the rerun after conflict resolution still prints the saga failure report - the three-step main path''s last step is not truly green (guards the "exit 0 but report printed" vacuous pass).'; $reFail = $true }
        if (-not $eOut) { Fail '闸15r(e)E：ship 输出为空——未产出任何 saga 报告。'; $reFail = $true }
        if ($eExit -eq 0) { Fail '闸15r(e)E：合并前守卫拦下仍退出 0——异常被吞。'; $reFail = $true }
        if ($eOut -notmatch [regex]::Escape('[SAGA-FAIL] local-merge (= first pending leg)')) { Fail 'Gate 15r(e)E: the guard-stopped merge-leg failure is not named as the [SAGA-FAIL] point.'; $reFail = $true }
        if ($eOut -notmatch 'SAGA-MERGE-GUARDED') { Fail 'Gate 15r(e)E: a non-conflict merge failure (no MERGE_HEAD on disk) did not take the guarded state - steering it to merge --continue would error with no merge in progress (R3 r5 #9).'; $reFail = $true }
        if ($eOut -notmatch 'merge --no-ff --no-edit T0-SAGA15RE') { Fail '闸15r(e)E：守卫态未给「切回基线后重发完整合并」的精确命令。'; $reFail = $true }
        if ($eOut -match 'SAGA-MERGE-CONFLICT') { Fail 'Gate 15r(e)E: a non-conflict merge failure was misclassified as the conflict state (text-sniffing regression - every merge failure message contains "conflict?", R3 r5 #9).'; $reFail = $true }
        if (-not $fOut) { Fail '闸15r(e)F：ship 输出为空——未产出任何 saga 报告。'; $reFail = $true }
        if ($fExit -eq 0) { Fail '闸15r(e)F：凭据铸造失败仍退出 0——异常被吞。'; $reFail = $true }
        if ($fOut -notmatch 'SAGA-MERGE-TOKEN') { Fail 'Gate 15r(e)F: a post-merge token failure did not take the merge-already-succeeded state - the merge truly succeeded but was misreported (R3 r5 #9).'; $reFail = $true }
        if ($fOut -notmatch '-Phase cleanup -Force') { Fail '闸15r(e)F：post-merge 态未给 cleanup -Force 出路。'; $reFail = $true }
        if ($fOut -match 'SAGA-MERGE-GUARDED') { Fail 'Gate 15r(e)F: a post-merge token failure was misreported as the pre-merge guarded state (the original R3 r5 #9 misreport).'; $reFail = $true }
        if (-not $reFail) { Write-Host '  15r(e) hermetic 失败路径 OK（B：提交后建议重跑同一条 ship；D：重跑命令含调用方原样选项、无假死锁警告；C：冲突三步主路+merge --continue 最后手段；E：守卫态→重发 merge；F：post-merge→凭据未铸出路；各例均非零退出、原异常在场）' -ForegroundColor Green }
      }
    }
  } finally {
    Set-Location $RepoRoot
    & git -C $sg merge --abort 2>$null   # 场景 C 冲突后 master 停在合并中，先中止再清理
    & git -C $sg worktree prune 2>$null
    Remove-Item -Recurse -Force $sg -ErrorAction SilentlyContinue
  }
}

# 15e. 元仓真 verify.ps1 干跑断言（T2-VERIFY-LINT 常设自证）：本仓无 pyproject.toml、frontend/ 仅 *.example，
#   verify 各步以「项目清单文件存在」为门，须全部优雅跳过并 exit 0——锁「uv 在 PATH 而无 pyproject 时误跑 pytest 误红」类降级回归。
#   与机器无关（uv/npm 在不在场都走跳过分支），亦不需 git，故置于闸 15 的 git 条件之外。
& pwsh -NoProfile -File (Join-Path $RepoRoot 'scripts/verify.ps1') *> $null
if ($LASTEXITCODE -ne 0) { Fail "闸15e：元仓 verify.ps1 干跑非零退出（$LASTEXITCODE）——降级路径回归（无 pyproject/前端未引导时须优雅跳过、exit 0）。" }
else { Write-Host '  15e 元仓 verify 干跑 OK（无 pyproject/前端未引导 → 优雅降级 exit 0）' -ForegroundColor Green }

# 15l. TaskId 绑定期校验（TD50/TD-113）：start 外的相（red/ship/cleanup）此前拿未净化 -TaskId 拼 $Wt/$Card 路径，
#   cleanup 更 `Remove-Item -Recurse -Force $Wt`——路径穿越面。修法=参数上绑定期即校验，全相统一。
#   T229/TD231 起判据不再是本文件里的 [ValidatePattern] 字面量，而是 [ValidateScript] 转调 _cards.ps1 的
#   Test-ScaffoldCardId、由 card-id 规则行派生（含 CaseSensitive 半边）；本闸的判据与结论不变——它判的是
#   「绑定期是否拒」，不是「用哪种 attribute 拒」。派生本身由 15v 单独证明。
#   卡存在守卫（task.ps1:109，在 switch 之前）会先于任何相为不存在的卡 throw，故畸形 id 在新旧码下都退非零——
#   退出码无法区分「绑定期拒」与「卡不存在 throw」。改判绑定期拒绝消息里的 ASCII 哨兵 `TD50-BADID`
#   （locale/mojibake 无关）：修后=畸形 id 绑定期即拒、消息含哨兵；修前=落到 :109 卡不存在 throw、无哨兵 → 本闸红。
#   安全：修后畸形 id 在绑定期即拒、零副作用；合法格式 id 落到 :109 卡不存在 throw（switch/删除之前）→ 无删除副作用。
$tIdTask = Join-Path $RepoRoot 'scripts/task.ps1'
foreach ($badId in @('bad id', '..\..\evil-nonexistent', 'lower-case', 'T1-FOO;rm')) {
  $bo = & pwsh -NoProfile -File $tIdTask -Phase cleanup -TaskId $badId 2>&1 | Out-String
  if ($bo -notmatch 'TD50-BADID') { Fail "闸15l：畸形 TaskId '$badId' 未在参数绑定期被拒（输出无哨兵 TD50-BADID，落到卡不存在 throw）——TD50 未修/回归：未净化 TaskId 会拼进 `$Wt/`$Card 路径（cleanup Remove-Item -Recurse -Force，路径穿越面）。" }
}
# 合法格式 id 须通过绑定期校验（不出现哨兵；落到 :109 卡不存在 throw 即止，switch/删除之前，无副作用），证不误伤合法 id
$go = & pwsh -NoProfile -File $tIdTask -Phase cleanup -TaskId 'T99-NONEXISTENT' 2>&1 | Out-String
if ($go -match 'TD50-BADID') { Fail "闸15l：合法格式 TaskId 'T99-NONEXISTENT' 被绑定期校验误拒（出现哨兵 TD50-BADID）——绑定期校验过严、误伤合法 id（正路径回归）。" }
else { Write-Host '  15l TaskId 绑定期校验 OK（畸形/穿越 id 绑定期被拒、合法格式 id 放行）' -ForegroundColor Green }

# 15v. [CARD-ID-DERIVED] (T229/TD231)：证「两个入口 **派生** 卡 id 文法」，而非「与规则行字面相同」。
#   为什么字面相等的闸不够——这是本子闸存在的全部理由：修前三份字面量逐字节相同，行为却已经不同
#   （ValidatePattern 默认 RegexOptions.IgnoreCase，而 check-cards 用 -cmatch），于是 't1-foo'、'T0-scaffold'
#   这两个规则行 ShouldNot 自己点名的 id 在入口被放行、在 check-cards 被拒。字面比对会一路报「同步」。
#   故本闸的判据是**收窄规则行后入口的判定是否随之改变**：在副本里把 card-id 的 Pattern 收窄，原本被接受的
#   id 必须在绑定期被拒（出哨兵）。反向控制在同一副本族里做：未收窄的副本对同一 id 不出哨兵——否则「拒」
#   可能只是副本坏了，而不是派生生效（防 vacuous PASS）。第三臂证 CaseSensitive 半边也走的是同一条派生链。
$cidRoot = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-cardid-$PID"
if (Test-Path $cidRoot) { Remove-Item $cidRoot -Recurse -Force }
foreach ($cidVariant in @('pristine', 'narrowed')) {
  $cidDir = Join-Path $cidRoot $cidVariant
  New-Item -ItemType Directory -Force (Join-Path $cidDir 'scripts') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts/*.ps1') (Join-Path $cidDir 'scripts') -Force
  if ($cidVariant -eq 'narrowed') {
    # 只动规则行的 Pattern，别的一概不动——收窄到只认一个字面 id。若入口仍持有自己的副本，本臂必红。
    $cidCards = Join-Path $cidDir 'scripts/_cards.ps1'
    $cidText = Get-Content -LiteralPath $cidCards -Raw
    # 替换串里 `$$` 是「一个字面 $」，`$1`/`$2` 是捕获组：末锚点要写 `$$`，收尾组要写 `$2`。
    # 曾写成 `${1}...$${2}`，.NET 解析为「字面 $」+「字面 {2}」，把收尾引号吃掉、_cards.ps1 变成语法坏文件——
    # 夹具坏了却仍产出一个「未派生」的结论（L227 的转义类）。故下方两道自证不是装饰，是这条 bug 的回归。
    $cidNew = $cidText -replace "(@\{ Id = 'card-id'; Pattern = ')[^']+(')", '$1^T0-ONLYTHIS$$$2'
    if ($cidNew -eq $cidText) { Fail '闸15v([CARD-ID-DERIVED:FIXTURE])：未能在副本中收窄 card-id 规则行的 Pattern（正则未命中）——夹具自身失效，本闸的结论不可采信（防 vacuous PASS）。' }
    Set-Content -LiteralPath $cidCards -Value $cidNew -NoNewline -Encoding utf8
    # 自证①：收窄后的副本必须仍能被解析。坏文件会让入口的 dot-source 抛错，那种「拒」与「派生生效」无关。
    $cidErr = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($cidCards, [ref]$null, [ref]$cidErr)
    if ($cidErr -and $cidErr.Count -gt 0) { Fail "闸15v([CARD-ID-DERIVED:FIXTURE])：收窄后的 _cards.ps1 副本已不可解析（$($cidErr.Count) 个语法错误）——夹具把文件改坏了，臂2 的判定无论红绿都不可采信。" }
    # 自证②：副本里的判定必须真的按收窄后的规则行走——直接问那份副本，不经入口。
    $cidProbe = & pwsh -NoProfile -Command ". '$cidCards'; if (Test-ScaffoldCardId 'T99-NONEXISTENT') { exit 3 }; if (-not (Test-ScaffoldCardId 'T0-ONLYTHIS')) { exit 4 }; exit 0" 2>&1 | Out-String
    if ($LASTEXITCODE -ne 0) { Fail "闸15v([CARD-ID-DERIVED:FIXTURE])：收窄后的副本自身判定不符预期（exit $LASTEXITCODE；3=旧 id 仍被接受，4=新 id 未被接受）——夹具未真正收窄，臂2 不可采信。输出：$cidProbe" }
  }
}
# 臂1（反向控制）：未收窄的副本里，合法 id 不得被拒——证副本可用、拒绝不是副本坏了。
$cidPristineOut = & pwsh -NoProfile -File (Join-Path $cidRoot 'pristine/scripts/task.ps1') -Phase cleanup -TaskId 'T99-NONEXISTENT' 2>&1 | Out-String
if ($cidPristineOut -match 'TD50-BADID') { Fail "闸15v([CARD-ID-DERIVED:A1]) 臂1：未收窄的副本把合法 id 'T99-NONEXISTENT' 在绑定期拒了（出现哨兵）——副本本身即坏，臂2 的『拒』不能归因于收窄（vacuous）。" }
# 臂2（派生本体）：收窄规则行后，同一个 id 必须在绑定期被拒。字面相等的闸在这里不会变红，派生的会。
$cidNarrowOut = & pwsh -NoProfile -File (Join-Path $cidRoot 'narrowed/scripts/task.ps1') -Phase cleanup -TaskId 'T99-NONEXISTENT' 2>&1 | Out-String
if ($cidNarrowOut -notmatch 'TD50-BADID') { Fail "闸15v([CARD-ID-DERIVED:A2]) 臂2：把 _cards.ps1 的 card-id 规则行收窄后，'T99-NONEXISTENT' 仍在 task.ps1 绑定期被放行（无哨兵）——入口没有从规则行派生文法，而是持有自己的副本（TD231 未修/回归）。" }
# 臂3（CaseSensitive 半边）：规则行声明大小写敏感，入口必须照此判——这正是旧 ValidatePattern 放行的那一类。
$cidCaseOut = & pwsh -NoProfile -File (Join-Path $cidRoot 'pristine/scripts/task.ps1') -Phase cleanup -TaskId 'T99-LOWERcase' 2>&1 | Out-String
if ($cidCaseOut -notmatch 'TD50-BADID') { Fail "闸15v([CARD-ID-DERIVED:A3]) 臂3：'T99-LOWERcase' 未在绑定期被拒（无哨兵）——规则行的 CaseSensitive 半边没有被入口采纳，回到 ValidatePattern 默认 IgnoreCase 的旧行为（TD231 的实测分歧）。" }
# 臂4（第二个入口）：check-scope.ps1 也必须走同一条派生链。臂1-3 只驱动 task.ps1，若少了本臂，
#   「删掉 check-scope 的校验行」这个变异会存活——两个入口共用一条规则的主张就只证了一半。
#   判据用 check-scope 自己的 ASCII 哨兵 [SCOPE-BADID]，不复用 TD50-BADID：否则分不清是哪个入口拒的。
$cidScopeCase = & pwsh -NoProfile -File (Join-Path $cidRoot 'pristine/scripts/check-scope.ps1') -TaskId 'T99-LOWERcase' -Base master 2>&1 | Out-String
if ($cidScopeCase -notmatch 'SCOPE-BADID') { Fail "闸15v([CARD-ID-DERIVED:A4]) 臂4：check-scope.ps1 未在绑定期拒 'T99-LOWERcase'（无哨兵 SCOPE-BADID）——第二个入口没有采纳规则行的判定（含 CaseSensitive 半边），TD231 只修了一半。" }
$cidScopeNarrow = & pwsh -NoProfile -File (Join-Path $cidRoot 'narrowed/scripts/check-scope.ps1') -TaskId 'T99-NONEXISTENT' -Base master 2>&1 | Out-String
if ($cidScopeNarrow -notmatch 'SCOPE-BADID') { Fail "闸15v([CARD-ID-DERIVED:A4B]) 臂4b：收窄规则行后 check-scope.ps1 仍放行 'T99-NONEXISTENT'（无哨兵 SCOPE-BADID）——第二个入口持有自己的文法副本，未从规则行派生。" }
Remove-Item $cidRoot -Recurse -Force -ErrorAction SilentlyContinue
Write-Host '  15v [CARD-ID-DERIVED] 卡 id 文法派生 OK（收窄规则行即改变两个入口的判定；未收窄副本不误拒；CaseSensitive 半边生效；task.ps1 与 check-scope.ps1 各自证）' -ForegroundColor Green

# 15f. verify 收紧路径夹具自证（stub uv/npm 记录调用 + 种子失败；15e 证「未引导→优雅降级」，此处证「引导后→真跑且红传导」）：
#   (a) pyproject + uv 在 → ruff 经 `uv run --no-sync` 被真调（--no-sync 同时是「verify 不在闸内装依赖」的常设离线证据）；
#   (b) frontend/package.json + node_modules 在 → npm run check / run test 被真调，stub 非零退出须把 verify 置红（防假绿）。
#   stub 按 OS 生成（Windows .cmd / 类 Unix sh），全离线确定；临时目录即弃，PATH 用毕还原，绝不动元仓。
$verifySource15 = [System.IO.File]::ReadAllText((Join-Path $RepoRoot 'scripts/verify.ps1'))
$projectGoldenVerify15 =
  $verifySource15.Contains(':core:e2eTest') -and
  $verifySource15.Contains('[GATE2-MISSING]') -and
  $verifySource15.Contains('[GATE2-NOT-RUN]')

# 本仓 verify 的 Gate 2 是已交付的 Android/Golden Evidence 闭环，而不是上游脚手架的
# Get-ScaffoldE2ECommand。15f 只判 Gate 1，因此在这些微型夹具中提供真实 Gradle 调用面，
# 让 Gate 1 的绿/红结论可达；15x 则另行覆盖该产品接口的缺失、绿、红三态。
function Set-ProjectGate2Stub15([string]$Root, [int]$ExitCode = 0) {
  if (-not $projectGoldenVerify15) { return }
  New-Item -ItemType Directory -Force (Join-Path $Root 'android') | Out-Null
  if ($IsWindows) {
    Set-Content (Join-Path $Root 'android/gradlew.bat') "@echo off`r`nexit /b $ExitCode" -Encoding ascii
  } else {
    $stub = Join-Path $Root 'android/gradlew'
    Set-Content $stub "#!/bin/sh`nexit $ExitCode" -Encoding utf8
    [System.IO.File]::SetUnixFileMode($stub, 'UserRead,UserWrite,UserExecute,GroupRead,GroupExecute,OtherRead,OtherExecute')
  }
}
$vfx = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-selftest-vfx-$PID"
$vfxOldPath = $env:PATH
try {
  $vfxBin = Join-Path $vfx 'bin'
  $uvLog = Join-Path $vfx 'uv.log'; $npmLog = Join-Path $vfx 'npm.log'
  New-Item -ItemType Directory -Force $vfxBin, (Join-Path $vfx 'a/scripts'), (Join-Path $vfx 'b/scripts'), (Join-Path $vfx 'b/frontend/node_modules') | Out-Null
  Set-ProjectGate2Stub15 (Join-Path $vfx 'a') 0
  Set-ProjectGate2Stub15 (Join-Path $vfx 'b') 0
  if ($IsWindows) {
    Set-Content (Join-Path $vfxBin 'uv.cmd')  "@echo off`r`necho uv %* >> `"$uvLog`"`r`nexit /b 0" -Encoding utf8
    Set-Content (Join-Path $vfxBin 'npm.cmd') "@echo off`r`necho npm %* >> `"$npmLog`"`r`nexit /b 1" -Encoding utf8
  } else {
    Set-Content (Join-Path $vfx 'bin/uv')  "#!/bin/sh`necho uv `"`$@`" >> '$uvLog'`nexit 0" -Encoding utf8
    Set-Content (Join-Path $vfx 'bin/npm') "#!/bin/sh`necho npm `"`$@`" >> '$npmLog'`nexit 1" -Encoding utf8
    # T205/TD201: the execute bit is set through the framework, not through `& chmod`. Hiding a tool from
    # PATH is DIRECTORY-granular - there is no way to remove one executable from a shared directory - so
    # when 8.2j hides `git` on a POSIX box it necessarily takes the whole of /usr/bin with it, and chmod
    # lives there too. Measured on ubuntu 2026-08-29: `-Only 15` with git hidden died here on
    # "The term 'chmod' is not recognized", which is not a statement about gate 15's git degradation at
    # all - 15f does not use git. Calling the framework keeps the fixture running under the strip instead
    # of skipping it, so the coverage is preserved rather than announced away. Absolute paths only (L106).
    foreach ($vfxStub in @((Join-Path $vfx 'bin/uv'), (Join-Path $vfx 'bin/npm'))) {
      [System.IO.File]::SetUnixFileMode($vfxStub, 'UserRead,UserWrite,UserExecute,GroupRead,GroupExecute,OtherRead,OtherExecute')
    }
  }
  $env:PATH = $vfxBin + [System.IO.Path]::PathSeparator + $env:PATH
  # (a) Python 已引导夹具：裸 pyproject → ruff 须被真调且含 --no-sync；stub 全绿 → verify exit 0。
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfx 'a/scripts/verify.ps1')
  Set-Content (Join-Path $vfx 'a/pyproject.toml') '[project]' -Encoding utf8
  & pwsh -NoProfile -File (Join-Path $vfx 'a/scripts/verify.ps1') *> $null
  $vfxAExit = $LASTEXITCODE
  $vfxALog = if (Test-Path $uvLog) { Get-Content $uvLog -Raw } else { '' }
  if ($vfxALog -notmatch 'run --no-sync ruff check') { Fail "闸15f(a)：pyproject+uv 在场时 ruff 未被真调或缺 --no-sync（uv.log=$($vfxALog.Trim())）——linter 兜底名存实亡 / verify 可能在闸内联网装依赖。" }
  elseif ($vfxAExit -ne 0) { Fail "闸15f(a)：ruff stub 全绿时 verify 仍非零退出（$vfxAExit）——收紧路径误红。" }
  else { Write-Host '  15f(a) ruff 真调 OK（uv run --no-sync ruff check 被调用、stub 绿 → verify exit 0）' -ForegroundColor Green }
  # (b) 前端已引导夹具：package.json + node_modules → npm run check / run test 须被真调；stub 红 → verify 必 exit 1。
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfx 'b/scripts/verify.ps1')
  Set-Content (Join-Path $vfx 'b/frontend/package.json') '{"name":"vfx","version":"0.0.0","scripts":{"check":"exit 1","test":"exit 1"}}' -Encoding utf8
  & pwsh -NoProfile -File (Join-Path $vfx 'b/scripts/verify.ps1') *> $null
  $vfxBExit = $LASTEXITCODE
  $vfxBLog = if (Test-Path $npmLog) { Get-Content $npmLog -Raw } else { '' }
  if (($vfxBLog -notmatch 'run check') -or ($vfxBLog -notmatch 'run test')) { Fail "闸15f(b)：前端已引导时 npm run check / run test 未被真调（npm.log=$($vfxBLog.Trim())）——前端闸名存实亡。" }
  elseif ($vfxBExit -eq 0) { Fail '闸15f(b)：前端 check/test 红（stub exit 1）时 verify 仍 exit 0——前端闸红不传导（假绿）。' }
  else { Write-Host '  15f(b) 前端红传导 OK（npm run check+test 真跑、stub 红 → verify exit 1）' -ForegroundColor Green }
} finally {
  $env:PATH = $vfxOldPath
  Remove-Item -Recurse -Force $vfx -ErrorAction SilentlyContinue
}

# 15f(c). TD43：pyproject.toml 在场（真已引导 Python 项目）但 uv 不在 PATH 时，ruff/pytest 两分支须 fail-closed（非零退出）——
#   镜像前端分支（:80-82）的既有先例；旧码两分支只打印跳过提示、$failed 不置位 → 误报绿（零 lint 零测试却 verify: PASS）。
#   裸骨架（无 pyproject.toml）在同样缺 uv 时须仍优雅跳过 exit 0（15e 已证的降级路径不可回归）。
#   PATH 只在**子进程内部**被 shim（一个写到临时目录的包装脚本，自己进程内把 $env:PATH 收窄到不含 uv 的极简目录表，
#   再用 pwsh 全路径去调 verify.ps1）——本 selftest（父/会话）进程的 $env:PATH 全程不动，亦不碰真实仓库。
$vfxC = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-selftest-vfxc-$PID"
if (Test-Path $vfxC) { Remove-Item -Recurse -Force $vfxC }
try {
  New-Item -ItemType Directory -Force (Join-Path $vfxC 'py/scripts'), (Join-Path $vfxC 'bare/scripts') | Out-Null
  Set-ProjectGate2Stub15 (Join-Path $vfxC 'py') 0
  Set-ProjectGate2Stub15 (Join-Path $vfxC 'bare') 0
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfxC 'py/scripts/verify.ps1')
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfxC 'bare/scripts/verify.ps1')
  Set-Content (Join-Path $vfxC 'py/pyproject.toml') '[project]' -Encoding utf8   # 'bare' 夹具故意不放 pyproject.toml
  $pwshExe = (Get-Command pwsh | Select-Object -First 1).Source
  $shimPath = if ($IsWindows) { (Join-Path $env:SystemRoot 'System32') + ';' + $env:SystemRoot } else { '/usr/bin:/bin' }
  $wrapC = Join-Path $vfxC 'run-shimmed.ps1'
  # 单引号 here-string：字面量写入，wrapper 自身运行时才对 $env:PATH/$PwshExe 等求值（子进程私有作用域，不牵父进程）。
  Set-Content $wrapC @'
param([string]$PwshExe, [string]$VerifyPath, [string]$ShimPath)
$env:PATH = $ShimPath
& $PwshExe -NoProfile -File $VerifyPath
exit $LASTEXITCODE
'@ -Encoding utf8
  & pwsh -NoProfile -File $wrapC -PwshExe $pwshExe -VerifyPath (Join-Path $vfxC 'py/scripts/verify.ps1') -ShimPath $shimPath *> $null
  $vfxCPyExit = $LASTEXITCODE
  & pwsh -NoProfile -File $wrapC -PwshExe $pwshExe -VerifyPath (Join-Path $vfxC 'bare/scripts/verify.ps1') -ShimPath $shimPath *> $null
  $vfxCBareExit = $LASTEXITCODE
  if ($vfxCPyExit -eq 0) { Fail "闸15f(c)：pyproject.toml 在场但 uv 不在 PATH（子进程内 shim，父进程 PATH 未动）时 verify.ps1 仍 exit 0（TD43：ruff/pytest 两分支静默跳过、`$failed` 未置位，零 lint 零测试却报绿，违反 verify.ps1:17 fail-closed 自称，且与前端分支 :80-82 不对称）。" }
  elseif ($vfxCBareExit -ne 0) { Fail "闸15f(c)：无 pyproject.toml（裸骨架）+ uv 不在 PATH 时 verify.ps1 非零退出（$vfxCBareExit）——裸骨架优雅跳过路径回归（TD43 修复不应影响此分支，15e 已证的降级路径被破坏）。" }
  else { Write-Host '  15f(c) TD43 uv 缺席 fail-closed OK（pyproject 在+uv 缺 → 非零；裸骨架+uv 缺 → 仍 exit 0 绿）' -ForegroundColor Green }
} finally {
  Remove-Item -Recurse -Force $vfxC -ErrorAction SilentlyContinue
}

# 15x. [VERIFY-THREE-STATES] (T296/TD224, extended by T297/TD285): verify's verdict is an assertion about
#   gates that RAN. 'verify: PASS' may never appear while a gate this file claims is an unwired placeholder,
#   and a configuration verify could not READ is FAIL, never that unwired state - "I could not read the
#   setting" is not "the setting is off".
#   LABEL is 15x, not 15g: the incumbent `15g` is the RED-phase / gate-removal contract at :7857 and its
#   continuations, indented inside gate 15 and therefore invisible to 14m, which projects column-0 headers
#   plus gate-17 seeds only. Registered as TD286; an anchored '^# 15[a-z]' grep will not find it either.
#   NB no line in this block may BEGIN with a bare label token, because the projection reads that as a
#   continuation header. Two earlier drafts of this very paragraph wrapped onto such a line and each
#   declared a phantom sub-gate; 14m's own form check caught both, which is the rule earning its keep.
#   The lettered rows below are the inventory. Each is backed by a hermetic run; the mapping from rows to
#   fixtures is deliberately NOT described here, because it is not one-to-one - (a) and (b) share one fixture
#   and (i) needs two - and every attempt to summarise it inline has been wrong: first a stale count, then a
#   corrected count that went stale on the next edit, then a false one-to-one claim. TD287 is that class; the
#   rule it earns is that a summary of a structure standing next to the structure is a liability, not a
#   service. Read the rows.
#   Every fixture is a copy of verify.ps1 plus a `_config.ps1` chosen
#   to exercise ONE branch - most define Get-ScaffoldE2ECommand, while brokencfg/emptymsg/partial THROW and
#   `absent` has no config file at all. The accessor's own missing-key / empty-array / argv-array semantics
#   are held by Test-ScaffoldConfigAccessorExamples in scripts/_config.ps1, not here.
#   (a) unconfigured           -> exit 0, prints NOT CONFIGURED, never PASS. The exit 0 is deliberate: ci.yml
#       runs this on every push to a repository that cannot wire gate 2 at all.
#   (b) unconfigured -Strict   -> non-zero AND still reaches the verdict line, since a crash is also non-zero.
#   (c) configured + green     -> exit 0 and prints PASS, so the third state cannot retire the word.
#   (d) configured + red       -> exit 1 and prints FAIL; the command's non-zero must propagate.
#   (e) driver missing on PATH -> non-zero. The 15f(c)/TD43 precedent: declared-but-absent material is red.
#   (f) config throws WITH a message    -> FAIL, not the third state.
#   (g) config throws with an EMPTY one -> FAIL. (f) cannot catch this: the failure was stored AS the message,
#       so a throw carrying none stayed falsy. A message is a detail about a failure, never the failure.
#   (h) the ACCESSOR throws             -> FAIL with a PRINTED verdict, not a bare crash.
#   (i) config DEFINES the accessor and then throws -> FAIL, and the accessor is never invoked (its marker
#       file is absent). The only fixture that can prove the skip: the others throw before defining anything,
#       so the accessor is missing and Get-Command would decline to call it regardless.
#   (j) ABSENT config          -> exit 0 and prints NOT CONFIGURED. 15f(a) covers absence's EXIT CODE; this
#       covers its VERDICT TEXT, which the `none` fixture (present config, empty command) does not.
if ($projectGoldenVerify15) {
  # This product's Gate 2 is deliberately fixed to Android :core:e2eTest.  Do not pretend the upstream
  # config-accessor matrix exercises it: use the executable project contract and keep every state live.
  $vfgProduct = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-selftest-vfg-product-$PID"
  if (Test-Path $vfgProduct) { Remove-Item -Recurse -Force $vfgProduct }
  try {
    foreach ($vfgProductCase in @('missing', 'green', 'red')) {
      $caseScripts = Join-Path $vfgProduct "$vfgProductCase/scripts"
      New-Item -ItemType Directory -Force $caseScripts | Out-Null
      Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $caseScripts 'verify.ps1')
    }
    Set-ProjectGate2Stub15 (Join-Path $vfgProduct 'green') 0
    Set-ProjectGate2Stub15 (Join-Path $vfgProduct 'red') 1
    $vfgProductLog = Join-Path $vfgProduct 'run.log'
    & pwsh -NoProfile -File (Join-Path $vfgProduct 'missing/scripts/verify.ps1') *> $vfgProductLog
    $vfgMissingExit = $LASTEXITCODE; $vfgMissingOut = Get-Content $vfgProductLog -Raw
    & pwsh -NoProfile -File (Join-Path $vfgProduct 'green/scripts/verify.ps1') *> $vfgProductLog
    $vfgGreenExit = $LASTEXITCODE; $vfgGreenOut = Get-Content $vfgProductLog -Raw
    & pwsh -NoProfile -File (Join-Path $vfgProduct 'red/scripts/verify.ps1') *> $vfgProductLog
    $vfgRedExit = $LASTEXITCODE; $vfgRedOut = Get-Content $vfgProductLog -Raw
    if ($vfgMissingExit -eq 0) { Fail '15x(a) [GATE2-MISSING-GREEN] a missing product Android wrapper made verify exit 0. Golden Evidence was not run, so this must fail closed.' }
    elseif (($vfgMissingOut -notmatch '\[GATE2-MISSING\]') -or ($vfgMissingOut -notmatch '\[GATE2-NOT-RUN\]') -or ($vfgMissingOut -notmatch 'verify: FAIL')) { Fail '15x(a) [GATE2-MISSING-SILENT] a missing product Android wrapper did not print GATE2-MISSING, GATE2-NOT-RUN, and verify: FAIL.' }
    elseif ($vfgGreenExit -ne 0) { Fail "15x(b) [GATE2-GREEN-FALSE-RED] the product Golden Evidence pass stub made verify exit $vfgGreenExit." }
    elseif ($vfgGreenOut -notmatch 'verify: PASS') { Fail '15x(b) [GATE2-GREEN-NOVERDICT] the product Golden Evidence pass stub did not reach verify: PASS.' }
    elseif ($vfgRedExit -eq 0) { Fail '15x(c) [GATE2-RED-NOT-PROPAGATED] the product Golden Evidence failure stub made verify exit 0.' }
    elseif (($vfgRedOut -notmatch '\[GATE2-FAILED\]') -or ($vfgRedOut -notmatch 'verify: FAIL')) { Fail '15x(c) [GATE2-RED-NOVERDICT] the product Golden Evidence failure stub did not print GATE2-FAILED and verify: FAIL.' }
    else { Write-Host '  15x product Golden Evidence three-state verdict OK (missing -> GATE2-MISSING/NOT-RUN + FAIL; green -> PASS; red -> GATE2-FAILED + FAIL)' -ForegroundColor Green }
  } finally {
    Remove-Item -Recurse -Force $vfgProduct -ErrorAction SilentlyContinue
  }
} else {
$vfg = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-selftest-vfg-$PID"
if (Test-Path $vfg) { Remove-Item -Recurse -Force $vfg }
$vfgOldPath = $env:PATH
try {
  $vfgBin = Join-Path $vfg 'bin'
  New-Item -ItemType Directory -Force $vfgBin, (Join-Path $vfg 'none/scripts'), (Join-Path $vfg 'ok/scripts'), (Join-Path $vfg 'bad/scripts'), (Join-Path $vfg 'nodriver/scripts'), (Join-Path $vfg 'brokencfg/scripts'), (Join-Path $vfg 'emptymsg/scripts'), (Join-Path $vfg 'accthrow/scripts'), (Join-Path $vfg 'partial/scripts'), (Join-Path $vfg 'absent/scripts'), (Join-Path $vfg 'markerctl/scripts') | Out-Null
  if ($IsWindows) {
    Set-Content (Join-Path $vfgBin 'e2eok.cmd')  "@echo off`r`nexit /b 0" -Encoding utf8
    Set-Content (Join-Path $vfgBin 'e2ebad.cmd') "@echo off`r`nexit /b 1" -Encoding utf8
  } else {
    Set-Content (Join-Path $vfg 'bin/e2eok')  "#!/bin/sh`nexit 0" -Encoding utf8
    Set-Content (Join-Path $vfg 'bin/e2ebad') "#!/bin/sh`nexit 1" -Encoding utf8
    # As in 15f: the execute bit is set through the framework, never via `& chmod` - when 8.2j hides git on
    # a POSIX box it necessarily hides the whole of /usr/bin with it, and chmod lives there too (T205/TD201).
    foreach ($vfgStub in @((Join-Path $vfg 'bin/e2eok'), (Join-Path $vfg 'bin/e2ebad'))) {
      [System.IO.File]::SetUnixFileMode($vfgStub, 'UserRead,UserWrite,UserExecute,GroupRead,GroupExecute,OtherRead,OtherExecute')
    }
  }
  $env:PATH = $vfgBin + [System.IO.Path]::PathSeparator + $env:PATH
  foreach ($vfgCase in @(
      @{ Dir = 'none';     Cmd = '@()' }
      @{ Dir = 'ok';       Cmd = "@('e2eok')" }
      @{ Dir = 'bad';      Cmd = "@('e2ebad')" }
      @{ Dir = 'nodriver'; Cmd = "@('scaffold-nonexistent-e2e-driver')" }
    )) {
    Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfg "$($vfgCase.Dir)/scripts/verify.ps1")
    Set-Content (Join-Path $vfg "$($vfgCase.Dir)/scripts/_config.ps1") "function Get-ScaffoldE2ECommand { return $($vfgCase.Cmd) }" -Encoding utf8
  }
  # (f) fixture: a _config.ps1 that is PRESENT and throws. Written outside the loop because it is the one
  # case that defines no accessor at all - the point is that verify never gets to ask.
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfg 'brokencfg/scripts/verify.ps1')
  Set-Content (Join-Path $vfg 'brokencfg/scripts/_config.ps1') "throw 'seeded broken config'" -Encoding utf8
  # (g) T297/TD285: a load throw whose Message is EMPTY. This is the fixture (f) could not be - (f) throws
  # WITH text, and the defect lived entirely in the absence of text.
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfg 'emptymsg/scripts/verify.ps1')
  Set-Content (Join-Path $vfg 'emptymsg/scripts/_config.ps1') 'throw ([System.Exception]::new([string]::Empty))' -Encoding utf8
  # (h) T297/TD285: the config loads and the ACCESSOR throws, which T296 called outside any catch.
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfg 'accthrow/scripts/verify.ps1')
  Set-Content (Join-Path $vfg 'accthrow/scripts/_config.ps1') "function Get-ScaffoldE2ECommand { throw 'seeded accessor failure' }" -Encoding utf8
  # (i) PARTIAL LOAD, and it is the only fixture that can prove "gate 2 is not consulted after a load
  # failure". The other two load-failure fixtures throw BEFORE defining anything, so the accessor is absent
  # and `Get-Command` would decline to call it regardless - the guard would look proven while never being
  # exercised. Here the accessor IS defined and then the file throws, so the guard is the only thing standing
  # between a failed load and a call. The accessor writes a marker; the arm asserts the marker is ABSENT,
  # which is the observable form of "was never invoked".
  # The marker path is NOT interpolated into the fixture source. It is derived at fixture RUNTIME from
  # $PSScriptRoot, because interpolating a host path into a single-quoted literal breaks on any root
  # containing an apostrophe - and it breaks in the worst possible way: the generated config fails to PARSE,
  # which throws before defining the accessor, so verify exits non-zero, prints FAIL and leaves the marker
  # absent. Every assertion below would pass while proving nothing. A vacuous test that only reveals itself
  # on somebody else's username is worse than no test (found by the R3 reviewer, dimension #6).
  $vfgMarker = Join-Path $vfg 'partial/scripts/accessor-was-called.txt'
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfg 'partial/scripts/verify.ps1')
  Set-Content (Join-Path $vfg 'partial/scripts/_config.ps1') @(
    'function Get-ScaffoldE2ECommand { Set-Content -LiteralPath (Join-Path $PSScriptRoot ''accessor-was-called.txt'') -Value ''called''; return @() }'
    'throw ([System.Exception]::new([string]::Empty))'
  ) -Encoding utf8
  # (i) POSITIVE CONTROL, and arm (i) means nothing without it. `partial` asserts the marker is ABSENT, which
  # is only evidence if the marker mechanism demonstrably WORKS - otherwise a broken side effect and a
  # correctly skipped accessor are the same observation. This fixture carries the identical accessor and does
  # NOT throw, so the accessor is reached normally and the marker MUST appear.
  $vfgCtlMarker = Join-Path $vfg 'markerctl/scripts/accessor-was-called.txt'
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfg 'markerctl/scripts/verify.ps1')
  Set-Content (Join-Path $vfg 'markerctl/scripts/_config.ps1') 'function Get-ScaffoldE2ECommand { Set-Content -LiteralPath (Join-Path $PSScriptRoot ''accessor-was-called.txt'') -Value ''called''; return @() }' -Encoding utf8
  # (j) ABSENT config: no _config.ps1 at all. 15f(a) already covers the absent-config EXIT CODE, but nothing
  # asserted the absent-config VERDICT TEXT - the 'none' fixture above has a PRESENT config returning an
  # empty command, which is a different question. Absence and empty must both reach NOT CONFIGURED, and only
  # this fixture says so about absence.
  Copy-Item (Join-Path $RepoRoot 'scripts/verify.ps1') (Join-Path $vfg 'absent/scripts/verify.ps1')
  $vfgLog = Join-Path $vfg 'run.log'
  & pwsh -NoProfile -File (Join-Path $vfg 'none/scripts/verify.ps1') *> $vfgLog
  $vfgNoneExit = $LASTEXITCODE; $vfgNoneOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'none/scripts/verify.ps1') -Strict *> $vfgLog
  $vfgStrictExit = $LASTEXITCODE; $vfgStrictOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'ok/scripts/verify.ps1') *> $vfgLog
  $vfgOkExit = $LASTEXITCODE; $vfgOkOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'bad/scripts/verify.ps1') *> $vfgLog
  $vfgBadExit = $LASTEXITCODE; $vfgBadOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'nodriver/scripts/verify.ps1') *> $vfgLog
  $vfgNoDrvExit = $LASTEXITCODE; $vfgNoDrvOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'brokencfg/scripts/verify.ps1') *> $vfgLog
  $vfgBrkExit = $LASTEXITCODE; $vfgBrkOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'emptymsg/scripts/verify.ps1') *> $vfgLog
  $vfgEmpExit = $LASTEXITCODE; $vfgEmpOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'accthrow/scripts/verify.ps1') *> $vfgLog
  $vfgAccExit = $LASTEXITCODE; $vfgAccOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'partial/scripts/verify.ps1') *> $vfgLog
  $vfgParExit = $LASTEXITCODE; $vfgParOut = Get-Content $vfgLog -Raw
  $vfgParCalled = Test-Path $vfgMarker
  & pwsh -NoProfile -File (Join-Path $vfg 'absent/scripts/verify.ps1') *> $vfgLog
  $vfgAbsExit = $LASTEXITCODE; $vfgAbsOut = Get-Content $vfgLog -Raw
  & pwsh -NoProfile -File (Join-Path $vfg 'markerctl/scripts/verify.ps1') *> $vfgLog
  $vfgCtlExit = $LASTEXITCODE; $vfgCtlCalled = Test-Path $vfgCtlMarker
  if ($vfgNoneOut -match 'verify: PASS') { Fail "15x(a) [VERIFY-PASS-WHILE-PENDING] verify still prints 'verify: PASS' while gate 2 is unconfigured. This is the false green TD224 and ADR 0015 record: the warning speaks only to a person, ci.yml's E2E verify gate step reads the exit code alone, and the placeholder is banked as a complete pass. PASS asserts that the gates RAN; gate 2 did not." }
  elseif ($vfgNoneOut -notmatch 'verify: NOT CONFIGURED') { Fail "15x(a) [VERIFY-STATE-SILENT] with gate 2 unconfigured verify printed neither 'verify: PASS' nor 'verify: NOT CONFIGURED'. Silence is not the third state - what is missing is the positive statement naming which gate is unwired." }
  elseif ($vfgNoneExit -ne 0) { Fail "15x(a) [VERIFY-DEFAULT-RED] verify exited non-zero ($vfgNoneExit) with gate 2 merely unconfigured. The default must stay exit 0 (gate 15e / TOOLCHAIN-INTERFACE invariant 1) or ci.yml reds master on every push to this repository to buy honesty. The escalation path is -Strict, not the default." }
  elseif ($vfgStrictExit -eq 0) { Fail '15x(b) [VERIFY-STRICT-INERT] -Strict still exited 0 with gate 2 unconfigured, so the escalation lever a downstream CI uses to demand a complete closure does nothing.' }
  elseif ($vfgStrictOut -notmatch 'verify: NOT CONFIGURED') { Fail "15x(b) [VERIFY-STRICT-VACUOUS] the -Strict run exited non-zero but never reached the verdict line (no 'verify: NOT CONFIGURED' in its output). A run that crashes early is also non-zero, so asserting the exit code alone proves nothing." }
  elseif ($vfgOkExit -ne 0) { Fail "15x(c) [VERIFY-CONFIGURED-FALSE-RED] E2ECommand is configured and its command is green, yet verify exited non-zero ($vfgOkExit) - the tightened path reds when it should pass." }
  elseif ($vfgOkOut -notmatch 'verify: PASS') { Fail "15x(c) [VERIFY-PASS-UNREACHABLE] every gate ran and is green, yet verify did not print 'verify: PASS'. The third state may not be bought by retiring PASS: if PASS is unreachable the word carries no meaning." }
  elseif ($vfgBadExit -eq 0) { Fail '15x(d) [VERIFY-E2E-RED-NOT-PROPAGATED] E2ECommand is configured and its command is red (stub exit 1), yet verify exited 0 - gate 2 red does not propagate, which is a false green.' }
  elseif ($vfgBadOut -notmatch 'verify: FAIL') { Fail "15x(d) [VERIFY-FAIL-UNPRINTED] gate 2 is red and verify exited non-zero, but it did not print 'verify: FAIL'. The three-state verdict line must cover the failure state too, not leave it to the exit code." }
  elseif ($vfgNoDrvExit -eq 0) { Fail '15x(e) [VERIFY-DRIVER-MISSING-GREEN] E2ECommand is DECLARED but its driver is not on PATH, yet verify exited 0. That breaks the 15f(c)/TD43 precedent: declared-but-missing material is fail-closed red, never a silent skip that reports green having run zero e2e.' }
  elseif ($vfgNoDrvOut -notmatch 'verify: FAIL') { Fail "15x(e) [VERIFY-DRIVER-MISSING-MISREPORTED] the driver is absent and verify exited non-zero, but it did not print 'verify: FAIL'. Missing material is the failure state, not the third state - unconfigured is not the same as configured-but-uninstallable." }
  elseif ($vfgBrkExit -eq 0) { Fail '15x(f) [VERIFY-CONFIG-BROKEN-GREEN] scripts/_config.ps1 is PRESENT and throws, yet verify exited 0. A configuration it could not read is being reported as a gate that is merely unwired - "I could not read the setting" misclassified as "the setting is off", which is this card own false green one layer down. Tolerate ABSENCE only; a present-but-unreadable config is fail-closed.' }
  elseif ($vfgBrkOut -notmatch 'verify: FAIL') { Fail "15x(f) [VERIFY-CONFIG-BROKEN-MISREPORTED] a throwing _config.ps1 made verify exit non-zero, but it did not print 'verify: FAIL' - an unhandled exception is not a verdict. The failure must land in the same `$failed` accounting every other gate uses, so there is ONE verdict path and not a second convention." }
  elseif ($vfgBrkOut -match 'verify: NOT CONFIGURED') { Fail '15x(f) [VERIFY-CONFIG-BROKEN-AS-UNWIRED] a throwing _config.ps1 produced the NOT CONFIGURED verdict. Broken and unwired are different states and the third state must never absorb the first: that is exactly how an unreadable configuration would ship looking safe.' }
  elseif ($vfgEmpExit -eq 0) { Fail '15x(g) [VERIFY-CONFIG-EMPTYMSG-GREEN] a present _config.ps1 throwing an exception whose Message is EMPTY exited 0. The message is a DETAIL about the failure and must never BE the failure - store a boolean and report the message separately, or a throw carrying no text reads exactly like a clean load (T297/TD285; arm (f) throws WITH text and passed throughout).' }
  elseif ($vfgEmpOut -notmatch 'verify: FAIL') { Fail "15x(g) [VERIFY-CONFIG-EMPTYMSG-NOVERDICT] an empty-message load throw made verify exit non-zero without printing 'verify: FAIL'. Exit 1 alone is also what a CRASH produces: the first cut of T297 skipped the pending branch, fell through to the driver check, and indexed an empty array to death before the verdict. Assert the printed verdict, never the exit code alone." }
  elseif ($vfgEmpOut -match 'verify: NOT CONFIGURED') { Fail '15x(g) [VERIFY-CONFIG-EMPTYMSG-AS-UNWIRED] an empty-message load throw produced the NOT CONFIGURED verdict. After a load failure the setting is UNKNOWN, not empty, so gate 2 must be skipped entirely rather than allowed to default into the third state.' }
  elseif ($vfgAccExit -eq 0) { Fail '15x(h) [VERIFY-ACCESSOR-THROW-GREEN] Get-ScaffoldE2ECommand threw and verify exited 0. The accessor can fail on its own - a malformed field, a helper it depends on - and its failure means the same thing a load failure means: verify cannot know what it was asked to run.' }
  elseif ($vfgAccOut -notmatch 'verify: FAIL') { Fail "15x(h) [VERIFY-ACCESSOR-THROW-NOVERDICT] the accessor threw and verify exited non-zero without printing 'verify: FAIL' - it died before its own conclusion. T296 called the accessor outside any catch and measured exactly this; the call belongs inside the common failure path so one verdict path serves every failure." }
  elseif (-not $vfgCtlCalled) { Fail '15x(i) [VERIFY-MARKER-CONTROL-DEAD] the POSITIVE CONTROL failed: a config that defines the side-effecting accessor and does NOT throw did not produce the marker file. Until that works, the partial-load arm below proves nothing - a broken side effect and a correctly skipped accessor are the same observation. Fix the control before reading the arm.' }
  elseif ($vfgCtlExit -ne 0) { Fail '15x(i) [VERIFY-MARKER-CONTROL-RED] the positive-control fixture exited non-zero. Its accessor returns an empty command, so it should reach NOT CONFIGURED and exit 0; a red here means the control is measuring something other than the marker mechanism.' }
  elseif ($vfgParCalled) { Fail '15x(i) [VERIFY-ACCESSOR-CALLED-AFTER-LOAD-FAIL] a config that DEFINED the accessor and then threw still had that accessor invoked - its marker file exists. After a load failure the setting is UNKNOWN, so gate 2 must not be consulted at all: a half-loaded config is not a source of truth about what to run. This is the only fixture that can catch it, because the other load-failure fixtures throw before defining anything and the accessor is simply absent.' }
  elseif ($vfgParExit -eq 0) { Fail '15x(i) [VERIFY-PARTIAL-LOAD-GREEN] a config that defined the accessor and then threw exited 0. A load failure is a failure whether or not anything was defined before it.' }
  elseif ($vfgParOut -notmatch 'verify: FAIL') { Fail "15x(i) [VERIFY-PARTIAL-LOAD-NOVERDICT] a partially loaded config made verify exit non-zero without printing 'verify: FAIL'." }
  elseif ($vfgAbsExit -ne 0) { Fail "15x(j) [VERIFY-ABSENT-CONFIG-RED] an ABSENT _config.ps1 made verify exit non-zero. Absence is the hermetic single-file case and must keep degrading quietly - this card separates absence from FAILURE and must not collapse them the other way." }
  elseif ($vfgAbsOut -notmatch 'verify: NOT CONFIGURED') { Fail "15x(j) [VERIFY-ABSENT-CONFIG-NOVERDICT] an ABSENT _config.ps1 exited 0 but did not print 'verify: NOT CONFIGURED'. 15f(a) covers the absent-config EXIT CODE; the VERDICT TEXT on absence was asserted by nothing - the 'none' fixture has a PRESENT config returning an empty command, which is a different question." }
  else { Write-Host "  15x verify three-state verdict OK (unconfigured and ABSENT -> NOT CONFIGURED + exit 0 and no PASS; -Strict -> non-zero and still reaches the verdict; configured+green -> PASS; configured+red -> FAIL + exit 1; driver absent -> FAIL non-zero; broken config, EMPTY-MESSAGE throw, throwing ACCESSOR and PARTIAL load -> FAIL with a printed verdict, never the third state, and a partially loaded accessor is never invoked)" -ForegroundColor Green }
} finally {
  $env:PATH = $vfgOldPath
  Remove-Item -Recurse -Force $vfg -ErrorAction SilentlyContinue
}
}

# 15e2. Golden Evidence is a product contract: it must stay in the dedicated JVM
# e2e source-set and never leak into the ordinary unit-test layout.  This is
# deliberately source-level and mutation-backed; it never starts Gradle or an
# emulator during a harness diagnosis.
function Test-GoldenEvidenceIsolationContract {
  param([Parameter(Mandatory)][string]$BuildSource, [Parameter(Mandatory)][string[]]$ObservedPaths)
  $requiredPaths = @(
    'android/core/src/e2eTest/kotlin/nz/myinspection/core/e2e/GoldenEvidenceCoreE2ETest.kt',
    'android/core/src/e2eTest/kotlin/nz/myinspection/core/e2e/GoldenEvidenceCoreHarness.kt',
    'android/core/src/e2eTest/kotlin/nz/myinspection/core/e2e/GoldenEvidenceFixture.kt',
    'android/core/src/e2eTest/kotlin/nz/myinspection/core/e2e/GoldenEvidenceFixtureTest.kt',
    'android/core/src/e2eTest/kotlin/nz/myinspection/core/e2e/GoldenEvidenceTenantRedactionE2ETest.kt',
    'android/core/src/e2eTest/resources/e2e/golden-inspection-v1.json'
  )
  foreach ($path in $requiredPaths) { if ($ObservedPaths -cnotcontains $path) { return $false } }
  if (@($ObservedPaths | Where-Object {
        $_.StartsWith('android/core/src/test/kotlin/nz/myinspection/core/e2e/', [StringComparison]::Ordinal) -or
        $_.StartsWith('android/core/src/test/resources/e2e/', [StringComparison]::Ordinal)
      }).Count) { return $false }
  $requiredPatterns = @(
    '(?ms)^val e2eTest = sourceSets\.create\("e2eTest"\)\s*\{.*?^\s+resources\.srcDir\("\.\./\.\./data/templates"\)\s*$',
    '(?m)^\s+compileClasspath \+= sourceSets\.main\.get\(\)\.output\s*$',
    '(?m)^\s+runtimeClasspath \+= output \+ compileClasspath\s*$',
    '(?m)^configurations\[e2eTest\.implementationConfigurationName\]\.extendsFrom\(configurations\.testImplementation\.get\(\)\)\s*$',
    '(?m)^configurations\[e2eTest\.runtimeOnlyConfigurationName\]\.extendsFrom\(configurations\.testRuntimeOnly\.get\(\)\)\s*$',
    '(?ms)^tasks\.register<Test>\("e2eTest"\)\s*\{.*?^\s+useTestNG\(\)\s*$.*?^\}\s*$',
    '(?m)^\s+testClassesDirs = e2eTest\.output\.classesDirs\s*$',
    '(?m)^\s+classpath = e2eTest\.runtimeClasspath\s*$'
  )
  foreach ($pattern in $requiredPatterns) { if ([regex]::Matches($BuildSource, $pattern).Count -ne 1) { return $false } }
  return -not ($BuildSource -match '(?ms)(?:tasks\.)?check\s*\{[^}]*e2eTest' -or $BuildSource -match '(?ms)tasks\.named(?:<[^>]+>)?\("check"\)\s*\{[^}]*e2eTest')
}
$coreBuildPath = Join-Path $RepoRoot 'android/core/build.gradle.kts'
if (-not (Test-Path -LiteralPath $coreBuildPath -PathType Leaf)) { Fail '15e2: android/core/build.gradle.kts is absent; Golden Evidence isolation cannot be judged.' }
else {
  $coreBuildSource = Get-Content -LiteralPath $coreBuildPath -Raw
  $goldenEvidencePaths = @('android/core/src/e2eTest', 'android/core/src/test/kotlin/nz/myinspection/core/e2e', 'android/core/src/test/resources/e2e') | ForEach-Object {
    Get-ChildItem -LiteralPath (Join-Path $RepoRoot $_) -File -Recurse -ErrorAction SilentlyContinue
  } | ForEach-Object { [IO.Path]::GetRelativePath($RepoRoot, $_.FullName) -replace '\\', '/' }
  $sourceSetNameMutation = $coreBuildSource.Replace('sourceSets.create("e2eTest")', 'sourceSets.create("e2eMutant")')
  $sourceSetTaskMutation = $coreBuildSource.Replace('testClassesDirs = e2eTest.output.classesDirs', 'testClassesDirs = sourceSets.test.get().output.classesDirs')
  $defaultLayoutMutation = @($goldenEvidencePaths) + 'android/core/src/test/kotlin/nz/myinspection/core/e2e/GoldenEvidenceMutantTest.kt'
  if (-not (Test-GoldenEvidenceIsolationContract -BuildSource $coreBuildSource -ObservedPaths $goldenEvidencePaths) -or
      (Test-GoldenEvidenceIsolationContract -BuildSource $sourceSetNameMutation -ObservedPaths $goldenEvidencePaths) -or
      (Test-GoldenEvidenceIsolationContract -BuildSource $sourceSetTaskMutation -ObservedPaths $goldenEvidencePaths) -or
      (Test-GoldenEvidenceIsolationContract -BuildSource $coreBuildSource -ObservedPaths $defaultLayoutMutation)) {
    Fail '15e2: Golden Evidence isolated source-set/task or file-layout contract is missing, or a source-set/task/default-layout mutation survived.'
  } else { Write-Host '  15e2 Golden Evidence JVM Core E2E isolation/layout mutations OK' -ForegroundColor Green }
}

# 15i. TD44：远端 ship 的 git push 静默失败 → 必在 push 步 fail-fast abort（不得续跑到 gh pr view/create/merge）。
#   task.ps1:46 关 $PSNativeCommandUseErrorActionPreference → 原生命令非零不抛；push 此前无 $LASTEXITCODE 校验，静默失败后
#   流程照跑到 `gh pr merge --squash`，把本地刚过闸的产物与远端【陈旧】head 解耦、合并未评审内容（gh-bootstrap:180-184 已知此坑、ship 未防）。
#   夹具：构造能走到 push 的最小仓（评审后端 stub 过 reviewAvail 闸、账号守卫 stub 掉——与本债正交、令 push 可离线复现），
#   origin 是可 fetch 的本地 bare 仓（满足 TD84 新鲜基线前置），再用 pre-receive hook 拒绝 push → push 步确定性非零失败（离线、无网络）。断言：ship 非零退出 且 输出含 push abort token
#   （旧码：push 静默续跑 → 死在 PR 号解析、无此 token → RED；新码：push 后 throw、含 token → GREEN）。
#   Chinese token 跨子进程匹配走 UTF-8 OutputEncoding 钉法（TD31/TD34：非 UTF-8 宿主下中文字节误码致假 FAIL）。
$gitI = Get-Command git -ErrorAction SilentlyContinue
if (-not $gitI) {
  Write-Host '  15i git 未安装，跳过（离线 / 无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  $PSNativeCommandUseErrorActionPreference = $false
  $pf = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-pushfail-$PID"
  if (Test-Path $pf) { Remove-Item -Recurse -Force $pf }
  New-Item -ItemType Directory -Force $pf | Out-Null
  try {
    # 忠实拷 scripts/（同 17k）；夹具内改 _config/_guard/verify，绝不碰元仓。
    Copy-Item (Join-Path $RepoRoot 'scripts') $pf -Recurse -Force
    $cfgPF = Join-Path $pf 'scripts/_config.ps1'
    $cP = Get-Content $cfgPF -Raw
    $cP = [regex]::Replace($cP, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$pf/wt'" })     # worktree 指向 fixture，绝不碰真实 wt 根
    $cP = [regex]::Replace($cP, "GhAccount\s*=\s*'[^']*'",   { "GhAccount = 'pf'" })
    $cP = $cP.Replace("ReviewCommand = ''", "ReviewCommand = 'pwsh -NoProfile -Command exit 0'")  # 非空 → 过 reviewAvail 闸（push 前，不会真跑）.Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if (($cP -notmatch [regex]::Escape("$pf/wt")) -or ($cP -notmatch "ReviewCommand = 'pwsh")) { Fail '闸15i：fixture _config 注入失败（WorktreeRoot/ReviewCommand 行格式变了？Replace 没命中）——测的不再是 push-fail abort。' }
    Set-Content $cfgPF $cP -NoNewline -Encoding utf8
    # 账号守卫与本债正交：stub 成 no-op，令非 -Local ship 能离线走到 push（真守卫要求 github.com origin → push 必联网、非 hermetic）。
    Add-FixtureAccountGuardStub (Join-Path $pf 'scripts')
    # verify 走确定性 stub（同 15b 之理，免随机器态漂移）。
    Set-Content (Join-Path $pf 'scripts/verify.ps1') 'exit 0' -Encoding utf8
    & git -C $pf init -q
    & git -C $pf symbolic-ref HEAD refs/heads/master
    & git -C $pf config user.email 'selftest@local'
    & git -C $pf config user.name  'selftest'
    $pfOrigin = Join-Path $pf 'remote.git'
    & git init --bare -q $pfOrigin
    & git -C $pf remote add origin $pfOrigin
    New-Item -ItemType Directory -Force (Join-Path $pf 'specs/tasks') | Out-Null
    @('---', 'id: T0-PUSHFAIL', 'title: seed 15i push-fail abort', 'status: todo',
      'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - README.md', '---') -join "`n" |
      Set-Content (Join-Path $pf 'specs/tasks/T0-PUSHFAIL.md') -Encoding utf8
    & git -C $pf -c user.email='selftest@local' -c user.name='selftest' add -A 2>$null
    & git -C $pf -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'pf base' *> $null
    & git -C $pf push -q -u origin master
    & pwsh -NoProfile -File (Join-Path $pf 'scripts/task.ps1') -TaskId T0-PUSHFAIL -Phase start *> $null
    $pfWt = Join-Path $pf 'wt/T0-PUSHFAIL'
    if (-not (Test-Path $pfWt)) { Fail '闸15i：fixture start 未产出 worktree——无法验证 push-fail abort（前置失败）。' }
    else {
      Set-Content (Join-Path $pfWt 'README.md') '15i push-fail change' -Encoding utf8              # allow_paths 内真改动 → 有 commit 可 push
      $pfReject = "#!/bin/sh`nexit 1`n"
      $pfRejectPath = Join-Path $pfOrigin 'hooks/pre-receive'
      [IO.File]::WriteAllText($pfRejectPath, $pfReject, [Text.UTF8Encoding]::new($false)) # fetch 可用、push 确定性被拒
      if (-not $IsWindows) {
        & chmod +x $pfRejectPath
        if ($LASTEXITCODE -ne 0) { Fail '闸15i setup：pre-receive chmod +x 失败，Ubuntu 夹具无法保证 push 被拒。' }
      }
      # UTF-8 钉法（TD31/TD34）：子端 enc-wrap 钉 OutputEncoding、父端捕获前后就地钉+还原，防中文 token 误码假 FAIL。
      $encWrapI = Join-Path $pf 'enc-ship-15i.ps1'
      Set-Content $encWrapI 'try { [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }; & (Join-Path $PSScriptRoot "scripts/task.ps1") -TaskId T0-PUSHFAIL -Phase ship -SkipRed; exit $LASTEXITCODE' -Encoding utf8
      $prevOutI = $null
      try { $prevOutI = [Console]::OutputEncoding; [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }
      try {
        $iOut = (& pwsh -NoProfile -File $encWrapI 2>&1 | Out-String)
        $iExit = $LASTEXITCODE
      } finally {
        if ($prevOutI) { try { [Console]::OutputEncoding = $prevOutI } catch { } }
      }
      $iTail = ($iOut -replace '\s+', ' ').Trim(); if ($iTail.Length -gt 260) { $iTail = $iTail.Substring($iTail.Length - 260) }
      if ($iExit -eq 0) { Fail '闸15i：git push 失败下远端 ship 仍退出 0——push 无 $LASTEXITCODE 校验、静默续跑（TD44：可合并陈旧远端 head）。' }
      elseif ($iOut -notmatch 'SHIP-PUSH-FAIL') { Fail "Gate 15i: a failed push did not abort at the push step (no SHIP-PUSH-FAIL token) - silent continuation into gh/PR can merge an unreviewed stale head (TD44). Output tail=$iTail" }
      elseif ($iOut -match 'squash') { Fail '闸15i：push 失败后输出仍出现 squash（走到了合并步）——abort 未前置于合并（TD44 未修）。' }
      else { Write-Host '  15i push 失败 → push 步 fail-fast abort（未走到 gh/合并）OK' -ForegroundColor Green }
    }
  } finally {
    Set-Location $RepoRoot
    & git -C $pf worktree prune 2>$null
    Remove-Item -Recurse -Force $pf -ErrorAction SilentlyContinue
  }
}

# 15d2（TD60/TD-123）：范围闸「第二种子」——15d 只种了一个卡外文件证「越界必拦」，但旧匹配是**字符前缀**
# 而非**路径段前缀**：`$f -like ($_.TrimEnd('/')+'*')` 对 allow `docs/`（trim 后 "docs*"）会让 `docs2/oob.md`
# 误判「在范围内」（字符串以 "docs" 打头即匹配，"2" 不算数）；对 allow `README.md`（"README.md*"）同理会让
# `README.md.bak` 误判在范围内。二者都是「本该拦却放行」的反向漏洞，比 15d 的「一般越界」更隐蔽。另外
# allow 条目里若含 `[` 这类 `-like` 通配符特殊字符（如 `scripts/foo[bar].ps1`），旧码把它当字符类而非字面量，
# 会让这条**合法**的字面路径匹配失败、被误判越界（反方向 bug：本该放行却拦）。本闸用独立隔离夹具（自建
# git 仓+worktree，绝不碰上面 15i 的共享夹具/元仓），allow_paths=[README.md, docs/, scripts/foo[bar].ps1]，
# 变更文件=[docs2/oob.md（假阳性放行陷阱）, README.md.bak（同类陷阱）, scripts/foo[bar].ps1（字面量陷阱）]，
# 断言 ship -Local 必在范围闸 block（gate=scope）、账本详情须点名两个假阳性文件、且不得点名字面量括号文件
# （证其被正确识别为「在范围内」，未被误拦）。
$gitD2 = Get-Command git -ErrorAction SilentlyContinue
if (-not $gitD2) {
  Write-Host '  15d2 git 未安装，跳过（离线 / 无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  $PSNativeCommandUseErrorActionPreference = $false
  $sd2 = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-scope-seed-$PID"
  if (Test-Path $sd2) { Remove-Item -Recurse -Force $sd2 }
  New-Item -ItemType Directory -Force $sd2 | Out-Null
  try {
    Copy-Item (Join-Path $RepoRoot 'scripts') $sd2 -Recurse -Force   # 忠实拷 scripts/（同 15i/17k）
    $cfgD2 = Join-Path $sd2 'scripts/_config.ps1'
    $cD2 = Get-Content $cfgD2 -Raw
    $cD2 = [regex]::Replace($cD2, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$sd2/wt'" })  # 隔离，绝不碰真实 wt 根
    $cD2 = [regex]::Replace($cD2, "GhAccount\s*=\s*'[^']*'",   { "GhAccount = 'sd2'" })
    # 15d3（TD-202）复用本夹具会走到 R3（范围闸被改名绕过后 ship 续跑到评审），故注入 pass-stub 评审后端
    # （确定性+离线，绝不调真 codex——它可能在 PATH 上、联网、非确定；同 15b 之理）。15d2 自身在范围闸即 block、
    # 不到 R3，故此注入不改 15d2 行为，仅令 15d3 的 RED 路径确定性退 0。stub 进 base 提交、worktree 继承、不入 ship diff。
    $revStubD2 = Join-Path $sd2 'review-stub.ps1'
    $revStubBodyD2 = @'
[Console]::In.ReadToEnd() | Out-Null
'{"verdict":"pass","reasons":[]}' | Set-Content $env:REVIEW_OUT -Encoding utf8
'@
    Set-Content $revStubD2 $revStubBodyD2 -Encoding utf8
    $cD2 = $cD2.Replace("ReviewCommand = ''", "ReviewCommand = 'pwsh -NoProfile -File $($revStubD2 -replace '\\', '/')'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if ($cD2 -notmatch 'review-stub') { Fail '闸15d3：pass-stub 评审后端未注入 15d2 夹具 _config（ReviewCommand 行格式变了？.Replace 没命中）——否则 15d3 的 RED 路径会撞真 codex（非确定/联网）。' }
    if ($cD2 -notmatch [regex]::Escape("$sd2/wt")) { Fail '闸15d2：fixture _config 注入失败（WorktreeRoot 行格式变了？Replace 没命中）——测的不再是范围闸段级匹配。' }
    Set-Content $cfgD2 $cD2 -NoNewline -Encoding utf8
    Set-Content (Join-Path $sd2 'scripts/verify.ps1') 'exit 0' -Encoding utf8   # verify 走确定性 stub（同 15b/15i 之理）
    # 15d3 的 RED 路径（范围闸被改名绕过后 ship 续跑到 R3）：review.ps1 从基线读 docs/QUALITY-RUBRIC.md，缺则 fail-closed
    # block（非因范围）。种一份最小 rubric（内容任意非空即可，pass-stub 后端忽略正文），令 R3 得 pass、RED 确定性退 0。
    New-Item -ItemType Directory -Force (Join-Path $sd2 'docs') | Out-Null
    Set-Content (Join-Path $sd2 'docs/QUALITY-RUBRIC.md') '# 15d3 fixture stub rubric（非空即可，pass-stub 后端忽略正文）' -Encoding utf8
    & git -C $sd2 init -q
    & git -C $sd2 symbolic-ref HEAD refs/heads/master
    & git -C $sd2 config user.email 'selftest@local'
    & git -C $sd2 config user.name  'selftest'
    New-Item -ItemType Directory -Force (Join-Path $sd2 'specs/tasks') | Out-Null
    @('---', 'id: T0-SCOPESEED', 'title: seed 15d2 scope segment-anchor', 'status: todo',
      'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:',
      '  - README.md', '  - docs/', '  - scripts/foo[bar].ps1', '---') -join "`n" |
      Set-Content (Join-Path $sd2 'specs/tasks/T0-SCOPESEED.md') -Encoding utf8
    & git -C $sd2 -c user.email='selftest@local' -c user.name='selftest' add -A 2>$null
    & git -C $sd2 -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'sd2 base' *> $null
    & pwsh -NoProfile -File (Join-Path $sd2 'scripts/task.ps1') -TaskId T0-SCOPESEED -Phase start *> $null
    $sd2Wt = Join-Path $sd2 'wt/T0-SCOPESEED'
    if (-not (Test-Path $sd2Wt)) { Fail '闸15d2：fixture start 未产出 worktree——无法验证范围闸段级匹配（前置失败）。' }
    else {
      New-Item -ItemType Directory -Force (Join-Path $sd2Wt 'docs2') | Out-Null
      Set-Content (Join-Path $sd2Wt 'docs2/oob.md') '15d2 假阳性放行陷阱：allow docs/ 不该匹配 docs2/' -Encoding utf8
      Set-Content (Join-Path $sd2Wt 'README.md.bak') '15d2 假阳性放行陷阱：allow README.md 不该匹配 README.md.bak' -Encoding utf8
      # -LiteralPath（非位置式 -Path）：路径含 `[bar]`，位置式 -Path 会被当 wildcard 解析，因未匹配到既有文件
      # 而令 FileSystem provider 无法确定 -Encoding 这个动态参数（报「找不到参数 Encoding」）——用 -LiteralPath 按字面路径处理。
      Set-Content -LiteralPath (Join-Path $sd2Wt 'scripts/foo[bar].ps1') -Value '# 15d2 字面量陷阱：allow 条目本身含 [ ]，须字面匹配自身，不得被误判越界' -Encoding utf8
      $ledgerD2 = Join-Path $sd2 '_local/effectiveness-ledger.jsonl'
      & pwsh -NoProfile -File (Join-Path $sd2 'scripts/task.ps1') -TaskId T0-SCOPESEED -Phase ship -Local -SkipRed *> $null
      $d2Exit = $LASTEXITCODE
      $d2Ledger = if (Test-Path $ledgerD2) { Get-Content $ledgerD2 -Raw } else { '' }
      $d2Rec = $d2Ledger -match '"gate":"scope"'
      # 只取 gate=scope 那一行（可能有其他闸的行）比对 detail 内容。
      $d2ScopeLine = ($d2Ledger -split "`n" | Where-Object { $_ -match '"gate":"scope"' } | Select-Object -Last 1)
      if ($d2Exit -eq 0) { Fail '闸15d2：卡外改动（docs2/oob.md、README.md.bak）存在时 ship -Local 仍退出 0——范围闸字符前缀匹配把「docs2/oob.md」/「README.md.bak」误判为在 allow_paths（docs/、README.md）范围内放行（TD60/TD-123：应为段级前缀匹配）。' }
      elseif (-not $d2Rec) { Fail '闸15d2：ship 非零退出但效果账本无 gate=scope 记录（Add-CatchRecord 丢失 / 在别的闸先 block，掩盖了本该测的范围闸）。' }
      elseif ($d2ScopeLine -notmatch [regex]::Escape('docs2/oob.md')) { Fail "闸15d2：范围闸拦了但账本 gate=scope 详情未点名 docs2/oob.md——allow docs/ 未正确拒绝 docs2/（段级前缀匹配缺失，字符前缀假阳性放行未堵）。`n账本行=$d2ScopeLine" }
      elseif ($d2ScopeLine -notmatch [regex]::Escape('README.md.bak')) { Fail "闸15d2：范围闸拦了但账本 gate=scope 详情未点名 README.md.bak——allow README.md 未正确拒绝 README.md.bak（段级前缀匹配缺失，字符前缀假阳性放行未堵）。`n账本行=$d2ScopeLine" }
      elseif ($d2ScopeLine -match 'foo\[bar\]') { Fail "闸15d2：范围闸把 scripts/foo[bar].ps1 误判越界（账本详情点名了它）——allow 条目本身含 [ ] 时须字面匹配自身，不得被当成 -like 通配符字符类（TD60/TD-123）。`n账本行=$d2ScopeLine" }
      else { Write-Host '  15d2 范围闸段级匹配 OK（docs2/oob.md·README.md.bak 正确拒绝、含 [ ] 的字面量 allow 条目正确放行、账本 gate=scope 记录完整）' -ForegroundColor Green }

      # 15d3（TD-202）：范围闸被 git **改名探测**绕过。一次提交删 A 路径文件、又在 B 路径增高相似文件时，
      # `git diff --name-only` 把删+增折叠成单条 rename 记录、**只印目标 B**——被删的 origin A 不出现，
      # 于是 $changed 缺 A、范围闸看不到卡外文件离场。复用上面的 15d2 隔离夹具（allow docs/）：先把 worktree
      # reset 回基线（清 15d2 已提交的卡外文件、范围闸 base=master），再把卡外 scripts/handoff.ps1 纯移动
      # （字节一致 → 100% 相似 → 必被识别为 R100 rename）到卡内 docs/handoff.ps1，跑 ship -Local。
      #   GREEN（task.ps1 带 -c diff.renames=false）：origin scripts/handoff.ps1 独立现身 → 范围闸 block + 账本点名它。
      #   RED（未加）：diff 只印卡内 docs/handoff.ps1 → 范围闸放行 → ship 退 0（评审走注入的 pass-stub、许可/密钥
      #   在干净夹具下过，故确定性退 0）。
      $mvSrcD3 = Join-Path $sd2Wt 'scripts/handoff.ps1'
      if (-not (Test-Path $mvSrcD3)) { Fail '闸15d3：夹具缺 scripts/handoff.ps1，无法构造改名越界种子（前置失败）——15d2 拷 scripts/ 的行为变了？' }
      else {
        & git -C $sd2Wt reset --hard master *> $null   # 清 15d2 已提交到 T0-SCOPESEED 的卡外文件，worktree 回基线（scope base=master）
        & git -C $sd2Wt clean -fd *> $null
        $dstDirD3 = Join-Path $sd2Wt 'docs'
        New-Item -ItemType Directory -Force $dstDirD3 | Out-Null
        Move-Item -LiteralPath $mvSrcD3 (Join-Path $dstDirD3 'handoff.ps1')   # 纯移动：字节一致 → git 识别为 R100 rename
        Remove-Item -LiteralPath $ledgerD2 -ErrorAction SilentlyContinue      # 隔离账本：只看本次 ship 新增的 gate=scope 记录
        & pwsh -NoProfile -File (Join-Path $sd2 'scripts/task.ps1') -TaskId T0-SCOPESEED -Phase ship -Local -SkipRed *> $null
        $d3Exit = $LASTEXITCODE
        $d3Ledger = if (Test-Path $ledgerD2) { Get-Content $ledgerD2 -Raw } else { '' }
        $d3Rec = $d3Ledger -match '"gate":"scope"'
        $d3ScopeLine = ($d3Ledger -split "`n" | Where-Object { $_ -match '"gate":"scope"' } | Select-Object -Last 1)
        if ($d3Exit -eq 0) { Fail '闸15d3：把卡外 scripts/handoff.ps1 改名（git rename）进卡内 docs/ 后 ship -Local 仍退出 0——范围闸的 git diff --name-only 未禁用改名探测，rename 记录只印卡内目标 docs/handoff.ps1、卡外 origin scripts/handoff.ps1 被折叠隐藏，范围闸遂放行卡外文件离场（TD-202：应给该 diff 加 -c diff.renames=false 让 origin 独立现身）。' }
        elseif (-not $d3Rec) { Fail '闸15d3：ship 非零退出但效果账本无 gate=scope 记录——被别的闸（许可/密钥/评审）先 block 掩盖了本该测的范围闸；无法证明是范围闸拦下改名 origin。' }
        elseif ($d3ScopeLine -notmatch [regex]::Escape('scripts/handoff.ps1')) { Fail "闸15d3：范围闸拦了但账本 gate=scope 详情未点名 origin scripts/handoff.ps1——改名探测仍在，范围闸看到的是卡内目标 docs/handoff.ps1 而非卡外 origin（TD-202 未修）。`n账本行=$d3ScopeLine" }
        else { Write-Host '  15d3 范围闸抗改名绕过 OK（卡外 scripts/handoff.ps1 改名进 docs/ 被范围闸看穿、账本 gate=scope 点名 origin、ship 被拦）' -ForegroundColor Green }
      }

      # 15d4. [SHIP-SCOPE-CARD-BINDING] (T241/TD247): WHICH COPY of the card the ship scope gate takes its
      # allow_paths from. Gates 15d, 15d2 and 15d3 all drive the MATCHER, and none of them can tell a
      # base-card read from a main-checkout read, because in every one of those cases the two copies are
      # byte-identical. The gate diffs against the base ref, so its standard has to come from that same ref:
      # otherwise an UNCOMMITTED edit to the card in the main checkout sets the merge standard, leaves no
      # trace in history, and - since sessions share a checkout - can be a PEER session's edit rather than
      # the shipper's. Before T241 the code was the single outlier in a tree where eight faces, this gate's
      # own throw text among them, already taught the base-card binding.
      # THREE arms over the 15d2 fixture, and arm b is what stops the fix degenerating into "block everything":
      #     a  base card narrow, main-checkout copy WIDENED and never committed => BLOCK + ledger gate=scope
      #     b  the same widening COMMITTED on the base branch, same tree        => SHIPS
      #     c  the card gone from the base ref while the checkout still holds it => fail-closed under its OWN
      #        sentinel, never the "declares no allow_paths" one, which names a repair that would not work
      if (-not $fail) {
        $cardRelD4 = 'specs/tasks/T0-SCOPESEED.md'
        $cardD4 = Join-Path $sd2 $cardRelD4
        $narrowD4 = (Get-Content $cardD4 -Raw)
        # Derived from the fixture's own card, never a second copy of it: a literal here would silently
        # stop matching the card 15d2 actually seeds, and this arm would then widen nothing.
        # The widening is `specs/` and NOT a fresh name like `docs2/`, and that is measured rather than
        # stylistic: ship validates the MAIN CHECKOUT's card with check-cards BEFORE it reaches this gate,
        # and `docs2/` is a [CARD-PATH-NEARMISS] of the existing `docs/` (TD166), so the seed would block at
        # the card-check leg and this arm would prove nothing about the scope gate. `specs/` resolves.
        $wideD4 = [regex]::Replace($narrowD4, '(?m)^  - docs/\r?$', "  - docs/`n  - specs/")
        if ($wideD4 -eq $narrowD4) { Fail '15d4 precondition [SCOPE-BIND-PRE]: no widenable `  - docs/` line found in the fixture card''s allow_paths (did 15d2''s card literal change?). The main-checkout widening seed cannot be built, so all three cases below would prove nothing.' }
        else {
          & git -C $sd2Wt reset --hard master *> $null   # back to baseline: drop the rename 15d3 committed, so the scope gate sees base=master
          & git -C $sd2Wt clean -fd *> $null
          Set-Content (Join-Path $sd2Wt 'specs/oob.md') '15d4: outside the BASE card allow_paths; only the uncommitted main-checkout widening would admit it' -Encoding utf8
          # The widening lands in the MAIN CHECKOUT's working file and is deliberately NEVER committed.
          # That is the whole seed: it is the copy a main-checkout binding reads and the copy no ref carries.
          Set-Content $cardD4 $wideD4 -Encoding utf8
          Remove-Item -LiteralPath $ledgerD2 -ErrorAction SilentlyContinue
          $d4aOut = (& pwsh -NoProfile -File (Join-Path $sd2 'scripts/task.ps1') -TaskId T0-SCOPESEED -Phase ship -Local -SkipRed 2>&1 | Out-String)
          $d4aExit = $LASTEXITCODE
          $d4aLedger = if (Test-Path $ledgerD2) { Get-Content $ledgerD2 -Raw } else { '' }
          $d4aScopeLine = ($d4aLedger -split "`n" | Where-Object { $_ -match '"gate":"scope"' } | Select-Object -Last 1)
          if ($d4aExit -eq 0) { Fail "15d4(a) [SCOPE-BIND-A]: widening the card's allow_paths in the MAIN CHECKOUT WORKING FILE, committed to no ref at all, admitted the out-of-scope specs/oob.md and ship -Local exited 0. The scope gate is taking allow_paths from that working file while judging a diff taken from the base ref. The consequence is not academic: the widening never enters history, reverting the file afterwards leaves no trace, and in a shared checkout it may not even be the shipper's own edit. Fix = read the card from the base ref via git show (TD247, ruled base-ref binding).`nOutput=$d4aOut" }
          elseif ($d4aOut -notmatch [regex]::Escape('[SHIP-SCOPE-BLOCK]')) { Fail "15d4(a) [SCOPE-BIND-A]: ship exited non-zero but printed no [SHIP-SCOPE-BLOCK] sentinel, so something else stopped it (DoD, verify, licence, secrets, review). Reading that as "the scope gate blocked on the base card" is a false green (L95: non-zero is not the same as this assertion firing).`nOutput=$d4aOut" }
          elseif ($d4aScopeLine -notmatch [regex]::Escape('specs/oob.md')) { Fail "15d4(a) [SCOPE-BIND-A]: the scope gate blocked but the gate=scope ledger detail does not name specs/oob.md, so what it stopped was not this seed.`nLedger row=$d4aScopeLine" }
          else { Write-Host '  15d4(a) OK: an uncommitted main-checkout widening is not honoured (base card rules -> block + [SHIP-SCOPE-BLOCK] + ledger names specs/oob.md)' -ForegroundColor Green }
        }

        # b. The repair the gate's own throw text names ("widen allow_paths on main first") has to actually
        #    work, on the SAME tree arm a blocked - otherwise the fix is indistinguishable from a gate that
        #    blocks unconditionally, and 15w3 is the precedent for pairing a block with its way out.
        if (-not $fail) {
          & git -C $sd2 add -- $cardRelD4 *> $null
          & git -C $sd2 -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'widen the seeded card allow_paths on the base branch, in its own commit' *> $null
          $d4bOut = (& pwsh -NoProfile -File (Join-Path $sd2 'scripts/task.ps1') -TaskId T0-SCOPESEED -Phase ship -Local -SkipRed 2>&1 | Out-String)
          $d4bExit = $LASTEXITCODE
          if ($d4bExit -ne 0) { Fail "15d4(b) [SCOPE-BIND-B]: with the same widening landed on the base branch as its own commit, the same tree still exited non-zero from ship -Local ($d4bExit). The repair the gate itself names - widen allow_paths on main first - does not work, which makes the gate an unsolvable block rather than a decision point.`nOutput=$d4bOut" }
          else { Write-Host '  15d4(b) OK: the widening has a way out (same tree ships once the widening is committed to the base branch)' -ForegroundColor Green }
        }

        # c. A card the base ref does not carry. This state is REACHED by the base-ref binding and by nothing
        #    else, so it needs its own sentinel: reporting it as "the card declares no allow_paths" sends the
        #    author to edit a file that is already correct, when the repair is to commit it to the base branch.
        if (-not $fail) {
          & git -C $sd2 rm -q --cached -- $cardRelD4 *> $null   # off the ref, still on disk in the checkout
          & git -C $sd2 -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'take the seeded card off the base ref while the checkout keeps it' *> $null
          Set-Content (Join-Path $sd2Wt 'README.md') '15d4(c): an in-scope edit, so nothing but the card binding can decide this ship' -Encoding utf8
          $d4cOut = (& pwsh -NoProfile -File (Join-Path $sd2 'scripts/task.ps1') -TaskId T0-SCOPESEED -Phase ship -Local -SkipRed 2>&1 | Out-String)
          $d4cExit = $LASTEXITCODE
          # The repair is asserted against the FOLDED copy (T259/TD258): this output is a child process's
          # stderr, so the child rendered the ErrorRecord and wrapped it at its own console width - 80 on
          # ubuntu, wider on windows - and the break landed mid-phrase, reddening this arm on Linux only
          # for three consecutive commits. Diagnostics keep the raw text, so a human still sees what ran.
          $d4cFlat = Get-ScaffoldUnwrappedErrorText -Text $d4cOut
          if ($d4cExit -eq 0) { Fail "15d4(c) [SCOPE-BIND-C]: ship -Local exited 0 with the card absent from the base ref. The scope gate could not read a standard and let the ship through anyway, which is undecidable treated as permission - the exact face fail-closed exists to cover.`nOutput=$d4cOut" }
          elseif ($d4cFlat -notmatch [regex]::Escape('[SHIP-SCOPE-CARD-ABSENT]')) { Fail "15d4(c) [SCOPE-BIND-C]: ship exited non-zero for a card absent from the base ref but printed no [SHIP-SCOPE-CARD-ABSENT] sentinel of its own. Reusing the empty-allow_paths message sends the author to fix a card that is already correct, when the real repair is to commit it to the base branch.`nOutput=$d4cOut" }
          # The sentinel alone is not the contract (R3 round 1): printing the token and then falling through
          # to the generic throw would satisfy it while still naming the wrong repair. Assert the repair
          # TEXT is present and the generic allow_paths diagnostic is ABSENT - acceptance item 3 says
          # "distinct from", and only the negative arm can show distinctness.
          elseif ($d4cFlat -notmatch [regex]::Escape('commit specs/tasks/T0-SCOPESEED.md to')) { Fail "15d4(c) [SCOPE-BIND-C]: the sentinel printed but the repair was not named (commit the card to the base branch). A sentinel says WHAT is wrong; only the repair says what to do about it, and without it this fail-closed is a dead end.`nOutput=$d4cOut" }
          elseif ($d4cFlat -match [regex]::Escape('[SHIP-SCOPE-ALLOW-EMPTY]')) { Fail "gate 15d4(c) [SCOPE-BIND-C]: an absent card also printed the generic [SHIP-SCOPE-ALLOW-EMPTY] diagnostic. The two states need opposite repairs - commit the card, versus fill in a field - so reporting both is the same as distinguishing neither, and acceptance item 3 asks for exactly that distinction.`nOutput=$d4cOut" }
          else { Write-Host '  15d4(c) OK: a card absent from the base ref fails closed under its own [SHIP-SCOPE-CARD-ABSENT] sentinel, names the repair, and does not blur into the generic empty-allow_paths diagnostic' -ForegroundColor Green }
        }

        if (-not $fail) { Write-Host '  15d4 [SHIP-SCOPE-CARD-BINDING] OK: the scope gate takes allow_paths from the base ref (a), the widening-on-base repair it names really ships (b), and a card missing from that ref fails closed under its own sentinel (c)' -ForegroundColor Green }
      }
    }
  } finally {
    Set-Location $RepoRoot
    & git -C $sd2 worktree prune 2>$null
    Remove-Item -Recurse -Force $sd2 -ErrorAction SilentlyContinue
  }
}

# 15s. （TD93 item①）：独立范围检查器 check-scope.ps1 —— 「已推送状态的手工恢复」序列（docs/DEVOPS-WORKFLOW.md）
# 绕过 ship 主路，而 CI 没有范围闸（TD89 根因），故那一步范围核对是该平面上范围闸的唯一承载；它此前是散文
# （人眼比对 git diff 输出、没有退出码）。本闸钉住它已成可跑命令，且与 ship 打**同一枚判定核**（scripts/_scope.ps1）。
# 夹具＝临时 git 仓 + 直接跑 check-scope.ps1（不经 ship，故快、无网络、不建 worktree）。case 分两类
# （**刻意不写 case 总数**：数字与实现会各自漂移，此前已因此被 R3 抓过两次；要清点就读下面的字母）：
#   【判定正确性】a 在界（exit 0 且印 PASS）· b 越界（点名 README.md 与 docs2/oob.md——后者是段级前缀陷阱：
#     匹配器退回旧字符前缀写法即随 15d2 一起变红，是「两个入口打同一枚核」的证据）· c 基线卡 allow_paths 写成
#     行内 flow 致取值 0 项 → 不可判须 fail-closed 且修法指向补齐（与闸 10d 不同面：10d 在**建卡期**拒行内写法，
#     本 case 证**取值失效时**的后置防线）· m 远端模式（= 已推送恢复这条**主路径**）的正题：越界须 BLOCK 且点名、
#     全在界须 PASS，并覆盖被接受的 origin/<base> 写法在两种模式下归一到同一判定。
#   【信任边界 · 全部来自 codex R3 实测的真 fail-open】d 自基线（base 解析成卡分支自己 → 空 diff 误印 PASS）·
#     e 缺省工作树缺失时**静默回退主检出** · f 该检出 HEAD 不在卡分支上（把主检出传进来即 master 比 master；
#     判定尖端必须按**卡 id** 锚定）· g -Path 指向无关仓库 · h 被审分支**自行扩自己的 allow_paths**（判定标准
#     必须取自受信基线那份卡）· i git revision 语法（`^{commit}`/`~0`/`@{0}`）把卡分支伪装成基线 ·
#     j 指向同一提交的**别名分支**作基线（证明按提交身份兜底那道独立于名字）· k 本地与远端卡分支分叉（k2 另证
#     其修法**真能解开**）· n 绑定族：`-ExpectTip`/`-ExpectBase` 的相符/不符/空值/唯一缩写/解析不出/位数边界
#     （离线检查器看不出 origin/* 陈旧，「判过的 == 要合的」须由调用方传 OID 机检；基线那侧决定采信哪份卡的
#     allow_paths）· p 判定对象钉在**不可变 sha** 而非可变引用名（接线断言，锁 TOCTOU）· q 被审分支把**检查器
#     自己**换掉时，跑受信检出那份仍须 BLOCK · r 权威恢复配方须核 PR 的 baseRefName（判定前/合并前各一次）。
#   信任边界类 **一律断言 ASCII 哨兵**而非只断言非零：夹具仓的多条错误路径都会碰巧非零，只断言非零会让守卫
#   被摘掉后仍「碰巧绿」（vacuous）——变异 C/D/E/G/I 已实测坐实这一点。
$gitS = Get-Command git -ErrorAction SilentlyContinue
if (-not $gitS) {
  Write-Host '  15s git 未安装，跳过（离线 / 无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  $PSNativeCommandUseErrorActionPreference = $false
  $ss = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-checkscope-$PID"
  $ssOther = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-checkscope-other-$PID"
  foreach ($d in @($ss, $ssOther)) {
    if (Test-Path $d) { Remove-Item -Recurse -Force $d }
    New-Item -ItemType Directory -Force $d | Out-Null
  }
  try {
    Copy-Item (Join-Path $RepoRoot 'scripts') $ss -Recurse -Force   # 忠实拷 scripts/（同 15d2/15i）
    # 注入隔离 WorktreeRoot（绝不碰真实 wt 根）。该目录**故意不创建**：case e 据此走「缺省工作树缺失」路径。
    $ssCfg = Join-Path $ss 'scripts/_config.ps1'
    $ssCfgText = [regex]::Replace((Get-Content $ssCfg -Raw), "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$ss/wt'" })
    if ($ssCfgText -notmatch [regex]::Escape("$ss/wt")) { Fail '闸15s：夹具 _config 的 WorktreeRoot 注入失败（行格式变了？）——case e 会去碰真实 wt 根，拒绝继续。' }
    Set-Content $ssCfg $ssCfgText -NoNewline -Encoding utf8
    $ssCheck = Join-Path $ss 'scripts/check-scope.ps1'
    $ssCard = Join-Path $ss 'specs/tasks/T0-SCOPECHK.md'
    # 写夹具卡：allow 段由调用方给（case h 用它把分支上的卡改宽、case c 用它把**基线**上的卡改成行内 flow）。
    $ssWriteCard = {
      param($CardPath, $AllowLines)
      (@('---', 'id: T0-SCOPECHK', 'title: seed 15s standalone scope checker', 'status: todo',
          'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"') + $AllowLines + @('---')) -join "`n" |
        Set-Content $CardPath -Encoding utf8
    }
    $ssCommit = { param($Msg) & git -C $ss add -A 2>$null; & git -C $ss commit -q -m $Msg *> $null }
    # 跑一次检查器，回 @{Out;Exit}。默认参数＝文档里那条（-Base master -Path <仓> -Local）。
    $ssRunExe = {
      param($Exe, $CsArgs)
      $o = (& pwsh -NoProfile -File $Exe @CsArgs 2>&1 | Out-String)
      return [pscustomobject]@{ Out = $o; Exit = $LASTEXITCODE }
    }
    $ssRun = { param($CsArgs) return (& $ssRunExe $ssCheck $CsArgs) }
    $ssStd = @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-Local')
    # 判定行 / 修法行取值器：只在**判定行**上比对，不在整份输出上比对——check-scope 在判定前会先打印改动清单，
    # 那份清单里本就含 docs2/oob.md，对整份输出做 -match 会让「误放行 docs2/」的变异存活（实测：变异 B 下
    # 15d2 已红而本闸仍绿）。同 15d2 只取账本 gate=scope 那一行之理。
    $ssLine = { param($Text, $Pat) (($Text -split '\r?\n') | Where-Object { $_ -match $Pat } | Select-Object -Last 1) }

    & git -C $ss init -q
    & git -C $ss symbolic-ref HEAD refs/heads/master
    & git -C $ss config user.email 'selftest@local'
    & git -C $ss config user.name  'selftest'
    New-Item -ItemType Directory -Force (Join-Path $ss 'specs/tasks') | Out-Null
    & $ssWriteCard $ssCard @('allow_paths:', '  - docs/')
    & $ssCommit 'ss base'
    & git -C $ss checkout -q -b T0-SCOPECHK
    # 无关仓库（case g）：有提交、但**没有**本卡的分支引用。
    & git -C $ssOther init -q
    & git -C $ssOther symbolic-ref HEAD refs/heads/master   # 与 $ss 同名基线：否则 case g 会先卡在「基线不可解析」而非 [SCOPE-NOTIP]，断错了面
    & git -C $ssOther config user.email 'selftest@local'
    & git -C $ssOther config user.name  'selftest'
    Set-Content (Join-Path $ssOther 'unrelated.md') '15s case g：无关仓库' -Encoding utf8
    & git -C $ssOther add -A 2>$null
    & git -C $ssOther commit -q -m 'other base' *> $null

    # ── a 在界 ──
    New-Item -ItemType Directory -Force (Join-Path $ss 'docs') | Out-Null
    Set-Content (Join-Path $ss 'docs/a.md') '15s case a：卡内改动，须判在界' -Encoding utf8
    & $ssCommit 'ss a'
    $rA = & $ssRun $ssStd
    if ($rA.Exit -ne 0) { Fail "闸15s(a)：卡内改动（docs/a.md ∈ allow docs/）时 check-scope.ps1 仍非零退出（$($rA.Exit)）——独立范围检查器误拦合法改动，恢复序列会被它挡死。`n输出=$($rA.Out)" }
    elseif ($rA.Out -notmatch '\[SCOPE-PASS\]') { Fail "闸15s(a)：check-scope.ps1 退 0 但输出无 PASS 文案——判定结论未被打印，人/子代理无从确认它真跑过判定。`n输出=$($rA.Out)" }

    # ── b 越界（含段级前缀陷阱 docs2/oob.md）──
    New-Item -ItemType Directory -Force (Join-Path $ss 'docs2') | Out-Null
    Set-Content (Join-Path $ss 'README.md') '15s case b：卡外改动，须判越界' -Encoding utf8
    Set-Content (Join-Path $ss 'docs2/oob.md') '15s case b：allow docs/ 不该匹配 docs2/（段级前缀陷阱）' -Encoding utf8
    & $ssCommit 'ss b'
    $rB = & $ssRun $ssStd
    $sBlockB = & $ssLine $rB.Out '\[SCOPE-BLOCK\]'
    if ($rB.Exit -eq 0) { Fail "闸15s(b)：卡外改动（README.md、docs2/oob.md ∉ allow docs/）时 check-scope.ps1 仍退 0——独立范围检查器放行越界，恢复序列那一步等同没有闸。`n输出=$($rB.Out)" }
    elseif (-not $sBlockB) { Fail "闸15s(b)：check-scope.ps1 非零退出但没有打印越界判定行——无法证明它是因范围判定而拦（可能挂在别的不可判分支上）。`n输出=$($rB.Out)" }
    elseif ($sBlockB -notmatch [regex]::Escape('README.md')) { Fail "闸15s(b)：越界判定行未点名 README.md——不点名则调用者不知该撤出哪个文件（修法不可执行）。`n判定行=$sBlockB" }
    elseif ($sBlockB -notmatch [regex]::Escape('docs2/oob.md')) { Fail "闸15s(b)：越界判定行未点名 docs2/oob.md——allow docs/ 被当字符前缀而非路径段前缀（TD60/TD-123 回归），且证明本检查器与 ship 范围闸未共用 _scope.ps1 那枚判定核。`n判定行=$sBlockB" }

    # ── q 被审分支把**检查器自己**换掉（codex R3 r6 #1）：check-scope.ps1 / _scope.ps1 按**相对自身位置**加载，
    #    从被审工作树里跑就等于让被审分支自带的那份判定自己——把匹配器改成恒 PASS 即可绕过这条恢复路径上唯一的
    #    范围闸（同 task.ps1 的 L86：相位命令只在主检出跑）。故正确形态是**跑受信检出那份、用 -Path 指被审树**。
    #    q1 先证投毒确实有效（否则 q2 是 vacuous），q2 证受信那份不受其影响。 ──
    Copy-Item $ssCheck "$ssCheck.bak" -Force
    Copy-Item (Join-Path $ss 'scripts/_scope.ps1') (Join-Path $ss 'scripts/_scope.ps1.bak') -Force
    Set-Content $ssCheck 'exit 0' -Encoding utf8                                                         # 被审分支：入口直接恒 PASS
    Set-Content (Join-Path $ss 'scripts/_scope.ps1') 'function Get-ScaffoldOutOfScopePath { return @() }' -Encoding utf8   # 判定核：恒无越界
    $rQ1 = & $ssRun $ssStd                                                                               # 分支侧那份
    $trustedCheck = Join-Path $PSScriptRoot 'check-scope.ps1'                                            # 受信主检出那份
    $rQ2 = & $ssRunExe $trustedCheck $ssStd
    $sBlockQ2 = & $ssLine $rQ2.Out '\[SCOPE-BLOCK\]'
    Copy-Item "$ssCheck.bak" $ssCheck -Force                                                             # 立刻解毒，勿影响后续 case
    Copy-Item (Join-Path $ss 'scripts/_scope.ps1.bak') (Join-Path $ss 'scripts/_scope.ps1') -Force
    Remove-Item "$ssCheck.bak", (Join-Path $ss 'scripts/_scope.ps1.bak') -Force -ErrorAction SilentlyContinue
    if ($rQ1.Exit -ne 0) { Fail "闸15s(q1)：把被审分支的 check-scope.ps1 换成 `exit 0` 后它竟没退 0——投毒无效，q2 证明不了任何事（vacuous 前置）。`n输出=$($rQ1.Out)" }
    elseif ($rQ2.Exit -eq 0) { Fail "闸15s(q2)：跑**受信主检出**那份 checker（-Path 指被审树）时，仍被被审分支替换掉的检查器/判定核带成退 0——恢复路径上唯一的范围闸可被被审分支自行拆除。`n输出=$($rQ2.Out)" }
    elseif (-not $sBlockQ2 -or $sBlockQ2 -notmatch [regex]::Escape('README.md')) { Fail "闸15s(q2)：受信 checker 非零退出但未给出点名 README.md 的越界判定行——判定没落到范围上。`n判定行=$sBlockQ2" }

    # ── d 自基线（codex R3 r1）：base 退化成卡分支自己 → 空 diff 误印 PASS。task.ps1 早有 L86-BASE 守卫，新入口须同守 ──
    $rD1 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'T0-SCOPECHK', '-Path', $ss, '-Local')   # 显式误传
    $rD2 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Path', $ss)                                     # 省略 -Base（HEAD 在卡分支上）且走远端基线路径
    if ($rD1.Exit -eq 0) { Fail "闸15s(d1)：显式 -Base <卡 id> 时 check-scope.ps1 仍退 0——基线退化成分支自己、diff 为空，越界改动被空过并误印 PASS（假绿比没有检查器更坏）。`n输出=$($rD1.Out)" }
    elseif ($rD1.Out -notmatch [regex]::Escape('[SCOPE-SELFBASE]')) { Fail "闸15s(d1)：非零退出但不是自基线守卫拦的（无 [SCOPE-SELFBASE] 哨兵）——挂在了别的失败面上，本闸对该 fail-open 无覆盖。`n输出=$($rD1.Out)" }
    if ($rD2.Exit -eq 0) { Fail "闸15s(d2)：在卡自己的分支上省略 -Base 时 check-scope.ps1 仍退 0——缺省基线探测取到当前分支＝卡分支（codex R3 r1 实测的原始 fail-open）。`n输出=$($rD2.Out)" }
    elseif ($rD2.Out -notmatch [regex]::Escape('[SCOPE-SELFBASE]')) { Fail "闸15s(d2)：非零退出但不是自基线守卫拦的（无 [SCOPE-SELFBASE] 哨兵）——夹具仓无 origin，很可能只是「基线引用不可解析」碰巧非零，对自基线 fail-open 仍无覆盖（vacuous）。`n输出=$($rD2.Out)" }

    # ── e 缺省工作树缺失（codex R3 r2 #1）：旧码在此静默回退主检出 → base=master vs HEAD=master → 0 改动误印 PASS ──
    $rE = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Local')   # 不传 -Path；注入的 WorktreeRoot 下无该工作树
    if ($rE.Exit -eq 0) { Fail "闸15s(e)：缺省工作树不存在时 check-scope.ps1 仍退 0——静默回退主检出、拿基线比自己得 0 改动并误印 PASS，被审分支的越界改动一个没看。`n输出=$($rE.Out)" }
    elseif ($rE.Out -notmatch [regex]::Escape('[SCOPE-NOWT]')) { Fail "闸15s(e)：非零退出但不是缺省工作树守卫拦的（无 [SCOPE-NOWT] 哨兵）——静默回退主检出这条 fail-open 仍无覆盖（vacuous）。`n输出=$($rE.Out)" }

    # ── g -Path 指向无关仓库：那里没有本卡的分支引用，须 fail-closed，不得拿别人的树蒙混成 PASS ──
    $rG = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ssOther, '-Local')
    if ($rG.Exit -eq 0) { Fail "闸15s(g)：-Path 指向无关仓库时 check-scope.ps1 仍退 0——判定对象没有绑到卡 id，检查了别人的树还报 PASS。`n输出=$($rG.Out)" }
    elseif ($rG.Out -notmatch [regex]::Escape('[SCOPE-NOTIP]')) { Fail "闸15s(g)：非零退出但不是尖端锚定守卫拦的（无 [SCOPE-NOTIP] 哨兵）——可能只是基线不可解析碰巧非零，对「检查错仓库」无覆盖（vacuous）。`n输出=$($rG.Out)" }

    # ── h 被审分支自行扩自己的 allow_paths（codex R3 r2 #2）：判定标准须取自**基线**那份卡 ──
    & $ssWriteCard $ssCard @('allow_paths:', '  - docs/', '  - README.md', '  - docs2/')
    & $ssCommit 'ss h：分支把自己的 allow_paths 扩宽'
    $rH = & $ssRun $ssStd
    $sBlockH = & $ssLine $rH.Out '\[SCOPE-BLOCK\]'
    if ($rH.Exit -eq 0) { Fail "闸15s(h)：被审分支把自己卡的 allow_paths 扩宽后 check-scope.ps1 就放行了——判定标准取自被审检出而非受信基线，恢复序列的范围闸可被分支自行绕过。`n输出=$($rH.Out)" }
    elseif (-not $sBlockH -or $sBlockH -notmatch [regex]::Escape('README.md') -or $sBlockH -notmatch [regex]::Escape('docs2/oob.md')) { Fail "闸15s(h)：分支扩宽 allow_paths 后越界判定行不再点名 README.md/docs2/oob.md——基线那份卡未被采信。`n判定行=$sBlockH" }

    # ── i 用 git revision 语法把卡分支伪装成基线（codex R3 r3 #1 实测三种写法全绕过按名字比对的旧守卫）──
    # 三种写法都解析到卡分支尖端 → 空 diff → 误印 PASS。逐个列黑名单是打地鼠，故守卫改为「只放行纯分支名」；
    # 断言 [SCOPE-BADBASE] 而非只断言非零——否则守卫被摘掉后，它们会被下游别的错误路径碰巧拦住而假通过。
    foreach ($spell in @('T0-SCOPECHK^{commit}', 'T0-SCOPECHK~0', 'T0-SCOPECHK@{0}')) {
      $rI = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', $spell, '-Path', $ss, '-Local')
      if ($rI.Exit -eq 0) { Fail "闸15s(i)：-Base '$spell' 时 check-scope.ps1 仍退 0——git revision 语法把卡分支自己伪装成基线，空 diff 被误印 PASS（按字面量比名字的守卫拦不住）。`n输出=$($rI.Out)" }
      elseif ($rI.Out -notmatch [regex]::Escape('[SCOPE-BADBASE]')) { Fail "闸15s(i)：-Base '$spell' 非零退出但不是纯名校验拦的（无 [SCOPE-BADBASE] 哨兵）——该写法仍会走进 git 解析，本 case 对该绕过无覆盖（vacuous）。`n输出=$($rI.Out)" }
    }

    # ── j 另起一个指向同一提交的分支名作基线：纯名校验放行，须由**提交身份**兜底（codex R3 r3 #1 的一般形）──
    & git -C $ss branch basealias T0-SCOPECHK 2>$null
    $rJ = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'basealias', '-Path', $ss, '-Local')
    if ($rJ.Exit -eq 0) { Fail "闸15s(j)：-Base 指向与卡分支同一提交的别名分支时 check-scope.ps1 仍退 0——只按名字比对拦不住「换个名字的同一个提交」，空 diff 误印 PASS。`n输出=$($rJ.Out)" }
    elseif ($rJ.Out -notmatch [regex]::Escape('[SCOPE-SELFBASE]')) { Fail "闸15s(j)：非零退出但不是自基线守卫拦的（无 [SCOPE-SELFBASE] 哨兵）——按提交身份兜底那道不在，写法一变即绕过。`n输出=$($rJ.Out)" }

    # ── k 远端模式下本地与远端卡分支分叉（codex R3 r3 #2）：旧码恒优先本地 ref，fetch 后本地陈旧就会判旧提交、
    #    把新推上去的越界改动整段忽略——假 PASS 恰好发生在本闸唯一要守的「已推送状态」平面上 ──
    $ssTipOld = "$(& git -C $ss rev-parse T0-SCOPECHK~1 2>$null)".Trim()
    & git -C $ss update-ref refs/remotes/origin/master (& git -C $ss rev-parse master) 2>$null
    & git -C $ss update-ref refs/remotes/origin/T0-SCOPECHK $ssTipOld 2>$null
    $rK = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss)   # 远端模式（不加 -Local）
    if ($rK.Exit -eq 0) { Fail "闸15s(k)：本地与远端卡分支分叉时 check-scope.ps1 仍退 0——判定尖端未随模式绑定（远端模式却判了本地那棵/或反之），已推送的越界改动可被陈旧 ref 掩盖。`n输出=$($rK.Out)" }
    elseif ($rK.Out -notmatch [regex]::Escape('[SCOPE-TIPDIVERGE]')) { Fail "闸15s(k)：非零退出但不是分叉守卫拦的（无 [SCOPE-TIPDIVERGE] 哨兵）——对「本地陈旧/远端更新」这条假 PASS 无覆盖（vacuous）。`n输出=$($rK.Out)" }
    # k2 修法可执行性（codex R3 r5 #3）：分叉守卫给的修法必须**真能解开**。`git fetch` 只动远端跟踪引用、
    # 不动本地分支，故若修法只说 fetch，「本地陈旧 / 远端更新」这个最常见的恢复态会被永久卡死。此处照修法
    # ① 让本地跟上远端（等价于 `merge origin/<id>` 的快进），断言分叉守卫**放行**并给出真正的范围判定。
    $ssLocalBeforeK = "$(& git -C $ss rev-parse T0-SCOPECHK)".Trim()
    & git -C $ss update-ref refs/heads/T0-SCOPECHK $ssTipOld 2>$null   # 本地跟上远端（remedy ① 的效果）
    $rK2 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss)
    $sBlockK2 = & $ssLine $rK2.Out '\[SCOPE-BLOCK\]'
    if ($rK2.Out -match [regex]::Escape('[SCOPE-TIPDIVERGE]')) { Fail "闸15s(k2)：照修法让本地与远端一致后，分叉守卫**仍**拦——修法解不开它，「本地陈旧/远端更新」的恢复态被永久卡死（codex R3 r5 #3 即此）。`n输出=$($rK2.Out)" }
    elseif ($rK2.Exit -eq 0) { Fail "闸15s(k2)：两侧一致后该棵树含卡外改动（README.md）却退 0——分叉解开后没有落到真正的范围判定上。`n输出=$($rK2.Out)" }
    elseif (-not $sBlockK2 -or $sBlockK2 -notmatch [regex]::Escape('README.md')) { Fail "闸15s(k2)：两侧一致后未给出点名 README.md 的越界判定。`n判定行=$sBlockK2" }
    & git -C $ss update-ref refs/heads/T0-SCOPECHK $ssLocalBeforeK 2>$null   # 还原本地尖端
    & git -C $ss update-ref -d refs/remotes/origin/T0-SCOPECHK 2>$null   # 收回夹具态，勿影响后续 case
    & git -C $ss update-ref -d refs/remotes/origin/master 2>$null

    # ── p 判定对象钉在**不可变 sha** 上而非可变引用名（codex R3 r5 #2）：本闸校验过 sha 之后若仍用 $baseRef/$tipRef
    #    去求 diff、读基线卡，另一进程一次 fetch 就能让「打印并被 -ExpectTip 校验过的 sha」与「实际判定的树 /
    #    实际采信的 allow_paths」错开（TOCTOU）。真并发无法在夹具里确定性复现，故这里锁**接线**：两处消费点
    #    必须吃 $baseShaFull/$tipShaFull，且不得再出现吃可变引用的形态。同闸 10d(接线) 之理。 ──
    $csText = Get-Content $ssCheck -Raw
    if ($csText -notmatch 'Get-ScaffoldChangedPath\s+-GitDir\s+\$Path\s+-BaseRef\s+\$baseShaFull\s+-TipRef\s+\$tipShaFull') { Fail '闸15s(p)：check-scope.ps1 求改动清单时未吃钉住的 $baseShaFull/$tipShaFull——并发 fetch 可令校验过的 sha 与实际判定的树错开（TOCTOU）。' }
    elseif ($csText -notmatch [regex]::Escape('"${baseShaFull}:${cardInBase}"')) { Fail '闸15s(p)：check-scope.ps1 读基线卡时未吃钉住的 $baseShaFull——diff 与 allow_paths 可能来自两个不同的基线提交。' }
    elseif ($csText -match 'Get-ScaffoldChangedPath[^\r\n]*-BaseRef\s+\$baseRef') { Fail '闸15s(p)：check-scope.ps1 仍把可变引用名 $baseRef 喂给改动清单求值——须改吃已解析的 sha。' }
    elseif ($csText -match [regex]::Escape('show "${baseRef}:')) { Fail '闸15s(p)：check-scope.ps1 仍用可变引用名 $baseRef 读基线卡——须改吃已解析的 sha。' }

    # ── m 远端模式的**正题**（codex R3 r4 #3）：上面 a/b/h 全走 -Local，远端模式此前只被「期望失败」的守卫
    #    间接碰到过，**主路径（已推送恢复）没有自证的 happy-path / 越界 BLOCK 覆盖**。此处把两侧 origin 引用
    #    对齐到与本地一致（无分叉），跑出 PASS 与 BLOCK 两个正面结论；顺带覆盖被显式接受的 origin/<base> 写法
    #    在**两种模式**下都归一到同一判定（r4 #2 的回归：曾被再拼一次成 origin/origin/master）。 ──
    $ssTipSaved = "$(& git -C $ss rev-parse T0-SCOPECHK)".Trim()   # 显式存尖端，末尾据此还原（不依赖 reflog @{n}）
    & git -C $ss update-ref refs/remotes/origin/master (& git -C $ss rev-parse master) 2>$null
    & git -C $ss update-ref refs/remotes/origin/T0-SCOPECHK $ssTipSaved 2>$null
    $rM1 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss)              # 远端模式 · 当前分支含卡外改动 ⇒ 须 BLOCK
    $sBlockM1 = & $ssLine $rM1.Out '\[SCOPE-BLOCK\]'
    if ($rM1.Exit -eq 0) { Fail "闸15s(m1)：远端模式下卡外改动（README.md、docs2/oob.md）仍退 0——「已推送状态」这条主路径没有真正拦住越界。`n输出=$($rM1.Out)" }
    elseif (-not $sBlockM1 -or $sBlockM1 -notmatch [regex]::Escape('README.md') -or $sBlockM1 -notmatch [regex]::Escape('docs2/oob.md')) { Fail "闸15s(m1)：远端模式越界判定行未点名 README.md/docs2/oob.md。`n判定行=$sBlockM1" }
    $rM2 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'origin/master', '-Path', $ss)       # 同上，但用被接受的 origin/<base> 写法
    if ($rM2.Exit -ne $rM1.Exit -or (($rM2.Out -match '\[SCOPE-BLOCK\]') -ne ($rM1.Out -match '\[SCOPE-BLOCK\]'))) { Fail "闸15s(m2)：-Base 'origin/master' 与 -Base 'master' 在远端模式下结论不一致（$($rM2.Exit) vs $($rM1.Exit)）——origin/ 前缀未被归一（曾被再拼成 refs/remotes/origin/origin/master）。`n输出=$($rM2.Out)" }
    $rM3a = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-Local')          # 同一仓库态下的本地基准
    $rM3 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'origin/master', '-Path', $ss, '-Local')    # -Local + origin/ 前缀：须与上一条同结论
    if ($rM3.Exit -ne $rM3a.Exit) { Fail "闸15s(m3)：-Local 配 -Base 'origin/master' 与配 -Base 'master' 结论不一致（$($rM3.Exit) vs $($rM3a.Exit)）——前缀把模式选择劫持了，违背 -Local 契约（取哪一侧只应由 -Local 决定）。`n输出=$($rM3.Out)" }
    # m4 happy-path：把卡外文件挪进 allow 范围内（改基线卡不行——那会污染后续 case），改用一条只动 docs/ 的新分支尖端。
    & git -C $ss update-ref refs/remotes/origin/T0-SCOPECHK (& git -C $ss rev-parse T0-SCOPECHK~2) 2>$null   # 回到只有 docs/a.md 那一提交
    & git -C $ss update-ref refs/heads/T0-SCOPECHK (& git -C $ss rev-parse T0-SCOPECHK~2) 2>$null            # 两侧对齐，避免撞分叉守卫
    $rM4 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss)
    if ($rM4.Exit -ne 0) { Fail "闸15s(m4)：远端模式下全部改动都在 allow docs/ 内时仍非零退出（$($rM4.Exit)）——主路径的 happy-path 被误拦，恢复序列会被它挡死。`n输出=$($rM4.Out)" }
    elseif ($rM4.Out -notmatch '\[SCOPE-PASS\]') { Fail "闸15s(m4)：远端模式退 0 但未印 PASS 文案。`n输出=$($rM4.Out)" }

    # ── n -ExpectTip 绑定（codex R3 r4 #1）：离线检查器看不出 origin/* 陈旧，故「判过的树 == 要合的树」
    #    必须由调用方把 PR head 传进来机检；只印告示不算 fail-closed 证据 ──
    $ssTipNow = "$(& git -C $ss rev-parse T0-SCOPECHK)".Trim()
    $ssMasterOid = "$(& git -C $ss rev-parse master)".Trim()
    $rN1 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-ExpectTip', $ssTipNow)
    if ($rN1.Exit -ne 0) { Fail "闸15s(n1)：-ExpectTip 传入与判定尖端**相同**的 sha 时仍非零退出（$($rN1.Exit)）——正确绑定被误拦，恢复序列没法用。`n输出=$($rN1.Out)" }
    # 不符用例必须传一个**在本仓真能解析、但不是尖端**的 OID（此处用 master 的）——全零 OID 会停在
    # 「解析不出唯一提交」那一支，根本走不到 `$full -ne $ActualSha` 那句身份比对，把身份比对整句删掉也照样绿
    # （codex R3 r10 #1 实测：这正是本卡第四次同类 vacuous 断言）。
    $rN2 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-ExpectTip', $ssMasterOid)
    if ($rN2.Exit -eq 0) { Fail "闸15s(n2)：-ExpectTip 传入**可解析但不同**的 sha 时 check-scope.ps1 仍退 0——身份比对没生效，「检查过的树」与「要合并的树」可以是两棵而闸毫无察觉。`n输出=$($rN2.Out)" }
    elseif ($rN2.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15s(n2)：非零退出但不是尖端绑定守卫拦的（无 [SCOPE-TIPMISMATCH] 哨兵）——该绑定无覆盖（vacuous）。`n输出=$($rN2.Out)" }
    elseif ($rN2.Out -notmatch [regex]::Escape('judged=')) { Fail "闸15s(n2)：不符文案未打印 judged=/expect= 两个 OID——无法证明拦下它的是身份比对而非解析失败那一支。`n输出=$($rN2.Out)" }
    # n3/n4/n5（codex R3 r6 #2）：-ExpectTip 曾用 StartsWith 比前缀——那只证明「前缀巧合」，证明不了提交身份，
    # 歧义缩写更会被当成命中。现改为**先解析成完整 OID 再整串相等**：唯一缩写照收（n3）、解析不出唯一提交的
    # 一律拒（n4，含不存在与歧义），并锁住接线本体（n5）——真歧义缩写在小夹具里无法确定性构造，故以接线断言补足。
    $rN3 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-ExpectTip', $ssTipNow.Substring(0, 8))
    if ($rN3.Exit -ne 0) { Fail "闸15s(n3)：-ExpectTip 传**唯一缩写**（8 位）时被拒（$($rN3.Exit)）——缩写应解析成完整 OID 后判等，而非一律拒收。`n输出=$($rN3.Out)" }
    $rN4 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-ExpectTip', 'deadbee')
    if ($rN4.Exit -eq 0) { Fail "闸15s(n4)：-ExpectTip 传一个解析不出提交的十六进制串时仍退 0——绑定形同虚设。`n输出=$($rN4.Out)" }
    elseif ($rN4.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15s(n4)：非零退出但不是尖端绑定守卫拦的（无 [SCOPE-TIPMISMATCH] 哨兵）。`n输出=$($rN4.Out)" }
    elseif ($csText -match [regex]::Escape('$tipShaFull.StartsWith($ExpectTip')) { Fail '闸15s(n5)：check-scope.ps1 仍用 StartsWith 比 -ExpectTip 前缀——前缀相同证明不了提交身份，歧义缩写会被当成命中。' }
    elseif ($csText -notmatch [regex]::Escape('rev-parse --verify --quiet "$Raw^{commit}"')) { Fail '闸15s(n5)：check-scope.ps1 未把绑定值经 git rev-parse --verify 解析成唯一提交——歧义缩写将无法被识别。' }
    # n6/n7（codex R3 r7 #1/#3）：**显式传入空值**必须 fail-closed。恢复配方里这个值来自 gh/git 的输出，
    # 一旦那步失败就是空串——若按真假值判（`if ($ExpectTip)`），绑定会被静默关掉、闸照印 [SCOPE-PASS]，
    # 而这恰恰是「本该强制的绑定」最容易失效的路径。故按 $PSBoundParameters.ContainsKey 判，空/空白一律拒。
    $rN6 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-ExpectTip', '')
    if ($rN6.Exit -eq 0) { Fail "闸15s(n6)：显式传 -ExpectTip '' 时 check-scope.ps1 仍退 0——空值被当成「没传」，强制绑定被静默关掉（gh 失败即产生此情形）。`n输出=$($rN6.Out)" }
    elseif ($rN6.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15s(n6)：非零退出但不是绑定守卫拦的（无 [SCOPE-TIPMISMATCH] 哨兵）——空值 fail-open 无覆盖（vacuous）。`n输出=$($rN6.Out)" }
    # n7：-ExpectBase 钉基线那一侧（决定采信哪份卡的 allow_paths）——陈旧 origin/<base> 会让判定按旧标准走。
    $ssBaseNow = "$(& git -C $ss rev-parse master)".Trim()
    $rN7 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-Local', '-ExpectBase', $ssBaseNow)
    if ($rN7.Exit -ne 0) { Fail "闸15s(n7)：-ExpectBase 传入与实际基线**相同**的 sha 时仍非零退出（$($rN7.Exit)）——正确绑定被误拦，恢复序列没法用。`n输出=$($rN7.Out)" }
    elseif ($rN7.Out -notmatch '\[SCOPE-PASS\]') { Fail "闸15s(n7)：-ExpectBase 正确绑定下退 0 但未印 [SCOPE-PASS]——判定结论未被打印。`n输出=$($rN7.Out)" }
    # 同 n2：不符用例传**可解析但不是基线**的 OID（此处用卡分支尖端），才走得到身份比对那句。
    $rN8 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-Local', '-ExpectBase', $ssTipNow)
    if ($rN8.Exit -eq 0) { Fail "闸15s(n8)：-ExpectBase 传入**可解析但不同**的 sha 时仍退 0——基线那一侧没被钉住，陈旧 origin/<base> 可让判定采信旧卡的 allow_paths。`n输出=$($rN8.Out)" }
    elseif ($rN8.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15s(n8)：非零退出但不是绑定守卫拦的（无 [SCOPE-TIPMISMATCH] 哨兵）。`n输出=$($rN8.Out)" }
    elseif ($rN8.Out -notmatch [regex]::Escape('judged=')) { Fail "闸15s(n8)：不符文案未打印 judged=/expect= 两个 OID——无法证明拦下它的是身份比对而非解析失败那一支。`n输出=$($rN8.Out)" }
    $rN9 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-Local', '-ExpectBase', '')
    if ($rN9.Exit -eq 0) { Fail "闸15s(n9)：显式传 -ExpectBase '' 时仍退 0——空值被当成「没传」（同 n6 之理，git rev-parse 失败即产生此情形）。`n输出=$($rN9.Out)" }
    elseif ($rN9.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15s(n9)：非零退出但不是绑定守卫拦的（无 [SCOPE-TIPMISMATCH] 哨兵）。`n输出=$($rN9.Out)" }
    # n10/n11（codex R3 r8 #2）：最小位数边界。帮助/校验/文案三处曾各说各的（7 / 4 / 7），现统一为 **7**——
    # 边界两侧各测一次，防再次漂移：7 位（唯一缩写）须收，6 位须拒。
    $rN10 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-ExpectTip', $ssTipNow.Substring(0, 7))
    if ($rN10.Exit -ne 0) { Fail "闸15s(n10)：-ExpectTip 传 7 位（声明的最小位数）唯一缩写时被拒（$($rN10.Exit)）——帮助与校验的下限不一致。`n输出=$($rN10.Out)" }
    $rN11 = & $ssRun @('-TaskId', 'T0-SCOPECHK', '-Base', 'master', '-Path', $ss, '-ExpectTip', $ssTipNow.Substring(0, 6))
    if ($rN11.Exit -eq 0) { Fail "闸15s(n11)：-ExpectTip 传 6 位（低于声明的最小位数）时仍退 0——校验下限比帮助宣称的松。`n输出=$($rN11.Out)" }
    elseif ($rN11.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15s(n11)：非零退出但不是绑定守卫拦的（无 [SCOPE-TIPMISMATCH] 哨兵）。`n输出=$($rN11.Out)" }

    # ── r 恢复配方须核 PR 的 baseRefName（codex R3 r8 #1）：只钉 base 的 sha 不够——PR 被 retarget 到别的
    #    基线分支时会「按 A 判、往 B 合」，而 --match-head-commit 只绑 head、绑不到基线。该核对发生在 gh 侧
    #    （本脚本不碰网络），故这里锁**权威配方文本**：判定前与合并前各须有一次 baseRefName 核对 + fail-closed。──
    # 断言必须**锚到可执行命令行**，不能只数关键词出现次数（codex R3 r9 #1）：本闸周围的散文/注释里本就写着
    # `baseRefName`、`--match-head-commit` 等字样，只数出现次数的话，把那几条真正的 fail-closed 命令整段删掉
    # 也照样绿——那正是本卡反复在别处踩过的 vacuous 断言。故逐条锚定：行首 `> ` + 真实命令形态。
    $rcvDoc = Get-Content (Join-Path $RepoRoot 'docs/DEVOPS-WORKFLOW.md') -Raw
    $rcvGuards = @(
      @{ Name = '判定前核 baseRefName'; Pat = '(?m)^>\s*if \(\$LASTEXITCODE -ne 0 -or \$prBase -ne .+\{ throw' },
      # Codex r5: deterministic diagnostics may stay manual, but final delivery must re-enter task ship so
      # workflow/run-attempt/PR/jobs identity and the final base/head snapshots remain one shared contract.
      @{ Name = '受保护的最终交付接续'; Pat = '(?m)^>\s*pwsh -NoProfile -File scripts\\task\.ps1 -TaskId <id> -Phase ship -Base <base>\s*$' },
      @{ Name = '接续非零阻断 cleanup'; Pat = '(?m)^>\s*if \(\$LASTEXITCODE -ne 0\) \{ throw ''protected ship resume failed; preserve the worktree/PR and do not cleanup'' \}\s*$' },
      # check-scope 之后必须**立刻**查退出码：PowerShell 原生命令非零不中断，而紧随其后的说明用 git 命令
      # 一执行就会把 $LASTEXITCODE 覆盖掉，BLOCK 遂被后续 review/merge 当成没发生（codex R3 r10 #2）。
      @{ Name = '范围闸非零即中止'; Pat = '(?m)^>\s*if \(\$LASTEXITCODE -ne 0\) \{ throw .*范围闸' }
    )
    foreach ($g in $rcvGuards) {
      if ($rcvDoc -notmatch $g.Pat) { Fail "闸15s(r)：DEVOPS-WORKFLOW 的已推送恢复配方缺可执行的「$($g.Name)」命令行（只在散文里提到不算）。" }
    }
    $rcvLastResort = [regex]::Match($rcvDoc, '(?s)\*\*已 push 状态的手工最后手段.*?> ```powershell(?<body>.*?)> ```').Groups['body'].Value
    if (-not $rcvLastResort) { Fail '闸15s(r)：无法定位手工最后手段的可执行块。' }
    elseif ($rcvLastResort -match '(?m)^>\s*(?:pwsh .*review\.ps1|gh pr checks|gh pr merge)\b') { Fail '闸15s(r)：手工最后手段仍暴露 review/checks/merge 裸命令，绕过 task ship 的完整精确 CI 身份与终局快照。' }
    elseif ($rcvLastResort -match '(?m)^>\s*pwsh -NoProfile -File scripts\\task\.ps1 .* -NoAutoMerge\b') { Fail '闸15s(r)：最终交付接续仍带 -NoAutoMerge，只会再次暂停而不会进入共享合并腿。' }
    $rcvClaude = Get-Content (Join-Path $RepoRoot 'CLAUDE.md') -Raw
    $rcvLoop = Get-Content (Join-Path $RepoRoot '.claude/skills/task-loop/SKILL.md') -Raw
    if ($rcvClaude -notmatch '\[SHIP-MANUAL-RESUME\].*fresh R3.*workflow/run-attempt/PR/jobs') { Fail '闸15s(r)：CLAUDE 范围恢复入口未声明最终交付须按 [SHIP-MANUAL-RESUME] 进入 fresh 精确身份 ship。' }
    elseif ($rcvClaude -match '合并配 `gh pr merge') { Fail '闸15s(r)：CLAUDE 仍把裸 gh pr merge 当手工恢复的最终交付。' }
    if ($rcvLoop -notmatch '\[SHIP-MANUAL-RESUME\].*fresh 重跑同一 ship.*workflow/run-attempt/PR/jobs') { Fail '闸15s(r)：task-loop 未把 -NoAutoMerge 后续定义为 fresh protected ship。' }
    elseif ($rcvLoop -notmatch '同一次连续 ship 内只跑一次.*fresh 受保护 ship，须重新评审') { Fail '闸15s(r)：task-loop 的 L15 指针仍会被读成禁止暂停后 fresh ship 重评审。' }
    # 那条「说明判据」的 git diff 必须是**注释掉的**：它一旦可执行就会覆盖掉范围闸的 $LASTEXITCODE（同上）。
    if ($rcvDoc -match '(?m)^>\s*git -c core\.quotepath=false') { Fail '闸15s(r)：恢复配方里那条说明用的 git diff 未被注释掉——它会执行并覆盖范围闸的 $LASTEXITCODE，令 BLOCK 被后续步骤忽略。' }
    # 收回夹具态：把分支尖端还原到进本段前存下的 sha、删掉临造的远端跟踪引用，后续 f/c 仍按原样跑
    & git -C $ss update-ref refs/heads/T0-SCOPECHK $ssTipSaved 2>$null
    & git -C $ss update-ref -d refs/remotes/origin/T0-SCOPECHK 2>$null
    & git -C $ss update-ref -d refs/remotes/origin/master 2>$null
    if ("$(& git -C $ss rev-parse T0-SCOPECHK)".Trim() -ne $ssTipSaved) { Fail '闸15s：m/n 段结束后未把卡分支尖端还原到进段前的 sha——后续 f/c 测的将不是原来那棵树。' }

    # ── f 该检出的 HEAD 不在卡分支上（codex R3 r2 #1 的原始复现）：把主检出传进来即 master 比 master ──
    & git -C $ss checkout -q master
    $rF = & $ssRun $ssStd
    $sBlockF = & $ssLine $rF.Out '\[SCOPE-BLOCK\]'
    if ($rF.Exit -eq 0) { Fail "闸15s(f)：被检查检出的 HEAD 切到 master 后 check-scope.ps1 就退 0 了——判定尖端跟着该检出的 HEAD 走（master 比 master 得 0 改动），而非按卡 id 锚定到卡分支；把主检出传进来即可让越界分支蒙混过关。`n输出=$($rF.Out)" }
    elseif (-not $sBlockF -or $sBlockF -notmatch [regex]::Escape('README.md')) { Fail "闸15s(f)：HEAD 不在卡分支上时越界判定行未点名 README.md——尖端未按卡 id 锚定。`n判定行=$sBlockF" }

    # ── c 基线那份卡的 allow_paths 写成行内 flow（块式取值器 0 项）→ 不可判须 fail-closed（此刻 HEAD 已在 master 上）──
    & $ssWriteCard $ssCard @('allow_paths: [docs/]')
    & $ssCommit 'ss c：基线卡改成行内 flow'
    $rC = & $ssRun $ssStd
    $sFixC = & $ssLine $rC.Out '\[SCOPE-FIX\]'
    if ($rC.Exit -eq 0) { Fail "闸15s(c)：基线卡 allow_paths 写成行内 flow（块式取值器解析为 0 项）时 check-scope.ps1 仍退 0——取值失效被当成「无越界」放行（fail-open）；不可判须 fail-closed。`n输出=$($rC.Out)" }
    elseif ($rC.Out -notmatch [regex]::Escape('[SCOPE-UNDECIDABLE]')) { Fail "闸15s(c)：check-scope.ps1 非零退出但未自称「不可判」——allow_paths 取值失效被误报成别的失败面，调用者会去查错方向。`n输出=$($rC.Out)" }
    elseif (-not $sFixC -or $sFixC -notmatch [regex]::Escape('allow_paths')) { Fail "闸15s(c)：不可判时的「修法：」一行未指向补齐 allow_paths——调用者无从知道该补什么（闸门失败信息须自带修法）。`n输出=$($rC.Out)" }
    # 文案按 case 名列举、**不写条数**（数字会与实现各自漂移——本卡已因此被 R3 抓过两次）。
    else { Write-Host '  15s 独立范围检查器 OK（判定正确性 a/b/c/m：在界 · 越界点名 · 段级前缀陷阱 · 基线卡取值失效 fail-closed · 远端模式主路径 PASS 与 BLOCK 且 origin/<base> 两模式归一 · 信任边界 d/i/j 自基线与其伪装写法（SELFBASE·BADBASE）· e 缺省工作树缺失 NOWT · g 无关仓库 NOTIP · k/k2 本地远端分叉 TIPDIVERGE 且修法可解 · n 绑定族 TIPMISMATCH（tip/base × 相符·不符·空值·缩写·位数边界）· h 分支自扩 allow_paths 不被采信 · f 尖端按卡 id 锚定不随 HEAD 漂移 · p 判定钉不可变 sha 的接线 · q 换掉检查器自身仍 BLOCK · r 恢复配方核 baseRefName）' -ForegroundColor Green }
  } finally {
    Set-Location $RepoRoot
    Remove-Item -Recurse -Force $ss -ErrorAction SilentlyContinue
    Remove-Item -Recurse -Force $ssOther -ErrorAction SilentlyContinue
  }
}

# 15o. （TD80/TD-262 · T21-LICENSE-GATE-WT）：ship 的商用许可闸此前调用【主检出】那份 check-licenses.ps1
# （Join-Path $RepoRoot ...），不像 verify.ps1/check-secrets.ps1 那样调【工作树自带】那份（Join-Path $Wt ...）。
# 卡通过 uv add/npm install 新增的依赖只存在于工作树（-Phase start 在其内 bootstrap 隔离环境），主检出扫不到——
# 闸报「PASS（无禁用许可）」是假阳性 commercial-safe 信号。独立隔离夹具（自建 git 仓+worktree，绝不碰共享
# 15i/15d2/元仓）：主检出与工作树各放一份不同的 check-licenses.ps1 stub——主检出恒 exit 0（模拟「看起来干净」），
# 工作树恒 exit 1（模拟「工作树新增了违禁许可依赖」）。
#   RED（未修，调用点仍是 $RepoRoot）：ship 只看到主检出的 exit 0 stub → 许可闸放行 → ship 续跑到 R3（经注入的
#     pass-stub 评审后端确定性退 0，本地合并完成）——证明真实 bug：违禁依赖漏判、假阳性 PASS。
#   GREEN（已修，调用点改 $Wt）：ship 看到工作树的 exit 1 stub → 许可闸拦、账本记 gate=license、ship 非零退出。
$gitO = Get-Command git -ErrorAction SilentlyContinue
if (-not $gitO) {
  Write-Host '  15o git 未安装，跳过（离线 / 无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  $PSNativeCommandUseErrorActionPreference = $false
  $so = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-license-gate-seed-$PID"
  if (Test-Path $so) { Remove-Item -Recurse -Force $so }
  New-Item -ItemType Directory -Force $so | Out-Null
  try {
    Copy-Item (Join-Path $RepoRoot 'scripts') $so -Recurse -Force   # 忠实拷 scripts/（同 15d2/15i）
    $cfgO = Join-Path $so 'scripts/_config.ps1'
    $cO = Get-Content $cfgO -Raw
    $cO = [regex]::Replace($cO, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$so/wt'" })   # 隔离，绝不碰真实 wt 根
    $cO = [regex]::Replace($cO, "GhAccount\s*=\s*'[^']*'",   { "GhAccount = 'so15o'" })
    # RED 路径（许可闸误放行）会续跑到 R3，注入确定性 pass-stub 评审后端（同 15d2 之理，绝不调真 codex）。
    $revStubO = Join-Path $so 'review-stub.ps1'
    $revStubBodyO = @'
[Console]::In.ReadToEnd() | Out-Null
'{"verdict":"pass","reasons":[]}' | Set-Content $env:REVIEW_OUT -Encoding utf8
'@
    Set-Content $revStubO $revStubBodyO -Encoding utf8
    $cO = $cO.Replace("ReviewCommand = ''", "ReviewCommand = 'pwsh -NoProfile -File $($revStubO -replace '\\', '/')'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if ($cO -notmatch 'review-stub') { Fail '闸15o：pass-stub 评审后端未注入夹具 _config（ReviewCommand 行格式变了？.Replace 没命中）——RED 路径会撞真 codex（非确定/联网）。' }
    if ($cO -notmatch [regex]::Escape("$so/wt")) { Fail '闸15o：fixture _config 注入失败（WorktreeRoot 行格式变了？Replace 没命中）——测的不再是隔离夹具。' }
    Set-Content $cfgO $cO -NoNewline -Encoding utf8
    Set-Content (Join-Path $so 'scripts/verify.ps1') 'exit 0' -Encoding utf8              # verify 走确定性 stub（同 15b/15d2/15i）
    Set-Content (Join-Path $so 'scripts/check-licenses.ps1') 'exit 0' -Encoding utf8      # 主检出侧 stub：恒「干净」
    New-Item -ItemType Directory -Force (Join-Path $so 'docs') | Out-Null
    Set-Content (Join-Path $so 'docs/QUALITY-RUBRIC.md') '# 15o fixture stub rubric（非空即可，pass-stub 后端忽略正文）' -Encoding utf8
    & git -C $so init -q
    & git -C $so symbolic-ref HEAD refs/heads/master
    & git -C $so config user.email 'selftest@local'
    & git -C $so config user.name  'selftest'
    New-Item -ItemType Directory -Force (Join-Path $so 'specs/tasks') | Out-Null
    @('---', 'id: T0-LICENSESEED', 'title: seed 15o license gate worktree-scan', 'status: todo',
      'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:',
      '  - scripts/check-licenses.ps1', '---') -join "`n" |
      Set-Content (Join-Path $so 'specs/tasks/T0-LICENSESEED.md') -Encoding utf8
    & git -C $so -c user.email='selftest@local' -c user.name='selftest' add -A 2>$null
    & git -C $so -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'so base' *> $null
    & pwsh -NoProfile -File (Join-Path $so 'scripts/task.ps1') -TaskId T0-LICENSESEED -Phase start *> $null
    $soWt = Join-Path $so 'wt/T0-LICENSESEED'
    if (-not (Test-Path $soWt)) { Fail '闸15o：fixture start 未产出 worktree——无法验证许可闸扫描根（前置失败）。' }
    else {
      Set-Content (Join-Path $soWt 'scripts/check-licenses.ps1') 'exit 1' -Encoding utf8   # 工作树侧 stub：恒「有违禁依赖」
      $ledgerO = Join-Path $so '_local/effectiveness-ledger.jsonl'
      Remove-Item -LiteralPath $ledgerO -ErrorAction SilentlyContinue
      & pwsh -NoProfile -File (Join-Path $so 'scripts/task.ps1') -TaskId T0-LICENSESEED -Phase ship -Local -SkipRed *> $null
      $oExit = $LASTEXITCODE
      $oLedger = if (Test-Path $ledgerO) { Get-Content $ledgerO -Raw } else { '' }
      $oRec = $oLedger -match '"gate":"license"'
      if ($oExit -eq 0) { Fail '闸15o：工作树的 check-licenses.ps1 stub 恒 exit 1（模拟违禁许可依赖）时 ship -Local 仍退出 0——许可闸调用的是主检出副本（恒 exit 0）而非工作树副本（TD80/TD-262：应改调 $Wt）。' }
      elseif (-not $oRec) { Fail '闸15o：ship 非零退出但效果账本无 gate=license 记录（Add-CatchRecord 丢失，或被别的闸先 block 掩盖了本该测的许可闸）。' }
      else { Write-Host '  15o 许可闸扫工作树 OK（工作树自带 check-licenses.ps1 恒 block、ship -Local 被拦、账本 gate=license 记录完整；主检出恒 pass 的 stub 未被误用）' -ForegroundColor Green }
    }
  } finally {
    Set-Location $RepoRoot
    & git -C $so worktree prune 2>$null
    Remove-Item -Recurse -Force $so -ErrorAction SilentlyContinue
  }
}
}

# 15j/15k. TD45：ship 的 dod_command 取值须与 check-cards 用同一份契约（front-matter-only + 大小写敏感），
#   且 ship 须重跑 check-cards——治「卡片在 start 后于主仓被编辑（或 -Phase ship 未 fresh start 续跑）」时，
#   ship 执行 check-cards 从未核准过的内容。$Card 变量恒指向【主仓】副本（非 worktree 副本，task.ps1:59），
#   故种子直接改夹具「主仓」里的卡片文件（模拟 start 后编辑），而非改 worktree 内的卡片。
#   15j：front-matter 无 dod_command，但正文里有一行形似 `dod_command: ...` 的文档示例——旧 Get-CardField
#   整文件 Select-String 会命中正文行并真执行（写出 marker 文件即证据）；15k：front-matter 键误大小写为
#   `DOD_COMMAND:`——旧 Get-CardField 大小写不敏感仍会取值执行，与 check-cards（大小写敏感）判定不一致。
#   两种子均须 ship block 且 marker 文件不得生成。
$gitJ = Get-Command git -ErrorAction SilentlyContinue
if (-not $gitJ) {
  Write-Host '  15j/15k git 未安装，跳过（离线 / 无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  $PSNativeCommandUseErrorActionPreference = $false
  # T213/TD208: 15j/15k are dynamic e2e legs; 15u below is not. The preference line above stays SHARED -
  # 15u arm (e) restores it deliberately and would otherwise run under the PS 7.4+ throwing default.
  if (Test-Gate15RegionSelected 'e2e') {
  $pj = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-cardfield-$PID"
  if (Test-Path $pj) { Remove-Item -Recurse -Force $pj }
  New-Item -ItemType Directory -Force $pj | Out-Null
  try {
    Copy-Item (Join-Path $RepoRoot 'scripts') $pj -Recurse -Force   # 忠实拷 scripts/（同 15i/17k）
    $cfgPJ = Join-Path $pj 'scripts/_config.ps1'
    $cJ = Get-Content $cfgPJ -Raw
    $cJ = [regex]::Replace($cJ, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$pj/wt'" })   # worktree 指向 fixture，绝不碰真实 wt 根
    $cJ = [regex]::Replace($cJ, "GhAccount\s*=\s*'[^']*'",   { "GhAccount = 'cf'" })
    if ($cJ -notmatch [regex]::Escape("$pj/wt")) { Fail '闸15j/15k：fixture _config 注入失败（WorktreeRoot 行格式变了？Replace 没命中）——测的不再是卡片重解析。' }
    Set-Content $cfgPJ $cJ -NoNewline -Encoding utf8
    Set-Content (Join-Path $pj 'scripts/verify.ps1') 'exit 0' -Encoding utf8   # verify 走确定性 stub（同 15b/15i 之理）
    & git -C $pj init -q
    & git -C $pj symbolic-ref HEAD refs/heads/master
    & git -C $pj config user.email 'selftest@local'
    & git -C $pj config user.name  'selftest'
    $cardDirJ = Join-Path $pj 'specs/tasks'
    New-Item -ItemType Directory -Force $cardDirJ | Out-Null
    $cardPathJ = Join-Path $cardDirJ 'T0-CARDFIELD.md'
    # 合法卡（-Phase start 用）：满足 check-cards 全部必填字段，前置元数据 dod_command 为真实（非 no-op）命令。
    $validBody = @(
      '---', 'id: T0-CARDFIELD', 'title: TD45 seed valid', 'status: todo',
      'dod_command: "pwsh -NoProfile -File scripts/check-cards.ps1"', 'allow_paths:', '  - README.md', '---',
      '# valid seed card（selftest 闸 15j/15k 起点：start 后主仓副本会被种子改写）'
    ) -join "`n"
    Set-Content $cardPathJ $validBody -Encoding utf8
    & git -C $pj -c user.email='selftest@local' -c user.name='selftest' add -A 2>$null
    & git -C $pj -c user.email='selftest@local' -c user.name='selftest' commit -q -m 'cardfield base' *> $null
    & pwsh -NoProfile -File (Join-Path $pj 'scripts/task.ps1') -TaskId T0-CARDFIELD -Phase start *> $null
    $wtJ = Join-Path $pj 'wt/T0-CARDFIELD'
    if ($LASTEXITCODE -ne 0 -or -not (Test-Path $wtJ)) { Fail '闸15j/15k：fixture start 未产出 worktree——无法验证 ship 阶段卡片重解析（前置失败）。' }
    else {
      $markerJ = (Join-Path $wtJ 'PWNED_MARKER.txt') -replace '\\', '/'

      # 15j：front-matter 无 dod_command，正文一行 `dod_command: ...`（形似文档示例）写 marker——须绝不被执行。
      $shadowBody = @(
        '---', 'id: T0-CARDFIELD', 'title: TD45 seed body-shadow', 'status: todo',
        'allow_paths:', '  - README.md', '---',
        '# doc example（这是正文，不是 front-matter——绝不该被当真执行）：',
        "dod_command: Set-Content -Path '$markerJ' -Value pwned"
      ) -join "`n"
      Set-Content $cardPathJ $shadowBody -Encoding utf8   # 改的是【主仓】副本（$Card 恒指向此路径，非 $wtJ 内的卡片）
      Remove-Item $markerJ -Force -ErrorAction SilentlyContinue
      Set-Content (Join-Path $wtJ 'README.md') 'e2e cardfield body-shadow change' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $pj 'scripts/task.ps1') -TaskId T0-CARDFIELD -Phase ship -Local -SkipRed *> $null
      $jExit = $LASTEXITCODE
      if (Test-Path $markerJ) { Fail '闸15j：front-matter 缺 dod_command、正文含 `dod_command:` 行时，ship 执行了正文行（marker 文件已生成）——Get-CardField 仍整文件扫描 / ship 未重跑 check-cards（TD45）。' }
      elseif ($jExit -eq 0) { Fail '闸15j：front-matter 缺 dod_command 的卡片，ship -Local 仍退出 0（应因 dod_command 缺失 / check-cards 重跑而 block）。' }
      else { Write-Host '  15j TD45 正文行屏蔽 OK（front-matter 缺 dod_command → ship block、正文行未被执行）' -ForegroundColor Green }

      # 15k：front-matter 键误大小写为 DOD_COMMAND:（check-cards 大小写敏感、视作缺失）——ship 须与 start 同判定（拒）。
      $wrongCaseBody = @(
        '---', 'id: T0-CARDFIELD', 'title: TD45 seed wrong-case', 'status: todo',
        "DOD_COMMAND: Set-Content -Path '$markerJ' -Value pwned",
        'allow_paths:', '  - README.md', '---',
        '# front-matter 键误大写 DOD_COMMAND（非 dod_command）'
      ) -join "`n"
      Set-Content $cardPathJ $wrongCaseBody -Encoding utf8
      Remove-Item $markerJ -Force -ErrorAction SilentlyContinue
      Set-Content (Join-Path $wtJ 'README.md') 'e2e cardfield wrong-case change' -Encoding utf8
      & pwsh -NoProfile -File (Join-Path $pj 'scripts/task.ps1') -TaskId T0-CARDFIELD -Phase ship -Local -SkipRed *> $null
      $kExit = $LASTEXITCODE
      if (Test-Path $markerJ) { Fail '闸15k：front-matter 键误大写 DOD_COMMAND 时，ship 执行了该值（marker 文件已生成）——Get-CardField 大小写不敏感（TD45）。' }
      elseif ($kExit -eq 0) { Fail '闸15k：front-matter 键误大写 DOD_COMMAND（check-cards 视作缺失）时，ship -Local 仍退出 0——与 start 判定不一致（TD45）。' }
      else { Write-Host '  15k TD45 大小写一致 OK（DOD_COMMAND 误大写 → ship 与 start 同判定：block，正文/误大写值均未被执行）' -ForegroundColor Green }
    }
  } finally {
    Set-Location $RepoRoot
    & git -C $pj worktree prune 2>$null
    Remove-Item -Recurse -Force $pj -ErrorAction SilentlyContinue
  }
  }

  # T213/TD208: the fixture-contract region. 15u shares 15j/15k's git guard (L291 was paid to move it
  # inside), so this wrapper sits INSIDE that same else and a no-git tree still degrades through the one
  # announcement that block already prints.
  if (Test-Gate15RegionSelected 'fx') {
$metaRun = Test-MetaSelected "15u"
if ($metaRun) {
# 15u. (T210 / upstream issue #305) The fixture baseline contract, driven by DECLARED examples rather than by
#   this repository's own force-add collection - which is empty here, so an arm reading only the live tree
#   would assert nothing. Same stance as 8.2h'/TD140/ADR 0011: a face that only ever sees a
#   correct-by-construction input can never prove the REJECTING half, so the two controls below (a baseline
#   built the OLD way, and one built FIRST-MEMBER-ONLY, which is the exact defect reported downstream) are
#   what stop this sub-gate going vacuous. Arms: (a) fidelity, (b) controls, (c) derivation, (d) an
#   unstageable member is reported, (e) a non-git source degrades, (f) an excluded root is filtered.
$ub = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-e2ebase-$PID"
if (Test-Path $ub) { Remove-Item -Recurse -Force $ub }
try {
  $ubFind = @()
  # A source shaped like a real consumer: ordinary tracked files, TWO members force-added past .gitignore
  # (issue #305 is precisely "the first was staged, the second was not"), one ignored file that was never
  # added, and one force-added member under a root the fixture copy excludes.
  $ubSrc = Join-Path $ub 'src'
  New-Item -ItemType Directory -Force (Join-Path $ubSrc 'skipme') | Out-Null
  Set-Content (Join-Path $ubSrc '.gitignore') @('*.db', 'skipme/') -Encoding utf8
  Set-Content (Join-Path $ubSrc 'readme.md') 'ordinary tracked file' -Encoding utf8
  Set-Content (Join-Path $ubSrc 'a.db') 'sanitized sample A' -Encoding utf8
  Set-Content (Join-Path $ubSrc 'b.db') 'sanitized sample B' -Encoding utf8
  Set-Content (Join-Path $ubSrc 'never-added.db') 'ignored and never added' -Encoding utf8
  Set-Content (Join-Path $ubSrc 'skipme/forced.db') 'force-added under an excluded root' -Encoding utf8
  & git -C $ubSrc init -q
  & git -C $ubSrc config user.email 'selftest@local'
  & git -C $ubSrc config user.name 'selftest'
  & git -C $ubSrc add -A 2>$null
  & git -C $ubSrc add -f -- a.db b.db skipme/forced.db 2>$null
  & git -C $ubSrc commit -q -m base *> $null
  # (c) derivation: the collection is exactly tracked-AND-ignored - an ordinary tracked file and an ignored
  #     file that was never added both stay out of it.
  $ubAll = @(Get-ScaffoldE2eForcePath -SourceDir $ubSrc)
  if ((($ubAll | Sort-Object) -join ',') -ne 'a.db,b.db,skipme/forced.db') { $ubFind += "[E2E-BASELINE-EXAMPLE] (c) derivation: expected exactly the force-added members 'a.db,b.db,skipme/forced.db', got '$(($ubAll | Sort-Object) -join ',')' - the collection has to be tracked-AND-ignored, so readme.md (tracked, not ignored) and never-added.db (ignored, never added) both stay out. [FIX] fix the rule, never the example."  }
  # (f) a member under a root the fixture copy excludes must be filtered out, or the baseline check would
  #     demand a file that was never copied.
  $ubForce = @(Get-ScaffoldE2eForcePath -SourceDir $ubSrc -SkipRootName @('skipme'))
  if ((($ubForce | Sort-Object) -join ',') -ne 'a.db,b.db') { $ubFind += "[E2E-BASELINE-EXAMPLE] (f) excluded roots: with -SkipRootName 'skipme' the collection must be 'a.db,b.db', got '$(($ubForce | Sort-Object) -join ',')' - a member the copy never brought over would red for a reason the workflow under test has nothing to do with. [FIX] fix the rule, never the example." }
  # (a) fidelity: a faithful copy plus a rebuilt baseline carries the ordinary tracked file AND both
  #     force-added members. The two halves get their own finding text on purpose - add -A covers the first,
  #     the force-add loop the second, and a mutation that removes either must name which half it broke.
  $ubDst = Join-Path $ub 'dst'
  New-Item -ItemType Directory -Force $ubDst | Out-Null
  Get-ChildItem $ubSrc -Force | Where-Object { $_.Name -notin @('.git', 'skipme') } | Copy-Item -Destination $ubDst -Recurse -Force
  & git -C $ubDst init -q
  & git -C $ubDst config user.email 'selftest@local'
  & git -C $ubDst config user.name 'selftest'
  $ubGap = @(Add-ScaffoldE2eBaseline -RepoDir $ubDst -ForcePath $ubForce)
  $ubTracked = @(& git -C $ubDst ls-files)
  if ($ubGap.Count) { $ubFind += "[E2E-BASELINE-EXAMPLE] (a) fidelity: rebuilding the baseline over a faithful copy reported $($ubGap.Count) gap(s) - $($ubGap -join ' | '). [FIX] fix the rule, never the example." }
  if ($ubTracked -notcontains 'readme.md') { $ubFind += "[E2E-BASELINE-EXAMPLE] (a) fidelity: the ORDINARY tracked file readme.md is missing from the rebuilt baseline (tracked: $($ubTracked -join ',')) - the add -A half of the baseline is gone, so the fixture would start from an almost empty tree. [FIX] fix the rule, never the example." }
  foreach ($ubM in @('a.db', 'b.db')) {
    if ($ubTracked -notcontains $ubM) { $ubFind += "[E2E-BASELINE-EXAMPLE] (a) fidelity: FORCE-ADDED member '$ubM' is missing from the rebuilt baseline (tracked: $($ubTracked -join ',')) - every member of the collection has to be staged, not just the first one. [FIX] fix the rule, never the example." }
  }
  # (b) anti-vacuous controls: the same two members, baselined the OLD way and the FIRST-ONLY way, must both
  #     be reported by the same verifier - otherwise a verifier that finds nothing would satisfy (a) forever.
  $ubOld = Join-Path $ub 'ctl-old'
  New-Item -ItemType Directory -Force $ubOld | Out-Null
  Get-ChildItem $ubSrc -Force | Where-Object { $_.Name -notin @('.git', 'skipme') } | Copy-Item -Destination $ubOld -Recurse -Force
  & git -C $ubOld init -q
  & git -C $ubOld add -A 2>$null
  $ubOldGap = @(Get-ScaffoldE2eBaselineGap -RepoDir $ubOld -Expected $ubForce)
  if ($ubOldGap.Count -ne 2) { $ubFind += "[E2E-BASELINE-EXAMPLE] (b) control: a baseline built the OLD way (add -A alone) must be reported as missing BOTH force-added members; got $($ubOldGap.Count) finding(s). A verifier that finds nothing here cannot be trusted when it finds nothing in (a). [FIX] fix the rule, never the example." }
  $ubFirst = Join-Path $ub 'ctl-first'
  New-Item -ItemType Directory -Force $ubFirst | Out-Null
  Get-ChildItem $ubSrc -Force | Where-Object { $_.Name -notin @('.git', 'skipme') } | Copy-Item -Destination $ubFirst -Recurse -Force
  & git -C $ubFirst init -q
  & git -C $ubFirst add -A 2>$null
  & git -C $ubFirst add -f -- a.db 2>$null
  $ubFirstGap = @(Get-ScaffoldE2eBaselineGap -RepoDir $ubFirst -Expected $ubForce)
  if ($ubFirstGap.Count -ne 1 -or -not (($ubFirstGap -join ' ') -like "*'b.db'*")) { $ubFind += "[E2E-BASELINE-EXAMPLE] (b) control: staging only the FIRST member - the exact defect reported in upstream issue #305 - must produce exactly one gap naming 'b.db'; got $($ubFirstGap.Count) finding(s): $($ubFirstGap -join ' | '). [FIX] fix the rule, never the example." }
  # (d) a declared member the builder could not stage is REPORTED, not silently skipped.
  $ubMiss = @(Add-ScaffoldE2eBaseline -RepoDir $ubDst -ForcePath @('a.db', 'absent.db'))
  if ($ubMiss.Count -ne 1 -or -not (($ubMiss -join ' ') -like "*'absent.db'*")) { $ubFind += "[E2E-BASELINE-EXAMPLE] (d) validation: a declared member that is not on disk must produce exactly one finding naming 'absent.db'; got $($ubMiss.Count): $($ubMiss -join ' | '). Skipping it silently is how a baseline goes incomplete without anyone noticing. [FIX] fix the rule, never the example." }
  # (e) a source that is not a repository yields an empty collection and raises nothing - the -Parallel
  #     non-git snapshot, and a downstream before git init. Run with the PS 7.4+ native-error default back
  #     ON (this gate turns it off for itself): without the guard, git ls-files outside a repo throws.
  $ubPlain = Join-Path $ub 'plain'
  New-Item -ItemType Directory -Force $ubPlain | Out-Null
  $ubPrevNative = $PSNativeCommandUseErrorActionPreference
  try {
    $PSNativeCommandUseErrorActionPreference = $true
    $ubNonGit = @(Get-ScaffoldE2eForcePath -SourceDir $ubPlain)
    if ($ubNonGit.Count -ne 0) { $ubFind += "[E2E-BASELINE-EXAMPLE] (e) non-git source: expected an empty collection, got '$($ubNonGit -join ',')'. [FIX] fix the rule, never the example." }
  } catch { $ubFind += "[E2E-BASELINE-EXAMPLE] (e) non-git source: a terminating error escaped ($($_.Exception.Message)) - under the PS 7.4+ native-error default a caller that has not disabled it crashes instead of degrading. [FIX] fix the rule, never the example." }
  finally { $PSNativeCommandUseErrorActionPreference = $ubPrevNative }
  if ($ubFind.Count) { $ubFind | ForEach-Object { Fail "15u (T210): $_" } }
  elseif (-not $fail) { Write-Host '  15u [E2E-BASELINE] fixture baseline fidelity OK (both force-added members staged, ordinary tracked file kept, excluded-root member filtered, unstageable member reported, non-git source empty, and the old-way / first-only controls both refuted)' -ForegroundColor Green }
} catch {
  Fail "15u (T210): an unexpected terminating error escaped the sub-gate ($($_.Exception.Message)) - a fixture that throws would otherwise abort the whole run instead of reddening one gate. Re-check with: selftest.ps1 -Only 15fx"
} finally { Remove-Item -Recurse -Force $ub -ErrorAction SilentlyContinue }
}
  }

}

# --- 16. L-id 引用完整性：根入口文档 + .claude/skills + docs 里的 L<n> 经验引用须存在于 LEDGER ∪ lessons-archive
#        （16b：归档卡的 [RETRACTED L<n>] 退稿标注双向绑定，见该子闸头注）---
# 治本 L29：交叉链接闸（⑪）只校验文件路径，不管 L<n> 引用；写错/写旧 id 把读者导向错误经验，无闸可拦。
# 此闸从热 LEDGER 与冷存 specs/archive/lessons-archive.md 两侧机数已定义 id（T74：引用进冷存不算悬空），
# 扫 skills/docs 的 L<n> 引用（排除 path:Lnn 行号、Lnn-mm 行段等代码引用形态），存在性机检；
# 内容是否对得上（L20 的指针是否真指 L20 的内容）仍须人工——存在性可机检、语义不行。
Exit-Gate
}

if (Enter-Gate '16') {
Step '16/17 L-id 引用完整性（skills/docs 的 L<n> 引用存在于 LEDGER ∪ lessons-archive）'
$ledgerPath = Join-Path $RepoRoot 'docs/lessons/LEDGER.md'
if (-not (Test-Path $ledgerPath)) { Fail 'docs\lessons\LEDGER.md 不存在（经验真相源缺失）。' }
else {
  $defined = @{}
  foreach ($d in [regex]::Matches((Get-Content $ledgerPath -Raw), '(?m)^##\s*L(\d+)\b')) { $defined["L$($d.Groups[1].Value)"] = $true }
  # T74: archived one-offs (cold store, moved by archive.ps1 -LessonIds / the lessons.ps1 archive
  # selector) remain DEFINED ids - a doc/skill reference into the error library is valid, not dangling.
  # specs/archive is not in THIS scan's surface and must not be: an archived card's ordinary L-references
  # are historical records, and holding them to a rule invented after the freeze is the retroactive rewrite
  # specs/README.md forbids. 16b below reads that directory for exactly ONE sentinel - the [RETRACTED L<n>]
  # marker a card opts into - and for nothing else.
  $lsnColdPath = Join-Path $RepoRoot 'specs/archive/lessons-archive.md'
  $lsnColdDefs = 0
  if (Test-Path $lsnColdPath) {
    foreach ($d in [regex]::Matches((Get-Content $lsnColdPath -Raw), '(?m)^##\s*L(\d+)\b')) { if (-not $defined.ContainsKey("L$($d.Groups[1].Value)")) { $lsnColdDefs++ }; $defined["L$($d.Groups[1].Value)"] = $true }
  }
  # Keep the recognition grammar in one place.  lessons.ps1 uses this exact pattern when archive protects
  # resident references; copying it here previously let the two decisions drift independently.
  $lessonsSourcePath = Join-Path $PSScriptRoot 'lessons.ps1'
  $lessonsSource = if (Test-Path -LiteralPath $lessonsSourcePath) { Get-Content -LiteralPath $lessonsSourcePath -Raw } else { '' }
  $lessonRefDeclaration = [regex]::Match($lessonsSource, '(?m)^\$LessonRefRegex\s*=\s*''(?<pattern>[^'']+)''\s*$')
  if (-not $lessonRefDeclaration.Success) {
    Fail '[LSN-REF-REGEX-SOURCE-MISSING] scripts/lessons.ps1 must declare the single-quoted, single-line $LessonRefRegex used by gate 16 and archive resident-reference protection.'
  }
  else {
    $refRe = $lessonRefDeclaration.Groups['pattern'].Value

    # 16a. A hermetic witness prevents the hot∪cold definition domain from becoming vacuous in a repository
    # without a real cold store.  L901 is hot-only, L903 cold-only, and only L904 must be rejected; the
    # path/line-range lookalikes prove this uses the production grammar rather than a broad L<n> grep.
    $g16ProbeDefined = @{}
    foreach ($g16Text in @("# hot`n## L901`n", "# cold`n## L903`n")) {
      foreach ($g16Def in [regex]::Matches($g16Text, '(?m)^##\s*L(\d+)\b')) { $g16ProbeDefined["L$($g16Def.Groups[1].Value)"] = $true }
    }
    $g16ProbeDangling = @()
    foreach ($g16Ref in [regex]::Matches('hot L901; cold L903; dangling L904; path:L905; range L906-907', $refRe)) {
      $g16Id = "L$($g16Ref.Groups[1].Value)"
      if (-not $g16ProbeDefined.ContainsKey($g16Id)) { $g16ProbeDangling += $g16Id }
    }
    if (($g16ProbeDangling.Count -ne 1) -or $g16ProbeDangling[0] -ne 'L904') {
      Fail "[LSN-COLD-REFERENCE-CONTRACT] gate 16's hot+cold hermetic witness expected only L904 dangling under lessons.ps1 `$LessonRefRegex; got [$($g16ProbeDangling -join ', ')]."
    }
    else { Write-Host '  16a hot+cold lesson-reference witness OK (cold-only L903 resolves; L904 alone is dangling)' }

  # 扫描范围：根入口文档 CLAUDE.md + CLAUDE.template.md（下游 CLAUDE.md 的来源，其 L 引用也须不悬空）+ TEMPLATE-README.md + .claude/skills/**/*.md + docs/**/*.md，排除 LEDGER 自身（id 的定义处）。
  $scanFiles = @(
    @(Get-Item -Path (Join-Path $RepoRoot 'CLAUDE.md') -ErrorAction SilentlyContinue) +
    @(Get-Item -Path (Join-Path $RepoRoot 'CLAUDE.template.md') -ErrorAction SilentlyContinue) +
    @(Get-Item -Path (Join-Path $RepoRoot 'TEMPLATE-README.md') -ErrorAction SilentlyContinue) +
    @(Get-ChildItem -Path (Join-Path $RepoRoot '.claude/skills') -Filter *.md -Recurse -ErrorAction SilentlyContinue) +
    @(Get-ChildItem -Path (Join-Path $RepoRoot 'docs') -Filter *.md -Recurse -ErrorAction SilentlyContinue)
  ) | Where-Object { $_.FullName -ne $ledgerPath }
  # 真经验引用：$refRe 从 lessons.ps1 的单一真相源抽取；其排除 HTML5/path:L88/L52-71 等 lookalikes。
  $dangling = @()
  foreach ($sf in $scanFiles) {
    foreach ($mm in [regex]::Matches((Get-Content $sf.FullName -Raw), $refRe)) {
      $id = "L$($mm.Groups[1].Value)"
      if (-not $defined.ContainsKey($id)) { $dangling += ("{0} → {1}" -f $sf.FullName.Substring($RepoRoot.Length + 1), $id) }
    }
  }
  if ($dangling) { $dangling | Sort-Object -Unique | ForEach-Object { Fail "Dangling lesson reference: $_ (the L<n> id is defined in neither docs/lessons/LEDGER.md nor specs/archive/lessons-archive.md; after renaming/renumbering/archiving a lesson, sync its references - existence is machine-checked here, content match remains a human check)" } }
  else { Write-Host "  L-id 引用完整（扫 $($scanFiles.Count) 个 skills/docs 文件，$($defined.Count) 个已定义 id（defs: LEDGER + lessons-archive，冷存贡献 $lsnColdDefs），引用均存在）" }
  }

# 16b. (T212/TD198) Archived-card retraction annotations, bound in BOTH directions. Declared at column 0
#      deliberately, though the block it heads is indented inside gate 16's ledger-present branch: outside
#      gate 17, whose indented seed headers T284 gave a projection of their own, an indented header is not
#      projected as a declaration at all, so 14m would never judge this label and the sub-gate would exist
#      without being declared (L291's corollary, caught live here).
  # An archived card is frozen and specs/README.md forbids rewriting it, so a claim that a LESSON later
  # refuted stays on the card asserting itself. `superseded_by` does not cover it - that field answers "a
  # later CARD deliberately deleted what this card's DoD asserted". The sanctioned form is a
  # [RETRACTED L<n>] marker QUOTING the frozen sentence verbatim, so a single grep of specs/archive/tasks
  # returns claim and retraction together, plus a `retracts: <card-id>` declaration on the lessons side.
  # This sub-gate binds both ends: a marker must resolve and anchor, and a declaration must land a marker.
  #
  # PLACEMENT IS LOAD-BEARING (L291, one week old and in this same file). This block sits INSIDE the
  # ledger-present `else` because it reads $defined, which is built there. PowerShell scopes per function,
  # not per block, so the identical block moved below the closing brace would still SEE $defined - as an
  # EMPTY hashtable - and would then report every valid marker as an unknown lesson on a tree with no
  # ledger. That is L291's trap with the tell inverted: 15u reddened, this would have passed a lie.
  #
  # The judgement is Get-ScaffoldRetractionFinding in _cards.ps1 - hermetic, example-locked, and callable
  # without a tree - so this gate stays a caller and the rule stays mutation-testable on its own.
  . (Join-Path $PSScriptRoot '_cards.ps1')
  $retrEx = @(Test-ScaffoldRetractionExamples)
  if ($retrEx) { $retrEx | ForEach-Object { Fail "16b declared examples: $_" } }

  $archDir = Join-Path $RepoRoot 'specs/archive/tasks'
  $archCards = @{}
  if (Test-Path $archDir) {
    foreach ($ac in Get-ChildItem $archDir -Filter *.md -ErrorAction SilentlyContinue) {
      $archCards[[IO.Path]::GetFileNameWithoutExtension($ac.Name)] = (Get-Content $ac.FullName -Raw)
    }
  }
  # Declarations are read from the hot ledger AND the cold store: archiving a lesson must not silently
  # release the card it retracted, which is the same reasoning T74 applied to the defined-id set above.
  $lsnAllText = (Get-Content $ledgerPath -Raw)
  if (Test-Path $lsnColdPath) { $lsnAllText += "`n" + (Get-Content $lsnColdPath -Raw) }
  $retr = @(Get-ScaffoldRetractionFinding -Card $archCards -LedgerText $lsnAllText -KnownLessonId @($defined.Keys))
  $retrDeclared = @([regex]::Matches($lsnAllText, '(?m)^-\s*retracts:\s*\S+\s*$')).Count
  $retrMarkers = 0
  # Counted through the SAME section owner the judge uses: a count taken over whole card text would
  # report every prose mention as a marker, so the success line would overstate the corpus it judged.
  foreach ($ct in $archCards.Values) { $retrMarkers += @([regex]::Matches((Get-ScaffoldRetractionSection -CardText ([string]$ct)), (Get-ScaffoldRetractionMarkerPattern))).Count }

  foreach ($rf in $retr) {
    switch ($rf.Kind) {
      'lesson-unknown' {
        Fail "[RETRACTION-LESSON-UNKNOWN] specs/archive/tasks/$($rf.Card).md carries a [RETRACTED $($rf.Lesson)] marker and that id is defined in neither docs/lessons/LEDGER.md nor specs/archive/lessons-archive.md, so the annotation points the reader at nothing. [FIX] correct the id on the marker, or restore the lesson it names."
      }
      'claim-missing' {
        Fail "[RETRACTION-CLAIM-MISSING] specs/archive/tasks/$($rf.Card).md marks a retraction for $($rf.Lesson) but quotes no claim. The double-quoted sentence IS what a reader's grep lands on, so a marker without one records the retraction where only someone who already knows will find it. [FIX] put the refuted sentence, verbatim and in double quotes, on the marker line."
      }
      'anchor-unresolved' {
        Fail "[RETRACTION-ANCHOR-UNRESOLVED] specs/archive/tasks/$($rf.Card).md marks $($rf.Lesson) against a quoted claim that occurs nowhere else in that card: '$($rf.Claim)'. The quote must be the frozen sentence verbatim - otherwise a reader grepping the real sentence gets the claim and not the retraction, which is the entire defect this form closes. [FIX] copy the sentence out of the card body; never edit the body to match a paraphrase."
      }
      'marker-missing' {
        Fail "[RETRACTION-MARKER-MISSING] $($rf.Lesson) declares 'retracts: $($rf.Card)' and specs/archive/tasks/$($rf.Card).md carries no [RETRACTED $($rf.Lesson)] marker, so the retraction exists on the lessons side only. A reader arriving at the archived card by grep still reads the refuted claim with nothing beside it - the one-way link TD198 registers. [FIX] add the marker to that card, quoting the refuted sentence."
      }
      'card-missing' {
        Fail "[RETRACTION-CARD-MISSING] $($rf.Lesson) declares 'retracts: $($rf.Card)' and no such card exists in specs/archive/tasks. [FIX] point the declaration at the id that exists now, or drop it if the card was never archived."
      }
      default {
        Fail "[RETRACTION-UNCLASSIFIED] Get-ScaffoldRetractionFinding returned kind '$($rf.Kind)' for card $($rf.Card) / lesson $($rf.Lesson), which this gate has no branch for. [FIX] add the branch here in the same diff that adds the kind - an unhandled kind would otherwise be counted and never explained."
      }
    }
  }
  if (-not $retrEx -and -not $retr) {
    Write-Host "  16b archived retraction anchors OK (scanned $($archCards.Count) archived cards, $retrMarkers marker(s), $retrDeclared retracts: declaration(s); every marker resolves to a defined lesson and anchors to text present in its own card, and every declaration has landed its marker)"
  }
}

Exit-Gate
}

if (Enter-Gate '17') {
# --- 17. 种子缺陷闸（seeded-defect）：把关键 enforcer 喂已知坏输入，断言它确实 BLOCK ---
# 治本「闸只做语法/存在性检查，从不做行为/检出测试」——把『严格/fail-closed/难绕过』从断言升级为可机检回归。
# 每条子测在临时目录造一个已知坏输入，跑对应 enforcer，断言其非零/拦截。缺 git 优雅跳过。绝不动元仓 / 真实工作树。
Step '17/17 种子缺陷闸（enforcer 对已知坏输入须 BLOCK：check-secrets / review.ps1 stale-verdict + 超时 + codex-launch + quoted-cmd + stdin-delivery / init / guard-frozen / 账号守卫 host 锚定 / pre-push 钩子体 + 安装行为(core.hooksPath/链式) / 远端 ship 无评审后端 fail-fast / 评审者身份随后端 / scout-options 年份 / 两 Stop 钩子文案 / 许可闸 Distributes 降级 / handoff 存活性 / R3 prompt verdict-token 中和 + nonce 数据栅栏 + 运行期裁决 schema 强制）'
if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
  Write-Host '  git 未安装，跳过种子缺陷闸（离线/无 git 环境正常）。' -ForegroundColor DarkGray
} else {
  $PSNativeCommandUseErrorActionPreference = $false
  $sd = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-seed-$PID"
  if (Test-Path $sd) { Remove-Item -Recurse -Force $sd }
  New-Item -ItemType Directory -Force $sd | Out-Null
  $seedSkip = $RootIgnore + @('_local', 'CLAUDE.md')
  try {
    $mkSeed = {
      param($dir, [hashtable]$files)
      New-Item -ItemType Directory -Force $dir | Out-Null
      Copy-Item (Join-Path $RepoRoot 'scripts') $dir -Recurse -Force
      & git -C $dir init -q
      foreach ($rel in $files.Keys) {
        $fp = Join-Path $dir $rel
        New-Item -ItemType Directory -Force (Split-Path $fp) | Out-Null
        Set-Content $fp $files[$rel] -Encoding utf8
      }
      & git -C $dir -c user.email='s@l' -c user.name='s' add -A 2>$null
      & git -C $dir -c user.email='s@l' -c user.name='s' commit -q -m seed *> $null
      & pwsh -NoProfile -File (Join-Path $dir 'scripts/check-secrets.ps1') *> $null
      $LASTEXITCODE
    }

    # Hoisted above the region guards (T118): consumed by 17q (pre) AND 17v+ (post), so it must exist
    # whichever region runs standalone - the hoisting criterion in the header (pure/cheap definitions only).
    $hoScript = Join-Path $RepoRoot 'scripts/handoff.ps1'

    if (Test-SeedRegionSelected 'pre') {
    Add-SeedRegionReceipt 'pre@17a'   # T194: execution evidence, filed from inside the guarded body
    # 17a. check-secrets 必须抓到 snake_case 硬编码密钥（证 #6：(?<![A-Za-z]) 边界 + 可选引号）。
    $a = & $mkSeed (Join-Path $sd 'a') @{ 'config.py' = 'db_password = "s3cr3tValue123"' }   # allowlist secret （本行写出密钥字面量做种子；标记令本仓 check-secrets 跳过 selftest.ps1 自身这行，不自报）
    if ($a -eq 0) { Fail '种子缺陷 17a：check-secrets 未拦截 snake_case 硬编码密钥（db_password=...）——#6 检出回归。' }
    else { Write-Host '  17a check-secrets 拦截 snake_case 密钥 OK' -ForegroundColor Green }

    # 17a3 (TD4): reviewed SQLDelight schema snapshots are an exact-path exception
    # to the tracked-sensitive filename rule.  Exercise the real entry point in
    # throwaway repositories: the reviewed file alone passes; siblings, malformed
    # and case-aliased authorities fail; and a reparse ancestor never becomes a
    # back door.  Copying the whole scripts directory is deliberate: check-secrets
    # must load its real `_unicode.ps1` scalar validator in every fixture.
    $td4Path = 'android/core/src/main/sqldelight/databases/1.db'
    $td4ConfigPath = 'configs/secrets/tracked-sensitive-allowlist.json'
    $td4Json = '[{"path":"android/core/src/main/sqldelight/databases/1.db","purpose":"SQLDelight migration schema baseline"}]'
    $invokeTd4Fixture = {
      param([string]$Name, [AllowNull()][string]$Json, [string[]]$Tracked = @(), [string]$ReparseParent = '')
      $root = Join-Path $sd "a3-$Name"
      New-Item -ItemType Directory -Force $root | Out-Null
      Copy-Item (Join-Path $RepoRoot 'scripts') $root -Recurse -Force
      if (-not (Test-Path -LiteralPath (Join-Path $root 'scripts/_unicode.ps1') -PathType Leaf)) { throw '[SECRET-ALLOWLIST-FIXTURE] _unicode.ps1 was not carried into the real consumer fixture.' }
      if ($null -ne $Json) {
        $config = Join-Path $root $td4ConfigPath
        New-Item -ItemType Directory -Force (Split-Path -Parent $config) | Out-Null
        [IO.File]::WriteAllText($config, $Json, [Text.UTF8Encoding]::new($false))
      }
      foreach ($path in $Tracked) {
        $file = Join-Path $root $path
        New-Item -ItemType Directory -Force (Split-Path -Parent $file) | Out-Null
        [IO.File]::WriteAllBytes($file, [byte[]](0x53,0x51,0x4c,0x69,0x00))
      }
      & git -C $root init -q
      & git -C $root -c user.email='s@l' -c user.name='s' add -f -A 2>$null
      & git -C $root -c user.email='s@l' -c user.name='s' commit -q -m seed *> $null
      if ($ReparseParent) {
        $parent = Join-Path $root $ReparseParent; $outside = Join-Path $sd "a3-$Name-outside"
        Move-Item -LiteralPath $parent -Destination $outside -Force
        if ($IsWindows) { & cmd /c mklink /J $parent $outside *> $null } else { New-Item -ItemType SymbolicLink -Path $parent -Target $outside -ErrorAction Stop | Out-Null }
        $item = Get-Item -LiteralPath $parent -Force -ErrorAction SilentlyContinue
        if (-not $item -or (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0)) { throw "[SECRET-ALLOWLIST-FIXTURE] failed to create reparse ancestor $ReparseParent" }
      }
      $out = & pwsh -NoProfile -File (Join-Path $root 'scripts/check-secrets.ps1') 2>&1 | Out-String
      return [pscustomobject]@{ Exit=$LASTEXITCODE; Output=$out }
    }
    $td4Exact = & $invokeTd4Fixture 'exact' $td4Json @($td4Path)
    if ($td4Exact.Exit -ne 0) { Fail "17a3: exact reviewed schema baseline was rejected (exit=$($td4Exact.Exit)): $($td4Exact.Output)" }
    foreach ($case in @(
      @{ Name='adjacent'; Json=$td4Json; Paths=@($td4Path,'android/core/src/main/sqldelight/databases/runtime.db') },
      @{ Name='malformed'; Json='[{'; Paths=@($td4Path) },
      @{ Name='unknown-field'; Json='[{"path":"android/core/src/main/sqldelight/databases/1.db","purpose":"schema","scope":"broad"}]'; Paths=@($td4Path) },
      @{ Name='config-case'; Json=$null; Paths=@($td4Path); CaseConfig=$true }
    )) {
      if ($case.ContainsKey('CaseConfig')) {
        $resultRoot = Join-Path $sd 'a3-config-case'; New-Item -ItemType Directory -Force $resultRoot | Out-Null
        Copy-Item (Join-Path $RepoRoot 'scripts') $resultRoot -Recurse -Force
        $wrongConfig = Join-Path $resultRoot 'configs/secrets/Tracked-sensitive-allowlist.json'; New-Item -ItemType Directory -Force (Split-Path -Parent $wrongConfig) | Out-Null
        [IO.File]::WriteAllText($wrongConfig, '[]', [Text.UTF8Encoding]::new($false))
        $db = Join-Path $resultRoot $td4Path
        New-Item -ItemType Directory -Force (Split-Path -Parent $db) | Out-Null
        [IO.File]::WriteAllBytes($db,[byte[]](0x53,0x51,0x4c,0x69,0x00))
        & git -C $resultRoot init -q
        & git -C $resultRoot -c user.email='s@l' -c user.name='s' add -f -A
        & git -C $resultRoot -c user.email='s@l' -c user.name='s' commit -q -m seed
        $caseOut = & pwsh -NoProfile -File (Join-Path $resultRoot 'scripts/check-secrets.ps1') 2>&1 | Out-String
        $result = [pscustomobject]@{ Exit=$LASTEXITCODE; Output=$caseOut }
      } else { $result = & $invokeTd4Fixture $case.Name $case.Json $case.Paths }
      if ($result.Exit -eq 0) { Fail "17a3($($case.Name)): invalid or unreviewed tracked-sensitive state passed check-secrets." }
    }
    foreach ($reparse in @('configs/secrets','android/core/src/main/sqldelight/databases')) {
      $td4Reparse = & $invokeTd4Fixture ('reparse-' + ($reparse -replace '/','-')) $td4Json @($td4Path) $reparse
      if ($td4Reparse.Exit -eq 0 -or $td4Reparse.Output -notmatch '\[SECRET-ALLOWLIST\]') { Fail "17a3(reparse): reparse ancestor $reparse was not fail-closed: $($td4Reparse.Output)" }
    }
    if (-not $fail) { Write-Host '  17a3 tracked-sensitive allowlist exact/adjacent/schema/case/reparse regressions OK' -ForegroundColor Green }

# Insert in 17pre before gate17a3-migration.ps1.snippet. Requires helpers.ps1.snippet and existing $sd/$RepoRoot.
$td145Probe = Join-Path $sd 'a3-cleanup-probe'
$td145Counter = [PSCustomObject]@{ Count = 0 }
New-Item -ItemType Directory -Force $td145Probe | Out-Null
$td145Retry = Remove-Td4MigrationFixtureWorktree -RepoRoot $RepoRoot -WorktreePath $td145Probe -MaxAttempts 2 -RetryDelayMs 1 `
  -AttemptInvoker { param($attempt, $path) $td145Counter.Count++; if ($attempt -eq 2) { Remove-Item -LiteralPath $path -Recurse -Force; [PSCustomObject]@{ Exit = 0; Output = 'retry-detail-2' } } else { [PSCustomObject]@{ Exit = 41; Output = 'retry-detail-1' } } } `
  -RegistrationProbe { $false } -SleepInvoker { param($ms) }
$td145RetryOk = $td145Retry.Success -and $td145Retry.Attempts -eq 2 -and $td145Counter.Count -eq 2
if (-not $td145RetryOk) { Fail "17a3(cleanup/retry): first failed removal did not make its bounded second attempt. Diagnostics: $($td145Retry.Diagnostics)" }
New-Item -ItemType Directory -Force $td145Probe | Out-Null
$td145Diagnostic = Remove-Td4MigrationFixtureWorktree -RepoRoot $RepoRoot -WorktreePath $td145Probe -MaxAttempts 2 -RetryDelayMs 1 `
  -AttemptInvoker { param($attempt, $path) [PSCustomObject]@{ Exit = 42; Output = "diagnostic-detail-$attempt" } } `
  -RegistrationProbe { $false } -SleepInvoker { param($ms) }
$td145DiagnosticOk = -not $td145Diagnostic.Success -and $td145Diagnostic.PathExists -and (Test-Path -LiteralPath $td145Probe) -and $td145Diagnostic.Diagnostics.Contains('attempt=1') -and $td145Diagnostic.Diagnostics.Contains('remove-exit=42') -and $td145Diagnostic.Diagnostics.Contains('diagnostic-detail-1') -and $td145Diagnostic.Diagnostics.Contains('attempt=2') -and $td145Diagnostic.Diagnostics.Contains('diagnostic-detail-2')
if (-not $td145DiagnosticOk) { Fail "17a3(cleanup/diagnostic): terminal failure did not retain fixture plus each exit/detail. Diagnostics: $($td145Diagnostic.Diagnostics)" }
elseif ($td145RetryOk) { Write-Host '  17a3(cleanup-probe) bounded retry and retained per-attempt diagnostics OK' -ForegroundColor Green }
Remove-Item -LiteralPath $td145Probe -Recurse -Force -ErrorAction SilentlyContinue

$td145GitRepo = Join-Path $sd 'a3-cleanup-git'
$td145GitWorktree = Join-Path $sd 'a3-cleanup-git-wt'
$td145FallbackPath = Join-Path $sd 'a3-cleanup-fallback'
$td145InvalidRepo = Join-Path $sd 'a3-cleanup-invalid-repo'
$td145InvalidTarget = Join-Path $sd 'a3-cleanup-invalid-target'
$td145LockedStream = $null
try {
  New-Item -ItemType Directory -Force $td145GitRepo | Out-Null
  & git -C $td145GitRepo init -q
  Set-Content -LiteralPath (Join-Path $td145GitRepo 'seed.txt') -Value 'td145' -Encoding utf8
  & git -C $td145GitRepo -c user.email='s@l' -c user.name='s' add seed.txt
  & git -C $td145GitRepo -c user.email='s@l' -c user.name='s' commit -q -m seed
  & git -C $td145GitRepo worktree add --detach $td145GitWorktree HEAD *> $null
  $td145RealCleanup = Remove-Td4MigrationFixtureWorktree -RepoRoot $td145GitRepo -WorktreePath $td145GitWorktree -MaxAttempts 2 -RetryDelayMs 1 -SleepInvoker { param($ms) }
  if (-not $td145RealCleanup.Success -or -not $td145RealCleanup.Diagnostics.Contains('remove-exit=0') -or -not $td145RealCleanup.Diagnostics.Contains('list-exit=0')) { Fail "17a3(cleanup/real-git): real remove/list did not retain distinct successful exits. Diagnostics: $($td145RealCleanup.Diagnostics)" }

  & git -C $td145GitRepo worktree add --detach $td145GitWorktree HEAD *> $null
  & git -C $td145GitRepo worktree lock $td145GitWorktree
  Remove-Item -LiteralPath $td145GitWorktree -Recurse -Force
  $td145MissingPath = Remove-Td4MigrationFixtureWorktree -RepoRoot $td145GitRepo -WorktreePath $td145GitWorktree -MaxAttempts 2 -RetryDelayMs 1 -SleepInvoker { param($ms) }
  if ($td145MissingPath.Success -or -not $td145MissingPath.Registered -or $td145MissingPath.PathExists -or -not $td145MissingPath.Diagnostics.Contains('remove-exit=') -or -not $td145MissingPath.Diagnostics.Contains('list-exit=0')) { Fail "17a3(cleanup/registered-missing): locked registration with missing path did not fail closed. Diagnostics: $($td145MissingPath.Diagnostics)" }

  New-Item -ItemType Directory -Force $td145FallbackPath | Out-Null
  Set-Content -LiteralPath (Join-Path $td145FallbackPath 'plain.txt') -Value 'fallback' -Encoding utf8
  $td145Fallback = Remove-Td4MigrationFixtureWorktree -RepoRoot $td145GitRepo -WorktreePath $td145FallbackPath -MaxAttempts 1 -RetryDelayMs 1 -SleepInvoker { param($ms) }
  if (-not $td145Fallback.Success -or $td145Fallback.Registered -or $td145Fallback.PathExists -or $td145Fallback.Diagnostics -notmatch 'remove-exit=[1-9]\d*' -or -not $td145Fallback.Diagnostics.Contains('remove-detail=') -or -not $td145Fallback.Diagnostics.Contains('list-exit=0') -or -not $td145Fallback.Diagnostics.Contains('fallback-exit=0')) { Fail "17a3(cleanup/fallback-success): failed Git remove did not retain stderr then remove unregistered directory. Diagnostics: $($td145Fallback.Diagnostics)" }

  if ($IsWindows) {
    New-Item -ItemType Directory -Force $td145FallbackPath | Out-Null
    $td145LockedFile = Join-Path $td145FallbackPath 'locked.txt'
    Set-Content -LiteralPath $td145LockedFile -Value 'locked' -Encoding utf8
    $td145LockedStream = [System.IO.File]::Open($td145LockedFile, 'Open', 'ReadWrite', 'None')
    $td145FallbackFailure = Remove-Td4MigrationFixtureWorktree -RepoRoot $td145GitRepo -WorktreePath $td145FallbackPath -MaxAttempts 1 -RetryDelayMs 1 -SleepInvoker { param($ms) }
    if ($td145FallbackFailure.Success -or $td145FallbackFailure.Registered -or -not $td145FallbackFailure.PathExists -or -not $td145FallbackFailure.Diagnostics.Contains('fallback-exit=99') -or -not $td145FallbackFailure.Diagnostics.Contains('fallback-detail=')) { Fail "17a3(cleanup/fallback-failure): failed filesystem fallback did not retain scene and diagnosis. Diagnostics: $($td145FallbackFailure.Diagnostics)" }
    $td145LockedStream.Dispose(); $td145LockedStream = $null
  }

  New-Item -ItemType Directory -Force $td145InvalidRepo, $td145InvalidTarget | Out-Null
  $td145GitFailure = Remove-Td4MigrationFixtureWorktree -RepoRoot $td145InvalidRepo -WorktreePath $td145InvalidTarget -MaxAttempts 1 -RetryDelayMs 1 -SleepInvoker { param($ms) }
  if ($td145GitFailure.Success -or -not $td145GitFailure.Registered -or -not $td145GitFailure.PathExists -or $td145GitFailure.Diagnostics -notmatch 'remove-exit=[1-9]\d*' -or -not $td145GitFailure.Diagnostics.Contains('remove-detail=') -or $td145GitFailure.Diagnostics -notmatch 'list-exit=[1-9]\d*' -or -not $td145GitFailure.Diagnostics.Contains('list-detail=')) { Fail "17a3(cleanup/git-failure): nonzero Git remove/list did not retain independent exit/stderr and fail closed. Diagnostics: $($td145GitFailure.Diagnostics)" }
}
finally {
  if ($td145LockedStream) { $td145LockedStream.Dispose() }
  & git -C $td145GitRepo worktree unlock $td145GitWorktree 2>$null
  & git -C $td145GitRepo worktree prune --expire now 2>$null
  Remove-Item -LiteralPath $td145GitWorktree, $td145GitRepo, $td145FallbackPath, $td145InvalidRepo, $td145InvalidTarget -Recurse -Force -ErrorAction SilentlyContinue
}

# Insert after current 17a3 allowlist success line and after cleanup-probes.ps1.snippet, inside 17pre.
. (Join-Path $PSScriptRoot 'check-licenses.ps1') -AsLibrary
$td4GradleUserHome = if ($env:GRADLE_USER_HOME) { $env:GRADLE_USER_HOME } else { Join-Path ([Environment]::GetFolderPath('UserProfile')) '.gradle' }
$td4WrapperState = Get-GradleWrapperDistributionState -AndroidRoot (Join-Path $RepoRoot 'android') -GradleUserHome $td4GradleUserHome
if (-not $td4WrapperState.Ready) {
  Write-Host "  17a3(migration) skipped [GRADLE-WRAPPER-OFFLINE]: $($td4WrapperState.Detail)" -ForegroundColor DarkGray
} else {
  $td4MigrationRepo = if ($IsWindows) { Join-Path ([System.IO.Path]::GetPathRoot($RepoRoot)) "st4-$PID" } else { Join-Path ([System.IO.Path]::GetTempPath()) "st4-$PID" }
  $td4MigrationWorktreeAdded = $false
  $td4BuildFile = $null; $td4BuildText = $null; $td4BuildTextCaptured = $false
  $td4ForcedTestFile = $null; $td4ForcedTestCreated = $false; $td4ForcedTestExistedBefore = $false
  $td4ForcedTestOriginal = $null; $td4ForcedTestOriginalCaptured = $false
  $td4TenancyFile = $null; $td4TenancyOriginal = $null; $td4TenancyOriginalCaptured = $false
  $td4WrongMigration = $null
  try {
    & git -C $RepoRoot worktree add --detach $td4MigrationRepo HEAD *> $null
    if ($LASTEXITCODE -ne 0) { Fail '17a3(migration/setup): cannot create detached migration fixture worktree.' }
    else {
      $td4MigrationWorktreeAdded = $true
      $td4BuildFile = Join-Path $td4MigrationRepo 'android/core/build.gradle.kts'
      $td4BaselineFile = Join-Path $td4MigrationRepo $td4Path
      try {
        if (Test-Path -LiteralPath $td4BuildFile -PathType Leaf) { $td4BuildText = [System.IO.File]::ReadAllText($td4BuildFile); $td4BuildTextCaptured = $true }
        else { Fail '17a3(migration/setup): build.gradle.kts snapshot is absent.' }
      } catch { Fail "17a3(migration/setup): cannot read build.gradle.kts snapshot: $($_.Exception.Message)" }
      $td4TenancyFile = Join-Path $td4MigrationRepo 'android/core/src/main/sqldelight/nz/myinspection/core/db/Tenancy.sq'
      try { $td4TenancyOriginal = [System.IO.File]::ReadAllText($td4TenancyFile); $td4TenancyOriginalCaptured = $true }
      catch { Fail "17a3(migration/setup): cannot read Tenancy.sq snapshot: $($_.Exception.Message)" }
      if (-not $td4BuildTextCaptured -or -not $td4TenancyOriginalCaptured) {
        Fail '17a3(migration/setup): original snapshots incomplete; fixture is not modified.'
      } elseif ($td4BuildText -notmatch 'verifyMigrations\.set\(true\)' -or -not (Test-Path -LiteralPath $td4BaselineFile -PathType Leaf)) {
        Fail '17a3(migration/setup): HEAD lacks verifyMigrations=true or tracked 1.db; migration negative examples would be vacuous.'
      } else {
        $invokeTd4CoreCheckWithoutContinue = {
          Push-Location $td4MigrationRepo
          try {
            if ($IsWindows) { $output = & cmd /c android\gradlew.bat -p android --offline --no-daemon -q :core:check 2>&1 | Out-String }
            else { $output = & sh android/gradlew -p android --offline --no-daemon -q :core:check 2>&1 | Out-String }
            [pscustomobject]@{ Exit = $LASTEXITCODE; Output = $output }
          } finally { Pop-Location }
        }
        $invokeTd4CoreCheck = {
          Push-Location $td4MigrationRepo
          try {
            if ($IsWindows) { $output = & cmd /c android\gradlew.bat -p android --offline --no-daemon --continue -q :core:check 2>&1 | Out-String }
            else { $output = & sh android/gradlew -p android --offline --no-daemon --continue -q :core:check 2>&1 | Out-String }
            [pscustomobject]@{ Exit = $LASTEXITCODE; Output = $output }
          } finally { Pop-Location }
        }
        $td4ForcedTestFile = Join-Path $td4MigrationRepo 'android/core/src/test/kotlin/nz/myinspection/core/selftest/Td4ContinueProbeTest.kt'
        $td4ForcedTestExistedBefore = Test-Path -LiteralPath $td4ForcedTestFile
        if ($td4ForcedTestExistedBefore) {
          try { $td4ForcedTestOriginal = [System.IO.File]::ReadAllText($td4ForcedTestFile); $td4ForcedTestOriginalCaptured = $true }
          catch { Fail "17a3(migration-continue/setup): cannot snapshot existing probe test: $($_.Exception.Message)" }
          if ($td4ForcedTestOriginalCaptured) { Fail '17a3(migration-continue/setup): probe test path exists; refusing to overwrite product test.' }
        } else {
          New-Item -ItemType Directory -Force (Split-Path -Parent $td4ForcedTestFile) | Out-Null
          $td4ForcedTestSource = @('package nz.myinspection.core.selftest','','import kotlin.test.Test','import kotlin.test.fail','','class Td4ContinueProbeTest {','    @Test','    fun forcedFailureForContinueProbe() {','        fail("TD4_CONTINUE_TEST_FAILURE")','    }','}','') -join [Environment]::NewLine
          $td4ForcedTestCreated = $true
          [System.IO.File]::WriteAllText($td4ForcedTestFile, $td4ForcedTestSource, [System.Text.UTF8Encoding]::new($false))
          $td4ContinueOrdering = @('','// selftest fixture: makes the no-continue blind spot deterministic.','tasks.configureEach {','    if (name == "verifyMainMyInspectionDatabaseMigration") {','        mustRunAfter("test")','    }','}','') -join [Environment]::NewLine
          [System.IO.File]::WriteAllText($td4BuildFile, $td4BuildText + [Environment]::NewLine + $td4ContinueOrdering, [System.Text.UTF8Encoding]::new($false))

          $td4MissingProbe = "`nCREATE TABLE td4_missing_migration_probe (`n  id INTEGER NOT NULL PRIMARY KEY`n);`n"
          [System.IO.File]::WriteAllText($td4TenancyFile, $td4TenancyOriginal + $td4MissingProbe, [System.Text.UTF8Encoding]::new($false))
          $td4WithoutContinueResult = & $invokeTd4CoreCheckWithoutContinue
          $td4MissingResult = & $invokeTd4CoreCheck
          $td4ContinueCleanup = Restore-Td4ContinueProbeFixture -ProbeFile $td4ForcedTestFile -ProbeCreated $td4ForcedTestCreated -ProbeExistedBefore $td4ForcedTestExistedBefore -ProbeOriginal $td4ForcedTestOriginal -ProbeOriginalCaptured $td4ForcedTestOriginalCaptured -BuildFile $td4BuildFile -BuildOriginal $td4BuildText -BuildOriginalCaptured $td4BuildTextCaptured -TenancyFile $td4TenancyFile -TenancyOriginal $td4TenancyOriginal -TenancyOriginalCaptured $td4TenancyOriginalCaptured
          if (-not (Test-Td4ContinueProbeCleanupComplete -Cleanup $td4ContinueCleanup)) {
            Fail "17a3(migration-continue/cleanup): fixture restore failed; skip wrong-migration probe. $(Get-Td4ContinueProbeCleanupDiagnostics -Cleanup $td4ContinueCleanup)"
          } else {
            $td4TestFailureMarker = "Execution failed for task ':core:test'."
            $td4WithoutContinueExact = $td4WithoutContinueResult.Exit -ne 0 -and $td4WithoutContinueResult.Output.Contains($td4TestFailureMarker) -and $td4WithoutContinueResult.Output -notmatch 'verifyMainMyInspectionDatabaseMigration' -and $td4WithoutContinueResult.Output -notmatch 'td4_missing_migration_probe'
            if (-not $td4WithoutContinueExact) { Fail "17a3(migration-continue/mutant): no --continue did not reproduce test-first failure without migration verifier (exit=$($td4WithoutContinueResult.Exit)). Output: $($td4WithoutContinueResult.Output)" }
            $td4MissingExact = $td4MissingResult.Output -match 'verifyMainMyInspectionDatabaseMigration' -and $td4MissingResult.Output -match 'td4_missing_migration_probe' -and $td4MissingResult.Output -match 'ADDED'
            $td4ContinuedExact = $td4MissingResult.Exit -ne 0 -and $td4MissingResult.Output.Contains($td4TestFailureMarker) -and $td4MissingExact
            if (-not $td4ContinuedExact) { Fail "17a3(migration-continue): --continue did not execute the real migration verifier after :core:test failure (exit=$($td4MissingResult.Exit)). Output: $($td4MissingResult.Output)" }
            $td4WrongMigration = Join-Path $td4MigrationRepo 'android/core/src/main/sqldelight/nz/myinspection/core/db/1.sqm'
            $td4WrongSql = "CREATE TABLE td4_wrong_migration_probe (`n  id INTEGER NOT NULL PRIMARY KEY`n);`n"
            [System.IO.File]::WriteAllText($td4WrongMigration, $td4WrongSql, [System.Text.UTF8Encoding]::new($false))
            $td4WrongResult = & $invokeTd4CoreCheck
            Remove-Item -LiteralPath $td4WrongMigration -Force -ErrorAction SilentlyContinue
            $td4WrongExact = $td4WrongResult.Output -match 'verifyMainMyInspectionDatabaseMigration' -and $td4WrongResult.Output -match 'td4_wrong_migration_probe' -and $td4WrongResult.Output -match 'REMOVED'
            if ($td4WrongResult.Exit -eq 0 -or -not $td4WrongExact) { Fail "17a3(migration-wrong): injected 1.sqm was not rejected by real :core:check migration task (exit=$($td4WrongResult.Exit)). Output: $($td4WrongResult.Output)" }
            else { Write-Host '  17a3(migration) real :core:check rejects missing migration ADDED and wrong migration REMOVED OK' -ForegroundColor Green }
          }
        }
      }
    }
  } finally {
    $td4ContinueCleanup = Restore-Td4ContinueProbeFixture -ProbeFile $td4ForcedTestFile -ProbeCreated $td4ForcedTestCreated -ProbeExistedBefore $td4ForcedTestExistedBefore -ProbeOriginal $td4ForcedTestOriginal -ProbeOriginalCaptured $td4ForcedTestOriginalCaptured -BuildFile $td4BuildFile -BuildOriginal $td4BuildText -BuildOriginalCaptured $td4BuildTextCaptured -TenancyFile $td4TenancyFile -TenancyOriginal $td4TenancyOriginal -TenancyOriginalCaptured $td4TenancyOriginalCaptured
    if (-not (Test-Td4ContinueProbeCleanupComplete -Cleanup $td4ContinueCleanup)) { Fail "17a3(migration-continue/cleanup): temporary test, build script, or Tenancy.sq was not restored. $(Get-Td4ContinueProbeCleanupDiagnostics -Cleanup $td4ContinueCleanup)" }
    if ($td4WrongMigration -and (Test-Path -LiteralPath $td4WrongMigration)) { Remove-Item -LiteralPath $td4WrongMigration -Force -ErrorAction SilentlyContinue }
    if ($td4MigrationWorktreeAdded) {
      $td4Cleanup = Remove-Td4MigrationFixtureWorktree -RepoRoot $RepoRoot -WorktreePath $td4MigrationRepo -MaxAttempts 3 -RetryDelayMs 250
      if (-not $td4Cleanup.Success) { Fail "17a3(migration/cleanup): detached fixture remains after $($td4Cleanup.Attempts) bounded attempts at $td4MigrationRepo. Diagnostics:`n$($td4Cleanup.Diagnostics)" }
      else { Write-Host "  17a3(migration/cleanup) short-path fixture removed (attempts=$($td4Cleanup.Attempts); path and registration absent) OK" -ForegroundColor Green }
    }
  }
}

    # 17a2. (TD-201) check-secrets 必须**存活** git 子模块 gitlink：`git ls-files` 把子模块作为**单条 gitlink** 输出，
    #   其工作树路径是**目录**。1b 循环旧码 `Test-Path $full` 对目录为真、放行后 :151 对 DirectoryInfo 求 `.Length`
    #   （StrictMode 终止错误）/ :152 `ReadAllBytes` 对目录抛 → 脚本崩、不返回裁决，含子模块的任何下游仓上防泄露闸不可用。
    #   修法把 :148 收口为 `-PathType Leaf`（同时跳过缺失/目录条目）。hermetic：内部 git 仓 + 超级仓（拷入当前 scripts/
    #   含被测 check-secrets.ps1 + 良性文本 + 子模块 gitlink），断言 check-secrets **干净退出（exit 0）**、不崩。
    $inner = Join-Path $sd 'a2-inner'; New-Item -ItemType Directory -Force $inner | Out-Null
    & git -C $inner init -q
    Set-Content (Join-Path $inner 'readme.txt') 'inner submodule content, no secrets here' -Encoding utf8
    & git -C $inner -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $inner -c user.email='s@l' -c user.name='s' commit -q -m inner *> $null
    $ss = Join-Path $sd 'a2'; New-Item -ItemType Directory -Force $ss | Out-Null
    Copy-Item (Join-Path $RepoRoot 'scripts') $ss -Recurse -Force
    & git -C $ss init -q
    Set-Content (Join-Path $ss 'notes.txt') 'benign super-repo file, no secrets here' -Encoding utf8
    # protocol.file.allow=always：git 2.38+ 默认禁 file:// 子模块（CVE-2022-39253），种子里显式放行本地路径。
    & git -C $ss -c protocol.file.allow=always -c user.email='s@l' -c user.name='s' submodule add ($inner -replace '\\','/') sub *> $null
    $a2SubAdd = $LASTEXITCODE
    & git -C $ss -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $ss -c user.email='s@l' -c user.name='s' commit -q -m seed *> $null
    # setup 自证（R3 rubric #6：测试不得无声退化）：native 命令非终止（*> $null），若 submodule add 静默失败，
    # 种子会退化成**普通仓**、check-secrets exit 0 便 vacuously pass 而从未触碰 gitlink 目录。故在跑被测脚本前，
    # 断言 add 退 0 **且**（提交后）`ls-files --stage sub` 报 gitlink 模式 **160000**——两者缺一即本子例 FAIL
    # （种子坏了、不是被测行为对），杜绝 TD-201 回归护栏无声失效。
    $a2Stage = "$(& git -C $ss ls-files --stage -- sub 2>$null)"
    if ($a2SubAdd -ne 0 -or $a2Stage -notmatch '(?m)^160000 ') {
      Fail "闸17a2(setup)：子模块 gitlink 未建立（submodule add exit=$a2SubAdd · ls-files --stage sub='$a2Stage'，期望模式 160000）——种子退化为普通仓，17a2 将 vacuously pass 而不触碰 gitlink 目录（TD-201 回归护栏失效）。核查 git 版本 / protocol.file.allow=always 支持。"
    } else {
      $a2out = & pwsh -NoProfile -File (Join-Path $ss 'scripts/check-secrets.ps1') 2>&1
      $a2code = $LASTEXITCODE
      if ($a2code -ne 0) { Fail "种子缺陷 17a2：含子模块 gitlink 的仓上 check-secrets 未干净退出（exit $a2code）——1b 循环对目录条目求 .Length/ReadAllBytes 崩，含子模块的下游仓上防泄露闸不可用（TD-201）。输出：$a2out" }
      else { Write-Host '  17a2 check-secrets 存活子模块 gitlink（gitlink 模式 160000 已证 · tracked 目录条目不再崩）OK（TD-201）' -ForegroundColor Green }
    }

    # 17u. check-secrets 覆盖强化（TD62/TD-125）：① JWT 内容模式 ② *.example 内的密钥仍走内容闸
    #      ③ 收窄 .example 文件名白名单（secret.example 被文件名闸拦、.env.example 仍豁免不过度收紧）。
    #      hermetic：每例独立 temp git 仓（镜像 17a），拷入当前 scripts/（含被测 check-secrets.ps1）。
    # 公开示例 JWT（jwt.io HS256 demo，非真凭据）；# allowlist secret 标记令本仓自身 & 各 temp 仓里被拷入的 selftest.ps1 该行被 check-secrets 跳过（不自报）。
    $jwtSeed = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c'   # allowlist secret
    $u1 = & $mkSeed (Join-Path $sd 'u1') @{ 'app/token.txt' = "bearer = $jwtSeed" }
    if ($u1 -eq 0) { Fail '种子缺陷 17u1：check-secrets 未抓到 JWT（eyJ….eyJ….）内容密钥——TD62 JWT 模式回归。' }
    else { Write-Host '  17u1 JWT 内容模式 OK' -ForegroundColor Green }
    $u2 = & $mkSeed (Join-Path $sd 'u2') @{ 'deploy/service-account.json.example' = "{ ""token"": ""$jwtSeed"" }" }
    if ($u2 -eq 0) { Fail '种子缺陷 17u2：*.example 内的 JWT 被放过——.example 文件须仍走内容扫描（不被文件名白名单豁免内容闸）。' }
    else { Write-Host '  17u2 *.example 内容仍被扫描 OK' -ForegroundColor Green }
    # u3a：secret.example 命中文件名模式 (^|/)secret，收窄后不再被 blanket .example$ 放行 → 文件名闸拦（良性内容隔离出文件名闸）。
    $u3a = & $mkSeed (Join-Path $sd 'u3a') @{ 'secret.example' = 'value = your-placeholder-here' }
    if ($u3a -eq 0) { Fail '种子缺陷 17u3a：收窄后 secret.example 仍被 .example 白名单放过（文件名闸未拦）——TD62 白名单收窄回归。' }
    else { Write-Host '  17u3a 收窄 .example 白名单 OK（secret.example 文件名闸拦）' -ForegroundColor Green }
    # u3b（控制/防过度收紧）：.env.example 良性模板须仍豁免、PASS（exit 0）。
    $u3b = & $mkSeed (Join-Path $sd 'u3b') @{ '.env.example' = 'API_KEY=your-key-here' }
    if ($u3b -ne 0) { Fail '种子缺陷 17u3b：.env.example（良性模板）被误拦（exit '"$u3b"'）——白名单收窄过度。' }
    else { Write-Host '  17u3b .env.example 仍豁免 OK' -ForegroundColor Green }

    # 17b. review.ps1 stale-verdict fail-open 已堵（证 #1）：评审者 no-op（不写裁决）+ 预置陈旧 pass → 仍须 block。
    $sb = Join-Path $sd 'b'
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $sb -Recurse -Force
    $cfgB = Join-Path $sb 'scripts/_config.ps1'
    # ReviewCommand = no-op：读干 stdin、不写 $env:REVIEW_OUT、exit 0（模拟「静默 no-op 评审者」）。用 .Replace 避免 -replace 替换语义。
    $cb = (Get-Content $cfgB -Raw).Replace("ReviewCommand = ''", "ReviewCommand = '`$input | Out-Null'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if ($cb -notmatch 'Out-Null') { Fail '闸17b：no-op ReviewCommand 未注入（_config 行格式变了？）——否则改用真 codex，测的不再是「no-op 评审者+陈旧裁决仍 block」（CI 无 codex 会因 codex 缺失而误绿）。' }
    Set-Content $cfgB $cb -NoNewline -Encoding utf8
    New-ReviewFixtureRepo $sb 'feat-x'
    Set-Content (Join-Path $sb 'CHANGED.txt') 'a change under review' -Encoding utf8
    & git -C $sb -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $sb -c user.email='s@l' -c user.name='s' commit -q -m change *> $null
    $revDir = Join-Path $sb '.review'; New-Item -ItemType Directory -Force $revDir | Out-Null
    '{"verdict":"pass","reasons":[],"sha":"stalesha","branch":"feat-x"}' | Set-Content (Join-Path $revDir 'feat-x.json') -Encoding utf8
    & pwsh -NoProfile -File (Join-Path $sb 'scripts/review.ps1') -WorktreePath $sb -Base master *> $null
    if ($LASTEXITCODE -eq 0) { Fail '种子缺陷 17b：review.ps1 在「no-op 评审者 + 预置陈旧 pass」下仍放行（exit 0）——stale-verdict fail-open 回归（#1）。' }
    else { Write-Host '  17b review.ps1 对 no-op 评审者+陈旧裁决仍 block OK' -ForegroundColor Green }

    # 17b'. The two-axis verdict, driven end to end (T277 / ADR 0016 item 4). 17b above proves review.ps1
    #   refuses to read a stale verdict; this proves what the verdict now SAYS reaches the ship decision, and
    #   that it reaches it differently per card tier. The DoD arms for T277 are text anchors - a schema
    #   property, a producer mentioning it, a sentinel in the consumer - and text anchors cannot tell a wired
    #   mechanism from a spelled one (L325). So this drives the real scripts over a real repository: one
    #   stub reviewer emitting a SPEC block with a clean standards axis, and two synthetic cards whose
    #   allow_paths COMPUTE different tiers.
    #     A (tier S, allow_paths names scripts/task.ps1) - ship -Local must refuse with [R3-SPEC-BLOCK],
    #       merge nothing, and file the block in the effectiveness ledger.
    #     B (tier 1, allow_paths names neither a Tier-S nor an all-Tier-0 surface) - the SAME verdict, the
    #       same backend, the same diff, and the ship must merge, warning [R3-ADVISORY-NONZERO]. This half is
    #       the one that fails if the block is wired to the verdict rather than to the tier, and it is the
    #       direction that would quietly re-arm the merge gate T68 removed.
    #     C - a verdict carrying NO axes (any ReviewCommand backend predating the field) must normalise to
    #       both axes carrying the top-level verdict, so an older backend still produces a readable artifact.
    #   The changed file is deliberately NOT markdown: ReviewSkipWhen routes an all-.md diff around the
    #   reviewer entirely, and this gate would then assert its verdict against a review that never ran.
    $sbx = Join-Path $sd 'bx'
    New-Item -ItemType Directory -Force $sbx | Out-Null
    Copy-Item (Join-Path $RepoRoot 'scripts') $sbx -Recurse -Force
    $cfgX = Join-Path $sbx 'scripts/_config.ps1'
    $cX = Get-Content $cfgX -Raw
    $cX = [regex]::Replace($cX, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$sbx/wt'" })   # isolated; never the real wt root
    $cX = [regex]::Replace($cX, "GhAccount\s*=\s*'[^']*'", { "GhAccount = 'seed17bx'" })
    # This is the axis-only fixture: it deliberately disables the legacy required gate and its accumulating
    # round cap.  A spec block must stop Tier-S while Tier-0 stays advisory; 15/security own the real gate/cap.
    $cX = [regex]::Replace($cX, "(?m)^[ \t]*ReviewGate\s*=\s*'[^']*'\s*$", "ReviewGate = ''")
    $cX = [regex]::Replace($cX, '(?m)^[ \t]*ReviewRoundCap\s*=\s*\d+\s*$', 'ReviewRoundCap = 0')
    if (($cX -notmatch "(?m)^ReviewGate\s*=\s*''\s*$") -or ($cX -notmatch '(?m)^ReviewRoundCap\s*=\s*0\s*$')) {
      Fail "17b' fixture _config injection missed ReviewGate='' or ReviewRoundCap=0 (did either assignment format change?) - this axis-only fixture would instead be blocked by the repository mandatory gate or accumulated prior reviewer rounds."
    }
    # T301: the intensity dial is BLANKED here for the same reason 17z blanks ReviewEffortBySize - to isolate
    # the axis under test. This sub-gate drives a tier-0 card (T0-TIERZERO) whose whole point is that a
    # reviewer RUNS and its non-zero exit is reported as [R3-ADVISORY-NONZERO]; with the repo's own map in
    # force that tier is configured 'skip', no reviewer runs, and the seed asserts nothing. Blanking it keeps
    # this gate about the two-axis verdict; the dial's own behaviour is asserted by 17ib, on its own fixtures.
    $cX = [regex]::Replace($cX, "ReviewIntensityByTier\s*=\s*@\{[^}]*\}", 'ReviewIntensityByTier = @{}')
    if ($cX -notmatch 'ReviewIntensityByTier\s*=\s*@\{\s*\}') {
      Fail "17b' fixture _config injection missed ReviewIntensityByTier (did the field's literal format change?) - with the repo's own map in force the tier-0 leg is routed around its reviewer and its seeded defect can never fire."
    }
    $stubX = Join-Path $sbx 'review-stub.ps1'
    $cX = $cX.Replace("ReviewCommand = ''", "ReviewCommand = 'pwsh -NoProfile -File $($stubX -replace '\\', '/')'")
    if (($cX -notmatch 'review-stub') -or ($cX -notmatch [regex]::Escape("$sbx/wt"))) {
      Fail "17b' fixture _config injection missed (did the WorktreeRoot / ReviewCommand line format change?) - without it this sub-gate would call the real codex (networked, non-deterministic) or build its worktrees under the real WorktreeRoot."
    }
    Set-Content $cfgX $cX -NoNewline -Encoding utf8
    Set-Content (Join-Path $sbx 'scripts/verify.ps1') 'exit 0' -Encoding utf8   # verify runs as a deterministic stub (same reasoning as 15b/15d2)
    New-Item -ItemType Directory -Force (Join-Path $sbx 'docs') | Out-Null
    # review.ps1 reads the rubric from the BASELINE and fail-closes without it; content is irrelevant to a stub.
    Set-Content (Join-Path $sbx 'docs/QUALITY-RUBRIC.md') "# 17b' fixture stub rubric (non-empty is all that matters; the stub backend ignores the body)" -Encoding utf8
    Set-Content (Join-Path $sbx 'seed.txt') 'fixture payload under review' -Encoding utf8
    # The tier-S card's own payload file, present at the base because check-cards resolves every
    # allow_paths entry (T174): a name that does not exist AND sits within three edits of one that
    # does is refused at -Phase start, and 'seed-s.txt' is two edits from 'seed.txt'.
    Set-Content (Join-Path $sbx 'seed-s.txt') 'fixture payload under review (tier-S card)' -Encoding utf8
    # T285: the TIER-0 card's payload, under `docs/` (a Tier0Paths entry) but NOT markdown. Both halves are
    # load-bearing: the directory is what makes the card compute 0, and the extension is what keeps
    # ReviewSkipWhen (AllPathsMatch '\.md$') from routing the diff around the reviewer, which would leave
    # case J asserting a decision about a review that never ran.
    Set-Content (Join-Path $sbx 'docs/seed-zero.txt') 'fixture payload under review (tier-0 card)' -Encoding utf8
    # T288: case L's payload. Its own file, like every other card here, so the branch it ships never has to
    # resolve a merge against one of the others.
    Set-Content (Join-Path $sbx 'seed-b.txt') 'fixture payload under review (base-reviewer card)' -Encoding utf8
    # The same .review exclusion the real repository carries, and this fixture needs it from the SECOND
    # ship onwards: ship commits the worktree with `git add -A`, so the previous round's verdict artifacts
    # would be committed as card-external paths and the SCOPE gate would refuse before the R3 leg ran at
    # all - a non-zero exit that proves nothing about any axis (L167).
    Set-Content (Join-Path $sbx '.gitignore') @('.review/', '_local/') -Encoding utf8
    $stubBodyX = @'
[Console]::In.ReadToEnd() | Out-Null
'{"verdict":"block","reasons":["[spec] #6 @ seed.txt - fixture spec finding"],"axes":{"spec":{"verdict":"block","reasons":["#6 @ seed.txt - fixture spec finding"]},"standards":{"verdict":"pass","reasons":[]}}}' | Set-Content $env:REVIEW_OUT -Encoding utf8
'@
    Set-Content $stubX $stubBodyX -Encoding utf8
    & git -C $sbx init -q
    & git -C $sbx symbolic-ref HEAD refs/heads/master
    & git -C $sbx config user.email 'selftest@local'
    & git -C $sbx config user.name 'selftest'
    New-Item -ItemType Directory -Force (Join-Path $sbx 'specs/tasks') | Out-Null
    # Both cards declare review_gate (so the advisory R3 RUNS - T242) and an acceptance list (check-cards
    # requires one alongside review_gate). Neither declares `tier:`: the tier is COMPUTED from allow_paths,
    # which is the whole point - 'scripts/task.ps1' is a TierSPaths entry, the seed payload files are under
    # neither list. Each card names its OWN payload file so the two branches never collide on a merge.
    @('---', 'id: T0-TIERS', "title: seed 17b' tier-S spec-axis block", 'status: todo',
      'review_gate: codex {verdict:pass}',
      'dod_command: "pwsh -NoProfile -Command exit 0"',
      'acceptance:', '  - "A1 a spec-axis block stops this ship."', '  - "A2 the fixture reviewer writes a verdict."', '  - "A3 the ship reports the decision."', 'allow_paths:',
      '  - seed-s.txt', '  - scripts/task.ps1', '---') -join "`n" |
      Set-Content (Join-Path $sbx 'specs/tasks/T0-TIERS.md') -Encoding utf8
    # T285: the THIRD card, whose allow_paths are docs-only, so the tier COMPUTES 0 - the acceptance face for
    # "nothing changes for Tier 0 cards". It carries no `arbitration:` yet; case J writes one onto the BASE
    # copy bound to the sha its review is about to judge, which is the only shape that could change anything.
    @('---', 'id: T0-TIERZERO', "title: seed 17b' tier-0 advisory", 'status: todo',
      'review_gate: codex {verdict:pass}',
      'dod_command: "pwsh -NoProfile -Command exit 0"',
      'acceptance:', '  - "A1 a spec-axis block never stops a tier-0 ship."', '  - "A2 the fixture reviewer writes a verdict."', '  - "A3 the ship reports the decision."', 'allow_paths:',
      '  - docs/seed-zero.txt', '---') -join "`n" |
      Set-Content (Join-Path $sbx 'specs/tasks/T0-TIERZERO.md') -Encoding utf8
    @('---', 'id: T1-TIERONE', "title: seed 17b' tier-1 advisory", 'status: todo',
      'review_gate: codex {verdict:pass}',
      'dod_command: "pwsh -NoProfile -Command exit 0"',
      'acceptance:', '  - "A1 the same spec-axis block stays advisory here."', '  - "A2 the fixture reviewer writes a verdict."', '  - "A3 the ship reports the decision."', 'allow_paths:',
      '  - seed.txt', '---') -join "`n" |
      Set-Content (Join-Path $sbx 'specs/tasks/T1-TIERONE.md') -Encoding utf8
    # T288: the FOURTH card, and the only one that declares `scripts/review.ps1` in allow_paths - which is
    # what lets case L plant a reviewer inside the tree under review without the scope gate refusing it
    # first. That entry also computes tier S (TierSPaths), which is the tier a spec block stops.
    @('---', 'id: T0-BASEREV', "title: seed 17b' the reviewer comes from the base commit", 'status: todo',
      'review_gate: codex {verdict:pass}',
      'dod_command: "pwsh -NoProfile -Command exit 0"',
      'acceptance:', '  - "A1 a review.ps1 planted in the worktree never reviews its own ship."', '  - "A2 the fixture reviewer writes a verdict."', '  - "A3 the ship reports the decision."', 'allow_paths:',
      '  - seed-b.txt', '  - scripts/review.ps1', '---') -join "`n" |
      Set-Content (Join-Path $sbx 'specs/tasks/T0-BASEREV.md') -Encoding utf8
    & git -C $sbx add -A 2>$null
    & git -C $sbx -c user.email='selftest@local' -c user.name='selftest' commit -q -m "17b' base" *> $null
    # Same encoding pin 17k states: the sentinels asserted below are ASCII, but the captured stream carries
    # localized prose, and a mis-decoded capture garbles the diagnostic tail printed on failure (TD31).
    $encWrapX = Join-Path $sbx 'enc-ship-17bx.ps1'
    Set-Content $encWrapX 'param([string]$Tid) try { [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }; & (Join-Path $PSScriptRoot "scripts/task.ps1") -TaskId $Tid -Phase ship -Local -SkipRed; exit $LASTEXITCODE' -Encoding utf8
    $bxOk = $true
    $ledgerX = Join-Path $sbx '_local/effectiveness-ledger.jsonl'
    foreach ($bxCase in @(
      @{ Id = 'T0-TIERS';   Tier = 'S'; Block = $true;  File = 'seed-s.txt' },
      @{ Id = 'T1-TIERONE'; Tier = '1'; Block = $false; File = 'seed.txt' })) {
      # The start output is CAPTURED rather than discarded: a setup failure here reports "no worktree" and
      # nothing else, which says what did not happen and never why - measured while building this gate,
      # where a card-validation refusal and a git failure were indistinguishable from the outside.
      $bxStart = (& pwsh -NoProfile -File (Join-Path $sbx 'scripts/task.ps1') -TaskId $bxCase.Id -Phase start 2>&1 | Out-String)
      $bxWt = Join-Path $sbx "wt/$($bxCase.Id)"
      if (-not (Test-Path $bxWt)) {
        $bxStartTail = ($bxStart -replace '\s+', ' ').Trim(); if ($bxStartTail.Length -gt 400) { $bxStartTail = $bxStartTail.Substring($bxStartTail.Length - 400) }
        Fail "17b'($($bxCase.Id)) fixture start produced no worktree - a setup failure, so this sub-gate proves nothing at all about tier $($bxCase.Tier). Start output tail=$bxStartTail"
        $bxOk = $false; continue
      }
      # Each card edits its OWN payload file. The tier-S branch is shipped three times (A, E, F) and
      # the tier-1 branch merges in between, so one shared file would leave the last of those ships
      # resolving a merge conflict instead of measuring an axis (measured: [SHIP-LOCAL-MERGE-FAIL]).
      Set-Content (Join-Path $bxWt $bxCase.File) "change under review for $($bxCase.Id)" -Encoding utf8
      $bxMergesBefore = @(& git -C $sbx rev-list --merges HEAD 2>$null).Count
      $bxOut = (& pwsh -NoProfile -File $encWrapX -Tid $bxCase.Id 2>&1 | Out-String)
      $bxExit = $LASTEXITCODE
      $bxMerged = (@(& git -C $sbx rev-list --merges HEAD 2>$null).Count) -gt $bxMergesBefore
      $bxTail = ($bxOut -replace '\s+', ' ').Trim(); if ($bxTail.Length -gt 300) { $bxTail = $bxTail.Substring($bxTail.Length - 300) }
      if ($bxCase.Block) {
        # The verdict artifact first: without it a green here could mean "the ship died for some other
        # reason", which is a non-zero exit proving nothing (L167).
        $bxVerdict = Get-Content (Join-Path $bxWt ".review/$($bxCase.Id).json") -Raw -ErrorAction SilentlyContinue
        if (-not $bxVerdict -or $bxVerdict -notmatch '"axes"') {
          Fail "17b'(A) the tier-S verdict carries no axes - either no reviewer ran for it (ReviewSkipWhen routed the diff around one) or review.ps1 stopped attaching them, and from here this sub-gate is judging something other than the two-axis mechanism. Verdict=$bxVerdict"
          $bxOk = $false
        }
        elseif ($bxExit -eq 0) { Fail "17b'(A) seeded defect: a spec-axis block on a tier-S card left ship -Local exiting 0 and merging - the single blocking rule ADR 0016 item 4 adds is gone. Output tail=$bxTail"; $bxOk = $false }
        elseif ($bxOut -notmatch 'R3-SPEC-BLOCK') { Fail "17b'(A) seeded defect: the ship refused but printed no [R3-SPEC-BLOCK] - it blocked at some other gate (so this sub-gate is no longer measuring the spec axis), or the sentinel is gone and an operator has no code to route on. Output tail=$bxTail"; $bxOk = $false }
        elseif ($bxOut -notmatch 'fixture spec finding') { Fail "17b'(A) seeded defect: [R3-SPEC-BLOCK] was thrown without the spec axis reasons - the half that makes a verdict double as a fix prompt is missing. Output tail=$bxTail"; $bxOk = $false }
        elseif ($bxMerged) { Fail "17b'(A) seeded defect: [R3-SPEC-BLOCK] was thrown and a merge commit appeared anyway - the refusal happens after the merge, which is not a refusal."; $bxOk = $false }
        elseif (-not ((Test-Path $ledgerX) -and ((Get-Content $ledgerX -Raw) -match 'spec-axis block'))) { Fail "17b'(A) the spec axis blocked but the effectiveness ledger holds no record of it (a lost Add-CatchRecord, which is how HARNESS-REVIEW comes to read a live gate as a dead one)."; $bxOk = $false }
      }
      else {
        if ($bxExit -ne 0) { Fail "17b'(B) seeded defect: the SAME spec-block verdict stopped a tier-1 ship (exit $bxExit) - the refusal is wired to the verdict instead of to the card tier, which re-arms through the back door the merge gate T68 removed. Output tail=$bxTail"; $bxOk = $false }
        elseif ($bxOut -match 'R3-SPEC-BLOCK') { Fail "17b'(B) seeded defect: a tier-1 ship printed [R3-SPEC-BLOCK] - the tier took no part in the decision. Output tail=$bxTail"; $bxOk = $false }
        elseif ($bxOut -notmatch 'R3-ADVISORY-NONZERO') { Fail "17b'(B) seeded defect: R3 exited non-zero on a tier-1 card and nothing printed [R3-ADVISORY-NONZERO] - the advisory finding went silent and the author never sees it. Output tail=$bxTail"; $bxOk = $false }
        elseif (-not $bxMerged) { Fail "17b'(B) seeded defect: the tier-1 ship exited 0 and produced no merge commit (--no-ff not in effect, or the change was never committed) - the does-not-block half of this sub-gate was never actually reached."; $bxOk = $false }
      }
    }
    # C. A backend that never learned `axes` (every custom ReviewCommand written before T277). Run against
    #   the tier-S worktree, whose branch case A left unmerged. Both axes must carry the top-level verdict:
    #   an unsplit block is a block on both questions, never a free pass on the one that can stop a ship.
    Set-Content $stubX @'
[Console]::In.ReadToEnd() | Out-Null
'{"verdict":"block","reasons":["no-axes backend finding"]}' | Set-Content $env:REVIEW_OUT -Encoding utf8
'@ -Encoding utf8
    $bxWtS = Join-Path $sbx 'wt/T0-TIERS'
