        else {
          # The ANNOUNCEMENT is compared WHOLE, not by substring: a card's acceptance names the sha, the
          # round count, the ruler and the reason, and every one of those is a thing a later reader needs.
          # `rounds=2` in the expected text is also what pins the floor to TWO from above - a build requiring
          # three would still be sitting at [R3-SPEC-BLOCK] here.
          $bxSentI = [regex]::Match($bxOutI, '\[R3-SPEC-ARBITRATED\][^\r\n]*')
          $bxWantI = "[R3-SPEC-ARBITRATED] sha=$bxShaUse rounds=2 by=fixture arc owner reason=the standing asks are outside this card closed list"
          $bxRowI = $null
          try { $bxRowI = @(@(Get-Content -LiteralPath $ledgerX -ErrorAction Stop) | Where-Object { $_ -match 'spec-axis arbitrated' } | ForEach-Object { $_ | ConvertFrom-Json })[-1] } catch { $bxRowI = $null }
          if ($bxExitI -ne 0) { Fail "17b'(I2) seeded defect: two consecutive spec-block rounds are on record and a maker ruling bound to this sha is on the BASE card, and the ship still refused (exit $bxExitI) - either the recorded ruling reaches no decision, or the floor has drifted above the two rounds CLAUDE.md's stop rule names. Output tail=$bxTailI"; $bxOk = $false }
          elseif (-not $bxSentI.Success) { Fail "17b'(I2) the ship proceeded without printing [R3-SPEC-ARBITRATED] - a waiver that leaves no trace is what this card forbids, and nothing downstream could count its uses. Output tail=$bxTailI"; $bxOk = $false }
          elseif ($bxSentI.Value.Trim() -cne $bxWantI) { Fail "17b'(I2) the announced line is not the one this card specifies. A reader of the console gets the sha the waiver covers, the round count it rested on, who ruled and why - all four, verbatim.`nExpected: $bxWantI`nActual:   $($bxSentI.Value.Trim())"; $bxOk = $false }
          elseif ($bxOutI -match 'R3-SPEC-BLOCK') { Fail "17b'(I2) the ship printed BOTH [R3-SPEC-ARBITRATED] and [R3-SPEC-BLOCK], so the two decisions disagree and a reader cannot tell what happened. Output tail=$bxTailI"; $bxOk = $false }
          elseif (-not $bxMergedI) { Fail "17b'(I2) the ship exited 0 and announced the arbitration but produced no merge commit, so the arbitrated path was never actually reached."; $bxOk = $false }
          elseif (-not $bxRowI) { Fail "17b'(I2) the spec axis was arbitrated but the effectiveness ledger holds no parseable 'spec-axis arbitrated' row - a use of the one mechanism that can set aside a blocking verdict is then uncountable, which is how a waiver stops being visible."; $bxOk = $false }
          elseif (($bxRowI.PSObject.Properties.Name -notcontains 'gate') -or ([string]$bxRowI.gate -cne 'review')) { Fail "17b'(I2) the ledger row for the arbitration is filed under gate '$(if ($bxRowI.PSObject.Properties.Name -contains 'gate') { $bxRowI.gate } else { '(absent)' })', not 'review' - a census of what the review gate did would not find it."; $bxOk = $false }
          elseif (($bxRowI.PSObject.Properties.Name -notcontains 'detail') -or -not ([string]$bxRowI.detail).StartsWith('spec-axis arbitrated')) { Fail "17b'(I2) the ledger row's detail does not start with 'spec-axis arbitrated', so an arbitrated verdict cannot be told from an ordinary advisory row by anything a counter can read. Got: $(if ($bxRowI.PSObject.Properties.Name -contains 'detail') { $bxRowI.detail } else { '(absent)' })"; $bxOk = $false }
        }
      }
    }
    # J. A TIER-0 CARD IS UNTOUCHED BY A RULING, and the case is built so that EVERY other condition holds.
    #   The arbitration branch is unreachable below tier S by construction - the whole block sits inside
    #   `if (($specTier -eq 'S') -and $specBlocked)` - and unreachable-by-construction is exactly the claim a
    #   reader is entitled to see executed rather than argued (acceptance item 5). So this drives the real
    #   ship on a card whose allow_paths COMPUTE 0, with a well-formed maker ruling bound to the sha the
    #   review is about to judge and TWO consecutive spec-block rounds already on record: nothing is missing
    #   except the tier. The ship must stay advisory, print no [R3-SPEC-ARBITRATED] and file no ledger row -
    #   the same advisory path a tier-0 card had before ADR 0016 item 4 existed.
    Set-Content $stubX $stubBodyX -Encoding utf8
    $bxStartZ = (& pwsh -NoProfile -File (Join-Path $sbx 'scripts/task.ps1') -TaskId 'T0-TIERZERO' -Phase start 2>&1 | Out-String)
    $bxWtZ = Join-Path $sbx 'wt/T0-TIERZERO'
    if (-not (Test-Path $bxWtZ)) {
      $bxStartZTail = ($bxStartZ -replace '\s+', ' ').Trim(); if ($bxStartZTail.Length -gt 400) { $bxStartZTail = $bxStartZTail.Substring($bxStartZTail.Length - 400) }
      Fail "17b'(J) fixture start produced no tier-0 worktree - a setup failure, so this case proves nothing about tier 0. Start output tail=$bxStartZTail"
      $bxOk = $false
    }
    elseif ($bxStartZ -notmatch '\[CARD-TIER\] id=T0-TIERZERO tier=0') {
      # The positive control, and it is not decoration: if this card computed S or 1, everything below would
      # pass for the wrong reason and the case would be asserting nothing about tier 0 at all.
      Fail "17b'(J) positive control: check-cards did not compute tier 0 for the docs-only card, so the case below is not measuring a tier-0 ship. Expected a [CARD-TIER] id=T0-TIERZERO tier=0 line; got: $(($bxStartZ -replace '\s+', ' ').Trim())"
      $bxOk = $false
    }
    else {
      # Commit the payload here, for the reason case I states: the ruling binds to the sha the review reads,
      # and a head that moved between writing the card and running the ship would prove nothing.
      Set-Content (Join-Path $bxWtZ 'docs/seed-zero.txt') 'change under review for T0-TIERZERO' -Encoding utf8
      & git -C $bxWtZ add docs/seed-zero.txt 2>$null
      & git -C $bxWtZ -c user.email='selftest@local' -c user.name='selftest' commit -q -m "17b'(J) tier-0 payload" *> $null
      $bxShaZ = "$(& git -C $bxWtZ rev-parse HEAD 2>$null)".Trim()
      # One review run BEFORE the ship, so the ship's own round is the SECOND on record and the two-round
      # floor is satisfied. Without it a green here would also be satisfied by "the floor was not met".
      & pwsh -NoProfile -File (Join-Path $sbx 'scripts/review.ps1') -WorktreePath $bxWtZ -Base master -LocalBase *> $null
      @('---', 'id: T0-TIERZERO', "title: seed 17b' tier-0 advisory", 'status: todo',
        'review_gate: codex {verdict:pass}',
        'dod_command: "pwsh -NoProfile -Command exit 0"',
        'arbitration:', "  - sha: $bxShaZ", '    rounds: 2', '    ruling: maker',
        '    by: fixture arc owner', '    reason: a ruling that must not reach a tier-0 card',
        'acceptance:', '  - "A1 a spec-axis block never stops a tier-0 ship."', '  - "A2 the fixture reviewer writes a verdict."', '  - "A3 the ship reports the decision."', 'allow_paths:',
        '  - docs/seed-zero.txt', '---') -join "`n" |
        Set-Content (Join-Path $sbx 'specs/tasks/T0-TIERZERO.md') -Encoding utf8
      & git -C $sbx add specs/tasks/T0-TIERZERO.md 2>$null
      & git -C $sbx -c user.email='selftest@local' -c user.name='selftest' commit -q -m "17b'(J) ruling recorded on the tier-0 base card" *> $null
      $bxArbRowsBeforeZ = @(@(Get-Content -LiteralPath $ledgerX -ErrorAction SilentlyContinue) | Where-Object { $_ -match 'spec-axis arbitrated' }).Count
      $bxMergesZ = @(& git -C $sbx rev-list --merges HEAD 2>$null).Count
      $bxOutZ = (& pwsh -NoProfile -File $encWrapX -Tid 'T0-TIERZERO' 2>&1 | Out-String)
      $bxExitZ = $LASTEXITCODE
      $bxMergedZ = (@(& git -C $sbx rev-list --merges HEAD 2>$null).Count) -gt $bxMergesZ
      $bxArbRowsAfterZ = @(@(Get-Content -LiteralPath $ledgerX -ErrorAction SilentlyContinue) | Where-Object { $_ -match 'spec-axis arbitrated' }).Count
      $bxTailZ = ($bxOutZ -replace '\s+', ' ').Trim(); if ($bxTailZ.Length -gt 400) { $bxTailZ = $bxTailZ.Substring($bxTailZ.Length - 400) }
      if ($bxShaZ -notmatch '^[0-9a-f]{40}$') { Fail "17b'(J) could not read the tier-0 worktree head (got '$bxShaZ'), so the ruling was bound to nothing and the case proves nothing. Setup failure, not a verdict."; $bxOk = $false }
      elseif ($bxOutZ -match 'R3-SPEC-ARBITRATED') { Fail "17b'(J) seeded defect: a tier-0 ship ARBITRATED a spec block - the arbitration is reading the ruling before the tier, so a mechanism scoped to the riskiest paths now speaks on the cheapest ones. Output tail=$bxTailZ"; $bxOk = $false }
      elseif ($bxArbRowsAfterZ -ne $bxArbRowsBeforeZ) { Fail "17b'(J) seeded defect: a tier-0 ship filed a 'spec-axis arbitrated' ledger row ($bxArbRowsBeforeZ -> $bxArbRowsAfterZ). Nothing about tier 0 may change, and a row nobody can explain is worse than no row."; $bxOk = $false }
      elseif ($bxOutZ -match 'R3-SPEC-BLOCK') { Fail "17b'(J) seeded defect: a tier-0 ship printed [R3-SPEC-BLOCK] - the Tier-S refusal itself has leaked below tier S. Output tail=$bxTailZ"; $bxOk = $false }
      elseif ($bxExitZ -ne 0) { Fail "17b'(J) seeded defect: a spec-axis block stopped a tier-0 ship (exit $bxExitZ) - tier 0's merge bar is ci.yml, and nothing in this card may change that. Output tail=$bxTailZ"; $bxOk = $false }
      elseif ($bxOutZ -notmatch 'R3-ADVISORY-NONZERO') { Fail "17b'(J) seeded defect: R3 exited non-zero on a tier-0 card and nothing printed [R3-ADVISORY-NONZERO] - the finding went silent and the author never sees it. Output tail=$bxTailZ"; $bxOk = $false }
      elseif (-not $bxMergedZ) { Fail "17b'(J) seeded defect: the tier-0 ship exited 0 and produced no merge commit, so the advisory path was never actually reached."; $bxOk = $false }
    }
    # K. THE HISTORY READER, DRIVEN OVER FIVE MALFORMED RECORD SETS. The round count decides whether a ruling
    #   applies, so a history that is not this branch's own contiguous sequence is a history a waiver could be
    #   assembled from by dropping a file in. Five shapes, each ending the count where it becomes unreadable:
    #   a record with no `branch` field, one naming another branch, a GAP in the indices, and one index claimed
    #   by two files - TWICE, above and below an already-counted round, because the ordering where the duplicate
    #   sits below one is the one that reached the floor while the check ran mid-walk (R3 round 5). Driven on the PRODUCTION decision through the same AST probe
    #   case G uses - never a re-implementation - over synthetic record sets, so each shape costs milliseconds
    #   instead of a ship. The HEALTHY set is run first and must arbitrate: without it, six identical
    #   "did not arbitrate" answers would also be produced by a decision that never arbitrates at all.
    $bxHistShaK = '00000000000000000000000000000000000000aa'
    $bxHistCardK = Join-Path $sbx 'hist-card.md'
    @('---', 'id: T0-TIERS', 'title: history probe card', 'status: todo',
      'review_gate: codex {verdict:pass}',
      'dod_command: "pwsh -NoProfile -Command exit 0"',
      'arbitration:', "  - sha: $bxHistShaK", '    rounds: 2', '    ruling: maker',
      '    by: fixture arc owner', '    reason: every condition but the history holds',
      'acceptance:', '  - "A1 the history decides."', '  - "A2 the fixture reviewer writes a verdict."', '  - "A3 the ship reports the decision."', 'allow_paths:',
      '  - scripts/task.ps1', '---') -join "`n" | Set-Content $bxHistCardK -Encoding utf8
    $bxHistBlockK = '{"verdict":"block","reasons":["x"],"sha":"' + $bxHistShaK + '","branch":"T0-TIERS","run_status":"success","axes":{"spec":{"verdict":"block","reasons":["x"]},"standards":{"verdict":"pass","reasons":[]}}}'
    $bxHistNoBranchK = '{"verdict":"block","reasons":["x"],"sha":"' + $bxHistShaK + '","run_status":"success","axes":{"spec":{"verdict":"block","reasons":["x"]},"standards":{"verdict":"pass","reasons":[]}}}'
    $bxHistForeignK = '{"verdict":"block","reasons":["x"],"sha":"' + $bxHistShaK + '","branch":"T9-SOMEONE-ELSE","run_status":"success","axes":{"spec":{"verdict":"block","reasons":["x"]},"standards":{"verdict":"pass","reasons":[]}}}'
    foreach ($bxK in @(
      @{ Name = 'healthy';         Arbitrates = $true;  Rounds = @{ 'r1' = $bxHistBlockK; 'r2' = $bxHistBlockK }
         Why = 'two contiguous spec-block rounds, both carrying this branch name - the shape the producer actually writes' },
      @{ Name = 'missing-branch';  Arbitrates = $false; Rounds = @{ 'r1' = $bxHistBlockK; 'r2' = $bxHistNoBranchK }
         Why = 'the newest record carries no branch field at all, so its ownership is unknown - and unknown must count against a waiver, never for it' },
      @{ Name = 'foreign-branch';  Arbitrates = $false; Rounds = @{ 'r1' = $bxHistBlockK; 'r2' = $bxHistForeignK }
         Why = "the newest record names another card's branch, which is what a history assembled by copying a file in looks like" },
      @{ Name = 'index-gap';       Arbitrates = $false; Rounds = @{ 'r1' = $bxHistBlockK; 'r3' = $bxHistBlockK }
         Why = 'r2 is missing, so the two surviving rounds are not consecutive - and consecutive is exactly what the stop rule asks for' },
      @{ Name = 'duplicate-index'; Arbitrates = $false; Rounds = @{ 'r1' = $bxHistBlockK; 'r2' = $bxHistBlockK; 'r02' = $bxHistBlockK }
         Why = 'one index is claimed by two files, so a single round would be counted twice and one real block could buy the floor' },
      @{ Name = 'duplicate-after-one'; Arbitrates = $false; Rounds = @{ 'r3' = $bxHistBlockK; 'r2' = $bxHistBlockK; 'r02' = $bxHistBlockK }
         Why = 'the duplicated index sits BELOW an already-counted round, which is the ordering that reached the floor while the duplicate was only checked mid-walk - three files describing two rounds, counted as two' })) {
      $bxHistDirK = Join-Path $sbx "histfix/$($bxK.Name)"
      if (Test-Path $bxHistDirK) { Remove-Item -Recurse -Force $bxHistDirK }
      New-Item -ItemType Directory -Force (Join-Path $bxHistDirK '.review') | Out-Null
      Set-Content (Join-Path $bxHistDirK '.review/T0-TIERS.json') $bxHistBlockK -Encoding utf8
      foreach ($bxRK in $bxK.Rounds.Keys) { Set-Content (Join-Path $bxHistDirK ".review/T0-TIERS.$bxRK.json") $bxK.Rounds[$bxRK] -Encoding utf8 }
      $bxHistOutK = (& pwsh -NoProfile -File $bxProbeX -Scripts (Join-Path $sbx 'scripts') -Wt $bxHistDirK -CardPath $bxHistCardK -Mode 'loaded' 2>&1 | Out-String)
      $bxHistSeenK = ($bxHistOutK -replace '\s+', ' ').Trim()
      $bxWantBlockK = if ($bxK.Arbitrates) { 'False' } else { 'True' }
      if ($bxHistSeenK -notmatch 'TIER=\[S\]') { Fail "17b'(K/$($bxK.Name)) the probe did not compute tier S, so its answer says nothing about the arbitration at all. Got: $bxHistSeenK"; $bxOk = $false }
      elseif ($bxHistSeenK -notmatch "BLOCK=$bxWantBlockK\b") {
        if ($bxK.Arbitrates) { Fail "17b'(K/healthy) positive control: a history of $($bxK.Why) did NOT arbitrate, so every 'did not arbitrate' answer below is satisfied by a decision that never arbitrates and proves nothing. Got: $bxHistSeenK"; $bxOk = $false }
        else { Fail "17b'(K/$($bxK.Name)) seeded defect: the arbitration APPLIED on a history where $($bxK.Why). The count is assembled from records that are not this branch's own contiguous sequence, so a waiver can be manufactured by writing files into .review/. Got: $bxHistSeenK"; $bxOk = $false }
      }
    }
    # L. THE REVIEWER COMES FROM THE BASE COMMIT (T288). Until this card both ship legs ran a copy of
    #   review.ps1 taken from a tree the branch could edit - the -Local leg the WORKTREE's, the remote leg
    #   the main checkout's - so a card whose subject IS the reviewer had its own review read by the code it
    #   was replacing (measured on T283). Here a review.ps1 that approves everything and exits 0 is planted
    #   in the worktree of a card that declares scripts/review.ps1 in allow_paths, so the plant is in scope
    #   and really reaches the R3 leg. If that copy ran, the ship would exit 0 and merge; the BASE copy runs
    #   the same COMMITTED stub backend case A uses, so the ship must announce [R3-REVIEWER-FROM-BASE] naming
    #   the base sha and then refuse with [R3-SPEC-BLOCK]. The plant is asserted to be on disk FIRST: without that
    #   control, a green here would also be produced by a plant that never landed (L167).
    #   BOTH LEGS, and only one of them is reachable here. The REMOTE leg needs a pushed branch, a PR and
    #   gh, exactly as 17b'(H) records for the decision, so its half is judged from the syntax tree: the
    #   resolver is called at two sites, and no invocation anywhere in the file still takes review.ps1 from
    #   a checkout. Static, and deliberately BEFORE the ship below - a deletion that also crashes the ship
    #   is then reported by its cause rather than by the crash (L167).
    $bxTaskAstL = [System.Management.Automation.Language.Parser]::ParseFile((Join-Path $sbx 'scripts/task.ps1'), [ref]$null, [ref]$null)
    $bxResolveL = @($bxTaskAstL.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true) | Where-Object { $_.GetCommandName() -eq 'Resolve-ShipReviewerScript' })
    #   The wire is followed PER LEG, never grepped and never pooled. A substring check for the two spellings
    #   this card removed would be green by construction (the grep-for-a-wire failure 17z(T178) refuses), and
    #   a check that only COUNTS resolver calls would still pass with BOTH review invocations wired to the
    #   -Local variable, or with the remote resolver asking for HEAD instead of the pinned sha - the three
    #   shapes R3 round 1 named. So: each resolver call must ask for `-BaseSha $scopeBaseSha` and nothing
    #   else; each review invocation (a command passing -WorktreePath - nothing else in this file takes that
    #   parameter) must take its -File from a variable an assignment filled from the resolver; and each leg
    #   is identified by the BASELINE it compares against - `$Base` is -Local, `$shipBase` is remote - with
    #   the two legs required to hold DIFFERENT variables, so neither leg's resolution can decide the other's.
    $bxRvVars = @()
    $bxRvBadArgL = @()
    foreach ($bxRvSite in $bxResolveL) {
      if (((@($bxRvSite.CommandElements | Select-Object -Skip 1) | ForEach-Object { $_.Extent.Text }) -join ' ') -cne '-BaseSha $scopeBaseSha') { $bxRvBadArgL += $bxRvSite.Extent.Text }
      $bxRvNode = $bxRvSite
      while ($bxRvNode -and -not ($bxRvNode -is [System.Management.Automation.Language.AssignmentStatementAst])) { $bxRvNode = $bxRvNode.Parent }
      if ($bxRvNode) { $bxRvVars += [string]$bxRvNode.Left.VariablePath.UserPath }
    }
    $bxRevCallsL = @($bxTaskAstL.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true) |
      Where-Object { @($_.CommandElements | ForEach-Object { $_.Extent.Text }) -contains '-WorktreePath' })
    $bxUnwiredL = @()
    $bxLegWireL = @()
    foreach ($bxRc in $bxRevCallsL) {
      $bxEls = @($bxRc.CommandElements)
      $bxFileIdx = -1; $bxBaseIdx = -1
      for ($bxI = 0; $bxI -lt $bxEls.Count; $bxI++) {
        if ($bxEls[$bxI].Extent.Text -eq '-File') { $bxFileIdx = $bxI }
        if ($bxEls[$bxI].Extent.Text -eq '-Base') { $bxBaseIdx = $bxI }
      }
      $bxArgL = if (($bxFileIdx -ge 0) -and (($bxFileIdx + 1) -lt $bxEls.Count)) { $bxEls[$bxFileIdx + 1] } else { $null }
      $bxBaseTxtL = if (($bxBaseIdx -ge 0) -and (($bxBaseIdx + 1) -lt $bxEls.Count)) { $bxEls[$bxBaseIdx + 1].Extent.Text } else { '(no -Base)' }
      if (-not ($bxArgL -is [System.Management.Automation.Language.VariableExpressionAst]) -or ($bxRvVars -notcontains [string]$bxArgL.VariablePath.UserPath)) { $bxUnwiredL += $bxRc.Extent.Text; continue }
      # WHICH MODE this invocation belongs to, read from the `if` clause that encloses it rather than from
      # its position: the mandatory one is under `$reviewRun.Blocking`, the advisory one under
      # `$reviewRun.Run`. A count alone accepts one mode being replaced by a duplicate of its sibling, which
      # deletes a review while every count stays right (R3 round 3).
      $bxModeS = ''
      $bxAncS = $bxRc.Parent
      while ($bxAncS -and -not $bxModeS) {
        if ($bxAncS -is [System.Management.Automation.Language.IfStatementAst]) {
          foreach ($bxClS in $bxAncS.Clauses) {
            if (($bxRc.Extent.StartOffset -ge $bxClS.Item2.Extent.StartOffset) -and ($bxRc.Extent.EndOffset -le $bxClS.Item2.Extent.EndOffset)) {
              if ($bxClS.Item1.Extent.Text -match '\$reviewRun\.Blocking') { $bxModeS = 'blocking' }
              elseif ($bxClS.Item1.Extent.Text -match '\$reviewRun\.Run') { $bxModeS = 'advisory' }
            }
          }
        }
        $bxAncS = $bxAncS.Parent
      }
      $bxLegWireL += , ([pscustomobject]@{ Base = $bxBaseTxtL; Var = [string]$bxArgL.VariablePath.UserPath; Mode = $(if ($bxModeS) { $bxModeS } else { '(no mode branch)' }) })
    }
    $bxLocalWireL = @($bxLegWireL | Where-Object { $_.Base -ceq '$Base' })
    $bxRemoteWireL = @($bxLegWireL | Where-Object { $_.Base -ceq '$shipBase' })
    $bxLocalVarsL = @($bxLocalWireL | ForEach-Object { $_.Var } | Select-Object -Unique)
    $bxRemoteVarsL = @($bxRemoteWireL | ForEach-Object { $_.Var } | Select-Object -Unique)
    $bxLocalModesL = ((@($bxLocalWireL | ForEach-Object { $_.Mode }) | Sort-Object) -join ',')
    $bxRemoteModesL = ((@($bxRemoteWireL | ForEach-Object { $_.Mode }) | Sort-Object) -join ',')
    #   EACH LEG HAS TWO MODES - a mandatory one under ReviewGate='required' and the advisory one a card's
    #   own review_gate asks for - and counting invocations per leg is what closes the hole a per-leg
    #   VARIABLE count leaves open: delete one mode's invocation and the surviving one still reports a
    #   single variable for that baseline (R3 round 2). The invocation must also sit inside the statement
    #   block that ASSIGNED the variable it runs, so a mode cannot borrow the other leg's resolution and
    #   still read as wired.
    $bxRvScopeL = @{}
    foreach ($bxRvSite in $bxResolveL) {
      $bxRvNodeS = $bxRvSite
      while ($bxRvNodeS -and -not ($bxRvNodeS -is [System.Management.Automation.Language.AssignmentStatementAst])) { $bxRvNodeS = $bxRvNodeS.Parent }
      if (-not $bxRvNodeS) { continue }
      $bxBlkS = $bxRvNodeS
      while ($bxBlkS -and -not ($bxBlkS -is [System.Management.Automation.Language.StatementBlockAst])) { $bxBlkS = $bxBlkS.Parent }
      if ($bxBlkS) { $bxRvScopeL[[string]$bxRvNodeS.Left.VariablePath.UserPath] = $bxBlkS.Extent }
    }
    $bxOutOfScopeL = @()
    foreach ($bxRc in $bxRevCallsL) {
      $bxEls = @($bxRc.CommandElements)
      $bxFileIdx = -1
      for ($bxI = 0; $bxI -lt $bxEls.Count; $bxI++) { if ($bxEls[$bxI].Extent.Text -eq '-File') { $bxFileIdx = $bxI } }
      if ($bxFileIdx -lt 0 -or (($bxFileIdx + 1) -ge $bxEls.Count)) { continue }
      $bxArgS = $bxEls[$bxFileIdx + 1]
      if (-not ($bxArgS -is [System.Management.Automation.Language.VariableExpressionAst])) { continue }
      $bxVarS = [string]$bxArgS.VariablePath.UserPath
      if (-not $bxRvScopeL.ContainsKey($bxVarS)) { continue }
      $bxScopeS = $bxRvScopeL[$bxVarS]
      if (($bxRc.Extent.StartOffset -lt $bxScopeS.StartOffset) -or ($bxRc.Extent.EndOffset -gt $bxScopeS.EndOffset)) { $bxOutOfScopeL += $bxRc.Extent.Text }
    }
    if ($bxResolveL.Count -ne 2) { Fail "17b'(L) scripts/task.ps1 makes $($bxResolveL.Count) real call(s) to Resolve-ShipReviewerScript, not the two the ship has legs for (searched from the AST, so a mention in a comment or a string does not count). A leg that does not ask for the base copy is a leg reviewing the tree it is judging, and the remote one is judged here or nowhere."; $bxOk = $false }
    elseif ($bxRvBadArgL.Count -ne 0) { Fail "17b'(L) a Resolve-ShipReviewerScript call asks for something other than the sha the scope gate pinned: $($bxRvBadArgL -join ' | '). `-BaseSha `$scopeBaseSha` is what makes the reviewer, the allow_paths, the tier and the budget come from ONE commit; HEAD or a ref name is a reviewer from a tree nothing else was judged against."; $bxOk = $false }
    elseif (@($bxRvVars | Select-Object -Unique).Count -ne 2) { Fail "17b'(L) the two Resolve-ShipReviewerScript calls assign to $(@($bxRvVars | Select-Object -Unique).Count) distinct variable(s), not two - one leg's resolution would then decide the other's, or one of them is not assigned at all and what that leg hands the reviewer cannot be read."; $bxOk = $false }
    elseif ($bxRevCallsL.Count -lt 2) { Fail "17b'(L) task.ps1 makes $($bxRevCallsL.Count) review invocation(s) (a command passing -WorktreePath), fewer than the two legs it has - this case can no longer see whether both legs are wired to the base copy."; $bxOk = $false }
    elseif ($bxUnwiredL.Count -ne 0) { Fail "17b'(L) a review invocation does not take its -File from a variable the resolver filled: $($bxUnwiredL -join ' | '). That is a leg running a reviewer out of a checkout - the worktree's own copy on the -Local leg, the main checkout's on the remote one - which is the split T288 exists to end."; $bxOk = $false }
    elseif ($bxLocalVarsL.Count -ne 1) { Fail "17b'(L) the -Local review invocations (the ones comparing against `$Base) take their -File from $($bxLocalVarsL.Count) distinct resolver variable(s), not one: $($bxLocalVarsL -join ', '). Either that leg is gone from this file or its two modes disagree about which base copy they run."; $bxOk = $false }
    elseif ($bxRemoteVarsL.Count -ne 1) { Fail "17b'(L) the REMOTE review invocations (the ones comparing against `$shipBase) take their -File from $($bxRemoteVarsL.Count) distinct resolver variable(s), not one: $($bxRemoteVarsL -join ', '). The remote leg cannot be executed from a hermetic fixture, so this is the only place its wiring is judged - and a count that pooled both legs would accept it being deleted or wired to the -Local one."; $bxOk = $false }
    elseif ($bxLocalVarsL[0] -ceq $bxRemoteVarsL[0]) { Fail "17b'(L) both legs run the reviewer held in `$$($bxLocalVarsL[0]) - one leg's resolution decides the other's, and the leg this fixture cannot execute is then proved by the leg it can."; $bxOk = $false }
    elseif ($bxLocalModesL -cne 'advisory,blocking') { Fail "17b'(L) the -Local leg's review invocations classify as [$bxLocalModesL], not exactly one advisory and one blocking. Each leg has two modes - the mandatory one under `$reviewRun.Blocking and the advisory one under `$reviewRun.Run - and the mode is read from the `if` clause that encloses each call, so a mode replaced by a duplicate of its sibling (which deletes a review while every count stays right) is seen here."; $bxOk = $false }
    elseif ($bxRemoteModesL -cne 'advisory,blocking') { Fail "17b'(L) the REMOTE leg's review invocations classify as [$bxRemoteModesL], not exactly one advisory and one blocking. This leg never runs in a hermetic fixture, so a mode deleted or duplicated there is invisible everywhere else in the suite."; $bxOk = $false }
    elseif ($bxOutOfScopeL.Count -ne 0) { Fail "17b'(L) a review invocation runs a resolver variable assigned OUTSIDE its own control-flow branch: $($bxOutOfScopeL -join ' | '). A mode that borrows the other leg's resolution reads as wired while taking its reviewer from a leg that answered a different question."; $bxOk = $false }
    $bxStartL = (& pwsh -NoProfile -File (Join-Path $sbx 'scripts/task.ps1') -TaskId 'T0-BASEREV' -Phase start 2>&1 | Out-String)
    $bxWtL = Join-Path $sbx 'wt/T0-BASEREV'
    if (-not (Test-Path $bxWtL)) {
      $bxStartLTail = ($bxStartL -replace '\s+', ' ').Trim(); if ($bxStartLTail.Length -gt 400) { $bxStartLTail = $bxStartLTail.Substring($bxStartLTail.Length - 400) }
      Fail "17b'(L) fixture start produced no worktree for the base-reviewer card - a setup failure, so this case proves nothing about which copy of review.ps1 ran. Start output tail=$bxStartLTail"
      $bxOk = $false
    } else {
      Set-Content (Join-Path $bxWtL 'seed-b.txt') 'change under review for T0-BASEREV' -Encoding utf8
      # Keep the original body below an early exit: replacing the whole reviewer exceeds this
      # project's retained diff-size gate and would test a tool_error rather than reviewer provenance.
      $bxPlantPathL = Join-Path $bxWtL 'scripts/review.ps1'
      $bxOriginalL = [IO.File]::ReadAllText($bxPlantPathL)
      $bxPlantTokensL = $null; $bxPlantErrorsL = $null
      $bxPlantAstL = [System.Management.Automation.Language.Parser]::ParseInput($bxOriginalL, [ref]$bxPlantTokensL, [ref]$bxPlantErrorsL)
      if ($bxPlantErrorsL.Count -gt 0 -or $bxPlantAstL.EndBlock.Statements.Count -eq 0) { throw "17b'(L) fixture reviewer has no parseable executable body." }
      $bxInsertL = $bxPlantAstL.EndBlock.Statements[0].Extent.StartOffset
      $bxApproveL = @'
# PLANTED-WORKTREE-REVIEWER: approves everything, asks no backend, exits 0. If any ship ever runs THIS copy,
# the reviewer lives inside the tree it judges and a card repairing review.ps1 reviews itself.
New-Item -ItemType Directory -Force (Join-Path $WorktreePath '.review') | Out-Null
'{"verdict":"pass","reasons":[],"axes":{"spec":{"verdict":"pass","reasons":[]},"standards":{"verdict":"pass","reasons":[]}}}' |
  Set-Content (Join-Path $WorktreePath '.review/T0-BASEREV.json') -Encoding utf8
exit 0
'@
      [IO.File]::WriteAllText($bxPlantPathL, $bxOriginalL.Insert($bxInsertL, $bxApproveL + "`n"), [Text.UTF8Encoding]::new($false))
      $bxBaseShaL = "$(& git -C $sbx rev-parse --verify --quiet 'refs/heads/master^{commit}' 2>$null)".Trim()
      # The reviewer is a bundle, not one file: review.ps1 dot-sources _config/_gitbase/_encoding and, on
      # status publication, _guard (which itself needs _lessons). Reproduce a mutable-main split without a
      # race by letting the private task process load its normal config, then dirtying RepoRoot/_config.ps1
      # immediately before Resolve-ShipReviewerScript. The dirty dependency selects an approve backend; the
      # committed BASE config selects the already-committed blocking backend above. Therefore only a resolver
      # that materialises ALL required siblings from $bxBaseShaL can keep reaching `fixture spec finding`.
      $bxBaseStubL = "$(& git -C $sbx show "${bxBaseShaL}:review-stub.ps1" 2>$null | Out-String)"
      $bxBaseBundleRowsL = @(& git --no-replace-objects -C $sbx ls-tree -r --full-tree $bxBaseShaL -- scripts 2>$null)
      $bxBaseBundleFilesL = @($bxBaseBundleRowsL | ForEach-Object {
        if ([string]$_ -match '^100(?:644|755) blob [0-9a-fA-F]{40}\t(?<path>.+)$') {
          $bxBundlePathL = $Matches.path
          if ($bxBundlePathL -ceq 'scripts/review.ps1' -or $bxBundlePathL -match '^scripts/_[^/]+\.ps1$') { $bxBundlePathL }
        }
      } | Sort-Object -Unique)
      $bxBaseBundleCountL = $bxBaseBundleFilesL.Count
      $bxDirtyStubL = Join-Path $sbx 'review-dirty-stub-17bL.ps1'
      Set-Content $bxDirtyStubL @'
[Console]::In.ReadToEnd() | Out-Null
'{"verdict":"pass","reasons":[],"axes":{"spec":{"verdict":"pass","reasons":[]},"standards":{"verdict":"pass","reasons":[]}}}' | Set-Content $env:REVIEW_OUT -Encoding utf8
'@ -Encoding utf8
      $bxConfigOriginalL = [IO.File]::ReadAllText($cfgX)
      $bxTaskPathL = Join-Path $sbx 'scripts/task.ps1'
      $bxTaskOriginalL = [IO.File]::ReadAllText($bxTaskPathL)
      $bxBaseCommandL = "ReviewCommand = 'pwsh -NoProfile -File $($stubX -replace '\\','/')'"
      $bxDirtyCommandL = "ReviewCommand = 'pwsh -NoProfile -File $($bxDirtyStubL -replace '\\','/')'"
      $bxConfigDirtyL = $bxConfigOriginalL.Replace($bxBaseCommandL, $bxDirtyCommandL)
      $bxResolveAnchorL = '        $rvLocal = if ($reviewAvail -and ($reviewRun.Blocking -or $reviewRun.Run)) { Resolve-ShipReviewerScript -BaseSha $scopeBaseSha } else { '''' }'
      $bxDirtyBytesL = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($bxConfigDirtyL))
      $bxDirtyWriteL = "        [IO.File]::WriteAllBytes((Join-Path `$RepoRoot 'scripts/_config.ps1'), [Convert]::FromBase64String('$bxDirtyBytesL')) # SELFTEST-17bL-DIRTY-DEPENDENCY`n"
      $bxTaskDirtyL = $bxTaskOriginalL.Replace($bxResolveAnchorL, $bxDirtyWriteL + $bxResolveAnchorL)
      $bxBundleSetupL = ($bxBaseStubL -match 'fixture spec finding') -and ($bxBaseBundleFilesL -contains 'scripts/_cards.ps1') -and ($bxBaseBundleFilesL -contains 'scripts/_scope.ps1') -and ($bxConfigDirtyL -cne $bxConfigOriginalL) -and ($bxTaskDirtyL -cne $bxTaskOriginalL) -and (($bxTaskOriginalL.Split($bxResolveAnchorL).Count - 1) -eq 1)
      if (-not $bxBundleSetupL) { Fail "17b'(L/dependencies) setup could not prove the blocking backend is committed at $bxBaseShaL or install the one-shot dirty-dependency boundary; the bundle test would be vacuous."; $bxOk = $false }
      else { [IO.File]::WriteAllText($bxTaskPathL, $bxTaskDirtyL, [Text.UTF8Encoding]::new($false)) }
      $bxMergesL = @(& git -C $sbx rev-list --merges HEAD 2>$null).Count
      # ACCEPTANCE ITEM 1 ALSO SAYS "removed on every exit path", and nothing here OBSERVED that directory
      # (R3 round 1, finding 2). Both ships below run with TEMP and TMP pointed at a directory of this
      # fixture's own, so the copy the resolver materialises has exactly one place it can be, and it is
      # counted after a ship that THREW (the tier-S refusal below) and after one that RETURNED (the tier-1
      # advisory merge, which also re-proves the sentinel so the count is not taken over a path where no
      # reviewer was ever resolved). The environment is restored in a finally: every later case in this
      # gate builds fixtures under the real temp root.
      $bxTmpL = Join-Path $sbx 'r3tmp'
      if (Test-Path $bxTmpL) { Remove-Item -Recurse -Force $bxTmpL }
      New-Item -ItemType Directory -Force $bxTmpL | Out-Null
      $bxTmpSaveL = $env:TEMP; $bxTmpSave2L = $env:TMP
      try {
        $env:TEMP = $bxTmpL; $env:TMP = $bxTmpL
        try {
          $bxOutL = (& pwsh -NoProfile -File $encWrapX -Tid 'T0-BASEREV' 2>&1 | Out-String)
          $bxExitL = $LASTEXITCODE
          $bxDirtyAppliedL = ([IO.File]::ReadAllText($cfgX) -ceq $bxConfigDirtyL)
          $bxMergedL = (@(& git -C $sbx rev-list --merges HEAD 2>$null).Count) -gt $bxMergesL
          $bxLeftThrowL = @(Get-ChildItem -LiteralPath $bxTmpL -Directory -Filter 'scaffold-r3-base-*' -ErrorAction SilentlyContinue)
        }
        finally {
          [IO.File]::WriteAllText($cfgX, $bxConfigOriginalL, [Text.UTF8Encoding]::new($false))
          [IO.File]::WriteAllText($bxTaskPathL, $bxTaskOriginalL, [Text.UTF8Encoding]::new($false))
        }
        Set-Content (Join-Path (Join-Path $sbx 'wt/T1-TIERONE') 'seed.txt') 'a second change for the tier-1 card' -Encoding utf8
        $bxOutPassL = (& pwsh -NoProfile -File $encWrapX -Tid 'T1-TIERONE' 2>&1 | Out-String)
        $bxExitPassL = $LASTEXITCODE
        $bxLeftPassL = @(Get-ChildItem -LiteralPath $bxTmpL -Directory -Filter 'scaffold-r3-base-*' -ErrorAction SilentlyContinue)
      }
      finally { $env:TEMP = $bxTmpSaveL; $env:TMP = $bxTmpSave2L }
      $bxTailPassL = ($bxOutPassL -replace '\s+', ' ').Trim(); if ($bxTailPassL.Length -gt 400) { $bxTailPassL = $bxTailPassL.Substring($bxTailPassL.Length - 400) }
      $bxPlantL = Join-Path $bxWtL 'scripts/review.ps1'
      $bxPlantedL = (Test-Path -LiteralPath $bxPlantL) -and ((Get-Content -Raw -LiteralPath $bxPlantL) -match 'PLANTED-WORKTREE-REVIEWER')
      $bxTailL = ($bxOutL -replace '\s+', ' ').Trim(); if ($bxTailL.Length -gt 400) { $bxTailL = $bxTailL.Substring($bxTailL.Length - 400) }
      if (-not $bxBundleSetupL -or -not $bxDirtyAppliedL) { Fail "17b'(L/dependencies) control: the committed blocking backend or the deterministic dirty _config boundary was not observed, so this run did not distinguish a pinned dependency bundle from mutable RepoRoot siblings."; $bxOk = $false }
      elseif (-not $bxPlantedL) { Fail "17b'(L) control: the approve-everything review.ps1 is not in the worktree after the ship, so 'the base copy ran' would be satisfied by there being no other copy to run. Setup failure, not a verdict."; $bxOk = $false }
      elseif ($bxBaseShaL -notmatch '^[0-9a-f]{40}$') { Fail "17b'(L) could not read the fixture base sha (got '$bxBaseShaL'), so the sentinel cannot be checked against the commit the reviewer must come from. Setup failure, not a verdict."; $bxOk = $false }
      elseif ($bxOutL -notmatch [regex]::Escape("[R3-REVIEWER-FROM-BASE] sha=$bxBaseShaL")) { Fail "17b'(L) seeded defect: the ship did not announce [R3-REVIEWER-FROM-BASE] sha=$bxBaseShaL - the reviewer was not taken from the base commit the scope gate pinned, or the sentinel an operator routes on is gone. Output tail=$bxTailL"; $bxOk = $false }
      elseif ($bxOutL -notmatch [regex]::Escape("[R3-REVIEWER-BUNDLE-VERIFIED] sha=$bxBaseShaL files=$bxBaseBundleCountL")) { Fail "17b'(L/dependencies) the ship did not verify all $bxBaseBundleCountL baseline reviewer files (review.ps1 + every scripts/_*.ps1, including _cards/_scope). A hand-picked dependency list can silently run a mixed evaluator when review.ps1 grows another sibling. Output tail=$bxTailL"; $bxOk = $false }
      elseif ($bxExitL -eq 0) { Fail "17b'(L) seeded defect: a tier-S ship whose worktree carries a review.ps1 that approves everything exited 0 - the reviewer under the tree being judged decided this ship, which is the self-review docs/HARNESS-REVIEW.md forbids. Output tail=$bxTailL"; $bxOk = $false }
      elseif ($bxOutL -notmatch 'R3-SPEC-BLOCK') { Fail "17b'(L) the ship refused but printed no [R3-SPEC-BLOCK], so it stopped at some other gate and this case is no longer measuring which reviewer ran. Output tail=$bxTailL"; $bxOk = $false }
      elseif ($bxOutL -notmatch 'fixture spec finding') { Fail "17b'(L) the refusal carries none of the base reviewer's reasons - the verdict that stopped this ship was written by something other than the stub backend the base copy drives. Output tail=$bxTailL"; $bxOk = $false }
      elseif ($bxMergedL) { Fail "17b'(L) seeded defect: the ship refused and a merge commit appeared anyway - the refusal happens after the merge, which is not a refusal."; $bxOk = $false }
      elseif ($bxLeftThrowL.Count -ne 0) { Fail "17b'(L) seeded defect: the ship THREW and left $($bxLeftThrowL.Count) base-reviewer director(ies) behind in its temp root ($($bxLeftThrowL.Name -join ', ')). 'Removed on every exit path' includes the path a refusal takes, and a copy left there is a pinned reviewer outliving the run that pinned it."; $bxOk = $false }
      elseif ($bxExitPassL -ne 0) { Fail "17b'(L) control: the tier-1 ship that should RETURN cleanly exited $bxExitPassL, so the successful-path half of the cleanup assertion never ran. Setup failure, not a verdict. Output tail=$bxTailPassL"; $bxOk = $false }
      elseif ($bxOutPassL -notmatch 'R3-REVIEWER-FROM-BASE') { Fail "17b'(L) control: the tier-1 ship printed no [R3-REVIEWER-FROM-BASE], so no reviewer copy was ever materialised on that path and 'nothing left behind' is satisfied by nothing having been created. Output tail=$bxTailPassL"; $bxOk = $false }
      elseif ($bxLeftPassL.Count -ne 0) { Fail "17b'(L) seeded defect: a ship that RETURNED left $($bxLeftPassL.Count) base-reviewer director(ies) behind ($($bxLeftPassL.Name -join ', ')) - the -Local leg returns from inside the try, and the removal has to survive that return as well as a throw."; $bxOk = $false }
    }
    # M. THE CARD THE REVIEWER JUDGES IS READ FROM THE BASE (T290). Everything above binds to the BASE copy
    #   of the card - the scope gate, the computed tier, and the arbitration ruling case I records - while
    #   review.ps1 read the WORKTREE copy, so an amendment or a ruling landed on the base was invisible to the
    #   reviewer until the branch merged the base, and the next round repeated the previous verdict verbatim.
    #   Measured four times across this arc (T279, T284, T285, T287), and each such round cost one frozen-tree
    #   acceptance. The fixture makes the two copies DISAGREE: the acceptance list is amended on the base only,
    #   the worktree copy keeps the stale text, and the prompt the stub reviewer actually receives must carry
    #   the base text and none of the stale one. A text anchor cannot see this - both strings sit in the tree
    #   either way (L325) - so it is asserted on the DELIVERED prompt, the way 17j asserts the diff reached the
    #   backend. The stale copy is left UNCOMMITTED on purpose: committed, it would enter the diff this same
    #   prompt carries and the absence assertion would be measuring the diff rather than the card.
    Set-Content $stubX @'
$t = [Console]::In.ReadToEnd()
$t | Set-Content -Path ($env:REVIEW_OUT + '.prompt.txt') -Encoding utf8
'{"verdict":"pass","reasons":[],"axes":{"spec":{"verdict":"pass","reasons":[]},"standards":{"verdict":"pass","reasons":[]}}}' | Set-Content -Path $env:REVIEW_OUT -Encoding utf8
'@ -Encoding utf8
    if (-not (Test-Path $bxWtS)) { Fail "17b'(M) the tier-S worktree is gone, so the base-versus-worktree card read cannot be driven at all."; $bxOk = $false }
    else {
      $bxBaseMarkM = 'BASE-CARD-ACCEPTANCE-MARK'
      $bxStaleMarkM = 'STALE-WORKTREE-ACCEPTANCE-MARK'
      $bxCardLinesM = {
        param($mark, $note)
        @('---', 'id: T0-TIERS', "title: seed 17b' tier-S spec-axis block", 'status: todo',
          'review_gate: codex {verdict:pass}',
          'dod_command: "pwsh -NoProfile -Command exit 0"',
          'acceptance:', ('  - "A1 {0} - {1}"' -f $mark, $note), '  - "A2 the fixture reviewer writes a verdict."', '  - "A3 the ship reports the decision."', 'allow_paths:',
          '  - seed-s.txt', '  - scripts/task.ps1', '---') -join "`n"
      }
      (& $bxCardLinesM $bxBaseMarkM 'the amendment landed on the base after this branch was cut') |
        Set-Content (Join-Path $sbx 'specs/tasks/T0-TIERS.md') -Encoding utf8
      & git -C $sbx add specs/tasks/T0-TIERS.md 2>$null
      & git -C $sbx -c user.email='selftest@local' -c user.name='selftest' commit -q -m "17b'(M) acceptance amended on the base card only" *> $null
      (& $bxCardLinesM $bxStaleMarkM 'the text the branch was cut with') |
        Set-Content (Join-Path $bxWtS 'specs/tasks/T0-TIERS.md') -Encoding utf8
      # A non-empty, non-markdown payload: the cases above merged this branch into master, and an empty diff
      # would either fail closed or be routed around the reviewer by ReviewSkipWhen, leaving no prompt to read.
      Set-Content (Join-Path $bxWtS 'seed-s.txt') "change under review for 17b'(M)" -Encoding utf8
      & git -C $bxWtS add seed-s.txt 2>$null
      & git -C $bxWtS -c user.email='selftest@local' -c user.name='selftest' commit -q -m "17b'(M) payload" *> $null
      $bxPromptPathM = Join-Path $bxWtS '.review/T0-TIERS.json.prompt.txt'
      if (Test-Path $bxPromptPathM) { Remove-Item -Force $bxPromptPathM }
      $bxOutM = (& pwsh -NoProfile -File (Join-Path $sbx 'scripts/review.ps1') -WorktreePath $bxWtS -Base master -LocalBase 2>&1 | Out-String)
      $bxPromptM = Get-Content $bxPromptPathM -Raw -ErrorAction SilentlyContinue
      $bxTailM = ($bxOutM -replace '\s+', ' ').Trim(); if ($bxTailM.Length -gt 400) { $bxTailM = $bxTailM.Substring($bxTailM.Length - 400) }
      if (-not $bxPromptM) { Fail "17b'(M) the stub reviewer received no prompt at all ($bxPromptPathM is absent), so what the reviewer was handed cannot be judged - review.ps1 failed before invoking a backend, or the diff was routed around one. Output tail=$bxTailM"; $bxOk = $false }
      elseif ($bxPromptM -notmatch [regex]::Escape($bxBaseMarkM)) { Fail "17b'(M) seeded defect: the amendment committed on the BASE card never reached the reviewer prompt. A ruling or an amendment written where the ship reads it is then invisible to the reviewer until the branch merges the base, and the next round repeats the previous verdict - the defect T290 repairs. Output tail=$bxTailM"; $bxOk = $false }
      elseif ($bxPromptM -match [regex]::Escape($bxStaleMarkM)) { Fail "17b'(M) seeded defect: the STALE worktree copy of the card reached the reviewer prompt. The reviewer is judging a different card text from the one the scope gate, the tier and the arbitration all bind to, which is exactly the split this case exists to close. Output tail=$bxTailM"; $bxOk = $false }
      elseif ($bxOutM -notmatch '\[R3-CARD-FROM-BASE\] sha=[0-9a-f]{7,40}') { Fail "17b'(M) the card came from the base but nothing announced it with [R3-CARD-FROM-BASE] and the sha it was read at - an operator reading a verdict cannot tell which card text it was judged against, and a silent fallback to the worktree copy would be indistinguishable from this. Output tail=$bxTailM"; $bxOk = $false }
      # THE BASE-ABSENT HALF of the same acceptance item, DRIVEN rather than grepped (R3 round 1, finding 2).
      # A card the base does not carry is the other state review.ps1 has to answer for, and until this leg it
      # was only text-anchored - the sentinel existed in the file and no fixture ever executed the branch.
      # Removing the card from the BASE alone leaves the branch's own copy on disk in the worktree, which is
      # exactly the shape the fallback exists for, and the SAME TWO MARKERS now have to come out the other way
      # round: the stale worktree text is what reaches the prompt, and [R3-CARD-FROM-WORKTREE] is what is
      # announced. A base read that silently returned the worktree text, or a fallback that read the base
      # anyway, passes one leg and fails the other; nothing passes both by accident.
      & git -C $sbx rm -q -f specs/tasks/T0-TIERS.md *> $null
      & git -C $sbx -c user.email='selftest@local' -c user.name='selftest' commit -q -m "17b'(M) the base no longer carries this card" *> $null
      # A fresh payload for the same reason the first leg needs one: an empty diff is routed around the
      # reviewer and no prompt would be built at all.
      Set-Content (Join-Path $bxWtS 'seed-s.txt') "second change under review for 17b'(M)" -Encoding utf8
      & git -C $bxWtS add seed-s.txt 2>$null
      & git -C $bxWtS -c user.email='selftest@local' -c user.name='selftest' commit -q -m "17b'(M) payload for the base-absent leg" *> $null
      if (Test-Path $bxPromptPathM) { Remove-Item -Force $bxPromptPathM }
      $bxOutM2 = (& pwsh -NoProfile -File (Join-Path $sbx 'scripts/review.ps1') -WorktreePath $bxWtS -Base master -LocalBase 2>&1 | Out-String)
      $bxPromptM2 = Get-Content $bxPromptPathM -Raw -ErrorAction SilentlyContinue
      $bxTailM2 = ($bxOutM2 -replace '\s+', ' ').Trim(); if ($bxTailM2.Length -gt 400) { $bxTailM2 = $bxTailM2.Substring($bxTailM2.Length - 400) }
      if ((& git -C $sbx cat-file -e 'master:specs/tasks/T0-TIERS.md' 2>&1 | Out-String) -notmatch '\S') { Fail "17b'(M/absent) control: the card is still on the base after the removal, so this leg is running the base-PRESENT path again and proves nothing about the fallback. Setup failure, not a verdict."; $bxOk = $false }
      elseif (-not $bxPromptM2) { Fail "17b'(M/absent) the stub reviewer received no prompt at all, so what it was handed cannot be judged - review.ps1 fail-closed on a card the base does not carry instead of falling back, or the diff was routed around the reviewer. Output tail=$bxTailM2"; $bxOk = $false }
      elseif ($bxPromptM2 -notmatch [regex]::Escape($bxStaleMarkM)) { Fail "17b'(M/absent) seeded defect: with no card on the base, the worktree copy did NOT reach the reviewer prompt - the fallback acceptance item 1 keeps is gone, and a card that exists only on a branch would now be reviewed with no card context at all, which is a strictly worse review than before this change. Output tail=$bxTailM2"; $bxOk = $false }
      elseif ($bxOutM2 -match '\[R3-CARD-FROM-BASE\]') { Fail "17b'(M/absent) the run announced [R3-CARD-FROM-BASE] although the base carries no such card - the sentinel is printed unconditionally rather than from which source actually answered, so it tells an operator nothing. Output tail=$bxTailM2"; $bxOk = $false }
      elseif ($bxOutM2 -notmatch '\[R3-CARD-FROM-WORKTREE\]') { Fail "17b'(M/absent) the fallback ran and said nothing - a review judged against the branch's own card text is indistinguishable from one judged against the base's, which is the ambiguity both sentinels exist to end. Output tail=$bxTailM2"; $bxOk = $false }
    }
    if ($bxOk) { Write-Host "  17b' two-axis verdict end to end OK (tier-S card: a spec-axis block throws [R3-SPEC-BLOCK], merges nothing and files a ledger row; tier-1 card: the same verdict only warns [R3-ADVISORY-NONZERO] and merges; a verdict carrying no axes normalises to both axes holding the top-level one; a top-level block with two clean axes stays a block and keeps its reasons; a spec block whose reason carries a brace still refuses; a standards-only block on the same tier-S card merges; an undecidable tier falls back to advisory with [R3-SPEC-TIER-UNKNOWN]; both ship legs take the one decision with the same arguments, guard and throw; a base-card maker ruling bound to the reviewed sha is INERT at one recorded round and, at two, prints [R3-SPEC-ARBITRATED], files a ledger row and merges; the same ruling on a computed tier-0 card changes nothing at all; and five malformed round histories - no branch, a foreign branch, an index gap, and a duplicate index both above and below an already-counted round - each leave the block standing while the healthy one arbitrates; the two extracted helpers' declared examples are green; and a review.ps1 planted in the worktree that approves everything does not review its own ship - the base copy runs, named by [R3-REVIEWER-FROM-BASE], each leg wired to its own resolver variable asking for the pinned sha, and the copy is gone from an isolated temp root after a ship that threw and after one that returned; and an acceptance list amended on the BASE card alone reaches the reviewer prompt while the stale worktree copy does not, announced as [R3-CARD-FROM-BASE] with the sha it was read at, while removing that card from the base alone flips both markers the other way and announces [R3-CARD-FROM-WORKTREE] instead)" -ForegroundColor Green }

    # 17c. init 对含撇号 ProjectName 须产出**可解析**的 _config.ps1（证 #7：撇号 brick 已堵）。
    #   TD15：init-scaffold.ps1 本身随下游保留（未随 selftest.ps1 一起自动删），但文档明示用户可手动删它；
    #   若已被手动删除，本闸测的元仓专属 init 机制已不适用于该仓，优雅跳过而非误判失败。
    if (-not (Test-Path (Join-Path $RepoRoot 'init-scaffold.ps1'))) {
      Write-Host '  17c 跳过（无 init-scaffold.ps1——已被手动清理，正常）。' -ForegroundColor DarkGray
    } else {
      $sc = Join-Path $sd 'c'
      Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $sc -Recurse -Force
      & pwsh -NoProfile -File (Join-Path $sc 'init-scaffold.ps1') -ProjectName "O'Brien Studio" -GhAccount smoke *> $null
      $cfgC = Join-Path $sc 'scripts/_config.ps1'
      $cErr = $null
      [void][System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $cfgC).Path, [ref]$null, [ref]$cErr)
      if ($cErr -and $cErr.Count) { Fail "种子缺陷 17c：init 用含撇号 ProjectName 后 _config.ps1 不可解析（撇号 brick 回归 #7）：$($cErr[0].Message)" }
      else { Write-Host '  17c init 含撇号项目名后 _config.ps1 仍可解析 OK' -ForegroundColor Green }
    }

    # 17d. guard-frozen 钩子的**行为**种子（证「冻结一等资产」拦截，非仅语法/存在性）。
    #   钩子 fail-open（恒 exit 0、仅靠 stdout 的 deny JSON 拦截）——输出契约格式漂移会**静默**解除所有冻结保护，
    #   正是 17a/b/c「严重+静默+易复发」要锁的面。同一份钩子喂两种 _config：含冻结点→须 deny（路径 A Edit +
    #   路径 B 删除动词命令）；删除动词 + 非冻结路径→须无输出（写动词与冻结路径**共现**才拦，低误报设计）；空→须无输出（fail-open no-op）。
    $sdGf = Join-Path $sd 'd'
    New-Item -ItemType Directory -Force (Join-Path $sdGf '.claude/hooks') | Out-Null
    New-Item -ItemType Directory -Force (Join-Path $sdGf 'scripts') | Out-Null
    Copy-Item (Join-Path $RepoRoot '.claude/hooks/guard-frozen.ps1') (Join-Path $sdGf '.claude/hooks/') -Force
    $gfHook = Join-Path $sdGf '.claude/hooks/guard-frozen.ps1'
    $gfCfg = Join-Path $sdGf 'scripts/_config.ps1'
    $gfEvt = '{"tool_name":"Edit","tool_input":{"file_path":"contracts/frozen.py"}}'
    Set-Content $gfCfg "`$script:ScaffoldConfig = @{ FrozenPaths = @('contracts/') }" -Encoding utf8
    $gfDeny = ($gfEvt | & pwsh -NoProfile -File $gfHook 2>$null | Out-String)
    if ($gfDeny -notmatch '"permissionDecision"\s*:\s*"deny"') { Fail '种子缺陷 17d：guard-frozen 未对冻结路径输出 deny（冻结守卫回归——输出契约 hookSpecificOutput.permissionDecision 漂移？）。' }
    else { Write-Host '  17d guard-frozen 对冻结路径 Edit 输出 deny OK' -ForegroundColor Green }
    $gfCmdEvt = '{"tool_name":"PowerShell","tool_input":{"command":"Remove-Item contracts/frozen.py"}}'
    $gfCmdDeny = ($gfCmdEvt | & pwsh -NoProfile -File $gfHook 2>$null | Out-String)
    if ($gfCmdDeny -notmatch '"permissionDecision"\s*:\s*"deny"') { Fail '种子缺陷 17d：guard-frozen 未对「删除动词命令 + 冻结路径」输出 deny（路径 B 删除动词回归——写动词正则漂移？）。' }
    else { Write-Host '  17d guard-frozen 对冻结路径删除命令（路径 B）输出 deny OK' -ForegroundColor Green }
    $gfCmdSafe = '{"tool_name":"Bash","tool_input":{"command":"rm docs/scratch.txt"}}'
    $gfSafeOut = ($gfCmdSafe | & pwsh -NoProfile -File $gfHook 2>$null | Out-String).Trim()
    if ($gfSafeOut) { Fail "种子缺陷 17d：删除动词 + 非冻结路径仍被拦（应共现才拦、低误报；实际：$gfSafeOut）。" }
    else { Write-Host '  17d guard-frozen 删除动词 + 非冻结路径无输出（共现才拦）OK' -ForegroundColor Green }
    # 17d(TD49). 命令路径写动词白名单扩展 + 非写动词冻结引用的非阻断警告（TD-112）。
    #   旧白名单漏 git apply/checkout/restore·patch·perl -i → 这些 + 冻结路径共现须 deny（旧码放行=冻结物可绕改）；
    #   非写动词但引用冻结路径（python -c open(w) 类）→ 须发非阻断 defer 警告（不 deny 免误伤只读、不 allow 免自动放行）。
    #   FrozenPaths 仍为 'contracts/'（上一子测设定，尚未清空）。
    foreach ($vc in @(
        'git apply contracts/frozen.py.patch',
        'git checkout -- contracts/frozen.py',
        'git restore contracts/frozen.py',
        'patch -p1 -i contracts/frozen.py.patch',
        "perl -i -pe 's/a/b/' contracts/frozen.py")) {
      $ev = @{ tool_name = 'Bash'; tool_input = @{ command = $vc } } | ConvertTo-Json -Compress
      $o = ($ev | & pwsh -NoProfile -File $gfHook 2>$null | Out-String)
      if ($o -notmatch '"permissionDecision"\s*:\s*"deny"') { Fail "种子缺陷 17d(TD49)：命令『$vc』（写动词 + 冻结路径）未被 deny——写动词白名单漏 git apply/checkout/restore·patch·perl -i（冻结物可经常见命令绕改）。" }
    }
    $gfWarnEvt = @{ tool_name = 'Bash'; tool_input = @{ command = "python -c `"open('contracts/frozen.py','w')`"" } } | ConvertTo-Json -Compress
    $gfWarn = ($gfWarnEvt | & pwsh -NoProfile -File $gfHook 2>$null | Out-String)
    if ($gfWarn -match '"permissionDecision"\s*:\s*"deny"') { Fail '种子缺陷 17d(TD49)：非写动词引用冻结路径被 deny（应非阻断 defer 警告，免误伤只读命令如 cat/Get-Content）。' }
    elseif (($gfWarn -notmatch '"permissionDecision"\s*:\s*"defer"') -or ($gfWarn -notmatch 'additionalContext')) { Fail '种子缺陷 17d(TD49)：非写动词引用冻结路径未发非阻断 defer 警告（python -c open(w) 类静默漏过——defer + additionalContext 缺失）。' }
    else { Write-Host '  17d(TD49) 命令路径写动词扩展 deny + 非写动词冻结引用 defer 警告 OK' -ForegroundColor Green }
    Set-Content $gfCfg "`$script:ScaffoldConfig = @{ FrozenPaths = @() }" -Encoding utf8
    $gfNoop = ($gfEvt | & pwsh -NoProfile -File $gfHook 2>$null | Out-String).Trim()
    if ($gfNoop) { Fail "种子缺陷 17d：空 FrozenPaths 下 guard-frozen 仍输出（应 fail-open no-op；实际：$gfNoop）。" }
    else { Write-Host '  17d guard-frozen 空 FrozenPaths 无输出（fail-open no-op）OK' -ForegroundColor Green }

    # 17e. 账号守卫 host 锚定回归（证 C17 端口容忍 + 拒子串/子域伪装、他人仓 + TD38 路径内嵌 host 伪装）——纯函数、不需 gh/网络：
    #   dot-source _guard.ps1（顶层只 . _config + 定义函数，不触发 gh），直接调 Test-PushTargetOwner 对 accept/reject 串表测。
    #   （旧版从源抠 -notmatch 正则测；TD38 改为解析 authority 的函数后，子串正则已不复存在，故直测函数=更真的行为回归。）
    . (Join-Path $RepoRoot 'scripts/_guard.ps1')
    if (-not (Get-Command Test-PushTargetOwner -ErrorAction SilentlyContinue)) {
      Fail '种子缺陷 17e：_guard.ps1 未定义 Test-PushTargetOwner（结构变了？无法回归 host 锚定 C17/C25/TD38）。'
    }
    else {
      $acceptUrls = @('https://github.com/acct/x.git', 'git@github.com:acct/x.git', 'ssh://git@github.com:22/acct/x.git', 'https://github.com:443/acct/x.git')
      # 后三条 = TD38/评审 TD-101 路径内嵌 host 伪装（旧子串正则误放行；解析 authority 后 host≠github.com → 拒）：
      $rejectUrls = @('https://evilgithub.com/acct/x.git', 'https://github.com.evil.com/acct/x.git', 'https://github.com/other/x.git',
        'https://evil.example/github.com/acct/x.git', 'ssh://git@evil.example/github.com/acct/x.git', 'evil.example:github.com/acct/x.git')
      $eFail = $false
      foreach ($u in $acceptUrls) { if (-not (Test-PushTargetOwner -Url $u -Expected 'acct')) { Fail "种子缺陷 17e：合法个人远端被误拒：$u（C17 端口/host 锚定回归）。"; $eFail = $true } }
      foreach ($u in $rejectUrls) { if (Test-PushTargetOwner -Url $u -Expected 'acct') { Fail "种子缺陷 17e：伪装/越权远端被放行：$u（host 锚定回归；TD38 路径内嵌）。"; $eFail = $true } }
      if (-not $eFail) { Write-Host '  17e 账号守卫 host 锚定 OK（显式端口 + 拒 evilgithub/子域/他人仓/路径内嵌 host 伪装 TD38）' -ForegroundColor Green }
    }

    # 17f. pre-push 钩子体格式（证 C10/C25/C19）：从 gh-bootstrap.ps1 源抠出 here-string，按安装时同样的 CRLF→LF
    #   变换落临时文件，断言 shebang 开头、无 CR、无 UTF-8 BOM（sh 钩子要求），且含 -ExecutionPolicy Bypass 与 -RemoteUrl
    #   与 check-secrets（防泄露闸：裸 git push 也须推送前扫描，与账号守卫同被回归锁死）。
    $ghSrc = Get-Content (Join-Path $RepoRoot 'scripts/gh-bootstrap.ps1') -Raw
    $hb = [regex]::Match($ghSrc, "(?s)\`$hookBody = @'\r?\n(.*?)\r?\n'@")
    if (-not $hb.Success) { Fail '种子缺陷 17f：gh-bootstrap.ps1 未找到 pre-push 钩子体 here-string（结构变了？）。' }
    else {
      $bodyLf = $hb.Groups[1].Value -replace "`r`n", "`n"
      $tmpHook = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-prepush-$PID"
      $bodyLf | Set-Content -Path $tmpHook -NoNewline -Encoding utf8
      $hookBytes = [System.IO.File]::ReadAllBytes($tmpHook)
      Remove-Item $tmpHook -Force -ErrorAction SilentlyContinue
      $hasBom = ($hookBytes.Length -ge 3 -and $hookBytes[0] -eq 0xEF -and $hookBytes[1] -eq 0xBB -and $hookBytes[2] -eq 0xBF)
      $hasCr  = ($hookBytes -contains 0x0D)
      if (-not $bodyLf.StartsWith('#!/bin/sh')) { Fail '种子缺陷 17f：pre-push 钩子体未以 #!/bin/sh 开头。' }
      elseif ($hasBom) { Fail '种子缺陷 17f：pre-push 钩子写出含 UTF-8 BOM（sh 会拒；Set-Content -Encoding utf8 在 pwsh7 应无 BOM）。' }
      elseif ($hasCr)  { Fail '种子缺陷 17f：pre-push 钩子写出含 CR（CRLF 未规整为 LF）。' }
      elseif ($bodyLf -notmatch '-ExecutionPolicy Bypass') { Fail '种子缺陷 17f：pre-push 钩子缺 -ExecutionPolicy Bypass（C10 回归：MOTW/RemoteSigned 下守卫被静默停用）。' }
      elseif ($bodyLf -notmatch '-RemoteUrl') { Fail '种子缺陷 17f：pre-push 钩子缺 -RemoteUrl（C25 回归：只校验 origin、可推非 origin 组织远端绕过）。' }
      elseif ($bodyLf -notmatch 'check-secrets') { Fail '种子缺陷 17f：pre-push 钩子缺 check-secrets（防泄露闸回归：裸 git push 绕过推送前扫描，SECURITY.md §1 失真）。' }
      elseif ($bodyLf -notmatch 'scaffold-prepush-guard') { Fail '种子缺陷 17f：pre-push 钩子缺幂等标记 scaffold-prepush-guard（C05 回归：无法识别本脚手架所装，幂等重跑会把自己当既有钩子备份）。' }
      elseif ($bodyLf -notmatch 'STDIN_CACHE') { Fail '种子缺陷 17f：pre-push 钩子缺 stdin 缓存（C05 回归：链式既有钩子收不到 git 经 stdin 传入的 ref 更新）。' }
      elseif ($bodyLf -notmatch '\.local\*') { Fail '种子缺陷 17f：pre-push 钩子缺链式调用既有钩子（"$0".local* 全部按序调用；C05 回归：既有 pre-push 被静默丢弃、无链式）。' }
      # TD-204 注入面（六条锁全套接线，抗 mutation：分别锁「两个不可信值各自的赋值(from $2/$ROOT) + 消费(经 $env:) + sh 单引号 -Command 边界」；
      #   仅查「有 env 引用」会被「删赋值留引用」或「留赋值却把消费改回 '$ROOT' 原始插值」绕过，故赋值与消费两端都锁）：
      elseif ($bodyLf.Contains("-RemoteUrl '`$2'")) { Fail '种子缺陷 17f(inject/TD-204)：账号守卫仍把远端 URL $2 单引号插进 pwsh -Command（-RemoteUrl ''$2''）——$2 里一个单引号即在 Assert-PersonalAccount 之前于 pwsh parse 期越界执行；须经环境变量传。' }
      elseif ($bodyLf -notmatch 'SCAFFOLD_REMOTE="\$2"') { Fail '种子缺陷 17f(inject/TD-204)：钩子未把 $2（git 远端 URL）赋给 SCAFFOLD_REMOTE="$2"——不可信值须经 env 值（不被 pwsh 解析为代码）传入而非命令文本；缺此赋值 -RemoteUrl 引用的是空/别处值。' }
      elseif ($bodyLf -notmatch 'SCAFFOLD_ROOT="\$ROOT"') { Fail '种子缺陷 17f(inject/TD-204)：钩子未把 $ROOT 赋给 SCAFFOLD_ROOT="$ROOT"——含撇号克隆路径经命令文本插值会破坏 -Command、每次 push 报 parse error。' }
      elseif ($bodyLf -notmatch '-RemoteUrl "\$env:SCAFFOLD_REMOTE"') { Fail '种子缺陷 17f(inject/TD-204)：-RemoteUrl 未消费 $env:SCAFFOLD_REMOTE——即便设了环境变量，-RemoteUrl 仍插值原始 $2 则注入面未堵。' }
      elseif ($bodyLf -notmatch '-RepoRoot "\$env:SCAFFOLD_ROOT"') { Fail '种子缺陷 17f(inject/TD-204)：-RepoRoot 未消费 $env:SCAFFOLD_ROOT——若消费端改回 -RepoRoot ''$ROOT'' 原始插值，撇号克隆路径仍破坏 -Command（可用性回归），root 通道未走不可再解析的 env 值。' }
      elseif (-not $bodyLf.Contains('-Command ''. "$env:SCAFFOLD_ROOT')) { Fail '种子缺陷 17f(inject/TD-204)：pwsh -Command 非「sh 单引号边界 + env-root dot-source」（须 -Command ''. "$env:SCAFFOLD_ROOT…''）——-Command 若改成 sh 双引号，sh 会先展开其中 $env:，安全语义崩溃并可能重开注入面。' }
      else { Write-Host '  17f pre-push 钩子体 OK（shebang / 无 BOM / 无 CR / -ExecutionPolicy Bypass / 账号守卫 $2·$ROOT 各自赋 env 值 + 经 $env: 消费 + sh 单引号 -Command 边界（注入面已堵 TD-204）/ -RemoteUrl / check-secrets / 幂等标记 / stdin 缓存 / 链式 .local*）' -ForegroundColor Green }
    }

    # 17g. R3 评审者 wall-clock 超时（TD11 / C27；实证 L21）：ReviewCommand=挂起后端（Start-Sleep 30，忽略 stdin、
    #   永不写裁决）+ review.ps1 -TimeoutSec 2 → 必须**有界**地杀子进程并 fail-closed block，而非永久卡 ship。
    #   关键断言是**用时**：超时若失效，挂起后端会睡满 30s 才返回（其间 ship 死等）——故断言 exit≠0 且 elapsed 远小于 sleep。
    $sg = Join-Path $sd 'g'
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $sg -Recurse -Force
    $cfgG = Join-Path $sg 'scripts/_config.ps1'
    # 挂起评审者：睡 30s、永不写 $env:REVIEW_OUT。用 .Replace（非 -replace）避免替换语义。
    $cg = (Get-Content $cfgG -Raw).Replace("ReviewCommand = ''", "ReviewCommand = 'Start-Sleep 30'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if ($cg -notmatch 'Start-Sleep') { Fail '闸17g：挂起 ReviewCommand 未注入（_config 行格式变了？）——否则改撞真 codex，测的不再是「挂起评审者必被超时杀掉」。' }
    Set-Content $cfgG $cg -NoNewline -Encoding utf8
    New-ReviewFixtureRepo $sg 'feat-y'
    Set-Content (Join-Path $sg 'CHANGED.txt') 'a change under review' -Encoding utf8
    & git -C $sg -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $sg -c user.email='s@l' -c user.name='s' commit -q -m change *> $null
    $swG = [System.Diagnostics.Stopwatch]::StartNew()
    & pwsh -NoProfile -File (Join-Path $sg 'scripts/review.ps1') -WorktreePath $sg -Base master -TimeoutSec 2 *> $null
    $gExit = $LASTEXITCODE
    $swG.Stop()
    if ($gExit -eq 0) { Fail '种子缺陷 17g：review.ps1 在挂起评审者下仍放行（exit 0）——wall-clock 超时回归（TD11）。' }
    elseif ($swG.Elapsed.TotalSeconds -ge 25) { Fail "种子缺陷 17g：review.ps1 等了 $([math]::Round($swG.Elapsed.TotalSeconds,1))s 才返回（≈挂起后端睡满 30s）——超时未生效，ship 会被挂起评审者卡死（TD11）。" }
    else { Write-Host "  17g review.ps1 对挂起评审者有界超时 block OK（$([math]::Round($swG.Elapsed.TotalSeconds,1))s，-TimeoutSec 2）" -ForegroundColor Green }

    # 17h. R3 codex 分支真启动**非 .exe 的 codex 包装**（TD11 续；本轮 dogfood 实测的 bug）：npm 装的 codex 是 .ps1/.cmd，
    #   `Start-Process -FilePath` 直指它会「%1 is not a valid Win32 application」。在 PATH 放一个**假 codex.ps1**（mirror 真实
    #   ExternalScript 形态）、留 ReviewCommand 空走 codex 分支，断言 review.ps1 能经子 pwsh 的 `& codex` 启动它并解析出 pass。
    #   （17b/g 用 ReviewCommand=pwsh.exe 走不到 codex 分支的二进制解析，故此 bug 此前对 selftest 不可见。）
    #   仅 Windows：codex 的 .ps1/.cmd shim 是 Windows npm 特有；非 Windows 上 npm codex 为可直接执行的二进制、
    #   Start-Process 直指即可（且 `& codex` 在 Linux 也不解析名为 codex.ps1 的文件），该 bug 不复现 → 跳过。
    if (-not $IsWindows) {
      Write-Host '  17h 跳过（codex .ps1/.cmd shim 为 Windows 特有；非 Windows 不复现此 bug）。' -ForegroundColor DarkGray
    } else {
    $sh = Join-Path $sd 'h'
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $sh -Recurse -Force
    $fakeBin = Join-Path $sd 'fakebin'; New-Item -ItemType Directory -Force $fakeBin | Out-Null
    # 假 codex.ps1：按 --output-last-message 写 pass 裁决、drain 管道输入、exit 0（mirror 真 codex 的 .ps1 shim 形态）；
    # 另把收到的 prompt 原文落 <REVIEW_OUT>.prompt.txt——供 17l 在**送达文本**上断言默认路径的评审者身份。
    $fakeCodex = @'
$o = ''
for ($i = 0; $i -lt $args.Count; $i++) { if ($args[$i] -eq '--output-last-message') { $o = $args[$i + 1] } }
$raw = ($input | Out-String)
if ($o) {
  '{"verdict":"pass","reasons":[]}' | Set-Content -Path $o -Encoding utf8
  $raw | Set-Content -Path ($o + '.prompt.txt') -Encoding utf8
}
exit 0
'@
    Set-Content (Join-Path $fakeBin 'codex.ps1') $fakeCodex -Encoding utf8
    New-ReviewFixtureRepo $sh 'feat-z'
    Set-Content (Join-Path $sh 'CHANGED.txt') 'a change under review' -Encoding utf8
    & git -C $sh -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $sh -c user.email='s@l' -c user.name='s' commit -q -m change *> $null
    $savedPath = $env:PATH
    try {
      $env:PATH = "$fakeBin$([System.IO.Path]::PathSeparator)$env:PATH"   # 假 codex.ps1 先于真 codex 被解析
      & pwsh -NoProfile -File (Join-Path $sh 'scripts/review.ps1') -WorktreePath $sh -Base master *> $null
      $hExit = $LASTEXITCODE
    } finally { $env:PATH = $savedPath }
    $hVerdict = Get-Content (Join-Path $sh '.review/feat-z.json') -Raw -ErrorAction SilentlyContinue
    if ($hExit -ne 0) { Fail "种子缺陷 17h：review.ps1 codex 分支未能启动非 .exe 的 codex 包装（exit $hExit）——Start-Process 直指 .ps1/.cmd 的「%1 不是有效 Win32 程序」回归（TD11）。" }
    elseif (-not $hVerdict -or $hVerdict -notmatch '"verdict"\s*:\s*"pass"') { Fail "种子缺陷 17h：codex 分支启动了包装但未解析出 pass 裁决（裁决文件=$hVerdict）。" }
    else { Write-Host '  17h review.ps1 codex 分支经子 pwsh & codex 启动非 .exe 包装（codex.ps1）并 pass OK' -ForegroundColor Green }
    }

    # 17i. ReviewCommand 含**内嵌双引号 + 带空格的引用路径**仍能跑（codex R3 实测的回归点）：旧版把整条命令拼进单条命令行、
    #   只「含空白即包双引号」而不转义内嵌引号 → 合法后端被拆碎、误判 fail-closed。新版命令体落临时 .ps1 经 -File 跑（命令是
    #   文件内容、不进命令行），内嵌引号无害。断言 review.ps1 跑通该后端并解析出 pass（exit 0）。
    $si = Join-Path $sd 'i'
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $si -Recurse -Force
    $cfgI = Join-Path $si 'scripts/_config.ps1'
    # 后端命令含双引号串 "a b"、带空格的引用路径 "C:\a b\c"，并把 pass 裁决写到 $env:REVIEW_OUT（here-string 取字面、'' = 单引号）。
    $reviewCmdI = @'
ReviewCommand = '$m = "a b"; $p = "C:\a b\c"; Set-Content -Path $env:REVIEW_OUT -Value ''{"verdict":"pass","reasons":[]}'' -Encoding utf8'
'@.Trim()
    $cI = (Get-Content $cfgI -Raw).Replace("ReviewCommand = ''", $reviewCmdI).Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if (-not $cI.Contains('$m = "a b"')) { Fail '闸17i：含内嵌引号的 ReviewCommand 未注入（_config 行格式变了？.Replace 没命中）。' }
    Set-Content $cfgI $cI -NoNewline -Encoding utf8
    New-ReviewFixtureRepo $si 'feat-q'
    Set-Content (Join-Path $si 'CHANGED.txt') 'a change under review' -Encoding utf8
    & git -C $si -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $si -c user.email='s@l' -c user.name='s' commit -q -m change *> $null
    & pwsh -NoProfile -File (Join-Path $si 'scripts/review.ps1') -WorktreePath $si -Base master *> $null
    $iExit = $LASTEXITCODE
    $iVerdict = Get-Content (Join-Path $si '.review/feat-q.json') -Raw -ErrorAction SilentlyContinue
    if ($iExit -ne 0) { Fail "种子缺陷 17i：含内嵌引号/引用路径的 ReviewCommand 被误判 fail-closed（exit $iExit）——手拼命令行不转义内嵌引号的回归（TD11 codex R3）。" }
    elseif (-not $iVerdict -or $iVerdict -notmatch '"verdict"\s*:\s*"pass"') { Fail "种子缺陷 17i：含内嵌引号的 ReviewCommand 未解析出 pass（裁决文件=$iVerdict）。" }
    else { Write-Host '  17i 含内嵌引号 + 引用路径的 ReviewCommand 经临时 .ps1 跑通并 pass OK' -ForegroundColor Green }

    # 17j. ReviewCommand 经 stdin **真收到 prompt**（codex R3 实测：原 `$prompt | pwsh -Command` 改 `pwsh -File <临时>` 后须证
    #   stdin 契约不破，非仅 plumbing 跑通）：后端读 [Console]::In 全文，含本次 diff 标记（CHANGED）才写 pass、否则写 block。
    #   prompt 若没经文件重定向 stdin 抵达后端（空输入），该后端自判 block → 本闸即失败。证「prompt 真达自定义后端」。
    $sj = Join-Path $sd 'j'
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $sj -Recurse -Force
    $cfgJ = Join-Path $sj 'scripts/_config.ps1'
    # 后端：读 stdin 全文，含 'CHANGED'（本次 diff 标记）→ pass，否则 block（here-string 取字面、'' = 单引号）；
    # 另把 prompt 原文落 <REVIEW_OUT>.prompt.txt——供 17l 在**送达文本**上断言自定义后端的评审者身份。
    $reviewCmdJ = @'
ReviewCommand = '$t = [Console]::In.ReadToEnd(); $t | Set-Content -Path ($env:REVIEW_OUT + ''.prompt.txt'') -Encoding utf8; if ($t -match ''CHANGED'') { ''{"verdict":"pass","reasons":[]}'' | Set-Content -Path $env:REVIEW_OUT -Encoding utf8 } else { ''{"verdict":"block","reasons":["stdin prompt empty"]}'' | Set-Content -Path $env:REVIEW_OUT -Encoding utf8 }'
'@.Trim()
    $cJ = (Get-Content $cfgJ -Raw).Replace("ReviewCommand = ''", $reviewCmdJ).Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if (-not $cJ.Contains('[Console]::In.ReadToEnd()')) { Fail '闸17j：读 stdin 的 ReviewCommand 未注入（_config 行格式变了？.Replace 没命中）。' }
    Set-Content $cfgJ $cJ -NoNewline -Encoding utf8
    New-ReviewFixtureRepo $sj 'feat-w'
    Set-Content (Join-Path $sj 'CHANGED.txt') 'a change under review' -Encoding utf8
    & git -C $sj -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $sj -c user.email='s@l' -c user.name='s' commit -q -m change *> $null
    & pwsh -NoProfile -File (Join-Path $sj 'scripts/review.ps1') -WorktreePath $sj -Base master *> $null
    $jExit = $LASTEXITCODE
    $jVerdict = Get-Content (Join-Path $sj '.review/feat-w.json') -Raw -ErrorAction SilentlyContinue
    if ($jExit -ne 0 -or -not $jVerdict -or $jVerdict -notmatch '"verdict"\s*:\s*"pass"') { Fail "种子缺陷 17j：自定义 ReviewCommand 未从 stdin 收到 prompt（diff 标记缺失 → 该后端自判 block；exit $jExit 裁决=$jVerdict）——prompt 经 -File stdin 抵达契约回归（TD11 codex R3）。" }
    else { Write-Host '  17j ReviewCommand 经文件重定向 stdin 真收到 prompt（含 diff 标记）并 pass OK' -ForegroundColor Green }

    # 17k. remote-ship no-review-backend fail-fast (TD22-C23): strip codex from PATH + force an empty
    #   ReviewCommand, run -Phase ship (non-Local) — it must throw SHIP-NO-REVIEWER with the three
    #   remedies (install codex / set ReviewCommand / explicitly choose advisory policy) BEFORE commit/push/PR;
    #   -Local must not be offered as a bypass of required review (the real local no-merge control is 15b').
    #   otherwise it dies at the review gate only after push + open PR, leaving a half-merged remote
    #   branch. Assertions: non-zero exit, SHIP-NO-REVIEWER + remedies present, and NEITHER the
    #   "commit changes" nor the "push + open PR" step banner appeared (proves the fail-fast precedes
    #   every commit/push side effect; the fixture has no git repo, so a leak would be side-effect-free).
    $sk = Join-Path $sd 'k'
    New-Item -ItemType Directory -Force (Join-Path $sk 'specs/tasks'), (Join-Path $sk 'wt/T0-FF') | Out-Null
    Copy-Item (Join-Path $RepoRoot 'scripts') $sk -Recurse -Force
    $cfgK = Join-Path $sk 'scripts/_config.ps1'
    $cK = Get-Content $cfgK -Raw
    $cK = [regex]::Replace($cK, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$sk/wt'" })     # worktree 指向 fixture，绝不碰真实 wt 根
    $cK = [regex]::Replace($cK, "ReviewCommand\s*=\s*'[^']*'", "ReviewCommand = ''")             # 无论本机是否配了后端，种子强制无后端
    $cK = $cK.Replace("ReviewGate = ''", "ReviewGate = 'required'")   # T68：17k 测的是 opt-in 旧强制行为
    if (($cK -notmatch [regex]::Escape("$sk/wt")) -or ($cK -notmatch "ReviewCommand = ''")) { Fail '闸17k：fixture _config 注入失败（WorktreeRoot/ReviewCommand 行格式变了？Replace 没命中）——测的不再是「无评审后端」。' }
    Set-Content $cfgK $cK -NoNewline -Encoding utf8
    @('---', 'id: T0-FF', 'title: seed 17k remote-ship fail-fast', 'status: todo',
      'dod_command: "pwsh -NoProfile -Command exit 0"', 'allow_paths:', '  - README.md', '---') -join "`n" |
      Set-Content (Join-Path $sk 'specs/tasks/T0-FF.md') -Encoding utf8
    $savedPathK = $env:PATH
    try {
      $codexDirsK = @(Get-Command codex -All -ErrorAction SilentlyContinue | Where-Object { $_.Source } |
        ForEach-Object { (Split-Path $_.Source -Parent).TrimEnd('\', '/') } | Select-Object -Unique)
      if ($codexDirsK.Count) {
        $env:PATH = (($env:PATH -split [System.IO.Path]::PathSeparator) |
          Where-Object { $_ -and ($codexDirsK -notcontains $_.TrimEnd('\', '/')) }) -join [System.IO.Path]::PathSeparator
      }
      & pwsh -NoProfile -Command 'if (Get-Command codex -ErrorAction SilentlyContinue) { exit 9 } else { exit 0 }'
      if ($LASTEXITCODE -ne 0) { Fail '闸17k：无法从 PATH 剔除 codex（子进程仍可解析）——种子前置失败，测的不再是「无评审后端」。' }
      else {
        # TD31/T73: since the TD120 wave the key 17k anchors are ASCII sentinels (SHIP-NO-REVIEWER /
        #   step banners), so the original TD31 false-FAIL mechanism no longer applies to 17k itself.
        #   The encoding pinning below is KEPT anyway: the captured output still carries localized
        #   prose, and a mis-decoded capture would garble the diagnostic tail shown on failure;
        #   宿主 console 非 UTF-8（git-bash / 传统代码页）时子进程中文字节被误解码 → -match 失配 → 假 FAIL（TD31：两处 verifier 环境复现）。
        #   修法（TD31「17k 夹具内固定 OutputEncoding」）：父(解码)与子(编码)的 console 输出编码就地钉成 UTF-8、用完 finally 还原；
        #   只动 OutputEncoding、不碰 InputEncoding（L4/评审：强制 InputEncoding 破坏兄弟闸的嵌套 stdin）；set 以 try/catch 兜底
        #   （CI 无 attached console 时 setter 可能抛——抛了即退化为原行为，本就 UTF-8 的环境仍过）。子端经小包装脚本钉编码并 exit $LASTEXITCODE 忠实透传 task.ps1 退出码。
        $encWrap = Join-Path $sk 'enc-ship-17k.ps1'
        Set-Content $encWrap 'try { [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }; & (Join-Path $PSScriptRoot "scripts/task.ps1") -TaskId T0-FF -Phase ship; exit $LASTEXITCODE' -Encoding utf8
        $prevConsoleOut = $null
        try { $prevConsoleOut = [Console]::OutputEncoding; [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }
        try {
          $kOut = (& pwsh -NoProfile -File $encWrap 2>&1 | Out-String)
          $kExit = $LASTEXITCODE
        } finally {
          if ($prevConsoleOut) { try { [Console]::OutputEncoding = $prevConsoleOut } catch { } }
        }
        $kTail = ($kOut -replace '\s+', ' ').Trim(); if ($kTail.Length -gt 260) { $kTail = $kTail.Substring($kTail.Length - 260) }
        if ($kExit -eq 0) { Fail '种子缺陷 17k：PATH 无 codex + 空 ReviewCommand 下远端 ship 仍退出 0——「无评审后端」fail-fast 回归（TD22-C23）。' }
        elseif ($kOut -notmatch 'SHIP-NO-REVIEWER') { Fail "Seed defect 17k: a remote ship without a review backend did not throw the SHIP-NO-REVIEWER fail-fast (failed at some other gate instead? output tail=$kTail)." }
        elseif (($kOut -notmatch 'codex') -or ($kOut -notmatch 'ReviewCommand') -or ($kOut -notmatch 'ReviewGate') -or ($kOut -notmatch 'advisory')) { Fail 'Seed defect 17k: SHIP-NO-REVIEWER must name the backend remedies and the explicit ReviewGate advisory policy choice.' }
        elseif ($kOut -match 'ship -Local') { Fail 'Seed defect 17k: SHIP-NO-REVIEWER must not suggest bypassing required review with -Local.' }
        elseif (($kOut -match '\] commit changes ===') -or ($kOut -match 'push \+ open PR')) { Fail 'Seed defect 17k: SHIP-NO-REVIEWER was thrown only after the commit/push steps - the fail-fast is not front-loaded, half-merged-state regression (TD22-C23).' }
        else { Write-Host '  17k 远端 ship 无评审后端 → 提交/push 前 fail-fast（含三条补救）OK' -ForegroundColor Green }
      }
    } finally { $env:PATH = $savedPathK }

    # 17l. 评审者身份随后端参数化（T4-GUARD-HYGIENE ⑧，应 R3 #6）：复用 17h/17j 夹具**送达**的 prompt 副本
    #   （两处 stub 把 stdin 收到的 prompt 原文落在 $env:REVIEW_OUT 旁的 .prompt.txt）断言身份行随后端切换——
    #   默认 codex 路径自称「独立第二评审（Codex）」；自定义 ReviewCommand 后端只自称「独立第二评审」、不得再冒名 Codex。
    #   断言在送达文本上做（非 review.ps1 源码 grep）——证身份参数化真抵达评审者，而非仅源码里存在分支。
    if (-not $IsWindows) {
      Write-Host '  17l（默认 codex 半）跳过（依赖 17h 的 Windows 专有 codex.ps1 shim 夹具）。' -ForegroundColor DarkGray
    } else {
      $lPromptH = Get-Content (Join-Path $sh '.review/feat-z.json.prompt.txt') -Raw -ErrorAction SilentlyContinue
      if (-not $lPromptH) { Fail '闸17l：17h 夹具未捕获送达 prompt（假 codex.ps1 stub 结构变了？）——无从断言默认 codex 路径的评审者身份。' }
      elseif ($lPromptH -notmatch '你是独立第二评审（Codex）') { Fail '种子缺陷 17l：默认 codex 路径送达的 prompt 不含「你是独立第二评审（Codex）」——评审者身份参数化回归（T4-GUARD-HYGIENE ⑤）。' }
      else { Write-Host '  17l 默认 codex 路径送达 prompt 自称「独立第二评审（Codex）」OK' -ForegroundColor Green }
    }
    $lPromptJ = Get-Content (Join-Path $sj '.review/feat-w.json.prompt.txt') -Raw -ErrorAction SilentlyContinue
    if (-not $lPromptJ) { Fail '闸17l：17j 夹具未捕获送达 prompt（ReviewCommand stub 结构变了？）——无从断言自定义后端的评审者身份。' }
    elseif ($lPromptJ -notmatch '你是独立第二评审') { Fail '种子缺陷 17l：自定义 ReviewCommand 后端送达的 prompt 不含「你是独立第二评审」——评审者身份行丢失回归。' }
    elseif ($lPromptJ -match '（Codex）') { Fail '种子缺陷 17l：自定义 ReviewCommand 后端送达的 prompt 仍含「（Codex）」——身份应随后端参数化、不得冒名默认后端（T4-GUARD-HYGIENE ⑤）。' }
    else { Write-Host '  17l 自定义 ReviewCommand 后端送达 prompt 自称「独立第二评审」且不含「（Codex）」OK' -ForegroundColor Green }

    # 17m. scout-options 年份硬编码静态回归（T4-GUARD-HYGIENE ⑧，应 R3 #6；体例仿 17f 的文本体检查）：
    #   (i) 源内不得再出现「当前是 20xx」类硬编码绝对年份（workflow 沙箱里 new Date()/Date.now() 会抛、无法运行时取年，
    #   写死则逐年腐化）；(ii) 须保留 args 条件日期表达式（A.today 取参或 TODAY ? 条件拼接）——日期只能经 args 进入 prompt。
    $soPath = Join-Path $RepoRoot '.claude/workflows/scout-options.mjs'
    if (-not (Test-Path $soPath)) { Write-Host '  17m 跳过（无 scout-options.mjs——下游裁剪后正常）。' -ForegroundColor DarkGray }
    else {
      $soRaw = Get-Content $soPath -Raw
      if ($soRaw -match '当前是\s*20\d\d') { Fail '种子缺陷 17m：scout-options.mjs 又现硬编码绝对年份「当前是 20xx」——逐年腐化回归（T4-GUARD-HYGIENE ⑦；日期只能经 args.today 进入）。' }
      elseif (($soRaw -notmatch 'A\.today') -and ($soRaw -notmatch 'TODAY\s*\?')) { Fail '种子缺陷 17m：scout-options.mjs 缺 args 条件日期表达式（A.today 取参 / TODAY ? 条件拼接均不见）——日期经 args 注入的通道丢失（T4-GUARD-HYGIENE ⑦）。' }
      else { Write-Host '  17m scout-options.mjs 无硬编码年份、日期仅经 args.today 条件注入 OK' -ForegroundColor Green }
    }

    # 17n. 两 Stop 钩子文案/节律静态回归（T4-GUARD-HYGIENE ⑨，应 R3 #6 二轮；静态字符串断言，评审已明示接受）：
    #   handoff-reminder 节律须为 30 分钟且措辞为「真正离场前」（非每次 Stop 义务）；
    #   lessons-reminder 须含策展指引（相近条目更新勿新增、删错条目）。钩子是模板载荷、settings.json 引用（闸 9 管存在性），
    #   缺文件在此按 fail-closed 记 Fail 而非跳过。
    $hookChecks = @(
      @{ f = '.claude/hooks/handoff-reminder.ps1';       re = "Test-HookThrottle -Name 'handoff' -Minutes 30"; what = "30 分钟节流（Test-HookThrottle -Name 'handoff' -Minutes 30）" },
      # T116/TD155：节流须带内容键，否则 progress.md 一变仍要静默等满冷却期——「状态报告」退化回「周期 nudge」。
      # 反向的一半（lessons-reminder 必须**不**带键）在本表之后单独断言：本表的循环只做正向 -notmatch 判定。
      @{ f = '.claude/hooks/handoff-reminder.ps1';       re = '-ContentKey \$key';                what = '内容键节流（-ContentKey $key，progress.md 一变即当轮提醒）' },
      @{ f = '.claude/hooks/handoff-reminder.ps1';       re = '真正离场前';                       what = '离场措辞「真正离场前」（非每次 Stop 义务）' },
      @{ f = '.claude/hooks/lessons-reminder.ps1';       re = '相近条目就更新而非新增';           what = '策展指引「相近条目就更新而非新增」' },
      @{ f = '.claude/hooks/lessons-reminder.ps1';       re = '删除';                             what = '策展指引「（发现错的条目）删除」' }
    )
    $nFail = $false
    # TD175: the same author-extended grep shape 17z's $zWirings carries, one table over. A row naming the
    # file it is DECLARED in would be satisfied by its own declaration - the row spells the regex out, the
    # grep finds it, and no change to any hook could turn it red. All five live rows name a hook file, so
    # this is the trap for the next author rather than a present hole, which is exactly how TD171 was found.
    # Judged BEFORE the loop so a self row is reported AS a self row, not as the missing-file Fail this
    # table opens with (17n is fail-closed on absence where 17z skips).
    foreach ($nSelfSat in @(Get-ScaffoldSelfSatisfyingWiringRows -Rows $hookChecks -DeclaringPath 'scripts/selftest.ps1')) { Fail "17n(TD175): $nSelfSat"; $nFail = $true }
    foreach ($hc in $hookChecks) {
      $hp = Join-Path $RepoRoot $hc.f
      if (-not (Test-Path $hp)) { Fail "种子缺陷 17n：$($hc.f) 不存在——两 Stop 钩子文案/节律回归无从断言（T4-GUARD-HYGIENE ⑨）。"; $nFail = $true; continue }
      if ((Get-Content $hp -Raw) -notmatch $hc.re) { Fail "种子缺陷 17n：$($hc.f) 缺 $($hc.what)——hook 文案/节律回归（T4-GUARD-HYGIENE ⑨）。"; $nFail = $true }
    }
    # 17n 的反向一半（T116/TD155）：内容键是**按调用方**选的规则，不是全局开关。lessons-reminder 打的是固定
    # 文案，一旦给它带上键就会「首轮打一次、此后永远静默」——比过度提醒更糟，因为它是无声的。故这里断言它
    # **没有**内容键。两条方向相反的断言合起来才钉住「可选参数」这一设计：只有正向那条时，把键加到两个钩子
    # 上仍能全绿。
    $lrPath = Join-Path $RepoRoot '.claude/hooks/lessons-reminder.ps1'
    if (-not (Test-Path $lrPath)) { Fail '种子缺陷 17n：.claude/hooks/lessons-reminder.ps1 不存在——内容键的反向断言无从成立（T116/TD155）。'; $nFail = $true }
    elseif ((Get-Content $lrPath -Raw) -match 'ContentKey') { Fail '种子缺陷 17n：lessons-reminder.ps1 出现 ContentKey——固定文案的周期提醒带上内容键即「首轮之后永久静默」（T116/TD155）。'; $nFail = $true }
    if (-not $nFail) { Write-Host '  17n 两 Stop 钩子文案/节律静态回归 OK（handoff 30 分钟+内容键+真正离场前 / lessons 相近更新勿新增+删错，且 lessons 无内容键）' -ForegroundColor Green }

    # 17n'. 内容键节流的**行为**夹具（T116/TD155）。上面 17n 是静态文本断言：它能证明调用方传了键，证明不了
    #   键起了作用。卡的 DoD 能证明后者，但 DoD 合并之后就再也不跑了——于是这条契约会失去全部机检覆盖。
    #   故把四态搬进闸内，hermetic：CLAUDE_PROJECT_DIR 指向临时目录，真实 _local/.hook-stamps 不被触碰。
    #   四组用例各自钉一条规则，删任一条判断行都会有一组翻红（单句删除变异，L165）：
    #     a 组 = 键变即发（本卡修的缺陷）+ 发后存新键；b 组 = 时间地板仍在（-Minutes 0 每次都发）；
    #     c 组 = 无键调用与 T116 之前逐字一致；d 组 = 无键调用按时间独断，不受戳里存着的旧键影响。
    $thPath = Join-Path $RepoRoot '.claude/hooks/_throttle.ps1'
    if (-not (Test-Path $thPath)) { Fail '种子缺陷 17n''：.claude/hooks/_throttle.ps1 不存在——内容键节流的行为夹具无从跑（T116/TD155）。' }
    else {
      $thTmp = Join-Path ([System.IO.Path]::GetTempPath()) ('selftest-17n-' + [guid]::NewGuid().ToString('N'))
      $thPrev = $env:CLAUDE_PROJECT_DIR
      $thFails = [System.Collections.Generic.List[string]]::new()
      try {
        New-Item -ItemType Directory -Force $thTmp -ErrorAction SilentlyContinue | Out-Null
        $env:CLAUDE_PROJECT_DIR = $thTmp
        . $thPath
        # a 组：冷却期内，键相同静默 / 键变化即发 / 发后存的是新键（故新键随即又静默）
        if (-not (Test-HookThrottle -Name 'a' -Minutes 30 -ContentKey 'K1')) { $thFails.Add('首次带键调用未提醒（无戳可比时必须发）') }
        if (Test-HookThrottle -Name 'a' -Minutes 30 -ContentKey 'K1') { $thFails.Add('冷却期内同一内容键仍提醒（banner blindness 未消）') }
        if (-not (Test-HookThrottle -Name 'a' -Minutes 30 -ContentKey 'K2')) { $thFails.Add('冷却期内内容键已变却静默——正是 TD155 要修的那半：状态刚变的那一刻被压掉') }
        if (Test-HookThrottle -Name 'a' -Minutes 30 -ContentKey 'K2') { $thFails.Add('发提醒后未把新键写回戳（否则每轮都判为「变了」，退化成不节流）') }
        # b 组：时间地板仍在——冷却期已过则同一键也发，本节流器不是纯变更检测器
        if (-not (Test-HookThrottle -Name 'b' -Minutes 0 -ContentKey 'K1')) { $thFails.Add('冷却期已过的首次带键调用未提醒') }
        if (-not (Test-HookThrottle -Name 'b' -Minutes 0 -ContentKey 'K1')) { $thFails.Add('冷却期已过、键未变即不提醒——时间地板丢失，提醒退化成纯变更检测器') }
        # c 组：不传键的调用与 T116 之前逐字一致（首次发、冷却期内静默）
        if (-not (Test-HookThrottle -Name 'c' -Minutes 30)) { $thFails.Add('无键调用首次未提醒（纯时间路径回归）') }
        if (Test-HookThrottle -Name 'c' -Minutes 30) { $thFails.Add('无键调用在冷却期内仍提醒（纯时间路径回归）') }
        # d 组：戳里存着旧键时，无键调用仍按时间独断——「有没有键」是调用方选的规则，不是戳的状态说了算
        if (-not (Test-HookThrottle -Name 'd' -Minutes 30 -ContentKey 'K1')) { $thFails.Add('d 组首次带键调用未提醒（夹具前置失败）') }
        if (Test-HookThrottle -Name 'd' -Minutes 30) { $thFails.Add('戳里存着键时，无键调用不再按时间独断——纯时间调用方会被别人写的键带偏') }
      }
      catch { $thFails.Add("行为夹具抛异常：$($_.Exception.Message)") }
      finally {
        $env:CLAUDE_PROJECT_DIR = $thPrev
        Remove-Item $thTmp -Recurse -Force -ErrorAction SilentlyContinue
      }
      if ($thFails.Count) { $thFails | ForEach-Object { Fail "种子缺陷 17n'（T116/TD155 内容键节流）：$_" } }
      else { Write-Host "  17n' 内容键节流行为夹具 OK（键变即发/键同静默/发后存新键 · 时间地板仍在 · 无键路径逐字不变 · 无键调用不被戳里的旧键带偏）" -ForegroundColor Green }
    }

    # 17o. pre-push 安装行为（C05 · T6-HOOK-CHAIN）：hermetic 三情形——honoring core.hooksPath + 不静默覆盖既有钩子（链式）。
    #   dot-source gh-bootstrap.ps1 -AsLibrary 取 Install-PrePushHook（库模式不触网络/不建仓），对临时 git 仓真跑安装并断言落点/备份/链式。
    #   治本 C05：原实现写死 .git/hooks，core.hooksPath 环境下 git 根本不看该文件却仍报「已装」= 安全控制假成功；且静默覆盖既有钩子。
    . (Join-Path $RepoRoot 'scripts/gh-bootstrap.ps1') -AsLibrary
    $oFail = $false
    # Case E's execution assertions need `sh`; case C already announces when it cannot run them and E did
    # not, so on an sh-less box E's arms evaporated while the success line below went on asserting that
    # both retained hooks executed (TD200). The state is READ into that line rather than assumed there.
    $oEExec = 'skipped'
    $oRepos = @()
    function New-HookTestRepo($tag) {
      $d = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-hook-$tag-$PID"
      if (Test-Path $d) { Remove-Item -Recurse -Force $d }
      New-Item -ItemType Directory -Force $d | Out-Null
      & git -C $d init -q 2>$null
      return $d
    }
    try {
      # 情形 A：无 core.hooksPath → 钩子落 .git/hooks/pre-push 且含幂等标记。
      $ra = New-HookTestRepo 'a'; $oRepos += $ra
      Install-PrePushHook -RepoRoot $ra *> $null
      $aHook = Join-Path $ra '.git/hooks/pre-push'
      if (-not (Test-Path $aHook)) { Fail '种子缺陷 17o-A：无 core.hooksPath 时 pre-push 未落 .git/hooks（装钩失败）。'; $oFail = $true }
      elseif ((Get-Content $aHook -Raw) -notmatch 'scaffold-prepush-guard') { Fail '种子缺陷 17o-A：装出的 pre-push 缺幂等标记 scaffold-prepush-guard。'; $oFail = $true }

      # 情形 B：设 core.hooksPath 自定义目录 → 钩子落该目录、**不**落 .git/hooks（治 C05 假成功）。
      $rb = New-HookTestRepo 'b'; $oRepos += $rb
      & git -C $rb config core.hooksPath myhooks 2>$null
      Install-PrePushHook -RepoRoot $rb *> $null
      $bCustom = Join-Path $rb 'myhooks/pre-push'
      $bDefault = Join-Path $rb '.git/hooks/pre-push'
      if (-not (Test-Path $bCustom)) { Fail '种子缺陷 17o-B：设 core.hooksPath 后 pre-push 未落自定义目录（C05：git 实际读的目录被忽略、安全控制假成功）。'; $oFail = $true }
      elseif (Test-Path $bDefault) { Fail '种子缺陷 17o-B：设 core.hooksPath 后仍误写 .git/hooks/pre-push（git 不看它，等于装了个假成功的死钩子）。'; $oFail = $true }

      # 情形 F：core.hooksPath 用 ~ 家目录展开 → git `--git-path hooks` 按 git 路径语义解析到 $HOME 下，绝不误当仓库相对路径写成 $RepoRoot/~/…（C05 变体）。
      #   临时把 $env:HOME 指向 temp 家目录（git 的 ~ 展开据此），断言钩子落该家目录下、且**未**落 $RepoRoot/~ 误路径。
      $rf = New-HookTestRepo 'f'; $oRepos += $rf
      $fakeHome = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-hook-home-$PID"
      if (Test-Path $fakeHome) { Remove-Item -Recurse -Force $fakeHome }
      New-Item -ItemType Directory -Force $fakeHome | Out-Null
      $oRepos += $fakeHome
      & git -C $rf config core.hooksPath '~/mh' 2>$null
      $savedHome = $env:HOME
      try { $env:HOME = $fakeHome; Install-PrePushHook -RepoRoot $rf *> $null }
      finally { if ($null -eq $savedHome) { Remove-Item Env:HOME -ErrorAction SilentlyContinue } else { $env:HOME = $savedHome } }
      $fExpanded = Join-Path $fakeHome 'mh/pre-push'
      $fWrong = Join-Path $rf '~/mh/pre-push'
      if (-not (Test-Path $fExpanded)) { Fail '种子缺陷 17o-F：~ 展开的 core.hooksPath 未解析到 $HOME 下（C05 变体：未用 git 路径语义、钩子落错位置 = 安全控制假成功）。'; $oFail = $true }
      elseif (Test-Path $fWrong) { Fail '种子缺陷 17o-F：~ 被误当仓库相对路径、钩子写成 $RepoRoot/~/mh（git 不看它，死钩子）。'; $oFail = $true }

      # 情形 G：链接工作树（linked worktree）→ 钩子须落**主仓公共** hooks 目录（git 只在此跑 pre-push），
      #   而非 .git/worktrees/<name>/hooks（用 --git-dir 拼会错装到这里、git 不看 = 假成功，Codex R3 catch）。
      $rg = New-HookTestRepo 'g'; $oRepos += $rg
      & git -C $rg -c user.email='t@t' -c user.name='t' commit -q --allow-empty -m init 2>$null
      $rgWt = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-hook-gwt-$PID"
      if (Test-Path $rgWt) { Remove-Item -Recurse -Force $rgWt }
      & git -C $rg worktree add -q $rgWt 2>$null
      $oRepos += $rgWt
      Install-PrePushHook -RepoRoot $rgWt *> $null
      $gCommon = Join-Path $rg '.git/hooks/pre-push'
      $gWrong = Join-Path $rg ".git/worktrees/$(Split-Path $rgWt -Leaf)/hooks/pre-push"
      if (-not (Test-Path $gCommon)) { Fail '种子缺陷 17o-G：链接工作树下 pre-push 未落主仓公共 hooks（git 只在公共目录跑 pre-push；钩子落错位置 = 安全控制假成功）。'; $oFail = $true }
      elseif (Test-Path $gWrong) { Fail '种子缺陷 17o-G：链接工作树下 pre-push 误装到 .git/worktrees/<name>/hooks（git 不在此跑 pre-push，死钩子）。'; $oFail = $true }

      # 情形 C：安装前已有非本脚手架的 pre-push → 备份为 pre-push.local + 新钩子含标记且链式 $0.local（不静默覆盖）。
      #   既有钩子体**记录**收到的参数与 stdin，供下方执行断言链式确实原样转交（非仅文本含 $0.local）。
      $rc = New-HookTestRepo 'c'; $oRepos += $rc
      $cHook = Join-Path $rc '.git/hooks/pre-push'
      $cForeign = "#!/bin/sh`n# SELFTEST-FOREIGN-HOOK`nprintf '%s|%s\n' `"`$1`" `"`$2`" > `"`$(git rev-parse --show-toplevel)/chain-args.txt`"`ncat > `"`$(git rev-parse --show-toplevel)/chain-stdin.txt`"`nexit 0`n"
      ($cForeign -replace "`r`n", "`n") | Set-Content -Path $cHook -NoNewline -Encoding utf8
      Install-PrePushHook -RepoRoot $rc *> $null
      $cBackup = "$cHook.local"
      $cNew = Get-Content $cHook -Raw
      if (-not (Test-Path $cBackup)) { Fail '种子缺陷 17o-C：既有 pre-push 未备份为 pre-push.local（C05：静默覆盖丢失用户既有钩子）。'; $oFail = $true }
      elseif ((Get-Content $cBackup -Raw) -notmatch 'SELFTEST-FOREIGN-HOOK') { Fail '种子缺陷 17o-C：pre-push.local 未保留既有钩子原内容。'; $oFail = $true }
      elseif ($cNew -notmatch 'scaffold-prepush-guard') { Fail '种子缺陷 17o-C：覆盖后的新 pre-push 缺幂等标记。'; $oFail = $true }
      elseif ($cNew -notmatch '\.local\*') { Fail '种子缺陷 17o-C：新 pre-push 未链式调用既有钩子（"$0".local*；既有钩子被丢弃）。'; $oFail = $true }
      else {
        # 情形 C（执行断言）：真跑装出的 pre-push，证链式既有钩子**确实**收到原始参数($1/$2)与 stdin（治「仅文本含 $0.local」的假测）。
        #   桩掉两闸（_guard/check-secrets exit 0），把 sh/pwsh 与执行位备齐；sh 不可用则跳过执行、结构断言仍生效（诚实降级，同 15f）。
        if ((Get-Command sh -ErrorAction SilentlyContinue) -and (Get-Command pwsh -ErrorAction SilentlyContinue)) {
          $cScripts = Join-Path $rc 'scripts'
          New-Item -ItemType Directory -Force $cScripts | Out-Null
          Set-Content (Join-Path $cScripts '_guard.ps1') 'function Assert-PersonalAccount { param($RepoRoot,[switch]$CheckRemote,$RemoteUrl) }' -Encoding utf8
          Set-Content (Join-Path $cScripts 'check-secrets.ps1') 'exit 0' -Encoding utf8
          # 不在此 chmod：故意跑**真实安装态**——经 `& sh <hook>` 调用装出的钩子（无需其可执行位），
          # 其内部按 [ -x ] 分支决定直接执行或 sh 回退（Windows 上备份无可执行位，须走 sh 回退才不静默丢钩子，C05 catch）。
          $hookSh = $cHook -replace '\\', '/'
          Push-Location $rc
          try { 'refs/heads/main aaa refs/heads/main bbb' | & sh $hookSh origin 'https://github.com/acct/repo.git' 2>$null } finally { Pop-Location }
          $argsFile = Join-Path $rc 'chain-args.txt'
          $stdinFile = Join-Path $rc 'chain-stdin.txt'
          if (-not (Test-Path $argsFile)) { Fail '种子缺陷 17o-C(exec)：链式既有钩子未被执行（chain-args.txt 未生成）——$0.local 未真正被调用。'; $oFail = $true }
          elseif ((Get-Content $argsFile -Raw) -notmatch 'origin\|https://github\.com/acct/repo\.git') { Fail '种子缺陷 17o-C(exec)：链式既有钩子未收到原始参数 $1/$2（args 转交失败）。'; $oFail = $true }
          elseif ((-not (Test-Path $stdinFile)) -or ((Get-Content $stdinFile -Raw) -notmatch 'refs/heads/main aaa refs/heads/main bbb')) { Fail '种子缺陷 17o-C(exec)：链式既有钩子未收到原始 stdin（ref 更新转交失败）。'; $oFail = $true }
        } else {
          Write-Host '  17o-C(exec) 跳过：sh/pwsh 不可用（结构断言仍生效；CI ubuntu 支路必跑执行断言）。' -ForegroundColor DarkGray
        }
        # 情形 D：幂等重跑（既有的已是本脚手架标记的）→ 不再二次备份为 pre-push.local.local。
        Install-PrePushHook -RepoRoot $rc *> $null
        if (Test-Path "$cBackup.local") { Fail '种子缺陷 17o-D：幂等重跑二次备份（生成 pre-push.local.local）——标记识别失效。'; $oFail = $true }
      }

      # 情形 E：备份名冲突（.local 已存在前次备份）→ 当前既有钩子另备份为 .local.1、前次 .local 不被覆盖、脚手架守卫仍安装（不留无守卫仓），
      #   且**两个**保留钩子都在两闸后按序被链式调用（治「冲突时当前既有钩子被保留却从不执行」）。两钩子各记录到不同文件以便执行断言分辨。
      $re = New-HookTestRepo 'e'; $oRepos += $re
      $eHook = Join-Path $re '.git/hooks/pre-push'
      # 前次备份 .local 带 shebang → Windows MSYS 判 [ -x ] 真、走直接 exec 分支；当前既有 .local.1 **无 shebang** → [ -x ] 假、
      # 走 sh 回退分支——两个不同分支各覆盖一钩子，共同证「无论有无可执行位/shebang，既有钩子都被链式执行、不静默丢弃」（C05 Windows-drop catch）。
      $ePrior = "#!/bin/sh`n# PRIOR-BACKUP`nprintf '%s|%s\n' `"`$1`" `"`$2`" > `"`$(git rev-parse --show-toplevel)/prior-args.txt`"`ncat > `"`$(git rev-parse --show-toplevel)/prior-stdin.txt`"`nexit 0`n"
      $eCur = "# CURRENT-FOREIGN (no shebang → 走 sh 回退)`nprintf '%s|%s\n' `"`$1`" `"`$2`" > `"`$(git rev-parse --show-toplevel)/cur-args.txt`"`ncat > `"`$(git rev-parse --show-toplevel)/cur-stdin.txt`"`nexit 0`n"
      ($ePrior -replace "`r`n", "`n") | Set-Content -Path "$eHook.local" -NoNewline -Encoding utf8
      ($eCur   -replace "`r`n", "`n") | Set-Content -Path $eHook -NoNewline -Encoding utf8
      Install-PrePushHook -RepoRoot $re *> $null
      $eNew = Get-Content $eHook -Raw
      if ($eNew -notmatch 'scaffold-prepush-guard') { Fail '种子缺陷 17o-E：备份名冲突时未安装脚手架守卫（留仓库无 pre-push 守卫 = 账号守卫/防泄露闸静默失效，安全漏洞）。'; $oFail = $true }
      elseif ((Get-Content "$eHook.local" -Raw) -notmatch 'PRIOR-BACKUP') { Fail '种子缺陷 17o-E：前次备份 pre-push.local 被覆盖（数据丢失）。'; $oFail = $true }
      elseif (-not (Test-Path "$eHook.local.1")) { Fail '种子缺陷 17o-E：当前既有钩子未另备份为 pre-push.local.1。'; $oFail = $true }
      elseif ((Get-Content "$eHook.local.1" -Raw) -notmatch 'CURRENT-FOREIGN') { Fail '种子缺陷 17o-E：pre-push.local.1 未保留当前既有钩子内容。'; $oFail = $true }
      elseif ((Get-Command sh -ErrorAction SilentlyContinue) -and (Get-Command pwsh -ErrorAction SilentlyContinue)) {
        # 情形 E（执行断言）：真跑装出的 pre-push，证**两个**保留钩子都被链式调用、且当前既有钩子（.local.1）确实收到原始参数与 stdin（Codex R3 要求）。
        $oEExec = 'run'
        $eScripts = Join-Path $re 'scripts'
        New-Item -ItemType Directory -Force $eScripts | Out-Null
        Set-Content (Join-Path $eScripts '_guard.ps1') 'function Assert-PersonalAccount { param($RepoRoot,[switch]$CheckRemote,$RemoteUrl) }' -Encoding utf8
        Set-Content (Join-Path $eScripts 'check-secrets.ps1') 'exit 0' -Encoding utf8
        # 不 chmod：跑真实安装态（Windows 上备份无可执行位 → 依赖钩子内 sh 回退链式，才不静默丢既有钩子，C05 catch）。
        $eHookSh = $eHook -replace '\\', '/'
        Push-Location $re
        try { 'refs/heads/main ccc refs/heads/main ddd' | & sh $eHookSh origin 'https://github.com/acct/repo2.git' 2>$null } finally { Pop-Location }
        $curArgs = Join-Path $re 'cur-args.txt'; $curStdin = Join-Path $re 'cur-stdin.txt'; $priorArgs = Join-Path $re 'prior-args.txt'
        if (-not (Test-Path $priorArgs)) { Fail '种子缺陷 17o-E(exec)：前次备份钩子 pre-push.local 未被链式调用（prior-args.txt 未生成）。'; $oFail = $true }
        elseif (-not (Test-Path $curArgs)) { Fail '种子缺陷 17o-E(exec)：当前既有钩子 pre-push.local.1 被保留却从不执行（cur-args.txt 未生成，Codex R3 catch）。'; $oFail = $true }
        elseif ((Get-Content $curArgs -Raw) -notmatch 'origin\|https://github\.com/acct/repo2\.git') { Fail '种子缺陷 17o-E(exec)：当前既有钩子 pre-push.local.1 未收到原始参数 $1/$2。'; $oFail = $true }
        elseif ((-not (Test-Path $curStdin)) -or ((Get-Content $curStdin -Raw) -notmatch 'refs/heads/main ccc refs/heads/main ddd')) { Fail '种子缺陷 17o-E(exec)：当前既有钩子 pre-push.local.1 未收到原始 stdin。'; $oFail = $true }
      }
      else {
        # The arm case C has had since it was written, and E has not (TD200). Without it E's execution
        # assertions vanish on an sh-less box leaving no trace, which is the fail-quiet shape 8.2j exists to
        # detect - and worse here, because the success line below then asserts the execution as fact.
        Write-Host '  17o-E(exec) skipped (sh unavailable; the structural assertions above still apply - the CI ubuntu leg runs the execution assertions).' -ForegroundColor DarkGray
      }

      if (-not $oFail) { Write-Host "  17o pre-push 安装行为 OK（honoring core.hooksPath 含 ~ 展开 + 链接工作树公共 hooks / 既有钩子备份为 .local 并链式转交 args+stdin（含无 shebang sh 回退）/ 幂等不重复备份 / 备份名冲突不覆盖且仍装守卫）; E exec: $oEExec (run = both retained hooks were executed; skipped = sh absent, announced above)" -ForegroundColor Green }
    } finally {
      foreach ($r in $oRepos) { Remove-Item -Recurse -Force $r -ErrorAction SilentlyContinue }
    }

    # 17p. 许可闸 Distributes 旗降级（C21 · T6-LICENSE-DISTRIBUTES）：dot-source check-licenses.ps1 -AsLibrary 取 Scan/正则/Distributes，
    #   对合成许可字符串直测分类——证「Distributes=$false 只降**纯 GPL**（分发触发），AGPL(网络)/SSPL(SaaS)/EUPL(通信)/非商用(用途)仍致命」。
    #   法务红线机检：降错一类都会让 selftest 红。dot-source 的 -AsLibrary 不 Set-Location/不扫描/不 exit（同 check-secrets 库模式）。
    . (Join-Path $RepoRoot 'scripts/check-licenses.ps1') -AsLibrary
    function Test-LicVerdict([bool]$dist, [string]$lic) {
      $script:bad = @(); $script:warn = @(); $script:Distributes = $dist
      Scan 'pkg' $lic
      if ($script:bad.Count) { return 'bad' } elseif ($script:warn.Count) { return 'warn' } else { return 'ok' }
    }
    $pFail = $false
    # Distributes=$true（默认）：GPL 系全致命（行为不变）
    $pCases = @(
      @{ d = $true;  lic = 'GPL-3.0';                          want = 'bad';  why = '默认(分发)下纯 GPL 应致命' }
      @{ d = $true;  lic = 'GNU General Public License v2';    want = 'bad';  why = '默认下 GPL 全称应致命' }
      # Distributes=$false（不分发）：**仅纯 GPL** 降黄牌；其余触发点仍致命
      @{ d = $false; lic = 'GPL-3.0';                          want = 'warn'; why = '不分发下纯 GPL 应降黄牌（分发触发点未命中）' }
      @{ d = $false; lic = 'GNU General Public License v2';    want = 'warn'; why = '不分发下 GPL 全称应降黄牌' }
      @{ d = $false; lic = 'AGPL-3.0';                         want = 'bad';  why = 'AGPL 网络触发——不分发也致命，绝不降级' }
      @{ d = $false; lic = 'GNU Affero General Public License';want = 'bad';  why = 'Affero 全称网络触发——不分发也致命' }
      @{ d = $false; lic = 'SSPL-1.0';                         want = 'bad';  why = 'SSPL SaaS 触发——不分发也致命' }
      @{ d = $false; lic = 'EUPL-1.2';                         want = 'bad';  why = 'EUPL 分发+通信触发——保守仍致命' }
      @{ d = $false; lic = 'non-commercial';                   want = 'bad';  why = '非商用限用途——与分发无关，仍致命' }
      @{ d = $false; lic = 'CC-BY-NC-4.0';                     want = 'bad';  why = 'CC-BY-NC 限用途——仍致命' }
      # LGPL 两档均黄牌（既有路径不受 Distributes 影响）
      @{ d = $true;  lic = 'LGPL-2.1';                         want = 'warn'; why = 'LGPL 恒黄牌（动态链接可接受）' }
      @{ d = $false; lic = 'LGPL-2.1';                         want = 'warn'; why = 'LGPL 恒黄牌（不受 Distributes 影响）' }
      # 宽松许可两档均放行
      @{ d = $false; lic = 'MIT';                              want = 'ok';   why = 'MIT 恒放行' }
    )
    foreach ($c in $pCases) {
      $got = Test-LicVerdict $c.d $c.lic
      if ($got -ne $c.want) { Fail "种子缺陷 17p：Distributes=$($c.d) 下 '$($c.lic)' 判为 $got，应为 $($c.want)（$($c.why)）——C21 法务边界回归。"; $pFail = $true }
    }
    if (-not $pFail) { Write-Host '  17p 许可闸 Distributes 降级 OK（不分发只降纯 GPL；AGPL/SSPL/EUPL/非商用仍致命；LGPL 恒黄牌）' -ForegroundColor Green }

    # 17p2. 许可闸 JSON 解析失败 catch 块须记 coverageGap（TD-211 · TD81 · T22-LICENSE-PARSE-GAP）：
    #   `ConvertFrom-Json` 解析失败时（畸形/截断输出，非空但非法 JSON）不能只 Write-Warning 就放过；必须与姊妹的
    #   「空输出」分支（80/95 行）同款记一条 $coverageGap，否则退出阶梯全空、-Strict 下也假绿 PASS。
    #   用**真 AST**（同 TD69 check-cards.ps1 的手法）而非原始文本正则——纯正则只匹配子串会被注释/字符串里提到
    #   `coverageGap +=` 的假满足骗过（codex R3 两轮 catch：先指出子串匹配漏判非追加写法，再指出正则版即便加了
    #   `\+=` 仍分不清「真赋值语句」与「注释/字符串里长得像赋值的文本」）。改为对每个目标 catch 子句的**语句树**
    #   查找是否存在一条 `AssignmentStatementAst`，左值是变量 `coverageGap`（可选 `script:` 作用域前缀）、
    #   操作符是 `+=`——这类结构只可能来自真实可执行代码，注释/字符串天然不会被解析进 AST 语句节点。
    $clAst17p2 = [System.Management.Automation.Language.Parser]::ParseFile((Join-Path $RepoRoot 'scripts/check-licenses.ps1'), [ref]$null, [ref]$null)
    $catchClauses17p2 = $clAst17p2.FindAll({ param($n) $n -is [System.Management.Automation.Language.CatchClauseAst] }, $true)
    $p2Fail = $false
    $p2Blocks = @(
      @{ anchor = 'pip-licenses 输出解析失败'; label = '后端 pip-licenses' }
      @{ anchor = 'license-checker 解析失败';   label = '前端 license-checker' }
    )
    foreach ($b in $p2Blocks) {
      $target = $catchClauses17p2 | Where-Object { $_.Body.Extent.Text -match [regex]::Escape($b.anchor) } | Select-Object -First 1
      if (-not $target) {
        Fail "种子缺陷 17p2：未找到 $($b.label) 的 catch 块（结构漂移，锚点 '$($b.anchor)' 未命中）。"
        $p2Fail = $true
        continue
      }
      $hasAppend = @($target.Body.FindAll({
        param($n)
        $n -is [System.Management.Automation.Language.AssignmentStatementAst] `
          -and $n.Operator -eq [System.Management.Automation.Language.TokenKind]::PlusEquals `
          -and $n.Left -is [System.Management.Automation.Language.VariableExpressionAst] `
          -and $n.Left.VariablePath.UserPath -match '^(script:)?coverageGap$'
      }, $true)).Count -gt 0
      if (-not $hasAppend) {
        Fail "种子缺陷 17p2：$($b.label) 的 catch 块只 Write-Warning、未见真正的 `$coverageGap += 赋值语句（AST 级校验，注释/字符串不算）——解析失败被静默吞掉，零覆盖却可能 PASS（甚至 -Strict 下也 PASS）。"
        $p2Fail = $true
      }
    }
    if (-not $p2Fail) { Write-Host '  17p2 许可闸 JSON 解析失败 catch 块记 coverageGap OK（后端/前端两处均不再静默吞零覆盖）' -ForegroundColor Green }

    # 17p3. 许可闸前端扫描须真扫 frontend/ 子树（TD-205 · TD81 · T29-LICENSE-FRONTEND-DIR）：
    #   check-licenses.ps1:59 `Set-Location $RepoRoot` 后，前端块跑 `license-checker` 默认从 process.cwd()(=仓根)找
    #   package.json、恒扫仓根、从不进 frontend/——下游 frontend/ 的 GPL/AGPL 等违禁依赖漏判，却仍打印「已扫描 npm 包」(fail-open)。
    #   修复=显式 `--start $feDir` 指到前端目录。本子闸用**行为夹具**证明修复非 vacuous：临时夹具仓（含被测 check-licenses
    #   与其 _config/_encoding 依赖 + frontend/package.json + 只在 frontend/ 植一个 .gpl-marker）+ PATH 注入的 npx 桩
    #   （模拟 license-checker 的 --start/cwd 目录选择：据扫描目标目录是否含 .gpl-marker 决定吐含 GPL 的许可 JSON 还是 {}）。
    #   修复前扫 cwd/仓根→无标记→吐 {}→放行(exit 0)；修复后 --start frontend→有标记→吐 GPL→check-licenses 命中 forbidden→
    #   block(exit 1)。桩/夹具全离线确定、临时目录用毕即弃、PATH 用毕 finally 还原（同 15f 之理，不动元仓）。
    $fx3 = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-selftest-td205-$PID"
    $fx3OldPath = $env:PATH
    if (Test-Path $fx3) { Remove-Item -Recurse -Force $fx3 }
    try {
      $fx3Bin = Join-Path $fx3 'bin'; $fx3Scripts = Join-Path $fx3 'scripts'; $fx3Fe = Join-Path $fx3 'frontend'
      New-Item -ItemType Directory -Force $fx3Bin, $fx3Scripts, $fx3Fe | Out-Null
      # 被测件 + 其 dot-source 依赖（_config/_encoding）拷入夹具 scripts/，令 check-licenses 的 $PSScriptRoot/.. 解析到夹具根。
      Copy-Item (Join-Path $RepoRoot 'scripts/check-licenses.ps1') (Join-Path $fx3Scripts 'check-licenses.ps1')
      Copy-Item (Join-Path $RepoRoot 'scripts/_config.ps1')        (Join-Path $fx3Scripts '_config.ps1')
      Copy-Item (Join-Path $RepoRoot 'scripts/_encoding.ps1')      (Join-Path $fx3Scripts '_encoding.ps1')
      Set-Content (Join-Path $fx3Fe 'package.json') '{"name":"fe","version":"0.0.0"}' -Encoding utf8
      Set-Content (Join-Path $fx3Fe '.gpl-marker')  'seed: frontend subtree has a GPL dep' -Encoding utf8   # 只植前端子树
      $fx3Gpl = Join-Path $fx3 'gpl.json'   # 桩在「扫描目标含 .gpl-marker」时吐它（模拟前端有 GPL 依赖）
      Set-Content $fx3Gpl '{"gpl-pkg@1.0.0":{"licenses":"GPL-3.0-only"}}' -Encoding ascii
      # npx 桩：解析 --start <dir>（无则取 cwd），据该目录是否含 .gpl-marker 决定吐 GPL 还是 {}——模拟 license-checker 目录选择。
      if ($IsWindows) {
        Set-Content (Join-Path $fx3Bin 'npx.cmd') @(
          '@echo off'
          'set "SCAN=%CD%"'
          ':parse'
          'if "%~1"=="" goto done'
          'if /I "%~1"=="--start" set "SCAN=%~2"'
          'shift'
          'goto parse'
          ':done'
          "if exist ""%SCAN%\.gpl-marker"" (type ""$fx3Gpl"") else (echo {})"
        ) -Encoding ascii
      } else {
        Set-Content (Join-Path $fx3Bin 'npx') "#!/bin/sh`nSCAN=`"`$PWD`"`nwhile [ `$# -gt 0 ]; do`n  if [ `"`$1`" = `"--start`" ]; then SCAN=`"`$2`"; fi`n  shift`ndone`nif [ -f `"`$SCAN/.gpl-marker`" ]; then cat `"$fx3Gpl`"; else echo '{}'; fi`n" -Encoding ascii
        & chmod +x (Join-Path $fx3Bin 'npx') | Out-Null
      }
      $env:PATH = $fx3Bin + [System.IO.Path]::PathSeparator + $env:PATH
      & pwsh -NoProfile -File (Join-Path $fx3Scripts 'check-licenses.ps1') *> $null
      $fx3Exit = $LASTEXITCODE
      if ($fx3Exit -eq 0) {
        Fail "种子缺陷 17p3：前端 frontend/ 子树存在 GPL 依赖（.gpl-marker），但 check-licenses.ps1 从仓根跑 license-checker（未传 --start frontend）、漏扫前端子树、exit 0 放行——fail-open 许可闸（TD-205）。修复=前端扫描传 --start `$feDir 指到 frontend/，令违禁依赖被扫到并 block。"
      } else {
        Write-Host '  17p3 前端许可扫描 --start frontend OK（frontend/ 的 GPL 依赖被扫到并 block[exit 1]；不再从仓根漏扫）' -ForegroundColor Green
      }
    } finally {
      $env:PATH = $fx3OldPath
      Remove-Item -Recurse -Force $fx3 -ErrorAction SilentlyContinue
    }

    # 17q. handoff check 存活性校验（C31 · T6-HANDOFF-VALIDATE）：字段合法≠续接环境仍在。
    #   合法且存活基线（WORKTREE=(main checkout)/BRANCH=main）→ check 通过；WORKTREE 指向不存在路径 / BRANCH 指向不存在分支 → check 非零退出。
    #   子进程调用真实 handoff.ps1（CWD=仓库根，令其分支存活校验的 git rev-parse 在 git 仓内跑）。
    #   T179/TD170 adds a fourth probe on the same subprocess channel: a field value carrying a raw TAB (the
    #   L17 backslash-eating residue) must be refused. It rides here rather than staying a pure-function
    #   example because only this arm proves the REAL script reaches the judgement end to end.
    $hq = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-handoff-$PID"
    if (Test-Path $hq) { Remove-Item -Recurse -Force $hq }
    New-Item -ItemType Directory -Force $hq | Out-Null
    function New-HandoffProbe([string]$file, [string]$worktree, [string]$branch, [string]$nextAction = 'pwsh -File scripts/selftest.ps1') {
      @"
# progress
<!-- HANDOFF:START -->
STATUS: in-progress
TASK: hermetic handoff liveness probe
CARD: none
BRANCH: $branch
WORKTREE: $worktree
LAST-GREEN: abc12345 — selftest PASS
NEXT-ACTION: $nextAction
VERIFY: pwsh -File scripts/selftest.ps1
DO-NOT: none
OPEN-QUESTIONS: none
INVARIANTS: none
UPDATED: probe step 1
<!-- HANDOFF:END -->
"@ | Set-Content -Path $file -Encoding utf8
    }
    $qFail = $false
    try {
      $pOk = Join-Path $hq 'ok.md';       New-HandoffProbe $pOk     '(main checkout)' 'main'
      $pWt = Join-Path $hq 'deadwt.md';   New-HandoffProbe $pWt     (Join-Path $hq 'no-such-worktree') 'main'
      $pBr = Join-Path $hq 'deadbr.md';   New-HandoffProbe $pBr     '(main checkout)' "gone-branch-$PID"
      # The backtick-t is the point: it writes the exact byte an interpreter leaves where a backslash was,
      # so this probe's NEXT-ACTION is literally `scripts\task.ps1` after the L17 mangling (T140, T173).
      $pTab = Join-Path $hq 'tabbed.md';  New-HandoffProbe $pTab    '(main checkout)' 'main' "pwsh -NoProfile -File scripts`task.ps1 -Phase ship"
      Push-Location $RepoRoot   # 令 handoff.ps1 子进程的 git rev-parse 在 git 仓内跑（分支存活校验）
      try {
        & pwsh -NoProfile -File $hoScript check -Path $pOk *> $null
        if ($LASTEXITCODE -ne 0) { Fail '种子缺陷 17q：合法且存活的 HANDOFF（WORKTREE=(main checkout)/BRANCH=main）被 check 误拒。'; $qFail = $true }
        & pwsh -NoProfile -File $hoScript check -Path $pWt *> $null
        if ($LASTEXITCODE -eq 0) { Fail '种子缺陷 17q：WORKTREE 指向不存在路径的 HANDOFF 仍通过 check（C31：续接到已被 cleanup 拆除的 worktree）。'; $qFail = $true }
        & pwsh -NoProfile -File $hoScript check -Path $pBr *> $null
        if ($LASTEXITCODE -eq 0) { Fail '种子缺陷 17q：BRANCH 指向不存在分支的 HANDOFF 仍通过 check（C31：续接到已合并删除的分支）。'; $qFail = $true }
        & pwsh -NoProfile -File $hoScript check -Path $pTab *> $null
        if ($LASTEXITCODE -eq 0) { Fail '17q seeded defect (T179/TD170): a HANDOFF whose NEXT-ACTION carries a raw TAB still passed check. The L17 backslash-eating residue parses like any other value, so the resuming session receives a command that cannot run - measured twice on the live file with L17 already at tier:must.'; $qFail = $true }
      } finally { Pop-Location }
    } finally { Remove-Item -Recurse -Force $hq -ErrorAction SilentlyContinue }
    if (-not $qFail) { Write-Host '  17q handoff check 存活性 OK（WORKTREE 路径/BRANCH 不存在即拒续接；合法存活放行）+ a raw TAB in a field value is refused (T179)' -ForegroundColor Green }

    # 17s. R3 运行期裁决 schema 强制 + fail-closed 守卫对抗输入（TD48/TD-111）：
    #   verdict 解析历史上 case-insensitive（'PASS' -eq 'pass' 为真）且数组 {"verdict":["pass"]} 经 -eq 过滤为真值
    #   → 畸形/被诱导的第二模型后端可把非法裁决滑过成 pass。且 fail-closed 守卫（非零退出强制 block、sha 新鲜度、
    #   JSON 解析失败、缺 verdict）此前无任何**喂敌意输出**的执行测试（proof #3）。本闸对 7 类后端输出各建独立 fixture
    #   + stub（把该 case 的裁决 JSON 写 $env:REVIEW_OUT，可选控制退出码），断言 6 类敌意输出全 BLOCK（exit≠0）、
    #   1 类合法 pass 放行（exit 0）。unfixed 码放行 s5(大写 PASS)/s6(数组) → RED，证种子非 vacuous。
    $sCases = @(
      @{ tag = 's1-pass-nonzero-exit'; json = '{"verdict":"pass","reasons":[]}';                     tail = '; exit 3'; block = $true },
      @{ tag = 's2-pass-stale-sha';    json = '{"verdict":"pass","reasons":[],"sha":"deadbeefdeadbeef"}'; tail = ''; block = $true },
      @{ tag = 's3-not-json';          json = '{not json';                                            tail = ''; block = $true },
      @{ tag = 's4-missing-verdict';   json = '{"reasons":[]}';                                        tail = ''; block = $true },
      @{ tag = 's5-uppercase-verdict'; json = '{"verdict":"PASS","reasons":[]}';                       tail = ''; block = $true },
      @{ tag = 's6-array-verdict';     json = '{"verdict":["pass"],"reasons":[]}';                     tail = ''; block = $true },
      @{ tag = 's7-legit-pass';        json = '{"verdict":"pass","reasons":[]}';                       tail = ''; block = $false }
    )
    $sAllOk = $true
    $sIdx = 0
    foreach ($sc in $sCases) {
      $sIdx++
      $ss = Join-Path $sd "s$sIdx"
      Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $ss -Recurse -Force
      $cfgS = Join-Path $ss 'scripts/_config.ps1'
      # stub 后端命令体：'<json>' | Set-Content $env:REVIEW_OUT（+可选 tail）。json 内只用双引号；包 JSON 的单引号
      # 在 _config 单引号串里加倍（-replace "'","''"）。`$env 用反引号保 $ 字面、不在此双引号串里插值。
      $inner = "'" + $sc.json + "' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8" + $sc.tail
      $innerEsc = $inner -replace "'", "''"
      $lineS = "ReviewCommand = '$innerEsc'"
      $cS = (Get-Content $cfgS -Raw).Replace("ReviewCommand = ''", $lineS).Replace("ReviewGate = ''", "ReviewGate = 'required'")
      if (-not $cS.Contains($innerEsc)) { Fail "闸17s($($sc.tag))：裁决 stub 未注入（_config ReviewCommand 行格式变了？.Replace 没命中）。"; $sAllOk = $false; continue }
      Set-Content $cfgS $cS -NoNewline -Encoding utf8
      New-ReviewFixtureRepo $ss 'feat-s'
      Set-Content (Join-Path $ss 'CHANGED.txt') 'a change under review' -Encoding utf8
      & git -C $ss -c user.email='s@l' -c user.name='s' add -A 2>$null
      & git -C $ss -c user.email='s@l' -c user.name='s' commit -q -m change *> $null
      & pwsh -NoProfile -File (Join-Path $ss 'scripts/review.ps1') -WorktreePath $ss -Base master *> $null
      $sExit = $LASTEXITCODE
      if ($sc.block) {
        if ($sExit -eq 0) { Fail "种子缺陷 17s($($sc.tag))：敌意后端输出被放行（exit 0）——R3 运行期裁决 schema / fail-closed 守卫回归（TD48）：$($sc.json)$($sc.tail)。"; $sAllOk = $false }
      } else {
        if ($sExit -ne 0) { Fail "种子缺陷 17s($($sc.tag))：合法 pass 裁决被误 block（exit $sExit）——schema 强制过紧、误杀正常放行（TD48）：$($sc.json)。"; $sAllOk = $false }
      }
    }
    if ($sAllOk) { Write-Host '  17s R3 运行期裁决 schema 强制：6 类敌意输出全 block、合法 pass 放行 OK' -ForegroundColor Green }

    }
    if (Test-SeedRegionSelected 't') {
    Add-SeedRegionReceipt 't@17t'   # T194: execution evidence, filed from inside the guarded body
    # 17t. R3 阻断态**可诊断性**（TD96 核心半）：17s 证「敌意输出别放行」（闸强度），本闸证**阻断得说清是哪一种、
    #   给得出出路**。各态语义与恢复路由的真相源 = `docs/QUALITY-RUBRIC.md` §5，此处不复述。
    #   断言主锚是 **ASCII 状态码**而非英文措辞（措辞会改，状态码是契约 · L165）；**两个平面各司其职**：
    #   状态码比对 **stdout**（用处就是操作者在 ship 日志上看见），reason 面比对**规范化裁决 JSON**。
    #   **两平面担保只对「裁决文件写得进去」的用例成立**：t14/t15 的裁决落点本身被占（目录占位 / 只读），
    #   那份 JSON 读不出或不是本轮产物，故它们**只验 stdout 面**（`jsonReason = $false`）——这不是放宽，
    #   而是那一族的可审计记录本就落不了盘；正因如此，`[R3-VERDICT-WRITE-FAILED]` 会把这种局面**判成 block**。
    $tCases = @(
      # 不写 $env:REVIEW_OUT（stub 直接 exit 0）=> 文件不存在 => S1
      @{ tag = 't1-no-output';     body = 'exit 0';                                                                                       code = '[R3-NO-OUTPUT]';      block = $true },
      # 写散文、无花括号 => S2（拒答形状）
      @{ tag = 't2-refusal-prose'; body = "'I''m sorry, but I can''t help with that request.' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8"; code = '[R3-NO-VERDICT-JSON]'; block = $true },
      # 合法 pass 仍须放行 => 证新分支不过度触发（没把正常放行误 block）
      @{ tag = 't4-legit-pass';    body = "'{""verdict"":""pass"",""reasons"":[]}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8";   code = '';                     block = $false },
      # S3 = an object was read but does not meet the verdict schema. The four driven here are the four
      # that need a fixture; the fifth emit site (T283: nothing in the output parses at all) is reached by
      # a body no object of which closes, and its state is the same class (same-class sweep, rubric #17):
      # 只测其中一支会让另外三支的状态码悄悄漏掉或写歪，而它们的排查方向与 S1/S2 完全不同。
      @{ tag = 't5-json-parse-fail';  body = "'{""verdict"":}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8";                       code = '[R3-BAD-VERDICT-JSON]'; block = $true },
      @{ tag = 't6-missing-verdict';  body = "'{""reasons"":[]}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8";                     code = '[R3-BAD-VERDICT-JSON]'; block = $true },
      @{ tag = 't7-verdict-not-str';  body = "'{""verdict"":[""pass""],""reasons"":[]}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8"; code = '[R3-BAD-VERDICT-JSON]'; block = $true },
      @{ tag = 't8-verdict-bad-enum'; body = "'{""verdict"":""PASS"",""reasons"":[]}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8";  code = '[R3-BAD-VERDICT-JSON]'; block = $true },
      # S1 的两条边界：**零字节**与**只含空白**。后者是 `-not $raw` 判不出来的那一支——空白字符串在
      # `-not` 下为真值，会被送进 S2 并被描述成「评审者写了东西」，可它其实什么都没说。
      @{ tag = 't9-zero-byte';        body = "[System.IO.File]::WriteAllText(`$env:REVIEW_OUT, '')";                                        code = '[R3-NO-OUTPUT]';        block = $true },
      @{ tag = 't10-whitespace-only'; body = "[System.IO.File]::WriteAllText(`$env:REVIEW_OUT, ([string][char]32 + [char]9 + [char]13 + [char]10 + [char]32))"; code = '[R3-NO-OUTPUT]'; block = $true },
      # 合法裁决**省略 reasons** —— 注意这**不符 schema**（required 同时含 verdict 与 reasons），
      # pass 支若沿用兜底串，会拿一枚只该用于阻断的码去描述放行；block 支则被说成「读不出可用裁决」。
      @{ tag = 't11-pass-no-reasons';  body = "'{""verdict"":""pass""}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8";  code = ''; block = $false },
      @{ tag = 't12-block-no-reasons'; body = "'{""verdict"":""block""}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8"; code = ''; block = $true },
      # 原文**落盘失败**路径：stub 先把目标 raw 文件位置占成**目录**（Set-Content 写不进去），
      # 再写拒答散文 ⇒ S2 触发但保全失败。契约要求此时**说实话**：不得再宣称「已保全、去读」。
      @{ tag = 't13-raw-save-fails'; body = "New-Item -ItemType Directory -Force (Join-Path (Split-Path `$env:REVIEW_OUT -Parent) 'feat-t.raw.txt') | Out-Null; 'I refuse to review this.' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8"; code = '[R3-NO-VERDICT-JSON]'; block = $true },
      # 输出路径**存在但读不了**：stub 把 `$env:REVIEW_OUT 本身占成目录。此前用 `-ErrorAction SilentlyContinue`
      # 读，读故障与「没写」一律吞成空 ⇒ 被误报成 S1，操作者被指去查后端写入，而真因是路径被占（R3 r8）。
      # 本例的 `jsonReason = $false`：裁决 JSON 的落点正是被占的那个路径，读不出 reason 面属预期，只验 stdout。
      # （`$readFailed` 的另一入口 —— ReadAllText 抛异常的**加锁/权限拒绝** —— 不设夹具：跨进程持锁是计时相关的，
      #  会做出 flaky 闸；它与本例进入**同一个**已被覆盖的状态，不额外声称覆盖。）
      @{ tag = 't14-out-unreadable'; body = "New-Item -ItemType Directory -Force `$env:REVIEW_OUT | Out-Null"; code = '[R3-OUTPUT-UNREADABLE]'; block = $true; jsonReason = $false },
      # **合法 pass + 裁决落盘失败 ⇒ 仍须 block**（R3 r10）：stub 先写一份完全合法的 pass 裁决，再把该文件设为只读，
      # 于是「读得出 pass」但「写不回去」。r8 为让 S0 诊断可见而 catch 了写异常，却没把失败记进判定 ⇒
      # 这一路会回贴 success 并 exit 0，把基线的 fail-closed 变成 fail-open。本例正是那条回归的锁。
      # jsonReason = $false：裁决文件里留着的是 stub 写的那份 pass 原文（新裁决写不进去），读它只会误导。
      @{ tag = 't15-pass-but-write-fails'; body = "'{""verdict"":""pass"",""reasons"":[]}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8; Set-ItemProperty -LiteralPath `$env:REVIEW_OUT -Name IsReadOnly -Value `$true"; code = '[R3-VERDICT-WRITE-FAILED]'; block = $true; jsonReason = $false },
      # `axes` is optional for legacy backends, but once present its carried half cannot be discarded. This
      # schema-valid partial shape used to fall back wholesale to the top-level pass and erase spec:block.
      @{ tag = 't16-partial-axis-block'; body = "'{""verdict"":""pass"",""reasons"":[],""axes"":{""spec"":{""verdict"":""block"",""reasons"":[""partial spec finding""]}}}' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8"; code = ''; block = $true }
    )
    $tAllOk = $true
    foreach ($tc in $tCases) {
      # Fixture dirs are named by the tag's numeric prefix, not by loop index: the standalone cases below
      # (t17/t21/t23) own their own `t17`/`t21`/`t23` dirs, and index-naming would silently collide with
      # them when this table gains or loses entries (two cases sharing one fixture tree = mutual clobber, L158).
      # 顺带修掉既有的错位：表里没有 t3 标签，序号命名下 t4-legit-pass 落在 `t3` 目录、逐个后错一位。
      $ts = Join-Path $sd (($tc.tag -split '-')[0])
      Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $ts -Recurse -Force
      $cfgT = Join-Path $ts 'scripts/_config.ps1'
      $tEsc = $tc.body -replace "'", "''"
      $cT = (Get-Content $cfgT -Raw).Replace("ReviewCommand = ''", "ReviewCommand = '$tEsc'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
      if (-not $cT.Contains($tEsc)) { Fail "闸17t($($tc.tag))：stub 未注入（_config ReviewCommand 行格式变了？.Replace 没命中）。"; $tAllOk = $false; continue }
      Set-Content $cfgT $cT -NoNewline -Encoding utf8
      New-ReviewFixtureRepo $ts 'feat-t'
      Set-Content (Join-Path $ts 'CHANGED.txt') 'a change under review' -Encoding utf8
      & git -C $ts -c user.email='t@l' -c user.name='t' add -A 2>$null
      & git -C $ts -c user.email='t@l' -c user.name='t' commit -q -m change *> $null
      # stdout 必须捕获：只断言 .review JSON 的话，删掉 review.ps1 打印 reason 那句本闸照样全绿、
      # 而操作者在 ship 日志上什么也看不到（R3 r2）。故两侧都断言。
      $tOut = (& pwsh -NoProfile -File (Join-Path $ts 'scripts/review.ps1') -WorktreePath $ts -Base master 2>&1 | Out-String)
      $tExit = $LASTEXITCODE
      if ($tc.block -and $tExit -eq 0) { Fail "闸17t($($tc.tag))：应 block 的状态被放行（exit 0）——R3 fail-closed 回归。"; $tAllOk = $false; continue }
      if ((-not $tc.block) -and $tExit -ne 0) { Fail "闸17t($($tc.tag))：合法 pass 被误 block（exit $tExit）——新增的诊断分支过度触发、误杀正常放行（TD96）。"; $tAllOk = $false; continue }
      # 每个 case 都读裁决 JSON：`code` 为空的用例（t4/t11/t12）照样有 reason 面要验。早前把这段放在
      # `if (-not $tc.code) { continue }` 之后，那几条专项断言**永远到不了**——写了却从不执行，是另一种 vacuous。
      # 例外 `jsonReason = $false`（t14）：裁决落点本身被占，读不出 reason 面属预期，只验 stdout。
      # StrictMode 下缺键即抛，故必须 ContainsKey 判在场，不能直接取 $tc.jsonReason。
      $wantJsonReason = (-not $tc.ContainsKey('jsonReason')) -or $tc.jsonReason
      $tReason = ''
      $tRunStatus = ''
      $tRoundRunStatus = ''
      if ($wantJsonReason) {
        $vFile = Get-ChildItem (Join-Path $ts '.review') -Filter '*.json' -EA SilentlyContinue | Select-Object -First 1
        if (-not $vFile) { Fail "闸17t($($tc.tag))：未落规范化裁决 JSON（.review\*.json 不存在），无法判定诊断状态。"; $tAllOk = $false; continue }
        try { $tReason = ((Get-Content $vFile.FullName -Raw | ConvertFrom-Json).reasons -join ' ') } catch { }
        # T188 run_status: read the PRODUCER-side class off the same normalized verdict the reason face
        # comes from. Both files are addressed by EXACT NAME rather than the -Filter '*.json' first-match
        # above: the round-indexed sibling <branch>.r<N>.json now sits beside the pointer file, and a
        # first-match glob would silently start reporting whichever the enumerator happened to yield first.
        # StrictMode throws on an absent property, so presence is tested before the read - an absent key
        # must leave '' for the assertion to report, not take the gate down.
        try { $tvP = Get-Content (Join-Path $ts '.review/feat-t.json') -Raw | ConvertFrom-Json; if ($tvP.PSObject.Properties.Name -contains 'run_status') { $tRunStatus = [string]$tvP.run_status } } catch { }
      }
      # The ROUND SIBLING is read OUTSIDE the $wantJsonReason guard, and that placement is the point:
      # $env:REVIEW_OUT IS $verdictPath, so t14/t15 occupy or lock exactly the POINTER file - while
      # `<branch>.r<N>.json` is a different path that still gets written. Read inside the guard, the
      # `[R3-OUTPUT-UNREADABLE] -> tool_error` arm below was DEAD CODE: no fixture ever reached it, so it
      # would have passed every mutation while looking like coverage. Here it is the ONLY class face those
      # two cases have, which is exactly why it must not be skipped for them.
      try { $tvR = Get-Content (Join-Path $ts '.review/feat-t.r1.json') -Raw | ConvertFrom-Json; if ($tvR.PSObject.Properties.Name -contains 'run_status') { $tRoundRunStatus = [string]$tvR.run_status } } catch { }
      if ($tc.code) {
        if ($tOut -notmatch [regex]::Escape($tc.code)) {
          Fail "闸17t($($tc.tag))：状态码 $($tc.code) 没出现在 **console 输出**里——它只进了裁决文件，操作者在 ship 日志上看不到，本卡「阻断得说清是哪一种」那一半没交付（TD96）。"
          $tAllOk = $false; continue
        }
        if ($wantJsonReason -and $tReason -notmatch [regex]::Escape($tc.code)) {
          Fail "闸17t($($tc.tag))：裁决 reason 未带状态码 $($tc.code)——S1「无输出」与 S2「有输出但无 JSON 裁决」仍被压进同一条兜底文案，分类器拒答不可诊断（TD96）。实得：$tReason"
          $tAllOk = $false; continue
        }
      }
      # T188 run_status (TD181): `verdict` answers "may this merge?", `run_status` answers "how did the
      # run end?". They are INDEPENDENT facts and these fixtures prove it in BOTH directions - every hostile
      # or output-less case keeps verdict=block while its class varies, and t11/t12 keep class=success across
      # a pass AND a block. Expected class is DERIVED from the state code rather than restated per row,
      # because "state code X implies class Y" IS the contract: a per-row literal would let the code and the
      # class drift apart one row at a time without any single assertion ever going red.
      $tExpectRs = switch ($tc.code) {
        '[R3-NO-OUTPUT]'         { 'no_output' }
        '[R3-NO-VERDICT-JSON]'   { 'malformed' }
        '[R3-BAD-VERDICT-JSON]'  { 'malformed' }
        '[R3-OUTPUT-UNREADABLE]' { 'tool_error' }
        default                  { 'success' }
      }
      $tCodeText = if ($tc.code) { $tc.code } else { '(a cleanly parsed verdict)' }
      # The POINTER face is asserted only where the pointer is readable at all - that is what jsonReason
      # marks. t15 lands on `default` deliberately: its stub writes a legitimate pass, so the RUN succeeded
      # and the class is `success`; the block it ends on is stamped by [R3-VERDICT-WRITE-FAILED] AFTER
      # Write-Verdict has already returned, which is the one state that structurally cannot carry a class.
      if ($wantJsonReason -and $tRunStatus -cne $tExpectRs) {
        Fail "闸17t($($tc.tag)) run_status: run_status should be '$tExpectRs' for $tCodeText but is '$tRunStatus'. The verdict and HOW THE RUN ENDED are still collapsed into one field, so a reviewer timeout or a backend failure is indistinguishable from a genuine quality block and the operator cannot tell whether to fix the diff or retry the reviewer (TD181)."
        $tAllOk = $false; continue
      }
      # Asserted for EVERY case, t14/t15 INCLUDED. For those two it is the only class face there is.
      if ($tRoundRunStatus -cne $tExpectRs) {
        Fail "闸17t($($tc.tag)) run_status: the round-indexed sibling feat-t.r1.json should carry run_status '$tExpectRs' for $tCodeText but carries '$tRoundRunStatus'. Without the class on the round record, the round-indexed corpus TD161 built cannot separate 'two quality rounds then human adjudication' from 'the reviewer timed out twice' (TD181)."
        $tAllOk = $false; continue
      }
      # T188 t4-only: the class must SURVIVE the redaction walk into the TRACKED record. `.review/*.json` is
      # gitignored, so `.review/records/<branch>.jsonl` is the only face of this that reaches version control -
      # and the record DERIVES from the same $payload, so this assertion is what pins nobody adding a
      # status-shaped key to $recRedactKeys and silently emptying the audit trail of its class.
      if ($tc.tag -eq 't4-legit-pass') {
        $tRecPath = Join-Path (Join-Path (Join-Path $ts '.review') 'records') 'feat-t.jsonl'
        if (-not (Test-Path $tRecPath)) {
          Fail '闸17t(t4) run_status: the local review record .review/records/feat-t.jsonl was not written, so whether run_status reaches the diagnostic log cannot be judged.'
          $tAllOk = $false
        } else {
          $tRecTxt = Get-Content $tRecPath -Raw
          if ($tRecTxt -notmatch '"run_status"\s*:\s*"success"') {
            Fail "闸17t(t4) run_status: the local record carries no run_status=success - the class did not survive the redaction walk (was a status-shaped key added to `$recRedactKeys?). This record is ignored local diagnostics; published PR evidence is the shared record. Content: $tRecTxt"
            $tAllOk = $false
          }
        }
      }
      if ($tc.tag -eq 't16-partial-axis-block') {
        $partial16 = $null
        try { $partial16 = Get-Content (Join-Path $ts '.review/feat-t.json') -Raw | ConvertFrom-Json } catch { }
        $partialSpec16 = if ($partial16 -and $partial16.axes -and $partial16.axes.spec) { [string]$partial16.axes.spec.verdict } else { '' }
        $partialStandards16 = if ($partial16 -and $partial16.axes -and $partial16.axes.standards) { [string]$partial16.axes.standards.verdict } else { '' }
        if (-not $partial16 -or [string]$partial16.verdict -cne 'block' -or $partialSpec16 -cne 'block' -or $partialStandards16 -cne 'pass' -or (@($partial16.reasons) -join ' ') -notmatch 'partial spec finding') {
          Fail "闸17t(t16)：partial axes lost or softened its present spec:block (top=$([string]$partial16.verdict), spec=$partialSpec16, standards=$partialStandards16). A missing axis may inherit the top-level decision; a present blocking axis may never be discarded."
          $tAllOk = $false
        }
      }
      # t2 专项：S2 承诺「原文另存在某处、你自己去读」，那么那个地方就必须**真的读得到原文**——
      # 首版指向的 `$verdictPath` 随后被 Write-Verdict 整个覆盖，指针悬空而当时的 t2 只验状态码、测不到（R3 r6）。
      if ($tc.tag -eq 't2-refusal-prose') {
        # 断言面须**恰好等于**契约面（L165）：契约是「原文逐字保全在 `<branchSafe>.raw.txt`」，故路径按
        # **确切文件名**取（不 glob）、内容按**整串大小写敏感相等**比——glob+子串在文件名写错或内容被截断时仍绿（R3 r7）。
        $rawExpectName = 'feat-t.raw.txt'
        $rawExpectPath = Join-Path (Join-Path $ts '.review') $rawExpectName
        $rawExpectText = "I'm sorry, but I can't help with that request." + [Environment]::NewLine
        if (-not (Test-Path $rawExpectPath)) {
          Fail "闸17t(t2)：S2 承诺的原文产物不在**确切路径** $rawExpectName（.review 下实有：$((Get-ChildItem (Join-Path $ts '.review') -EA SilentlyContinue | ForEach-Object Name) -join ', ')）——文件名漂了或压根没落盘，操作者按 reason 去读会扑空。"
          $tAllOk = $false
        } else {
          $rawTxt = [System.IO.File]::ReadAllText($rawExpectPath)
          if (-not ($rawTxt -ceq $rawExpectText)) {
            Fail "闸17t(t2)：原文产物内容与评审者原话**不逐字相等**（期望 $($rawExpectText.Length) 字符，实得 $($rawTxt.Length)：'$($rawTxt.Substring(0,[Math]::Min(80,$rawTxt.Length)))'）——被截断/改写/编码漂移，操作者读到的不是评审者说的那段。"
            $tAllOk = $false
          }
          if ($tReason -notmatch [regex]::Escape($rawExpectName)) {
            Fail "闸17t(t2)：reason 没点名那份原文产物（$rawExpectName）——操作者不知道该去哪读。实得：$tReason"
            $tAllOk = $false
          }
        }
      }
      # t13 专项：保全失败时**必须说实话**——不得宣称已保全、也不得再指人去读一个不存在的文件。
      if ($tc.tag -eq 't13-raw-save-fails') {
        if ($tReason -match 'preserved verbatim') {
          Fail "闸17t(t13)：原文落盘失败，reason 却仍宣称『preserved verbatim』——把操作者指向一个写不出来的文件（R3 r7）。实得：$tReason"
          $tAllOk = $false
        }
        if ($tReason -notmatch 'could NOT be written') {
          Fail "闸17t(t13)：原文落盘失败却没给出**如实的**失败说明（应含 could NOT be written）——操作者不知道原文根本不可得。实得：$tReason"
          $tAllOk = $false
        }
        # 卡片承诺「本地化细节改打 ship 控制台」——那就得**真有一条**打出来，且带稳定英文前缀。
        # 早前 catch 把 $_.Exception 整个丢了，reason 里的泛化措辞照样让本例绿 ⇒ 承诺无人验（R3 r12）。
        if ($tOut -notmatch [regex]::Escape('[R3-RAW-SAVE-FAILED]')) {
          Fail '闸17t(t13)：原文落盘失败时没在控制台打出 [R3-RAW-SAVE-FAILED] 诊断——本地化细节被静默丢弃，卡片「细节改打控制台」的承诺没兑现。'
          $tAllOk = $false
        }
      }
      # t14 专项：读故障**不得被说成「评审者没写」**。这条负断言就是缺陷本身的形状——
      # 用 `-EA SilentlyContinue` 读时，被占的路径读出 $null ⇒ 落进 S1 并印 [R3-NO-OUTPUT]，
      # 把人指去查后端写入故障，而真因是路径被目录占着（R3 r8）。
      if ($tc.tag -eq 't14-out-unreadable') {
        if ($tOut -match [regex]::Escape('[R3-NO-OUTPUT]')) {
          Fail "闸17t(t14)：输出路径存在但读不了，却被诊断成 S1『评审者没写输出』（[R3-NO-OUTPUT]）——读故障被静默吞成空，操作者被指向错误的排查方向（R3 r8）。"
          $tAllOk = $false
        }
        # 裁决落点被占 ⇒ Write-Verdict 必然写不进去。它若让异常逃逸，脚本会在**打印 reason 之前**就死掉，
        # 于是这枚专为「说清故障」而设的状态反倒最看不见。故断言：落盘失败被如实报出、且判定仍抵达控制台。
        if ($tOut -notmatch [regex]::Escape('[R3-VERDICT-WRITE-FAILED]')) {
          Fail "闸17t(t14)：裁决落点被占、Write-Verdict 必然失败，却没报出 [R3-VERDICT-WRITE-FAILED]——要么异常逃逸把脚本打死在打印判定之前（诊断态反而最看不见），要么落盘失败被静默吞掉。"
          $tAllOk = $false
        }
      }
      # t11/t12 专项：合法裁决省略 reasons 时 reasons **须被重置为空**。直接量**契约本身**（= 空），
      # 不用「不含 `[R3-`」这种代理——r4 把兜底串的状态码摘掉后该代理当场失明（兜底串还在却不再以 `[R3-` 开头），
      # 变异 Q 撞出这一点：**上一轮的修复，悄悄废掉了上一轮的测试**。
      if ($tc.tag -in @('t11-pass-no-reasons', 't12-block-no-reasons')) {
        if (-not [string]::IsNullOrWhiteSpace($tReason)) {
          Fail "闸17t($($tc.tag))：合法裁决省略 reasons 时 reasons 未被重置为空——兜底串残留会让 pass 带着一段阻断话术、或把一次正当的 block 说成「读不出可用裁决」。实得：$tReason"
          $tAllOk = $false
        }
      }
    }

    # t17：`ReadAllText` 抛异常那一支（加锁/权限拒绝）——S0 契约明写覆盖这类，就必须真测到（R3 r10 #3）。
    $ts17 = Join-Path $sd 't17'
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $ts17 -Recurse -Force
    $b17 = "'irrelevant prose' | Set-Content -Path `$env:REVIEW_OUT -Encoding utf8; if (`$IsWindows) { `$a = Get-Acl `$env:REVIEW_OUT; `$a.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.WindowsIdentity]::GetCurrent().Name,'Read','Deny'))); Set-Acl -Path `$env:REVIEW_OUT -AclObject `$a } else { & chmod 000 `$env:REVIEW_OUT }"
    $cfg17 = Join-Path $ts17 'scripts/_config.ps1'
    $e17 = $b17 -replace "'", "''"
    $c17 = (Get-Content $cfg17 -Raw).Replace("ReviewCommand = ''", "ReviewCommand = '$e17'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if (-not $c17.Contains($e17)) { Fail '闸17t(t17)：stub 未注入（_config ReviewCommand 行格式变了？）'; $tAllOk = $false }
    else {
      Set-Content $cfg17 $c17 -NoNewline -Encoding utf8
      New-ReviewFixtureRepo $ts17 'feat-t'
      Set-Content (Join-Path $ts17 'CHANGED.txt') 'a change under review' -Encoding utf8
      & git -C $ts17 -c user.email='t@l' -c user.name='t' add -A 2>$null
      & git -C $ts17 -c user.email='t@l' -c user.name='t' commit -q -m change *> $null
      $o17 = (& pwsh -NoProfile -File (Join-Path $ts17 'scripts/review.ps1') -WorktreePath $ts17 -Base master 2>&1 | Out-String)
      $x17 = $LASTEXITCODE
      # 反 vacuous：先确认这台机器**真的**造出了「是文件、但读不了」——否则本例只是重跑了一遍 S2。
      $vp17 = Join-Path (Join-Path $ts17 '.review') 'feat-t.json'
