      if (Test-Path -LiteralPath $stale23) {
        Fail '闸17t(t23)：上一轮残留的 feat-t.raw.txt 在本轮结束后仍在——S1 说没有原文，操作者却会在文档写明的路径上读到**上一轮**的旧件并误当本轮产物（R3 r17）。'
        $tAllOk = $false
      }
    }
    # t24 (T188/TD181): the INJECTED TIMEOUT, and the one case the table above structurally cannot carry -
    # it needs its own `-TimeoutSec`, so it is standalone like t17/t21/t23. This is the case the whole row
    # exists for: a reviewer that never answers is an INFRASTRUCTURE failure whose right next move is
    # "retry the reviewer", yet today it is reported with exactly the shape of "fix your diff". The stub
    # sleeps far past a 3s budget and never writes $env:REVIEW_OUT, so the process tree is killed and no
    # fresh verdict exists. Contract: verdict STAYS `block` (fail-closed is correct and is not what TD181
    # disputes) while run_status becomes `timeout` - the two facts separating for the first time.
    $ts24 = Join-Path $sd 't24'
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $seedSkip } | Copy-Item -Destination $ts24 -Recurse -Force
    $b24 = 'Start-Sleep -Seconds 30'
    $cfg24 = Join-Path $ts24 'scripts/_config.ps1'
    $e24 = $b24 -replace "'", "''"
    $c24 = (Get-Content $cfg24 -Raw).Replace("ReviewCommand = ''", "ReviewCommand = '$e24'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if (-not $c24.Contains($e24)) { Fail '闸17t(t24)：stub 未注入（_config ReviewCommand 行格式变了？）'; $tAllOk = $false }
    else {
      Set-Content $cfg24 $c24 -NoNewline -Encoding utf8
      New-ReviewFixtureRepo $ts24 'feat-t'
      Set-Content (Join-Path $ts24 'CHANGED.txt') 'a change under review' -Encoding utf8
      & git -C $ts24 -c user.email='t@l' -c user.name='t' add -A 2>$null
      & git -C $ts24 -c user.email='t@l' -c user.name='t' commit -q -m change *> $null
      $o24 = (& pwsh -NoProfile -File (Join-Path $ts24 'scripts/review.ps1') -WorktreePath $ts24 -Base master -TimeoutSec 3 2>&1 | Out-String)
      $x24 = $LASTEXITCODE
      if ($x24 -eq 0) { Fail '闸17t(t24)：评审者超时被杀却仍放行（exit 0）——R3 fail-closed 回归。'; $tAllOk = $false }
      elseif ($o24 -notmatch [regex]::Escape('[R3-REVIEWER-TIMEOUT]')) {
        Fail "闸17t(t24)：超时没打出 [R3-REVIEWER-TIMEOUT]——操作者在 ship 日志上看不出这是预算信号而非质量判断（§4）。实得：$o24"
        $tAllOk = $false
      } else {
        $v24 = ''; $rs24 = ''; $rrs24 = ''
        try {
          $j24 = Get-Content (Join-Path (Join-Path $ts24 '.review') 'feat-t.json') -Raw | ConvertFrom-Json
