          if ($j24.PSObject.Properties.Name -contains 'run_status') { $rs24 = [string]$j24.run_status }
        } catch { }
        try {
          $r24 = Get-Content (Join-Path (Join-Path $ts24 '.review') 'feat-t.r1.json') -Raw | ConvertFrom-Json
          if ($r24.PSObject.Properties.Name -contains 'run_status') { $rrs24 = [string]$r24.run_status }
        } catch { }
