    if (-not $c25.Contains($e25)) { Fail '闸17t(t25)：stub 未注入（_config ReviewCommand 行格式变了？）'; $tAllOk = $false }
    elseif (-not $rt25.Contains($seed25)) {
      Fail "闸17t(t25)：找不到要植入缺陷的终末调用『$seed25』——review.ps1 的调用形态变了，本用例等于没测（vacuous）。"
      $tAllOk = $false
    } else {
      Set-Content $cfg25 $c25 -NoNewline -Encoding utf8
      # BOM preserved deliberately: gate 7 lints .ps1 files and the fixture tree is a full repo copy.
      [System.IO.File]::WriteAllText($rv25, $rt25.Replace($seed25, 'Write-Verdict $verdict $reasons'), [System.Text.UTF8Encoding]::new($true))
