      New-ReviewFixtureRepo $ts26 'feat-t'
      Set-Content (Join-Path $ts26 'CHANGED.txt') 'a change under review' -Encoding utf8
      & git -C $ts26 -c user.email='t@l' -c user.name='t' add -A 2>$null
