    # asks whether ONE NAMED field survived the elision, not whether a given line is a field.
    $haAnchors = @()
    foreach ($haF in $haFiles) {
      foreach ($haLit in $haAsts[$haF].FindAll({ param($node) $node -is [System.Management.Automation.Language.StringConstantExpressionAst] }, $true)) {
