    $ztLogCMissing = Get-Content $zTimeoutLog -Raw -ErrorAction SilentlyContinue
    if (($ztCEmpty -ne 0) -or ($ztCMissing -ne 0)) { Fail "闸17z T43-TimeoutDefaultMissingOrEmpty：ReviewTimeoutSec 留空/缺键时抛错或非零退出（empty=$ztCEmpty, missing=$ztCMissing）。" }
    elseif (($ztLogCEmpty -notmatch '\[R3-TIMEOUT-BUDGET\] 600s') -or ($ztLogCMissing -notmatch '\[R3-TIMEOUT-BUDGET\] 600s')) { Fail "闸17z T43-TimeoutDefaultMissingOrEmpty [17z-BUDGET-DEFAULT]：ReviewTimeoutSec 留空/缺键时未退回内建 600s（empty=$ztLogCEmpty, missing=$ztLogCMissing）。" }
    elseif (-not $fail) { Write-Host '  17z R3 超时预算三级优先级：CLI 覆盖配置、配置生效、留空/缺键退回内建 600s OK' -ForegroundColor Green }

    # (4) 自定义 ReviewCommand 后端：只经 env 透传（L26），且不得调起 codex
    Set-ZConfig 'env-model' 'env-effort'
    $zStub = '$null = [Console]::In.ReadToEnd(); Set-Content -Path ($env:REVIEW_OUT + ''.env.txt'') -Value ("M=" + $env:REVIEW_MODEL + ";E=" + $env:REVIEW_EFFORT); Set-Content -Path $env:REVIEW_OUT -Value ''{"verdict":"pass","reasons":[]}'''
    # 嵌进 _config 的**单引号字面量**前必须把内部单引号成对转义，否则 _config.ps1 语法即崩、review.ps1 dot-source 失败（本轮实测）。
    $zStubEsc = $zStub.Replace("'", "''")
    $zCfg4 = (Get-Content $zCfg -Raw).Replace("ReviewCommand = ''", "ReviewCommand = '$zStubEsc'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
    if ($zCfg4 -notmatch 'REVIEW_EFFORT') { Fail '闸17z(4)：ReviewCommand stub 未注入（_config 的 ReviewCommand 行格式变了？）。' }
    Set-Content $zCfg -Value $zCfg4 -Encoding utf8
    $z4 = Invoke-ZReview @()
    $e4 = Get-Content ($zVer + '.env.txt') -Raw -ErrorAction SilentlyContinue
    $a4 = Get-Content $zArgv -Raw -ErrorAction SilentlyContinue
    if ($z4 -ne 0) { Fail "闸17z(4)：自定义 ReviewCommand 后端下 review.ps1 非零退出（$z4）。" }
    elseif (-not $e4) { Fail '闸17z(4)：自定义后端未收到 env——REVIEW_MODEL/REVIEW_EFFORT 未透传（L26 透传断裂）。' }
    elseif ($e4 -notmatch 'M=env-model' -or $e4 -notmatch 'E=env-effort') { Fail "闸17z(4)：自定义后端收到的 env 不是 _config 的值（收到：$e4）。" }
    elseif ($a4) { Fail '闸17z(4)：设了 ReviewCommand 却仍调起了 codex（argv 文件存在）——后端选择逻辑坏了。' }

    # (5) 向后兼容：**旧 _config**（无两键、无两个便捷函数）下 review.ps1 仍须跑通、且省略两个 flag。
    #     模拟 fleet 回填半程：review.ps1 已升级、_config 还是旧的（R3 评审指出的真实失效面）。
    $zOld = $zCfgBase
    $zOld = [regex]::Replace($zOld, "(?m)^\s*ReviewModel\s*=\s*'[^']*'\s*$", '')
    $zOld = [regex]::Replace($zOld, "(?m)^\s*ReviewEffort\s*=\s*'[^']*'\s*$", '')
    $zOld = [regex]::Replace($zOld, '(?s)function Get-ScaffoldReviewModel \{.*?\n\}', '')
    $zOld = [regex]::Replace($zOld, '(?s)function Get-ScaffoldReviewEffort \{.*?\n\}', '')
    if ($zOld.Contains('ReviewModel =') -or $zOld.Contains('function Get-ScaffoldReviewModel')) { Fail '闸17z(5)：未能构造「旧 _config」夹具（字面量格式变了？）——否则本例假绿。' }
    Set-Content $zCfg -Value $zOld -Encoding utf8
    $z5 = Invoke-ZReview @()
    $a5 = Get-Content $zArgv -Raw -ErrorAction SilentlyContinue
    if ($z5 -ne 0) { Fail "闸17z(5)：旧 _config（无 ReviewModel/ReviewEffort 键与便捷函数）下 review.ps1 非零退出（$z5）——升级 review.ps1 却未同步 _config 即崩，连 fail-closed 裁决都写不出。" }
    elseif (-not $a5) { Fail '闸17z(5)：旧 _config 下假 codex 未被调起。' }
    elseif (($a5 -match '\s-m\s') -or ($a5 -match 'model_reasoning_effort')) { Fail "闸17z(5)：旧 _config 下仍传了 -m / -c——应优雅退回后端默认（argv=$a5）。" }
    elseif (-not $fail) { Write-Host '  17z R3 模型/档位钉在项目配置：argv 真送达 codex（-m / -c model_reasoning_effort=）、留空即省略 flag、CLI 覆盖 _config、自定义后端经 env 透传且不调 codex、旧 _config 优雅降级 OK' -ForegroundColor Green }

  }
  finally {
    $env:PATH = $zSavedPath
    Remove-Item -Recurse -Force $zRoot -ErrorAction SilentlyContinue
  }
}

# ── 17aa. 评审基线取**远端跟踪引用** origin/<base>，不取可能陈旧的同名本地分支（TD68）──
#   现场：`symbolic-ref refs/remotes/origin/HEAD` 得 'origin/master'，旧代码 -replace 剥成本地 'master'。
#   本地 master 落后 origin/master N 个提交时，`git diff master...HEAD` 的 merge-base 落在旧点上，
#   那 N 个**早已在基线里**的提交会被当成本次 PR 的改动喂给评审者（本仓实测混入 3 个无关文件）。
#   反向亦险：本地 base 领先远端时，属于本 PR 的改动会被隐藏、评审者根本看不到。
#   夹具：造 bare origin + 工作克隆；origin/master=B，本地 master 强制回退到 A；分支 feat-base 自 B 起 + 提交 C。
#   断言送达评审者的 prompt **含 C、不含 B**。仅 Windows（复用 17h 的假 codex.ps1 shim 形态）。
if (-not $gitPost) {
  Write-Host '  17aa skipped (git absent; the stale-local-base fixture repo cannot be built)' -ForegroundColor DarkGray
}
elseif (-not $IsWindows) {
  Write-Host '  17aa 跳过（假 codex.ps1 shim 为 Windows 特有）。' -ForegroundColor DarkGray
}
else {
  $bRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("st17aa_" + [guid]::NewGuid().ToString('N').Substring(0, 8))
  $bSavedPath = $env:PATH
  try {
    $bOrigin = Join-Path $bRoot 'origin.git'
    $bw = Join-Path $bRoot 'w'
    New-Item -ItemType Directory -Force $bw | Out-Null
    & git init --bare -q $bOrigin
    $bSkip = @('.git', 'wt', '_local', '.review', 'node_modules', 'review')
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $bSkip } | Copy-Item -Destination $bw -Recurse -Force
    # 假 codex.ps1：把送达的 prompt 原文落 <REVIEW_OUT>.prompt.txt，并写一个 pass 裁决。
    $bBin = Join-Path $bRoot 'fakebin'; New-Item -ItemType Directory -Force $bBin | Out-Null
    $bFake = @'
$o = ''
for ($i = 0; $i -lt $args.Count; $i++) { if ($args[$i] -eq '--output-last-message') { $o = $args[$i + 1] } }
$raw = ($input | Out-String)
if ($o) {
  $raw | Set-Content -Path ($o + '.prompt.txt') -Encoding utf8
  '{"verdict":"pass","reasons":[]}' | Set-Content -Path $o -Encoding utf8
}
exit 0
'@
    Set-Content (Join-Path $bBin 'codex.ps1') $bFake -Encoding utf8

    & git -C $bw init -q
    & git -C $bw symbolic-ref HEAD refs/heads/master
    & git -C $bw -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $bw -c user.email='s@l' -c user.name='s' commit -q -m A *> $null   # 提交 A
    & git -C $bw remote add origin $bOrigin
    & git -C $bw push -q -u origin master *> $null
    # 提交 B：一个**与本 PR 无关**、但会先于分支点进入基线的改动
    Set-Content (Join-Path $bw 'UNRELATED-B.txt') 'unrelated commit already in the baseline' -Encoding utf8
    & git -C $bw -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $bw -c user.email='s@l' -c user.name='s' commit -q -m B *> $null
    & git -C $bw push -q origin master *> $null                                   # origin/master = B
    $bShaA = (& git -C $bw rev-parse master~1).Trim()
    # 分支自 B 起，加提交 C（本 PR 的真实改动）
    & git -C $bw -c user.email='s@l' -c user.name='s' checkout -q -b feat-base
    Set-Content (Join-Path $bw 'FEATURE-C.txt') 'the actual change under review' -Encoding utf8
    & git -C $bw -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $bw -c user.email='s@l' -c user.name='s' commit -q -m C *> $null
    # 让**本地** master 陈旧（退回 A）；origin/master 仍是 B。真实克隆里 origin/HEAD 由 clone 建，这里显式补上。
    & git -C $bw branch -f master $bShaA
    & git -C $bw symbolic-ref refs/remotes/origin/HEAD refs/remotes/origin/master
    $bFeatSha = (& git -C $bw rev-parse feat-base).Trim()
    $bVerdictFile = Join-Path $bw '.review/feat-base.json'
    function Invoke-BReview {
      Remove-Item -Recurse -Force (Join-Path $bw '.review') -ErrorAction SilentlyContinue
      $env:PATH = "$bBin$([System.IO.Path]::PathSeparator)$bSavedPath"
      try { & pwsh -NoProfile -File (Join-Path $bw 'scripts/review.ps1') -WorktreePath $bw *> $null }
      finally { $env:PATH = $bSavedPath }
      $script:bExit = $LASTEXITCODE
      return (Get-Content ($bVerdictFile + '.prompt.txt') -Raw -ErrorAction SilentlyContinue)
    }

    # (1) 本地 base **落后**远端：旧写法会把基线里的 B 当成本次改动喂进来。
    & git -C $bw branch -f master $bShaA
    if ((& git -C $bw rev-parse --short master).Trim() -eq (& git -C $bw rev-parse --short origin/master).Trim()) {
      Fail '闸17aa(1)：夹具没造出「本地 master 落后 origin/master」的局面——本例会假绿。'
    }
    $bPrompt = Invoke-BReview
    if ($bExit -ne 0) { Fail "闸17aa(1)：假 codex 下 review.ps1 非零退出（$bExit）——夹具或基线解析坏了。" }
    elseif (-not $bPrompt) { Fail '闸17aa(1)：假 codex 未落 prompt 文件——评审者未被调起。' }
    elseif ($bPrompt -notmatch 'FEATURE-C\.txt') { Fail '闸17aa(1)：送达评审者的 diff 不含本次改动 FEATURE-C.txt。' }
    elseif ($bPrompt -match 'UNRELATED-B\.txt') { Fail '种子缺陷 17aa(1)（TD68）：送达评审者的 diff 混入了 UNRELATED-B.txt——基线用了陈旧的**本地** master 而非 origin/master，评审的是错的范围。' }

    # (2) 本地 base **领先**远端（含分支的提交）：旧写法的 merge-base 落在 feat 上 → diff 为空 →
    #     属于本 PR 的改动被**隐藏**，评审者一无所知却给 pass（fail-open，比 (1) 更危险）。
    & git -C $bw branch -f master $bFeatSha
    $bPrompt2 = Invoke-BReview
    if ($bExit -ne 0) { Fail "闸17aa(2)：本地 base 领先远端时 review.ps1 非零退出（$bExit）。" }
    elseif (-not $bPrompt2) { Fail '闸17aa(2)：假 codex 未落 prompt 文件。' }
    elseif ($bPrompt2 -notmatch 'FEATURE-C\.txt') { Fail '种子缺陷 17aa(2)（TD68 反向）：本地 base 领先远端时，本次改动 FEATURE-C.txt 从送达评审者的 diff 里消失了——评审者看不到却会给 pass（fail-open）。基线须取 origin/<base>。' }

    # Note: a card's `review_gate:` verdict literal is visible to the reviewer in the diff body (TD83) —
    #     the diff is deliberately NOT neutralized (that would blind the reviewer to real hunks). TD83 was
    #     closed as paid via the T12 stance; the stance block and its gate were later removed with the
    #     mandatory review gate (T69) — under advisory review a forged verdict gains nothing enforceable.
    & git -C $bw branch -f master $bShaA
    # (5) 基线与 HEAD **无共同祖先**（unrelated histories）：`git diff base...HEAD` exit 128、stdout 为空。
    #     _encoding.ps1 把 $PSNativeCommandUseErrorActionPreference 设为 $false（按码判、不抛），故若不显式检查，
    #     评审者会收到**空 diff** 并可能在「什么都没看到」的情况下给 pass —— fail-open。须 fail-closed block。
    if (-not $fail) {
      & git -C $bw checkout -q --orphan orphan-x
      & git -C $bw -c user.email='s@l' -c user.name='s' commit -q -m orphan *> $null
      Remove-Item -Recurse -Force (Join-Path $bw '.review') -ErrorAction SilentlyContinue
      $env:PATH = "$bBin$([System.IO.Path]::PathSeparator)$bSavedPath"
      try { & pwsh -NoProfile -File (Join-Path $bw 'scripts/review.ps1') -WorktreePath $bw -Base master *> $null }
      finally { $env:PATH = $bSavedPath }
      $b5Exit = $LASTEXITCODE
      $b5Verdict = Get-Content (Join-Path $bw '.review/orphan-x.json') -Raw -ErrorAction SilentlyContinue
      $b5Prompt = Get-Content (Join-Path $bw '.review/orphan-x.json.prompt.txt') -Raw -ErrorAction SilentlyContinue
      if ($b5Exit -eq 0) { Fail '种子缺陷 17aa(5)：基线与 HEAD 无共同祖先时 review.ps1 仍退出 0——空 diff 被送去评审、评审者在看不到任何改动的情况下可给 pass（fail-open）。' }
      elseif ($b5Prompt) { Fail '种子缺陷 17aa(5)：无共同祖先时仍调起了评审者（落了 prompt 文件）——应在构造 prompt 之前就 fail-closed 阻断。' }
      elseif (-not $b5Verdict -or $b5Verdict -notmatch '"verdict"\s*:\s*"block"') { Fail "闸17aa(5)：无共同祖先时未写出 block 裁决（exit $b5Exit）——fail-closed 未生效。" }
      elseif ($b5Verdict -notmatch 'merge base') { Fail '闸17aa(5)：block 裁决的 reason 未点明「无共同祖先 / no merge base」——排障线索缺失。' }
    }
    if (-not $fail) { Write-Host '  17aa 基线取 origin/<base>：落后不混入 / 领先不隐藏 / 无共同祖先 fail-closed OK（TD68）' -ForegroundColor Green }
  }
  finally {
    $env:PATH = $bSavedPath
    Remove-Item -Recurse -Force $bRoot -ErrorAction SilentlyContinue
  }
}

# ── 17aa(6). 共享解析器 Resolve-ScaffoldBaseRef 单元测试 + 两处调用点静态防漂移（TD68 根因收敛，跨平台）──
#   R3（PR #102）指出 task.ps1 的**确定性范围闸**（line 318）吃同一个「用本地 $Base」的 bug。把「名→ref」解析
#   收敛到 scripts/_gitbase.ps1，review.ps1 与 task.ps1 共用。这里直接喂它「本地落后 origin」的仓，断言返回
#   origin/master；再静态守两处调用点都经该函数、都不再用本地 $Base 算 diff（防再次一处修一处漏）。
if (-not $fail) {
  $gbFile = Join-Path $RepoRoot 'scripts/_gitbase.ps1'
  if (-not (Test-Path $gbFile)) { Fail '17aa(6)：scripts/_gitbase.ps1 缺失——TD68 的共享基线解析器不存在。' }
  elseif (-not $gitPost) {
    Write-Host '  17aa(6) resolver fixture skipped (git absent; the static drift guards over task.ps1/review.ps1/_gitbase.ps1 below still run)' -ForegroundColor DarkGray
  }
  else {
    $gbRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("st17aa6_" + [guid]::NewGuid().ToString('N').Substring(0, 8))
    try {
      $gbOrigin = Join-Path $gbRoot 'o.git'; $gbw = Join-Path $gbRoot 'w'
      New-Item -ItemType Directory -Force $gbw | Out-Null
      # setup 命令一律查退出码——否则「造出的输入」可能根本没造成（R3 PR#102 七轮：branch -f 在 master 被检出时 exit 128、
      # 被静默忽略，「本地落后」场景从未成立，断言假绿）。GS = git-setup-with-exit-check。
      function GS { param([string[]]$a) & git -C $gbw @a; if ($LASTEXITCODE -ne 0) { Fail "17aa(6) setup 失败（exit $LASTEXITCODE）：git $($a -join ' ')" } }
      & git init --bare -q $gbOrigin
      if ($LASTEXITCODE -ne 0) { Fail '17aa(6) setup 失败：git init --bare origin' }
      GS @('init', '-q')
      GS @('symbolic-ref', 'HEAD', 'refs/heads/master')
      Set-Content (Join-Path $gbw 'x.txt') 'a' -Encoding utf8
      GS @('-c', 'user.email=s@l', '-c', 'user.name=s', 'add', '-A')
      GS @('-c', 'user.email=s@l', '-c', 'user.name=s', 'commit', '-q', '-m', 'a')
      $gbA = (& git -C $gbw rev-parse master).Trim()
      Set-Content (Join-Path $gbw 'x.txt') 'b' -Encoding utf8
      GS @('-c', 'user.email=s@l', '-c', 'user.name=s', 'commit', '-aq', '-m', 'b')
      $gbB = (& git -C $gbw rev-parse master).Trim()
      Set-Content (Join-Path $gbw 'x.txt') 'c' -Encoding utf8
      GS @('-c', 'user.email=s@l', '-c', 'user.name=s', 'commit', '-aq', '-m', 'c')
      $gbC = (& git -C $gbw rev-parse master).Trim()
      GS @('remote', 'add', 'origin', $gbOrigin)
      # origin/master := B（推 B，不推 C）。先把 master 移到 B 再 push，再 detach 以便自由改本地 master ref。
      GS @('checkout', '-q', '--detach', $gbC)       # detach，master 不再被检出 → branch -f 可用（R3 七轮）
      GS @('branch', '-f', 'master', $gbB)
      GS @('push', '-q', '-u', 'origin', 'master')   # origin/master = B
      if (-not $fail) {
        # --- 方向1：本地落后 origin（master=A, origin/master=B）---
        GS @('branch', '-f', 'master', $gbA)
        $gbLocSha1 = (& git -C $gbw rev-parse master).Trim(); $gbRemSha = (& git -C $gbw rev-parse origin/master).Trim()
        if ($gbLocSha1 -eq $gbRemSha) { Fail '17aa(6)：夹具没造出「本地 master 落后 origin」（local==remote SHA）——本例会假绿（R3 七轮）。' }
        $gbOut = (& pwsh -NoProfile -Command ". '$gbFile'; `$r = Resolve-ScaffoldBaseRef -GitDir '$gbw' -BaseName 'master'; `$r + '=' + (git -C '$gbw' rev-parse `$r)" 2>$null | Out-String).Trim()
        if ($gbOut -ne "refs/remotes/origin/master=$gbRemSha") { Fail "17aa(6)：本地落后 origin 时解析器应返回 origin/master(=$gbRemSha)，却得 '$gbOut'（TD68 共享解析器坏了）。" }
      }
      if (-not $fail) {
        # --- 方向2：本地领先 origin（master=C, origin/master=B）；-PreferLocal 须返回本地 ---
        GS @('branch', '-f', 'master', $gbC)
        $gbLocSha2 = (& git -C $gbw rev-parse master).Trim(); $gbRemSha2 = (& git -C $gbw rev-parse origin/master).Trim()
        if ($gbLocSha2 -eq $gbRemSha2) { Fail '17aa(6)：夹具没造出「本地 master 领先 origin」（local==remote SHA）——本例会假绿。' }
        $gbLocal = (& pwsh -NoProfile -Command ". '$gbFile'; `$r = Resolve-ScaffoldBaseRef -GitDir '$gbw' -BaseName 'master' -PreferLocal; (git -C '$gbw' rev-parse `$r)" 2>$null | Out-String).Trim()
        if ($gbLocal -ne $gbLocSha2) { Fail "17aa(6)：-PreferLocal 在本地领先时未解析到本地 master（得 $gbLocal，应 $gbLocSha2）——-Local 会误对照陈旧 origin（R3 三轮）。" }
        # 缺省（不 -PreferLocal）此刻仍须优先 origin（远端 PR 的合并目标不变）。
        $gbRemote2 = (& pwsh -NoProfile -Command ". '$gbFile'; Resolve-ScaffoldBaseRef -GitDir '$gbw' -BaseName 'master'" 2>$null | Out-String).Trim()
        if ($gbRemote2 -ne 'refs/remotes/origin/master') { Fail "17aa(6)：缺省模式在本地领先时仍应优先 origin/master，却得 '$gbRemote2'。" }
      }
      if (-not $fail) {
        # --- F2 影子劫持（TD84 · R3 十轮 + 审计）：造一条本地分支 refs/heads/origin/master 指向**别的 sha**（$gbA），
        #     短名 rev-parse 'origin/master' 会被它先命中；全限定 refs/remotes/origin/master 不受影响。断言解析器仍解到远端 sha。
        GS @('update-ref', 'refs/heads/origin/master', $gbA)   # 恶意影子 ref（≠ origin/master=B）
        $gbShadowSha = (& git -C $gbw rev-parse "refs/heads/origin/master").Trim()
        $gbRemSha3 = (& git -C $gbw rev-parse "refs/remotes/origin/master").Trim()
        if ($gbShadowSha -eq $gbRemSha3) { Fail '17aa(6/F2)：夹具影子 ref 与远端 sha 相同——无法判别劫持，本例假绿。' }
        $gbF2 = (& pwsh -NoProfile -Command ". '$gbFile'; `$r = Resolve-ScaffoldBaseRef -GitDir '$gbw' -BaseName 'master'; (git -C '$gbw' rev-parse `$r)" 2>$null | Out-String).Trim()
        if ($gbF2 -eq $gbShadowSha) { Fail '种子缺陷 17aa(6/F2)：解析器被本地 refs/heads/origin/master 影子劫持（解到影子 sha 而非远端）——短名 rev-parse 歧义 fail-open；须用全限定 refs/remotes/origin/<name>。' }
        elseif ($gbF2 -ne $gbRemSha3) { Fail "17aa(6/F2)：解析器未解到远端 origin/master sha（得 $gbF2，应 $gbRemSha3）。" }
        & git -C $gbw update-ref -d refs/heads/origin/master 2>$null   # 清影子，免污染后续
      }
    }
    finally { Remove-Item -Recurse -Force $gbRoot -ErrorAction SilentlyContinue }
  }
  # 17aa(6)' (T112 / TD140 / ADR 0011): the declared examples that now live BESIDE Resolve-ScaffoldBaseRef.
  #   Overlap with the block above is deliberate and cheap: that block drives the resolver from a FOREIGN
  #   process and sets up the F2 shadow-hijack ref, neither of which an in-process table can do; these make
  #   the preference matrix callable next to the code, which is the ADR 0011 convention and what lets any
  #   caller re-run it. TD68 got this decision wrong twice, so two levels of assertion is not extravagance.
  . (Join-Path $PSScriptRoot '_gitbase.ps1')
  if (-not $gitPost) {
    Write-Host "  17aa(6)' base-ref examples skipped (git absent; they build a throwaway repo of their own)" -ForegroundColor DarkGray
  }
  else {
    $baseRefExampleFindings = @(Test-ScaffoldBaseRefExamples)
    if ($baseRefExampleFindings.Count) { $baseRefExampleFindings | ForEach-Object { Fail "17aa(6)' T112: $_" } }
    elseif (@(Test-ScaffoldBaseRefExamples -Variant 'first-candidate-wins').Count -lt 1) {
      Fail "17aa(6)' T112 (anti-vacuous): feeding the SAME examples through the 'first-candidate-wins' shape - return a candidate without asking git whether it resolves - produced zero disagreements, so the examples assert nothing about base-ref resolution (TD140/ADR 0011)."
    }
    elseif (-not $fail) { Write-Host "  17aa(6)' base-ref resolution examples OK (local fallback / remote preference / -PreferLocal / empty on no match; the unverified-candidate control disagrees)" -ForegroundColor Green }
  }
  # 静态防漂移：两处都必须经 Resolve-ScaffoldBaseRef，且都**不得**再用本地 $Base 直接算 diff。
  $revText = Get-Content (Join-Path $RepoRoot 'scripts/review.ps1') -Raw
  $taskText = Get-Content (Join-Path $RepoRoot 'scripts/task.ps1') -Raw
  if ($revText -notmatch 'Resolve-ScaffoldBaseRef') { Fail '17aa(6)：review.ps1 未经 Resolve-ScaffoldBaseRef 解析基线（TD68 共享点被绕过）。' }
  if ($taskText -notmatch 'Resolve-ScaffoldBaseRef') { Fail '17aa(6)：task.ps1 的范围闸未经 Resolve-ScaffoldBaseRef 解析基线——同 TD68 的本地-基线 bug 会复发（R3 PR #102 指出）。' }
  if ($taskText -match 'diff --name-only "\$Base\.\.\.HEAD"') { Fail '17aa(6)：task.ps1 范围闸仍用本地 $Base 算 diff（应为 $scopeBaseRef）——TD68 未在确定性范围闸修复。' }
  if ($revText -match 'diff "\$Base\.\.\.HEAD"') { Fail '17aa(6)：review.ps1 仍用本地 $Base 算 diff（应为 $baseRef）。' }
  # -Local 工作流须把「本地为合并目标」的信号透传到两处（R3 PR#102 三轮）：task 范围闸 -PreferLocal:$Local、
  # task→review 传 -LocalBase、review 把 -LocalBase 透传给解析器。任一漏传，-Local 就会误对照 origin。
  if ($taskText -notmatch 'Resolve-ScaffoldBaseRef[^\r\n]*-PreferLocal:\$Local') { Fail '17aa(6)：task.ps1 范围闸未按 -PreferLocal:$Local 解析——-Local ship 会误对照 origin，把前次本地合并的文件当越界。' }
  # T288 moved the call FORM - the reviewer now comes from a resolver-filled variable instead of a
  # `Join-Path ... 'scripts/review.ps1'` literal - so this reads the PROPERTY rather than the old spelling:
  # every review invocation on the -Local leg (identified by the LOCAL base it compares against, not by the
  # script path) must carry -LocalBase. Finding NONE is a failure of its own, because a pattern that matches
  # nothing reads from outside exactly like a pattern that is satisfied - which is how this guard would have
  # gone quietly inert when the call form changed under it.
  $taskLocalRev = @(($taskText -split "`r?`n") | Where-Object { ($_ -match '-WorktreePath \$Wt -Base \$Base\b') -and ($_.TrimStart() -notmatch '^#') })
  if ($taskLocalRev.Count -lt 1) { Fail '17aa(6): no -Local review invocation found in task.ps1 (searched for a command passing -WorktreePath $Wt -Base $Base, the local baseline that leg compares against). This guard can no longer see the leg it is about, so it proves nothing - fix the pattern, never the guard.' }
  elseif (@($taskLocalRev | Where-Object { $_ -notmatch '-LocalBase' }).Count -gt 0) { Fail '17aa(6)：task.ps1 的 -Local 评审调用未传 -LocalBase——-Local 的 R3 会误对照 origin。' }
  if ($revText -notmatch '\[switch\]\$LocalBase' -or $revText -notmatch 'Resolve-ScaffoldBaseRef[^\r\n]*-PreferLocal:\$LocalBase') { Fail '17aa(6)：review.ps1 未把 -LocalBase 透传给 Resolve-ScaffoldBaseRef -PreferLocal。' }
  # finding-2（R3 PR#102 五轮）：-Local 的合并目标是主检出**当前分支**，若显式 -Base 与之不一致须 fail-closed
  # （否则「对照 A 评审、却并入 B」，同类错基线）。静态守 task.ps1 ship 有该守卫。
  if (($taskText -notmatch 'SHIP-BASE-MISMATCH') -or ($taskText -notmatch 'SHIP-REMOTE-BASE') ) { Fail '17aa(6): task.ps1 is missing the full -Local guard set (SHIP-REMOTE-BASE / SHIP-BASE-MISMATCH / SHIP-DETACHED / target==task-branch F1) - R3 PR#102 rounds 5-9 + audit.' }
  # Codex#1（TD84）：远端 ship 须校验 PR baseRefName == $Base 并 fail-closed；meta T11 卡在场时，17aa(8) 用 gh mock 行为覆盖错配/空/失败。
  if (($taskText -notmatch 'baseRefName') -or ($taskText -notmatch 'SHIP-PR-RETARGET')) { Fail '17aa(6/Codex#1): task.ps1 remote ship is missing the PR baseRefName validation (SHIP-PR-RETARGET, TD84).' }
  # F2（TD84）：解析器须用全限定 refs（防 refs/heads/origin/<name> 影子劫持）。
  $gbText = Get-Content (Join-Path $RepoRoot 'scripts/_gitbase.ps1') -Raw
  if ($gbText -notmatch 'refs/remotes/origin/') { Fail '17aa(6/F2)：_gitbase.ps1 未用全限定 refs/remotes/origin/<name>。' }
  # F3（合并前 TOCTOU 再断言）：Assert-LocalMergeTarget 必须被调用**至少两次**（ship 入口 + 合并前），否则合并时 HEAD 若已变、review 对照的 $Base 与实际并入分支不一致。
  if (@([regex]::Matches($taskText, 'Assert-LocalMergeTarget\s+-Cur')).Count -lt 2) { Fail '17aa(6)：task.ps1 未在合并前**重新**断言 -Local 合并目标（Assert-LocalMergeTarget 调用点 < 2）——F3 merge-time TOCTOU 未闭合。' }
  if (-not $fail) { Write-Host '  17aa(6) 共享解析器：缺省优先 origin / -PreferLocal 优先本地 + 两处静态防漂移 + -Local 信号透传 OK（TD68 根因收敛）' -ForegroundColor Green }
}

# ── 17aa(7). 行为测试（R3 PR#102 六轮）：-Local + 坏 -Base 真的 fail-closed（不是只在源码里搜标记）──
#   造「本地 master 领先 origin/master」的仓，实跑 `task.ps1 -Phase ship -Local -Base <坏值>`，断言非零退出 + 报错点明原因。
#   守卫置于 ship 最前（worktree/check-cards 之前），故本测试不需建 worktree、不触 DoD/评审——快且确定。
if (-not $fail -and -not $gitPost) {
  Write-Host '  17aa(7) skipped (git absent; the -Local fail-closed fixture needs a real repo)' -ForegroundColor DarkGray
}
elseif (-not $fail) {
  $lbRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("st17aa7_" + [guid]::NewGuid().ToString('N').Substring(0, 8))
  try {
    $lbOrigin = Join-Path $lbRoot 'o.git'; $lbw = Join-Path $lbRoot 'w'
    New-Item -ItemType Directory -Force $lbw | Out-Null
    & git init --bare -q $lbOrigin
    # 拷整个 scripts/（task.ps1 dot-source _config/_gitbase/_encoding + 调 check-cards）
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin @('.git', 'wt', '_local', '.review', 'node_modules', 'review') } | Copy-Item -Destination $lbw -Recurse -Force
    & git -C $lbw init -q
    & git -C $lbw symbolic-ref HEAD refs/heads/master
    & git -C $lbw -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $lbw -c user.email='s@l' -c user.name='s' commit -q -m base *> $null
    & git -C $lbw remote add origin $lbOrigin
    & git -C $lbw push -q -u origin master *> $null
    Set-Content (Join-Path $lbw 'AHEAD.txt') 'local ahead of origin' -Encoding utf8
    & git -C $lbw -c user.email='s@l' -c user.name='s' add -A 2>$null
    & git -C $lbw -c user.email='s@l' -c user.name='s' commit -q -m ahead *> $null   # 本地 master 领先 origin/master
    # 最小卡文件：守卫在 check-cards **之前**，故只需文件存在（内容不必合法）。
    New-Item -ItemType Directory -Force (Join-Path $lbw 'specs/tasks') | Out-Null
    Set-Content (Join-Path $lbw 'specs/tasks/T0-LOCALBASE.md') "---`nid: T0-LOCALBASE`n---`n# stub`n" -Encoding utf8
    # (a) 远端限定 -Base origin/master：本地领先时旧代码会对照陈旧 origin——须**拒绝**、fail-closed。
    $lbA = (& pwsh -NoProfile -File (Join-Path $lbw 'scripts/task.ps1') -TaskId T0-LOCALBASE -Phase ship -Local -Base origin/master 2>&1 | Out-String)
    $lbAExit = $LASTEXITCODE
    if ($lbAExit -eq 0) { Fail '种子缺陷 17aa(7a)：-Local -Base origin/master（本地领先 origin）未 fail-closed——远端限定基线被放行，会对照陈旧 origin、却并入本地（R3 PR#102 六轮）。' }
    elseif ($lbA -notmatch 'SHIP-REMOTE-BASE') { Fail "Gate 17aa(7a): -Local + origin/ baseline exited non-zero but the error does not name SHIP-REMOTE-BASE as the cause (output: $($lbA.Substring(0,[Math]::Min(160,$lbA.Length))))." }
    # (b) 与当前分支不一致的本地名 -Base other：错配、fail-closed。
    $lbB = (& pwsh -NoProfile -File (Join-Path $lbw 'scripts/task.ps1') -TaskId T0-LOCALBASE -Phase ship -Local -Base some-other-branch 2>&1 | Out-String)
    $lbBExit = $LASTEXITCODE
    if ($lbBExit -eq 0) { Fail '种子缺陷 17aa(7b)：-Local -Base some-other-branch 未 fail-closed——会对照它评审、却并入当前分支。' }
    elseif ($lbB -notmatch 'SHIP-BASE-MISMATCH') { Fail "Gate 17aa(7b): -Local + a mismatched local baseline exited non-zero but the error does not name SHIP-BASE-MISMATCH (output: $($lbB.Substring(0,[Math]::Min(160,$lbB.Length))))." }
    # (e) F4 大小写敏感（TD84 · R3 十轮）：当前分支 master，-Base MASTER（仅大小写不同）——git refs 大小写敏感，
    #     必须判为「基线错配」（-cne）。旧 -ne 大小写不敏感会漏判、对照 MASTER 却并入 master。
    $lbE = (& pwsh -NoProfile -File (Join-Path $lbw 'scripts/task.ps1') -TaskId T0-LOCALBASE -Phase ship -Local -Base MASTER 2>&1 | Out-String)
    $lbEExit = $LASTEXITCODE
    if ($lbEExit -eq 0) { Fail '种子缺陷 17aa(7e/F4)：-Local -Base MASTER（当前分支 master，仅大小写异）未 fail-closed——大小写不敏感 -ne 漏判，对照 MASTER 却并入 master。须用 -cne。' }
    elseif ($lbE -notmatch 'SHIP-BASE-MISMATCH') { Fail "Gate 17aa(7e/F4): -Local + a case-variant -Base exited non-zero but the error does not name SHIP-BASE-MISMATCH (output: $($lbE.Substring(0,[Math]::Min(160,$lbE.Length))))." }
    # (d) 合并目标 == 任务分支（F1；L86 worktree 自调用形态）：当前分支就是 TaskId → 自并入空操作 + cleanup 数据丢失，须 fail-closed。
    & git -C $lbw checkout -q -b T0-LOCALBASE
    if ($LASTEXITCODE -ne 0) { Fail '17aa(7) setup 失败：git checkout -b T0-LOCALBASE' }
    $lbD = (& pwsh -NoProfile -File (Join-Path $lbw 'scripts/task.ps1') -TaskId T0-LOCALBASE -Phase ship -Local 2>&1 | Out-String)   # 无 -Base → 自动=当前分支=TaskId
    $lbDExit = $LASTEXITCODE
    if ($lbDExit -eq 0) { Fail '种子缺陷 17aa(7d)：主检出当前分支 == TaskId 时 -Local 未 fail-closed——`git merge $TaskId` 自并入空操作，work 从未落基线，随后 cleanup branch -D 丢弃（F1 数据丢失）。' }
    elseif ($lbD -notmatch 'L86-BASE') { Fail "Gate 17aa(7d): with current branch == TaskId, -Local exited non-zero but the error does not carry the L86-BASE sentinel (output: $($lbD.Substring(0,[Math]::Min(160,$lbD.Length))))." }
    # (c) 主检出 detached HEAD（R3 PR#102 八轮）：合并目标不存在，须 fail-closed（否则 merge 落空、review 对照 $Base）。
    & git -C $lbw checkout -q --detach
    if ($LASTEXITCODE -ne 0) { Fail '17aa(7) setup 失败：git checkout --detach' }
    $lbC = (& pwsh -NoProfile -File (Join-Path $lbw 'scripts/task.ps1') -TaskId T0-LOCALBASE -Phase ship -Local 2>&1 | Out-String)
    $lbCExit = $LASTEXITCODE
    if ($lbCExit -eq 0) { Fail '种子缺陷 17aa(7c)：主检出 detached HEAD 下 -Local 未 fail-closed——`git merge` 会并入游离 HEAD、不落任何分支，而 review/范围对照 $Base（R3 PR#102 八轮）。' }
    elseif ($lbC -notmatch 'SHIP-DETACHED') { Fail "Gate 17aa(7c): under a detached HEAD, -Local exited non-zero but the error does not name SHIP-DETACHED (output: $($lbC.Substring(0,[Math]::Min(160,$lbC.Length))))." }
  }
  finally { Remove-Item -Recurse -Force $lbRoot -ErrorAction SilentlyContinue }
if (-not $fail) { Write-Host '  17aa(7) 行为：-Local + 远端限定/错配-Base/detached/目标==任务分支 实跑 fail-closed OK（TD68 · R3 六/八/九轮 F1/F3）' -ForegroundColor Green }
}

# --- 17ib [R3-INTENSITY] (T301): review intensity is keyed on the COMPUTED tier, and it only lowers ---
# Five fixture cards, one stub reviewer, one run of the REAL review.ps1 each. What makes this an acceptance
# face rather than a restatement of the config: the stub APPENDS to a file outside the repo when it is
# invoked, so "no reviewer ran" is proved by that file's absence - an exit code cannot tell a routed skip
# from a fast pass, and asserting only the printed line would pass just as happily if the skip never
# actually skipped anything.
# The tier-0 case is built where the two routers PROVABLY differ (L352): its diff is a non-markdown file, so
# ReviewSkipWhen refuses to route it away and the tier dial is the only thing that can. Built on a .md diff
# it would have been vacuous - the content router would have skipped first and this gate would have been
# asserting that field's behaviour under this field's name.
# The FLOOR case is the security half: a card declaring only doc paths computes tier 0, and without the
# never-path floor a reviewee could route around the review by shaping its card. review.ps1 runs no scope
# gate, so the fixture states the tier through allow_paths and the never-path through the diff separately.
# The GATE case is the other floor, and it is the one that keeps this repo's OWN gates armed: a routed skip
# writes a `pass`, so under ReviewGate='required' an unfloored skip would not lower the merge gate, it would
# delete it - and every fixture in this file that arms `required` to exercise a reviewer would quietly stop
# exercising one. Measured, not theorised: 15r(e)E and 17b'(J) both went red on exactly that before the
# floor existed, one of them by merging a branch its seeded guard was supposed to stop.
# The OFF case is the "empty means off" arm: with the map blanked, the same tier-0 card draws the full
# adversarial read it draws today, and the source reads `default` rather than `field`.
if (-not $fail -and -not $gitPost) {
  Write-Host '  17ib skipped (git absent; the hermetic review repo cannot be built)' -ForegroundColor DarkGray
}
elseif (-not $fail) {
  # The repository's deployed policy deliberately remains tier-0=advisory under an armed required gate.
  # The hermetic cases below exercise a stricter synthetic map; assert the live policy separately so that
  # fixture setup cannot silently redefine what this checkout actually ships.
  $ibProductionIntensity = Get-ScaffoldReviewIntensityByTier
  if (([string]$ibProductionIntensity['0'] -ne 'advisory') -or (([string]$ScaffoldConfig.ReviewGate).Trim() -ne 'required')) {
    Fail "17ib production-policy drift: expected ReviewIntensityByTier['0']='advisory' with ReviewGate='required'; fixture-only skip routing must not mask a changed local policy."
  }
  $ibRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("st17ib_" + [guid]::NewGuid().ToString('N').Substring(0, 8))
  $ibSavedPath = $env:PATH
  try {
    $ibh = Join-Path $ibRoot 'repo'
    New-Item -ItemType Directory -Force $ibh | Out-Null
    $ibSkip = @('.git', 'wt', '_local', '.review', 'node_modules', 'review')
    Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $ibSkip } | Copy-Item -Destination $ibh -Recurse -Force
    $ibBin = Join-Path $ibRoot 'fakebin'; New-Item -ItemType Directory -Force $ibBin | Out-Null
    $ibReached = (Join-Path $ibRoot 'reviewer-reached.txt') -replace '\\', '/'
    # The stub also records its ARGV, because the effort arm cannot be proved any other way: asserting the
    # printed class would pass with the effort code deleted, since the fixture's one-line diff already
    # selects 'low' through ReviewEffortBySize. What has to be shown is the value that reached the BACKEND
    # (L353: a green arm proves nothing when the asserted value has a second path in).
    $ibArgv = (Join-Path $ibRoot 'reviewer-argv.txt') -replace '\\', '/'
    $ibFake = @"
`$o = ''
for (`$i = 0; `$i -lt `$args.Count; `$i++) { if (`$args[`$i] -eq '--output-last-message') { `$o = `$args[`$i + 1] } }
`$null = (`$input | Out-String)
Add-Content -Path '$ibReached' -Value 'reached'
Add-Content -Path '$ibArgv' -Value (`$args -join ' ')
if (`$o) { '{"verdict":"pass","reasons":[]}' | Set-Content -Path `$o -Encoding utf8 }
exit 0
"@
    Set-Content (Join-Path $ibBin 'codex.ps1') $ibFake -Encoding utf8
    New-ReviewFixtureRepo $ibh 'ib-seed'
    $ibCfgPath = Join-Path $ibh 'scripts/_config.ps1'
    $ibCfgBase = Get-Content $ibCfgPath -Raw
    # The acceptance rows are about the three intensity classes, not today's deployment decision.  Their
    # exact semantic fixture is explicit: tier S stays adversarial, tier 1 is advisory, tier 0 is skip.
    # Content routing is independently armed for the COMPOSE row; its never lists are also the data that
    # the FLOOR / CASEPFX / EXACTPATH / RENAME rows prove the intensity path consumes.
    $ibFixtureIntensity = "ReviewIntensityByTier = @{ 'S' = 'adversarial'; '1' = 'advisory'; '0' = 'skip' }"
    $ibFixtureRoute = "ReviewSkipWhen = @{ AllPathsMatch = '\.md$'; NeverPrefixes = @('scripts/'); NeverPaths = @('docs/QUALITY-RUBRIC.md') }"
    # wantEffort is the arm that cannot be read off the printed line; composed is the arm that asserts this
    # dial does NOT get to decide, because the content router already did.
    # Every row after the first seven is a CONTROL that fails under one specific rejected implementation,
    # which is the only thing that makes acceptance item 10 an assertion rather than a claim (R3 round 2,
    # finding 1): NOBASE fails if the worktree card is tiered, PADGATE if ReviewGate is compared untrimmed,
    # CASEPFX if the never-prefix match is case-sensitive, EXACTPATH if the NeverPaths leg is missing,
    # RENAME if the changed-path list keeps rename detection, CALLER if an explicit -Effort is overruled,
    # UNRANKED if a rung this file cannot place is forced to 'low'.
    $ibCases = @(
      @{ id = 'T900-IB-TIER0';     allow = 'docs/';              change = 'ib-change.txt';          tier = '0'; class = 'skip';        src = 'field';   reached = $false; floorNote = '';                                 wantEffort = ''        ; composed = $false }
      @{ id = 'T900-IB-TIER1';     allow = 'frontend/';          change = 'ib-change.txt';          tier = '1'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = '';                                 wantEffort = ''        ; composed = $false }
      @{ id = 'T900-IB-TIERS';     allow = 'scripts/review.ps1'; change = 'ib-change.txt';          tier = 'S'; class = 'adversarial'; src = 'field';   reached = $true;  floorNote = '';                                 wantEffort = ''        ; composed = $false }
      @{ id = 'T900-IB-FLOOR';     allow = 'docs/';              change = 'scripts/ib-floor.txt';   tier = '0'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = 'never-path:scripts/ib-floor.txt';   wantEffort = ''        ; composed = $false }
      @{ id = 'T900-IB-GATE';      allow = 'docs/';              change = 'ib-change.txt';          tier = '0'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = 'ReviewGate=required';               wantEffort = ''        ; composed = $false; gateLiteral = 'required' }
      @{ id = 'T900-IB-EFFORT';    allow = 'frontend/';          change = 'ib-change.txt';          tier = '1'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = '';                                 wantEffort = 'low'     ; composed = $false; flatEffort = $true }
      @{ id = 'T900-IB-COMPOSE';   allow = 'docs/';              change = 'docs/ib-note.md';        tier = '0'; class = 'skip';        src = 'field';   reached = $false; floorNote = '';                                 wantEffort = ''        ; composed = $true  }
      @{ id = 'T900-IB-NOBASE';    allow = 'docs/';              change = 'ib-change.txt';          tier = '?'; class = 'adversarial'; src = 'default'; reached = $true;  floorNote = '';                                 wantEffort = ''        ; composed = $false; branchOnly = $true }
      @{ id = 'T900-IB-PADGATE';   allow = 'docs/';              change = 'ib-change.txt';          tier = '0'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = 'ReviewGate=required';               wantEffort = ''        ; composed = $false; gateLiteral = ' required ' }
      @{ id = 'T900-IB-CASEPFX';   allow = 'docs/';              change = 'scripts/ib-case.txt';    tier = '0'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = 'never-path:scripts/ib-case.txt';    wantEffort = ''        ; composed = $false; neverPrefixes = 'SCRIPTS/' }
      @{ id = 'T900-IB-EXACTPATH'; allow = 'docs/';              change = 'docs/QUALITY-RUBRIC.md'; tier = '0'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = 'never-path:docs/QUALITY-RUBRIC.md'; wantEffort = ''        ; composed = $false }
      @{ id = 'T900-IB-RENAME';    allow = 'docs/';              change = 'docs/ib-renamed.md';     tier = '0'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = 'never-path:docs/QUALITY-RUBRIC.md'; wantEffort = ''        ; composed = $false; renameFrom = 'docs/QUALITY-RUBRIC.md' }
      @{ id = 'T900-IB-CALLER';    allow = 'frontend/';          change = 'ib-change.txt';          tier = '1'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = '';                                 wantEffort = 'high'    ; composed = $false; flatEffort = $true; reviewArgs = @('-Effort', 'high') }
      @{ id = 'T900-IB-UNRANKED';  allow = 'frontend/';          change = 'ib-change.txt';          tier = '1'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = '';                                 wantEffort = 'thrifty' ; composed = $false; flatEffort = $true; flatEffortValue = 'thrifty' }
      @{ id = 'T900-IB-EMPTYEFF';  allow = 'frontend/';          change = 'ib-change.txt';          tier = '1'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = '';                                 wantEffort = 'low'     ; composed = $false; flatEffort = $true; emptyEffort = $true }
      @{ id = 'T900-IB-NODIFF';    allow = 'docs/';              change = '';                       tier = '0'; class = 'advisory';    src = 'field';   reached = $true;  floorNote = 'no-changed-paths';                 wantEffort = ''        ; composed = $false; noChange = $true }
      @{ id = 'T900-IB-OFF';       allow = 'docs/';              change = 'ib-change.txt';          tier = '0'; class = 'adversarial'; src = 'default'; reached = $true;  floorNote = '';                                 wantEffort = ''        ; composed = $false; off = $true }
    )
    $ibAllOk = $true
    foreach ($ibC in $ibCases) {
      # Fill the OPTIONAL keys before anything reads them. Under `Set-StrictMode -Version Latest` a missing
      # hashtable key read with dot notation THROWS, so a case table where only some rows carry a knob kills
      # the gate on the first row that does not - which is exactly how this arm died once already. Defaults
      # here rather than ContainsKey at each use: one place to look, and no reader can forget.
      foreach ($ibK in @('off', 'flatEffort', 'branchOnly', 'emptyEffort', 'noChange')) { if (-not $ibC.ContainsKey($ibK)) { $ibC[$ibK] = $false } }
      foreach ($ibK in @('gateLiteral', 'neverPrefixes', 'flatEffortValue', 'renameFrom')) { if (-not $ibC.ContainsKey($ibK)) { $ibC[$ibK] = '' } }
      if (-not $ibC.ContainsKey('reviewArgs')) { $ibC['reviewArgs'] = @() }
      & git -C $ibh -c user.email='s@l' -c user.name='s' checkout -q master
      $ibCfgWant = [regex]::Replace($ibCfgBase, "ReviewIntensityByTier\s*=\s*@\{[^}]*\}", $ibFixtureIntensity)
      if ($ibCfgWant -eq $ibCfgBase -or $ibCfgWant -notmatch [regex]::Escape($ibFixtureIntensity)) { Fail 'Gate 17ib fixture _config could not install the explicit S=adversarial / 1=advisory / 0=skip intensity map; expected class assertions would otherwise be testing this repository policy by accident.'; $ibAllOk = $false; break }
      $ibCfgWant = $ibCfgWant.Replace('ReviewSkipWhen = @{}', $ibFixtureRoute)
      if ($ibCfgWant -notmatch [regex]::Escape($ibFixtureRoute)) { Fail 'Gate 17ib fixture _config could not install the explicit markdown-only content route and its never lists; COMPOSE and the floor controls would no longer name the same routing policy.'; $ibAllOk = $false; break }
      # The production required gate is asserted separately above.  It would floor every synthetic tier-0
      # skip to advisory, so leave it empty here except for the GATE/PADGATE rows that explicitly install it.
      $ibCfgWant = [regex]::Replace($ibCfgWant, "(?m)^[ \t]*ReviewGate\s*=\s*'[^']*'\s*$", "ReviewGate = ''")
      if ($ibCfgWant -notmatch "(?m)^ReviewGate\s*=\s*''\s*$") { Fail 'Gate 17ib fixture _config could not clear ReviewGate before the class cases; every tier-0 skip would otherwise be floored to advisory and the skip arm would be vacuous.'; $ibAllOk = $false; break }
      # FrozenPaths is deliberately production-wide: any directory claim is Tier S while frozen contracts
      # exist.  These class cases need their declared docs/ allowance to compute Tier 0, so disable only
      # that unrelated production policy inside this synthetic fixture.
      $ibCfgWant = [regex]::Replace($ibCfgWant, "FrozenPaths\s*=\s*@\([^)]*\)", 'FrozenPaths = @()')
      if ($ibCfgWant -notmatch 'FrozenPaths\s*=\s*@\(\s*\)') { Fail 'Gate 17ib fixture _config could not clear FrozenPaths; a production frozen contract would raise every directory allowance to Tier S and hide the Tier-0 intensity arm.'; $ibAllOk = $false; break }
      if ($ibC.off) {
        $ibCfgWant = [regex]::Replace($ibCfgWant, "ReviewIntensityByTier\s*=\s*@\{[^}]*\}", 'ReviewIntensityByTier = @{}')
        if ($ibCfgWant -notmatch 'ReviewIntensityByTier\s*=\s*@\{\s*\}') { Fail "Gate 17ib(off): the fixture _config could not blank ReviewIntensityByTier (did the literal format change?) - the 'empty means today behaviour' arm would then pass vacuously."; $ibAllOk = $false; break }
      }
      if ($ibC.gateLiteral) {
        # The literal is per case on purpose: the PADGATE case injects a PADDED ' required ', which is what
        # the authority Get-ScaffoldReviewRunDecision treats as armed. Under a raw comparison that case
        # skips and the floor never fires, so it is the control that discriminates the trim (R3 round 2, #1).
        $ibCfgWant = $ibCfgWant.Replace("ReviewGate = ''", "ReviewGate = '$($ibC.gateLiteral)'")
        if ($ibCfgWant -notmatch [regex]::Escape("ReviewGate = '$($ibC.gateLiteral)'")) { Fail "Gate 17ib($($ibC.id)): the fixture _config could not be set to ReviewGate = '$($ibC.gateLiteral)' (did the literal format change?) - without it the arm proving an armed merge gate cannot be routed away would pass vacuously."; $ibAllOk = $false; break }
      }
      if ($ibC.neverPrefixes) {
        # An UPPERCASE prefix against a lowercase changed path: the shared predicate matches
        # OrdinalIgnoreCase, so the floor must still fire. The first draft's private copy used a
        # case-sensitive StartsWith and this case is what tells the two apart (R3 round 2, #1).
        $ibCfgWant = [regex]::Replace($ibCfgWant, "NeverPrefixes\s*=\s*@\([^)]*\)", "NeverPrefixes = @('$($ibC.neverPrefixes)')")
        if ($ibCfgWant -notmatch [regex]::Escape("NeverPrefixes = @('$($ibC.neverPrefixes)')")) { Fail "Gate 17ib($($ibC.id)): the fixture _config could not set NeverPrefixes (did the literal format change?) - the case-insensitivity control would then prove nothing."; $ibAllOk = $false; break }
      }
      if ($ibC.emptyEffort) {
        # The SHIPPED DOWNSTREAM state, and the reason it needs its own case: init-scaffold.ps1 blanks
        # ReviewEffort, and ReviewEffortBySize ships empty too, so an initialized project resolves an EMPTY
        # effort. Under the round-2 code that landed in the unranked branch and was preserved, meaning the
        # advisory class bought nothing at all downstream while the repo's own configured fixtures stayed
        # green (R3 round 3). This case fails if empty is ever folded back in with unranked.
        $ibCfgWant = [regex]::Replace($ibCfgWant, "(?m)^(\s*)ReviewEffort(\s*)=\s*'[^']*'", "`${1}ReviewEffort`${2}= ''")
        if ($ibCfgWant -notmatch "(?m)^\s*ReviewEffort\s*=\s*''\s*$") { Fail "Gate 17ib($($ibC.id)): the fixture _config could not blank ReviewEffort (did the literal format change?) - the shipped-downstream empty-effort control would then prove nothing."; $ibAllOk = $false; break }
      }
      if ($ibC.flatEffortValue) {
        # A rung this file's rank table does not know. The advisory class must leave it EXACTLY as resolved:
        # forcing 'low' onto a value it cannot compare could be a raise, which the card forbids outright.
        $ibCfgWant = [regex]::Replace($ibCfgWant, "(?m)^(\s*)ReviewEffort(\s*)=\s*'[^']*'", "`${1}ReviewEffort`${2}= '$($ibC.flatEffortValue)'")
        if ($ibCfgWant -notmatch [regex]::Escape("= '$($ibC.flatEffortValue)'")) { Fail "Gate 17ib($($ibC.id)): the fixture _config could not set a custom ReviewEffort rung (did the literal format change?) - the unranked-rung control would then prove nothing."; $ibAllOk = $false; break }
      }
      if ($ibC.flatEffort) {
        # Blank the size map so the FLAT ReviewEffort ('high' in this repo) is what the diff would otherwise
        # draw. Without this the one-line fixture diff already resolves to 'low' through ReviewEffortBySize,
        # and the effort assertion below would hold with the advisory effort code deleted (R3 round 1, #4).
        $ibCfgWant = [regex]::Replace($ibCfgWant, "ReviewEffortBySize\s*=\s*@\{[^}]*\}", 'ReviewEffortBySize = @{}')
        if ($ibCfgWant -notmatch 'ReviewEffortBySize = @\{\}') { Fail 'Gate 17ib(effort): the fixture _config could not blank ReviewEffortBySize (did the literal format change?) - the effort arm would then assert a value the size map produces on its own.'; $ibAllOk = $false; break }
      }
      Set-Content $ibCfgPath -Value $ibCfgWant -Encoding utf8
      $ibCardText = @('---', "id: $($ibC.id)", 'title: intensity fixture card', 'status: todo', 'allow_paths:', "  - $($ibC.allow)", '---') -join "`n"
      # branchOnly is the base-card-absent control (R3 round 2, #1): the card exists ONLY on the branch, so
      # review.ps1 falls back to the worktree copy. Tiering THAT is the move the base binding refuses, so
      # the tier must stay '?' and the class adversarial no matter what allow_paths the branch card names.
      if (-not $ibC.branchOnly) { Set-Content (Join-Path $ibh "specs/tasks/$($ibC.id).md") -Value $ibCardText -Encoding utf8 }
      & git -C $ibh -c user.email='s@l' -c user.name='s' add -A 2>$null
      & git -C $ibh -c user.email='s@l' -c user.name='s' commit -q -m "fixture card $($ibC.id)" *> $null
      & git -C $ibh -c user.email='s@l' -c user.name='s' checkout -q -b $ibC.id
      if ($ibC.branchOnly) { Set-Content (Join-Path $ibh "specs/tasks/$($ibC.id).md") -Value $ibCardText -Encoding utf8 }
      if ($ibC.noChange) {
        # No commit at all on the branch, so the changed-path list comes back EMPTY - the same shape a
        # failed `git diff` produces. The floor must hold: a diff nobody could enumerate is not a diff
        # anyone proved cheap, and without the floor a tier-0 card would route its review away on it.
      }
      elseif ($ibC.renameFrom) {
        # The rubric-rename control for --no-renames: with rename detection ON the diff shows only the
        # destination and the never-path vanishes, so the tier-0 skip stands and no reviewer runs.
        & git -C $ibh -c user.email='s@l' -c user.name='s' mv $ibC.renameFrom $ibC.change *> $null
      }
      else {
        $ibChangePath = Join-Path $ibh $ibC.change
        New-Item -ItemType Directory -Force (Split-Path $ibChangePath -Parent) | Out-Null
        Set-Content $ibChangePath "a change under review for $($ibC.id)" -Encoding utf8
      }
      & git -C $ibh -c user.email='s@l' -c user.name='s' add -A 2>$null
      & git -C $ibh -c user.email='s@l' -c user.name='s' commit -q -m "change $($ibC.id)" *> $null
      Remove-Item -Force $ibReached, $ibArgv -ErrorAction SilentlyContinue
      Remove-Item -Recurse -Force (Join-Path $ibh '.review') -ErrorAction SilentlyContinue
      $ibExtraArgs = if ($ibC.reviewArgs) { @($ibC.reviewArgs) } else { @() }
      $env:PATH = "$ibBin$([System.IO.Path]::PathSeparator)$ibSavedPath"
      try { $ibOut = (& pwsh -NoProfile -File (Join-Path $ibh 'scripts/review.ps1') -WorktreePath $ibh -Base master @ibExtraArgs 2>&1 | Out-String); $ibExit = $LASTEXITCODE }
      finally { $env:PATH = $ibSavedPath }
      $ibWantLine = "[R3-INTENSITY] tier=$($ibC.tier) class=$($ibC.class) source=$($ibC.src)"
      $ibTail = $ibOut.Substring([Math]::Max(0, $ibOut.Length - 400))
      $ibRan = Test-Path $ibReached
      $ibWantPredicate = if ($ibC.composed) { 'ReviewSkipWhen' } else { 'ReviewIntensityByTier' }
      if ($ibExit -ne 0) {
        Fail "Gate 17ib($($ibC.id)): review.ps1 exited $ibExit - every leg of this fixture is a pass shape, so non-zero is a regression. Output tail: $ibTail"; $ibAllOk = $false
      }
      elseif ($ibC.composed -and ($ibOut -match [regex]::Escape('[R3-INTENSITY]'))) {
        Fail "Gate 17ib($($ibC.id)): a markdown-only tier-0 diff printed [R3-INTENSITY], so intensity resolution ran on a diff the CONTENT router had already decided. The precedence documented in TEMPLATE-README.md and docs/QUALITY-RUBRIC.md says ReviewSkipWhen answers first and this dial never sees such a diff - if that changed, the docs are now wrong about which knob an operator must turn. Output tail: $ibTail"; $ibAllOk = $false
      }
      elseif ((-not $ibC.composed) -and ($ibOut -notmatch [regex]::Escape($ibWantLine))) {
        Fail "Gate 17ib($($ibC.id)): the expected decision line '$ibWantLine' did not appear - at least one of tier/class/source resolved wrongly, and the operator cannot see from the log which class this review ran at. Output tail: $ibTail"; $ibAllOk = $false
      }
      elseif ($ibC.floorNote -and ($ibOut -notmatch [regex]::Escape("floor=$($ibC.floorNote)"))) {
        Fail "Gate 17ib($($ibC.id)): the expected floor clause 'floor=$($ibC.floorNote)' did not appear - a skip that should have been raised back to advisory was not. Both floors matter on their own: never-path stops a doc-shaped card routing around the standard that judges it; ReviewGate=required stops a routed skip writing a pass for a merge gate the operator armed. Output tail: $ibTail"; $ibAllOk = $false
      }
      elseif ((-not $ibC.floorNote) -and ($ibOut -match [regex]::Escape('floor='))) {
        Fail "Gate 17ib($($ibC.id)): no floor applies to this case yet a floor clause was printed - the floor is firing where it should not, and a card that should have been cheapened drew a dearer review. Output tail: $ibTail"; $ibAllOk = $false
      }
      elseif ($ibRan -ne $ibC.reached) {
        Fail "Gate 17ib($($ibC.id)): the review backend was actually invoked = $ibRan, expected $($ibC.reached) - what the decision line claims and what happened disagree (a skip still called the backend, or a class that must run one did not). Output tail: $ibTail"; $ibAllOk = $false
      }
      elseif ($ibC.wantEffort -and ((-not (Test-Path $ibArgv)) -or ((Get-Content $ibArgv -Raw) -notmatch [regex]::Escape("model_reasoning_effort=$($ibC.wantEffort)")))) {
        $ibGotArgv = if (Test-Path $ibArgv) { (Get-Content $ibArgv -Raw).Trim() } else { '(the backend was never invoked)' }
        Fail "Gate 17ib($($ibC.id)): the advisory class did not lower the effort that REACHED THE BACKEND to '$($ibC.wantEffort)'. This fixture blanks ReviewEffortBySize so the flat ReviewEffort would otherwise apply, which is the whole point: asserting the printed class instead would stay green with the advisory effort code deleted, because a small diff already resolves to low through the size map (L353). Backend argv: $ibGotArgv"; $ibAllOk = $false
      }
      elseif ($ibC.class -eq 'skip') {
        $ibVerdictPath = Join-Path $ibh ".review/$($ibC.id).json"
        if (-not (Test-Path $ibVerdictPath)) {
          Fail "Gate 17ib($($ibC.id)): the routed skip wrote no verdict file - 'no review ran' is exactly the fact an audit chain must never lose silently."; $ibAllOk = $false
        }
        else {
          $ibJson = Get-Content $ibVerdictPath -Raw | ConvertFrom-Json
          $ibNames = @($ibJson.PSObject.Properties.Name)
          if ($ibJson.verdict -ne 'pass') { Fail "Gate 17ib($($ibC.id)): the routed skip's verdict is '$($ibJson.verdict)' and not pass - writing a skip as a block would wedge every card at that tier."; $ibAllOk = $false }
          elseif ($ibNames -notcontains 'routed_skip') { Fail "Gate 17ib($($ibC.id)): the verdict carries no routed_skip - downstream this pass reads exactly like a review that ran and approved."; $ibAllOk = $false }
          elseif ($ibJson.routed_skip.predicate -ne $ibWantPredicate) { Fail "Gate 17ib($($ibC.id)): routed_skip.predicate is '$($ibJson.routed_skip.predicate)', expected '$ibWantPredicate' - the verdict names the wrong decider, so a later reader cannot tell which knob to turn."; $ibAllOk = $false }
          elseif ($ibJson.run_status -ne 'success') { Fail "Gate 17ib($($ibC.id)): run_status is '$($ibJson.run_status)' and not success - a cleanly ended run recorded as a fault state reads as 'retry the reviewer' rather than 'this is the outcome'."; $ibAllOk = $false }
        }
      }
      if (-not $ibAllOk) { break }
    }
    if ($ibAllOk -and -not $fail) { Write-Host '  17ib [R3-INTENSITY] tier-keyed review intensity OK (0=skip with a routed_skip verdict and no reviewer invoked, 1=advisory, S=adversarial; a never-path diff floors a tier-0 skip back to advisory through the SHARED route predicate; an armed ReviewGate=required floors it too, so a skip cannot delete the merge gate it would otherwise write a pass for; the advisory class lowers the effort that REACHES THE BACKEND, asserted from the stub argv over a fixture whose flat effort is high; a markdown-only tier-0 diff is decided by ReviewSkipWhen and never reaches this dial at all; and an empty map is today behaviour with source=default)' -ForegroundColor Green }
  }
  finally {
    $env:PATH = $ibSavedPath
    Remove-Item -Recurse -Force $ibRoot -ErrorAction SilentlyContinue
  }
}

# 17aa. (8). 远端 ship 行为回归（R3 PR#102 十轮）：
#   ① origin/<base> 缺失/陈旧时须在范围闸前 fetch 恢复到远端当前 SHA，绝不回退本地；
#   ② gh baseRefName 错配 / 空输出 / 命令失败三态均须 fail-closed；origin/master 正确归一化；评审后 retarget 在 merge 前复查阻断。
# meta T11 卡在场时复用真任务卡，让其无变量 DoD 经 task.ps1 的双层包装实际执行成功，防「只直接跑卡命令」假绿。
$r8DispositionFixture = Join-Path ([System.IO.Path]::GetTempPath()) ("st17aa8-[literal]-" + [guid]::NewGuid().ToString('N').Substring(0, 8))
try {
  [void][IO.Directory]::CreateDirectory((Join-Path $r8DispositionFixture 'scripts'))
  foreach ($scriptName in @('check-cards.ps1', '_cards.ps1', '_encoding.ps1')) {
    Copy-Item -LiteralPath (Join-Path $RepoRoot "scripts/$scriptName") -Destination (Join-Path $r8DispositionFixture "scripts/$scriptName") -Force
  }
  $r8LiveProbeCard = Join-Path $r8DispositionFixture 'specs/tasks/T11-R3-BASELINE.md'
  $r8ArchivedProbeCard = Join-Path $r8DispositionFixture 'specs/archive/tasks/T11-R3-BASELINE.md'

  $r8AbsentStream = @(Get-R3FixtureCardPath $r8DispositionFixture 6>&1)
  if (($r8AbsentStream | Out-String) -notmatch '\[SELFTEST-POSTINIT-R3-FIXTURE-SKIP\]') {
    Fail '17aa(8) absent-card precondition did not emit the stable downstream skip marker.'
  }

  $r8ValidCardText = "---`nid: T11-R3-BASELINE`ntitle: R3 fixture`nstatus: merged`ndod_command: pwsh -NoProfile -File scripts/verify.ps1`nallow_paths:`n  - scripts/`n---`n"
  [void][IO.Directory]::CreateDirectory((Split-Path $r8ArchivedProbeCard))
  foreach ($case in @(
    @{ Name = 'missing-frontmatter'; Raw = 'malformed card' },
    @{ Name = 'canonical-rules'; Raw = "---`nid: T11-R3-BASELINE`nstatus: invalid`nbranch: OTHER`nworktree: C:\wt\OTHER`ndod_command: echo noop`nallow_paths: [scripts/]`n---`n{{BAD_TOKEN}}" },
    @{ Name = 'block-scalar-dod'; Raw = "---`nid: T11-R3-BASELINE`nstatus: merged`ndod_command: |`nallow_paths:`n  - scripts/`n---`n" },
    @{ Name = 'frontmatter-garbage'; Raw = "---`nid: T11-R3-BASELINE`nGARBAGE`nstatus: merged`ndod_command: pwsh -NoProfile -File scripts/verify.ps1`nallow_paths:`n  - scripts/`n---`n" }
  )) {
    Set-Content -LiteralPath $r8ArchivedProbeCard -Value $case.Raw -NoNewline -Encoding utf8
    $r8MalformedError = $null
    try { Get-R3FixtureCardPath $r8DispositionFixture | Out-Null } catch { $r8MalformedError = $_ }
    if ($null -eq $r8MalformedError -or -not $r8MalformedError.Exception.Message.StartsWith("[SELFTEST-R3-FIXTURE-MALFORMED] path=$r8ArchivedProbeCard canonical-check-cards failed:")) {
      Fail "17aa(8) canonical validator did not reject archived $($case.Name) under a bracketed root."
    }
  }

  Set-Content -LiteralPath $r8ArchivedProbeCard -Value $r8ValidCardText -NoNewline -Encoding utf8
  if ((Get-R3FixtureCardPath $r8DispositionFixture) -ne $r8ArchivedProbeCard) { Fail '17aa(8) valid archived card was not selected under a bracketed root.' }
  [void][IO.Directory]::CreateDirectory((Split-Path $r8LiveProbeCard))
  Set-Content -LiteralPath $r8LiveProbeCard -Value 'malformed live card' -NoNewline
  $r8MixedError = $null
  try { Get-R3FixtureCardPath $r8DispositionFixture | Out-Null } catch { $r8MixedError = $_ }
  if ($null -eq $r8MixedError -or -not $r8MixedError.Exception.Message.Contains("path=$r8LiveProbeCard")) {
    Fail '17aa(8) dual-present state did not fail closed on the selected malformed live card.'
  }

  Set-Content -LiteralPath $r8LiveProbeCard -Value $r8ValidCardText -NoNewline -Encoding utf8
  Set-Content -LiteralPath $r8ArchivedProbeCard -Value 'malformed archived card' -NoNewline
  if ((Get-R3FixtureCardPath $r8DispositionFixture) -ne $r8LiveProbeCard) { Fail '17aa(8) dual-present state did not keep valid live-card precedence.' }
  if (-not $fail) { Write-Host '  17aa(8) precondition: literal bracketed-root routing + stable absent skip + canonical check-cards validation + live precedence OK' -ForegroundColor Green }
} finally {
  Remove-Item -LiteralPath $r8DispositionFixture -Recurse -Force -ErrorAction SilentlyContinue
}

if (-not $fail -and -not $gitPost) {
  Write-Host '  17aa(8) gh.ps1 behaviour fixture skipped (git absent; the remote-ship fixture needs a real repo)' -ForegroundColor DarkGray
}
elseif (-not $fail) {
  $r8SelectedCardPath = Get-R3FixtureCardPath $RepoRoot
  if (-not $r8SelectedCardPath) {
    # The stable skip marker is emitted by Get-R3FixtureCardPath.
  } elseif (-not $IsWindows) {
    Write-Host '  17aa(8) gh.ps1 行为夹具仅 Windows 执行；非 Windows 由 Windows CI 覆盖。' -ForegroundColor DarkGray
  } else {
    $r8Root = Join-Path ([System.IO.Path]::GetTempPath()) ("st17aa8_" + [guid]::NewGuid().ToString('N').Substring(0, 8))
    $r8SavedPath = $env:PATH; $r8SavedMode = $env:GH_MOCK_BASE_MODE; $r8SavedRoot = $env:GH_MOCK_ROOT
    $r8SavedMergeState = $env:GH_MOCK_MERGE_STATE; $r8SavedMockWt = $env:GH_MOCK_WT
    try {
      $r8Repo = Join-Path $r8Root 'repo'; $r8Origin = Join-Path $r8Root 'origin.git'; $r8Shim = Join-Path $r8Root 'shim'
      New-Item -ItemType Directory -Force $r8Repo,$r8Shim | Out-Null
      Copy-Item (Join-Path $RepoRoot 'scripts') $r8Repo -Recurse -Force
      Copy-Item (Join-Path $RepoRoot 'specs') $r8Repo -Recurse -Force
      # r3 #6: the CI check gate fail-closes when the workflow is absent, so the fixture repo needs real
      # workflows in place. T86: the expected CHECK set is ci.yml's single fan-in context `required` (the
      # scaffold-selftest copy is kept for the shard-matrix surfaces, not for the gate's expected set;
      # 判定机制与生产同路真被测），mock 按真 ci.yml 的 job 全集回绿（缺 required/跳过即闸红）。
      New-Item -ItemType Directory -Force (Join-Path $r8Repo '.github/workflows') | Out-Null
      Copy-Item (Join-Path $RepoRoot '.github/workflows/scaffold-selftest.yml') (Join-Path $r8Repo '.github/workflows/scaffold-selftest.yml') -Force
      # ci.yml too: T86 - the ship CI gate reads its fan-in contract (one required context) from ci.yml.
      Copy-Item (Join-Path $RepoRoot '.github/workflows/ci.yml') (Join-Path $r8Repo '.github/workflows/ci.yml') -Force
      Set-Content (Join-Path $r8Repo '.gitignore') ".review/`n_local/" -Encoding utf8
      New-Item -ItemType Directory -Force (Join-Path $r8Repo 'docs') | Out-Null
      Set-Content (Join-Path $r8Repo 'docs/QUALITY-RUBRIC.md') '# 17aa8 fixture rubric' -Encoding utf8
      Set-Content (Join-Path $r8Repo 'scripts/verify.ps1') 'exit 0' -Encoding utf8
      Set-Content (Join-Path $r8Repo 'scripts/check-licenses.ps1') 'exit 0' -Encoding utf8
      Set-Content (Join-Path $r8Repo 'scripts/check-secrets.ps1') 'exit 0' -Encoding utf8
      Add-FixtureAccountGuardStub (Join-Path $r8Repo 'scripts')
      $r8ReviewStub = Join-Path $r8Repo 'review-backend.ps1'
      $r8ReviewBody = @"
Set-Content -LiteralPath '$($r8Root -replace "'", "''")/review-reached' 'bad'
'{"verdict":"pass","reasons":[]}' | Set-Content `$env:REVIEW_OUT -Encoding utf8
"@
      Set-Content $r8ReviewStub $r8ReviewBody -Encoding utf8
      $r8CfgPath = Join-Path $r8Repo 'scripts/_config.ps1'; $r8Cfg = Get-Content $r8CfgPath -Raw
      $r8WtRoot = Join-Path $r8Root 'wt'
      $r8Cfg = [regex]::Replace($r8Cfg, "WorktreeRoot\s*=\s*'[^']*'", { "WorktreeRoot = '$($r8WtRoot -replace '\\','/')'" })
      $r8Cfg = [regex]::Replace($r8Cfg, "GhAccount\s*=\s*'[^']*'", { "GhAccount = 'selftest'" })
      $r8Cfg = $r8Cfg.Replace("ReviewCommand = ''", "ReviewCommand = 'pwsh -NoProfile -File $($r8ReviewStub -replace '\\','/')'").Replace("ReviewGate = ''", "ReviewGate = 'required'")
      Set-Content $r8CfgPath $r8Cfg -NoNewline -Encoding utf8
      # 本夹具复用真卡 T11-R3-BASELINE，其无变量 DoD 是静态「证据」断言，会 grep 姊妹卡路径（如
      # `Test-Path specs/tasks/T14-R3-DIFF-VERDICT-REDACT.md`）与 tracker 里的历史债 id（`TD68`）。archive.ps1（TD86/T28）
      # 把 merged 卡与 paid/accepted 债行冷存到 specs/archive/——本夹具把二者还原回活位置，令临时仓看到「压缩前」形态，
      # 不因归档改变本 gate 观测（归档是运行时机制，不该让复用真卡 DoD 的闸感知到）。
      $r8ArchTasks = Join-Path $r8Repo 'specs/archive/tasks'
      $r8Tasks = Join-Path $r8Repo 'specs/tasks'
      if (Test-Path -LiteralPath $r8ArchTasks) {
        Get-ChildItem -LiteralPath $r8ArchTasks -Filter *.md | Where-Object { $_.Name -ne 'T11-R3-BASELINE.md' } |
          Copy-Item -Destination $r8Tasks -Force
      }
      $r8CardPath = Join-Path $r8Tasks 'T11-R3-BASELINE.md'
      Copy-Item -LiteralPath $r8SelectedCardPath -Destination $r8CardPath -Force
      $r8Tracker = Join-Path $r8Repo 'specs/tech-debt-tracker.md'; $r8TdArch = Join-Path $r8Repo 'specs/archive/tech-debt-archive.md'
      if ((Test-Path $r8Tracker) -and (Test-Path $r8TdArch)) {
        $r8ArchRows = @(Get-Content $r8TdArch | Where-Object { $_ -match '^\s*\|\s*TD\d' })
        if ($r8ArchRows) { Add-Content -Path $r8Tracker -Value $r8ArchRows -Encoding utf8 }
        # T177/TD173: the restore above puts EVERY archived card in a live position at once - a state that
        # never actually existed. Since the cross-card rules now run under -TaskId, that synthetic state is
        # judged as one: T11-R3-BASELINE and T14-R3-DIFF-VERDICT-REDACT both claim TD83 (T11's own title
        # reads «TD83 拆 T14»), and TD83's frozen row names only T14, so the pair reads as an UNDECLARED
        # duplicate and task start dies before this gate's real subject - remote base-ref handling - runs.
        # The declaration is materialised on the TEMP tracker only, the same containment
        # Add-ScaffoldPostFreezeCardField already uses above: a fixture that synthesises a state must also
        # synthesise what that state requires, and frozen history is never rewritten to satisfy a later rule.
        $r8TdText = Get-Content $r8Tracker -Raw
        $r8TdFixed = [regex]::Replace($r8TdText, '(?m)^(\|\s*TD83\s*\|.*?)(\s*\|\s*)$', '${1} + T11-R3-BASELINE${2}')
        if ($r8TdFixed -eq $r8TdText) { Fail '17aa(8) setup: could not declare the TD83 split on the temp tracker, so restoring every archived card to a live position will trip [CARD-TD-DUP] and task start will die before the base-ref subject under test. [FIX] re-anchor this replace on TD83''s row, or narrow the restore above to the sibling cards T11''s DoD actually greps.' }
        else { Set-Content $r8Tracker $r8TdFixed -NoNewline -Encoding utf8 }
      }
      $r8Card = Get-Content $r8CardPath -Raw
      $r8Card = [regex]::Replace($r8Card, '(?m)^worktree:.*$', "worktree: $($r8WtRoot -replace '\\','/')/T11-R3-BASELINE")
      # The fixture restores an archived card to a LIVE position, so the copy must carry what a live card
      # is required to carry today; the frozen original is never touched (Add-ScaffoldPostFreezeCardField).
      $r8Card = Add-ScaffoldPostFreezeCardField $r8Card
      Set-Content $r8CardPath $r8Card -NoNewline -Encoding utf8

      $r8Gh = @'
if ($args -contains 'baseRefName') {
  if ($env:GH_MOCK_BASE_MODE -eq 'retarget') {
