    $count = if (Test-Path $countPath) { [int](Get-Content $countPath -Raw) } else { 0 }
    $count++; Set-Content $countPath $count
    if ($count -eq 1) { 'master' } else { 'other' }
    exit 0
  }
  switch ($env:GH_MOCK_BASE_MODE) {
    'mismatch' { 'other'; exit 0 }
    'empty'    { exit 0 }
    'fail'     { exit 23 }
    default    { 'master'; exit 0 }
  }
}
if ($args -contains 'state,headRefOid') {
  $st = if ($env:GH_MOCK_MERGE_STATE -eq 'open') { 'OPEN' } else { 'MERGED' }
  $oid = "$(& git -C $env:GH_MOCK_WT rev-parse HEAD 2>$null)".Trim()
  "{""state"":""$st"",""headRefOid"":""$oid""}"
  exit 0
}
# T64 CI 检查闸新增两问：merge 前取 PR head oid + 查该 head 的 check-runs（缺省全绿——本夹具测的是
# base/T24 行为面，CI 红面归 T64-CIRED 场景专测）。不服务这两问会让 CI 闸在 headRefOid 上提前
# fail-closed，抢在 T24-mint 断言要测的 merge 腿之前（17aa(8/T24-mint-open) 假红根因）。
if ($args -contains '.headRefOid') {
  "$(& git -C $env:GH_MOCK_WT rev-parse HEAD 2>$null)".Trim(); exit 0
}
if (($args -contains 'api') -and (@($args) -match 'check-runs').Count -gt 0) {
  # T86: the expected check set is ci.yml's ONE fan-in context, `required` (ADR 0007 - scaffold-selftest
  # does not trigger on pull_request, so its shards are not part of a PR's check set). Answer the real
  # workflow's jobs green; dropping `required` from this list turns the gate red (it would dead-wait,
  # then fail closed). This fixture exercises the base/T24 surface, not the CI-red face.
  $ciMockNames = @('verify', 'required')
  $ciMockRuns = foreach ($n in $ciMockNames) { '{"name":"' + $n + '","status":"completed","conclusion":"success"}' }
  '{"total_count":' + $ciMockNames.Count + ',"check_runs":[' + ($ciMockRuns -join ',') + ']}'
  exit 0
}
if ($args -contains 'number') { '102'; exit 0 }
if ($args -contains 'merge') { Set-Content (Join-Path $env:GH_MOCK_ROOT 'merge-reached') 'bad'; exit 0 }
exit 0
'@
      Set-Content (Join-Path $r8Shim 'gh.ps1') $r8Gh -Encoding utf8
      $env:PATH = "$r8Shim$([IO.Path]::PathSeparator)$r8SavedPath"
      $env:GH_MOCK_ROOT = $r8Root

      & git init --bare -q $r8Origin
      & git -C $r8Repo init -q
      & git -C $r8Repo symbolic-ref HEAD refs/heads/master
      & git -C $r8Repo config user.email selftest@local
      & git -C $r8Repo config user.name selftest
      & git -C $r8Repo remote add origin $r8Origin
      & git -C $r8Repo add -A
      & git -C $r8Repo commit -q -m base
      & git -C $r8Repo push -q -u origin master
      & pwsh -NoProfile -File (Join-Path $r8Repo 'scripts/task.ps1') -TaskId T11-R3-BASELINE -Phase start *> $null
      $r8Wt = Join-Path $r8WtRoot 'T11-R3-BASELINE'
      if ($LASTEXITCODE -ne 0 -or -not (Test-Path $r8Wt)) { Fail '闸17aa(8) setup：task start 未建出 T11 worktree。' }
      else {
        Set-Content (Join-Path $r8Repo 'fresh-base.txt') 'remote base advanced after worktree creation' -Encoding utf8
        & git -C $r8Repo add fresh-base.txt
        & git -C $r8Repo commit -q -m 'advance remote base'
        & git -C $r8Repo push -q origin master
        $r8RemoteSha = (& git --git-dir=$r8Origin rev-parse refs/heads/master).Trim()
        & git -C $r8Wt update-ref -d refs/remotes/origin/master
        & git -C $r8Wt rev-parse --verify --quiet refs/remotes/origin/master 1>$null 2>$null
        if ($LASTEXITCODE -eq 0) { Fail '闸17aa(8) setup：未成功删除 worktree 的 origin/master，缺失远端基线场景未造成。' }
        # TD134: the CI check gate now runs on the -NoAutoMerge path too (hoisted above the split), so the
        # origin-ok case below reaches it — the stub's headRefOid branch needs GH_MOCK_WT from the start.
        $env:GH_MOCK_WT = $r8Wt

        foreach ($r8Case in @(
          @{ mode='mismatch'; pattern='SHIP-PR-RETARGET' },
          @{ mode='empty';    pattern='SHIP-PR-BASE-UNKNOWN' },
          @{ mode='fail';     pattern='SHIP-PR-BASE-UNKNOWN' }
        )) {
          Remove-Item (Join-Path $r8Root 'review-reached') -ErrorAction SilentlyContinue
          $env:GH_MOCK_BASE_MODE = $r8Case.mode
          $r8Out = (& pwsh -NoProfile -File (Join-Path $r8Repo 'scripts/task.ps1') -TaskId T11-R3-BASELINE -Phase ship -SkipRed -NoAutoMerge 2>&1 | Out-String)
          $r8Exit = $LASTEXITCODE
          if ($r8Exit -eq 0) { Fail "Seed defect 17aa(8/$($r8Case.mode)): remote ship still exited 0 when gh baseRefName is $($r8Case.mode) (fail-open)."; break }
          elseif ($r8Out -notmatch $r8Case.pattern) { $r8Diag = if ($r8Out.Length -gt 800) { $r8Out.Substring($r8Out.Length - 800) } else { $r8Out }; Fail "Gate 17aa(8/$($r8Case.mode)): blocked, but the base-query cause code is absent from the output. Tail=$r8Diag"; break }
          elseif (Test-Path (Join-Path $r8Root 'review-reached')) { Fail "Gate 17aa(8/$($r8Case.mode)): base unconfirmed yet review was still entered."; break }
        }
        $r8TrackedSha = (& git -C $r8Wt rev-parse refs/remotes/origin/master 2>$null | Out-String).Trim()
        if (-not $fail -and $r8TrackedSha -ne $r8RemoteSha) { Fail "闸17aa(8/F5)：ship 未把缺失/陈旧 origin/master 刷新到远端当前 SHA（local=$r8TrackedSha remote=$r8RemoteSha）。" }
        if (-not $fail) {
          Remove-Item (Join-Path $r8Root 'review-reached') -ErrorAction SilentlyContinue
          $env:GH_MOCK_BASE_MODE = 'origin-ok'
          & pwsh -NoProfile -File (Join-Path $r8Repo 'scripts/task.ps1') -TaskId T11-R3-BASELINE -Phase ship -Base origin/master -SkipRed -NoAutoMerge *> $null
          if ($LASTEXITCODE -ne 0 -or -not (Test-Path (Join-Path $r8Root 'review-reached'))) { Fail '闸17aa(8/origin-form)：-Base origin/master 未归一化为 GitHub baseRefName=master 并走到 review 成功。' }
        }
        if (-not $fail) {
          Remove-Item (Join-Path $r8Root 'review-reached'),(Join-Path $r8Root 'merge-reached'),(Join-Path $r8Root 'base-count') -ErrorAction SilentlyContinue
          $env:GH_MOCK_BASE_MODE = 'retarget'
          $r8RetargetOut = (& pwsh -NoProfile -File (Join-Path $r8Repo 'scripts/task.ps1') -TaskId T11-R3-BASELINE -Phase ship -SkipRed 2>&1 | Out-String)
          if ($LASTEXITCODE -eq 0 -or $r8RetargetOut -notmatch 'SHIP-PR-RETARGET') { $r8RetargetDiag = if ($r8RetargetOut.Length -gt 1000) { $r8RetargetOut.Substring($r8RetargetOut.Length - 1000) } else { $r8RetargetOut }; Fail "Seed defect 17aa(8/retarget): a PR retargeted from master to other after R3 was not re-verified and blocked before merge (SHIP-PR-RETARGET absent). Output tail=$r8RetargetDiag" }
          elseif (-not (Test-Path (Join-Path $r8Root 'review-reached'))) { Fail '闸17aa(8/retarget)：夹具未走过 review，未真正覆盖评审后的 TOCTOU 窗口。' }
          elseif (Test-Path (Join-Path $r8Root 'merge-reached')) { Fail '闸17aa(8/retarget)：二次 base 校验失败后仍调用 gh pr merge。' }
        }
        if (-not $fail) {
          # 17aa(8/T24-mint) 远端铸造行为（T24 R3 r5 #17/#6，复用本 gh mock 远端 ship 夹具）：`gh pr merge` exit 0 ≠ 已合并——
          #   state=OPEN（auto-merge/队列仅入队）→ 不铸凭据且 ship fail-closed；state=MERGED → 铸 tip 绑定凭据（tip==被合并 head）。
          $r8TokFile = Join-Path (Join-Path (Join-Path $r8Repo '.git') 'scaffold-merged') 'T11-R3-BASELINE'
          $env:GH_MOCK_BASE_MODE = 'ok'
          $env:GH_MOCK_WT = $r8Wt
          Remove-Item $r8TokFile -Force -ErrorAction SilentlyContinue
          $env:GH_MOCK_MERGE_STATE = 'open'
          $r8OpenOut = (& pwsh -NoProfile -File (Join-Path $r8Repo 'scripts/task.ps1') -TaskId T11-R3-BASELINE -Phase ship -SkipRed 2>&1 | Out-String)
          if ($LASTEXITCODE -eq 0) { Fail '闸17aa(8/T24-mint-open)：gh pr merge 返回 0 但 PR state=OPEN（仅入队）时 ship 仍退出 0——未合并状态被当已合并。' }
          elseif (Test-Path $r8TokFile) { Fail '闸17aa(8/T24-mint-open)：PR 未 MERGED 却铸出了合并凭据——cleanup 将被授权删除未合并分支（T24 数据丢失面重开）。' }
          elseif ($r8OpenOut -notmatch 'T24-MERGETOKEN') { Fail '闸17aa(8/T24-mint-open)：fail-closed 但报错未携带 T24-MERGETOKEN 哨兵与恢复指引。' }
          if (-not $fail) {
            $env:GH_MOCK_MERGE_STATE = 'merged'
            & pwsh -NoProfile -File (Join-Path $r8Repo 'scripts/task.ps1') -TaskId T11-R3-BASELINE -Phase ship -SkipRed *> $null
            $r8MintExit = $LASTEXITCODE
            $r8WtHead = "$(& git -C $r8Wt rev-parse HEAD 2>$null)".Trim()
            if ($r8MintExit -ne 0) { Fail "闸17aa(8/T24-mint-merged)：state=MERGED 的远端 ship 非零退出（$r8MintExit）。" }
            elseif (-not (Test-Path $r8TokFile)) { Fail '闸17aa(8/T24-mint-merged)：远端合并成功但未铸 T24-MERGETOKEN 凭据文件。' }
            else {
              $r8TokTip = "$(@(Get-Content $r8TokFile) -match '^tip=' -replace '^tip=', '' | Select-Object -First 1)".Trim()
              if ($r8TokTip -ne $r8WtHead) { Fail "闸17aa(8/T24-mint-merged)：凭据 tip=$r8TokTip ≠ 被合并的分支 HEAD=$r8WtHead——tip 绑定铸错。" }
              else { Write-Host '  17aa(8/T24-mint) 远端铸造行为 OK（OPEN 不铸 + fail-closed；MERGED 铸 tip 绑定凭据）' -ForegroundColor Green }
            }
          }
          $env:GH_MOCK_MERGE_STATE = $null; $env:GH_MOCK_WT = $null
        }
        if (-not $fail) { Write-Host '  [SELFTEST-R3-FIXTURE-EXECUTED] 17aa(8) 远端基线刷新 + gh base 三态 fail-closed + origin/ 归一化 + R3 后 retarget 再校验 + T11 DoD 真执行 OK' -ForegroundColor Green }
      }
    }
    finally {
      $env:PATH = $r8SavedPath; $env:GH_MOCK_BASE_MODE = $r8SavedMode; $env:GH_MOCK_ROOT = $r8SavedRoot
      $env:GH_MOCK_MERGE_STATE = $r8SavedMergeState; $env:GH_MOCK_WT = $r8SavedMockWt
      & git -C $r8Repo worktree prune 2>$null
      Remove-Item -Recurse -Force $r8Root -ErrorAction SilentlyContinue
    }
  }
}

# --- T37-REMOTEMX. 远端态 hermetic 夹具矩阵（TD89 收口）：底座 pre-PR→PR 新建腿→mock 合并 / push 非 FF drive-through / 远端合并失败态 ---
# 归在闸①下（静态/hermetic、gh 恒 PATH-stub，绝不真打 GitHub）；不新增顶层 Step（护闸⑭计数一致，见 :269 设计注）。
# 复用 17aa(8) GH_MOCK PATH-stub gh + 裸 origin + 15r(e) 隔离仓；本卡新增能力 = gh stub 按 PR 存在性状态化
# （create 前 `gh pr view --json number` 返回空→走 PR 新建腿；create 后返回号→走复用腿）+ 可注入远端 merge 失败。
# 每场景各建一个全新隔离仓（own root/origin/worktree/shim）——完全隔离、独立 teardown，防跨场景状态残留假绿（L137）。
if (-not $fail -and -not $gitPost) {
  Write-Host '  T37-REMOTEMX skipped (git absent; the remote-state matrix needs a real repo)' -ForegroundColor DarkGray
}
elseif (-not $fail) {
  if (-not $IsWindows) {
    Write-Host '  T37-REMOTEMX 远端态矩阵仅 Windows 执行（gh.ps1 经 PATHEXT 解析）；非 Windows 由 Windows CI 覆盖。' -ForegroundColor DarkGray
  } else {
    $rmSavedPath = $env:PATH; $rmSavedRoot = $env:GH_MOCK_ROOT; $rmSavedWt = $env:GH_MOCK_WT; $rmSavedMergeFail = $env:GH_MOCK_MERGE_FAIL
    $rmSavedBaseMode = $env:GH_MOCK_BASE_MODE; $rmSavedMergeState = $env:GH_MOCK_MERGE_STATE   # Codex R3 r5：全部 GH_MOCK_* 均须 save/restore（含 17aa(8) 用的 BASE_MODE/MERGE_STATE）
    $rmSavedCiMode = $env:GH_MOCK_CI_MODE; $rmSavedCiTimeout = $env:SCAFFOLD_CI_TIMEOUT_SEC
    $rmSavedContainFault = $env:SCAFFOLD_CI_CONTAINMENT_FAULT; $rmSavedSlowMs = $env:GH_MOCK_SLOW_MS
    $rmSavedRealGit = $env:GH_MOCK_REAL_GIT   # TD134 knobs: same save/restore discipline
    $script:rmRoots = @()   # Codex 二审 major#2：root 一经创建即登记（script 域），setup 中途抛异常也不泄漏临时根。
    # 集中一处的哨兵/状态文件清单（卡 dod_assert：每场景进入前统一复位全部 GH_MOCK_* 每场景旋钮 + 全部哨兵/gh 状态文件）。
    # T37 stub 实际使用的**全部**哨兵/状态文件——闸15t 新增的四个也必须在列，否则 $rmReset 名不副实、
    # 跨场景状态会残留（codex R3 r2 #4：集中复位清单未随新增哨兵更新）。
    $rmSentinels = @('pr-created', 'create-count', 'merge-reached', 'merge-attempted', 'create-fail-armed',
      'review-invoked', 'status-posted', 'pr-commented', 'merge-head-arg', 'merge-pr-arg', 'ci-checked',
      'ci-workflow-checked', 'ci-jobs-consumed', 'ci-jobs-run-id', 'ci-jobs-names', 'ci-event-trace', 'ci-gh-cwds',
      'ci-check-count', 'ci-workflow-count', 'ci-jobs-count',
      # T0-CI-IDENTITY-DEADLINE 新增：R3 窗口移 HEAD 的一次性闸（不在列 ⇒ 残留会让下一场景假红，同 codex R3 r2 #4）。
      'r3-head-moved', 'local-base-moved', 'base-moved-applied', 'headmove-count', 'ci-final-pr-count', 'ci-recipe-checked', 'deadline-legs', 'orphan-started', 'orphan-completed', 'git-hang-started',
      'git-hang-completed', 'deadline-pre-git', 'arm-git-hang', 'ci-git-calls', 'ci-api-hang-started',
      'ci-api-hang-completed')   # base-count 属 17aa(8)，本卡 stub 不写；last five: TD134
    $rmReset = {
      param($root)
      foreach ($s in $rmSentinels) { Remove-Item (Join-Path $root $s) -ErrorAction SilentlyContinue }
      # Codex R3 r5：进入场景前统一复位**全部** GH_MOCK_* 每场景旋钮（含 17aa(8) 的 BASE_MODE/MERGE_STATE，防跨闸继承）；PATH/GH_MOCK_ROOT 由 $rmMake 绑至本夹具。
      $env:GH_MOCK_WT = $null; $env:GH_MOCK_MERGE_FAIL = $null; $env:GH_MOCK_BASE_MODE = $null; $env:GH_MOCK_MERGE_STATE = $null
      $env:GH_MOCK_CI_MODE = $null; $env:SCAFFOLD_CI_TIMEOUT_SEC = $null
      $env:SCAFFOLD_CI_CONTAINMENT_FAULT = $null; $env:GH_MOCK_SLOW_MS = $null
      $env:GH_MOCK_REAL_GIT = $null
    }
    # Finding B（Codex R3 r3 #2）：证远端投影真被更新——push 成功后裸 origin 的任务 ref 须 == worktree HEAD。
    $rmOriginRef = { param($origin) "$(& git --git-dir=$origin rev-parse refs/heads/T0-REMOTEMX 2>$null)".Trim() }
    # Restored downstream CI identity/deadline fixture driver (T0-CI-IDENTITY-DEADLINE).
    $ciShip = {
      param($fx, [string]$Mode, [string[]]$Extra = @(), [string]$TimeoutSec = '30', [string]$Fault = '', [string]$SlowMs = '')
      & $rmReset $fx.Root
      # 效果账本随每次 ship 复位：闸的**逐字段拒因**只落在这里（Add-CatchRecord，不打印到 stdout），
      # 身份负例要证明「命中的是被造坏的那一处」就得读它——跨轮残留会让上一例的拒因冒充本例的证据。
      $ledger = Join-Path $fx.Repo '_local/effectiveness-ledger.jsonl'
      Remove-Item $ledger -ErrorAction SilentlyContinue
      # 每场景旋钮一律在 $rmReset **之后**设置：$rmReset 会把它们全部清空（防跨场景继承），在外面先设再调本闭包等于白设。
      $env:GH_MOCK_WT = $fx.Wt; $env:GH_MOCK_CI_MODE = $Mode; $env:SCAFFOLD_CI_TIMEOUT_SEC = $TimeoutSec
      $env:SCAFFOLD_CI_CONTAINMENT_FAULT = $Fault; $env:GH_MOCK_SLOW_MS = $SlowMs
      $sw = [Diagnostics.Stopwatch]::StartNew()
      $out = (& pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship @Extra 2>&1 | Out-String)
      $exit = $LASTEXITCODE
      $sw.Stop()
      $lines = @((Get-Content (Join-Path $fx.Root 'ci-gh-cwds') -ErrorAction SilentlyContinue) | Where-Object { $_ })
      $num = { param($n) $p = Join-Path $fx.Root $n; if (Test-Path $p) { [int]((Get-Content $p -Raw).Trim()) } else { 0 } }
      $txt = { param($n) $p = Join-Path $fx.Root $n; if (Test-Path $p) { "$(Get-Content $p -Raw)".Trim() } else { '' } }
      [pscustomobject]@{
        Mode = $Mode; X = $exit; O = $out; Sec = $sw.Elapsed.TotalSeconds
        Calls = @($lines | ForEach-Object { ($_ -split '\|', 3)[0] })
        Urls = @($lines | ForEach-Object { ($_ -split '\|', 3)[2] })
        BadCwd = @($lines | Where-Object { (($_ -split '\|', 3)[1]) -ine $fx.Wt })
        CR = (& $num 'ci-check-count'); WR = (& $num 'ci-workflow-count'); JR = (& $num 'ci-jobs-count')
        MA = [bool](Test-Path (Join-Path $fx.Root 'merge-attempted'))
        M = [bool](Test-Path (Join-Path $fx.Root 'merge-reached'))
        MH = (& $txt 'merge-head-arg')
        JobsRunId = (& $txt 'ci-jobs-run-id')
        JobsNames = @((Get-Content (Join-Path $fx.Root 'ci-jobs-names') -ErrorAction SilentlyContinue) | Where-Object { $_ })
        PrN = (& $txt 'fixture-pr-number'); RunId = (& $txt 'fixture-run-id'); Try = (& $txt 'fixture-run-attempt')
        Led = @((Get-Content $ledger -ErrorAction SilentlyContinue) | Where-Object { $_ }) -join "`n"
        H = "$(& git -C $fx.Wt rev-parse HEAD 2>$null)".Trim()
      }
    }
    $ciExpectIdBlock = {
      param($r, [string]$Sentinel, [int]$C = -1, [int]$W = -1, [int]$J = -1, [string]$Led = '')
      if ($r.X -eq 0) { return 'exit 0（未 fail-closed）' }
      if ($r.O -cnotmatch $Sentinel) { return "缺哨兵 $Sentinel；尾段=$($r.O.Substring([Math]::Max(0, $r.O.Length - 400)))" }
      if ($r.MA -or $r.M) { return "触达合并腿（attempted=$($r.MA) reached=$($r.M)）" }
      if ($r.BadCwd.Count -gt 0) { return "gh 调用未绑 worktree CWD：$($r.BadCwd -join ',')" }
      if ((($C -ge 0) -and ($r.CR -ne $C)) -or (($W -ge 0) -and ($r.WR -ne $W)) -or (($J -ge 0) -and ($r.JR -ne $J))) {
        return "读计数 $($r.CR)/$($r.WR)/$($r.JR)，期望 $C/$W/$J——链没有停在该环"
      }
      if ($Led -and ($r.Led -cnotmatch $Led)) { return "账本未点名被造坏处（期望 '$Led'，实际 $($r.Led)）" }
      return ''
    }
    # 状态化 gh stub 源（各场景各写一份到自己的 shim；17aa(8) 的 stub 不动）：
    #   create → 记 pr-created 号 + 累加 create-count；number → pr-created 在则返号、否则空（=尚无 PR）；
    #   merge → GH_MOCK_MERGE_FAIL=1 时非零退出（注入远端合并失败），否则记 merge-reached；state,headRefOid → MERGED+HEAD。
    $rmGh = @'
function Add-CiTrace([string]$Event) {
  Add-Content (Join-Path $env:GH_MOCK_ROOT 'ci-event-trace') $Event
}
function Add-CiCwd([string]$Call, [string]$Payload = '') {
  Add-Content (Join-Path $env:GH_MOCK_ROOT 'ci-gh-cwds') "$Call|$((Get-Location).Path)|$Payload"
}
function Next-CiCount([string]$Name) {
  $p = Join-Path $env:GH_MOCK_ROOT $Name
  $n = if (Test-Path $p) { [int]((Get-Content $p -Raw).Trim()) } else { 0 }
  Set-Content $p ($n + 1)
  return ($n + 1)
}
function Send-CiJson($o) { $o | ConvertTo-Json -Depth 6 -Compress; exit 0 }
function Wait-CiDeadlineLeg([string]$Name) {
  if ($env:GH_MOCK_CI_MODE -ceq 'deadline-slow') {
    Add-Content (Join-Path $env:GH_MOCK_ROOT 'deadline-legs') "$Name|$([DateTimeOffset]::UtcNow.ToString('o'))"
    Start-Sleep -Milliseconds ([int]$env:GH_MOCK_SLOW_MS)
  } elseif ($Name -ceq 'head' -and "$env:GH_MOCK_CI_MODE" -like 'git-*-hang') {
    $p=Join-Path $env:GH_MOCK_ROOT 'deadline-pre-git'; if (-not (Test-Path $p)) { Set-Content $p ([DateTimeOffset]::UtcNow.ToString('o')); Start-Sleep -Milliseconds ([int]$env:GH_MOCK_SLOW_MS) }
  }
}
function Get-CiPage([string]$s) { if ($s -match '(?:\?|&)page=(\d+)') { [int]$Matches[1] } else { 1 } }
# 分页契约夹具注入器（T0-CI-PAGED-CONTRACT）：GH_MOCK_CI_MODE = '<endpoint>-<case>'。
# 三个分页 endpoint 共用生产侧同一个读取函数，故三者各自把自己的**合法条目原型** $Item 交给本注入器，
# 由它按 case 造出畸形/重放载荷并直接应答；模式不匹配则原样返回，交回该 endpoint 的正常分支。
# 每个 case 只动一处（total_count 的形态、集合的形态、或条目 id 的形态），其余保持合法——
# 这样闸被拦下时命中的必然是被造坏的那一处，而不是顺带的其它不合法。
function Send-CiShapeCase([string]$Endpoint, [string]$Collection, $Item, [int]$Page) {
  $mode = "$env:GH_MOCK_CI_MODE"; $prefix = "$Endpoint-"
  if (-not $mode.StartsWith($prefix, [StringComparison]::Ordinal)) { return }
  $case = $mode.Substring($prefix.Length)
  $shapeCases = @('missing-total', 'null-total', 'string-total', 'fraction-total', 'negative-total',
    'object', 'item-not-object', 'total-drift', 'page-replay', 'dup-in-page')
  $idCases = @('id-missing', 'id-null', 'id-string', 'id-fraction', 'id-zero', 'id-negative', 'id-over-int64')
  if (($case -notin $shapeCases) -and ($case -notin $idCases)) { return }
  # total_count：page-replay/total-drift 声明 2（两页才读得完），其余单页 1。total-drift 第二页故意报 3。
  $o = [ordered]@{}
  if ($case -cne 'missing-total') {
    $total = 1
    if ($case -ceq 'null-total') { $total = $null }
    elseif ($case -ceq 'string-total') { $total = '1' }
    elseif ($case -ceq 'fraction-total') { $total = [double]1.0 }
    elseif ($case -ceq 'negative-total') { $total = [long](-1) }
    elseif ($case -ceq 'page-replay' -or $case -ceq 'dup-in-page') { $total = 2 }
    elseif ($case -ceq 'total-drift') { if ($Page -eq 1) { $total = 2 } else { $total = 3 } }
    $o.total_count = $total
  }
  # id 负例一律**从该 endpoint 自己的合法 id 派生**（而不是写死一个常数）：这样被拒的原因只可能是形态，
  # 不可能是「换了个别的值」。id-over-int64 必须用 BigInteger——[decimal]/[double] 会被 ConvertTo-Json
  # 渲染成 `9223372036854775808.0`、读回即 Double，那样只是把「小数 id」又测了一遍。
  $realId = [long]$Item.id
  if ($case -ceq 'id-missing') { $Item.Remove('id') }
  elseif ($case -ceq 'id-null') { $Item.id = $null }
  elseif ($case -ceq 'id-string') { $Item.id = "$realId" }
  elseif ($case -ceq 'id-fraction') { $Item.id = [double]$realId }
  elseif ($case -ceq 'id-zero') { $Item.id = [long]0 }
  elseif ($case -ceq 'id-negative') { $Item.id = -$realId }
  elseif ($case -ceq 'id-over-int64') { $Item.id = [bigint]::Parse('9223372036854775808') }
  # total-drift 的第二页给一个**全新合法 id**：让这条只在 total_count 上不合法，不依赖生产侧
  # 「漂移检查排在去重之前」这个顺序也仍然只可能命中漂移出口。
  elseif ($case -ceq 'total-drift' -and $Page -gt 1) { $Item.id = $realId + 1 }
  # 注意：集合值必须逐句赋值，**不能**写成 `$o[$k] = if (...) {...} else {...}`——
  # if 分支的输出走管线，单元素数组会被解包成标量，于是每个负例都变成「集合不是数组」那一种，
  # 十几条用例塌缩成同一条（本闸开发期实测踩到）。
  if ($case -ceq 'object') { $o[$Collection] = $Item }
  elseif ($case -ceq 'item-not-object') { $o[$Collection] = [object[]]@($null) }
  # 同页重复：一页内两条 id 相同的条目，total_count=2 ⇒ 去重若失效，这一页自己就把总数凑满并判为读完。
  elseif ($case -ceq 'dup-in-page') { $o[$Collection] = [object[]]@($Item, $Item) }
  else { $o[$Collection] = [object[]]@($Item) }
  Send-CiJson $o
}
