                elseif (-not (Test-Path (Join-Path $fx2.Root 'merge-reached'))) { Fail 'T37-REMOTEMX/2-rerun：重跑 ship 未走到 mock 合并腿。' }
                elseif ($originRef2b -ne $head2b) { Fail "T37-REMOTEMX/2-rerun：FF push 后 origin ref($originRef2b) != worktree HEAD($head2b)——远端投影未更新（Codex R3 r3 #2）。" }
                else { Write-Host '  T37-REMOTEMX/2 push 非 FF drive-through（首跑 push 拒→教义 merge→重跑 resume+幂等 push 变 FF 全绿，origin ref==HEAD）OK' -ForegroundColor Green }
              }
            }
          }
        }
        finally { Remove-Item -Recurse -Force $fx2.Root -ErrorAction SilentlyContinue }
      }

      # 场景 3：远端合并失败态（TD89 点名零覆盖缺口）——注入 gh pr merge 非零 → ship fail-closed：非零退出、点名合并失败、绝不铸 T24 凭据。
      if (-not $fail) {
        $fx3 = & $rmMake 'mergefail'
        try {
          if (-not $fx3.Ok) { Fail 'T37-REMOTEMX/3 setup：合并失败夹具 start 未产出 worktree。' }
          else {
            & $rmReset $fx3.Root
            $tok3 = Join-Path $fx3.Repo '.git/scaffold-merged/T0-REMOTEMX'
            $env:GH_MOCK_WT = $fx3.Wt; $env:GH_MOCK_MERGE_FAIL = '1'
            # 真 RED（非 -SkipRed，与场景 1/2 一致）：worktree README 无 GREENMX → -Phase red 落证据；再写 GREENMX 令 DoD 绿。
            & pwsh -NoProfile -File (Join-Path $fx3.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fx3.Wt 'README.md') 'GREENMX merge-fail work' -Encoding utf8
            $s3 = (& pwsh -NoProfile -File (Join-Path $fx3.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
            $s3Exit = $LASTEXITCODE
            if ($s3Exit -eq 0) { Fail 'T37-REMOTEMX/3: ship still exited 0 when the remote gh pr merge failed (not fail-closed).' }
            elseif (-not (Test-Path (Join-Path $fx3.Root 'merge-attempted'))) { Fail 'T37-REMOTEMX/3：ship 未走到 gh pr merge 腿（更早失败）——非零退出来源非远端合并失败，断言失真（Codex 二审 blocking）。' }
            elseif (Test-Path (Join-Path $fx3.Root 'merge-reached')) { Fail 'T37-REMOTEMX/3：merge 注入失败却写下成功哨兵 merge-reached（负哨兵应缺）。' }
            elseif ($s3 -notmatch 'SHIP-MERGE-FAIL') { $s3d = if ($s3.Length -gt 900) { $s3.Substring($s3.Length - 900) } else { $s3 }; Fail "T37-REMOTEMX/3: the merge failed but the error does not carry SHIP-MERGE-FAIL (must come from task.ps1's production fail-closed throw, not stub output). Tail=$s3d" }
            elseif (Test-Path $tok3) { Fail 'T37-REMOTEMX/3：远端合并失败却铸出 T24 合并凭据——cleanup 将被授权删未合并分支（数据丢失面重开）。' }
            else { Write-Host '  T37-REMOTEMX/3 远端合并失败态 fail-closed（非零退出 + merge-reached 缺 + 不铸 T24 凭据 + 点名合并失败）OK' -ForegroundColor Green }
          }
        }
        finally { Remove-Item -Recurse -Force $fx3.Root -ErrorAction SilentlyContinue }
      }

      # 场景 3b（T64）：**CI 检查闸**——分片后本地滤过跑非验收、全量面由 CI 分片并集承担，故 ship 合并前
      # 须 fail-closed 等齐 head 的全部 check runs。种子：mock 注入一枚 failure 分片（GH_MOCK_CI_MODE=red），
      # assertions: non-zero exit + the [CI-GATE-RED code on the failing throw + the ci-checked sentinel present
      # (the gate was truly consumed, not an earlier failure) + merge-attempted ABSENT (zero merge-leg
      # touches - the red shard blocks before merge) + no T24 token minted.
      if (-not $fail) {
        $fx3b = & $rmMake 'cired'
        try {
          if (-not $fx3b.Ok) { Fail 'T64-CIRED setup：夹具 start 未产出 worktree。' }
          else {
            & $rmReset $fx3b.Root
            $env:GH_MOCK_WT = $fx3b.Wt; $env:GH_MOCK_MERGE_FAIL = ''; $env:GH_MOCK_CI_MODE = 'red'
            & pwsh -NoProfile -File (Join-Path $fx3b.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fx3b.Wt 'README.md') 'GREENMX ci-red work' -Encoding utf8
            $s3b = (& pwsh -NoProfile -File (Join-Path $fx3b.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
            $s3bExit = $LASTEXITCODE
            $env:GH_MOCK_CI_MODE = ''
            if ($s3bExit -eq 0) { Fail 'T64-CIRED: ship still exited 0 with a failing shard - the CI check gate is fail-open and a red shard would merge (shard acceptance contract broken).' }
            elseif (-not (Test-Path (Join-Path $fx3b.Root 'ci-checked'))) { Fail 'T64-CIRED：ship 未消费 check-runs 查询（ci-checked 哨兵缺）——非零退出来源并非 CI 检查闸，断言失真。' }
            elseif ($s3b -notmatch '\[CI-GATE-RED') { $s3bd = if ($s3b.Length -gt 900) { $s3b.Substring($s3b.Length - 900) } else { $s3b }; Fail "T64-CIRED: blocked but the failing throw does not carry the CI-GATE-RED code (the message is the fix: it must point the operator at the red shard). Tail=$s3bd" }
            elseif (Test-Path (Join-Path $fx3b.Root 'merge-attempted')) { Fail 'T64-CIRED：CI 红却仍触达 gh pr merge 腿——检查闸没有挡在合并之前。' }
            else { Write-Host '  T64-CIRED CI 检查闸 fail-closed（红分片挡合并 + ci-checked 在场 + merge 腿零触达）OK' -ForegroundColor Green }
          }
        }
        finally { $env:GH_MOCK_CI_MODE = ''; Remove-Item -Recurse -Force $fx3b.Root -ErrorAction SilentlyContinue }
      }

      # 场景 3c（T64 r3 #7）：**期望分片 skipped 同样挡合并**——skipped/neutral 意味着该片一个闸都没执行，
      # 「completed 非失败」的宽判会把零执行片计入验收。mock 注入一枚 skipped 期望分片（GH_MOCK_CI_MODE=skipped），
      # assertions mirror 3b: non-zero + the [CI-GATE-RED throw + ci-checked present + merge-attempted absent.
      if (-not $fail) {
        $fx3c = & $rmMake 'ciskip'
        try {
          if (-not $fx3c.Ok) { Fail 'T64-CISKIP setup：夹具 start 未产出 worktree。' }
          else {
            & $rmReset $fx3c.Root
            $env:GH_MOCK_WT = $fx3c.Wt; $env:GH_MOCK_MERGE_FAIL = ''; $env:GH_MOCK_CI_MODE = 'skipped'
            & pwsh -NoProfile -File (Join-Path $fx3c.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fx3c.Wt 'README.md') 'GREENMX ci-skip work' -Encoding utf8
            $s3c = (& pwsh -NoProfile -File (Join-Path $fx3c.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
            $s3cExit = $LASTEXITCODE
            $env:GH_MOCK_CI_MODE = ''
            if ($s3cExit -eq 0) { Fail 'T64-CISKIP: ship still exited 0 with an expected shard skipped - a zero-execution shard was counted as acceptance (r3 #7: expected shards must be success).' }
            elseif (-not (Test-Path (Join-Path $fx3c.Root 'ci-checked'))) { Fail 'T64-CISKIP：ship 未消费 check-runs 查询（ci-checked 哨兵缺）——非零退出来源并非 CI 检查闸，断言失真。' }
            elseif ($s3c -notmatch '\[CI-GATE-RED') { $s3cd = if ($s3c.Length -gt 900) { $s3c.Substring($s3c.Length - 900) } else { $s3c }; Fail "T64-CISKIP: blocked but the failing throw does not carry the CI-GATE-RED code. Tail=$s3cd" }
            elseif (Test-Path (Join-Path $fx3c.Root 'merge-attempted')) { Fail 'T64-CISKIP：期望分片 skipped 却仍触达 gh pr merge 腿——检查闸没有挡在合并之前。' }
            else { Write-Host '  T64-CISKIP 期望分片 skipped 挡合并（只认 success + ci-checked 在场 + merge 腿零触达）OK' -ForegroundColor Green }
          }
        }
        finally { $env:GH_MOCK_CI_MODE = ''; Remove-Item -Recurse -Force $fx3c.Root -ErrorAction SilentlyContinue }
      }

      # Restored merged downstream contracts; kept inside the existing T37 remote fixture (no new sub-gate).
      if (-not $fail) {
        $dlProblem = $null; $taskPath = Join-Path $RepoRoot 'scripts/task.ps1'; $taskText = Get-Content $taskPath -Raw
        $tok = $null; $pe = $null
        $ast = [Management.Automation.Language.Parser]::ParseFile($taskPath, [ref]$tok, [ref]$pe)
        $deadlineAssignments = @($ast.FindAll({ param($n)
          $n -is [Management.Automation.Language.AssignmentStatementAst] -and
          $n.Left -is [Management.Automation.Language.VariableExpressionAst] -and
          $n.Left.VariablePath.UserPath -ceq 'ciDeadline'
        }, $true))
        $passCalls = @($ast.FindAll({ param($n)
          $n -is [Management.Automation.Language.CommandAst] -and $n.GetCommandName() -ceq 'Write-Host' -and
          $n.Extent.Text -cmatch '\[CI-GATE-PASS\]'
        }, $true))
        if ($pe.Count -gt 0 -or $deadlineAssignments.Count -ne 1 -or $passCalls.Count -ne 1 -or
            $deadlineAssignments[0].Right.Extent.Text -cne '[DateTimeOffset]::UtcNow.AddSeconds($ciTimeoutSec)') {
          $dlProblem = 'candidate-CI deadline AST 边界不可唯一定位'
        }
        else {
          $dlStart = $deadlineAssignments[0].Extent.StartOffset
          $dlEnd = $passCalls[0].Extent.StartOffset
          if ($dlEnd -le $dlStart) { $dlProblem = 'candidate-CI deadline AST 边界次序错误' }
        }
        if (-not $dlProblem) {
          $dlCi = $taskText.Substring($dlStart, $dlEnd - $dlStart)
          if ($dlCi -match '(?m)^\s*&\s+(?:gh|git)\b') { $dlProblem = 'candidate-CI 仍有绕过统一 deadline 的裸 gh/git 调用' }
          $deadlineBlock = $deadlineAssignments[0].Parent
          $deadlineStatements = if ($deadlineBlock -is [Management.Automation.Language.StatementBlockAst]) { @($deadlineBlock.Statements) } else { @() }
          $deadlineIndex = [array]::IndexOf([object[]]$deadlineStatements, $deadlineAssignments[0])
          $warmText = if ($deadlineIndex -gt 0) { $deadlineStatements[$deadlineIndex - 1].Extent.Text } else { '' }
          if (-not $dlProblem -and $warmText -cne 'Initialize-CiContainment -Fault "$env:SCAFFOLD_CI_CONTAINMENT_FAULT"') { $dlProblem = '容纳原语未在 candidate-CI deadline 建立前紧邻预热' }
          if (-not $dlProblem -and $taskText -cnotmatch 'STARTUPINFOEX|PROC_THREAD_ATTRIBUTE_HANDLE_LIST|UpdateProcThreadAttribute') { $dlProblem = 'CreateProcess 未白名单继承标准流 handles' }
        }
        # 直接执行生产函数：外层 ship 墙钟不能区分一份/两份 cleanup grace，也会把前段固定成本混进去。
        if (-not $dlProblem) {
          $defs = @($ast.FindAll({ param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] -and
            $n.Name -in @('Initialize-CiContainment','Invoke-ExternalBeforeDeadline') }, $true) | Sort-Object { $_.Extent.StartOffset })
          if ($pe.Count -gt 0 -or $defs.Count -ne 2) { $dlProblem = '生产容纳函数缺失或不可解析' }
          elseif (($defs.Extent.Text -join "`n") -match '(?m)\.WaitForExit\(\)') { $dlProblem = '生产容纳函数仍有无参 WaitForExit()，重定向句柄可令闸无界等待' }
          else {
            $names = @('Invoke-GhBeforeDeadline','Get-ExactHeadChecksBeforeDeadline','Get-GhPagedCollectionBeforeDeadline','Invoke-ExternalBeforeDeadline','Get-GitOidBeforeDeadline','Wait-CiRetryBeforeDeadline')
            $calls = @($ast.FindAll({ param($n) $n -is [Management.Automation.Language.CommandAst] }, $true) | Where-Object {
              $_.Extent.StartOffset -ge $dlStart -and $_.Extent.EndOffset -le $dlEnd -and $_.GetCommandName() -in $names
            })
            if ($calls.Count -ne 17) { $dlProblem = "candidate-CI 外部/等待调用数漂移（$($calls.Count) != 17）" }
            foreach ($call in $calls) {
              if ($dlProblem) { break }
              $els = @($call.CommandElements); $name = $call.GetCommandName()
              if ($name -ceq 'Wait-CiRetryBeforeDeadline') { if ($els.Count -ne 2 -or $els[1].Extent.Text -cne '$ciDeadline') { $dlProblem = "$name 未绑定唯一 `$ciDeadline" } }
              else {
                $di = -1; for ($i=0; $i -lt $els.Count; $i++) { if ($els[$i] -is [Management.Automation.Language.CommandParameterAst] -and $els[$i].ParameterName -ceq 'Deadline') { $di=$i; break } }
                if ($di -lt 0 -or $di + 1 -ge $els.Count -or $els[$di + 1].Extent.Text -cne '$ciDeadline') { $dlProblem = "$name 未绑定唯一 `$ciDeadline" }
              }
            }
            $edges = @(
              @('Invoke-GhBeforeDeadline','Invoke-ExternalBeforeDeadline'), @('Get-GitOidBeforeDeadline','Invoke-ExternalBeforeDeadline'),
              @('Get-GhPagedCollectionBeforeDeadline','Invoke-GhBeforeDeadline'), @('Get-ExactHeadChecksBeforeDeadline','Get-GhPagedCollectionBeforeDeadline'))
            foreach ($edge in $edges) {
              if ($dlProblem) { break }
              $fnName=$edge[0]; $callee=$edge[1]
              $fn = @($ast.FindAll({ param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -ceq $fnName }, $true))
              $inner = @(if ($fn.Count -eq 1) { $fn[0].FindAll({ param($n) $n -is [Management.Automation.Language.CommandAst] -and $n.GetCommandName() -ceq $callee }, $true) })
              if ($inner.Count -ne 1) { $dlProblem = "$fnName 未唯一委派 $callee"; break }
              $els=@($inner[0].CommandElements); $di=-1; for($i=0;$i -lt $els.Count;$i++){if($els[$i] -is [Management.Automation.Language.CommandParameterAst] -and $els[$i].ParameterName -ceq 'Deadline'){$di=$i;break}}
              if ($di -lt 0 -or $di+1 -ge $els.Count -or $els[$di+1].Extent.Text -cne '$Deadline') { $dlProblem = "$fnName 在 helper 内重启/丢失共享 deadline" }
            }
            if (-not $dlProblem) { . ([scriptblock]::Create(($defs.Extent.Text -join "`n"))) }
          }
        }
        $dlRoot = $null
        if (-not $dlProblem) {
          $dlRoot = Join-Path ([IO.Path]::GetTempPath()) ('stT37_deadline_' + [guid]::NewGuid().ToString('N').Substring(0,8))
          New-Item -ItemType Directory -Force $dlRoot | Out-Null
          $oldFault = $env:SCAFFOLD_CI_CONTAINMENT_FAULT
          try {
            $waitGone = { param([int]$Id) $until=[DateTimeOffset]::UtcNow.AddSeconds(1); do { $p=Get-Process -Id $Id -ErrorAction SilentlyContinue; if(-not $p){return $true}; Start-Sleep -Milliseconds 50 } while([DateTimeOffset]::UtcNow -lt $until); return (-not (Get-Process -Id $Id -ErrorAction SilentlyContinue)) }
            # 必须触达真实 Add-Type catch；不能用预抛 fault 冒充编译失败。
            $env:SCAFFOLD_CI_CONTAINMENT_FAULT = 'add-type'; $msg = ''
            try { [void](Invoke-ExternalBeforeDeadline -Command 'cmd.exe' -Arguments @('/d','/c','exit','0') -Deadline ([DateTimeOffset]::UtcNow.AddSeconds(8)) -WorkingDirectory $dlRoot) } catch { $msg = $_.Exception.ToString() }
            if ($msg -cnotmatch '\[CI-GATE-CONTAINMENT\] stage=add-type\b' -or $msg -cnotmatch '\bCS\d{4}\b') { $dlProblem = 'Add-Type 负例未触达真实编译失败 catch' }

            $env:SCAFFOLD_CI_CONTAINMENT_FAULT = $null
            $ok = Invoke-ExternalBeforeDeadline -Command 'cmd.exe' -Arguments @('/d','/c','echo','contained') -Deadline ([DateTimeOffset]::UtcNow.AddSeconds(8)) -WorkingDirectory $dlRoot
            if ($ok.TimedOut -or $ok.ExitCode -ne 0 -or $ok.Stdout -notmatch 'contained') { $dlProblem = '容纳执行器正例未保留 stdout/exit' }

            # 每个 setup stage 都必须 fail-closed，且 assign/resume 前后的 suspended child 不得执行 body。
            foreach ($stage in @('create-job','configure-job','create-process','assign','resume','platform')) {
              if ($dlProblem) { break }
              $mark = Join-Path $dlRoot "$stage-ran"; Remove-Item $mark -ErrorAction SilentlyContinue
              $env:SCAFFOLD_CI_CONTAINMENT_FAULT = $stage; $msg = ''
              try { [void](Invoke-ExternalBeforeDeadline -Command 'pwsh' -Arguments @('-NoProfile','-Command',"Set-Content -LiteralPath '$mark' yes") -Deadline ([DateTimeOffset]::UtcNow.AddSeconds(8)) -WorkingDirectory $dlRoot) }
              catch { $msg = $_.Exception.ToString() }
              if ($msg -cnotmatch "\[CI-GATE-CONTAINMENT\] stage=$stage\b") { $dlProblem = "$stage 未以稳定 containment 诊断 fail-closed" }
              elseif ($stage -ne 'platform' -and $msg -cnotmatch 'api-result') { $dlProblem = "$stage 未经真实返回值 guard fail-closed" }
              elseif (Test-Path $mark) { $dlProblem = "$stage 失败时 suspended child 仍执行了 body" }
              elseif ($stage -in @('assign','resume')) {
                $pm = [regex]::Match($msg,'\bpid=(\d+)\b'); $gone = $pm.Success -and (& $waitGone ([int]$pm.Groups[1].Value))
                if (-not $gone) { if($pm.Success){Stop-Process -Id ([int]$pm.Groups[1].Value) -Force -ErrorAction SilentlyContinue}; $dlProblem = "$stage 失败留下 suspended root 或未记录 PID" }
              }
            }

