            else {
              $env:GH_MOCK_WT = $fxd.Wt
              & pwsh -NoProfile -File (Join-Path $fxd.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
              Set-Content (Join-Path $fxd.Wt 'README.md') 'GREENMX deadline' -Encoding utf8
              $r = & $ciShip $fxd 'deadline-slow' @('-NoAutoMerge') '20' '' '11000'
              $legs = @((Get-Content (Join-Path $fxd.Root 'deadline-legs') -ErrorAction SilentlyContinue) | Where-Object { $_ })
              $ciSec = if ($legs.Count) { ([DateTimeOffset]::UtcNow - [DateTimeOffset]::Parse(($legs[0] -split '\|',2)[1])).TotalSeconds } else { 999 }
              if ($r.X -eq 0 -or $r.O -cnotmatch '\[CI-GATE-TIMEOUT\]' -or $legs.Count -lt 2 -or $r.MA -or $ciSec -ge 24) {
                $dlProblem = "gh 多腿未共享同一 wall-clock deadline（exit=$($r.X), legs=$($legs -join ','), ciSec=$([Math]::Round($ciSec,1)), merge=$($r.MA)）"
              }
            }
          } finally { if ($fxd -and $fxd.Root) { Remove-Item -Recurse -Force $fxd.Root -ErrorAction SilentlyContinue } }
        }
        if (-not $dlProblem) {
          $fxg = & $rmMake 'deadlinegit'
          try {
            if (-not $fxg.Ok) { $dlProblem = 'git deadline 夹具 start 失败' }
            else {
              # 当前 PR 首读把两个字段合并在同一个 --json 参数；只为本 DEADLINE 夹具扩展旧 head 分派，
              # 让 deadline-pre-git 仍从 CI 首次受控外部调用起计时。
              $ghShimPath = Join-Path $fxg.Shim 'gh.ps1'; $ghShimText = Get-Content $ghShimPath -Raw
              $prSnapshotDispatch = "if ((`$args -join ' ') -match 'baseRefName,headRefOid') {"
              $deadlinePrSnapshotDispatch = $prSnapshotDispatch + "`n  Wait-CiDeadlineLeg 'head'"
              if ([regex]::Matches($ghShimText, [regex]::Escape($prSnapshotDispatch)).Count -ne 1) { $dlProblem = 'git deadline gh 夹具 PR snapshot 分派形状漂移' }
              else { Set-Content $ghShimPath ($ghShimText.Replace($prSnapshotDispatch, $deadlinePrSnapshotDispatch)) -Encoding utf8 }
            }
            if (-not $dlProblem) {
              $env:GH_MOCK_WT = $fxg.Wt
              & pwsh -NoProfile -File (Join-Path $fxg.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
              Set-Content (Join-Path $fxg.Wt 'README.md') 'GREENMX git deadline' -Encoding utf8
              $env:GH_MOCK_REAL_GIT = (Get-Command git -CommandType Application -ErrorAction Stop | Select-Object -First 1).Source
              Set-Content (Join-Path $fxg.Shim 'git.ps1') $rmGitShim -Encoding utf8
              foreach ($mode in @('git-fetch-hang','git-revparse-hang')) {
                if ($dlProblem) { break }
                $r = & $ciShip $fxg $mode @('-NoAutoMerge') '25' '' '12000'
                $started = "$(Get-Content (Join-Path $fxg.Root 'git-hang-started') -Raw -ErrorAction SilentlyContinue)"
                $completed = Test-Path (Join-Path $fxg.Root 'git-hang-completed')
                $sp = $started.Trim() -split '\|',4; $gp = if ($sp.Count -ge 3 -and $sp[1] -match '^\d+$') { Get-Process -Id ([int]$sp[1]) -ErrorAction SilentlyContinue } else { $null }
                $hangSec = if ($sp.Count -ge 3) { ([DateTimeOffset]::UtcNow - [DateTimeOffset]::Parse($sp[2])).TotalSeconds } else { 999 }
                $pre = "$(Get-Content (Join-Path $fxg.Root 'deadline-pre-git') -Raw -ErrorAction SilentlyContinue)".Trim()
                $allSec = if($pre){([DateTimeOffset]::UtcNow-[DateTimeOffset]::Parse($pre)).TotalSeconds}else{999}
                if ($r.X -eq 0 -or $r.O -cnotmatch '\[CI-GATE-TIMEOUT\]' -or $sp[0] -cne $mode -or $completed -or $gp -or $hangSec -ge 14 -or $allSec -ge 27.5 -or $r.MA) {
                  if ($gp) { Stop-Process -Id $gp.Id -Force -ErrorAction SilentlyContinue }
                  $tag = [regex]::Match($r.O,'\[CI-GATE-[A-Z-]+\]').Value
                  $dlProblem = "$mode 未被统一 deadline 收口（exit=$($r.X), tag=$tag, started=$started, completed=$completed, alive=$([bool]$gp), hangSec=$([Math]::Round($hangSec,1)), allSec=$([Math]::Round($allSec,1)), merge=$($r.MA)）"
                }
              }
            }
          } finally { $env:GH_MOCK_REAL_GIT = $null; if ($fxg -and $fxg.Root) { Remove-Item -Recurse -Force $fxg.Root -ErrorAction SilentlyContinue } }
        }
        if ($dlRoot) { Remove-Item -Recurse -Force $dlRoot -ErrorAction SilentlyContinue }
        if ($dlProblem) { Fail "T37-CIGATE/DEADLINE: $dlProblem" }
        else { Write-Host '  T37-CIGATE/DEADLINE OK' -ForegroundColor Green }
      }

      if (-not $fail) {
        # 读计数含义：稳定态一轮各读 1 次、终局快照再各读 1 次 ⇒ 停在稳定态身份判定=1/1/0、停在终局快照=2/2/2。
        $wbProblem = $null
        $wbNeg = & $rmMake 'wfbind'
        try {
          if (-not $wbNeg.Ok) { $wbProblem = 'setup：身份负例夹具 start 未产出 worktree' }
          else {
            $env:GH_MOCK_WT = $wbNeg.Wt
            & pwsh -NoProfile -File (Join-Path $wbNeg.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $wbNeg.Wt 'README.md') 'GREENMX workflow binding' -Encoding utf8
          }
          # 账本 pattern 逐条只匹配「被造坏的那一处 + 其余各处仍然合法」的完整形状：例如 pr-key-case 要求
          # event/path 都还是合法值、只有 prs=0，从而排除「其实是被更早的通用错误拦下」。
          $wbCases = @(
            @{ M = 'pr-head-mismatch'; S = '\[CI-GATE-HEAD-MISMATCH\]'; C = 0; W = 0; J = 0; L = 'c{40}' }
            @{ M = 'wfid-head'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/a{40}/pull_request/\.github/workflows/ci\.yml/prs=1' }
            @{ M = 'wfid-event-case'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/Pull_Request/\.github/workflows/ci\.yml/prs=1' }
            @{ M = 'wfid-path-case'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/pull_request/\.github/workflows/CI\.yml/prs=1' }
            @{ M = 'wfid-pr-key-case'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/pull_request/\.github/workflows/ci\.yml/prs=0' }
            @{ M = 'wfid-pr-other'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/pull_request/\.github/workflows/ci\.yml/prs=0' }
            @{ M = 'snap-retarget'; S = '\[CI-GATE-BASE-MISMATCH\]'; C = 2; W = 2; J = 2; L = 'master!=release' }
            @{ M = 'snap-head-moved'; S = '\[CI-GATE-HEAD-MOVED\]'; C = 2; W = 2; J = 2; L = '->b{40}' }
          )
          foreach ($c in $wbCases) {
            if ($wbProblem) { break }
            $r = & $ciShip $wbNeg $c.M
            $why = & $ciExpectIdBlock $r $c.S $c.C $c.W $c.J $c.L
            if ($why) { $wbProblem = "$($c.M)：$why" }
          }
          # 决策前身份漂移：稳定态那一读身份完全正确、**终局快照**那一读才变。两条各打终局的一处判据——
          # 没有它们，终局那几行删掉也全绿（首读就非法的负例根本走不到终局，R3 r1 #6）。
          # run id 那条另核诊断点名夹具自己的 run id（期望值取自随机身份文件 ⇒ 断言里不可能是硬编码常数）。
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'wfid-final-drift'
            $why = & $ciExpectIdBlock $r '\[CI-GATE-WORKFLOW-IDENTITY\]' 2 2 1 ''
            if ($why) { $wbProblem = "wfid-final-drift：$why" }
            elseif ($r.O -cnotmatch "expected=$($r.RunId)\b") { $wbProblem = "wfid-final-drift：诊断未点名本夹具的 run id（expected=$($r.RunId)）" }
          }
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'wfid-final-pr-key-case'
            $why = & $ciExpectIdBlock $r '\[CI-GATE-WORKFLOW-IDENTITY\]' 2 2 1 ''
            if ($why) { $wbProblem = "wfid-final-pr-key-case：$why（终局那次 PR 关联判定若不是大小写敏感的，本例会一路走到合并）" }
          }
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'wfid-final-pr-missing'
            $why = & $ciExpectIdBlock $r '\[CI-GATE-WORKFLOW-IDENTITY\]' 2 2 1 ''
            if ($why) { $wbProblem = "wfid-final-pr-missing：$why（终局 workflow 缺 pull_requests 必须稳定 fail-closed，不能先触发 StrictMode 属性异常）" }
          }
          # A5：-NoAutoMerge 只跳过合并腿，不放松任何一层——同一条身份负例带上它仍须被同一个哨兵拦下。
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'wfid-path-case' @('-NoAutoMerge')
            $why = & $ciExpectIdBlock $r '\[CI-GATE-WORKFLOW-IDENTITY\]' 1 1 0 '/pull_request/\.github/workflows/CI\.yml/prs=1'
            if ($why) { $wbProblem = "nomerge-blocked：$why" }
          }
          # A5 绿路 + 三条 `-case` 负例的对照组：同一份载荷、属性名/取值全部小写合法 ⇒ 逐层绑定全过、
          # 打印 [CI-GATE-PASS]，但因 -NoAutoMerge 不触达合并腿。jobs 必须是按**本夹具自己的** run id/attempt 取的。
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg '' @('-NoAutoMerge')
            if ($r.X -ne 0) { $wbProblem = "nomerge-green：绿路未走通（exit $($r.X)）；尾段=$($r.O.Substring([Math]::Max(0, $r.O.Length - 500)))" }
            elseif ($r.O -cnotmatch '\[CI-GATE-PASS\]') { $wbProblem = 'nomerge-green：缺 [CI-GATE-PASS]' }
            elseif ($r.O -cnotmatch "(?m)^\[SHIP-MANUAL-RESUME\] pwsh -NoProfile -File scripts\\task\.ps1 -TaskId 'T0-REMOTEMX' -Phase ship -Base 'master'\s*$") { $wbProblem = 'nomerge-green：接续命令未安全引用 TaskId/已解析的 master 基线，或仍携带 NoAutoMerge。' }
            elseif (($r.CR -ne 2) -or ($r.WR -ne 2) -or ($r.JR -ne 2)) { $wbProblem = "nomerge-green：读计数 $($r.CR)/$($r.WR)/$($r.JR) != 2/2/2——放松了某一层" }
            elseif ($r.MA -or $r.M) { $wbProblem = '-NoAutoMerge 却触达了合并腿' }
            elseif ($r.JobsRunId -cne "$($r.RunId)/$($r.Try)") { $wbProblem = "nomerge-green：jobs 未按本夹具 run 身份取（$($r.JobsRunId)）" }
          }
          # GitHub may expose the workflow run before the required check is created or completed. Both are
          # pending states under the one shared deadline, not CI-red/drift. The transient controls must
          # progress to success; the persistent queued control must time out without reaching merge.
          foreach ($pm in @('check-queued-once','check-missing-once')) {
            if ($wbProblem) { break }
            $r = & $ciShip $wbNeg $pm @('-NoAutoMerge') '120'
            if ($r.X -ne 0) { $wbProblem = "$pm：暂态 pending 未等到 success（exit=$($r.X)）；尾段=$($r.O.Substring([Math]::Max(0,$r.O.Length-400)))" }
            elseif ($r.O -cnotmatch '\[CI-GATE-PASS\]' -or $r.CR -lt 2) { $wbProblem = "$pm：未真实消费 pending→success（checks=$($r.CR)）" }
            elseif ($r.MA -or $r.M) { $wbProblem = "$pm：-NoAutoMerge 却触达 merge" }
          }
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'check-pending' @('-NoAutoMerge') '15'
            if ($r.X -eq 0 -or $r.O -cnotmatch '\[CI-GATE-TIMEOUT\]' -or $r.CR -lt 2 -or $r.Sec -gt 55) { $wbProblem = "check-pending：持续 queued 未由共享 deadline 收口（exit=$($r.X), checks=$($r.CR), sec=$([Math]::Round($r.Sec,2))）" }
            elseif (-not (Test-Path (Join-Path $wbNeg.Root 'ci-checked'))) { $wbProblem = 'check-pending：未真实消费 check-runs endpoint' }
            elseif ($r.MA -or $r.M) { $wbProblem = 'check-pending：timeout 后仍触达 merge' }
          }
        }
        finally { if ($wbNeg -and $wbNeg.Root) { Remove-Item -Recurse -Force $wbNeg.Root -ErrorAction SilentlyContinue } }
        # A4 的两条负例各改仓状态（一条在 R3 窗口里前移本地 HEAD，一条让裸 origin 的 master 长出新提交），
        # 故各用一棵全新夹具——与阻断类共用会把「下一条负例的基线」也一并改掉。
        foreach ($mv in @(
            @{ M = 'r3-head-move'; S = '\[CI-GATE-LOCAL-HEAD-MOVED\]'; C = 0; W = 0; J = 0 }
            @{ M = 'base-moved'; S = '\[CI-GATE-BASE-MOVED\]'; C = 2; W = 2; J = 2 })) {
          if ($wbProblem) { break }
          $fxm = & $rmMake ($mv.M -replace '-', '')
          try {
            if (-not $fxm.Ok) { $wbProblem = "$($mv.M) setup：夹具 start 未产出 worktree"; break }
            $env:GH_MOCK_WT = $fxm.Wt
            & pwsh -NoProfile -File (Join-Path $fxm.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxm.Wt 'README.md') "GREENMX $($mv.M)" -Encoding utf8
            $r = & $ciShip $fxm $mv.M
            $why = & $ciExpectIdBlock $r $mv.S $mv.C $mv.W $mv.J ''
            if ($why) { $wbProblem = "$($mv.M)：$why" }
            elseif (($mv.M -ceq 'r3-head-move') -and (-not (Test-Path (Join-Path $fxm.Root 'r3-head-moved')))) {
              $wbProblem = 'r3-head-move：评审后端没有真的移动本地 HEAD，负例未构造出来'
            }
          }
          finally { if ($fxm -and $fxm.Root) { Remove-Item -Recurse -Force $fxm.Root -ErrorAction SilentlyContinue } }
        }
        # The local path has no PR/CI identity to catch these races later. Bind both the reviewed task OID
        # and the checked-out base OID across R3, then merge the immutable reviewed OID. Each negative uses
        # a fresh repo because it deliberately advances one branch; the final case is the positive control.
        foreach ($lc in @(
            @{ M = 'r3-head-move'; S = '\[CI-GATE-LOCAL-HEAD-MOVED\]'; MoveBase = $false }
            @{ M = 'local-base-move'; S = '\[SHIP-LOCAL-BASE-MOVED\]'; MoveBase = $true }
            @{ M = ''; S = ''; MoveBase = $false })) {
          if ($wbProblem) { break }
          $fxl = & $rmMake ('local' + ($lc.M -replace '-', ''))
          try {
            if (-not $fxl.Ok) { $wbProblem = "local/$($lc.M) setup：夹具 start 未产出 worktree"; break }
            $env:GH_MOCK_WT = $fxl.Wt
            & pwsh -NoProfile -File (Join-Path $fxl.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxl.Wt 'README.md') "GREENMX local $($lc.M)" -Encoding utf8
            $reviewedParent = "$(git -C $fxl.Wt rev-parse HEAD)".Trim()
            $r = & $ciShip $fxl $lc.M @('-Local')
            $baseTip = "$(git -C $fxl.Repo rev-parse master 2>$null)".Trim()
            $taskTip = "$(git -C $fxl.Wt rev-parse HEAD 2>$null)".Trim()
            & git -C $fxl.Repo merge-base --is-ancestor $taskTip master 2>$null
            $taskMerged = ($LASTEXITCODE -eq 0)
            if ($lc.S) {
              if ($r.X -eq 0) { $wbProblem = "local/$($lc.M)：竞态后仍 exit 0" }
              elseif ($r.O -cnotmatch $lc.S) { $wbProblem = "local/$($lc.M)：缺哨兵 $($lc.S)；尾段=$($r.O.Substring([Math]::Max(0,$r.O.Length-400)))" }
              elseif (($lc.M -ceq 'r3-head-move') -and -not (Test-Path (Join-Path $fxl.Root 'r3-head-moved'))) { $wbProblem = 'local/r3-head-move：R3 stub 未实际移动任务 HEAD' }
              elseif ($lc.MoveBase -and -not (Test-Path (Join-Path $fxl.Root 'local-base-moved'))) { $wbProblem = 'local/local-base-move：R3 stub 未实际移动 base HEAD' }
              elseif ($taskMerged) { $wbProblem = "local/$($lc.M)：被拒后任务 tip 仍进入 master" }
            }
            elseif ($r.X -ne 0) { $wbProblem = "local/green：固定 reviewed OID 正例失败（exit=$($r.X)）；尾段=$($r.O.Substring([Math]::Max(0,$r.O.Length-400)))" }
            elseif (-not $taskMerged) { $wbProblem = "local/green：merge 后 master=$baseTip 不包含 reviewed task tip=$taskTip" }
            elseif ($taskTip -ceq $reviewedParent) { $wbProblem = 'local/green：ship 未提交 GREENMX 改动，正例未触达 merge' }
          }
          finally { if ($fxl -and $fxl.Root) { Remove-Item -Recurse -Force $fxl.Root -ErrorAction SilentlyContinue } }
        }
        if ($wbProblem) { Fail "T37-CIGATE/WORKFLOW-BINDING: $wbProblem" }
        else { Write-Host '  T37-CIGATE/WORKFLOW-BINDING OK' -ForegroundColor Green }
      }

      # ── TD134 fixture battery (five classes): the CI check gate holds on EVERY merge path (hoisted
      #    above the auto/-NoAutoMerge split, own saga leg), reads its fan-in contract from the MERGE
      #    CANDIDATE tree, and its wait paths are testable in seconds via SCAFFOLD_CI_TIMEOUT_SEC.
      #      TD134-CIMANUAL   -NoAutoMerge + red shard -> non-zero, never "ready for manual merge"
      #      TD134-CIWFMISS   workflow absent from the candidate tree -> immediate fail-closed (no wait)
      #      TD134-CIAPIFAIL  malformed check-runs fail API-closed; a hanging call obeys the shared deadline
      #      TD134-CIHEADMOVE head moves during the CI wait -> non-zero, never merge
      #      TD134-CIMATRIX   PR edits the shard matrix -> expected set follows the HEAD yml (T65 item 4)
      if (-not $fail) {
        $fxM = & $rmMake 'cimanual'
        try {
          if (-not $fxM.Ok) { Fail 'TD134-CIMANUAL setup: fixture start produced no worktree.' }
          else {
            & $rmReset $fxM.Root
            $env:GH_MOCK_WT = $fxM.Wt; $env:GH_MOCK_CI_MODE = 'red'
            & pwsh -NoProfile -File (Join-Path $fxM.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxM.Wt 'README.md') 'GREENMX manual-mode ci-red work' -Encoding utf8
            $sM = (& pwsh -NoProfile -File (Join-Path $fxM.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship -NoAutoMerge 2>&1 | Out-String)
            $sMExit = $LASTEXITCODE
            if ($sMExit -eq 0) { Fail 'TD134-CIMANUAL: ship -NoAutoMerge exits 0 with a red shard — the manual path bypasses the CI check gate, so a hand merge would land a red head (TD134 core defect).' }
            elseif (-not (Test-Path (Join-Path $fxM.Root 'ci-checked'))) { Fail 'TD134-CIMANUAL: ship never consumed the check-runs query (ci-checked sentinel missing) — the non-zero exit did not come from the CI check gate, assertion unfaithful.' }
            elseif ($sM -match 'ready for manual merge') { Fail 'TD134-CIMANUAL: red CI but the PR was still declared ready for manual merge.' }
            elseif ($sM -notmatch '\[CI-GATE-RED') { $sMd = if ($sM.Length -gt 900) { $sM.Substring($sM.Length - 900) } else { $sM }; Fail "TD134-CIMANUAL: blocked but the failing throw does not carry the CI-GATE-RED code. tail=$sMd" }
            elseif (Test-Path (Join-Path $fxM.Root 'merge-attempted')) { Fail 'TD134-CIMANUAL: manual mode must never invoke gh pr merge itself (merge-attempted must be absent).' }
            else { Write-Host '  TD134-CIMANUAL manual path CI-gated (red shard -> non-zero + no ready-for-merge + no merge call) OK' -ForegroundColor Green }
          }
        }
        finally { $env:GH_MOCK_CI_MODE = ''; Remove-Item -Recurse -Force $fxM.Root -ErrorAction SilentlyContinue }
      }

      if (-not $fail) {
        $fxW = & $rmMake 'ciwfmiss' $true
        try {
          if (-not $fxW.Ok) { Fail 'TD134-CIWFMISS setup: fixture start produced no worktree.' }
          else {
            & $rmReset $fxW.Root
            $env:GH_MOCK_WT = $fxW.Wt
            & pwsh -NoProfile -File (Join-Path $fxW.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxW.Wt 'README.md') 'GREENMX missing-workflow work' -Encoding utf8
            $wWatch = [System.Diagnostics.Stopwatch]::StartNew()
            $sW = (& pwsh -NoProfile -File (Join-Path $fxW.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
            $sWExit = $LASTEXITCODE
            $wWatch.Stop()
            if ($sWExit -eq 0) { Fail 'TD134-CIWFMISS: no scaffold-selftest.yml anywhere in the candidate tree yet ship exits 0 — an unreadable acceptance contract must be fail-closed, not fail-open.' }
            elseif ($sW -notmatch 'merge candidate tree') { $sWd = if ($sW.Length -gt 900) { $sW.Substring($sW.Length - 900) } else { $sW }; Fail "TD134-CIWFMISS: blocked but the error does not name the missing workflow in the merge candidate tree (the message must tell the operator what to restore). tail=$sWd" }
            elseif (Test-Path (Join-Path $fxW.Root 'merge-attempted')) { Fail 'TD134-CIWFMISS: workflow missing yet the merge leg was still reached.' }
            elseif ($wWatch.Elapsed.TotalSeconds -gt 120) { Fail "TD134-CIWFMISS: missing workflow burned $([int]$wWatch.Elapsed.TotalSeconds)s — this class must fail immediately (before the wait loop), not by timeout." }
            else { Write-Host '  TD134-CIWFMISS missing workflow fail-closed (immediate, names the candidate tree, no merge) OK' -ForegroundColor Green }
          }
        }
        finally { Remove-Item -Recurse -Force $fxW.Root -ErrorAction SilentlyContinue }
      }

      if (-not $fail) {
        foreach ($aCase in @(
            @{ Tag = 'malformed'; Mode = 'apifail'; Timeout = '30'; Max = 60 }
            @{ Tag = 'hang'; Mode = 'apihang'; Timeout = '3'; Max = 60 })) {
          $fxA = & $rmMake ("ciapi" + $aCase.Tag)
          try {
            if (-not $fxA.Ok) { Fail "TD134-CIAPIFAIL/$($aCase.Tag) setup: fixture start produced no worktree." }
            else {
              & $rmReset $fxA.Root
              $env:GH_MOCK_WT = $fxA.Wt
              & pwsh -NoProfile -File (Join-Path $fxA.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
              Set-Content (Join-Path $fxA.Wt 'README.md') "GREENMX api-$($aCase.Tag) work" -Encoding utf8
              # Run the real ship consumer behind an outer mutation guard. A production change that drops
              # SCAFFOLD_CI_TIMEOUT_SEC would otherwise leave this test waiting on the 30-minute default.
              $jobAExe = Join-Path $fxA.Repo 'scripts/task.ps1'; $jobPath = $env:PATH
              $jobA = Start-Job -ArgumentList @($jobAExe,$fxA.Root,$fxA.Wt,$aCase.Mode,$aCase.Timeout,$jobPath) -ScriptBlock {
                param($Exe,$Root,$Wt,$Mode,$Timeout,$PathValue)
                $env:PATH=$PathValue; $env:GH_MOCK_ROOT=$Root; $env:GH_MOCK_WT=$Wt; $env:GH_MOCK_CI_MODE=$Mode; $env:SCAFFOLD_CI_TIMEOUT_SEC=$Timeout
                $sw=[Diagnostics.Stopwatch]::StartNew(); $o=(& pwsh -NoProfile -File $Exe -TaskId T0-REMOTEMX -Phase ship 2>&1|Out-String);$x=$LASTEXITCODE;$sw.Stop()
                [pscustomobject]@{Out=$o;Exit=$x;Seconds=$sw.Elapsed.TotalSeconds}
              }
              $jobADone = Wait-Job $jobA -Timeout 90
              if (-not $jobADone) { Stop-Job $jobA; Remove-Job $jobA -Force; Fail "TD134-CIAPIFAIL/$($aCase.Tag): ship still running after 90s — the configured deadline is not containing the API call." }
              else {
                $rA = @(Receive-Job $jobA) | Select-Object -Last 1; Remove-Job $jobA -Force
                $apiCount = if (Test-Path (Join-Path $fxA.Root 'ci-check-count')) { [int]((Get-Content (Join-Path $fxA.Root 'ci-check-count') -Raw).Trim()) } else { 0 }
                if ($rA.Exit -eq 0) { Fail "TD134-CIAPIFAIL/$($aCase.Tag): unverifiable check-runs exited 0." }
                elseif (-not (Test-Path (Join-Path $fxA.Root 'ci-checked')) -or $apiCount -lt 1) { Fail "TD134-CIAPIFAIL/$($aCase.Tag): check-runs endpoint was not actually consumed (count=$apiCount)." }
                elseif ($rA.Seconds -gt $aCase.Max) { Fail "TD134-CIAPIFAIL/$($aCase.Tag): bounded failure took $([Math]::Round($rA.Seconds,2))s (> $($aCase.Max)s)." }
                elseif (Test-Path (Join-Path $fxA.Root 'merge-attempted')) { Fail "TD134-CIAPIFAIL/$($aCase.Tag): unverifiable CI reached merge." }
                elseif ($aCase.Mode -ceq 'apifail' -and "$($rA.Out)" -cnotmatch '\[CI-GATE-API\] checks: check_runs p1/0:') { Fail "TD134-CIAPIFAIL/malformed: rejection lost its endpoint/page API reason. tail=$($rA.Out.Substring([Math]::Max(0,$rA.Out.Length-700)))" }
                elseif ($aCase.Mode -ceq 'apihang') {
                  $hangStart = Join-Path $fxA.Root 'ci-api-hang-started'; $hangDone = Join-Path $fxA.Root 'ci-api-hang-completed'
                  $hangSec = if (Test-Path $hangStart) { ([DateTimeOffset]::UtcNow - [DateTimeOffset]::Parse("$(Get-Content $hangStart -Raw)".Trim())).TotalSeconds } else { 999 }
                  if ("$($rA.Out)" -cnotmatch '\[CI-GATE-TIMEOUT\] checks:') { Fail "TD134-CIAPIFAIL/hang: rejection was not the shared check deadline. tail=$($rA.Out.Substring([Math]::Max(0,$rA.Out.Length-700)))" }
                  elseif (-not (Test-Path $hangStart) -or (Test-Path $hangDone) -or $hangSec -gt 12) { Fail "TD134-CIAPIFAIL/hang: 3s deadline did not stop the real hanging endpoint (started=$(Test-Path $hangStart), completed=$(Test-Path $hangDone), elapsed=$([Math]::Round($hangSec,2))s)." }
                }
              }
            }
          }
          finally { $env:GH_MOCK_CI_MODE = ''; $env:SCAFFOLD_CI_TIMEOUT_SEC = ''; if ($fxA -and $fxA.Root) { Remove-Item -Recurse -Force $fxA.Root -ErrorAction SilentlyContinue } }
        }
        if (-not $fail) { Write-Host '  TD134-CIAPIFAIL malformed API fails immediately with endpoint/page reason; real hanging API obeys 3s shared deadline; both consumed and never merge OK' -ForegroundColor Green }
      }

      if (-not $fail) {
        $fxH = & $rmMake 'ciheadmove'
        try {
          if (-not $fxH.Ok) { Fail 'TD134-CIHEADMOVE setup: fixture start produced no worktree.' }
          else {
            & $rmReset $fxH.Root
            $env:GH_MOCK_WT = $fxH.Wt; $env:GH_MOCK_CI_MODE = 'headmove'
            & pwsh -NoProfile -File (Join-Path $fxH.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxH.Wt 'README.md') 'GREENMX head-move work' -Encoding utf8
            $sH = (& pwsh -NoProfile -File (Join-Path $fxH.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
            $sHExit = $LASTEXITCODE
            $hmQueries = if (Test-Path (Join-Path $fxH.Root 'headmove-count')) { [int]((Get-Content (Join-Path $fxH.Root 'headmove-count') -Raw).Trim()) } else { 0 }
            if ($sHExit -eq 0) { Fail 'TD134-CIHEADMOVE: PR head moved during the CI wait yet ship exits 0 — an unreviewed/unverified head would be merged.' }
            elseif ($hmQueries -lt 2) { Fail "TD134-CIHEADMOVE: head queried only $hmQueries time(s) — the post-wait head recheck never ran; the non-zero exit came from something else (assertion unfaithful)." }
            elseif ($sH -notmatch "'a{40}'") { $sHd = if ($sH.Length -gt 900) { $sH.Substring($sH.Length - 900) } else { $sH }; Fail "TD134-CIHEADMOVE: blocked but the error does not carry the moved head oid (the recheck throw is the only place that prints it — another guard fired instead). tail=$sHd" }
            elseif (Test-Path (Join-Path $fxH.Root 'merge-attempted')) { Fail 'TD134-CIHEADMOVE: head moved yet the merge leg was still reached.' }
            else { Write-Host '  TD134-CIHEADMOVE head moved during wait -> fail-closed (recheck ran, no merge) OK' -ForegroundColor Green }
          }
        }
        finally { $env:GH_MOCK_CI_MODE = ''; Remove-Item -Recurse -Force $fxH.Root -ErrorAction SilentlyContinue }
      }

      if (-not $fail) {
        $fxX = & $rmMake 'cimatrix'
        try {
          if (-not $fxX.Ok) { Fail 'TD134-CIMATRIX setup: fixture start produced no worktree.' }
          else {
            & $rmReset $fxX.Root
            # This is a positive end-to-end case, so leave enough budget for the contained multi-call chain.
            # Dedicated short-deadline cases above prove timeout behavior independently.
            $env:GH_MOCK_WT = $fxX.Wt; $env:GH_MOCK_CI_MODE = 'candidate-matrix'; $env:SCAFFOLD_CI_TIMEOUT_SEC = '120'
            & pwsh -NoProfile -File (Join-Path $fxX.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxX.Wt 'README.md') 'GREENMX matrix-edit work' -Encoding utf8
            # The PR itself renames a CI job on the HEAD side: verify -> verify-renamed in the worktree
            # ci.yml (in the fixture card's allow_paths). GitHub would create check runs from THIS yml, and
            # the mock models that (names derive from GH_MOCK_WT's copy). ADR 0007 moved the expected-set
            # source from the scaffold-selftest shard matrix to ci.yml's jobs; the property under test is
            # unchanged - derive from the merge candidate tree, never from the base checkout.
            $xYml = Join-Path $fxX.Wt '.github/workflows/ci.yml'
            # A valid rename also rewires the fan-in dependency; leaving needs:[verify] is a separate
            # negative contract case, not a successful candidate-tree rename.
            $xText = (Get-Content $xYml -Raw) -replace '(?m)^  verify:', '  verify-renamed:'
            $xText = $xText -replace '(?m)^    needs:\s*\[verify\][ \t]*\r?$', '    needs: [verify-renamed]'
            if ([regex]::Matches($xText, '(?m)^  verify-renamed:').Count -ne 1 -or
                [regex]::Matches($xText, '(?m)^    needs:\s*\[verify-renamed\][ \t]*\r?$').Count -ne 1 -or
                $xText -match '(?m)^  verify:|^    needs:\s*\[verify\]') {
              throw 'TD134-CIMATRIX setup: job/dependency rename did not produce the expected fixture.'
            }
            Set-Content $xYml $xText -Encoding utf8 -NoNewline
            $jobXExe = Join-Path $fxX.Repo 'scripts/task.ps1'
            $jobX = Start-Job -ScriptBlock { $o = (& pwsh -NoProfile -File $using:jobXExe -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String); [pscustomobject]@{ Out = $o; Exit = $LASTEXITCODE } }
            $jobXDone = Wait-Job $jobX -Timeout 150
            if (-not $jobXDone) { Stop-Job $jobX; Remove-Job $jobX -Force; Fail 'TD134-CIMATRIX: ship still running after 150s - the gate is dead-waiting (expected set not derived from the merge candidate tree, and the knob not honored either).' }
            else {
              $rX = Receive-Job $jobX; Remove-Job $jobX -Force
              $xCounts = @('ci-check-count','ci-workflow-count','ci-jobs-count') | ForEach-Object {
                $p = Join-Path $fxX.Root $_
                if (Test-Path $p) { [int]((Get-Content $p -Raw).Trim()) } else { 0 }
              }
              if ($rX.Exit -ne 0) { $sXd = if ($rX.Out.Length -gt 900) { $rX.Out.Substring($rX.Out.Length - 900) } else { $rX.Out }; Fail "TD134-CIMATRIX: PR that renames a ci.yml job fails to ship (exit $($rX.Exit)) - the fan-in contract is not read from the merge candidate tree (base-side names can never appear; T65 item 4 regression). tail=$sXd" }
              elseif (-not (Test-Path (Join-Path $fxX.Root 'ci-checked'))) { Fail 'TD134-CIMATRIX: ship succeeded without ever consuming the check-runs query — the CI gate was skipped, green is vacuous.' }
              elseif (@($xCounts | Where-Object { $_ -ne 2 }).Count -gt 0) { Fail "TD134-CIMATRIX: successful ship did not perform the initial and final checks/workflow/jobs reads (counts=$($xCounts -join '/'))." }
              elseif (-not (Test-Path (Join-Path $fxX.Root 'merge-reached'))) { Fail 'TD134-CIMATRIX: exit 0 but the mock merge was never reached — success is vacuous.' }
              else { Write-Host '  TD134-CIMATRIX job-renaming PR ships green (expected checks derived from the candidate tree) OK' -ForegroundColor Green }
            }
          }
        }
        finally { $env:GH_MOCK_CI_MODE = ''; $env:SCAFFOLD_CI_TIMEOUT_SEC = ''; Remove-Item -Recurse -Force $fxX.Root -ErrorAction SilentlyContinue }
      }

      # Scenario 4 = gate 15t: end-to-end fixture for the MANUAL recovery plane — completing an
      # already-pushed PR outside the ship pipeline (the documented "manual full-form recovery").
      # Why it exists: that path has the most privilege (it merges directly) and the fewest guardrails
      # (no ship pipeline), while CI has no scope gate (TD89 root cause) — so the scope step in the
      # recipe is the ONLY carrier of the scope gate on this plane. (The old 15q wording lock died in
      # the 0.30/0.31 subtraction batches; 15r locks the saga-report wording.) This
      # gate locks its BEHAVIOR (modeled step by step on docs/DEVOPS-WORKFLOW.md, incl. the T53
      # fail-closed bindings):
      #   negative: out-of-scope change => scope step [SCOPE-BLOCK] non-zero => chain stops there =>
      #             NO review/merge sentinel may appear (proves "no merge without passing scope").
      #   positive: all in scope => [SCOPE-PASS] => chain continues to -PostStatus => mock merge
      #             consumed (merge-reached present) — gives the negative case its discriminating power.
      if (-not $fail) {
        # The handoff text is executable API. Exercise the exact production AST statements that build it
        # with a Git-legal ref containing PowerShell metacharacters, then execute the emitted command with
        # a pwsh argument-capture stub. This isolates quoting from check-scope's intentionally narrower Base
        # grammar while proving one invocation, byte-faithful Base transport and no injected extra command.
        $taskSource4 = Join-Path $RepoRoot 'scripts/task.ps1'
        $taskText4 = [IO.File]::ReadAllText($taskSource4)
        $taskTokens4 = $null; $taskErrors4 = $null
        $taskAst4 = [Management.Automation.Language.Parser]::ParseInput($taskText4, [ref]$taskTokens4, [ref]$taskErrors4)
        $manualAssignAsts4 = @($taskAst4.FindAll({ param($n)
              $n -is [Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -ceq '$manualTaskArg'
            }, $true))
        $quoteProblem4 = ''
        if ($taskErrors4.Count -gt 0 -or $manualAssignAsts4.Count -ne 1 -or $manualAssignAsts4[0].Parent -isnot [Management.Automation.Language.StatementBlockAst]) {
          $quoteProblem4 = "生产接续命令 AST 不唯一/不可解析（parse=$($taskErrors4.Count), assignment=$($manualAssignAsts4.Count)）。"
        } else {
          $manualBlock4 = $manualAssignAsts4[0].Parent
          $resumeWrites4 = @($manualBlock4.Statements | Where-Object { $_.Extent.Text -match '\[SHIP-MANUAL-RESUME\]' })
          if ($resumeWrites4.Count -ne 1) { $quoteProblem4 = "生产接续输出语句不唯一（count=$($resumeWrites4.Count)）。" }
          else {
            $manualStatements4 = @($manualBlock4.Statements | Where-Object {
                $_.Extent.StartOffset -ge $manualAssignAsts4[0].Extent.StartOffset -and
                $_.Extent.EndOffset -le $resumeWrites4[0].Extent.EndOffset
              })
            $manualBuild4 = ($manualStatements4 | ForEach-Object { $_.Extent.Text }) -join "`n"
            if ($manualStatements4.Count -ne 6 -or $manualBuild4 -notmatch 'manualBaseArg' -or $manualBuild4 -notmatch 'if \(\$SkipRed\)' -or $manualBuild4 -match 'gh\s+pr\s+merge') {
              $quoteProblem4 = "生产接续命令 AST 片段形状不符（statements=$($manualStatements4.Count)）。"
            } else {
              $probeBase4 = 'resume'';pwd;#'
              $quoteOutput4 = (& {
                  param([string]$Fragment, [string]$ProbeBase)
                  $TaskId = 'T0-REMOTEMX'; $shipBase = $ProbeBase; $SkipRed = $true; $pr = 777; $ciHead = ('a' * 40)
                  & ([scriptblock]::Create($Fragment)) 6>&1
                } $manualBuild4 $probeBase4 | Out-String)
              $quotedProbeBase4 = "'" + $probeBase4.Replace("'", "''") + "'"
              $expectedProbeCmd4 = "pwsh -NoProfile -File scripts\task.ps1 -TaskId 'T0-REMOTEMX' -Phase ship -Base $quotedProbeBase4 -SkipRed"
              $probeMatches4 = [regex]::Matches($quoteOutput4, '(?m)^\s*\[SHIP-MANUAL-RESUME\]\s+(?<cmd>' + [regex]::Escape($expectedProbeCmd4) + ')\s*$')
              if ($probeMatches4.Count -ne 1) { $quoteProblem4 = "特殊 Base 输出未产生唯一、完整、安全引用的接续命令（count=$($probeMatches4.Count)）。" }
              else {
                $probeExec4 = & {
                  param([string]$Command)
                  $state = [pscustomobject]@{ Calls = 0; Args = @() }
                  function pwsh { $state.Calls = $state.Calls + 1; $state.Args = @($args) }
                  $unexpected = @(& ([scriptblock]::Create($Command)) 2>&1)
                  [pscustomobject]@{ Calls = $state.Calls; Args = @($state.Args); Unexpected = @($unexpected) }
                } $probeMatches4[0].Groups['cmd'].Value
                $expectedProbeArgs4 = @('-NoProfile','-File','scripts\task.ps1','-TaskId','T0-REMOTEMX','-Phase','ship','-Base',$probeBase4,'-SkipRed')
                $argDiff4 = @(Compare-Object -ReferenceObject $expectedProbeArgs4 -DifferenceObject @($probeExec4.Args) -SyncWindow 0 -CaseSensitive)
                if ($probeExec4.Calls -ne 1 -or $argDiff4.Count -gt 0 -or $probeExec4.Unexpected.Count -gt 0) {
                  $quoteProblem4 = "执行输出命令未保持单次 pwsh/完整 Base，或执行了额外命令（calls=$($probeExec4.Calls), args='$($probeExec4.Args -join '|')', unexpected=$($probeExec4.Unexpected.Count)）。"
                }
              }
            }
          }
        }
        if ($quoteProblem4) { Fail "闸15t protected-resume 参数引用：$quoteProblem4" }
        else { Write-Host '  闸15t protected-resume 特殊 Base 单次调用 + 参数保真 + 无额外命令 OK' -ForegroundColor Green }

        $fx4 = & $rmMake 'recovery'
        try {
          if (-not $fx4.Ok) { Fail '闸15t / T37-REMOTEMX/4 setup：恢复夹具 start 未产出 worktree。' }
          else {
            & $rmReset $fx4.Root
            $env:GH_MOCK_WT = $fx4.Wt
            # 让**本地 master 落后于 origin/master 一个提交**（先推、再 reset 回退本地）。
            # 为什么必须是「落后」而不是「领先」（codex R3 r3 #1）：三点 diff 由 merge-base 决定，本地领先时
            # `master...branch` 与 `origin/master...branch` 得到**同一份** feature 侧 diff ⇒ 加不加 -LocalBase 都一样、
            # 「远端基线」这条语义无从区分（原写法即如此，是 vacuous）。落后时 review.ps1 会打印
            # 「本地 'master' 落后 refs/remotes/origin/master N 个提交」——该提示**仅在 behindN>0 时**出现，
            # 故可作为「确实选了远端基线」的判据；一旦加 -LocalBase，baseRef 变成 refs/heads/master、behindN=0、提示消失。
            & git -C $fx4.Repo checkout -q master *> $null
            Set-Content (Join-Path $fx4.Repo 'origin-ahead.txt') 'T54：推到 origin/master 后本地回退，令本地 master 落后一个提交' -Encoding utf8
            & git -C $fx4.Repo add -A *> $null
            & git -C $fx4.Repo commit -q -m 'origin-ahead master commit' *> $null
            & git -C $fx4.Repo push -q origin master *> $null
            & git -C $fx4.Repo reset --hard HEAD~1 *> $null
            $manualBase4 = 'master'
            # Build the "already pushed + PR open" state: red phase -> green -> ship -NoAutoMerge. Its
            # machine-readable handoff is the only final-delivery command this recovery plane may execute.
            & pwsh -NoProfile -File (Join-Path $fx4.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fx4.Wt 'README.md') 'GREENMX recovery work' -Encoding utf8
            $ready4 = (& pwsh -NoProfile -File (Join-Path $fx4.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship -Base $manualBase4 -SkipRed -NoAutoMerge 2>&1 | Out-String)
            $ready4Exit = $LASTEXITCODE
            $prCreated4 = Test-Path (Join-Path $fx4.Root 'pr-created')
            $quotedBase4 = "'" + $manualBase4.Replace("'", "''") + "'"
            $wantResume4 = "pwsh -NoProfile -File scripts\task.ps1 -TaskId 'T0-REMOTEMX' -Phase ship -Base $quotedBase4 -SkipRed"
            $resumeMatches4 = [regex]::Matches($ready4, '(?m)^\s*\[SHIP-MANUAL-RESUME\]\s+(?<cmd>' + [regex]::Escape($wantResume4) + ')\s*$')
            $manualResume4 = if ($resumeMatches4.Count -eq 1) { $resumeMatches4[0].Groups['cmd'].Value } else { '' }
            if ($ready4Exit -ne 0) { Fail "闸15t setup：ship -NoAutoMerge 未形成可接续状态（exit=$ready4Exit）。尾段=$($ready4.Substring([Math]::Max(0,$ready4.Length-700)))" }
            elseif (-not $prCreated4) { Fail '闸15t setup：ship -NoAutoMerge 未开出 PR（pr-created 哨兵缺）——恢复场景的前提（已 push + PR 已开）没构造出来，后续断言失真。' }
            elseif (-not $manualResume4) { Fail "闸15t setup：-NoAutoMerge 没有且仅有一条安全引用的 [SHIP-MANUAL-RESUME] 接续命令，或未保留 -Base/-SkipRed、未移除 -NoAutoMerge。匹配数=$($resumeMatches4.Count)；输出尾段=$($ready4.Substring([Math]::Max(0,$ready4.Length-700)))" }
            else {
                # 恢复配方的**可执行建模**：范围步非零即中止，绿才续跑 -PostStatus → 合并。
                # 与 DEVOPS-WORKFLOW 那段一一对应；本闸测的正是这条控制流，不是各闸自身（各闸另有夹具）。
                # 恢复配方的**完整**可执行建模——逐条对应 docs/DEVOPS-WORKFLOW.md「任何已 push 状态的手工恢复」：
                # fetch(查码) → PR baseRefName 核 → 取 head/base OID → DoD → verify → **范围闸**（主检出那份 +
                # -Path 指被审树 + -ExpectTip/-ExpectBase，远端模式）→ 许可 → 防泄露 → review -PostStatus -PrNumber
                # → 最终执行 -NoAutoMerge 实际打印的 protected ship 接续命令；精确 CI 身份与合并均由共享路径完成。
                # **任一步非零即中止**（PowerShell 原生命令非零不自动中断，故每步都显式查）——这正是本闸要证的控制流。
                $recover4 = {
                  param($fx, [string]$CiMode = '')
                  # **有序腿轨迹**：每步跑之前把腿名追加进 $script:r4Trace。断言比对的是整条轨迹，
                  # 故删掉/跳过任何一条腿都会让轨迹不等而变红——只断言最终结局的话，中间腿全无覆盖（codex R3 r2 #1）。
                  # **逐腿分别留存输出**：只攒一份聚合输出的话，「范围步是否印了 [SCOPE-BLOCK]」这种断言会被
                  # **别的腿**的输出满足（codex R3 r5：聚合搜索 ⇒ 断言面宽于契约，同 L165 那一族）。
                  $step = { param($name, $sb) if ($script:r4Stop) { return }; $script:r4Trace += $name; $o = (& $sb 2>&1 | Out-String); $script:r4Out += $o; $script:r4LegOut[$name] = $o; if ($LASTEXITCODE -ne 0) { $script:r4Stop = $name } }
                  # 这两个由腿内赋值、腿外读取：**必须预初始化**。否则某条腿被删/跳过时，外面那句读取会因
                  # StrictMode「变量未定义」直接抛异常、整段中止——红是红了，却红在异常而非有序轨迹断言上
                  # （变异实测：删 pr-base / pr-head 两腿即如此，判据分类器把它们标为「存疑」而非 OK）。
                  # A leg signals failure with `& pwsh -NoProfile -Command 'exit 1'` to set $LASTEXITCODE.
                  # The Windows-only shell must NOT be used here: on ubuntu it raises CommandNotFound and
                  # never SETS $LASTEXITCODE, so the `$LASTEXITCODE -ne 0` test above reads the previous
                  # command's 0 and scores the leg as PASSED - fail-open on exactly the assertion whose job
                  # is to halt the recipe. The positive example never reaches these branches, so both
                  # platforms stay green and the defect only surfaces when a real regression needs catching.
                  $script:r4PrBase = ''; $script:r4Head = ''
                  $script:r4Stop = $null; $script:r4Out = ''; $script:r4Trace = @(); $script:r4LegOut = @{}
                  $env:GH_MOCK_CI_MODE = $CiMode
                  # ① fetch 两侧（退出码必查：失败即拿陈旧 origin/* 判，连 allow_paths 都取自旧卡）
                  & $step 'fetch' { & git -C $fx.Wt fetch origin $manualBase4 T0-REMOTEMX }
                  # ② PR 的 baseRefName 须 == 本次判定的 base（retarget 会「按 A 判往 B 合」）
                  $prBase = ''
                  & $step 'pr-base' { $s = (& gh pr view 777 --json baseRefName --jq .baseRefName); $script:r4PrBase = "$s".Trim(); if ($script:r4PrBase -cne $manualBase4) { & pwsh -NoProfile -Command 'exit 1' } }
                  $prBase = $script:r4PrBase
                  # ③ head **取自 PR 元数据**（不是 check-scope 会自己解析的那个 ref——同源自比即恒等式，r2 #1）；
                  #    base 取远端跟踪引用（= 将被合并进的那个提交）。
                  $headOid = ''
                  & $step 'pr-head' { $s = (& gh pr view 777 --json headRefOid --jq .headRefOid); $script:r4Head = "$s".Trim(); if ($script:r4Head -notmatch '^[0-9a-f]{40}$') { & pwsh -NoProfile -Command 'exit 1' } }
                  $headOid = $script:r4Head
                  $manualBaseRef4 = "refs/remotes/origin/$manualBase4"
                  $baseOid = "$(& git -C $fx.Wt rev-parse $manualBaseRef4 2>$null)".Trim()
                  # ④ DoD（卡上原命令，在被审工作树里跑）
                  & $step 'dod' { Push-Location $fx.Wt; try { & pwsh -NoProfile -Command 'if (-not (Select-String -Path README.md -Pattern GREENMX -Quiet)) { exit 1 }' } finally { Pop-Location } }
                  # ⑤ verify 总闸
                  & $step 'verify' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/verify.ps1') }
                  # ⑥ **范围闸**——跑受信主检出那份、-Path 指被审树、两侧 OID 都钉进去（远端模式，不加 -Local）
                  & $step 'scope' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/check-scope.ps1') -TaskId T0-REMOTEMX -Base $manualBase4 -Path $fx.Wt -ExpectTip $headOid -ExpectBase $baseOid }
                  # ⑦ 许可闸 ⑧ 防泄露闸
                  # ⑧b 预算闸（T233/TD235）：配方的第 3.5 步。**按打印的状态判，不按退出码**——check-budget 的
                  #    exit 1 同时表示 trip 与 over，而配方只在 OVER 时停（trip 是「趁拆还便宜时记个决定」的提示）。
                  #    照抄退出码就会把 trip 当 block，那正是文档里点名的读法错误。故显式收尾 exit 0/1：不这样做的话
                  #    check-budget 留下的 1 会被 $step 读成本腿失败。夹具卡不声明 budget:，故正例走 no-budget 分支。
                  & $step 'budget' { $b4 = (& pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/check-budget.ps1') -TaskId T0-REMOTEMX -Base $manualBase4 -Path $fx.Wt 2>&1 | Out-String); $b4; if ($b4 -match 'OVER') { & pwsh -NoProfile -Command 'exit 1' } else { & pwsh -NoProfile -Command 'exit 0' } }
                  & $step 'license' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/check-licenses.ps1') }
                  & $step 'secrets' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/check-secrets.ps1') }
                  # Final delivery re-enters the production ship path by executing the exact command printed
                  # by -NoAutoMerge. It reruns R3, exact CI identity, final base/head/OID snapshots and merge.
                  & $step 'ship-resume' { Push-Location $fx.Repo; try { & ([scriptblock]::Create($manualResume4)) } finally { Pop-Location } }
                  $readCount = { param($Name) $p = Join-Path $fx.Root $Name; if (Test-Path $p) { [int]((Get-Content $p -Raw).Trim()) } else { 0 } }
                  return [pscustomobject]@{ Out = $script:r4Out; LegOut = $script:r4LegOut; StoppedAt = $script:r4Stop; Head = $headOid; Base = $baseOid; PrBase = $prBase; Trace = @($script:r4Trace)
                    Checks = (& $readCount 'ci-check-count'); Workflows = (& $readCount 'ci-workflow-count'); Jobs = (& $readCount 'ci-jobs-count') }
                }
                # 三枚「腿被消费」哨兵：评审 / 状态回贴 / 合并。负例须**三枚全缺**——只看 merge 不够，
                # 评审若已在被拦的路径上跑过，就说明控制流没有真的在范围步止住（codex R3 r1 #3）。
                # 配方的**完整有序腿清单**：负例须恰好走到 scope 为止，正例须一条不落地走完。
                $legsAll4 = @('fetch', 'pr-base', 'pr-head', 'dod', 'verify', 'scope', 'budget', 'license', 'secrets', 'ship-resume')
                $legsNeg4 = @('fetch', 'pr-base', 'pr-head', 'dod', 'verify', 'scope')
                # `merge-attempted` 必须在列：stub 一被调用就写它，而 `merge-reached` 要等参数校验通过且成功才写。
                # 负例说的是「合并腿**一次都没被调用**」，那就得断言 attempted 缺——只断言 reached 缺会放过
                # 「调用了但因参数不符而失败」的情形（codex R3 r3 #3）。
                $sent4 = @('review-invoked', 'status-posted', 'pr-commented', 'ci-checked', 'ci-workflow-checked', 'ci-jobs-consumed',
                  'ci-check-count', 'ci-workflow-count', 'ci-jobs-count', 'merge-attempted', 'merge-reached')
                $clearSent4 = { foreach ($s in $sent4) { Remove-Item (Join-Path $fx4.Root $s) -ErrorAction SilentlyContinue } }
                # 本场景自用的单次调用器（15s 的 $ssRun* 属另一闸的作用域，勿跨用）。
                $run4 = { param($Exe, $A) $o = (& pwsh -NoProfile -File $Exe @A 2>&1 | Out-String); return [pscustomobject]@{ Out = $o; Exit = $LASTEXITCODE } }
                $hitSent4 = { @($sent4 | Where-Object { Test-Path (Join-Path $fx4.Root $_) }) }
                # ── 负例：种卡外文件（allow_paths = README.md/extra.txt ⇒ oob.md 越界）、提交并**推到 origin**。
                #    必须真 push：本卡测的是「**已 push** 状态」的恢复平面，只在本地提交的话远端仍停在旧 sha，
                #    远端模式的检查器根本看不到这个越界改动（codex R3 r1 #1 实测）。
                Set-Content (Join-Path $fx4.Wt 'oob.md') 'T54 负例：卡外改动，恢复序列的范围步必须拦下' -Encoding utf8
                & git -C $fx4.Wt add -A *> $null
                & git -C $fx4.Wt commit -q -m 'oob change' *> $null
                & git -C $fx4.Wt push -q origin T0-REMOTEMX *> $null
                & $clearSent4
                $neg4 = & $recover4 $fx4
                # @() 包裹**调用点**：scriptblock 返回单元素时 `&` 会解包成标量，StrictMode 下取 .Count 即抛。
                $negHit4 = @(& $hitSent4)
                if (($neg4.Trace -join '>') -ne ($legsNeg4 -join '>')) { Fail "闸15t 负例：腿轨迹与配方不符——实际 [$($neg4.Trace -join '>')]，期望 [$($legsNeg4 -join '>')]。删掉/跳过任一前置腿（fetch/PR base/head/DoD/verify）都会命中这条：只断言最终结局的话那些腿零覆盖。" }
                elseif ($neg4.StoppedAt -ne 'scope') { Fail "闸15t 负例：恢复序列没有停在**范围步**（实际停在 '$($neg4.StoppedAt)'；`$null=一路走到底）——最后手段平面上越界可直达合并，或红在了别的面上（断言失真）。`n输出=$($neg4.Out)" }
                elseif ("$($neg4.LegOut['scope'])" -notmatch '\[SCOPE-BLOCK\]') { Fail "闸15t 负例：停在范围步但**范围步自己的输出**没印 [SCOPE-BLOCK] 哨兵——可能是不可判分支而非越界判定（只搜聚合输出会被别的腿满足，故此处只看该腿）。`n范围步输出=$($neg4.LegOut['scope'])" }
                elseif ($negHit4.Count -gt 0) { Fail "闸15t 负例：范围闸 BLOCK 了，但下游腿仍被消费（哨兵在场：$($negHit4 -join ', ')）——「不过范围闸就到不了评审/回贴/合并」不成立。" }
                else {
                  # ── 正例：反向提交撤出卡外文件（禁改写历史——T36-DOCTRINE）并推上去，同一序列须**全程走通** ──
                  Remove-Item (Join-Path $fx4.Wt 'oob.md') -Force
                  # T233: one NON-markdown path, so the review leg is genuinely load-bearing. This diff is
                  # otherwise README.md alone, which the real ReviewSkipWhen predicate (AllPathsMatch
                  # '\.md$') routes around - review.ps1 then writes a pass verdict, posts status, and never
                  # asks the reviewer, so `review-invoked` is absent and the positive case proves less than
                  # it claims. It was masked until now because this fixture REPLACED _guard.ps1, deleting
                  # the route selector, so every diff reached the reviewer by accident. `extra.txt` is
                  # already in the card's allow_paths, so the scope step is unaffected.
                  Set-Content (Join-Path $fx4.Wt 'extra.txt') 'T233: a non-markdown path, so ReviewSkipWhen does not route this diff around the reviewer' -Encoding utf8
                  & git -C $fx4.Wt add -A *> $null
                  & git -C $fx4.Wt commit -q -m 'revert oob (反向提交撤出卡外改动)' *> $null
                  & git -C $fx4.Wt push -q origin T0-REMOTEMX *> $null
                  # The exact command printed by -NoAutoMerge must remain safe when the remote state changes
                  # before the later invocation. Each control executes THAT captured command, not a parallel
                  # hand-written merge recipe: duplicate run, wrong PR association, replaced run attempt,
                  # and duplicate job context all stop inside the shared ship CI verifier before merge.
                  $handoffProblem4 = $null
                  foreach ($hc in @(
                      @{ M = 'workflow-paged'; S = '\[CI-GATE-WORKFLOW-AMBIGUOUS\]'; C = 1; W = 2; J = 0 }
                      @{ M = 'wfid-pr-other'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0 }
                      @{ M = 'wfid-final-attempt'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 2; W = 2; J = 1 }
                      @{ M = 'jobs-duplicate'; S = '\[CI-GATE-JOBS-DRIFT\]'; C = 1; W = 1; J = 1 })) {
                    & $clearSent4
                    $blocked4 = & $recover4 $fx4 $hc.M
                    if ($blocked4.StoppedAt -ne 'ship-resume' -or "$($blocked4.LegOut['ship-resume'])" -notmatch $hc.S) {
                      $handoffProblem4 = "$($hc.M)：接续未在共享 CI 身份闸以 $($hc.S) 拒绝（stopped=$($blocked4.StoppedAt)）。尾段=$($blocked4.Out.Substring([Math]::Max(0,$blocked4.Out.Length-700)))"; break
                    }
                    if (($blocked4.Checks -ne $hc.C) -or ($blocked4.Workflows -ne $hc.W) -or ($blocked4.Jobs -ne $hc.J)) {
                      $handoffProblem4 = "$($hc.M)：端点读取计数 $($blocked4.Checks)/$($blocked4.Workflows)/$($blocked4.Jobs) != $($hc.C)/$($hc.W)/$($hc.J)，拒绝点不可信。"; break
                    }
                    if (-not (Test-Path (Join-Path $fx4.Root 'review-invoked')) -or -not (Test-Path (Join-Path $fx4.Root 'status-posted'))) {
                      $handoffProblem4 = "$($hc.M)：接续未真实重跑 R3/状态回贴，可能没有进入共享 ship 路径。"; break
                    }
                    if (Test-Path (Join-Path $fx4.Root 'merge-attempted')) { $handoffProblem4 = "$($hc.M)：身份不符后仍触达 merge。"; break }
                  }
                  if ($handoffProblem4) { Fail "闸15t protected-resume 负例：$handoffProblem4" }
                  else {
                    & $clearSent4
                    $pos4 = & $recover4 $fx4
                    $posMiss4 = @($sent4 | Where-Object { -not (Test-Path (Join-Path $fx4.Root $_)) })
                    if ($pos4.StoppedAt) { Fail "闸15t 正例：全部改动都在 allow_paths 内时恢复序列仍在 '$($pos4.StoppedAt)' 步中止——该序列走不通，负例的红遂失去鉴别力（可能只是序列本身坏了）。`n输出=$($pos4.Out)" }
                  elseif (($pos4.Trace -join '>') -ne ($legsAll4 -join '>')) { Fail "闸15t 正例：腿轨迹与配方不符——实际 [$($pos4.Trace -join '>')]，期望 [$($legsAll4 -join '>')]。删掉任一腿（fetch/PR base 两次/head/DoD/verify/范围/预算/许可/密钥/评审/基线 OID 复核/合并前 CI 检查/合并）都会命中这条。" }
                  elseif (($pos4.Checks -ne 2) -or ($pos4.Workflows -ne 2) -or ($pos4.Jobs -ne 2)) { Fail "闸15t 正例：protected resume 未完成共享 CI 初读+终读 2/2/2（实际 $($pos4.Checks)/$($pos4.Workflows)/$($pos4.Jobs)）。" }
                  elseif ((Get-Content (Join-Path $fx4.Root 'merge-head-arg') -Raw -ErrorAction SilentlyContinue).Trim() -ne $pos4.Head) { Fail "闸15t 正例：`gh pr merge` 的 --match-head-commit 实参与 PR head 不符（实参=$((Get-Content (Join-Path $fx4.Root 'merge-head-arg') -Raw -ErrorAction SilentlyContinue))，head=$($pos4.Head)）——「合并绑 head」只是文案、没真绑。" }
                  # 评审腿确实走了**远端基线**：本地 master 已被造成落后 1 个提交，review.ps1 遂打印「落后 … refs/remotes/origin/master」
                  # 提示（仅 behindN>0 时出现）。加 -LocalBase 会让 baseRef 变本地、behindN=0、提示消失 ⇒ 本断言即红（codex R3 r3 #1）。
                  # 远端基线判据：只看**评审腿自己**的输出里有没有 `refs/remotes/origin/master` 这个**稳定 ASCII 串**。
                  # 两点都要紧：① 必须**按腿**看——范围步也印这个串（`基线 = …`），搜聚合输出会恒真（变异 D 首轮即因此存活）；
                  # ② 判据必须是 ASCII，不能拿中文提示当锚（本卡自己的纪律就是「机检认 ASCII、本地化文案只给人读」，
                  # 上一版拿「落后」做判据是自相矛盾，codex R3 r5 指出）。
                  # 加回 -LocalBase 时 baseRef 变 refs/heads/master、behindN=0、该提示不印 ⇒ 评审腿输出里就没有这个串。
                  elseif ("$($pos4.LegOut['ship-resume'])" -notmatch [regex]::Escape("refs/remotes/origin/$manualBase4")) { Fail "闸15t 正例：protected resume 输出里没有特殊远端基线 ref——说明共享 ship 的评审没走被绑定的远端基线。`n接续输出=$($pos4.LegOut['ship-resume'])" }
                  elseif ("$($pos4.LegOut['scope'])" -notmatch '\[SCOPE-PASS\]') { Fail "闸15t 正例：**范围步自己的输出**未印 [SCOPE-PASS]——判定结论未被打印（只看聚合输出会被别的腿满足）。`n范围步输出=$($pos4.LegOut['scope'])" }
                  elseif ($posMiss4.Count -gt 0) { Fail "闸15t 正例：序列走通却有腿没被消费（哨兵缺：$($posMiss4 -join ', ')）——正例没真正覆盖到「范围过 → 评审+回贴 → 合并」全段。`n输出=$($pos4.Out)" }
                  else {
                    # 两枚**绑定承重性**用例（不属恢复链，单独跑；codex R3 r3 #2）：只记录 'scope' 标签证明不了
                    # -ExpectTip/-ExpectBase 真在起作用——把它们摘掉或改走 -Local，正/负例照样得到 BLOCK/PASS。
                    # 故直接喂**不符的 OID**，要求以 [SCOPE-TIPMISMATCH] 失败：该哨兵只有绑定生效时才可能出现。
                    # 不符值必须是**本仓可解析、但不是目标**的真实 OID（tip 侧喂 base 的、base 侧喂 head 的），
                    # 另一侧保持正确。喂 `000…001` 那种解析不出的串只会停在「OID 解析失败」那一支，**根本走不到**
                    # `$full -ne $ActualSha` 身份比对——把身份比对整句删掉也照样绿（codex R3 r4；15s 的 n2/n8 早已按
                    # 此法写，本卡新加的 pin 用例却没沿用）。故另断言文案含 `judged=`，证明拦它的确是身份比对那一支。
                    $csExe4 = Join-Path $fx4.Repo 'scripts/check-scope.ps1'
                    $pinTip4 = & $run4 $csExe4 @('-TaskId', 'T0-REMOTEMX', '-Base', $manualBase4, '-Path', $fx4.Wt, '-ExpectTip', $pos4.Base, '-ExpectBase', $pos4.Base)
                    $pinBase4 = & $run4 $csExe4 @('-TaskId', 'T0-REMOTEMX', '-Base', $manualBase4, '-Path', $fx4.Wt, '-ExpectTip', $pos4.Head, '-ExpectBase', $pos4.Head)
                    if ($pinTip4.Exit -eq 0 -or $pinTip4.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15t(pin/tip)：喂入**可解析但不符**的 -ExpectTip（基线 OID）仍未以 [SCOPE-TIPMISMATCH] 失败（exit=$($pinTip4.Exit)）——该绑定参数不承重。`n输出=$($pinTip4.Out)" }
                    elseif ($pinTip4.Out -notmatch [regex]::Escape('judged=')) { Fail "闸15t(pin/tip)：失败文案里没有 judged=/expect= 两个 OID——说明拦它的是「OID 解析失败」那一支，而非**提交身份比对**；删掉身份比对整句本用例仍会绿（vacuous）。`n输出=$($pinTip4.Out)" }
                    elseif ($pinBase4.Exit -eq 0 -or $pinBase4.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15t(pin/base)：喂入**可解析但不符**的 -ExpectBase（尖端 OID）仍未以 [SCOPE-TIPMISMATCH] 失败（exit=$($pinBase4.Exit)）——基线那一侧的绑定不承重。`n输出=$($pinBase4.Out)" }
                    elseif ($pinBase4.Out -notmatch [regex]::Escape('judged=')) { Fail "闸15t(pin/base)：失败文案里没有 judged=/expect= 两个 OID——拦它的是解析失败那一支而非身份比对（vacuous）。`n输出=$($pinBase4.Out)" }
                    else { Write-Host '  闸15t / T37-REMOTEMX/4 manual diagnostics + protected ship resume OK（输出命令保留 Base/SkipRed、移除 NoAutoMerge；4 类身份漂移均不到 merge；正例共享 CI 2/2/2 + exact-head merge；既有 scope/pin 约束保留）' -ForegroundColor Green }
                  }
                  }
                }
            }
          }
        }
        finally { Remove-Item -Recurse -Force $fx4.Root -ErrorAction SilentlyContinue }
      }
    }
    finally {
      $env:PATH = $rmSavedPath; $env:GH_MOCK_ROOT = $rmSavedRoot; $env:GH_MOCK_WT = $rmSavedWt; $env:GH_MOCK_MERGE_FAIL = $rmSavedMergeFail
      $env:GH_MOCK_BASE_MODE = $rmSavedBaseMode; $env:GH_MOCK_MERGE_STATE = $rmSavedMergeState
      $env:GH_MOCK_CI_MODE = $rmSavedCiMode; $env:SCAFFOLD_CI_TIMEOUT_SEC = $rmSavedCiTimeout
      $env:SCAFFOLD_CI_CONTAINMENT_FAULT = $rmSavedContainFault; $env:GH_MOCK_SLOW_MS = $rmSavedSlowMs
      $env:GH_MOCK_REAL_GIT = $rmSavedRealGit
      foreach ($rr in $script:rmRoots) { Remove-Item -Recurse -Force $rr -ErrorAction SilentlyContinue }
    }
  }
}

}

if (Test-SeedRegionSelected 'ac') {
# T279: the meta guard sits INSIDE the region guard and above the receipt, deliberately. The receipt is
# execution evidence for a body that ran; a skipped meta site did not run, so filing one would be a lie and
# would red 17ad below - which is itself a meta site, so on a run without -IncludeMeta neither speaks and on
# a run with it both do. `-Only 17ac` therefore needs the switch to exercise the runner seeds.
$metaRun = Test-MetaSelected "17ac"
if ($metaRun) {
Add-SeedRegionReceipt 'ac@17ac'   # T194: execution evidence, filed from inside the guarded body
# 17ac. 变异 runner mutate.ps1 种子缺陷（T63/TD119）：全 hermetic——stub 闸命令经 -RunCommand 注入、
#    不跑真 selftest，秒级。Cases a-s (with sub-variants): (a) detection + evidence column (b) survivor
#    (c) bad evidence (d) anchor miss = zero runs + single-line anchor + EOF-line mutability (e) reuse
#    (f) stale .mutbak identity-verified restore + divergent-state double-keep (g) cache-key mismatch retest
#    (criteria/template/serialization-collision) (h) -Only selection validation (i) positive evidence required
#    (j) ASCII evidence + regex precompile (k) gate-token injection rejection (named payload, zero collateral)
#    (l) confinement rejection (../ traversal / absolute path / guarded confinement / results alias by
#    path-string and NTFS file identity) (m) registry shape (dup id / parse fail / non-hashtable / empty id)
#    (n) dirty-baseline guard (needs git) (o) results schema (tracked + header match + RESET on old header)
#    (p) pristine control group red = refuse (q) orphan results row dropped with notice (TD135)
#    (r) unknown registry key rejected by name (TD133 item 3) (s) malformed results row discarded, never
#    reused (TD133 item 5). Cases run a-w: labels a-u were already taken when (v) was added, and the
#    list above said a-s since before (t) and (u) landed, so project the taken set from the file, never
#    from this comment (L264). (v) owner-stamped .mutbak refused while its owner is ALIVE, and the same
#    state still self-healed once that owner is dead (T269/TD271). (w) a survivor produced by a probe
#    that announced it SKIPPED meta sub-gates is named as such rather than banked as a bare survivor,
#    with four near-miss negatives held as their own arms - including w5, the PROSE shape these very
#    arms print, which an unanchored match read as an announcement (T294/TD279).
#    挂 T62 的 -Only 机制（'17ac' 单列 token）；runner 的绿不是验收，本闸只证它对已知坏输入 fail-closed。
$acRoot = Join-Path ([System.IO.Path]::GetTempPath()) "mutate-seed-$PID"
if (Test-Path $acRoot) { Remove-Item -Recurse -Force $acRoot }
New-Item -ItemType Directory -Force $acRoot | Out-Null
try {
  $mutatePath = Join-Path $RepoRoot 'scripts/mutate.ps1'
  $acPristine = "line-one`r`nGUARD-LINE-ALPHA`r`nline-three"
  $mkAcCase = {
    param([string]$name, [string]$stubBody)
    $d = Join-Path $acRoot $name
    New-Item -ItemType Directory -Force $d | Out-Null
    Set-Content (Join-Path $d 'guarded.txt') $acPristine -Encoding utf8
    Set-Content (Join-Path $d 'stubgate.ps1') $stubBody -Encoding utf8
    $d
  }
  # 检出型 stub：guarded.txt 缺守卫行 ⇒ exit 1 + 专属锚；在场 ⇒ exit 0。每次实跑记痕（供计数各案数实跑次数；
  # 注意 r3 起 runner 每批还有一次未变异控制组探针——非沿用批的 runs.log 增量恒为 2（控制组+变异体））。
  $acDetectStub = @'
param([string]$Gate)
$g = Get-Content (Join-Path $PSScriptRoot 'guarded.txt') -Raw
Add-Content (Join-Path $PSScriptRoot 'runs.log') "run $Gate"
if ($g -notmatch 'GUARD-LINE-ALPHA') { Write-Output 'STUB-CAUGHT-MISSING-GUARD'; exit 1 }
Write-Output 'STUB-GUARD-PRESENT'; exit 0
'@
  $acGreenStub = @'
param([string]$Gate)
Write-Output 'STUB-ALWAYS-GREEN'; exit 0
'@
  # 错证型 stub 须**控制组绿**（r3 起未变异探针先行）：守卫在场绿、缺失时红但吐**错误**文本。
  $acWrongStub = @'
param([string]$Gate)
$g = Get-Content (Join-Path $PSScriptRoot 'guarded.txt') -Raw
if ($g -notmatch 'GUARD-LINE-ALPHA') { Write-Output 'STUB-WRONG-TEXT'; exit 1 }
Write-Output 'STUB-GUARD-PRESENT'; exit 0
'@
  $acRedStub = @'
param([string]$Gate)
Write-Output 'STUB-ALWAYS-RED'; exit 1
'@
  # 登记表生成：target 一律 **Root 相对**（'guarded.txt'），runner 侧配 -Root 圈禁。
  $mkAcReg = {
    param([string]$dir, [string]$anchor, [string]$extra)
    $rp = Join-Path $dir 'reg.psd1'
    Set-Content $rp ("@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='$anchor'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD')$extra } ) }") -Encoding utf8
    $rp
  }
  $mkAcTpl = { param([string]$dir) 'pwsh -NoProfile -File "{0}" {{gate}}' -f (Join-Path $dir 'stubgate.ps1') }

  # (a) 检出：守卫行被删 → stub 抓到（非零+锚）→ [MUT-OK] · runner exit 0 · guarded.txt 字节复原 · 结果行含 evidence 列。
  $dA = & $mkAcCase 'a' $acDetectStub
  $regA = & $mkAcReg $dA 'GUARD-LINE-ALPHA' ''
  $shaA0 = (Get-FileHash (Join-Path $dA 'guarded.txt') -Algorithm SHA256).Hash
  $oA = & pwsh -NoProfile -File $mutatePath -Registry $regA -Root $dA -RunCommand (& $mkAcTpl $dA) 2>&1 | Out-String
  $eA = $LASTEXITCODE
  $tailA = ($oA -split "`n" | Select-Object -Last 4) -join ' | '
  $tsvA = Join-Path $dA 'reg-results.tsv'
  if ($eA -ne 0 -or $oA -notmatch '\[MUT-OK\] A1') { Fail "17ac(a)：检出案未记 [MUT-OK]（exit=$eA）——runner 把「守卫真会拦」判错。输出尾：$tailA" }
  elseif ((Get-FileHash (Join-Path $dA 'guarded.txt') -Algorithm SHA256).Hash -ne $shaA0) { Fail '17ac(a)：探针毕 guarded.txt 未按字节复原（L178）。' }
  elseif (-not (Test-Path $tsvA)) { Fail '17ac(a)：结果 TSV 未落盘（记账不再 tracked 的回归）。' }
  elseif ((Get-Content $tsvA -TotalCount 1) -ne "id`tverdict`texit`tseconds`tevidence`tcacheKey`tat") { Fail "17ac(a)：结果 TSV 列头不符契约（R3 r1 #6 要求 evidence 列在场）。实得：$(Get-Content $tsvA -TotalCount 1)" }
  elseif (-not ((Get-Content $tsvA | Select-Object -Skip 1 | Select-Object -First 1) -match 'found:STUB-CAUGHT-MISSING-GUARD')) { Fail '17ac(a)：结果行 evidence 列未记具名命中锚（R3 r1 #6——tracked 工件须能回答「凭什么算 OK」）。' }
  else { Write-Host '  17ac(a) 检出案 [MUT-OK] + 字节复原 + 结果行含具名证据 OK' -ForegroundColor Green }

  # (b) 存活：恒绿 stub → 控制组过（绿）、变异后仍绿 → [MUT-SURVIVED] 且 runner 非零（fail-closed）。
  $dB = & $mkAcCase 'b' $acGreenStub
  $regB = & $mkAcReg $dB 'GUARD-LINE-ALPHA' ''
  $oB = & pwsh -NoProfile -File $mutatePath -Registry $regB -Root $dB -RunCommand (& $mkAcTpl $dB) 2>&1 | Out-String
  $eB = $LASTEXITCODE
  if ($eB -eq 0 -or $oB -notmatch '\[MUT-SURVIVED\] A1') { Fail "17ac(b)：守卫死了（探针恒绿）却没被 [MUT-SURVIVED]+非零拦下（exit=$eB）——vacuous 证据会被当有效。" }
  else { Write-Host '  17ac(b) 存活案 fail-closed OK' -ForegroundColor Green }

  # (c) 错证：控制组绿、变异后非零但证据文本不符 → [MUT-BAD-EVIDENCE] 且非零（L167「且命中指定文本」那半真被执行）。
  $dC = & $mkAcCase 'c' $acWrongStub
  $regC = & $mkAcReg $dC 'GUARD-LINE-ALPHA' ''
  $oC = & pwsh -NoProfile -File $mutatePath -Registry $regC -Root $dC -RunCommand (& $mkAcTpl $dC) 2>&1 | Out-String
  $eC = $LASTEXITCODE
  if ($eC -eq 0 -or $oC -notmatch '\[MUT-BAD-EVIDENCE\] A1') { Fail "17ac(c)：红错地方（非零但证据不符）没被 [MUT-BAD-EVIDENCE]+非零拦下（exit=$eC）——L167 分类器那半失守。" }
  else { Write-Host '  17ac(c) 错证案 L167 分类 OK' -ForegroundColor Green }

  # (d) 锚失：登记锚不命中 → [MUT-ANCHOR-MISS] 且非零 · **变异体零实跑**（控制组那一次除外）· 无 .mutbak 残留。
  $dD = & $mkAcCase 'd' $acDetectStub
  $regD = & $mkAcReg $dD 'NO-SUCH-LINE-T63' ''
  $oD = & pwsh -NoProfile -File $mutatePath -Registry $regD -Root $dD -RunCommand (& $mkAcTpl $dD) 2>&1 | Out-String
  $eD = $LASTEXITCODE
  $runsD = if (Test-Path (Join-Path $dD 'runs.log')) { @(Get-Content (Join-Path $dD 'runs.log')).Count } else { 0 }
  if ($eD -eq 0 -or $oD -notmatch '\[MUT-ANCHOR-MISS\] A1') { Fail "17ac(d)：锚不命中未 fail-closed（exit=$eD）——登记表配置坏时会静默空跑。" }
  elseif ($runsD -gt 1) { Fail "17ac(d)：锚失案变异体仍被实跑（runs=$runsD，应 ≤1 即仅控制组）——anchor-miss 只打了行字没截断流程，空变异的「绿」会被当有效证据（本断言由自托管 N3 变异实测逼出：首版只查消息+退出码，N3 删 continue 后 fall-through 到 SURVIVED 仍全绿）。" }
  elseif ($oD -match '\[MUT-SURVIVED\]') { Fail '17ac(d)：锚失案不应出现 [MUT-SURVIVED]（fall-through 症状）。' }
  elseif (Test-Path (Join-Path $dD 'guarded.txt.mutbak')) { Fail '17ac(d)：锚失案不应写 .mutbak（未变异何来备份）。' }
  else { Write-Host '  17ac(d) 锚失案 fail-closed + 变异体零实跑 OK' -ForegroundColor Green }

  # (d)② 锚须单物理行（R3 r3 #5）：内嵌换行的锚可整段多行删除，违「单句删除」契约——整表拒收、零实跑。
  $dD2 = & $mkAcCase 'd2' $acDetectStub
  $rpD2 = Join-Path $dD2 'reg.psd1'
  Set-Content $rpD2 "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor=`"GUARD-LINE-ALPHA`nline-three`"; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD') } ) }" -Encoding utf8
  $oD2 = & pwsh -NoProfile -File $mutatePath -Registry $rpD2 -Root $dD2 -RunCommand (& $mkAcTpl $dD2) 2>&1 | Out-String
  $eD2 = $LASTEXITCODE
  if ($eD2 -eq 0 -or $oD2 -notmatch 'must be one physical line') { Fail "17ac(d)②：内嵌换行的锚未被拒（exit=$eD2）——一枚「单句删除」实际删多行（R3 r3 #5）。" }
  elseif (Test-Path (Join-Path $dD2 'runs.log')) { Fail '17ac(d)②：多行锚案探针仍被执行（应零实跑）。' }
  else { Write-Host '  17ac(d)② 多行锚整表拒收 OK' -ForegroundColor Green }

  # (d)③ EOF 行可变异（R3 r3 #5）：锚在**无尾随换行的末行**时也须恰一命中、删除保持原 EOF 形态。
  $dD3 = & $mkAcCase 'd3' $acDetectStub
  [IO.File]::WriteAllText((Join-Path $dD3 'guarded.txt'), "line-one`r`nGUARD-LINE-ALPHA", [Text.UTF8Encoding]::new($false))
  $regD3 = & $mkAcReg $dD3 'GUARD-LINE-ALPHA' ''
  $shaD3 = (Get-FileHash (Join-Path $dD3 'guarded.txt') -Algorithm SHA256).Hash
  $oD3 = & pwsh -NoProfile -File $mutatePath -Registry $regD3 -Root $dD3 -RunCommand (& $mkAcTpl $dD3) 2>&1 | Out-String
  $eD3 = $LASTEXITCODE
  if ($eD3 -ne 0 -or $oD3 -notmatch '\[MUT-OK\] A1') { Fail "17ac(d)③：无尾随换行的末行锚未被行感知匹配（exit=$eD3）——合法末行守卫测不了（R3 r3 #5）。" }
  elseif ((Get-FileHash (Join-Path $dD3 'guarded.txt') -Algorithm SHA256).Hash -ne $shaD3) { Fail '17ac(d)③：EOF 案 guarded.txt 未按字节复原（EOF 形态被改写）。' }
  else { Write-Host '  17ac(d)③ EOF 行可变异 + 字节复原 OK' -ForegroundColor Green }

  # (e) 沿用：案(a) 同登记表重跑，缓存键未变 → [MUT-REUSE] · exit 0 · **零探针**（连控制组都不跑——全沿用批无实跑）。
  # runs.log 读取一律 Test-Path 守护（runner 若被变异到早期崩溃、日志根本没生成，闸须干净 Fail 并走到结论哨兵，
  # 不得让 Get-Content 异常把整闸打死在半途——自托管 N24 实测逼出）。
  $runsBefore = if (Test-Path (Join-Path $dA 'runs.log')) { @(Get-Content (Join-Path $dA 'runs.log')).Count } else { 0 }
  $oE = & pwsh -NoProfile -File $mutatePath -Registry $regA -Root $dA -RunCommand (& $mkAcTpl $dA) 2>&1 | Out-String
  $eE = $LASTEXITCODE
  $runsAfter = if (Test-Path (Join-Path $dA 'runs.log')) { @(Get-Content (Join-Path $dA 'runs.log')).Count } else { 0 }
  if ($eE -ne 0 -or $oE -notmatch '\[MUT-REUSE\] A1') { Fail "17ac(e)：未变树重跑没走 [MUT-REUSE] 沿用（exit=$eE）——增量重测（TD119 修向核心）失效。" }
  elseif ($runsAfter -ne $runsBefore) { Fail "17ac(e)：沿用案仍有探针实跑（runs $runsBefore -> $runsAfter）——沿用只是打了行字、没省下探针。" }
  else { Write-Host '  17ac(e) 沿用案零实跑 OK' -ForegroundColor Green }

  # (g) 缓存失配重测（R3 r1 #1）：①改枚定义 → 必实跑；②换 RunCommand 模板 → 必实跑。r3 起每个非沿用批
  #     多一次未变异控制组，runs.log 增量恒 +2。
  $regA2 = & $mkAcReg $dA 'GUARD-LINE-ALPHA' "; mustFindRegex=@('STUB-CAUGHT')"
  $runsG0 = if (Test-Path (Join-Path $dA 'runs.log')) { @(Get-Content (Join-Path $dA 'runs.log')).Count } else { 0 }
  $oG1 = & pwsh -NoProfile -File $mutatePath -Registry $regA2 -Root $dA -RunCommand (& $mkAcTpl $dA) 2>&1 | Out-String
  $eG1 = $LASTEXITCODE
  $runsG1 = if (Test-Path (Join-Path $dA 'runs.log')) { @(Get-Content (Join-Path $dA 'runs.log')).Count } else { 0 }
  $oG2 = & pwsh -NoProfile -File $mutatePath -Registry $regA2 -Root $dA -RunCommand ((& $mkAcTpl $dA) + ' extra-arg') 2>&1 | Out-String
  $eG2 = $LASTEXITCODE
  $runsG2 = if (Test-Path (Join-Path $dA 'runs.log')) { @(Get-Content (Join-Path $dA 'runs.log')).Count } else { 0 }
  if ($eG1 -ne 0 -or $oG1 -notmatch '\[MUT-OK\] A1' -or $runsG1 -ne ($runsG0 + 2)) { Fail "17ac(g)①：改枚定义后仍沿用旧 OK（exit=$eG1 runs $runsG0->$runsG1，期望 +2=控制组+变异体）——缓存键没把判据算进去（R3 r1 #1）。" }
  elseif ($eG2 -ne 0 -or $oG2 -notmatch '\[MUT-OK\] A1' -or $runsG2 -ne ($runsG1 + 2)) { Fail "17ac(g)②：换 RunCommand 模板后仍沿用旧 OK（exit=$eG2 runs $runsG1->$runsG2，期望 +2）——缓存键没把模板算进去（R3 r1 #1）。" }
  else { Write-Host '  17ac(g) 缓存失配重测（改判据/换模板 双向）OK' -ForegroundColor Green }

  # (g)③ 序列化碰撞回归（R3 r2 #1）：旧式「k=v 拼 '|'」下 A(mustFind=X + mustNotFind=zzz) 与
  #     B(mustFind='X|mustNotFind=zzz' 单条) 同键——长度前缀序列化下必不同键：跑完 A 再跑 B 必须**实跑**
  #     且判 BAD-EVIDENCE（B 的合成锚不在输出里），绝不 [MUT-REUSE] 白拿 A 的 OK。
  $dGc = & $mkAcCase 'gc' $acDetectStub
  $rpGc = Join-Path $dGc 'reg.psd1'
  Set-Content $rpGc "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD'); mustNotFind=@('zzz') } ) }" -Encoding utf8
  $oGc1 = & pwsh -NoProfile -File $mutatePath -Registry $rpGc -Root $dGc -RunCommand (& $mkAcTpl $dGc) 2>&1 | Out-String
  $eGc1 = $LASTEXITCODE
  Set-Content $rpGc "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD|mustNotFind=zzz') } ) }" -Encoding utf8
  $oGc2 = & pwsh -NoProfile -File $mutatePath -Registry $rpGc -Root $dGc -RunCommand (& $mkAcTpl $dGc) 2>&1 | Out-String
  $eGc2 = $LASTEXITCODE
  if ($eGc1 -ne 0 -or $oGc1 -notmatch '\[MUT-OK\] A1') { Fail "17ac(g)③前置：碰撞对 A 半应先 OK（exit=$eGc1）——夹具坏，本例 vacuous。" }
  elseif ($eGc2 -eq 0 -or $oGc2 -match '\[MUT-REUSE\]' -or $oGc2 -notmatch '\[MUT-BAD-EVIDENCE\] A1') { Fail "17ac(g)③：字段边界伪装的碰撞对 B 半沿用了 A 的 OK（exit=$eGc2）——序列化仍可被竖线/等号拼接碰撞（R3 r2 #1）。" }
  else { Write-Host '  17ac(g)③ 序列化碰撞对必不同键 OK' -ForegroundColor Green }

  # (h) -Only 选集校验（R3 r1 #5）：不存在的 id → [MUT-REG-INVALID] 点名 + 非零，绝不静默全跳变绿。
  $oH = & pwsh -NoProfile -File $mutatePath -Registry $regA2 -Root $dA -RunCommand (& $mkAcTpl $dA) -Only 'NOPE' 2>&1 | Out-String
  $eH = $LASTEXITCODE
  if ($eH -eq 0 -or $oH -notmatch '\[MUT-REG-INVALID\] -Only id not in registry: NOPE') { Fail "17ac(h)：未知 -Only id 未被点名拒绝（exit=$eH）——打错字会静默零选集、空批变绿。" }
  else { Write-Host '  17ac(h) -Only 选集校验 fail-closed OK' -ForegroundColor Green }

  # (i) 正向证据强制（R3 r1 #3）：无 mustFind/mustFindRegex 的枚 → [MUT-REG-INVALID]（裸非零不算证据，L167）。
  $dI = & $mkAcCase 'i' $acDetectStub
  $rpI = Join-Path $dI 'reg.psd1'
  Set-Content $rpI "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1' } ) }" -Encoding utf8
  $oI = & pwsh -NoProfile -File $mutatePath -Registry $rpI -Root $dI -RunCommand (& $mkAcTpl $dI) 2>&1 | Out-String
  $eI = $LASTEXITCODE
  if ($eI -eq 0 -or $oI -notmatch 'needs at least one positive evidence') { Fail "17ac(i)：零正向证据的枚未被拒（exit=$eI）——任意非零都会被判 OK。" }
  else { Write-Host '  17ac(i) 正向证据强制 OK' -ForegroundColor Green }

  # (j) ASCII 证据强制（L165⑤ 机检化）：证据锚含非 ASCII → [MUT-REG-INVALID]。
  $dJ = & $mkAcCase 'j' $acDetectStub
  $rpJ = Join-Path $dJ 'reg.psd1'
  Set-Content $rpJ "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('中文锚') } ) }" -Encoding utf8
  $oJ = & pwsh -NoProfile -File $mutatePath -Registry $rpJ -Root $dJ -RunCommand (& $mkAcTpl $dJ) 2>&1 | Out-String
  $eJ = $LASTEXITCODE
  if ($eJ -eq 0 -or $oJ -notmatch 'not printable-ASCII') { Fail "17ac(j)：非 ASCII 证据锚未被拒（exit=$eJ）——编码链一变即假红/假绿（L165⑤）。" }
  else { Write-Host '  17ac(j) ASCII 证据强制 OK' -ForegroundColor Green }

  # (j)② 正则须预检可编译（R3 r2 #2）：可打印但非法的 '[' 过了 ASCII 检查后若不预编译，会在探针后半程抛
  #     Regex.IsMatch 异常——无 REG-INVALID、无结果行、无 SUMMARY。须整表预编译、零实跑拒收。
  $dJ2 = & $mkAcCase 'j2' $acDetectStub
  $rpJ2 = Join-Path $dJ2 'reg.psd1'
  Set-Content $rpJ2 "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD'); mustFindRegex=@('[') } ) }" -Encoding utf8
  $oJ2 = & pwsh -NoProfile -File $mutatePath -Registry $rpJ2 -Root $dJ2 -RunCommand (& $mkAcTpl $dJ2) 2>&1 | Out-String
  $eJ2 = $LASTEXITCODE
  if ($eJ2 -eq 0 -or $oJ2 -notmatch 'does not compile') { Fail "17ac(j)②：非法正则未被预编译拒收（exit=$eJ2）——会在变异后半程抛异常、无哨兵无记账（R3 r2 #2）。" }
  elseif (Test-Path (Join-Path $dJ2 'runs.log')) { Fail '17ac(j)②：非法正则案探针仍被执行（应零实跑）。' }
  else { Write-Host '  17ac(j)② 非法正则预编译拒收 + 零实跑 OK' -ForegroundColor Green }

  # (k) gate 注入拒绝（R3 r1 #4）：gate 携 shell 元字符 → [MUT-REG-INVALID]（injection guard 点名）且**零执行
  #     副作用**。载荷用**本批专名**文件（t63pwn-<PID>.txt）：检出与清场都只认专名——预置的同名旁观文件零误伤
  #     （R3 r3 #7：不误删用户既有文件）。
  $dK = & $mkAcCase 'k' $acDetectStub
  $acPwnName = "t63pwn-$PID.txt"
  $decoyK = Join-Path $dK 'pwned.txt'
  Set-Content $decoyK 'pre-existing bystander file' -Encoding utf8
  $decoySha = (Get-FileHash $decoyK -Algorithm SHA256).Hash
  $rpK = Join-Path $dK 'reg.psd1'
  Set-Content $rpK "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1; New-Item $acPwnName'; mustFind=@('STUB-CAUGHT-MISSING-GUARD') } ) }" -Encoding utf8
  $oK = & pwsh -NoProfile -File $mutatePath -Registry $rpK -Root $dK -RunCommand (& $mkAcTpl $dK) 2>&1 | Out-String
  $eK = $LASTEXITCODE
  $pwned = @(Get-ChildItem $dK -Filter $acPwnName -Recurse -ErrorAction SilentlyContinue) + @(Get-ChildItem $RepoRoot -Filter $acPwnName -ErrorAction SilentlyContinue)
  # 无论判定如何都清掉**专名**载荷残留（守卫被变异摘除时——自托管 N6 探针——注入会真执行、在仓根落专名文件）；
  # 旁观 pwned.txt 绝不触碰。
  $pwned | Remove-Item -Force -ErrorAction SilentlyContinue
  if ($eK -eq 0 -or $oK -notmatch 'injection guard') { Fail "17ac(k)：gate 注入载荷未被字符集校验拒绝（exit=$eK）——登记表成了可执行命令面（R3 r1 #4）。" }
  elseif ($pwned.Count -gt 0) { Fail '17ac(k)：注入载荷产生了执行副作用（专名文件出现，已代为清除）——校验没先于执行。' }
  elseif (-not (Test-Path $decoyK) -or ((Get-FileHash $decoyK -Algorithm SHA256).Hash -ne $decoySha)) { Fail '17ac(k)：预置同名旁观文件被误伤（R3 r3 #7——清场只许动本批专名载荷）。' }
  else { Write-Host '  17ac(k) gate 注入拒绝 + 零副作用 + 旁观零误伤 OK' -ForegroundColor Green }

  # (l) target 越界拒绝（R3 r1 #4）：../ 穿越出 Root → [MUT-REG-INVALID]（escapes Root 点名）且界外文件零改动。
  $dL = & $mkAcCase 'l' $acDetectStub
  $escTarget = Join-Path $acRoot 'escape-target.txt'
  Set-Content $escTarget "OUTSIDE-LINE`r`nGUARD-LINE-ALPHA`r`nOUTSIDE-END" -Encoding utf8
  $escSha0 = (Get-FileHash $escTarget -Algorithm SHA256).Hash
  $rpL = Join-Path $dL 'reg.psd1'
  Set-Content $rpL "@{ mutations = @( @{ id='A1'; target='../escape-target.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD') } ) }" -Encoding utf8
  $oL = & pwsh -NoProfile -File $mutatePath -Registry $rpL -Root $dL -RunCommand (& $mkAcTpl $dL) 2>&1 | Out-String
  $eL = $LASTEXITCODE
  if ($eL -eq 0 -or $oL -notmatch 'target escapes Root') { Fail "17ac(l)：越界 target 未被圈禁拒绝（exit=$eL）——登记表能改到仓外/根外任意文件（R3 r1 #4）。" }
  elseif ((Get-FileHash $escTarget -Algorithm SHA256).Hash -ne $escSha0) { Fail '17ac(l)：界外文件被碰了——拒绝没先于写入。' }
  else { Write-Host '  17ac(l) target 越界拒绝 + 界外零改动 OK' -ForegroundColor Green }

  # (l)② 绝对路径即便落在 Root 内也拒（相对-only 契约，R3 r2 #3）。
  $dL2 = & $mkAcCase 'l2' $acDetectStub
  $rpL2 = Join-Path $dL2 'reg.psd1'
  $absT = (Join-Path $dL2 'guarded.txt').Replace("'", "''")
  Set-Content $rpL2 "@{ mutations = @( @{ id='A1'; target='$absT'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD') } ) }" -Encoding utf8
  $shaL2 = (Get-FileHash (Join-Path $dL2 'guarded.txt') -Algorithm SHA256).Hash
  $oL2 = & pwsh -NoProfile -File $mutatePath -Registry $rpL2 -Root $dL2 -RunCommand (& $mkAcTpl $dL2) 2>&1 | Out-String
  $eL2 = $LASTEXITCODE
  if ($eL2 -eq 0 -or $oL2 -notmatch 'must be Root-relative') { Fail "17ac(l)②：Root 内的绝对路径 target 未被拒（exit=$eL2）——相对-only 契约破（R3 r2 #3）。" }
  elseif ((Get-FileHash (Join-Path $dL2 'guarded.txt') -Algorithm SHA256).Hash -ne $shaL2) { Fail '17ac(l)②：绝对路径案 target 被碰了。' }
  else { Write-Host '  17ac(l)② 绝对路径拒绝 OK' -ForegroundColor Green }

  # (l)④ guarded 路径同受圈禁（R3 r2 #3）：越界 guarded 不再被静默丢出缓存键，而是整表拒收。
  $dL4 = & $mkAcCase 'l4' $acDetectStub
  $rpL4 = Join-Path $dL4 'reg.psd1'
  Set-Content $rpL4 "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD'); guarded=@('../l4-nope.txt') } ) }" -Encoding utf8
  $oL4 = & pwsh -NoProfile -File $mutatePath -Registry $rpL4 -Root $dL4 -RunCommand (& $mkAcTpl $dL4) 2>&1 | Out-String
  $eL4 = $LASTEXITCODE
  if ($eL4 -eq 0 -or $oL4 -notmatch 'guarded path invalid') { Fail "17ac(l)④：越界 guarded 未被拒（exit=$eL4）——被静默剔出缓存键 = 依赖面窄于声明面（R3 r2 #3）。" }
  else { Write-Host '  17ac(l)④ guarded 圈禁 OK' -ForegroundColor Green }

  # (l)⑤ -Results 别名拒（R3 r2 #3）：结果路径与 target 同一文件时，逐枚记账会覆写被测源（路径串判别腿）。
  $dL5 = & $mkAcCase 'l5' $acDetectStub
  $rpL5 = & $mkAcReg $dL5 'GUARD-LINE-ALPHA' ''
  $shaL5 = (Get-FileHash (Join-Path $dL5 'guarded.txt') -Algorithm SHA256).Hash
  $oL5 = & pwsh -NoProfile -File $mutatePath -Registry $rpL5 -Root $dL5 -RunCommand (& $mkAcTpl $dL5) -Results (Join-Path $dL5 'guarded.txt') 2>&1 | Out-String
  $eL5 = $LASTEXITCODE
  if ($eL5 -eq 0 -or $oL5 -notmatch 'aliases a target or the registry') { Fail "17ac(l)⑤：-Results 与 target 同路径未被拒（exit=$eL5）——记账会覆写被测源（R3 r2 #3）。" }
  elseif ((Get-FileHash (Join-Path $dL5 'guarded.txt') -Algorithm SHA256).Hash -ne $shaL5) { Fail '17ac(l)⑤：别名案 target 被写了。' }
  else { Write-Host '  17ac(l)⑤ -Results 别名拒绝 OK' -ForegroundColor Green }

  # (l)⑦ -Results 硬链接别名拒（R3 r3 #2）：硬链接绕过路径串比对——按 NTFS 文件 ID 判同一文件。
  $dL7 = & $mkAcCase 'l7' $acDetectStub
  $l7Fs = [bool](Get-Command fsutil -ErrorAction SilentlyContinue)
  if ($l7Fs) { & fsutil file queryfileid (Join-Path $dL7 'guarded.txt') *> $null; if ($LASTEXITCODE -ne 0) { $l7Fs = $false } }
  $l7Link = Join-Path $dL7 'res-link.tsv'
  $l7Made = $true
  try { New-Item -ItemType HardLink -Path $l7Link -Target (Join-Path $dL7 'guarded.txt') -ErrorAction Stop | Out-Null } catch { $l7Made = $false }
  if ($l7Made -and $l7Fs) {
    $rpL7 = & $mkAcReg $dL7 'GUARD-LINE-ALPHA' ''
    $shaL7 = (Get-FileHash (Join-Path $dL7 'guarded.txt') -Algorithm SHA256).Hash
    $oL7 = & pwsh -NoProfile -File $mutatePath -Registry $rpL7 -Root $dL7 -RunCommand (& $mkAcTpl $dL7) -Results $l7Link 2>&1 | Out-String
    $eL7 = $LASTEXITCODE
    if ($eL7 -eq 0 -or $oL7 -notmatch 'aliases a target or the registry') { Fail "17ac(l)⑦：硬链接 -Results 未被文件 ID 判别拒绝（exit=$eL7）——路径串比对被硬链接绕过、记账覆写被测源（R3 r3 #2）。" }
    elseif ((Get-FileHash (Join-Path $dL7 'guarded.txt') -Algorithm SHA256).Hash -ne $shaL7) { Fail '17ac(l)⑦：硬链接案 target 被写了。' }
    else { Write-Host '  17ac(l)⑦ -Results 硬链接身份拒绝 OK' -ForegroundColor Green }
  } else { Write-Host '  17ac(l)⑦ 跳过（本机硬链接或 fsutil 文件 ID 不可用）' -ForegroundColor DarkGray }

  # (m) 登记表形状族：重复 id / psd1 解析失败 / 非哈希表条目 / 空或非法 id（R3 r1 + r3 #4）——一律 REG-INVALID 零实跑。
  $dM = & $mkAcCase 'm' $acDetectStub
  $rpM = Join-Path $dM 'reg.psd1'
  Set-Content $rpM "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('X') }, @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('Y') } ) }" -Encoding utf8
  $oM = & pwsh -NoProfile -File $mutatePath -Registry $rpM -Root $dM -RunCommand (& $mkAcTpl $dM) 2>&1 | Out-String
  $eM = $LASTEXITCODE
  if ($eM -eq 0 -or $oM -notmatch 'duplicate id') { Fail "17ac(m)：重复 id 未被拒（exit=$eM）——结果主键互踩、沿用判据糊掉。" }
  else { Write-Host '  17ac(m) 重复 id 拒绝 OK' -ForegroundColor Green }
  Set-Content $rpM "@{ mutations = @( @{ id='A1'; target=" -Encoding utf8
  $oM2 = & pwsh -NoProfile -File $mutatePath -Registry $rpM -Root $dM -RunCommand (& $mkAcTpl $dM) 2>&1 | Out-String
  $eM2 = $LASTEXITCODE
  if ($eM2 -eq 0 -or $oM2 -notmatch 'registry parse failed') { Fail "17ac(m)②：psd1 解析失败未被归一为 [MUT-REG-INVALID]（exit=$eM2）——裸异常无哨兵（R3 r3 #4）。" }
  else { Write-Host '  17ac(m)② 解析失败归一 REG-INVALID OK' -ForegroundColor Green }
  Set-Content $rpM "@{ mutations = @( 'not-a-hashtable' ) }" -Encoding utf8
  $oM3 = & pwsh -NoProfile -File $mutatePath -Registry $rpM -Root $dM -RunCommand (& $mkAcTpl $dM) 2>&1 | Out-String
  $eM3 = $LASTEXITCODE
  if ($eM3 -eq 0 -or $oM3 -notmatch 'not a hashtable') { Fail "17ac(m)③：非哈希表条目未被拒（exit=$eM3）——ContainsKey 会在 StrictMode 下裸崩（R3 r3 #4）。" }
  else { Write-Host '  17ac(m)③ 非哈希表条目拒绝 OK' -ForegroundColor Green }
  Set-Content $rpM "@{ mutations = @( @{ id=''; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('X') } ) }" -Encoding utf8
  $oM4 = & pwsh -NoProfile -File $mutatePath -Registry $rpM -Root $dM -RunCommand (& $mkAcTpl $dM) 2>&1 | Out-String
  $eM4 = $LASTEXITCODE
  if ($eM4 -eq 0 -or $oM4 -notmatch 'id missing/empty/illegal') { Fail "17ac(m)④：空 id 未被拒（exit=$eM4）——结果行主键为空、TSV 记账糊掉（R3 r3 #4）。" }
  else { Write-Host '  17ac(m)④ 空 id 拒绝 OK' -ForegroundColor Green }

  # (o) 结果 schema 两面（R3 r2 #4 + r3 #6）：①仓内 tracked TSV **必须在场**且列头等于 runner 现行 schema
  #     （缺失即红——Test-Path 假不许滑进成功分支）；②喂旧版头须触发 [MUT-RESULTS-RESET] 重建、旧 OK 行绝不被沿用。
  $acHeaderWant = "id`tverdict`texit`tseconds`tevidence`tcacheKey`tat"
  $acTrackedTsv = Join-Path $RepoRoot 'specs/mutations/T63-TD119-MUTATION-RUNNER-results.tsv'
  if (-not (Test-Path $acTrackedTsv)) { Fail '17ac(o)①：仓内 tracked 结果 TSV 缺失——自托管证据的交付物没了（R3 r3 #6：缺失不得滑进「头一致」成功分支）。' }
  elseif ((Get-Content $acTrackedTsv -TotalCount 1) -ne $acHeaderWant) { Fail "17ac(o)①：仓内 tracked 结果 TSV 列头 != runner 现行 schema——交付物自带 schema 漂移（R3 r2 #4）。实得：$(Get-Content $acTrackedTsv -TotalCount 1)" }
  else { Write-Host '  17ac(o)① tracked TSV 在场且列头一致 OK' -ForegroundColor Green }
  $dO = & $mkAcCase 'o' $acDetectStub
  $rpO = & $mkAcReg $dO 'GUARD-LINE-ALPHA' ''
  Set-Content (Join-Path $dO 'reg-results.tsv') "id`tverdict`texit`tseconds`tguardedSha`tat`nA1`tOK`t1`t9.9`tDEADBEEF`t2026-01-01" -Encoding utf8
  $oO = & pwsh -NoProfile -File $mutatePath -Registry $rpO -Root $dO -RunCommand (& $mkAcTpl $dO) 2>&1 | Out-String
  $eO = $LASTEXITCODE
  if ($oO -notmatch '\[MUT-RESULTS-RESET\]') { Fail '17ac(o)②：旧版列头未触发 [MUT-RESULTS-RESET]——旧行会被拿错列当缓存键（R3 r2 #4）。' }
  elseif ($eO -ne 0 -or $oO -notmatch '\[MUT-OK\] A1') { Fail "17ac(o)②：重建后应正常实跑收 OK（exit=$eO；旧 OK 行绝不可被沿用）。" }
  elseif ((Get-Content (Join-Path $dO 'reg-results.tsv') -TotalCount 1) -ne $acHeaderWant) { Fail '17ac(o)②：重建后的列头仍不是现行 schema。' }
  else { Write-Host '  17ac(o)② 旧版列头触发 RESET 重建 OK' -ForegroundColor Green }

  # (p) 未变异控制组红即拒（R3 r3 #1）：探针本来就红时，任何「非零+证据」都归因不到变异——[MUT-PRISTINE-RED]
  #     fail-closed 零变异（无 .mutbak、target 零改动、绝不产出 MUT-OK）。
  $dP = & $mkAcCase 'p' $acRedStub
  $rpP = Join-Path $dP 'reg.psd1'
  Set-Content $rpP "@{ mutations = @( @{ id='A1'; target='guarded.txt'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-ALWAYS-RED') } ) }" -Encoding utf8
  $shaP = (Get-FileHash (Join-Path $dP 'guarded.txt') -Algorithm SHA256).Hash
  $oP = & pwsh -NoProfile -File $mutatePath -Registry $rpP -Root $dP -RunCommand (& $mkAcTpl $dP) 2>&1 | Out-String
  $eP = $LASTEXITCODE
  if ($oP -notmatch '\[MUT-PRISTINE-RED\]') { Fail "17ac(p)：本来就红的探针没触发 [MUT-PRISTINE-RED]（exit=$eP）——红闸上跑批会把「本来就红」记成 [MUT-OK] 假证据（R3 r3 #1）。" }
  elseif ($oP -match '\[MUT-OK\]') { Fail '17ac(p)：控制组红却仍产出了 [MUT-OK]——归因失效。' }
  elseif ((Get-FileHash (Join-Path $dP 'guarded.txt') -Algorithm SHA256).Hash -ne $shaP) { Fail '17ac(p)：控制组红案 target 被变异过（应零变异）。' }
  elseif (Test-Path (Join-Path $dP 'guarded.txt.mutbak')) { Fail '17ac(p)：控制组红案不应留 .mutbak。' }
  else { Write-Host '  17ac(p) 未变异控制组红即拒 OK' -ForegroundColor Green }

  # (t) -Root/探针错树守卫（T98-MUT-ROOT-GUARD/TD144/L235）：-Root 只改 target/guarded 的解析根，Invoke-Probe
  #     仍 Push-Location $RepoRoot（由脚本自身位置派生）。故「-Root 指向别处 且 -RunCommand 留默认」= 变异一棵树、
  #     测量另一棵树，实测产出 ok=0 survived=5（同一登记表从被测树自己那份跑则 ok=5 survived=0）。控制组抓不到——
  #     它在同一棵错树里跑、必绿。三段断言：①错组合被 [MUT-ROOT-PROBE-MISMATCH] 拒且零变异；②带 -RunCommand 的
  #     同一错组合**不得**被拒（本闸 (a)-(s) 全部案例正是这么驱动的，误拒会连坐整段）；③守卫是**接线过的**，
  #     不只是定义了函数——故 ① 走真入口而非直调谓词。
  $dT = & $mkAcCase 't' $acDetectStub
  $rpT = & $mkAcReg $dT 'GUARD-LINE-ALPHA' ''
  $shaT = (Get-FileHash (Join-Path $dT 'guarded.txt') -Algorithm SHA256).Hash
  $oT1 = & pwsh -NoProfile -File $mutatePath -Registry $rpT -Root $dT 2>&1 | Out-String
  $eT1 = $LASTEXITCODE
  if ($eT1 -eq 0 -or $oT1 -notmatch '\[MUT-ROOT-PROBE-MISMATCH\]') {
    Fail "17ac(t)①：-Root 指向别树 + 默认 -RunCommand 未被 [MUT-ROOT-PROBE-MISMATCH] 拒（exit=$eT1）——该组合会变异一棵树、测量另一棵，整批假 [MUT-SURVIVED]，而未变异控制组在同一错树里必绿、抓不到（TD144/L235）。"
  }
  elseif ((Get-FileHash (Join-Path $dT 'guarded.txt') -Algorithm SHA256).Hash -ne $shaT) { Fail '17ac(t)①：错树守卫触发后 target 仍被变异过（应零变异）。' }
  elseif (Test-Path (Join-Path $dT 'guarded.txt.mutbak')) { Fail '17ac(t)①：错树守卫触发后不应留 .mutbak。' }
  else {
    $oT2 = & pwsh -NoProfile -File $mutatePath -Registry $rpT -Root $dT -RunCommand (& $mkAcTpl $dT) 2>&1 | Out-String
    $eT2 = $LASTEXITCODE
    if ($oT2 -match '\[MUT-ROOT-PROBE-MISMATCH\]') {
      Fail "17ac(t)②：显式 -RunCommand 的同一 -Root 组合被误拒（exit=$eT2）——调用方已自担探针解析责任，且本闸 (a)-(s) 全案例皆如此驱动，误拒即连坐整段。"
    }
    elseif ($eT2 -ne 0 -or $oT2 -notmatch '\[MUT-OK\] A1') { Fail "17ac(t)②：显式 -RunCommand 下应照常实跑收 OK（exit=$eT2）。" }
    else { Write-Host '  17ac(t) -Root/探针错树守卫 OK（错组合零变异拒收 · 显式 -RunCommand 不误拒 · 守卫接在真入口上）' -ForegroundColor Green }
  }

  # (n) 基线脏守卫（R3 r1 #2；需 git，缺则跳过）：git 追踪的 target 有未提交改动 → [MUT-BASELINE-DIRTY] 拒；
  #     -AllowDirty 显式放行后正常跑批。
  if (Get-Command git -ErrorAction SilentlyContinue) {
    $dN = & $mkAcCase 'n' $acDetectStub
    & git -C $dN init -q
    & git -C $dN -c user.email='t@l' -c user.name='t' add -A 2>$null
    & git -C $dN -c user.email='t@l' -c user.name='t' commit -q -m base *> $null
    Add-Content (Join-Path $dN 'guarded.txt') 'tampered-uncommitted-line'
    $regN = & $mkAcReg $dN 'GUARD-LINE-ALPHA' ''
    $oN1 = & pwsh -NoProfile -File $mutatePath -Registry $regN -Root $dN -RunCommand (& $mkAcTpl $dN) 2>&1 | Out-String
    $eN1 = $LASTEXITCODE
    $oN2 = & pwsh -NoProfile -File $mutatePath -Registry $regN -Root $dN -RunCommand (& $mkAcTpl $dN) -AllowDirty 2>&1 | Out-String
    $eN2 = $LASTEXITCODE
    if ($eN1 -eq 0 -or $oN1 -notmatch '\[MUT-BASELINE-DIRTY\]') { Fail "17ac(n)①：脏 target 未被 [MUT-BASELINE-DIRTY] 拒（exit=$eN1）——死批的变异态会被默认当基线（R3 r1 #2/L196）。" }
    elseif ($eN2 -ne 0 -or $oN2 -notmatch '\[MUT-OK\] A1') { Fail "17ac(n)②：-AllowDirty 显式放行后应正常跑批（exit=$eN2）。" }
    else { Write-Host '  17ac(n) 基线脏守卫（默认拒 + -AllowDirty 放行）OK' -ForegroundColor Green }
  } else { Write-Host '  17ac(n) 跳过（无 git，脏守卫的 git 判定面不可测；其余案不受影响）' -ForegroundColor DarkGray }

  # (q) TD135 orphan-row drop: a results row whose id is no longer in the registry must be dropped at load
  #     with a [MUT-ORPHAN-DROPPED] notice (the TSV stays a pure projection of the current registry), and
  #     legitimate rows keep riding [MUT-REUSE]. Seeded live: N16's row survived T69's registry prune.
  $dQ = & $mkAcCase 'q' $acDetectStub
  $regQ = & $mkAcReg $dQ 'GUARD-LINE-ALPHA' ''
  & pwsh -NoProfile -File $mutatePath -Registry $regQ -Root $dQ -RunCommand (& $mkAcTpl $dQ) *> $null
  $tsvQ = Join-Path $dQ 'reg-results.tsv'
  Add-Content $tsvQ ("ZOMBIE`tOK`t1`t9.9`tfound:STUB-CAUGHT-MISSING-GUARD`t$('A' * 64)`t2026-01-01T00:00:00") -Encoding utf8
  $runsQ0 = @(Get-Content (Join-Path $dQ 'runs.log') -ErrorAction SilentlyContinue).Count
  $oQ = & pwsh -NoProfile -File $mutatePath -Registry $regQ -Root $dQ -RunCommand (& $mkAcTpl $dQ) 2>&1 | Out-String
  $eQ = $LASTEXITCODE
  $runsQ1 = @(Get-Content (Join-Path $dQ 'runs.log') -ErrorAction SilentlyContinue).Count
  $tsvQRows = @(Get-Content $tsvQ | Select-Object -Skip 1)
  if ($oQ -notmatch '\[MUT-ORPHAN-DROPPED\] ZOMBIE') { Fail "17ac(q)：orphan row (id not in registry) not dropped with [MUT-ORPHAN-DROPPED] — the tracked TSV silently claims evidence for a mutation that does not exist (TD135, N16 live case). exit=$eQ" }
  elseif (@($tsvQRows | Where-Object { $_.StartsWith("ZOMBIE`t") }).Count -ne 0) { Fail '17ac(q)：[MUT-ORPHAN-DROPPED] printed but the ZOMBIE row is still in the rewritten TSV — the notice lied.' }
  elseif ($eQ -ne 0 -or $oQ -notmatch '\[MUT-REUSE\] A1' -or $runsQ1 -ne $runsQ0) { Fail "17ac(q)：orphan drop broke the legitimate row's reuse (exit=$eQ, runs $runsQ0->$runsQ1, expect unchanged) — dropping stale rows must not force re-runs of valid ones." }
  elseif (@($tsvQRows | Where-Object { $_.StartsWith("A1`t") }).Count -ne 1) { Fail '17ac(q)：A1 row missing/duplicated after the orphan-drop rewrite.' }
  else { Write-Host '  17ac(q) orphan row dropped with notice + valid row still reused OK (TD135)' -ForegroundColor Green }

  # (r) TD133(3) unknown-key rejection: a typo'd channel key (mustFinds) must hit [MUT-REG-INVALID] naming
  #     the key, with zero probes and zero mutations — silently ignoring it weakens declared evidence.
  $dR = & $mkAcCase 'r' $acDetectStub
  $regR = & $mkAcReg $dR 'GUARD-LINE-ALPHA' "; mustFinds=@('TYPO-CHANNEL')"
  $oR = & pwsh -NoProfile -File $mutatePath -Registry $regR -Root $dR -RunCommand (& $mkAcTpl $dR) 2>&1 | Out-String
  $eR = $LASTEXITCODE
  if ($eR -eq 0 -or $oR -notmatch 'unknown registry key: mustFinds') { Fail "17ac(r)：registry entry with unknown key mustFinds not rejected by name (exit=$eR) — a typo'd evidence channel is silently ignored (TD133 item 3)." }
  elseif (Test-Path (Join-Path $dR 'runs.log')) { Fail '17ac(r)：probes ran despite [MUT-REG-INVALID] — validation must be zero-execution.' }
  elseif (Test-Path (Join-Path $dR 'guarded.txt.mutbak')) { Fail '17ac(r)：a .mutbak was written despite registry rejection (zero-mutation contract).' }
  else { Write-Host '  17ac(r) unknown registry key rejected by name, zero execution OK (TD133 item 3)' -ForegroundColor Green }

  # (s) TD133(5) malformed-row discard: a row with a non-SHA256 cacheKey must be dropped with
  #     [MUT-ROW-MALFORMED] and NEVER reused — the mutation re-runs for real (runs.log +2: control+mutant).
  $dS = & $mkAcCase 's' $acDetectStub
  $regS = & $mkAcReg $dS 'GUARD-LINE-ALPHA' ''
  & pwsh -NoProfile -File $mutatePath -Registry $regS -Root $dS -RunCommand (& $mkAcTpl $dS) *> $null
  $tsvS = Join-Path $dS 'reg-results.tsv'
  Set-Content $tsvS ("id`tverdict`texit`tseconds`tevidence`tcacheKey`tat`nA1`tOK`t1`t1.0`tfound:STUB-CAUGHT-MISSING-GUARD`tDEADBEEF`t2026-01-01T00:00:00") -Encoding utf8
  $runsS0 = @(Get-Content (Join-Path $dS 'runs.log') -ErrorAction SilentlyContinue).Count
  $oS = & pwsh -NoProfile -File $mutatePath -Registry $regS -Root $dS -RunCommand (& $mkAcTpl $dS) 2>&1 | Out-String
  $eS = $LASTEXITCODE
  $runsS1 = @(Get-Content (Join-Path $dS 'runs.log') -ErrorAction SilentlyContinue).Count
  if ($oS -notmatch '\[MUT-ROW-MALFORMED\]') { Fail "17ac(s)：malformed row (cacheKey not 64-hex) not flagged [MUT-ROW-MALFORMED] (exit=$eS) — a corrupted row can be reused as evidence (TD133 item 5)." }
  elseif ($oS -match '\[MUT-REUSE\]') { Fail '17ac(s)：malformed row was still REUSED — discard must force a real re-run.' }
  elseif ($eS -ne 0 -or $oS -notmatch '\[MUT-OK\] A1' -or $runsS1 -ne ($runsS0 + 2)) { Fail "17ac(s)：after discarding the malformed row the mutation must re-run for real and land OK (exit=$eS, runs $runsS0->$runsS1, expect +2)." }
  else { Write-Host '  17ac(s) malformed row discarded, never reused, real re-run OK (TD133 item 5)' -ForegroundColor Green }

  # (f) 陈旧 .mutbak：上一批被硬杀在「植入后、还原前」→ 当前字节 == 备份套用本表变异的结果 ⇒ 验明身份后还原
  #     （L196 自愈）再正常跑批。
  $dF = & $mkAcCase 'f' $acDetectStub
  $regF = & $mkAcReg $dF 'GUARD-LINE-ALPHA' ''
  $fGuard = Join-Path $dF 'guarded.txt'
  $pristineBytes = [IO.File]::ReadAllBytes($fGuard)
  [IO.File]::WriteAllBytes("$fGuard.mutbak", $pristineBytes)
  Set-Content $fGuard "line-one`r`nline-three" -Encoding utf8   # == 备份删掉锚行的结果（可识别的死批遗留态）
  $oF = & pwsh -NoProfile -File $mutatePath -Registry $regF -Root $dF -RunCommand (& $mkAcTpl $dF) 2>&1 | Out-String
  $eF = $LASTEXITCODE
  $tailF = ($oF -split "`n" | Select-Object -Last 4) -join ' | '
  if ($oF -notmatch '\[MUT-STALE-BAK-RESTORED\]') { Fail "17ac(f)：可识别的死批遗留态未被自愈还原（L196）——跨会话变异态会被当基线。输出尾：$tailF" }
  elseif ($eF -ne 0) { Fail "17ac(f)：自愈后整批应正常收绿（exit=$eF）。" }
  elseif ([Convert]::ToBase64String([IO.File]::ReadAllBytes($fGuard)) -ne [Convert]::ToBase64String($pristineBytes)) { Fail '17ac(f)：自愈+探针毕 guarded.txt 未回到原始字节。' }
  else { Write-Host '  17ac(f) 陈旧 .mutbak 验明身份还原案 OK' -ForegroundColor Green }

  # (f)② 分歧态双保留（R3 r3 #3）：当前字节既不等于备份、也不是备份套用本表任何变异的结果（= 可能是用户的新
  #     编辑）→ [MUT-BAK-DIVERGENT] fail-closed（exit 3）、target 与 .mutbak 双双原样保留——陈旧备份不许覆
  #     掉新编辑。
  $dF2 = & $mkAcCase 'f2' $acDetectStub
  $regF2 = & $mkAcReg $dF2 'GUARD-LINE-ALPHA' ''
  $f2Guard = Join-Path $dF2 'guarded.txt'
  [IO.File]::WriteAllBytes("$f2Guard.mutbak", [IO.File]::ReadAllBytes($f2Guard))
  Set-Content $f2Guard "line-one`r`nUSER-EDITED-CONTENT`r`nline-three" -Encoding utf8
  $f2EditSha = (Get-FileHash $f2Guard -Algorithm SHA256).Hash
  $oF2 = & pwsh -NoProfile -File $mutatePath -Registry $regF2 -Root $dF2 -RunCommand (& $mkAcTpl $dF2) 2>&1 | Out-String
  $eF2 = $LASTEXITCODE
  if ($oF2 -notmatch '\[MUT-BAK-DIVERGENT\]' -or $eF2 -ne 3) { Fail "17ac(f)②：不可识别的分歧态未被 [MUT-BAK-DIVERGENT]+exit 3 拦下（exit=$eF2）——陈旧备份会静默覆掉用户新编辑（R3 r3 #3）。" }
  elseif ((Get-FileHash $f2Guard -Algorithm SHA256).Hash -ne $f2EditSha) { Fail '17ac(f)②：分歧案 target（用户编辑）被改写了——应双文件原样保留。' }
  elseif (-not (Test-Path "$f2Guard.mutbak")) { Fail '17ac(f)②：分歧案 .mutbak 被删了——应双文件原样保留供人工核对。' }
  else { Write-Host '  17ac(f)② 分歧态双保留 fail-closed OK' -ForegroundColor Green }

  # (v) T269/TD271 owner stamp: a stale .mutbak may only be self-healed when NOBODY OWNS IT. Same
  #     recognisable killed-batch state as (f), plus a .mutbak.owner naming a pid that is STILL ALIVE
  #     => [MUT-BAK-OWNED] fail-closed (exit 4) with target, backup and stamp all left exactly as
  #     found. The identity test (f) proves cannot tell these apart: a peer's IN-FLIGHT state is
  #     byte-identical to a dead batch's residue whenever two registries share a (target, anchor)
  #     pair, and 5 such pairs exist in the live corpus. The second half is the half that keeps this
  #     honest - kill the owner and the SAME state must still self-heal, so the guard is a prior
  #     question and never a replacement for L196 recovery.
  $dT = & $mkAcCase 't' $acDetectStub
  $regT = & $mkAcReg $dT 'GUARD-LINE-ALPHA' ''
  $tGuard = Join-Path $dT 'guarded.txt'
  $tPristineBytes = [IO.File]::ReadAllBytes($tGuard)
  [IO.File]::WriteAllBytes("$tGuard.mutbak", $tPristineBytes)
  Set-Content $tGuard "line-one`r`nline-three" -Encoding utf8   # == backup with the anchor line deleted
  $tPlantedB64 = [Convert]::ToBase64String([IO.File]::ReadAllBytes($tGuard))
  # Platform-neutral spawn: the hidden-window parameter Start-Process takes is Windows-only, and using
  # it here reddened the ubuntu seed-b shard on master (T272). CreateNoWindow is honoured on Windows,
  # ignored elsewhere, and Process.Start returns only once the process exists - no sleep stands in.
  $tPsi = [Diagnostics.ProcessStartInfo]::new()
  $tPsi.FileName = 'pwsh'
  $tPsi.Arguments = '-NoProfile -Command "Start-Sleep -Seconds 60"'
  $tPsi.UseShellExecute = $false
  $tPsi.CreateNoWindow = $true
  $tOwner = [Diagnostics.Process]::Start($tPsi)
  if (-not $tOwner -or $tOwner.HasExited) { Fail '17ac(v)：the fixture owner process did not start, so the live-owner half cannot be judged.' }
  # Built by the PRODUCTION writer, never by hand: a hand-built stamp encodes the field order as if it
  # were contract, observes nothing about Get-MutateBakStampText, and goes red on any format change while
  # proving nothing about it. Driven through -AsLibrary in a child so the library's own StrictMode and
  # $ErrorActionPreference cannot leak into this gate's scope.
  $tStamp = (& pwsh -NoProfile -Command ". '$mutatePath' -AsLibrary; Get-MutateBakStampText -OwnerPid $($tOwner.Id) -Registry 'specs/my mutations/peer.psd1' -StartedUtc '2026-01-01T00:00:00Z'" | Out-String).Trim()
  if ($tStamp -notmatch "^pid=$($tOwner.Id)\b") { Fail "17ac(v)：the production stamp writer did not emit a line naming the owner pid - got '$tStamp'." }
  Set-Content "$tGuard.mutbak.owner" $tStamp -Encoding utf8 -NoNewline
  $oT = & pwsh -NoProfile -File $mutatePath -Registry $regT -Root $dT -RunCommand (& $mkAcTpl $dT) 2>&1 | Out-String
  $eT = $LASTEXITCODE
  $tailT = ($oT -split "`n" | Select-Object -Last 4) -join ' | '
  if ($oT -notmatch '\[MUT-BAK-OWNED\]' -or $eT -ne 4) { Fail "17ac(v)：a .mutbak owned by a LIVE pid was not refused with [MUT-BAK-OWNED]+exit 4 (exit=$eT) — a second runner will unplant a peer's in-flight mutation and its probe then banks a false survivor (TD271). Tail: $tailT" }
  elseif ([Convert]::ToBase64String([IO.File]::ReadAllBytes($tGuard)) -ne $tPlantedB64) { Fail '17ac(v)：the refusal still rewrote the target — an owned target must be left exactly as found.' }
  elseif (-not (Test-Path "$tGuard.mutbak")) { Fail '17ac(v)：the refusal deleted a .mutbak it does not own — that is the peer''s only copy of the pristine bytes.' }
  elseif (-not (Test-Path "$tGuard.mutbak.owner")) { Fail '17ac(v)：the refusal deleted the owner stamp — the next run would then read the state as unowned.' }
  elseif ($oT -notmatch "pid=$($tOwner.Id)") { Fail "17ac(v)：the refusal did not NAME the owning pid — a refusal you cannot act on is a dead end (expected pid=$($tOwner.Id))." }
  else { Write-Host '  17ac(v) live-owner .mutbak refused, all three files untouched, owner named OK' -ForegroundColor Green }
  # Observe the exit rather than sleep past it: a fixed delay is a race on a slow runner, and the whole
  # point of the second half is that the owner is genuinely GONE before the same state is re-judged.
  try { $tOwner.Kill() } catch { }
  if (-not $tOwner.WaitForExit(15000)) { Fail '17ac(v)：the fixture owner did not exit within 15s, so the dead-owner half would judge a still-live owner.' }

  # (v)② the SAME state with the owner now DEAD must fall through to the identity test and self-heal,
  #     so this card adds a prior question rather than weakening the L196 recovery it sits in front of.
  $oT2 = & pwsh -NoProfile -File $mutatePath -Registry $regT -Root $dT -RunCommand (& $mkAcTpl $dT) 2>&1 | Out-String
  $eT2 = $LASTEXITCODE
  $tailT2 = ($oT2 -split "`n" | Select-Object -Last 4) -join ' | '
  if ($oT2 -notmatch '\[MUT-STALE-BAK-RESTORED\]') { Fail "17ac(v)②：with the owner dead the killed-batch state was NOT self-healed (exit=$eT2) — the owner guard must be a prior question, never a replacement for L196 recovery. Tail: $tailT2" }
  elseif ($eT2 -ne 0) { Fail "17ac(v)②：after self-healing the batch should finish green (exit=$eT2)." }
  elseif ([Convert]::ToBase64String([IO.File]::ReadAllBytes($tGuard)) -ne [Convert]::ToBase64String($tPristineBytes)) { Fail '17ac(v)②：guarded.txt did not return to its original bytes after the self-heal.' }
  elseif (Test-Path "$tGuard.mutbak.owner") { Fail '17ac(v)②：the owner stamp outlived the backup it names — a stale stamp would block the next run forever.' }
  else { Write-Host '  17ac(v)② dead-owner state still self-heals, stamp removed with the backup OK' -ForegroundColor Green }

  # (u) afterAnchor 单行删除（T209/TD205）：afterAnchor 用于锚不唯一时消歧，其契约是**只删锚行、保留前行原有换行**
  #   （mutate.ps1 该分支注释原文）。实现曾丢掉那个换行，把锚行的**下一行**粘到前行上——两行变更、登记表只声明一行，
  #   L165 单句删除契约被破。此前 `afterAnchor` 在本文件出现 0 次（无任何闸覆盖），故该违约得以长期存活。
  #   两形态各一例：注释前行（粘接后被 # 吞掉整行，响亮）与代码前行（粘接后仍能解析，静默）。
  #   stub 在探针期把**变异态**复制出来，断言据此判「恰少一行、且后一行仍独立成行」——这是唯一能分辨
  #   「删一行」与「删一行再粘一行」的观测点：两者都让 stub 变红、runner 都记 [MUT-OK]。
  $acFail = $false
  $acAfterStub = @'
param([string]$Gate)
Copy-Item (Join-Path $PSScriptRoot 'guarded.txt') (Join-Path $PSScriptRoot 'mutated.txt') -Force
$g = Get-Content (Join-Path $PSScriptRoot 'guarded.txt') -Raw
if ($g -notmatch 'GUARD-LINE-ALPHA') { Write-Output 'STUB-CAUGHT-MISSING-GUARD'; exit 1 }
Write-Output 'STUB-GUARD-PRESENT'; exit 0
'@
  foreach ($acU in @(
      @{ tag = 'u1'; keep = '# KEEP-COMMENT'; label = 'comment afterAnchor' }
      @{ tag = 'u2'; keep = 'code = 1';       label = 'code-line afterAnchor' })) {
    $dU = & $mkAcCase $acU.tag $acAfterStub
    # Written as an ARRAY, not a joined string: Set-Content terminates a single string with the platform EOL
    # while leaving embedded [char]10 separators alone, so the file would carry LF separators and a CRLF
    # terminator - and Get-MutatedVariant picks $eolV by asking whether the text CONTAINS CRLF, so it would
    # look for 'keep<CRLF>anchor' in a file separated by LF and miss the anchor entirely. Measured: that is
    # exactly how this fixture failed on its first run. An array gives one consistent EOL throughout.
    Set-Content (Join-Path $dU 'guarded.txt') @($acU.keep, 'GUARD-LINE-ALPHA', 'NEXT-LINE-BETA') -Encoding utf8
    $regU = Join-Path $dU 'reg.psd1'
    Set-Content $regU ("@{ mutations = @( @{ id='A1'; target='guarded.txt'; afterAnchor='$($acU.keep)'; anchor='GUARD-LINE-ALPHA'; gate='g1'; mustFind=@('STUB-CAUGHT-MISSING-GUARD') } ) }") -Encoding utf8
    $oU = & pwsh -NoProfile -File $mutatePath -Registry $regU -Root $dU -RunCommand (& $mkAcTpl $dU) 2>&1 | Out-String
    $eU = $LASTEXITCODE
    $mutU = Join-Path $dU 'mutated.txt'
    if ($eU -ne 0 -or $oU -notmatch '\[MUT-OK\] A1') { Fail "种子缺陷 17ac(u/$($acU.tag))[U-MUTOK] afterAnchor 枚未记 [MUT-OK]（exit=$eU）——变异未被 stub 抓到。"; $acFail = $true }
    elseif (-not (Test-Path $mutU)) { Fail "种子缺陷 17ac(u/$($acU.tag))[U-CAPTURE] stub 未截获变异态（mutated.txt 未生成），断言无从判读。"; $acFail = $true }
    elseif (@(Get-Content $mutU).Count -ne 2) { Fail "种子缺陷 17ac(u/$($acU.tag))[U-LINES] $($acU.label) 变异后剩 $(@(Get-Content $mutU).Count) 行，应为 2——afterAnchor 删了不止锚行（TD205 的粘行）。"; $acFail = $true }
    elseif (@(Get-Content $mutU) -notcontains 'NEXT-LINE-BETA') { Fail "种子缺陷 17ac(u/$($acU.tag))[U-GLUE] 锚的下一行未独立成行——它被粘到前行尾部（$($acU.label) 形态）。"; $acFail = $true }
    elseif (@(Get-Content $mutU) -notcontains $acU.keep) { Fail "种子缺陷 17ac(u/$($acU.tag))[U-KEEP] 前行未原样保留。"; $acFail = $true }
  }
  if (-not $acFail) { Write-Host '  17ac(u) afterAnchor deletes exactly the anchor line OK (comment and code-line previous-line shapes, mutated bytes captured by the stub: 2 lines remain, the following line still stands alone, the kept line is verbatim - TD205)' -ForegroundColor Green }

  # (w) T294/TD279: a probe that exits 0 AFTER announcing it SKIPPED meta sub-gates cannot say which of
  #   two things happened - the guard is dead, or the assertion never ran. Since T279 moved 22 sub-gates
  #   behind -IncludeMeta that is not hypothetical: T274 banked five rows on 14i whose default probe never
  #   executes 14i. The runner keeps the SURVIVED verdict and its non-zero exit exactly as before and adds
  #   the [MUT-META-PROBE-MISSING] reading, in the console AND in the stored row, so the corpus records
  #   which reading it is. FIVE arms, and the four negatives are what make this a reading rather than a
  #   blanket: w2 is the byte-identity control (green with no skip line records what it has always
  #   recorded, column for column); w3/w4 hold OK and BAD-EVIDENCE untouched even when sites WERE
  #   skipped - both require a non-zero probe, so the assertion demonstrably ran and a mutation the probe
  #   caught is caught regardless of what else the run passed over; and w5 is the PROSE control, which is
  #   why the match is anchored to a whole line - the arms below name [META-SKIP] mid-sentence themselves.
  #   Arm ids are ASCII attribution tokens ([W-*]) because the registry's anchors must be pure ASCII
  #   (L165(5)) and a kill has to name WHICH assertion fired (L265).
  $acMetaSkipGreenStub = @'
param([string]$Gate)
Write-Output '  [META-SKIP] 14o'
Write-Output 'STUB-ALWAYS-GREEN'; exit 0
'@
  $acMetaSkipDetectStub = @'
param([string]$Gate)
$g = Get-Content (Join-Path $PSScriptRoot 'guarded.txt') -Raw
Write-Output '  [META-SKIP] 14o'
if ($g -notmatch 'GUARD-LINE-ALPHA') { Write-Output 'STUB-CAUGHT-MISSING-GUARD'; exit 1 }
Write-Output 'STUB-GUARD-PRESENT'; exit 0
'@
  $acMetaSkipWrongStub = @'
param([string]$Gate)
$g = Get-Content (Join-Path $PSScriptRoot 'guarded.txt') -Raw
Write-Output '  [META-SKIP] 14o'
if ($g -notmatch 'GUARD-LINE-ALPHA') { Write-Output 'STUB-WRONG-TEXT'; exit 1 }
Write-Output 'STUB-GUARD-PRESENT'; exit 0
'@
  $dW1 = & $mkAcCase 'w1' $acMetaSkipGreenStub
  $regW1 = & $mkAcReg $dW1 'GUARD-LINE-ALPHA' ''
  $oW1 = & pwsh -NoProfile -File $mutatePath -Registry $regW1 -Root $dW1 -RunCommand (& $mkAcTpl $dW1) 2>&1 | Out-String
  $eW1 = $LASTEXITCODE
  $tailW1 = ($oW1 -split "`n" | Select-Object -Last 6) -join ' | '
  $rowW1 = @((Get-Content (Join-Path $dW1 'reg-results.tsv') | Select-Object -Skip 1 | Select-Object -First 1) -split "`t")
  if ($oW1 -notmatch '\[MUT-SURVIVED\] A1' -or $eW1 -eq 0) { Fail "17ac(w1)[W-SURVIVED] a probe that skipped meta sites and stayed green must STILL record SURVIVED and still fail the batch (exit=$eW1). This card changes what the operator is told, never whether the batch fails. Tail: $tailW1" }
  elseif ($oW1 -notmatch '\[MUT-META-PROBE-MISSING\] A1') { Fail "17ac(w1)[W-SENTINEL] the batch recorded a bare survivor for a probe that ANNOUNCED it skipped meta sub-gates, so the corpus banks 'the guard is dead or untested' - the strongest negative verdict it holds - against an assertion that never ran (T294/TD279). Tail: $tailW1" }
  elseif ($oW1 -notmatch '14o') { Fail "17ac(w1)[W-NAMES] the refusal did not NAME the skipped site, so it cannot be acted on: the operator has to re-run the probe by hand to learn which site went dark. Tail: $tailW1" }
  elseif ($oW1 -notmatch '-IncludeMeta') { Fail "17ac(w1)[W-FIX] the refusal named no fix, and the one that resolves it is adding -IncludeMeta to this registry's probe (specs/mutations/README.md, L337). Tail: $tailW1" }
  elseif (@($rowW1).Count -ne 7) { Fail "17ac(w1)[W-ROW-SHAPE] the stored row has $(@($rowW1).Count) columns, not the seven the results schema contracts (id verdict exit seconds evidence cacheKey at) - this card adds no column and the assertions below cannot read a row of another shape." }
  elseif ($rowW1[1] -ne 'SURVIVED') { Fail "17ac(w1)[W-ROW-VERDICT] the stored verdict reads '$($rowW1[1])', not SURVIVED. The known-verdict list is the evidence corpus's contract and this card adds no value to it - it qualifies the note, never the verdict." }
  elseif ($rowW1[4] -ne '[MUT-META-PROBE-MISSING] meta-skipped=14o; MISS-find:STUB-CAUGHT-MISSING-GUARD') { Fail "17ac(w1)[W-ROW-EVIDENCE] the stored row kept a bare survival note (got '$($rowW1[4])'), so a reader of the TSV alone still cannot tell the two readings apart - and the TSV, not the console, is what 14p and every later card read." }
  else { Write-Host '  17ac(w1) a green probe that announced [META-SKIP] records SURVIVED plus the [MUT-META-PROBE-MISSING] reading, named site and fix, in the console and in the stored row OK' -ForegroundColor Green }

  # (w2) the negative control, asserted as its own arm rather than inferred from w1 passing: a green probe
  #   that skipped nothing must record exactly what this runner has always recorded, column for column.
  $dW2 = & $mkAcCase 'w2' $acGreenStub
  $regW2 = & $mkAcReg $dW2 'GUARD-LINE-ALPHA' ''
  $oW2 = & pwsh -NoProfile -File $mutatePath -Registry $regW2 -Root $dW2 -RunCommand (& $mkAcTpl $dW2) 2>&1 | Out-String
  $eW2 = $LASTEXITCODE
  $tailW2 = ($oW2 -split "`n" | Select-Object -Last 6) -join ' | '
  $rowW2 = @((Get-Content (Join-Path $dW2 'reg-results.tsv') | Select-Object -Skip 1 | Select-Object -First 1) -split "`t")
  if ($oW2 -notmatch '\[MUT-SURVIVED\] A1' -or $eW2 -eq 0) { Fail "17ac(w2)[W-CONTROL] the control stopped recording a plain survivor (exit=$eW2), so the pair below judges nothing. Tail: $tailW2" }
  elseif ($oW2 -match '\[MUT-META-PROBE-MISSING\]') { Fail "17ac(w2)[W-FALSE-POSITIVE] a probe that skipped NOTHING was reported as having skipped meta sites. The check must read the probe's own announcement, never fire on every green probe - the loose forms that produce this are matching '[META-' (which [META-RAN] also carries) or matching '-IncludeMeta' (which the [META-ORPHAN] sentence carries). Tail: $tailW2" }
  elseif (@($rowW2).Count -ne 7) { Fail "17ac(w2)[W-CONTROL-SHAPE] the control's stored row has $(@($rowW2).Count) columns, not seven." }
  elseif ($rowW2[1] -ne 'SURVIVED' -or $rowW2[4] -ne 'MISS-find:STUB-CAUGHT-MISSING-GUARD') { Fail "17ac(w2)[W-ROW-PLAIN] the row for a plain survivor is no longer byte-identical to what this runner has always written (verdict '$($rowW2[1])', evidence '$($rowW2[4])')." }
  else { Write-Host '  17ac(w2) a green probe with no [META-SKIP] still records a plain SURVIVED, verdict and evidence columns byte-identical OK' -ForegroundColor Green }

  # (w3/w4) the other two verdicts, with meta sites skipped in both: the reading is confined to the green
  #   branch, so neither OK nor BAD-EVIDENCE may change.
  $acWFail = $false
  foreach ($acW in @(
      @{ tag = 'w3'; stub = $acMetaSkipDetectStub; want = 'MUT-OK';           zero = $true;  label = 'a mutation the probe CAUGHT' }
      @{ tag = 'w4'; stub = $acMetaSkipWrongStub;  want = 'MUT-BAD-EVIDENCE'; zero = $false; label = 'a mutation that went red for the WRONG reason' })) {
    $dW = & $mkAcCase $acW.tag $acW.stub
    $regW = & $mkAcReg $dW 'GUARD-LINE-ALPHA' ''
    $oW = & pwsh -NoProfile -File $mutatePath -Registry $regW -Root $dW -RunCommand (& $mkAcTpl $dW) 2>&1 | Out-String
    $eW = $LASTEXITCODE
    $tailW = ($oW -split "`n" | Select-Object -Last 6) -join ' | '
    if ($oW -notmatch "\[$($acW.want)\] A1" -or (($eW -eq 0) -ne [bool]$acW.zero)) { Fail "17ac($($acW.tag))[W-VERDICT] $($acW.label) was not judged $($acW.want) with the batch exit this runner has always given (exit=$eW). Tail: $tailW"; $acWFail = $true }
    elseif ($oW -match '\[MUT-META-PROBE-MISSING\]') { Fail "17ac($($acW.tag))[W-NONGREEN] the meta reading fired on a NON-ZERO probe. Both OK and BAD-EVIDENCE require a red probe, so the assertion demonstrably ran; firing here would red the registries whose evidence a skipped meta site cannot affect. Tail: $tailW"; $acWFail = $true }
  }
  if (-not $acWFail) { Write-Host '  17ac(w3/w4) OK and BAD-EVIDENCE untouched when the probe skipped meta sites - a mutation the probe caught is caught regardless of what else was skipped OK' -ForegroundColor Green }

  # (w5) the control that says WHY the match is anchored to a whole physical line, and it is not
  #   hypothetical: the arms above name [META-SKIP] mid-sentence in their own success messages, so a real
  #   `-Only 17ac -IncludeMeta` run - exactly the probe template a registry targeting 17ac must use - puts
  #   the literal in a green probe's output with nothing skipped. A substring test read those sentences as
  #   announcements and the id extraction took the FOLLOWING WORD as a site name ('records', 'still').
  #   Measured on this card's own R3 round 1. The fixture feeds that shape verbatim and demands the plain
  #   survivor back, byte for byte, with no invented site in the row.
  $acMetaProseStub = @'
param([string]$Gate)
Write-Output '  17ac(w1) a green probe that announced [META-SKIP] records SURVIVED plus the reading'
Write-Output '  17ac(w2) a green probe with no [META-SKIP] still records a plain SURVIVED'
Write-Output 'STUB-ALWAYS-GREEN'; exit 0
'@
  $dW5 = & $mkAcCase 'w5' $acMetaProseStub
  $regW5 = & $mkAcReg $dW5 'GUARD-LINE-ALPHA' ''
  $oW5 = & pwsh -NoProfile -File $mutatePath -Registry $regW5 -Root $dW5 -RunCommand (& $mkAcTpl $dW5) 2>&1 | Out-String
  $eW5 = $LASTEXITCODE
  $tailW5 = ($oW5 -split "`n" | Select-Object -Last 6) -join ' | '
  $rowW5 = @((Get-Content (Join-Path $dW5 'reg-results.tsv') | Select-Object -Skip 1 | Select-Object -First 1) -split "`t")
  if ($oW5 -notmatch '\[MUT-SURVIVED\] A1' -or $eW5 -eq 0) { Fail "17ac(w5)[W-PROSE-CONTROL] the prose control stopped recording a plain survivor (exit=$eW5), so the arms below judge nothing. Tail: $tailW5" }
  elseif ($oW5 -match '\[MUT-META-PROBE-MISSING\]') { Fail "17ac(w5)[W-PROSE] a probe that only MENTIONED [META-SKIP] inside a sentence was read as announcing a skipped site. The literal must be matched as a whole physical line - this file's own 17ac success messages carry it in prose, so an unanchored test fires on every green run of the very probe template a 17ac registry uses. Tail: $tailW5" }
  elseif (@($rowW5).Count -ne 7 -or $rowW5[1] -ne 'SURVIVED' -or $rowW5[4] -ne 'MISS-find:STUB-CAUGHT-MISSING-GUARD') { Fail "17ac(w5)[W-PROSE-ROW] the stored row for the prose control is not the plain survivor this runner has always written (verdict '$($rowW5[1])', evidence '$($rowW5[4])') - an unanchored matcher writes an INVENTED site id here, taken from the word that follows the literal in the sentence." }
  else { Write-Host '  17ac(w5) [META-SKIP] inside prose is not an announcement - plain SURVIVED, no invented site id in the row OK' -ForegroundColor Green }

  Write-Host '  17ac mutate.ps1 runner seeded-defects OK (cases a-w with sub-variants: detection / survivor / bad-evidence / anchor-miss + single-line anchor + EOF line / reuse / identity-verified restore + divergent double-keep / cache-key mismatch incl. serialization collision / -Only selection / positive evidence + regex precompile / ASCII / injection rejection with zero collateral / confinement rejection (traversal, absolute path, guarded, results alias by path and file identity) / registry shape (dup id, parse fail, non-hashtable, empty id) / dirty baseline / results schema / pristine control group / orphan-row drop with notice (TD135) / unknown-key rejection by name (TD133 item 3) / malformed-row discard, never reused (TD133 item 5) / afterAnchor single-line deletion in both previous-line shapes (TD205) / a survivor produced by a probe that announced it SKIPPED meta sub-gates is named as such in the console and in the stored row, with green-no-skip, OK, BAD-EVIDENCE and the prose shape these arms themselves print each held unchanged as its own arm (T294/TD279); stub gate via -RunCommand, fully hermetic)' -ForegroundColor Green
} finally {
  Remove-Item -Recurse -Force $acRoot -ErrorAction SilentlyContinue
}
}
}

# T279 (this card's own R3 round 1, #5): these three values are SHARED by 17ad and 17ad' and are
# therefore computed OUTSIDE both meta guards. Left inside 17ad's guard, a run in which 17ad did not
# report while 17ad' did - which is exactly the state a deleted tagging call produces - reached 17ad'
# with them unset and crashed under StrictMode BEFORE the reconciliation could name the site that went
# dark. A guard may decide whether a body runs; it must never be the only thing that defines a value
# a later body reads (L249: a mutation must red through an assertion, never through a crash).
$rrGit = [bool](Get-Command git -ErrorAction SilentlyContinue)
$rrExpected = @($SeedRegionSites | Where-Object { (Test-SeedRegionSelected $_.Region) -and ($rrGit -or -not $_.NeedsGit) } | ForEach-Object { $_.Id })
# Every site this run selected lives inside the block gate 17 skips for want of git: there is nothing to
# reconcile, and saying so is not the same as passing - the two sites that DO run without git are still
# judged on any token that selects them, so this branch narrows to the case where the set is genuinely empty.
$rrSkipped = ((-not $rrGit) -and $rrExpected.Count -eq 0)
$metaRun = Test-MetaSelected "17ad"
if ($metaRun) {
# 17ad. (T194 / upstream #272): execution evidence for this gate's region guards. Everything else in gate 17
#   observes the SELECTOR - the run's label, its [SELFTEST-ONLY-PASS] sentinel and the CI shard union all
#   prove a TOKEN was requested, never that the guarded body answered. Redirect one guard to another legally
#   routed region and the shard stays green over code that never ran; gate 14k rejects only a literal naming
#   NO routed region, and its own failure text states the consequence it cannot detect. So each body files a
#   receipt about itself and this reconciles the filed set against the sites the selector activates. Keyed
#   per SITE: 'post' has two legitimate bodies, so issue #272's prescribed duplicate-by-region rule would red
#   correct code (L270 - a prescribed fix is a hypothesis, and this one died against the tree).
if ($rrSkipped) { Write-Host '  17ad skipped (git absent - this gate skipped every guarded body the selected region(s) own, the same degradation it announces above).' -ForegroundColor DarkGray }
else {
$rrFindings = @(Get-ScaffoldRegionReceiptIssue -Expected $rrExpected -Observed @($script:SeedRegionReceipts))
if ($rrFindings.Count) {
  foreach ($rrF in $rrFindings) { Fail "17ad T194: $rrF Re-check with the same -Only token this run used." }
}
# This OK line deliberately does NOT carry the [REGION-RECEIPT] sentinel, and adding it back would be a
# regression rather than a tidy-up: the card's dod_command greps the run for `REGION-RECEIPT.*pre` and
# ignores the child exit code, so any earlier matching line turns the DoD into a test of "did some arm pass"
# instead of "did this sub-gate pass" (L283). The sentinel is RESERVED to the final line below - reserved
# structurally, not by careful prose: every failure path here reports under [SEED-REGION-EVIDENCE], because
# `TAG.*pre` also matches ordinary English after TAG (present, prevent, interpreted).
elseif (-not $fail) { Write-Host "  17ad region execution evidence reconciled OK ($($rrExpected.Count) selected site(s), every one filed from inside its own guarded body)" -ForegroundColor Green }
}
}

$metaRun = Test-MetaSelected "17ad'"
if ($metaRun) {
# 17ad'. (T194, same stance as 8.2g'/8.2h'/TD140/ADR 0011): the assertion above can only ever feed the core a
#   run that is correct by construction - on a green run the filed set EQUALS the selected set - so it proves
#   the core accepts agreement and can never prove it REJECTS anything. A core returning an empty finding list
#   unconditionally would pass 17ad forever. The declared shapes are the missing half, and the find-nothing
#   control re-runs the same shapes through exactly that core and must disagree at least once.
$rrExamples = @(Test-ScaffoldRegionReceiptExamples)
if ($rrExamples.Count) { $rrExamples | ForEach-Object { Fail "17ad' T194: $_" } }
elseif (@(Test-ScaffoldRegionReceiptExamples -Variant 'accept-any-run').Count -lt 1) {
  Fail "17ad' T194 (anti-vacuous): feeding the SAME shapes through the 'accept-any-run' core - one that finds nothing, ever - produced zero disagreements, so the examples assert nothing about execution evidence and 17ad, which only ever reads a run that agrees with itself, would remain the only assertion (TD140/ADR 0011)."
}
elseif (-not $fail) { Write-Host "  17ad' [REGION-RECEIPT] declared shapes hold and the filed set matched the selected set OK (sites: $(if ($rrSkipped) { 'none, git absent' } else { $rrExpected -join ', ' }) - missing / unexpected / redirected / nothing-selected all reported by the declared shapes, two sites of one region are not a duplicate, and the find-nothing control disagrees)" -ForegroundColor Green }
}

Exit-Gate
}

Step '结论'
# T279 (ADR 0016 item 3, amended): the meta reconciliation, the T194 receipt rule one level up. Probe FIRST,
# for the reason 14i/14k/14m state about theirs - a core that found nothing, ever, would pass the live half
# forever, because on a green run the filed set EQUALS the declared one and agreement is all it can prove.
# The seeded shapes below are the missing half: one declared site that never reported, one site reporting
# outside the registry, and one that reported on both faces at once. What is reconciled is the set every
# Test-MetaSelected call filed against the set this run could reach, so both directions are covered.
$metaProbe = @(Get-MetaReconcileIssue -Declared @('probe-a', 'probe-b') -Ran @('probe-a') -Skipped @('probe-c'))
$metaProbeDouble = @(Get-MetaReconcileIssue -Declared @('probe-a') -Ran @('probe-a') -Skipped @('probe-a'))
if ($metaProbe.Count -lt 2 -or $metaProbeDouble.Count -lt 1) {
  Fail "[META-ORPHAN] probe: the reconciliation core did not report its seeded shapes (missing + unexpected gave $($metaProbe.Count) of 2, double-reported gave $($metaProbeDouble.Count) of 1), so its silence about this run proves nothing. Fix Get-MetaReconcileIssue, never the probe."
}
# The reporting half, probed the same way: a builder that dropped the names would leave the live failure
# saying only that something is wrong, on the one line a reader has to act from.
# CAST, deliberately: with a null left-hand side PowerShell treats -notmatch as a COLLECTION filter and
# yields an empty result rather than $true, so an unguarded comparison reads a function that returned
# nothing as agreement. Mutation M5 measured exactly that - the probe stayed green over a deleted return.
$metaLineProbe = [string](Get-MetaOrphanLine -Orphans @('probe-a') -Findings @('seeded finding'))
$metaLineProbeEmpty = [string](Get-MetaOrphanLine -Orphans @() -Findings @('seeded finding'))
if ($metaLineProbe -notmatch 'META-ORPHAN' -or $metaLineProbe -notmatch 'probe-a' -or $metaLineProbe -notmatch 'seeded finding' -or $metaLineProbeEmpty -notmatch 'count-mismatch') {
  Fail "[META-ORPHAN] probe: the orphan line did not carry what it was given (got '$metaLineProbe' and '$metaLineProbeEmpty'), so a real reconciliation failure would report a site nobody can name. Fix Get-MetaOrphanLine, never the probe."
}
# The registry itself, judged before its verdict is trusted (the reason 14i/14k/14m give about their probes).
foreach ($metaRegF in @(Get-MetaRegistryIssue $MetaSubGates)) { Fail "[META-ORPHAN] registry: $metaRegF" }
# The wiring half, which no -Only run can reach on its own: every registered site is held against the
# wrapper that answers for it, by id, over this file's text - so a rename, a stray wrapper or a duplicate
# reds on EVERY face rather than only on a run that happens to enter that gate (R3 round 2 #1).
foreach ($metaWireF in @(Get-MetaWiringIssue -Path (Join-Path $RepoRoot 'scripts/selftest.ps1') -Registry $MetaSubGates)) { Fail "[META-ORPHAN] wiring: $metaWireF" }
foreach ($metaFaceF in @(Get-MetaFaceIssue -Path (Join-Path $RepoRoot 'scripts/selftest.ps1'))) { Fail "[META-ORPHAN] face: $metaFaceF" }
$metaDeclared = @(Get-MetaDeclaredSite)
$metaReported = @(@($script:MetaRan) + @($script:MetaSkipped))
$metaFindings = @(Get-MetaReconcileIssue -Declared $metaDeclared -Ran @($script:MetaRan) -Skipped @($script:MetaSkipped))
Write-Host ("[META-SUMMARY] declared={0} ran={1} skipped={2}" -f $metaDeclared.Count, @($script:MetaRan).Count, @($script:MetaSkipped).Count) -ForegroundColor DarkGray
if ($metaFindings.Count) {
  $metaOrphan = @(@($metaDeclared | Where-Object { $_ -notin $metaReported }) + @($metaReported | Where-Object { $_ -notin $metaDeclared }) | Select-Object -Unique)
  Fail (Get-MetaOrphanLine -Orphans $metaOrphan -Findings $metaFindings)
  # Name the GATE, not the site id: the summary line below turns what it is given into a re-check command,
  # and a site id is not a legal -Only token. An orphan whose id is not in the registry names no gate, and
  # is reported by the finding text alone rather than by inventing one.
  $script:FailedGates += @($MetaSubGates | Where-Object { $_.Id -in $metaOrphan } | ForEach-Object { $_.Gate } | Select-Object -Unique | Where-Object { $_ -notin $script:FailedGates })
}
$totalSec = [math]::Round($script:OnlyTotalSw.Elapsed.TotalSeconds, 1)
Write-Host ("[GATE-TIME-TOTAL] {0}s" -f $totalSec) -ForegroundColor DarkGray
# T176：一行说清「哪一闸红了」。CI 把这一行渲染进 job summary，十个矩阵作业于是在 run 页上各自点名自己的红闸，
# 不必逐个打开日志。它先于下面的结论面打印，故滤过跑与全量跑都拿得到（滤过跑的验收语义不因此改变）。
Write-Host (Get-ScaffoldGateResultSummary -FailedIds $script:FailedGates -Ran $script:GateTimes.Count -Wall $totalSec) -ForegroundColor $(if ($script:FailedGates.Count -gt 0) { 'Red' } else { 'DarkGray' })
if ($TaskIdActive) {
  # T274: the TIERED acceptance face. Tier S ran the whole suite, so it concludes with exactly what the
  # no-arg run prints - `selftest: PASS` - and a card cannot buy a cheaper proof by naming itself. Tiers 1
  # and 0 conclude through the tier sentinel ALONE and structurally cannot print that line, the same
  # separation -Only has had since T62: what a run proved is read off its own sentinel, never inferred.
  if ($fail) {
    if ($TierId -eq 'S') { Write-Host 'selftest: FAIL' -ForegroundColor Red }
    Write-Host "[SELFTEST-TIER-FAIL] task=$TaskId tier=$TierId gates=$TierGateList" -ForegroundColor Red
    exit 1
  }
  if ($TierId -eq 'S') { Write-Host 'selftest: PASS' -ForegroundColor Green }
  else { Write-Host "本次为按卡分级验收（tier=$TierId）：合并闸仍是 ci.yml；Tier S 的卡照旧付全量跑（ADR 0016）。" -ForegroundColor DarkYellow }
  Write-Host "[SELFTEST-TIER-PASS] task=$TaskId tier=$TierId gates=$TierGateList" -ForegroundColor Green
  exit 0
}
if ($OnlyActive) {
  # 滤过跑结论独立成面：绝不打印 `selftest: PASS`/`selftest: FAIL`——任何 grep 全量结论的消费者
  # （CI 日志 / 变异分类器 / 人在 ship 日志上）都不可能把滤过跑误当全量验收（T62；退出码语义不变）。
  $onlyList = $OnlyTokens -join ','
  Write-Host "滤过跑（-Only $onlyList）单独非验收：Tier S 卡的验收面 = 全 17 闸覆盖（本地无参全量跑，或 CI 分片并集全绿——T64/T65）；按卡分级的验收面是 -TaskId <卡 id>（ADR 0016）。" -ForegroundColor DarkYellow
  if ($fail) { Write-Host "[SELFTEST-ONLY-FAIL] gates=$onlyList" -ForegroundColor Red; exit 1 }
  Write-Host "[SELFTEST-ONLY-PASS] gates=$onlyList" -ForegroundColor Green
  exit 0
}
if ($fail) { Write-Host 'selftest: FAIL' -ForegroundColor Red; exit 1 }
Write-Host 'selftest: PASS' -ForegroundColor Green
exit 0
